/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2019_SEED = {"dse/writing/part-b/2019/Q2":[{"front":"opening the door","meaning":"敞開大門","examples":[{"en":"Hong Kong should focus on opening the door without leaving locals outside.","zh":"香港應專注於敞開大門，同時不把本地人排除在外。"},{"en":"Opening the door means welcoming people, ideas, or opportunities from outside.","zh":"敞開大門意思是歡迎外來的人、想法或機會。"},{"en":"A city opens the door to talent when it allows skilled workers to live and work there.","zh":"當一個城市容許有技能的工作者居住和工作時，就是向人才敞開大門。"},{"en":"Opening the door can strengthen an economy if local people also benefit.","zh":"如果本地人也受益，敞開大門可以強化經濟。"},{"en":"Opening the door should mean inclusion, not replacement.","zh":"敞開大門應該代表包容，而不是取代。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"without leaving locals outside","meaning":"不把本地人排除在外","examples":[{"en":"The city should welcome talent without leaving locals outside.","zh":"這個城市應歡迎人才，同時不把本地人排除在外。"},{"en":"Without leaving locals outside means including local people while welcoming outsiders.","zh":"不把本地人排除在外意思是在歡迎外來者時也包括本地人。"},{"en":"A company can hire overseas experts without leaving locals outside if it also trains local staff.","zh":"如果公司同時培訓本地員工，它就可以聘請海外專家而不把本地人排除在外。"},{"en":"Talent policy becomes unfair when locals feel excluded from opportunities.","zh":"當本地人覺得被排除在機會之外，人才政策就會變得不公平。"},{"en":"Welcoming newcomers works best without leaving locals outside.","zh":"歡迎新來者時，不把本地人排除在外，效果最好。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"gone are the days when","meaning":"……的日子已經過去","examples":[{"en":"Gone are the days when a city could prosper by relying only on local talent.","zh":"一個城市只靠本地人才就能繁榮的日子已經過去。"},{"en":"Gone are the days when means that an old situation no longer exists.","zh":"……的日子已經過去，意思是舊有情況已不再存在。"},{"en":"Gone are the days when students could succeed by memorising facts only.","zh":"學生只靠背誦事實就能成功的日子已經過去。"},{"en":"This phrase is useful when showing that the world has changed.","zh":"這個短語適合用來顯示世界已經改變。"},{"en":"Gone are the days when Hong Kong could ignore global competition.","zh":"香港可以忽視全球競爭的日子已經過去。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"prosper by relying on","meaning":"靠……而繁榮","examples":[{"en":"A city can no longer prosper by relying only on talent born within its borders.","zh":"一個城市不能再只靠在本地出生的人才而繁榮。"},{"en":"To prosper by relying on something means to become successful because of that support.","zh":"靠某事而繁榮，意思是因該支持而變得成功。"},{"en":"A business may prosper by relying on loyal customers and good service.","zh":"企業可能靠忠實顧客和良好服務而繁榮。"},{"en":"A city may fail to prosper by relying on one small talent pool only.","zh":"如果城市只靠一個小人才庫，可能難以繁榮。"},{"en":"Hong Kong needs wider connections if it wants to prosper in a global economy.","zh":"如果香港想在全球經濟中繁榮，就需要更廣闊的連繫。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"talent born within its borders","meaning":"在本地出生的人才","examples":[{"en":"A city cannot rely only on talent born within its borders.","zh":"一個城市不能只依賴在本地出生的人才。"},{"en":"Talent born within its borders means skilled people who were born inside that place.","zh":"在本地出生的人才，是指在該地方出生的有技能人才。"},{"en":"Local graduates are part of the talent born within Hong Kong’s borders.","zh":"本地畢業生是在香港本地出生的人才的一部分。"},{"en":"Relying only on talent born within its borders may limit a city’s development.","zh":"只依賴在本地出生的人才，可能限制城市發展。"},{"en":"A strong city develops local talent while also learning from outside talent.","zh":"強大的城市會培育本地人才，同時向外來人才學習。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"within its borders","meaning":"在其境內","examples":[{"en":"A city needs more than talent born within its borders.","zh":"一個城市需要的不只是其境內出生的人才。"},{"en":"Within its borders means inside a country, city, or region.","zh":"在其境內意思是在一個國家、城市或地區之內。"},{"en":"A government is responsible for people living within its borders.","zh":"政府要對其境內生活的人負責。"},{"en":"Companies may search beyond Hong Kong because not all needed skills exist within its borders.","zh":"公司可能到香港以外尋找人才，因為所需技能不一定都在其境內存在。"},{"en":"A global city connects people within its borders with people beyond them.","zh":"全球城市會把其境內的人和境外的人連繫起來。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"in the past","meaning":"在過去","examples":[{"en":"In the past, Hong Kong firms might have hired mainly from the local community.","zh":"在過去，香港公司可能主要從本地社群聘請員工。"},{"en":"In the past means during an earlier time, not now.","zh":"在過去意思是在較早的時間，而不是現在。"},{"en":"In the past, many students found jobs through family or school networks.","zh":"在過去，許多學生透過家庭或學校網絡找工作。"},{"en":"This phrase helps compare old habits with present changes.","zh":"這個短語幫助比較舊習慣和現在的轉變。"},{"en":"In the past, local hiring may have been enough, but today competition is global.","zh":"在過去，本地招聘可能已足夠，但今天競爭是全球性的。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"hire mainly from","meaning":"主要從……聘請","examples":[{"en":"Hong Kong firms might once have hired mainly from the local community.","zh":"香港公司曾經可能主要從本地社群聘請員工。"},{"en":"To hire mainly from a group means to choose most workers from that group.","zh":"主要從某群體聘請，意思是大部分員工都來自該群體。"},{"en":"A school may hire mainly from local graduates because they understand the community.","zh":"學校可能主要從本地畢業生中聘請員工，因為他們了解社區。"},{"en":"Companies hire mainly from one source when wider recruitment is unnecessary.","zh":"當較廣泛招聘沒有必要時，公司會主要從一個來源聘請。"},{"en":"Today, many firms cannot hire mainly from one place if they need specialised skills.","zh":"今天，如果公司需要專門技能，就不能總是主要從一個地方聘請。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"the local community","meaning":"本地社群","examples":[{"en":"Companies used to hire mainly from the local community.","zh":"公司過去主要從本地社群聘請員工。"},{"en":"The local community means the people who live, study, or work in a particular area.","zh":"本地社群是指在某地區居住、學習或工作的人。"},{"en":"A shop supports the local community when it hires nearby residents.","zh":"商店聘請附近居民時，就是支持本地社群。"},{"en":"Hiring from the local community can build trust and shared responsibility.","zh":"從本地社群聘請可以建立信任和共同責任。"},{"en":"Talent policy should help the local community, not push it aside.","zh":"人才政策應幫助本地社群，而不是把它擠到一旁。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"search the world for","meaning":"在全球尋找","examples":[{"en":"Companies now search the world for skilled workers.","zh":"公司現在在全球尋找有技能的工作者。"},{"en":"To search the world for something means to look internationally for it.","zh":"在全球尋找某物，意思是在國際範圍內尋找它。"},{"en":"Universities may search the world for top researchers.","zh":"大學可能在全球尋找頂尖研究員。"},{"en":"Companies search the world for workers when local supply is not enough.","zh":"當本地供應不足時，公司會在全球尋找員工。"},{"en":"Searching the world for talent can bring new skills into Hong Kong.","zh":"在全球尋找人才可以為香港帶來新技能。"}],"source":"2019 Q2.pdf","sourcePage":1},{"front":"meet international standards","meaning":"符合國際標準","examples":[{"en":"Companies search for people whose skills meet international standards.","zh":"公司尋找技能符合國際標準的人。"},{"en":"To meet international standards means to reach a level accepted globally.","zh":"符合國際標準意思是達到全球認可的水平。"},{"en":"Engineers must meet international standards when designing safe buildings.","zh":"工程師設計安全建築時，必須符合國際標準。"},{"en":"Workers who meet international standards can compete beyond the local market.","zh":"符合國際標準的工作者能在本地市場以外競爭。"},{"en":"Training helps local employees meet international standards.","zh":"培訓幫助本地僱員符合國際標準。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"international standards","meaning":"國際標準","examples":[{"en":"Hong Kong companies need skills that meet international standards.","zh":"香港公司需要符合國際標準的技能。"},{"en":"International standards are levels of quality or practice accepted across countries.","zh":"國際標準是跨國認可的質素或做法水平。"},{"en":"Hospitals, banks, and technology firms often follow international standards.","zh":"醫院、銀行和科技公司常遵循國際標準。"},{"en":"International standards matter because customers and partners compare cities globally.","zh":"國際標準很重要，因為顧客和合作夥伴會在全球比較城市。"},{"en":"A city becomes more competitive when its workers understand international standards.","zh":"當工作者理解國際標準，城市會變得更有競爭力。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"this change has led","meaning":"這個轉變導致","examples":[{"en":"This change has led Hong Kong companies and the government to attract international talent.","zh":"這個轉變導致香港公司和政府吸引國際人才。"},{"en":"This change has led means this new situation has caused something to happen.","zh":"這個轉變導致某事，意思是新情況造成某事發生。"},{"en":"The rise of online shopping has led many shops to improve delivery services.","zh":"網上購物興起導致許多商店改善送貨服務。"},{"en":"Global competition has led companies to look beyond local recruitment.","zh":"全球競爭導致公司放眼本地招聘以外。"},{"en":"This phrase connects a cause with its result.","zh":"這個短語把原因和結果連接起來。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"attract international talent","meaning":"吸引國際人才","examples":[{"en":"The government wants to attract international talent.","zh":"政府想吸引國際人才。"},{"en":"To attract international talent means to bring skilled people from other countries or regions.","zh":"吸引國際人才意思是引入來自其他國家或地區的有技能人士。"},{"en":"A city may attract international talent by offering good jobs and clear visa rules.","zh":"一個城市可以透過提供好工作和清晰簽證規則來吸引國際人才。"},{"en":"Attracting international talent can fill skill gaps in fast-growing industries.","zh":"吸引國際人才可以填補快速發展產業中的技能缺口。"},{"en":"Hong Kong should attract international talent while also training local workers.","zh":"香港應吸引國際人才，同時培訓本地工作者。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"so as to","meaning":"以便；為了","examples":[{"en":"Hong Kong attracts international talent so as to strengthen the economy.","zh":"香港吸引國際人才，以便強化經濟。"},{"en":"So as to means in order to or for the purpose of doing something.","zh":"以便或為了意思是出於某目的去做某事。"},{"en":"Students practise speaking so as to become more confident.","zh":"學生練習說話，以便變得更自信。"},{"en":"Governments design talent schemes so as to support economic growth.","zh":"政府設計人才計劃，以便支持經濟增長。"},{"en":"This phrase clearly explains the purpose behind an action.","zh":"這個短語清楚解釋行動背後的目的。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"strengthen the economy","meaning":"強化經濟","examples":[{"en":"International talent can help strengthen the economy.","zh":"國際人才可以幫助強化經濟。"},{"en":"To strengthen the economy means to make business, jobs, and income more stable or successful.","zh":"強化經濟意思是令商業、就業和收入更穩定或成功。"},{"en":"New technology companies can strengthen the economy by creating skilled jobs.","zh":"新科技公司可以透過創造技術職位來強化經濟。"},{"en":"Skilled workers strengthen the economy when they help firms grow and compete.","zh":"有技能工作者幫助公司成長和競爭時，就是在強化經濟。"},{"en":"A strong economy should benefit both newcomers and local people.","zh":"強大的經濟應該讓新來者和本地人都受益。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"sharpen competitiveness","meaning":"提升競爭力","examples":[{"en":"International talent can sharpen Hong Kong’s competitiveness.","zh":"國際人才可以提升香港的競爭力。"},{"en":"To sharpen competitiveness means to make a person, company, or city better able to compete.","zh":"提升競爭力意思是令個人、公司或城市更有能力競爭。"},{"en":"Training programmes can sharpen workers’ competitiveness in new industries.","zh":"培訓計劃可以提升工作者在新興產業中的競爭力。"},{"en":"Overseas experts may sharpen competitiveness by bringing advanced methods.","zh":"海外專家可能透過帶來先進方法來提升競爭力。"},{"en":"Hong Kong must sharpen competitiveness without weakening fairness.","zh":"香港必須提升競爭力，同時不削弱公平。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"broaden society’s outlook","meaning":"擴闊社會視野","examples":[{"en":"International talent can broaden society’s outlook.","zh":"國際人才可以擴闊社會視野。"},{"en":"To broaden society’s outlook means to help people see more ideas, cultures, and possibilities.","zh":"擴闊社會視野意思是幫助人們看見更多想法、文化和可能性。"},{"en":"Exchange students can broaden a school’s outlook by sharing different learning habits.","zh":"交換生透過分享不同學習習慣，可以擴闊學校視野。"},{"en":"A broader outlook helps society avoid narrow thinking.","zh":"更廣闊的視野幫助社會避免狹隘思維。"},{"en":"Talent from different places can broaden society’s outlook beyond local experience.","zh":"來自不同地方的人才可以把社會視野擴闊到本地經驗以外。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"my view is not that","meaning":"我的看法並不是","examples":[{"en":"My view is not that Hong Kong should choose foreigners over locals.","zh":"我的看法並不是香港應該選擇外地人而忽略本地人。"},{"en":"My view is not that introduces a position the writer does not support.","zh":"我的看法並不是，用來引出作者不支持的立場。"},{"en":"My view is not that exams should disappear completely.","zh":"我的看法並不是考試應該完全消失。"},{"en":"This phrase helps prevent readers from misunderstanding the argument.","zh":"這個短語幫助避免讀者誤解論點。"},{"en":"A careful writer explains both what they believe and what they do not believe.","zh":"謹慎的作者會解釋自己相信甚麼，也會解釋自己不相信甚麼。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"choose foreigners over locals","meaning":"選擇外地人而忽略本地人","examples":[{"en":"Hong Kong should not simply choose foreigners over locals.","zh":"香港不應簡單地選擇外地人而忽略本地人。"},{"en":"To choose foreigners over locals means to prefer people from outside while neglecting local people.","zh":"選擇外地人而忽略本地人，意思是偏好外來人士，同時忽視本地人。"},{"en":"A company chooses foreigners over locals unfairly if locals never get promotion chances.","zh":"如果本地人永遠沒有晉升機會，公司就是不公平地選擇外地人而忽略本地人。"},{"en":"Talent policy should not make residents feel replaced.","zh":"人才政策不應令居民覺得被取代。"},{"en":"Hong Kong needs balance, not a policy that chooses foreigners over locals.","zh":"香港需要平衡，而不是選擇外地人而忽略本地人的政策。"}],"source":"2019 Q2.pdf","sourcePage":2},{"front":"locals over foreigners","meaning":"選擇本地人而忽略外地人","examples":[{"en":"Hong Kong should not choose locals over foreigners either.","zh":"香港也不應選擇本地人而忽略外地人。"},{"en":"To choose locals over foreigners means to prefer local people simply because they are local.","zh":"選擇本地人而忽略外地人，意思是只因他們是本地人就偏好他們。"},{"en":"A company should not choose locals over foreigners if another candidate clearly has needed skills.","zh":"如果另一位候選人明顯具備所需技能，公司不應選擇本地人而忽略外地人。"},{"en":"Choosing locals over foreigners may feel protective, but it can limit growth.","zh":"選擇本地人而忽略外地人可能看似保護本地人，但會限制發展。"},{"en":"Fair policy judges ability and contribution, not birthplace alone.","zh":"公平政策應按能力和貢獻判斷，而不是只看出生地。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"rather","meaning":"而是","examples":[{"en":"Rather, Hong Kong should welcome the world while protecting locals.","zh":"而是，香港應歡迎世界各地的人，同時保護本地人。"},{"en":"Rather introduces the better or more accurate idea after rejecting another one.","zh":"而是用來在否定另一個想法後，引出更好或更準確的想法。"},{"en":"The goal is not to close the door; rather, it is to open it fairly.","zh":"目標不是關上大門；而是公平地敞開大門。"},{"en":"Writers use rather to correct a possible misunderstanding.","zh":"作者使用 rather 來糾正可能的誤解。"},{"en":"Rather helps move an argument from extremes toward balance.","zh":"Rather 幫助論點從極端走向平衡。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"welcome the world","meaning":"歡迎世界各地的人","examples":[{"en":"Hong Kong should welcome the world while protecting its own people.","zh":"香港應歡迎世界各地的人，同時保護自己的人民。"},{"en":"To welcome the world means to accept people, ideas, business, and culture from many places.","zh":"歡迎世界各地的人，意思是接納來自不同地方的人、想法、商業和文化。"},{"en":"Universities welcome the world when they invite students and scholars from abroad.","zh":"大學邀請海外學生和學者時，就是歡迎世界各地的人。"},{"en":"Welcoming the world can make a city more open and competitive.","zh":"歡迎世界各地的人可以令城市更開放和有競爭力。"},{"en":"A city can welcome the world without forgetting local needs.","zh":"一個城市可以歡迎世界各地的人，同時不忘本地需要。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"ensuring that","meaning":"確保","examples":[{"en":"Hong Kong should welcome the world while ensuring that locals are not pushed aside.","zh":"香港應歡迎世界各地的人，同時確保本地人不被擠到一旁。"},{"en":"Ensuring that means making sure something happens or does not happen.","zh":"確保意思是保證某事發生或不發生。"},{"en":"Schools should welcome new students while ensuring that old students still feel included.","zh":"學校應歡迎新學生，同時確保舊生仍感到被包括。"},{"en":"Governments need rules ensuring that talent policy remains fair.","zh":"政府需要規則，確保人才政策保持公平。"},{"en":"This phrase shows responsibility, not just hope.","zh":"這個短語顯示責任，而不只是希望。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"be pushed aside","meaning":"被擠到一旁","examples":[{"en":"Local people should not be pushed aside.","zh":"本地人不應被擠到一旁。"},{"en":"To be pushed aside means to be ignored, replaced, or treated as less important.","zh":"被擠到一旁意思是被忽視、被取代，或被視為較不重要。"},{"en":"Local workers may feel pushed aside if promotion always goes to overseas recruits.","zh":"如果晉升總是給海外招聘的人，本地工作者可能覺得被擠到一旁。"},{"en":"People become resentful when they are pushed aside in their own community.","zh":"當人們在自己的社區中被擠到一旁，他們會產生不滿。"},{"en":"Fair training can prevent locals from being pushed aside.","zh":"公平培訓可以防止本地人被擠到一旁。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"raise standards","meaning":"提高標準","examples":[{"en":"International talent can raise professional standards.","zh":"國際人才可以提高專業標準。"},{"en":"To raise standards means to improve the level of quality or performance.","zh":"提高標準意思是改善質素或表現水平。"},{"en":"Experienced doctors can raise standards in a hospital by sharing better methods.","zh":"有經驗的醫生可以透過分享更好方法來提高醫院標準。"},{"en":"Competition can raise standards if people are also given support to improve.","zh":"如果人們同時獲得改善支持，競爭可以提高標準。"},{"en":"Talent attraction should raise standards for the whole workforce.","zh":"人才吸引應為整體勞動力提高標準。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"connect Hong Kong to","meaning":"把香港連繫到……","examples":[{"en":"International talent can connect Hong Kong to wider networks.","zh":"國際人才可以把香港連繫到更廣闊的人脈及網絡。"},{"en":"To connect Hong Kong to something means to link the city with it.","zh":"把香港連繫到某事，意思是把這個城市與它連接起來。"},{"en":"Overseas professionals can connect Hong Kong to new markets and investors.","zh":"海外專業人士可以把香港連繫到新市場和投資者。"},{"en":"These connections help companies find partners beyond the local economy.","zh":"這些連繫幫助公司在本地經濟以外尋找夥伴。"},{"en":"A global city must connect Hong Kong to opportunities around the world.","zh":"全球城市必須把香港連繫到世界各地的機會。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"wider networks","meaning":"更廣闊的人脈及網絡","examples":[{"en":"International talent can connect Hong Kong to wider networks.","zh":"國際人才可以把香港連繫到更廣闊的人脈及網絡。"},{"en":"Wider networks are larger groups of contacts, partners, and opportunities.","zh":"更廣闊的人脈及網絡是更大的聯絡人、夥伴和機會群體。"},{"en":"A start-up with wider networks can find customers in different countries.","zh":"擁有更廣闊人脈及網絡的初創公司可以在不同國家尋找顧客。"},{"en":"Wider networks matter because business often depends on trust and information.","zh":"更廣闊的人脈及網絡很重要，因為商業常取決於信任和資訊。"},{"en":"Overseas professionals may bring wider networks that local firms do not yet have.","zh":"海外專業人士可能帶來本地公司尚未擁有的更廣闊網絡。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"fair policy","meaning":"公平政策","examples":[{"en":"Fair policy is needed to protect local workers.","zh":"需要公平政策來保護本地工作者。"},{"en":"Fair policy means rules that treat different groups reasonably and justly.","zh":"公平政策是指合理和公正對待不同群體的規則。"},{"en":"A fair policy gives both local and overseas workers clear chances to advance.","zh":"公平政策給本地和海外工作者清晰的發展機會。"},{"en":"Without fair policy, talent attraction may create resentment.","zh":"沒有公平政策，人才吸引可能造成不滿。"},{"en":"Fair policy turns openness into shared benefit.","zh":"公平政策把開放轉化為共同利益。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"serious local training","meaning":"認真的本地培訓","examples":[{"en":"Serious local training can help turn competition into shared progress.","zh":"認真的本地培訓可以幫助把競爭轉化為共同進步。"},{"en":"Serious local training means well-planned and meaningful training for local people.","zh":"認真的本地培訓是指為本地人提供有規劃和有意義的培訓。"},{"en":"A technology company provides serious local training when experts teach local engineers directly.","zh":"當專家直接教導本地工程師時，科技公司就是提供認真的本地培訓。"},{"en":"Serious training helps locals benefit from overseas recruitment instead of fearing it.","zh":"認真培訓幫助本地人從海外招聘中受益，而不是害怕它。"},{"en":"Talent policy is stronger when serious local training is part of it.","zh":"當認真的本地培訓成為其中一部分，人才政策會更強。"}],"source":"2019 Q2.pdf","sourcePage":3},{"front":"turn competition into","meaning":"把競爭轉化為……","examples":[{"en":"Fair policy can turn competition into shared progress.","zh":"公平政策可以把競爭轉化為共同進步。"},{"en":"To turn competition into something means to change rivalry into a better result.","zh":"把競爭轉化為某事，意思是把競爭改變成更好的結果。"},{"en":"Schools can turn competition into learning when students review mistakes together.","zh":"當學生一起檢討錯誤，學校可以把競爭轉化為學習。"},{"en":"Companies turn competition into growth when experienced staff train younger workers.","zh":"當有經驗員工培訓年輕工作者，公司就把競爭轉化為成長。"},{"en":"Hong Kong should turn competition into improvement, not resentment.","zh":"香港應把競爭轉化為改善，而不是不滿。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"shared progress","meaning":"共同進步","examples":[{"en":"International talent should lead to shared progress.","zh":"國際人才應帶來共同進步。"},{"en":"Shared progress means improvement that benefits more than one group.","zh":"共同進步意思是令多於一個群體受益的改善。"},{"en":"A workplace has shared progress when overseas experts and local staff both learn.","zh":"當海外專家和本地員工都能學習，工作場所就有共同進步。"},{"en":"Shared progress reduces jealousy because people can see common gains.","zh":"共同進步可以減少嫉妒，因為人們看見共同得益。"},{"en":"Talent attraction should aim for shared progress, not a winner-takes-all result.","zh":"人才吸引應以共同進步為目標，而不是贏者全取。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"economic and professional benefits","meaning":"經濟和專業上的好處","examples":[{"en":"International talent brings economic and professional benefits.","zh":"國際人才帶來經濟和專業上的好處。"},{"en":"Economic and professional benefits are advantages for business growth and work quality.","zh":"經濟和專業上的好處是指對商業增長和工作質素的優勢。"},{"en":"New experts may create jobs and improve professional skills.","zh":"新專家可能創造職位並提升專業技能。"},{"en":"These benefits matter because cities compete through both money and expertise.","zh":"這些好處很重要，因為城市透過金錢和專業知識競爭。"},{"en":"Hong Kong should make sure economic and professional benefits reach local workers too.","zh":"香港應確保經濟和專業上的好處也惠及本地工作者。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"skilled newcomers","meaning":"有技能的新來者","examples":[{"en":"Skilled newcomers bring new methods and fresh habits.","zh":"有技能的新來者帶來新方法和新做法。"},{"en":"Skilled newcomers are newly arrived people with useful abilities or professional knowledge.","zh":"有技能的新來者是新到來並具備有用能力或專業知識的人。"},{"en":"A skilled newcomer may teach a team a faster way to solve technical problems.","zh":"有技能的新來者可能教團隊更快解決技術問題的方法。"},{"en":"Skilled newcomers can improve a workplace when their knowledge is shared.","zh":"當知識被分享時，有技能的新來者可以改善工作場所。"},{"en":"Local employees benefit most when skilled newcomers become mentors, not rivals only.","zh":"當有技能的新來者成為導師而不只是競爭者時，本地僱員最能受益。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"fresh habits","meaning":"新做法；新習慣","examples":[{"en":"Skilled newcomers bring new methods, fresh habits, and different ways of solving problems.","zh":"有技能的新來者帶來新方法、新做法和不同的解難方法。"},{"en":"Fresh habits are new ways of working or behaving that may improve old routines.","zh":"新做法是可能改善舊慣例的新工作或行為方式。"},{"en":"A new manager may bring fresh habits such as shorter meetings and clearer notes.","zh":"新經理可能帶來新做法，例如較短會議和較清晰紀錄。"},{"en":"Fresh habits can help a team notice problems it used to ignore.","zh":"新做法可以幫助團隊注意以前忽略的問題。"},{"en":"Not every fresh habit is better, but good ones can raise standards.","zh":"不是每種新做法都更好，但好的新做法可以提高標準。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"different ways of solving problems","meaning":"不同的解難方法","examples":[{"en":"International staff may bring different ways of solving problems.","zh":"國際員工可能帶來不同的解難方法。"},{"en":"Different ways of solving problems are varied methods for dealing with difficulties.","zh":"不同的解難方法是處理困難的多種方法。"},{"en":"An engineer from another country may solve a software problem with a method local staff have not tried.","zh":"來自另一國家的工程師可能用本地員工未試過的方法解決軟件問題。"},{"en":"Different methods matter because one problem may need more than one perspective.","zh":"不同方法很重要，因為一個問題可能需要多於一個角度。"},{"en":"A diverse team becomes stronger when it compares different ways of solving problems.","zh":"當多元團隊比較不同的解難方法時，它會變得更強。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"a financial analyst","meaning":"金融分析師","examples":[{"en":"A financial analyst from London may understand European regulations.","zh":"來自倫敦的金融分析師可能了解歐洲法規。"},{"en":"A financial analyst studies money, markets, companies, and investment risks.","zh":"金融分析師研究金錢、市場、公司和投資風險。"},{"en":"A bank may hire a financial analyst to explain market changes.","zh":"銀行可能聘請金融分析師來解釋市場變化。"},{"en":"Financial analysts help companies make decisions based on numbers and risks.","zh":"金融分析師幫助公司根據數字和風險作決定。"},{"en":"An experienced financial analyst can bring useful knowledge from other markets.","zh":"有經驗的金融分析師可以帶來其他市場的有用知識。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"European regulations","meaning":"歐洲法規","examples":[{"en":"A financial analyst from London may understand European regulations.","zh":"來自倫敦的金融分析師可能了解歐洲法規。"},{"en":"European regulations are rules made or used in European markets or countries.","zh":"歐洲法規是在歐洲市場或國家制定或使用的規則。"},{"en":"A Hong Kong bank may need European regulations knowledge when serving European clients.","zh":"香港銀行服務歐洲客戶時，可能需要歐洲法規知識。"},{"en":"Understanding regulations helps firms avoid legal mistakes.","zh":"理解法規能幫助公司避免法律錯誤。"},{"en":"Overseas professionals may bring knowledge of European regulations that local teams lack.","zh":"海外專業人士可能帶來本地團隊缺乏的歐洲法規知識。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"large-scale software systems","meaning":"大型軟件系統","examples":[{"en":"An engineer from India may have experience in large-scale software systems.","zh":"來自印度的工程師可能有大型軟件系統的經驗。"},{"en":"Large-scale software systems are big computer systems used by many people or organisations.","zh":"大型軟件系統是由許多人或機構使用的大型電腦系統。"},{"en":"Online banking and transport apps may depend on large-scale software systems.","zh":"網上銀行和交通應用程式可能依賴大型軟件系統。"},{"en":"Experience with large systems helps engineers prevent crashes and delays.","zh":"大型系統經驗幫助工程師防止系統崩潰和延誤。"},{"en":"Hong Kong technology firms can learn from people who have built large-scale software systems.","zh":"香港科技公司可以向曾建立大型軟件系統的人學習。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"commercialise research","meaning":"將研究商業化","examples":[{"en":"A scientist from Canada may know how to commercialise research.","zh":"來自加拿大的科學家可能知道如何將研究商業化。"},{"en":"To commercialise research means to turn research results into products or services that can be sold.","zh":"將研究商業化意思是把研究成果轉化成可銷售的產品或服務。"},{"en":"A university may commercialise research by turning a medical discovery into a useful test.","zh":"大學可以把醫學發現變成有用測試，從而將研究商業化。"},{"en":"Commercialising research helps ideas leave the laboratory and reach society.","zh":"將研究商業化幫助想法離開實驗室並進入社會。"},{"en":"Scientists with this skill can help Hong Kong link education, technology, and business.","zh":"具備這種技能的科學家可以幫助香港連接教育、科技和商業。"}],"source":"2019 Q2.pdf","sourcePage":4},{"front":"working beside them","meaning":"與他們共事","examples":[{"en":"Working beside overseas professionals, local employees can learn global standards.","zh":"與海外專業人士共事，本地僱員可以學習全球標準。"},{"en":"Working beside them means doing work together with those people in the same environment.","zh":"與他們共事意思是在同一環境中和那些人一起工作。"},{"en":"Junior engineers learn quickly when working beside experienced specialists.","zh":"初級工程師與有經驗專才共事時，學習會很快。"},{"en":"Working beside experts allows local staff to observe real methods, not just read notes.","zh":"與專家共事讓本地員工觀察真實方法，而不只是閱讀筆記。"},{"en":"The value of overseas talent increases when locals can learn by working beside them.","zh":"當本地人能透過與他們共事而學習，海外人才的價值會提高。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"local employees","meaning":"本地僱員","examples":[{"en":"Local employees can learn global standards from skilled newcomers.","zh":"本地僱員可以向有技能的新來者學習全球標準。"},{"en":"Local employees are workers who come from or already live in the local community.","zh":"本地僱員是來自或已居住在本地社群的工作者。"},{"en":"Local employees may worry if overseas hiring reduces their chances to advance.","zh":"如果海外招聘減少晉升機會，本地僱員可能會擔心。"},{"en":"Training helps local employees turn international recruitment into opportunity.","zh":"培訓幫助本地僱員把國際招聘轉化為機會。"},{"en":"Good companies protect local employees while learning from overseas talent.","zh":"好公司會保護本地僱員，同時向海外人才學習。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"global standards","meaning":"全球標準","examples":[{"en":"Local employees can learn global standards instead of staying in familiar routines.","zh":"本地僱員可以學習全球標準，而不是停留在熟悉的慣常做法中。"},{"en":"Global standards are quality levels or practices accepted in many parts of the world.","zh":"全球標準是在世界許多地方被接受的質素水平或做法。"},{"en":"A hotel follows global standards when its service meets international expectations.","zh":"當酒店服務符合國際期望時，就是遵循全球標準。"},{"en":"Learning global standards helps workers compete outside their local market.","zh":"學習全球標準幫助工作者在本地市場以外競爭。"},{"en":"Overseas specialists can teach global standards through daily cooperation.","zh":"海外專才可以透過日常合作教授全球標準。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"instead of","meaning":"而不是","examples":[{"en":"Local employees can learn global standards instead of being locked inside familiar routines.","zh":"本地僱員可以學習全球標準，而不是被困在熟悉的慣常做法中。"},{"en":"Instead of means in place of or rather than another action.","zh":"而不是意思是以某行動取代另一行動。"},{"en":"Students should ask questions instead of pretending to understand.","zh":"學生應提問，而不是假裝明白。"},{"en":"Companies should train local staff instead of only importing talent.","zh":"公司應培訓本地員工，而不是只引入人才。"},{"en":"This phrase clearly contrasts one choice with another.","zh":"這個短語清楚對比兩個選擇。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"locked inside familiar routines","meaning":"被困在熟悉的慣常做法中","examples":[{"en":"Workers should not be locked inside familiar routines.","zh":"工作者不應被困在熟悉的慣常做法中。"},{"en":"To be locked inside familiar routines means to be trapped in old habits and unable to improve.","zh":"被困在熟悉的慣常做法中，意思是受困於舊習慣而無法改善。"},{"en":"A team may be locked inside familiar routines if it always solves problems the same way.","zh":"如果團隊總是用同一方法解決問題，就可能被困在熟悉的慣常做法中。"},{"en":"Outside ideas help workers escape routines that no longer work.","zh":"外來想法幫助工作者擺脫不再有效的慣例。"},{"en":"Training prevents local staff from being locked inside familiar routines.","zh":"培訓防止本地員工被困在熟悉的慣常做法中。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"familiar routines","meaning":"熟悉的慣常做法","examples":[{"en":"Global exposure helps workers move beyond familiar routines.","zh":"全球接觸幫助工作者超越熟悉的慣常做法。"},{"en":"Familiar routines are usual ways of doing things that people know well.","zh":"熟悉的慣常做法是人們很熟悉的做事方式。"},{"en":"A clerk may follow familiar routines when handling the same forms every day.","zh":"文員每天處理同樣表格時，可能會跟隨熟悉的慣常做法。"},{"en":"Familiar routines can save time, but they may also stop improvement.","zh":"熟悉的慣常做法可以節省時間，但也可能阻礙改善。"},{"en":"Workers grow when they learn skills beyond familiar routines.","zh":"當工作者學習超越熟悉慣例的技能時，他們會成長。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"the more diverse…, the more likely…","meaning":"越多元，就越有可能……","examples":[{"en":"The more diverse a workplace becomes, the more likely weak assumptions will be questioned.","zh":"工作場所越多元，站不住腳的假設就越有可能受到質疑。"},{"en":"This structure shows that when one thing increases, another result becomes more likely.","zh":"這個結構顯示一件事增加時，另一個結果更有可能出現。"},{"en":"The more diverse a class becomes, the more likely students are to hear new viewpoints.","zh":"班級越多元，學生就越有可能聽到新觀點。"},{"en":"The more varied a team’s experience is, the more likely old mistakes will be noticed.","zh":"團隊經驗越多樣，就越有可能注意到舊錯誤。"},{"en":"This pattern is useful for explaining cause and effect.","zh":"這個句式適合解釋因果關係。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"a diverse workplace","meaning":"多元化的工作場所","examples":[{"en":"A diverse workplace can help people question weak assumptions.","zh":"多元化的工作場所可以幫助人們質疑站不住腳的假設。"},{"en":"A diverse workplace includes people from different backgrounds, cultures, skills, or experiences.","zh":"多元化的工作場所包括來自不同背景、文化、技能或經驗的人。"},{"en":"A diverse workplace may include local graduates, overseas experts, and mid-career workers.","zh":"多元化的工作場所可能包括本地畢業生、海外專家和中年在職人士。"},{"en":"Diversity helps because different people notice different risks.","zh":"多元有幫助，因為不同的人會注意到不同風險。"},{"en":"A diverse workplace needs respect so that differences become strength.","zh":"多元化的工作場所需要尊重，差異才能變成力量。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"weak assumptions","meaning":"站不住腳的假設","examples":[{"en":"Weak assumptions should be questioned before they become expensive mistakes.","zh":"站不住腳的假設應在變成代價高昂的錯誤前受到質疑。"},{"en":"Weak assumptions are beliefs that lack enough evidence or careful thinking.","zh":"站不住腳的假設是缺乏足夠證據或仔細思考的信念。"},{"en":"A company makes a weak assumption if it thinks all customers want the same product.","zh":"如果公司以為所有顧客都想要同一產品，就是作出站不住腳的假設。"},{"en":"Weak assumptions can waste money because plans are built on poor judgement.","zh":"站不住腳的假設會浪費金錢，因為計劃建基於差劣判斷。"},{"en":"Diverse teams can expose weak assumptions early.","zh":"多元團隊可以及早揭露站不住腳的假設。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"be questioned","meaning":"受到質疑","examples":[{"en":"Weak assumptions may be questioned in a diverse workplace.","zh":"站不住腳的假設可能在多元化工作場所中受到質疑。"},{"en":"To be questioned means to be challenged, examined, or asked about critically.","zh":"受到質疑意思是被挑戰、檢視或批判性地詢問。"},{"en":"A plan should be questioned if it ignores customer needs.","zh":"如果計劃忽視顧客需要，就應受到質疑。"},{"en":"Ideas are questioned so that mistakes can be found before action.","zh":"想法受到質疑，是為了在行動前找出錯誤。"},{"en":"In a healthy workplace, being questioned can improve decisions.","zh":"在健康工作場所中，受到質疑可以改善決定。"}],"source":"2019 Q2.pdf","sourcePage":5},{"front":"expensive mistakes","meaning":"代價高昂的錯誤","examples":[{"en":"Weak assumptions can become expensive mistakes.","zh":"站不住腳的假設可以變成代價高昂的錯誤。"},{"en":"Expensive mistakes are errors that cost a lot of money, time, or opportunity.","zh":"代價高昂的錯誤是耗費大量金錢、時間或機會的錯誤。"},{"en":"Hiring without checking skills can become an expensive mistake.","zh":"沒有檢查技能就聘請員工，可能變成代價高昂的錯誤。"},{"en":"Expensive mistakes happen when organisations act before testing their assumptions.","zh":"當機構未測試假設就行動，代價高昂的錯誤就會發生。"},{"en":"Diverse advice can prevent expensive mistakes before they damage a company.","zh":"多元意見可以在錯誤損害公司前防止代價高昂的錯誤。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, overseas professionals can act as human bridges.","zh":"此外，海外專業人士可以充當人際橋樑。"},{"en":"Moreover means in addition or furthermore.","zh":"此外意思是另外或再者。"},{"en":"Talent brings skills; moreover, it can connect firms to new markets.","zh":"人才帶來技能；此外，人才可以把公司連接到新市場。"},{"en":"Writers use moreover to add another strong point.","zh":"作者使用 moreover 來加入另一個有力觀點。"},{"en":"Moreover is useful when the next idea strengthens the argument.","zh":"當下一個想法加強論點時，moreover 很有用。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"overseas professionals","meaning":"海外專業人士","examples":[{"en":"Overseas professionals can act as human bridges.","zh":"海外專業人士可以充當人際橋樑。"},{"en":"Overseas professionals are trained workers from other countries or regions.","zh":"海外專業人士是來自其他國家或地區的受訓工作者。"},{"en":"Overseas professionals may include doctors, engineers, researchers, and bankers.","zh":"海外專業人士可能包括醫生、工程師、研究員和銀行家。"},{"en":"They can bring skills, contacts, and cultural knowledge.","zh":"他們可以帶來技能、人脈和文化知識。"},{"en":"Overseas professionals help most when they work with and train local staff.","zh":"當海外專業人士與本地員工合作並培訓他們時，幫助最大。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"act as human bridges","meaning":"充當人際橋樑","examples":[{"en":"Overseas professionals can act as human bridges between markets.","zh":"海外專業人士可以在市場之間充當人際橋樑。"},{"en":"To act as human bridges means to connect people, cultures, or businesses through personal knowledge.","zh":"充當人際橋樑意思是透過個人知識連繫人、文化或企業。"},{"en":"A bilingual manager can act as a human bridge between local staff and overseas clients.","zh":"雙語經理可以在本地員工和海外客戶之間充當人際橋樑。"},{"en":"Human bridges reduce misunderstanding because they understand both sides.","zh":"人際橋樑能減少誤解，因為他們理解雙方。"},{"en":"International talent can act as human bridges for Hong Kong companies entering new markets.","zh":"國際人才可以為進入新市場的香港公司充當人際橋樑。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"a Hong Kong start-up","meaning":"香港初創公司","examples":[{"en":"A Hong Kong start-up may want to enter the Middle Eastern market.","zh":"香港初創公司可能想進入中東市場。"},{"en":"A Hong Kong start-up is a new business founded or based in Hong Kong.","zh":"香港初創公司是在香港創立或以香港為基地的新企業。"},{"en":"A Hong Kong start-up may develop an app, a green product, or a finance service.","zh":"香港初創公司可能開發應用程式、環保產品或金融服務。"},{"en":"Start-ups often need networks because they lack large-company resources.","zh":"初創公司常需要網絡，因為它們缺乏大公司的資源。"},{"en":"Overseas talent can help a Hong Kong start-up understand unfamiliar markets.","zh":"海外人才可以幫助香港初創公司了解陌生市場。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"entering the market","meaning":"進入市場","examples":[{"en":"A Hong Kong start-up entering the Middle Eastern market may need cultural knowledge.","zh":"進入中東市場的香港初創公司可能需要文化知識。"},{"en":"Entering the market means starting to sell products or services in a new place or industry.","zh":"進入市場意思是開始在新地方或行業銷售產品或服務。"},{"en":"A company entering the Japanese market may need to understand local customers.","zh":"進入日本市場的公司可能需要了解本地顧客。"},{"en":"Entering a market without research can lead to costly mistakes.","zh":"沒有研究就進入市場，可能導致昂貴錯誤。"},{"en":"International staff can guide firms entering the market for the first time.","zh":"國際員工可以指導首次進入市場的公司。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"Middle Eastern market","meaning":"中東市場","examples":[{"en":"A start-up may gain support when entering the Middle Eastern market.","zh":"初創公司進入中東市場時可能獲得支持。"},{"en":"The Middle Eastern market refers to business opportunities and customers in Middle Eastern countries.","zh":"中東市場是指中東國家的商業機會和顧客。"},{"en":"A finance company may enter the Middle Eastern market by working with local partners.","zh":"金融公司可以透過與本地夥伴合作進入中東市場。"},{"en":"Cultural knowledge matters because consumer expectations differ across regions.","zh":"文化知識很重要，因為不同地區的消費者期望不同。"},{"en":"Overseas professionals may help Hong Kong firms understand the Middle Eastern market.","zh":"海外專業人士可能幫助香港公司了解中東市場。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"language support","meaning":"語言支援","examples":[{"en":"The company may gain not only language support but also cultural understanding.","zh":"公司可能獲得的不只是語言支援，還有文化理解。"},{"en":"Language support means help with speaking, writing, translating, or communicating in another language.","zh":"語言支援是指在另一種語言中說話、書寫、翻譯或溝通的幫助。"},{"en":"A company needs language support when negotiating with clients who speak Arabic.","zh":"公司與說阿拉伯語的客戶談判時，需要語言支援。"},{"en":"Language support reduces mistakes in contracts, meetings, and marketing.","zh":"語言支援能減少合約、會議和市場推廣中的錯誤。"},{"en":"Good language support also helps people build trust.","zh":"良好的語言支援也幫助人建立信任。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"The company may gain not only language support but also an understanding of customs.","zh":"公司可能不但獲得語言支援，而且獲得對習俗的理解。"},{"en":"Not only…but also… connects two important ideas and gives weight to both.","zh":"不但……而且……連接兩個重要想法，並強調兩者。"},{"en":"International talent brings not only skills but also networks.","zh":"國際人才不但帶來技能，而且帶來網絡。"},{"en":"This structure helps writers add a second benefit clearly.","zh":"這個結構幫助作者清楚加入第二個好處。"},{"en":"A strong policy should protect not only companies but also local workers.","zh":"強有力的政策不但應保護公司，而且應保護本地工作者。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"customs and consumer expectations","meaning":"習俗和消費者期望","examples":[{"en":"International talent can bring knowledge of customs and consumer expectations.","zh":"國際人才可以帶來對習俗和消費者期望的知識。"},{"en":"Customs are social practices, and consumer expectations are what buyers hope to receive.","zh":"習俗是社會做法，而消費者期望是買家希望得到的東西。"},{"en":"A business entering a new country must understand local greetings, holidays, and service habits.","zh":"企業進入新國家時，必須理解當地問候、節日和服務習慣。"},{"en":"Ignoring customs and consumer expectations can damage trust.","zh":"忽視習俗和消費者期望可能損害信任。"},{"en":"Overseas professionals help firms adjust products to local markets.","zh":"海外專業人士幫助公司調整產品以配合本地市場。"}],"source":"2019 Q2.pdf","sourcePage":6},{"front":"in that sense","meaning":"從這個意義上說","examples":[{"en":"In that sense, talent attraction is not just about filling vacancies.","zh":"從這個意義上說，人才吸引不只是填補職位空缺。"},{"en":"In that sense means from that particular point of view.","zh":"從這個意義上說，意思是從某個特定角度理解。"},{"en":"In that sense, overseas professionals are bridges, not only employees.","zh":"從這個意義上說，海外專業人士是橋樑，不只是僱員。"},{"en":"Writers use this phrase to explain how an idea should be understood.","zh":"作者使用這個短語來解釋一個想法應如何理解。"},{"en":"In that sense, talent policy is also a strategy for connection.","zh":"從這個意義上說，人才政策也是連繫策略。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"talent attraction","meaning":"人才吸引","examples":[{"en":"Talent attraction is about enlarging Hong Kong’s reach.","zh":"人才吸引是關於擴大香港的影響範圍。"},{"en":"Talent attraction means policies or efforts used to bring skilled people to a place.","zh":"人才吸引是指用來把有技能人士帶到某地的政策或努力。"},{"en":"A city improves talent attraction by offering good careers and a welcoming environment.","zh":"城市透過提供良好事業和友善環境來改善人才吸引。"},{"en":"Talent attraction can fill skill gaps and open new international networks.","zh":"人才吸引可以填補技能缺口並打開新的國際網絡。"},{"en":"Talent attraction must be fair if it is to gain public support.","zh":"人才吸引若要得到公眾支持，就必須公平。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"filling vacancies","meaning":"填補職位空缺","examples":[{"en":"Talent attraction is not just about filling vacancies.","zh":"人才吸引不只是填補職位空缺。"},{"en":"Filling vacancies means finding people for empty job positions.","zh":"填補職位空缺意思是為空缺職位找到人手。"},{"en":"A hospital fills vacancies when it hires nurses for unfilled posts.","zh":"醫院聘請護士填補未有人擔任的職位時，就是填補職位空缺。"},{"en":"Talent policy should do more than fill vacancies; it should build future skills.","zh":"人才政策不應只填補職位空缺；它也應建立未來技能。"},{"en":"Filling vacancies solves immediate needs, but training solves long-term needs.","zh":"填補職位空缺解決即時需要，但培訓解決長遠需要。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"ultimately","meaning":"最終","examples":[{"en":"Talent attraction is ultimately about enlarging Hong Kong’s reach.","zh":"人才吸引最終是關於擴大香港的影響範圍。"},{"en":"Ultimately means in the end or most importantly after everything is considered.","zh":"最終意思是在最後，或在考慮一切後最重要的是。"},{"en":"Ultimately, education should help students think and live better.","zh":"最終，教育應幫助學生更好地思考和生活。"},{"en":"Writers use ultimately to show the deeper final purpose.","zh":"作者使用 ultimately 來顯示更深層的最終目的。"},{"en":"Ultimately, talent policy should make Hong Kong stronger and fairer.","zh":"最終，人才政策應令香港更強大和更公平。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"enlarging Hong Kong’s reach","meaning":"擴大香港的影響範圍","examples":[{"en":"International talent can help enlarge Hong Kong’s reach.","zh":"國際人才可以幫助擴大香港的影響範圍。"},{"en":"Enlarging Hong Kong’s reach means extending the city’s influence, connections, or opportunities.","zh":"擴大香港的影響範圍意思是延伸城市的影響力、連繫或機會。"},{"en":"A start-up enlarges Hong Kong’s reach when it sells services in new regions.","zh":"初創公司在新地區銷售服務時，就是擴大香港的影響範圍。"},{"en":"International talent helps by linking Hong Kong to wider markets.","zh":"國際人才透過把香港連接到更廣闊市場來提供幫助。"},{"en":"Enlarging Hong Kong’s reach should also create opportunities for local people.","zh":"擴大香港的影響範圍也應為本地人創造機會。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, the arrival of overseas talent is not without challenges.","zh":"話雖如此，海外人才的到來並非沒有挑戰。"},{"en":"That said means despite what has just been said, another point must be considered.","zh":"話雖如此意思是儘管剛才說了某事，仍需考慮另一點。"},{"en":"Talent brings benefits; that said, fairness still matters.","zh":"人才帶來好處；話雖如此，公平仍然重要。"},{"en":"Writers use that said to introduce a limitation or counterpoint.","zh":"作者使用 that said 來引出限制或反方觀點。"},{"en":"That said helps an essay sound balanced rather than one-sided.","zh":"That said 幫助文章聽起來平衡，而不是單方面。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"arrival of overseas talent","meaning":"海外人才的到來","examples":[{"en":"The arrival of overseas talent may create challenges.","zh":"海外人才的到來可能帶來挑戰。"},{"en":"The arrival of overseas talent means skilled people from other places coming to work or live locally.","zh":"海外人才的到來，是指來自其他地方的有技能人士來本地工作或生活。"},{"en":"The arrival of overseas talent can improve skills in a company.","zh":"海外人才的到來可以提升公司的技能水平。"},{"en":"It may also raise concerns about jobs, housing, and social integration.","zh":"它也可能引起對工作、住屋和社會融合的憂慮。"},{"en":"Good planning makes the arrival of overseas talent easier for everyone.","zh":"良好規劃能令海外人才的到來對所有人更容易適應。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"not without challenges","meaning":"並非沒有挑戰","examples":[{"en":"The arrival of overseas talent is not without challenges.","zh":"海外人才的到來並非沒有挑戰。"},{"en":"Not without challenges means there are difficulties, even if there are benefits.","zh":"並非沒有挑戰意思是即使有好處，也存在困難。"},{"en":"Online learning is useful but not without challenges for young children.","zh":"網上學習很有用，但對年幼兒童而言並非沒有挑戰。"},{"en":"Talent attraction is not without challenges because fairness and integration matter.","zh":"人才吸引並非沒有挑戰，因為公平和融合很重要。"},{"en":"This phrase gives a balanced view by admitting problems.","zh":"這個短語透過承認問題來提供平衡觀點。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"the first concern is","meaning":"第一個關注是","examples":[{"en":"The first concern is fairness.","zh":"第一個關注是公平。"},{"en":"The first concern is introduces the most immediate or important worry.","zh":"第一個關注是，用來引出最即時或最重要的憂慮。"},{"en":"The first concern is safety when a school organises an overseas trip.","zh":"學校組織海外旅行時，第一個關注是安全。"},{"en":"Writers use this phrase to organise problems clearly.","zh":"作者使用這個短語來清楚組織問題。"},{"en":"In talent policy, the first concern is whether locals are treated fairly.","zh":"在人才政策中，第一個關注是本地人是否受到公平對待。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"fairness","meaning":"公平","examples":[{"en":"Fairness is a key concern in talent policy.","zh":"公平是人才政策中的關鍵關注。"},{"en":"Fairness means treating people justly and giving them reasonable opportunities.","zh":"公平意思是公正對待人，並給予合理機會。"},{"en":"Fairness in hiring means judging candidates by ability, not background alone.","zh":"招聘中的公平是按能力判斷候選人，而不是只看背景。"},{"en":"Without fairness, local workers may lose trust in the policy.","zh":"沒有公平，本地工作者可能對政策失去信任。"},{"en":"A successful talent policy must combine openness with fairness.","zh":"成功的人才政策必須結合開放和公平。"}],"source":"2019 Q2.pdf","sourcePage":7},{"front":"recruit internationally","meaning":"在國際上招聘","examples":[{"en":"Companies may recruit internationally while offering locals only junior posts.","zh":"公司可能在國際上招聘，同時只給本地人初級職位。"},{"en":"To recruit internationally means to hire workers from other countries or regions.","zh":"在國際上招聘意思是從其他國家或地區聘請員工。"},{"en":"A hospital may recruit internationally when it lacks specialist doctors.","zh":"醫院缺乏專科醫生時，可能在國際上招聘。"},{"en":"International recruitment becomes unfair if locals are never trained for senior roles.","zh":"如果本地人永遠得不到高級職位培訓，國際招聘就會變得不公平。"},{"en":"Companies should recruit internationally while also developing local talent.","zh":"公司應在國際上招聘，同時培育本地人才。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"local graduates","meaning":"本地畢業生","examples":[{"en":"Local graduates may feel discouraged by limited opportunities.","zh":"本地畢業生可能因機會有限而感到氣餒。"},{"en":"Local graduates are people who finished their studies in local schools or universities.","zh":"本地畢業生是在本地學校或大學完成學業的人。"},{"en":"Local graduates often look for entry-level jobs after university.","zh":"本地畢業生通常在大學後尋找入門職位。"},{"en":"They may feel worried if all senior jobs seem reserved for overseas recruits.","zh":"如果所有高級職位看似留給海外招聘者，他們可能會擔心。"},{"en":"Talent policy should create pathways for local graduates to grow.","zh":"人才政策應為本地畢業生創造成長途徑。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"low-paid junior posts","meaning":"低薪初級職位","examples":[{"en":"Local graduates should not be offered only low-paid junior posts.","zh":"本地畢業生不應只獲提供低薪初級職位。"},{"en":"Low-paid junior posts are entry-level jobs with low salaries and limited responsibility.","zh":"低薪初級職位是薪金較低、責任有限的入門工作。"},{"en":"A graduate may accept a low-paid junior post to gain experience.","zh":"畢業生可能接受低薪初級職位來累積經驗。"},{"en":"Offering only such posts can make young workers feel undervalued.","zh":"只提供這類職位可能令年輕工作者覺得被低估。"},{"en":"Local graduates need pathways from low-paid junior posts to better roles.","zh":"本地畢業生需要從低薪初級職位通往更好角色的途徑。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"resentment is bound to grow","meaning":"不滿情緒必然增加","examples":[{"en":"If local graduates are treated unfairly, resentment is bound to grow.","zh":"如果本地畢業生受到不公平對待，不滿情緒必然增加。"},{"en":"Resentment is bound to grow means anger and bitterness will almost certainly increase.","zh":"不滿情緒必然增加，意思是憤怒和怨氣幾乎一定會上升。"},{"en":"Resentment grows when workers see no fair chance to advance.","zh":"當工作者看不到公平晉升機會，不滿情緒就會增加。"},{"en":"Unfair hiring can create resentment even if the policy has good intentions.","zh":"不公平招聘即使原意良好，也可能造成不滿。"},{"en":"Clear promotion pathways can stop resentment from growing.","zh":"清晰晉升途徑可以阻止不滿情緒增加。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"be bound to","meaning":"必然會","examples":[{"en":"Resentment is bound to grow if opportunities are unfair.","zh":"如果機會不公平，不滿情緒必然會增加。"},{"en":"Be bound to means very likely or certain to happen.","zh":"必然會意思是很可能或一定會發生。"},{"en":"Students are bound to feel tired if they sleep only four hours.","zh":"如果學生只睡四小時，他們必然會感到疲倦。"},{"en":"Workers are bound to complain if promotion rules are unclear.","zh":"如果晉升規則不清楚，工作者必然會投訴。"},{"en":"This phrase shows a strong and predictable result.","zh":"這個短語顯示強烈而可預見的結果。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"feel discouraged","meaning":"感到氣餒","examples":[{"en":"A young engineer may feel discouraged if promotion seems impossible.","zh":"如果晉升看似不可能，年輕工程師可能感到氣餒。"},{"en":"To feel discouraged means to lose confidence or hope.","zh":"感到氣餒意思是失去信心或希望。"},{"en":"A student may feel discouraged after failing several tests.","zh":"學生幾次測驗失敗後可能感到氣餒。"},{"en":"Local workers feel discouraged when effort does not lead to opportunity.","zh":"當努力沒有帶來機會，本地工作者會感到氣餒。"},{"en":"Fair feedback and training can help people stop feeling discouraged.","zh":"公平回饋和培訓可以幫助人不再感到氣餒。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"senior positions","meaning":"高級職位","examples":[{"en":"Senior positions should not always go to people brought in from elsewhere.","zh":"高級職位不應總是由從其他地方引入的人擔任。"},{"en":"Senior positions are higher-level jobs with more responsibility and authority.","zh":"高級職位是責任和權力較大的較高層工作。"},{"en":"Managers, directors, and team leaders may hold senior positions.","zh":"經理、董事和團隊主管可能擔任高級職位。"},{"en":"Local staff need training if they are to compete for senior positions.","zh":"如果本地員工要競爭高級職位，就需要培訓。"},{"en":"Fair promotion means senior positions are open to qualified people from different backgrounds.","zh":"公平晉升代表高級職位向不同背景的合資格人士開放。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"seem to go to","meaning":"看似落入……手中","examples":[{"en":"Senior positions may seem to go to overseas recruits.","zh":"高級職位可能看似落入海外招聘者手中。"},{"en":"Seem to go to means appear to be given to a particular group.","zh":"看似落入某群體手中，意思是似乎被給予某特定群體。"},{"en":"Awards may seem to go to the same students every year.","zh":"獎項可能每年都看似落入同一批學生手中。"},{"en":"If promotions seem to go only to outsiders, local staff may lose motivation.","zh":"如果晉升看似只落入外來者手中，本地員工可能失去動力。"},{"en":"Transparent criteria help prevent opportunities from seeming to go to one group unfairly.","zh":"透明準則有助防止機會看似不公平地落入某一群體手中。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"brought in from elsewhere","meaning":"從其他地方引入","examples":[{"en":"Some senior staff may be brought in from elsewhere.","zh":"有些高級員工可能從其他地方引入。"},{"en":"Brought in from elsewhere means invited or hired from another place.","zh":"從其他地方引入意思是從另一地方邀請或聘請。"},{"en":"A hospital may bring in a specialist from elsewhere for a difficult operation.","zh":"醫院可能從其他地方引入專家來處理困難手術。"},{"en":"Bringing people in from elsewhere can help if local expertise is limited.","zh":"如果本地專業知識有限，從其他地方引入人才可以有幫助。"},{"en":"It becomes a problem only when locals have no chance to learn or advance.","zh":"只有當本地人沒有學習或晉升機會時，它才成為問題。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"the presence of outsiders","meaning":"外來者的存在","examples":[{"en":"The problem is not the presence of outsiders per se.","zh":"問題並不是外來者的存在本身。"},{"en":"The presence of outsiders means outsiders being there or taking part.","zh":"外來者的存在是指外來者在場或參與其中。"},{"en":"The presence of outsiders can bring new ideas to a workplace.","zh":"外來者的存在可以為工作場所帶來新想法。"},{"en":"Problems arise when outsiders are welcomed while locals are ignored.","zh":"當外來者受到歡迎而本地人被忽視時，問題便出現。"},{"en":"The issue is not presence alone, but whether the system is fair.","zh":"問題不只是存在本身，而是制度是否公平。"}],"source":"2019 Q2.pdf","sourcePage":8},{"front":"per se","meaning":"本身","examples":[{"en":"The problem is not outsiders per se, but the lack of a pathway for locals.","zh":"問題不是外來者本身，而是本地人缺乏發展途徑。"},{"en":"Per se means by itself or in itself.","zh":"Per se 意思是本身或就其本身而言。"},{"en":"Competition per se is not bad if everyone has fair chances.","zh":"競爭本身不是壞事，只要每個人都有公平機會。"},{"en":"Overseas talent per se is not the problem; unfair policy is.","zh":"海外人才本身不是問題；不公平政策才是問題。"},{"en":"This phrase helps separate the thing itself from related problems.","zh":"這個短語幫助區分事物本身和相關問題。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"the absence of","meaning":"缺乏","examples":[{"en":"The real problem is the absence of a visible pathway for locals to advance.","zh":"真正問題是缺乏讓本地人晉升的清晰可見途徑。"},{"en":"The absence of something means that it is missing or not present.","zh":"缺乏某物意思是它不存在或沒有出現。"},{"en":"The absence of clear rules can make promotion feel unfair.","zh":"缺乏清晰規則會令晉升感覺不公平。"},{"en":"Workers become anxious when there is an absence of training opportunities.","zh":"當缺乏培訓機會時，工作者會感到焦慮。"},{"en":"In talent policy, the absence of local pathways can create resentment.","zh":"在人才政策中，缺乏本地發展途徑可能造成不滿。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"a visible pathway","meaning":"清晰可見的途徑","examples":[{"en":"Local workers need a visible pathway for advancement.","zh":"本地工作者需要清晰可見的晉升途徑。"},{"en":"A visible pathway is a clear route showing how someone can move forward.","zh":"清晰可見的途徑是顯示某人如何前進的清楚路線。"},{"en":"A company creates a visible pathway by explaining how junior staff can become managers.","zh":"公司解釋初級員工如何成為經理時，就是創造清晰可見的途徑。"},{"en":"Visible pathways give workers hope because progress seems possible.","zh":"清晰可見的途徑給工作者希望，因為進步看似可能。"},{"en":"Without a visible pathway, local staff may feel stuck.","zh":"沒有清晰可見的途徑，本地員工可能覺得被困住。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"advance","meaning":"晉升；發展","examples":[{"en":"Local workers need a pathway to advance.","zh":"本地工作者需要一條晉升和發展的途徑。"},{"en":"To advance means to move forward, improve, or reach a higher position.","zh":"晉升或發展意思是向前進、改善或達到更高職位。"},{"en":"A young employee advances when she becomes a team leader after training.","zh":"年輕員工接受培訓後成為團隊主管，就是得到晉升。"},{"en":"Workers need skills and fair chances if they are to advance.","zh":"如果工作者要發展，就需要技能和公平機會。"},{"en":"Talent policy should help both newcomers and locals advance.","zh":"人才政策應幫助新來者和本地人一起發展。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"social integration","meaning":"社會融合","examples":[{"en":"Another challenge is social integration.","zh":"另一個挑戰是社會融合。"},{"en":"Social integration means helping different groups live, work, and communicate together smoothly.","zh":"社會融合意思是幫助不同群體順利地一起生活、工作和溝通。"},{"en":"Schools support social integration when local and overseas students join the same activities.","zh":"當本地和海外學生參加同一活動時，學校就是支持社會融合。"},{"en":"Poor social integration can create misunderstanding and distance.","zh":"差劣的社會融合可能造成誤解和距離。"},{"en":"Talent policy needs social integration, not only work visas.","zh":"人才政策需要社會融合，而不只是工作簽證。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"working styles","meaning":"工作方式","examples":[{"en":"Different working styles can easily create misunderstanding.","zh":"不同工作方式很容易造成誤解。"},{"en":"Working styles are the usual ways people communicate, plan, and complete tasks at work.","zh":"工作方式是人們在工作中溝通、計劃和完成任務的慣常方式。"},{"en":"Some workers prefer direct feedback, while others prefer gentle discussion.","zh":"有些工作者喜歡直接回饋，另一些則喜歡溫和討論。"},{"en":"Different working styles can improve a team if people explain their expectations.","zh":"如果人們解釋自己的期望，不同工作方式可以改善團隊。"},{"en":"Without communication, different working styles may create conflict.","zh":"沒有溝通，不同工作方式可能造成衝突。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"create misunderstanding","meaning":"造成誤解","examples":[{"en":"Different working styles can create misunderstanding.","zh":"不同工作方式可以造成誤解。"},{"en":"To create misunderstanding means to cause people to understand each other wrongly.","zh":"造成誤解意思是令人錯誤理解彼此。"},{"en":"A short email may create misunderstanding if the tone sounds rude.","zh":"如果語氣聽起來無禮，簡短電郵可能造成誤解。"},{"en":"Cultural differences can create misunderstanding when people judge behaviour too quickly.","zh":"當人們太快判斷行為，文化差異可能造成誤解。"},{"en":"Clear communication prevents small differences from creating misunderstanding.","zh":"清楚溝通可以防止小差異造成誤解。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"what one culture sees as","meaning":"一種文化視為……的東西","examples":[{"en":"What one culture sees as confidence may be seen by another as arrogance.","zh":"一種文化視為自信的東西，另一種文化可能視為傲慢。"},{"en":"What one culture sees as something means how one group understands or judges it.","zh":"一種文化視為某事物的東西，是指某群體如何理解或判斷它。"},{"en":"What one culture sees as honesty may seem too direct to another culture.","zh":"一種文化視為誠實的東西，對另一種文化來說可能顯得太直接。"},{"en":"This phrase helps compare different cultural interpretations.","zh":"這個短語幫助比較不同文化理解。"},{"en":"In international workplaces, what one culture sees as normal may surprise another.","zh":"在國際工作場所中，一種文化視為正常的東西可能令另一種文化驚訝。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"confidence","meaning":"自信","examples":[{"en":"One culture may see direct speech as confidence.","zh":"一種文化可能把直接說話視為自信。"},{"en":"Confidence means belief in one’s ability or judgement.","zh":"自信意思是相信自己的能力或判斷。"},{"en":"A student shows confidence when she presents her idea clearly.","zh":"學生清楚表達自己的想法時，就是顯示自信。"},{"en":"Confidence can help workers speak up, but too much may seem rude in some cultures.","zh":"自信可以幫助工作者發聲，但過多自信在某些文化中可能顯得無禮。"},{"en":"Good teams distinguish confidence from arrogance.","zh":"好團隊會區分自信和傲慢。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"arrogance","meaning":"傲慢","examples":[{"en":"Confidence may be seen by another culture as arrogance.","zh":"自信可能被另一種文化視為傲慢。"},{"en":"Arrogance means behaving as if one is better or more important than others.","zh":"傲慢意思是表現得好像自己比別人更好或更重要。"},{"en":"A worker shows arrogance if he refuses to listen to local colleagues.","zh":"如果工作者拒絕聆聽本地同事，就是顯示傲慢。"},{"en":"Direct speech may be misunderstood as arrogance if tone and context are ignored.","zh":"如果忽略語氣和背景，直接說話可能被誤解為傲慢。"},{"en":"Cultural training helps people avoid mistaking confidence for arrogance.","zh":"文化培訓幫助人避免把自信誤認為傲慢。"}],"source":"2019 Q2.pdf","sourcePage":9},{"front":"modesty","meaning":"謙遜","examples":[{"en":"Modesty may be mistaken for passivity.","zh":"謙遜可能被誤以為是被動。"},{"en":"Modesty means not showing off one’s ability or success too strongly.","zh":"謙遜意思是不過分展示自己的能力或成功。"},{"en":"A modest employee may speak gently even when they have strong ideas.","zh":"謙遜的員工即使有強烈想法，也可能溫和地說話。"},{"en":"In some workplaces, modesty may be misunderstood as lack of ambition.","zh":"在某些工作場所中，謙遜可能被誤解為缺乏上進心。"},{"en":"Managers should recognise quiet ability instead of overlooking modesty.","zh":"經理應認出安靜的能力，而不是忽視謙遜。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"be mistaken for","meaning":"被誤以為是……","examples":[{"en":"Modesty may be mistaken for passivity.","zh":"謙遜可能被誤以為是被動。"},{"en":"To be mistaken for something means to be wrongly understood as that thing.","zh":"被誤以為是某事物，意思是被錯誤理解成那樣東西。"},{"en":"A quiet student may be mistaken for someone who has no ideas.","zh":"安靜學生可能被誤以為沒有想法。"},{"en":"Cultural habits are easily mistaken for personality traits.","zh":"文化習慣很容易被誤以為是性格特徵。"},{"en":"Good communication prevents confidence from being mistaken for arrogance.","zh":"良好溝通可以防止自信被誤以為是傲慢。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"passivity","meaning":"被動","examples":[{"en":"Modesty may be mistaken for passivity.","zh":"謙遜可能被誤以為是被動。"},{"en":"Passivity means not taking action or not showing active involvement.","zh":"被動意思是不採取行動或不表現積極參與。"},{"en":"A worker shows passivity if they never speak, suggest, or respond.","zh":"如果工作者從不發言、建議或回應，就是表現被動。"},{"en":"Quietness is not always passivity; it may be respect or careful thinking.","zh":"安靜不一定是被動；它可能是尊重或仔細思考。"},{"en":"Managers should not confuse cultural modesty with passivity.","zh":"經理不應把文化上的謙遜和被動混淆。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"outside the workplace","meaning":"在工作場所之外","examples":[{"en":"Outside the workplace, pressure on housing may worry residents.","zh":"在工作場所之外，住屋壓力可能令居民擔心。"},{"en":"Outside the workplace means in life beyond offices, companies, or job duties.","zh":"在工作場所之外，意思是在辦公室、公司或工作職責以外的生活中。"},{"en":"Outside the workplace, newcomers need homes, transport, schools, and community support.","zh":"在工作場所之外，新來者需要住所、交通、學校和社區支援。"},{"en":"Talent policy affects not only companies but also daily life outside the workplace.","zh":"人才政策不只影響公司，也影響工作場所之外的日常生活。"},{"en":"Public planning matters because integration happens outside the workplace too.","zh":"公共規劃很重要，因為融合也發生在工作場所之外。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"pressure on housing","meaning":"住屋壓力","examples":[{"en":"New arrivals may increase pressure on housing.","zh":"新來者可能增加住屋壓力。"},{"en":"Pressure on housing means greater demand for homes, which can raise prices or reduce supply.","zh":"住屋壓力是指對住所需求增加，可能推高價格或減少供應。"},{"en":"More workers moving into a city may create pressure on housing.","zh":"更多工作者搬入城市，可能造成住屋壓力。"},{"en":"Housing pressure worries residents because rent can become less affordable.","zh":"住屋壓力令居民擔心，因為租金可能變得較難負擔。"},{"en":"Talent policy should consider pressure on housing, not only job needs.","zh":"人才政策應考慮住屋壓力，而不只是工作需要。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"public services","meaning":"公共服務","examples":[{"en":"Pressure on public services may worry residents.","zh":"公共服務壓力可能令居民擔心。"},{"en":"Public services are services provided for the community, such as healthcare, transport, and schools.","zh":"公共服務是為社區提供的服務，例如醫療、交通和學校。"},{"en":"A growing population can increase demand for public services.","zh":"人口增長可能增加對公共服務的需求。"},{"en":"Public services need planning if a city wants to welcome more people.","zh":"如果城市想歡迎更多人，公共服務就需要規劃。"},{"en":"Residents support talent policy more easily when public services remain reliable.","zh":"當公共服務保持可靠，居民較容易支持人才政策。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"residents","meaning":"居民","examples":[{"en":"Residents may worry about the hidden price of global ambition.","zh":"居民可能擔心全球化抱負的隱藏代價。"},{"en":"Residents are people who live in a particular place.","zh":"居民是在某個地方生活的人。"},{"en":"Residents may support newcomers but still worry about housing and services.","zh":"居民可能支持新來者，但仍擔心住屋和服務。"},{"en":"Policies affect residents because they shape daily life in the city.","zh":"政策會影響居民，因為它們塑造城市日常生活。"},{"en":"Governments should listen to residents before expanding talent schemes.","zh":"政府擴大人才計劃前，應聆聽居民意見。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"hidden price","meaning":"隱藏代價","examples":[{"en":"Residents may wonder whether they are paying the hidden price of global ambition.","zh":"居民可能懷疑自己是否正在承擔全球化抱負的隱藏代價。"},{"en":"A hidden price is a cost or problem that is not obvious at first.","zh":"隱藏代價是一開始不明顯的成本或問題。"},{"en":"Higher rent may be the hidden price of rapid economic growth.","zh":"租金上升可能是快速經濟增長的隱藏代價。"},{"en":"If policy benefits companies but burdens families, the hidden price becomes unfair.","zh":"如果政策令公司受益卻加重家庭負擔，隱藏代價就變得不公平。"},{"en":"Good planning makes hidden prices visible before they grow.","zh":"良好規劃能在隱藏代價擴大前令它可見。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"global ambition","meaning":"全球化抱負","examples":[{"en":"Hong Kong’s global ambition may create local pressure.","zh":"香港的全球化抱負可能造成本地壓力。"},{"en":"Global ambition means the desire to become more important or competitive internationally.","zh":"全球化抱負意思是希望在國際上變得更重要或更有競爭力。"},{"en":"A city shows global ambition when it attracts companies, students, and professionals from abroad.","zh":"城市吸引海外公司、學生和專業人士時，就是顯示全球化抱負。"},{"en":"Global ambition can bring growth, but it may also strain local resources.","zh":"全球化抱負可以帶來增長，但也可能令本地資源受壓。"},{"en":"A wise city balances global ambition with local protection.","zh":"明智的城市會平衡全球化抱負和本地保護。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"such worries","meaning":"這些憂慮","examples":[{"en":"Such worries should not be ignored.","zh":"這些憂慮不應被忽視。"},{"en":"Such worries means the concerns just mentioned.","zh":"這些憂慮意思是剛才提到的擔心。"},{"en":"If residents worry about housing and jobs, such worries deserve a serious response.","zh":"如果居民擔心住屋和工作，這些憂慮值得認真回應。"},{"en":"Ignoring such worries can make people distrust the policy.","zh":"忽視這些憂慮可能令人不信任政策。"},{"en":"Leaders should answer such worries with facts, planning, and fairness.","zh":"領導者應以事實、規劃和公平回應這些憂慮。"}],"source":"2019 Q2.pdf","sourcePage":10},{"front":"be ignored","meaning":"被忽視","examples":[{"en":"If such worries are ignored, the policy may divide society.","zh":"如果這些憂慮被忽視，政策可能分裂社會。"},{"en":"To be ignored means to be noticed but not seriously considered or answered.","zh":"被忽視意思是被注意到卻沒有被認真考慮或回應。"},{"en":"Local workers feel hurt when their concerns are ignored.","zh":"當本地工作者的關注被忽視時，他們會感到受傷。"},{"en":"Problems often grow when early warnings are ignored.","zh":"當早期警告被忽視，問題往往會擴大。"},{"en":"Talent policy is safer when public worries are not ignored.","zh":"當公眾憂慮沒有被忽視時，人才政策會更安全。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"be meant to","meaning":"旨在","examples":[{"en":"A policy meant to strengthen Hong Kong may instead divide it.","zh":"一項旨在強化香港的政策，可能反而令香港分裂。"},{"en":"Be meant to means be intended or designed to do something.","zh":"旨在意思是打算或設計來做某事。"},{"en":"A training scheme is meant to help workers improve their skills.","zh":"培訓計劃旨在幫助工作者提升技能。"},{"en":"A policy meant to help can still fail if it ignores fairness.","zh":"旨在幫助人的政策，如果忽視公平，仍可能失敗。"},{"en":"This phrase shows the intended purpose behind an action.","zh":"這個短語顯示行動背後的原本目的。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"instead divide it","meaning":"反而使其分裂","examples":[{"en":"A policy meant to strengthen Hong Kong may instead divide it.","zh":"一項旨在強化香港的政策，可能反而使其分裂。"},{"en":"Instead divide it means produce the opposite result by separating people into opposing groups.","zh":"反而使其分裂意思是產生相反結果，把人分成對立群體。"},{"en":"A school rule meant to build discipline may instead divide students if it feels unfair.","zh":"旨在建立紀律的校規，如果感覺不公平，可能反而使學生分裂。"},{"en":"Talent policy may divide society if locals feel excluded.","zh":"如果本地人覺得被排除在外，人才政策可能分裂社會。"},{"en":"Careful design prevents a helpful policy from instead dividing the community.","zh":"謹慎設計能防止有益政策反而使社區分裂。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"in a way that","meaning":"以一種……的方式","examples":[{"en":"Hong Kong must welcome international talent in a way that protects local people.","zh":"香港必須以一種保護本地人的方式歡迎國際人才。"},{"en":"In a way that means by using a method that produces a particular result.","zh":"以一種……的方式意思是用會產生特定結果的方法。"},{"en":"Schools should use technology in a way that helps learning, not distracts students.","zh":"學校應以一種幫助學習而非分散學生注意力的方式使用科技。"},{"en":"Hong Kong should open its door in a way that creates shared progress.","zh":"香港應以一種創造共同進步的方式敞開大門。"},{"en":"This phrase links an action with the manner in which it should happen.","zh":"這個短語把行動和它應如何發生連接起來。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"protects and develops","meaning":"保護並培育","examples":[{"en":"Hong Kong should attract talent in a way that protects and develops local people.","zh":"香港應以保護並培育本地人的方式吸引人才。"},{"en":"Protects and develops means keeps people safe while helping them grow.","zh":"保護並培育意思是保障人們，同時幫助他們成長。"},{"en":"A company protects and develops workers by offering fair pay and training.","zh":"公司透過提供公平薪酬和培訓來保護並培育員工。"},{"en":"Talent policy should protect local opportunities and develop local skills.","zh":"人才政策應保護本地機會並培育本地技能。"},{"en":"Growth is healthier when it protects and develops the existing community.","zh":"當增長能保護並培育原有社群時，它會更健康。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"be encouraged to","meaning":"應被鼓勵","examples":[{"en":"Companies should be encouraged to link overseas recruitment with local training.","zh":"公司應被鼓勵把海外招聘與本地培訓連繫起來。"},{"en":"To be encouraged to do something means to be supported or urged to do it.","zh":"應被鼓勵做某事，意思是獲支持或被推動去做它。"},{"en":"Students are encouraged to ask questions when they do not understand.","zh":"學生不明白時，應被鼓勵提問。"},{"en":"Companies may be encouraged to train local staff through subsidies or rules.","zh":"公司可能透過資助或規則被鼓勵培訓本地員工。"},{"en":"Encouragement works best when it is linked to clear expectations.","zh":"鼓勵與清晰期望連繫起來時最有效。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"link…with…","meaning":"把……與……連繫起來","examples":[{"en":"Companies should link overseas recruitment with local training.","zh":"公司應把海外招聘與本地培訓連繫起來。"},{"en":"To link one thing with another means to connect them so they work together.","zh":"把一件事與另一件事連繫起來，意思是把它們連接，使它們一起發揮作用。"},{"en":"Schools can link classroom learning with internships.","zh":"學校可以把課堂學習與實習連繫起來。"},{"en":"Linking overseas recruitment with local training helps local staff benefit.","zh":"把海外招聘與本地培訓連繫起來，有助本地員工受益。"},{"en":"This phrase shows that two actions should not be separate.","zh":"這個短語顯示兩個行動不應分開。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"overseas recruitment","meaning":"海外招聘","examples":[{"en":"Overseas recruitment should be linked with local training.","zh":"海外招聘應與本地培訓連繫起來。"},{"en":"Overseas recruitment means hiring workers from other countries or regions.","zh":"海外招聘意思是從其他國家或地區聘請員工。"},{"en":"Overseas recruitment can fill skill gaps in technology or healthcare.","zh":"海外招聘可以填補科技或醫療方面的技能缺口。"},{"en":"It becomes more acceptable when it includes knowledge transfer.","zh":"當海外招聘包括知識轉移時，它會更容易被接受。"},{"en":"Overseas recruitment should strengthen local capacity, not replace it.","zh":"海外招聘應強化本地能力，而不是取代它。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"local training","meaning":"本地培訓","examples":[{"en":"Local training should accompany overseas recruitment.","zh":"本地培訓應伴隨海外招聘。"},{"en":"Local training means teaching local workers new skills or improving existing ones.","zh":"本地培訓意思是教授本地工作者新技能或改善現有技能。"},{"en":"A company provides local training when overseas experts coach Hong Kong employees.","zh":"當海外專家指導香港僱員時，公司就是提供本地培訓。"},{"en":"Local training helps residents compete fairly for better jobs.","zh":"本地培訓幫助居民公平競爭更好的工作。"},{"en":"Without local training, talent attraction may benefit only a small group.","zh":"沒有本地培訓，人才吸引可能只惠及少數人。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"for every senior specialist","meaning":"每聘請一位高級專才","examples":[{"en":"For every senior specialist hired from abroad, there should be training support.","zh":"每聘請一位從海外來的高級專才，都應有培訓支援。"},{"en":"For every senior specialist means each time one high-level expert is employed.","zh":"每聘請一位高級專才意思是每當聘用一位高層專家。"},{"en":"For every senior specialist brought in, a company could train two junior local staff.","zh":"每引入一位高級專才，公司可以培訓兩位本地初級員工。"},{"en":"This rule connects expert hiring with local development.","zh":"這條規則把專家招聘與本地發展連繫起來。"},{"en":"It helps ensure overseas expertise becomes shared knowledge.","zh":"它有助確保海外專業知識變成共享知識。"}],"source":"2019 Q2.pdf","sourcePage":11},{"front":"hired from abroad","meaning":"從海外聘請","examples":[{"en":"A senior specialist may be hired from abroad.","zh":"高級專才可能從海外聘請。"},{"en":"Hired from abroad means employed from another country or region.","zh":"從海外聘請意思是從另一國家或地區聘用。"},{"en":"A university may hire a professor from abroad to build a new research centre.","zh":"大學可能從海外聘請教授來建立新研究中心。"},{"en":"Someone hired from abroad can bring rare skills into a local workplace.","zh":"從海外聘請的人可以把稀有技能帶入本地工作場所。"},{"en":"The benefit is greater when people hired from abroad also train local colleagues.","zh":"當從海外聘請的人也培訓本地同事，益處會更大。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"mentorship schemes","meaning":"導師計劃","examples":[{"en":"Mentorship schemes can help local staff learn from overseas specialists.","zh":"導師計劃可以幫助本地員工向海外專才學習。"},{"en":"Mentorship schemes are organised programmes where experienced people guide less experienced people.","zh":"導師計劃是由有經驗人士指導較少經驗人士的有組織計劃。"},{"en":"A junior engineer may join a mentorship scheme with a senior overseas expert.","zh":"初級工程師可能參加由海外高級專家指導的導師計劃。"},{"en":"Mentorship schemes help transfer knowledge through regular conversations and tasks.","zh":"導師計劃透過定期對話和任務幫助轉移知識。"},{"en":"They make talent attraction more useful for local development.","zh":"它們令人才吸引對本地發展更有用。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"knowledge-transfer targets","meaning":"知識轉移目標","examples":[{"en":"Companies should set knowledge-transfer targets.","zh":"公司應設定知識轉移目標。"},{"en":"Knowledge-transfer targets are clear goals for sharing skills and expertise with others.","zh":"知識轉移目標是與他人分享技能和專業知識的清晰目標。"},{"en":"A target may require an overseas expert to train five local staff within a year.","zh":"一個目標可能要求海外專家在一年內培訓五位本地員工。"},{"en":"Targets matter because knowledge sharing should not be left to chance.","zh":"目標很重要，因為知識分享不應靠運氣。"},{"en":"Knowledge-transfer targets help measure whether recruitment benefits the whole team.","zh":"知識轉移目標幫助衡量招聘是否惠及整個團隊。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"promotion pathways","meaning":"晉升途徑","examples":[{"en":"Local staff need clear promotion pathways.","zh":"本地員工需要清晰的晉升途徑。"},{"en":"Promotion pathways are routes showing how workers can move to higher positions.","zh":"晉升途徑是顯示工作者如何升上更高職位的路線。"},{"en":"A company creates promotion pathways by listing skills needed for each level.","zh":"公司列出每個級別所需技能時，就是創造晉升途徑。"},{"en":"Clear pathways help workers plan training and career growth.","zh":"清晰途徑幫助工作者規劃培訓和事業發展。"},{"en":"Without promotion pathways, local staff may feel blocked.","zh":"沒有晉升途徑，本地員工可能感到受阻。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"local staff","meaning":"本地員工","examples":[{"en":"Local staff should benefit from international recruitment.","zh":"本地員工應從國際招聘中受益。"},{"en":"Local staff are employees who are from or based in the local community.","zh":"本地員工是來自或以本地社群為基地的僱員。"},{"en":"Local staff may learn new methods from overseas specialists.","zh":"本地員工可能向海外專才學習新方法。"},{"en":"They should receive training so that talent attraction becomes shared progress.","zh":"他們應接受培訓，使人才吸引成為共同進步。"},{"en":"A fair policy protects local staff while welcoming outside expertise.","zh":"公平政策會在歡迎外來專業知識時保護本地員工。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"artificial-intelligence researcher","meaning":"人工智能研究員","examples":[{"en":"A technology company may hire an experienced artificial-intelligence researcher.","zh":"科技公司可能聘請一位有經驗的人工智能研究員。"},{"en":"An artificial-intelligence researcher studies how machines can learn, reason, or make decisions.","zh":"人工智能研究員研究機器如何學習、推理或作決定。"},{"en":"A researcher may develop tools that recognise speech or analyse medical images.","zh":"研究員可能開發辨認語音或分析醫學影像的工具。"},{"en":"Hiring such a researcher can help a company build advanced technology.","zh":"聘請這類研究員可以幫助公司建立先進科技。"},{"en":"The researcher should also train local colleagues so knowledge stays in the city.","zh":"研究員也應培訓本地同事，讓知識留在城市中。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"experienced researcher","meaning":"有經驗的研究員","examples":[{"en":"An experienced researcher can train local colleagues.","zh":"有經驗的研究員可以培訓本地同事。"},{"en":"An experienced researcher is someone who has spent years doing serious study or experiments.","zh":"有經驗的研究員是多年從事認真研究或實驗的人。"},{"en":"An experienced researcher knows not only theories but also common mistakes.","zh":"有經驗的研究員不只懂理論，也知道常見錯誤。"},{"en":"Local colleagues learn faster when an experienced researcher explains real cases.","zh":"當有經驗的研究員解釋真實案例時，本地同事學得更快。"},{"en":"Hiring an experienced researcher is most useful when their knowledge is shared.","zh":"聘請有經驗的研究員時，如果他們的知識被分享，最有用。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"real success would not be that…, but that…","meaning":"真正的成功不在於……而在於……","examples":[{"en":"Real success would not be that one expert completes one project, but that local colleagues learn enough to lead the next one.","zh":"真正的成功不在於一位專家完成一個項目，而在於本地同事學到足以帶領下一個項目。"},{"en":"This structure contrasts a shallow success with a deeper success.","zh":"這個結構把表面的成功和更深層的成功作對比。"},{"en":"Real success would not be that students pass once, but that they learn how to study independently.","zh":"真正的成功不在於學生一次合格，而在於他們學會如何獨立學習。"},{"en":"In talent policy, real success means building local ability, not only finishing a task.","zh":"在人才政策中，真正成功是建立本地能力，而不只是完成任務。"},{"en":"This phrase helps writers define what success should truly mean.","zh":"這個短語幫助作者定義成功真正應該是甚麼。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"complete one project","meaning":"完成一個項目","examples":[{"en":"One expert may complete one project successfully.","zh":"一位專家可能成功完成一個項目。"},{"en":"To complete one project means to finish one planned piece of work.","zh":"完成一個項目意思是完成一項已計劃的工作。"},{"en":"A team may complete one project after months of research and testing.","zh":"團隊可能在數月研究和測試後完成一個項目。"},{"en":"Completing one project is useful, but it may not build long-term local skills.","zh":"完成一個項目很有用，但未必建立長遠本地技能。"},{"en":"The next goal is to help local colleagues complete future projects themselves.","zh":"下一個目標是幫助本地同事自己完成未來項目。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"learn enough to lead","meaning":"學到足以帶領","examples":[{"en":"Local colleagues should learn enough to lead the next project.","zh":"本地同事應學到足以帶領下一個項目。"},{"en":"To learn enough to lead means to gain enough knowledge and confidence to take charge.","zh":"學到足以帶領意思是獲得足夠知識和信心去負責。"},{"en":"A junior worker learns enough to lead after training, practice, and feedback.","zh":"初級工作者經過培訓、練習和回饋後，會學到足以帶領。"},{"en":"Knowledge transfer succeeds when local staff learn enough to lead without constant outside help.","zh":"當本地員工學到足以在沒有持續外援下帶領，知識轉移就成功。"},{"en":"Talent attraction should help people learn enough to lead, not only follow.","zh":"人才吸引應幫助人學到足以帶領，而不只是跟隨。"}],"source":"2019 Q2.pdf","sourcePage":12},{"front":"the next one","meaning":"下一個","examples":[{"en":"Local colleagues should learn enough to lead the next one.","zh":"本地同事應學到足以帶領下一個。"},{"en":"The next one means the following project, task, or example after the current one.","zh":"下一個意思是目前這個之後的項目、任務或例子。"},{"en":"After completing this report, the team will prepare the next one.","zh":"完成這份報告後，團隊會準備下一個。"},{"en":"Training matters because local staff should not always depend on outsiders for the next one.","zh":"培訓很重要，因為本地員工不應總是依賴外來者處理下一個。"},{"en":"This phrase avoids repeating the noun already mentioned.","zh":"這個短語避免重複剛才提過的名詞。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"educational institutions","meaning":"教育機構","examples":[{"en":"The government and educational institutions have a role to play.","zh":"政府和教育機構有角色可發揮。"},{"en":"Educational institutions are schools, universities, colleges, and training centres.","zh":"教育機構是學校、大學、專上學院和培訓中心。"},{"en":"Educational institutions prepare students for future jobs by teaching relevant skills.","zh":"教育機構透過教授相關技能，為學生未來工作作準備。"},{"en":"They can support talent policy by training local people for emerging industries.","zh":"它們可以透過培訓本地人進入新興產業來支持人才政策。"},{"en":"Strong educational institutions reduce the fear of being left behind.","zh":"強大的教育機構能減少被拋離的恐懼。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"have a role to play","meaning":"有角色可發揮","examples":[{"en":"The government and educational institutions have a role to play.","zh":"政府和教育機構有角色可發揮。"},{"en":"To have a role to play means to have responsibility or a useful part in solving something.","zh":"有角色可發揮意思是在解決某事上有責任或有用的位置。"},{"en":"Parents have a role to play in helping children build study habits.","zh":"父母在幫助孩子建立學習習慣方面有角色可發揮。"},{"en":"Universities have a role to play in preparing students for new industries.","zh":"大學在幫助學生準備進入新興產業方面有角色可發揮。"},{"en":"This phrase shows that a problem requires several contributors.","zh":"這個短語顯示問題需要多方參與。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"vocational bodies","meaning":"職業培訓機構","examples":[{"en":"Universities, vocational bodies, and employers should design relevant courses.","zh":"大學、職業培訓機構和僱主應設計相關課程。"},{"en":"Vocational bodies are organisations that provide job-related training or professional skills.","zh":"職業培訓機構是提供與工作相關培訓或專業技能的組織。"},{"en":"A vocational body may train electricians, nurses, or technicians.","zh":"職業培訓機構可能培訓電工、護士或技術員。"},{"en":"Vocational bodies help workers gain practical skills for real industries.","zh":"職業培訓機構幫助工作者獲得真實產業所需的實用技能。"},{"en":"They are important because not all learning happens in universities.","zh":"它們很重要，因為不是所有學習都在大學發生。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"design courses around","meaning":"圍繞……設計課程","examples":[{"en":"Institutions should design courses around emerging industries.","zh":"機構應圍繞新興產業設計課程。"},{"en":"To design courses around something means to build lessons and training based on that topic or need.","zh":"圍繞某事設計課程，意思是根據該主題或需要建立課堂和培訓。"},{"en":"Schools may design courses around digital skills if employers need them.","zh":"如果僱主需要數碼技能，學校可能圍繞數碼技能設計課程。"},{"en":"Designing courses around emerging industries helps students prepare before the market changes.","zh":"圍繞新興產業設計課程，幫助學生在市場改變前作準備。"},{"en":"Courses are more useful when they are designed around real future demand.","zh":"課程圍繞真實未來需求設計時，會更有用。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"emerging industries","meaning":"新興產業","examples":[{"en":"Courses should prepare students for emerging industries.","zh":"課程應讓學生準備進入新興產業。"},{"en":"Emerging industries are new or fast-growing areas of business and technology.","zh":"新興產業是新的或快速增長的商業和科技領域。"},{"en":"Biotechnology, green finance, and digital security are emerging industries.","zh":"生物科技、綠色金融和數碼安全都是新興產業。"},{"en":"Emerging industries need workers with updated knowledge and flexible skills.","zh":"新興產業需要具備最新知識和靈活技能的工作者。"},{"en":"Training for emerging industries helps young people avoid falling behind.","zh":"新興產業培訓幫助年輕人避免落後。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"biotechnology","meaning":"生物科技","examples":[{"en":"Biotechnology is one of the emerging industries mentioned in the passage.","zh":"生物科技是文章中提到的新興產業之一。"},{"en":"Biotechnology uses living things, cells, or biological knowledge to create products or solve problems.","zh":"生物科技使用生物、細胞或生物知識來創造產品或解決問題。"},{"en":"Biotechnology can help develop medicines, vaccines, and improved crops.","zh":"生物科技可以幫助開發藥物、疫苗和改良農作物。"},{"en":"Students need science and laboratory skills to work in biotechnology.","zh":"學生需要科學和實驗室技能才能在生物科技工作。"},{"en":"Hong Kong can prepare talent for biotechnology through research and training.","zh":"香港可以透過研究和培訓為生物科技準備人才。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"green finance","meaning":"綠色金融","examples":[{"en":"Green finance is an emerging industry.","zh":"綠色金融是一個新興產業。"},{"en":"Green finance means financial activities that support environmental protection or sustainable development.","zh":"綠色金融是支持環境保護或可持續發展的金融活動。"},{"en":"A bank practises green finance when it funds clean energy projects.","zh":"銀行資助清潔能源項目時，就是實踐綠色金融。"},{"en":"Green finance requires knowledge of both money and environmental risk.","zh":"綠色金融需要金錢和環境風險兩方面的知識。"},{"en":"Training in green finance can help Hong Kong connect business with sustainability.","zh":"綠色金融培訓可以幫助香港把商業與可持續發展連接起來。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"digital security","meaning":"數碼安全","examples":[{"en":"Digital security is an important emerging industry.","zh":"數碼安全是一個重要的新興產業。"},{"en":"Digital security protects computer systems, online data, and digital services from attack or misuse.","zh":"數碼安全保護電腦系統、網上數據和數碼服務免受攻擊或濫用。"},{"en":"Banks need digital security to protect customer information.","zh":"銀行需要數碼安全來保護客戶資料。"},{"en":"As more services move online, digital security becomes more important.","zh":"隨著更多服務轉到網上，數碼安全變得更重要。"},{"en":"Hong Kong needs trained workers in digital security to protect businesses and residents.","zh":"香港需要受訓的數碼安全工作者來保護企業和居民。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"catch up","meaning":"追趕","examples":[{"en":"Hong Kong students should not always be catching up after the market has changed.","zh":"香港學生不應總是在市場改變後才追趕。"},{"en":"To catch up means to reach the level of others after falling behind.","zh":"追趕意思是在落後後達到他人的水平。"},{"en":"A student may need to catch up after missing lessons for a week.","zh":"學生缺課一星期後可能需要追趕進度。"},{"en":"Workers must catch up quickly when technology changes faster than training.","zh":"當科技變化快過培訓時，工作者必須快速追趕。"},{"en":"Good education helps people prepare early instead of always catching up.","zh":"良好教育幫助人及早準備，而不是總是追趕。"}],"source":"2019 Q2.pdf","sourcePage":13},{"front":"after the market has changed","meaning":"在市場改變之後","examples":[{"en":"Students should not always catch up only after the market has changed.","zh":"學生不應總是在市場改變之後才追趕。"},{"en":"After the market has changed means after employers and industries already need different skills.","zh":"在市場改變之後，意思是在僱主和產業已經需要不同技能之後。"},{"en":"If schools update courses late, students learn only after the market has changed.","zh":"如果學校太遲更新課程，學生只能在市場改變之後才學習。"},{"en":"This delay makes young workers less prepared for new jobs.","zh":"這種延遲令年輕工作者較少準備好面對新工作。"},{"en":"Education should predict needs before the market has changed.","zh":"教育應在市場改變之前預測需要。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"scholarships","meaning":"獎學金","examples":[{"en":"Scholarships should be expanded for young workers.","zh":"獎學金應為年輕工作者擴大。"},{"en":"Scholarships are financial awards that help people pay for study or training.","zh":"獎學金是幫助人支付學習或培訓費用的財政獎勵。"},{"en":"A scholarship may allow a student to study biotechnology without heavy debt.","zh":"獎學金可能讓學生不用負重債也能學習生物科技。"},{"en":"Scholarships help talented people continue learning even if their families are not wealthy.","zh":"獎學金幫助有才華的人繼續學習，即使他們家庭不富裕。"},{"en":"More scholarships can prepare local workers for emerging industries.","zh":"更多獎學金可以讓本地工作者準備進入新興產業。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"internships","meaning":"實習機會","examples":[{"en":"Internships should be expanded for young workers.","zh":"實習機會應為年輕工作者擴大。"},{"en":"Internships are short-term work experiences that help people learn about a job or industry.","zh":"實習機會是幫助人了解工作或行業的短期工作經驗。"},{"en":"A student may join an internship at a technology company during summer.","zh":"學生可能在暑假到科技公司實習。"},{"en":"Internships help young workers connect classroom knowledge with real tasks.","zh":"實習機會幫助年輕工作者把課堂知識和真實任務連接起來。"},{"en":"More internships can make local talent more competitive.","zh":"更多實習機會可以令本地人才更有競爭力。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"subsidised re-training","meaning":"受資助再培訓","examples":[{"en":"Subsidised re-training should be expanded for mid-career employees.","zh":"受資助再培訓應為中年在職人士擴大。"},{"en":"Subsidised re-training means training partly paid for by the government or another organisation.","zh":"受資助再培訓是由政府或其他機構支付部分費用的培訓。"},{"en":"A mid-career worker may use subsidised re-training to learn digital security.","zh":"中年工作者可能使用受資助再培訓來學習數碼安全。"},{"en":"Re-training helps workers move into new fields when old jobs change.","zh":"當舊工作改變時，再培訓幫助工作者轉入新領域。"},{"en":"Subsidised re-training reduces the cost of learning new skills.","zh":"受資助再培訓降低學習新技能的成本。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"be expanded for","meaning":"為……擴大","examples":[{"en":"Training opportunities should be expanded for young workers.","zh":"培訓機會應為年輕工作者擴大。"},{"en":"To be expanded for a group means to be increased or made more available to that group.","zh":"為某群體擴大，意思是增加或令該群體更容易獲得。"},{"en":"Scholarships can be expanded for students from low-income families.","zh":"獎學金可以為低收入家庭學生擴大。"},{"en":"Training should be expanded for workers who risk being left behind.","zh":"培訓應為有被拋離風險的工作者擴大。"},{"en":"Expanding support makes opportunity more equal.","zh":"擴大支援能令機會更平等。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"young workers","meaning":"年輕工作者","examples":[{"en":"Young workers need more training opportunities.","zh":"年輕工作者需要更多培訓機會。"},{"en":"Young workers are people at the early stage of their working lives.","zh":"年輕工作者是處於職業生涯早期的人。"},{"en":"Young workers may lack experience but have strong potential to learn.","zh":"年輕工作者可能缺乏經驗，但有很強學習潛力。"},{"en":"Training helps young workers move from junior jobs to skilled roles.","zh":"培訓幫助年輕工作者從初級工作走向技術職位。"},{"en":"A city invests in its future when it supports young workers.","zh":"城市支持年輕工作者時，就是投資自己的未來。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"mid-career employees","meaning":"中年在職人士","examples":[{"en":"Mid-career employees may need subsidised re-training.","zh":"中年在職人士可能需要受資助再培訓。"},{"en":"Mid-career employees are workers who already have years of work experience but are not yet near retirement.","zh":"中年在職人士是已有多年工作經驗、但尚未接近退休的工作者。"},{"en":"A mid-career employee may need new digital skills when their industry changes.","zh":"當行業改變，中年在職人士可能需要新的數碼技能。"},{"en":"Re-training helps mid-career employees stay employable.","zh":"再培訓幫助中年在職人士保持受聘能力。"},{"en":"Talent policy should not focus only on graduates; mid-career employees need support too.","zh":"人才政策不應只集中於畢業生；中年在職人士也需要支持。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"risk being left behind","meaning":"有被拋離的風險","examples":[{"en":"Some workers risk being left behind if training is insufficient.","zh":"如果培訓不足，一些工作者有被拋離的風險。"},{"en":"To risk being left behind means to face the possibility of falling behind others.","zh":"有被拋離的風險，意思是面對落後於他人的可能性。"},{"en":"Workers risk being left behind when technology changes but their skills do not.","zh":"當科技改變但技能沒有改變，工作者就有被拋離的風險。"},{"en":"Training reduces the risk of being left behind in new industries.","zh":"培訓能減少在新興產業中被拋離的風險。"},{"en":"A fair society helps people who risk being left behind.","zh":"公平社會會幫助有被拋離風險的人。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"at the same time","meaning":"與此同時","examples":[{"en":"At the same time, promotion criteria should be transparent.","zh":"與此同時，晉升準則應透明。"},{"en":"At the same time means while another thing is also true or happening.","zh":"與此同時意思是另一件事也同樣成立或正在發生。"},{"en":"Hong Kong should welcome talent; at the same time, it should protect local workers.","zh":"香港應歡迎人才；與此同時，也應保護本地工作者。"},{"en":"This phrase helps writers balance two ideas.","zh":"這個短語幫助作者平衡兩個想法。"},{"en":"At the same time, growth and fairness must be considered together.","zh":"與此同時，增長和公平必須一起考慮。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"promotion criteria","meaning":"晉升準則","examples":[{"en":"Promotion criteria should be transparent.","zh":"晉升準則應透明。"},{"en":"Promotion criteria are the standards used to decide who moves to a higher position.","zh":"晉升準則是用來決定誰升上更高職位的標準。"},{"en":"Promotion criteria may include skills, results, leadership, and responsibility.","zh":"晉升準則可能包括技能、成果、領導能力和責任。"},{"en":"Clear criteria prevent workers from thinking promotion depends on nationality or favouritism.","zh":"清晰準則防止工作者以為晉升取決於國籍或偏袒。"},{"en":"Local staff trust the system more when promotion criteria are open.","zh":"當晉升準則公開，本地員工會更信任制度。"}],"source":"2019 Q2.pdf","sourcePage":14},{"front":"transparent","meaning":"透明","examples":[{"en":"Promotion criteria should be transparent.","zh":"晉升準則應透明。"},{"en":"Transparent means clear, open, and easy to understand.","zh":"透明意思是清晰、公開和容易理解。"},{"en":"A transparent hiring process tells candidates how decisions are made.","zh":"透明的招聘程序會告訴候選人決定如何作出。"},{"en":"Transparent rules reduce suspicion because people know the standard.","zh":"透明規則能減少猜疑，因為人們知道標準。"},{"en":"Talent policy must be transparent if it wants public trust.","zh":"人才政策若想得到公眾信任，就必須透明。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"pay should reflect responsibility","meaning":"薪酬應反映責任","examples":[{"en":"Pay should reflect responsibility rather than nationality.","zh":"薪酬應反映責任，而不是國籍。"},{"en":"Pay should reflect responsibility means salary should match the difficulty and importance of the job.","zh":"薪酬應反映責任，意思是薪金應配合工作的難度和重要性。"},{"en":"A team leader should earn more because they carry more responsibility.","zh":"團隊主管應賺取較高薪酬，因為他承擔更多責任。"},{"en":"If pay reflects nationality instead of responsibility, workers will see the system as unfair.","zh":"如果薪酬反映國籍而不是責任，工作者會視制度為不公平。"},{"en":"Fair pay helps both local and overseas employees feel respected.","zh":"公平薪酬幫助本地和海外僱員都感到被尊重。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"rather than nationality","meaning":"而不是國籍","examples":[{"en":"Pay should reflect responsibility rather than nationality.","zh":"薪酬應反映責任，而不是國籍。"},{"en":"Rather than nationality means instead of judging people by the country or place they belong to.","zh":"而不是國籍意思是不按人所屬的國家或地方來判斷。"},{"en":"Hiring should depend on ability rather than nationality.","zh":"招聘應取決於能力，而不是國籍。"},{"en":"Promotion should be based on contribution rather than nationality.","zh":"晉升應基於貢獻，而不是國籍。"},{"en":"This phrase stresses fairness across different backgrounds.","zh":"這個短語強調跨背景的公平。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"close its door to","meaning":"對……關上大門","examples":[{"en":"Hong Kong should not close its door to international talent.","zh":"香港不應對國際人才關上大門。"},{"en":"To close its door to someone means to refuse to welcome or accept them.","zh":"對某人關上大門意思是拒絕歡迎或接納他們。"},{"en":"A university closes its door to exchange if it rejects all overseas students.","zh":"如果大學拒絕所有海外學生，就是對交流關上大門。"},{"en":"Closing the door to talent can make a city less competitive.","zh":"對人才關上大門可能令城市競爭力下降。"},{"en":"Hong Kong should not close its door, but it should open it fairly.","zh":"香港不應關上大門，但應公平地開門。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"doing so","meaning":"這樣做","examples":[{"en":"Doing so would be shortsighted for Hong Kong.","zh":"這樣做對香港來說會是目光短淺的。"},{"en":"Doing so means taking the action just mentioned.","zh":"這樣做意思是採取剛才提到的行動。"},{"en":"If a school stops all internships, doing so may hurt students’ future careers.","zh":"如果學校停止所有實習機會，這樣做可能傷害學生未來事業。"},{"en":"In this passage, doing so refers to closing the door to international talent.","zh":"在這篇文章中，這樣做指對國際人才關上大門。"},{"en":"This phrase avoids repeating the whole previous action.","zh":"這個短語避免重複整個先前行動。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"shortsighted","meaning":"目光短淺","examples":[{"en":"Closing the door to international talent would be shortsighted.","zh":"對國際人才關上大門會是目光短淺的。"},{"en":"Shortsighted means focusing on immediate comfort while ignoring long-term results.","zh":"目光短淺意思是只看即時舒適，而忽略長遠結果。"},{"en":"A company is shortsighted if it refuses training because it wants to save money today.","zh":"如果公司因今天想省錢而拒絕培訓，就是目光短淺。"},{"en":"Rejecting all overseas talent may protect comfort now but harm future growth.","zh":"拒絕所有海外人才可能現在保護舒適感，但傷害未來增長。"},{"en":"A smart city avoids shortsighted decisions by planning for long-term needs.","zh":"聰明城市會透過長遠規劃避免目光短淺的決定。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"survived by connecting with","meaning":"靠連繫……而生存","examples":[{"en":"Hong Kong has always survived by connecting with the world.","zh":"香港一直靠與世界連繫而生存。"},{"en":"To survive by connecting with something means to continue successfully because of that connection.","zh":"靠連繫某事而生存，意思是因這種連繫而成功延續。"},{"en":"A small business may survive by connecting with loyal customers online.","zh":"小企業可能靠在網上連繫忠實顧客而生存。"},{"en":"Hong Kong survived by connecting with trade, finance, and global movement.","zh":"香港靠連繫貿易、金融和全球流動而生存。"},{"en":"Connection has long been part of Hong Kong’s strength.","zh":"連繫一直是香港力量的一部分。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"connecting with the world","meaning":"與世界連繫","examples":[{"en":"Hong Kong has always survived by connecting with the world.","zh":"香港一直靠與世界連繫而生存。"},{"en":"Connecting with the world means building links with people, markets, and ideas outside one’s own place.","zh":"與世界連繫意思是與本地以外的人、市場和想法建立連接。"},{"en":"A school connects with the world when students join international exchanges.","zh":"學生參加國際交流時，學校就是與世界連繫。"},{"en":"Connecting with the world helps a city learn and compete.","zh":"與世界連繫幫助城市學習和競爭。"},{"en":"Hong Kong’s future depends on connecting with the world while caring for locals.","zh":"香港的未來取決於與世界連繫，同時照顧本地人。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"not the same as","meaning":"與……並不相同","examples":[{"en":"Opening the door is not the same as allowing locals to be pushed aside.","zh":"敞開大門與容許本地人被擠到一旁並不相同。"},{"en":"Not the same as means two things should not be confused.","zh":"與……並不相同意思是兩件事不應被混淆。"},{"en":"Being quiet is not the same as being weak.","zh":"安靜與軟弱並不相同。"},{"en":"Welcoming talent is not the same as ignoring local workers.","zh":"歡迎人才與忽視本地工作者並不相同。"},{"en":"This phrase helps writers make an important distinction.","zh":"這個短語幫助作者作出重要區分。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"pushed into the corridor","meaning":"被擠到走廊上","examples":[{"en":"Locals should not be pushed into the corridor when the door is opened.","zh":"當大門打開時，本地人不應被擠到走廊上。"},{"en":"Pushed into the corridor is a metaphor meaning moved outside the main room or opportunity.","zh":"被擠到走廊上是一個比喻，意思是被移出主要空間或機會之外。"},{"en":"If a company hires experts but gives locals no voice, locals may feel pushed into the corridor.","zh":"如果公司聘請專家卻不給本地人發聲機會，本地人可能覺得被擠到走廊上。"},{"en":"The image shows exclusion even while the door appears open.","zh":"這個意象顯示即使大門看似打開，人仍可能被排除。"},{"en":"A fair policy opens the door without pushing anyone into the corridor.","zh":"公平政策會敞開大門，而不把任何人擠到走廊上。"}],"source":"2019 Q2.pdf","sourcePage":15},{"front":"a balanced policy","meaning":"平衡的政策","examples":[{"en":"The best policy is a balanced one.","zh":"最好的政策是平衡的政策。"},{"en":"A balanced policy considers more than one need or interest fairly.","zh":"平衡的政策會公平考慮多於一種需要或利益。"},{"en":"A balanced talent policy welcomes overseas experts and trains local workers.","zh":"平衡的人才政策會歡迎海外專家，也會培訓本地工作者。"},{"en":"Balance matters because extreme policies often create new problems.","zh":"平衡很重要，因為極端政策常會製造新問題。"},{"en":"A balanced policy can protect fairness while supporting growth.","zh":"平衡的政策可以在支持增長時保護公平。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"bring in talent","meaning":"引入人才","examples":[{"en":"Hong Kong should bring in talent where it genuinely needs it.","zh":"香港應在真正需要的地方引入人才。"},{"en":"To bring in talent means to attract or hire skilled people from outside.","zh":"引入人才意思是吸引或聘請外來有技能人士。"},{"en":"A hospital may bring in talent when it lacks specialist doctors.","zh":"醫院缺乏專科醫生時，可能引入人才。"},{"en":"Bringing in talent is useful if the city truly lacks certain skills.","zh":"如果城市真正缺乏某些技能，引入人才是有用的。"},{"en":"Talent should be brought in with training plans for local workers.","zh":"引入人才時應配合本地工作者的培訓計劃。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"genuinely needs it","meaning":"真正需要","examples":[{"en":"Hong Kong should bring in talent where it genuinely needs it.","zh":"香港應在真正需要的地方引入人才。"},{"en":"Genuinely needs it means truly requires it, not merely wants it for convenience.","zh":"真正需要意思是真實地需要，而不只是為了方便而想要。"},{"en":"A company genuinely needs an overseas expert if no local worker has the required skill yet.","zh":"如果沒有本地工作者具備所需技能，公司就真正需要海外專家。"},{"en":"Hiring should be based on real skill gaps, not habit or prestige.","zh":"招聘應基於真正技能缺口，而不是習慣或名聲。"},{"en":"This phrase helps prevent unnecessary or unfair recruitment.","zh":"這個短語幫助防止不必要或不公平的招聘。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"require knowledge to be shared","meaning":"要求知識被分享","examples":[{"en":"Policy should require knowledge to be shared.","zh":"政策應要求知識被分享。"},{"en":"To require knowledge to be shared means to make skill transfer a clear expectation.","zh":"要求知識被分享，意思是把技能轉移定為清晰期望。"},{"en":"A company may require overseas experts to run training sessions for local staff.","zh":"公司可能要求海外專家為本地員工舉辦培訓課程。"},{"en":"Shared knowledge prevents talent attraction from helping only one project.","zh":"共享知識防止人才吸引只幫助一個項目。"},{"en":"Policies should require knowledge sharing so local capacity grows.","zh":"政策應要求知識分享，讓本地能力成長。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"invest seriously in","meaning":"認真投資於……","examples":[{"en":"Hong Kong should invest seriously in local training.","zh":"香港應認真投資於本地培訓。"},{"en":"To invest seriously in something means to put real money, time, and effort into it.","zh":"認真投資於某事，意思是真正投入金錢、時間和努力。"},{"en":"A school invests seriously in language learning when it hires teachers and builds practice programmes.","zh":"學校聘請教師並建立練習計劃，就是認真投資於語言學習。"},{"en":"Hong Kong cannot protect local workers without serious investment in training.","zh":"香港若沒有認真投資於培訓，就不能保護本地工作者。"},{"en":"Serious investment shows that local development is not just a slogan.","zh":"認真投資顯示本地發展不只是口號。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"keep opportunity fair","meaning":"保持機會公平","examples":[{"en":"Hong Kong should keep opportunity fair from hiring to promotion.","zh":"香港應由招聘到晉升都保持機會公平。"},{"en":"To keep opportunity fair means to make sure chances are open and just for all qualified people.","zh":"保持機會公平意思是確保所有合資格人士都有公開和公正的機會。"},{"en":"A company keeps opportunity fair when it explains hiring and promotion rules clearly.","zh":"公司清楚解釋招聘和晉升規則時，就是保持機會公平。"},{"en":"Fair opportunity prevents both locals and newcomers from feeling unfairly judged.","zh":"公平機會防止本地人和新來者覺得被不公平判斷。"},{"en":"Talent policy succeeds when it keeps opportunity fair at every stage.","zh":"當人才政策在每個階段保持機會公平，它就會成功。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"from hiring to promotion","meaning":"由招聘到晉升","examples":[{"en":"Opportunity should be fair from hiring to promotion.","zh":"機會應由招聘到晉升都公平。"},{"en":"From hiring to promotion means across the whole work journey, from getting a job to moving upward.","zh":"由招聘到晉升意思是涵蓋整個工作歷程，從得到工作到向上發展。"},{"en":"Rules should be clear from hiring to promotion so workers know how to grow.","zh":"規則由招聘到晉升都應清晰，讓工作者知道如何成長。"},{"en":"Fairness at hiring is not enough if promotion later becomes unfair.","zh":"招聘時公平並不足夠，如果之後晉升變得不公平。"},{"en":"This phrase shows that fairness must continue over time.","zh":"這個短語顯示公平必須持續一段時間。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"become a threat to","meaning":"成為對……的威脅","examples":[{"en":"International talent should not become a threat to the local community.","zh":"國際人才不應成為對本地社群的威脅。"},{"en":"To become a threat to something means to start causing danger, fear, or harm to it.","zh":"成為對某事的威脅，意思是開始對它造成危險、恐懼或傷害。"},{"en":"New technology becomes a threat to workers if no re-training is provided.","zh":"如果沒有再培訓，新科技可能成為對工作者的威脅。"},{"en":"Overseas talent may seem threatening if local people see no benefit.","zh":"如果本地人看不到好處，海外人才可能看似具威脅性。"},{"en":"Fair policy can prevent international talent from becoming a threat to locals.","zh":"公平政策可以防止國際人才成為對本地人的威脅。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"the local community","meaning":"本地社群","examples":[{"en":"International talent should benefit the local community.","zh":"國際人才應使本地社群受益。"},{"en":"The local community means the people who live and work in a particular place.","zh":"本地社群是指在某個地方生活和工作的人。"},{"en":"Training programmes can help the local community gain from overseas expertise.","zh":"培訓計劃可以幫助本地社群從海外專業知識中得益。"},{"en":"Policies lose support if the local community feels ignored.","zh":"如果本地社群感到被忽視，政策會失去支持。"},{"en":"A successful city connects global talent with the needs of the local community.","zh":"成功城市會把全球人才與本地社群的需要連接起來。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"a catalyst for","meaning":"……的催化劑","examples":[{"en":"International talent can become a catalyst for a more capable city.","zh":"國際人才可以成為建設更有能力城市的催化劑。"},{"en":"A catalyst for something is a person, event, or force that helps change happen faster.","zh":"……的催化劑是幫助改變更快發生的人、事件或力量。"},{"en":"A good teacher can be a catalyst for a student’s confidence.","zh":"好老師可以成為學生自信的催化劑。"},{"en":"Overseas talent becomes a catalyst when it helps local workers learn and improve.","zh":"當海外人才幫助本地工作者學習和改善時，它就成為催化劑。"},{"en":"A catalyst creates progress without replacing the whole system.","zh":"催化劑能創造進步，而不是取代整個系統。"}],"source":"2019 Q2.pdf","sourcePage":16},{"front":"more capable","meaning":"更有能力的","examples":[{"en":"Hong Kong can become a more capable city.","zh":"香港可以成為更有能力的城市。"},{"en":"More capable means better able to do difficult tasks or meet challenges.","zh":"更有能力的意思是更能完成困難任務或面對挑戰。"},{"en":"A more capable workforce can handle new technology and global competition.","zh":"更有能力的勞動力可以處理新科技和全球競爭。"},{"en":"Training and international cooperation can make a city more capable.","zh":"培訓和國際合作可以令城市更有能力。"},{"en":"A more capable city should also be fairer and more confident.","zh":"更有能力的城市也應更公平和更自信。"}],"source":"2019 Q2.pdf","sourcePage":17},{"front":"confident and outward-looking","meaning":"自信而具國際視野","examples":[{"en":"Hong Kong can become more capable, confident, and outward-looking.","zh":"香港可以變得更有能力、自信而具國際視野。"},{"en":"Confident and outward-looking means sure of oneself while staying open to the wider world.","zh":"自信而具國際視野意思是對自己有信心，同時保持對更廣闊世界開放。"},{"en":"A confident and outward-looking city welcomes new ideas without losing its identity.","zh":"自信而具國際視野的城市會歡迎新想法，而不失去自身身份。"},{"en":"Hong Kong becomes outward-looking when it connects local strengths with global opportunities.","zh":"當香港把本地優勢與全球機會連接起來，它就變得具國際視野。"},{"en":"The goal is not only growth, but a confident and outward-looking society.","zh":"目標不只是增長，而是一個自信而具國際視野的社會。"}],"source":"2019 Q2.pdf","sourcePage":17},{"front":"outward-looking city","meaning":"面向世界的城市","examples":[{"en":"International talent can help Hong Kong become an outward-looking city.","zh":"國際人才可以幫助香港成為面向世界的城市。"},{"en":"An outward-looking city is open to the world and willing to learn from other places.","zh":"面向世界的城市是對世界開放，並願意向其他地方學習的城市。"},{"en":"An outward-looking city welcomes trade, talent, students, and cultural exchange.","zh":"面向世界的城市歡迎貿易、人才、學生和文化交流。"},{"en":"It does not close itself off because global connection brings opportunity.","zh":"它不會自我封閉，因為全球連繫帶來機會。"},{"en":"Hong Kong can be an outward-looking city while still protecting local people.","zh":"香港可以成為面向世界的城市，同時仍保護本地人。"}],"source":"2019 Q2.pdf","sourcePage":17}],"dse/writing/part-b/2019/Q3":[{"front":"a public forum","meaning":"公共論壇","examples":[{"en":"A noisy square is not the same as a public forum.","zh":"嘈雜的廣場不等同於公共論壇。"},{"en":"A public forum is a place or space where people can discuss public issues openly and seriously.","zh":"公共論壇是人們可以公開而認真地討論公共議題的地方或空間。"},{"en":"A school hall can become a public forum if students, teachers, and parents discuss rules there.","zh":"如果學生、老師和家長在禮堂討論校規，學校禮堂可以成為公共論壇。"},{"en":"A public forum needs listening and order, not just many people speaking at once.","zh":"公共論壇需要聆聽和秩序，而不只是很多人同時說話。"},{"en":"Without respect and clear rules, a public forum can quickly become noise rather than debate.","zh":"如果沒有尊重和清晰規則，公共論壇很快會變成噪音，而不是辯論。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Social media was once celebrated as a democratic tool.","zh":"社交媒體曾被讚揚為民主工具。"},{"en":"Social media refers to online platforms where people post, share, comment, and communicate.","zh":"social media 是指人們發布、分享、評論和交流的網上平台。"},{"en":"Students may use social media to discuss school events or share study reminders.","zh":"學生可以使用社交媒體討論學校活動或分享溫習提醒。"},{"en":"Social media can spread useful information quickly, but it can also spread anger and rumours.","zh":"社交媒體可以迅速傳播有用資訊，但也可以傳播憤怒和謠言。"},{"en":"This phrase is important because much modern public debate now happens online.","zh":"這個詞很重要，因為許多現代公共辯論現在都在網上發生。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"was first celebrated","meaning":"最初受到讚揚時","examples":[{"en":"When social media was first celebrated, it seemed to offer a democratic miracle.","zh":"當社交媒體最初受到讚揚時，它似乎帶來一個民主奇蹟。"},{"en":"Was first celebrated means was praised or welcomed strongly at the beginning.","zh":"was first celebrated 的意思是在一開始受到高度讚賞或歡迎。"},{"en":"When online learning was first celebrated, many people thought it would solve every education problem.","zh":"當網上學習最初受到讚揚時，許多人以為它會解決所有教育問題。"},{"en":"Something may be first celebrated before people notice its hidden risks.","zh":"某事可能先受到讚揚，然後人們才注意到其隱藏風險。"},{"en":"This phrase helps compare early excitement with later criticism.","zh":"這個短語幫助比較早期興奮與後來批評。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"democratic miracle","meaning":"民主奇蹟","examples":[{"en":"Social media seemed to offer a democratic miracle.","zh":"社交媒體似乎帶來一個民主奇蹟。"},{"en":"A democratic miracle is an almost unbelievable improvement that appears to give ordinary people more public voice.","zh":"democratic miracle 是一種幾乎令人難以置信的改善，似乎讓普通人有更多公共發聲機會。"},{"en":"Free online discussion once looked like a democratic miracle because anyone could speak.","zh":"免費網上討論曾看似民主奇蹟，因為任何人都可以發聲。"},{"en":"A democratic miracle may disappoint people if power later returns to platform owners or algorithms.","zh":"如果權力後來又回到平台擁有人或演算法手中，民主奇蹟可能令人失望。"},{"en":"This phrase shows hope that public participation can suddenly become wider and fairer.","zh":"這個短語展示一種希望：公共參與可以突然變得更廣泛和公平。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"a public square in every pocket","meaning":"每個人口袋裏的公共廣場","examples":[{"en":"Social media seemed to offer a public square in every pocket.","zh":"社交媒體似乎讓每個人口袋裏都有一個公共廣場。"},{"en":"A public square in every pocket means everyone with a phone seems to have access to public discussion.","zh":"a public square in every pocket 的意思是每個有手機的人似乎都能參與公共討論。"},{"en":"A teenager with a mobile phone may feel she has a public square in every pocket when she can post opinions instantly.","zh":"當青少年能即時發表意見時，她可能覺得自己口袋裏有一個公共廣場。"},{"en":"This idea sounds powerful because public speech no longer needs a newspaper or television studio.","zh":"這個想法聽起來很有力量，因為公共發言不再需要報章或電視台。"},{"en":"However, a public square in every pocket still needs responsibility, evidence, and listening.","zh":"然而，每個人口袋裏的公共廣場仍然需要責任、證據和聆聽。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"school rules","meaning":"校規","examples":[{"en":"Students can discuss school rules online.","zh":"學生可以在網上討論校規。"},{"en":"School rules are instructions that tell students what behaviour is allowed or not allowed at school.","zh":"校規是告訴學生在學校甚麼行為可以或不可以的指引。"},{"en":"School rules may cover uniforms, phones, homework, attendance, and classroom behaviour.","zh":"校規可能涵蓋校服、手機、功課、出席率和課堂行為。"},{"en":"Students discuss school rules more fairly when they explain how the rules affect daily life.","zh":"當學生解釋校規如何影響日常生活時，他們會更公平地討論校規。"},{"en":"Good school rules protect learning without treating students unfairly.","zh":"好的校規保護學習，同時不會不公平地對待學生。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"government policy","meaning":"政府政策","examples":[{"en":"Citizens can comment on government policy through social media.","zh":"市民可以透過社交媒體評論政府政策。"},{"en":"Government policy is a plan or rule made by the government to deal with public issues.","zh":"政府政策是政府為處理公共議題而制定的計劃或規則。"},{"en":"Government policy may involve housing, transport, education, healthcare, or the environment.","zh":"政府政策可能涉及房屋、交通、教育、醫療或環境。"},{"en":"People should understand the facts before criticising government policy online.","zh":"人們在網上批評政府政策前，應先了解事實。"},{"en":"Debate about government policy works best when citizens discuss costs, benefits, and consequences.","zh":"關於政府政策的辯論，在市民討論成本、好處和後果時最有效。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"comment on","meaning":"評論……","examples":[{"en":"Citizens often comment on government policy online.","zh":"市民常在網上評論政府政策。"},{"en":"To comment on something means to give an opinion or reaction about it.","zh":"comment on something 的意思是對某事給予意見或反應。"},{"en":"Students may comment on a new homework rule during a class meeting.","zh":"學生可以在班會上評論新的功課規則。"},{"en":"People should comment on serious issues with evidence, not only anger.","zh":"人們評論嚴肅議題時，應使用證據，而不只是憤怒。"},{"en":"This phrase is useful when describing public reaction to news, rules, or decisions.","zh":"當描述公眾對新聞、規則或決定的反應時，這個短語很有用。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"be heard","meaning":"被聽見","examples":[{"en":"Anyone could speak, respond and be heard.","zh":"任何人都可以發言、回應並被聽見。"},{"en":"To be heard means to have other people listen to and notice your voice or opinion.","zh":"be heard 的意思是讓別人聆聽並注意你的聲音或意見。"},{"en":"A quiet student may feel heard when the teacher seriously considers her suggestion.","zh":"當老師認真考慮安靜學生的建議時，她可能會覺得自己被聽見。"},{"en":"People want to be heard because ignored opinions can turn into frustration.","zh":"人們希望被聽見，因為被忽略的意見可能變成挫折感。"},{"en":"Being heard is not the same as winning; it means being treated as worth listening to.","zh":"被聽見不等於勝出；它是指被視為值得聆聽。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"ordinary users","meaning":"普通用戶","examples":[{"en":"Ordinary users help shape public conversation online.","zh":"普通用戶幫助塑造網上公共討論。"},{"en":"Ordinary users are normal people who use a platform, not celebrities, officials, or owners.","zh":"ordinary users 是使用平台的普通人，而不是名人、官員或擁有人。"},{"en":"Ordinary users can share local problems that newspapers may not report.","zh":"普通用戶可以分享報章未必報道的本地問題。"},{"en":"When many ordinary users repeat the same concern, public attention may grow.","zh":"當許多普通用戶重複同一個關注時，公眾注意可能增加。"},{"en":"This phrase shows that online discussion is not controlled only by powerful people.","zh":"這個短語顯示網上討論不只由有權力的人控制。"}],"source":"2019 Q3.pdf","sourcePage":1},{"front":"platform owners","meaning":"平台擁有人","examples":[{"en":"Platform owners influence how public debate takes place.","zh":"平台擁有人影響公共辯論如何發生。"},{"en":"Platform owners are the people or companies that control online platforms and their rules.","zh":"platform owners 是控制網上平台及其規則的人或公司。"},{"en":"Platform owners can decide what content is promoted, removed, or recommended.","zh":"平台擁有人可以決定甚麼內容被推廣、移除或推薦。"},{"en":"If platform owners reward anger, users may learn to argue more aggressively.","zh":"如果平台擁有人獎勵憤怒，用戶可能會學會更具攻擊性地爭論。"},{"en":"This phrase reminds us that online spaces are not completely neutral.","zh":"這個短語提醒我們，網上空間並非完全中立。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"reconsider whether","meaning":"重新考慮是否","examples":[{"en":"People must reconsider whether social media should shape public conversation so freely.","zh":"人們必須重新考慮社交媒體是否應如此自由地塑造公共討論。"},{"en":"To reconsider whether means to think again about whether something is right, useful, or safe.","zh":"reconsider whether 的意思是重新思考某事是否正確、有用或安全。"},{"en":"Schools may reconsider whether phones should be allowed during lessons.","zh":"學校可能重新考慮上課時是否應允許使用手機。"},{"en":"People reconsider whether a rule works when its harmful effects become clear.","zh":"當一條規則的有害影響變得清楚時，人們會重新考慮它是否有效。"},{"en":"This phrase is useful when a familiar idea needs fresh judgement.","zh":"當熟悉的想法需要新的判斷時，這個短語很有用。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"shape public conversation","meaning":"塑造公共討論","examples":[{"en":"Social media platforms can shape public conversation.","zh":"社交媒體平台可以塑造公共討論。"},{"en":"To shape public conversation means to influence what people discuss and how they discuss it.","zh":"shape public conversation 的意思是影響人們討論甚麼以及如何討論。"},{"en":"News apps can shape public conversation by choosing which stories appear first.","zh":"新聞應用程式可以透過選擇哪些新聞先出現來塑造公共討論。"},{"en":"If platforms promote extreme posts, they may shape public conversation in a harmful way.","zh":"如果平台推廣極端帖文，它們可能以有害方式塑造公共討論。"},{"en":"This phrase shows that communication tools can guide public attention and behaviour.","zh":"這個短語顯示溝通工具可以引導公眾注意和行為。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"so freely","meaning":"如此自由地","examples":[{"en":"These platforms should not shape public conversation so freely.","zh":"這些平台不應如此自由地塑造公共討論。"},{"en":"So freely means with very few limits, controls, or responsibilities.","zh":"so freely 的意思是幾乎沒有太多限制、控制或責任。"},{"en":"Students should not share classmates’ photos so freely without asking permission.","zh":"學生不應在未經同意下如此自由地分享同學相片。"},{"en":"When information spreads so freely, false claims can travel before facts are checked.","zh":"當資訊如此自由地傳播，虛假說法可能在事實被核實前已經流傳。"},{"en":"This phrase often suggests that too much freedom without responsibility can cause harm.","zh":"這個短語常暗示沒有責任的過度自由可能造成傷害。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"in order to protect","meaning":"為了保護","examples":[{"en":"Platforms may need rules in order to protect rational discussion.","zh":"平台可能需要規則，為了保護理性討論。"},{"en":"In order to protect means for the purpose of keeping something safe from harm.","zh":"in order to protect 的意思是為了使某事物免受傷害。"},{"en":"Schools create exam rules in order to protect fairness.","zh":"學校制定考試規則，是為了保護公平。"},{"en":"Websites may remove threats in order to protect users from fear and abuse.","zh":"網站可能移除威脅，是為了保護用戶免受恐懼和辱罵。"},{"en":"This phrase clearly explains the reason behind an action or rule.","zh":"這個短語清楚解釋行動或規則背後的原因。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"rational discussion","meaning":"理性討論","examples":[{"en":"Public debate needs rational discussion.","zh":"公共辯論需要理性討論。"},{"en":"Rational discussion is conversation based on reason, evidence, and careful thinking.","zh":"rational discussion 是建基於理由、證據和細心思考的對話。"},{"en":"A class can have rational discussion when students explain why they support or oppose a rule.","zh":"當學生解釋自己為何支持或反對一條規則時，班上可以有理性討論。"},{"en":"Rational discussion becomes difficult when people only insult each other.","zh":"當人們只互相侮辱時，理性討論會變得困難。"},{"en":"This phrase describes debate that tries to understand truth, not just win attention.","zh":"這個短語描述試圖理解真相，而不只是爭取注意的辯論。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"mutual understanding","meaning":"相互理解","examples":[{"en":"Healthy public debate should promote mutual understanding.","zh":"健康的公共辯論應促進相互理解。"},{"en":"Mutual understanding means both sides try to understand each other’s reasons and concerns.","zh":"mutual understanding 的意思是雙方嘗試理解彼此的理由和關注。"},{"en":"Parents and teenagers need mutual understanding when they discuss phone use at home.","zh":"父母和青少年在家討論手機使用時，需要相互理解。"},{"en":"Mutual understanding can reduce conflict because people feel less ignored.","zh":"相互理解可以減少衝突，因為人們較不覺得被忽略。"},{"en":"This phrase does not mean everyone agrees; it means people listen seriously.","zh":"這個短語不代表人人同意；它代表人們認真聆聽。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"civic trust","meaning":"公民信任；社會信任","examples":[{"en":"Social media can damage civic trust.","zh":"社交媒體可以破壞公民信任。"},{"en":"Civic trust is the belief that citizens, institutions, and public systems can act fairly and responsibly.","zh":"civic trust 是相信市民、機構和公共制度能公平而負責地行事。"},{"en":"Civic trust grows when people believe elections, schools, courts, and news sources are honest.","zh":"當人們相信選舉、學校、法院和新聞來源誠實時，公民信任會增長。"},{"en":"False information can damage civic trust by making people doubt everyone and everything.","zh":"虛假資訊會令人懷疑所有人和所有事，從而破壞公民信任。"},{"en":"A society with weak civic trust finds it harder to solve public problems together.","zh":"公民信任薄弱的社會，較難共同解決公共問題。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, social media stifles public debate.","zh":"就我而言，社交媒體扼殺公眾辯論。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"as far as I am concerned 的意思是在我看來或從我的角度而言。"},{"en":"As far as I am concerned, students should learn digital citizenship before using public platforms.","zh":"就我而言，學生應在使用公共平台前學習數碼公民意識。"},{"en":"This phrase is useful when stating a clear personal position in an essay.","zh":"這個短語在文章中表達清晰個人立場時很有用。"},{"en":"It signals that the writer is about to give a judgement.","zh":"它表示作者即將提出判斷。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"platforms such as","meaning":"例如……的平台","examples":[{"en":"Platforms such as Facebook and Twitter shape public conversation.","zh":"Facebook 和 Twitter 等平台塑造公共討論。"},{"en":"Platforms such as means online services of the same kind as the examples given.","zh":"platforms such as 的意思是與所舉例子同類的網上服務。"},{"en":"Platforms such as Instagram and YouTube can influence what young people watch.","zh":"Instagram 和 YouTube 等平台可以影響年輕人觀看甚麼。"},{"en":"This phrase helps give examples without listing every possible platform.","zh":"這個短語幫助給出例子，而不需要列出所有可能的平台。"},{"en":"Use it when you want readers to understand the category through familiar names.","zh":"當你想讀者透過熟悉名稱理解類別時，可以使用它。"}],"source":"2019 Q3.pdf","sourcePage":2},{"front":"do far more to…than to…","meaning":"更大程度上……而不是……","examples":[{"en":"Social media platforms do far more to stifle public debate than to encourage it.","zh":"社交媒體平台更大程度上是扼殺公眾辯論，而不是鼓勵它。"},{"en":"Do far more to A than to B means one effect is much stronger than another.","zh":"do far more to A than to B 的意思是一種影響遠比另一種影響強。"},{"en":"Some school rules do far more to frighten students than to guide them.","zh":"有些校規更大程度上是嚇怕學生，而不是引導他們。"},{"en":"This structure helps compare two possible effects clearly.","zh":"這個結構幫助清楚比較兩種可能影響。"},{"en":"It is useful when arguing that something mainly causes harm instead of benefit.","zh":"當論證某事主要造成傷害而非好處時，它很有用。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"stifle public debate","meaning":"扼殺公眾辯論","examples":[{"en":"Social media platforms often stifle public debate.","zh":"社交媒體平台常扼殺公眾辯論。"},{"en":"To stifle public debate means to weaken, limit, or silence serious discussion about public issues.","zh":"stifle public debate 的意思是削弱、限制或壓制對公共議題的嚴肅討論。"},{"en":"Personal attacks can stifle public debate because reasonable people stop joining in.","zh":"人身攻擊會扼殺公眾辯論，因為理性的人會停止參與。"},{"en":"Debate is stifled when people fear being mocked more than they value speaking honestly.","zh":"當人們害怕被嘲笑多於重視坦誠發言時，辯論就被扼殺。"},{"en":"This phrase describes a situation where discussion exists but becomes less free or meaningful.","zh":"這個短語描述討論雖然存在，但變得較不自由或較無意義的情況。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"encourage public debate","meaning":"鼓勵公眾辯論","examples":[{"en":"Social media does not always encourage public debate.","zh":"社交媒體並不總是鼓勵公眾辯論。"},{"en":"To encourage public debate means to help people discuss public issues openly and thoughtfully.","zh":"encourage public debate 的意思是幫助人們公開而有思考地討論公共議題。"},{"en":"A town hall meeting can encourage public debate by letting residents ask questions.","zh":"市政廳會議讓居民提問，可以鼓勵公眾辯論。"},{"en":"Platforms encourage public debate when they promote evidence and respectful disagreement.","zh":"當平台推廣證據和尊重的分歧時，它們就是鼓勵公眾辯論。"},{"en":"This phrase describes conditions that make citizens more willing to discuss shared problems.","zh":"這個短語描述令市民更願意討論共同問題的條件。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"reward emotional performance","meaning":"獎勵情緒化表演","examples":[{"en":"Platforms reward emotional performance over reasoned analysis.","zh":"平台獎勵情緒化表演，而不是有理據的分析。"},{"en":"To reward emotional performance means to give more attention to dramatic feelings than careful thinking.","zh":"reward emotional performance 的意思是給戲劇化情緒比細心思考更多注意。"},{"en":"A post full of anger may be rewarded with more likes than a calm explanation.","zh":"一篇充滿憤怒的帖文，可能比冷靜解釋得到更多讚好。"},{"en":"When platforms reward emotional performance, users learn to sound outraged instead of thoughtful.","zh":"當平台獎勵情緒化表演時，用戶會學會表現憤怒，而不是深思熟慮。"},{"en":"This phrase shows how online systems can shape people’s behaviour.","zh":"這個短語展示網上系統如何塑造人的行為。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"over reasoned analysis","meaning":"而不是有理據的分析","examples":[{"en":"Social media rewards emotional performance over reasoned analysis.","zh":"社交媒體獎勵情緒化表演，而不是有理據的分析。"},{"en":"Over reasoned analysis means instead of, or more than, careful argument based on reasons.","zh":"over reasoned analysis 的意思是取代或多於建基於理由的細心分析。"},{"en":"A debate becomes weak when people choose jokes over reasoned analysis.","zh":"當人們選擇笑話而不是有理據的分析時，辯論會變得薄弱。"},{"en":"If anger is valued over reasoned analysis, truth becomes harder to find.","zh":"如果憤怒比有理據的分析更受重視，真相會更難找到。"},{"en":"This phrase shows that one kind of response is being preferred unfairly.","zh":"這個短語顯示某種反應被不公平地優先看待。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"trap people in echo chambers","meaning":"把人困在同溫層中","examples":[{"en":"Social media can trap people in echo chambers.","zh":"社交媒體可以把人困在同溫層中。"},{"en":"To trap people in echo chambers means to keep them surrounded by opinions similar to their own.","zh":"trap people in echo chambers 的意思是令他們一直被相似意見包圍。"},{"en":"A student may be trapped in an echo chamber if every video tells her the same political view is correct.","zh":"如果每段影片都告訴學生同一個政治觀點是正確的，她可能被困在同溫層中。"},{"en":"Echo chambers can make disagreement feel shocking or threatening.","zh":"同溫層會令分歧顯得震驚或具威脅性。"},{"en":"This phrase warns that online comfort can weaken real understanding.","zh":"這個短語提醒人們，網上的舒適感可以削弱真正理解。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"echo chambers","meaning":"同溫層；回音室效應","examples":[{"en":"Echo chambers weaken public debate.","zh":"同溫層削弱公共辯論。"},{"en":"Echo chambers are situations where people mostly hear opinions that repeat and confirm their own views.","zh":"echo chambers 是人們主要聽到重複並確認自己觀點的意見的情況。"},{"en":"In an echo chamber, users may think everyone sensible agrees with them.","zh":"在同溫層中，用戶可能以為所有理性的人都同意自己。"},{"en":"Echo chambers make public debate weaker because people stop testing their beliefs.","zh":"同溫層令公共辯論變弱，因為人們停止檢視自己的信念。"},{"en":"This phrase describes a closed information environment, not a real discussion space.","zh":"這個短語描述封閉的資訊環境，而不是真正的討論空間。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"despite apparent openness","meaning":"儘管表面開放","examples":[{"en":"Despite apparent openness, social media can silence reasonable voices.","zh":"儘管表面開放，社交媒體可以令理性的聲音沉默。"},{"en":"Despite apparent openness means although something looks open and free on the surface.","zh":"despite apparent openness 的意思是雖然某事表面上看起來開放和自由。"},{"en":"Despite apparent openness, a class discussion may silence shy students if loud voices dominate.","zh":"儘管表面開放，如果大聲的人主導討論，班上討論仍可能令害羞學生沉默。"},{"en":"This phrase helps show contrast between appearance and reality.","zh":"這個短語幫助展示表象與現實之間的對比。"},{"en":"It warns that a space can look free while still discouraging careful speech.","zh":"它提醒人們，一個空間可以看似自由，卻仍令人不敢細心發言。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"apparent openness","meaning":"表面上的開放","examples":[{"en":"The apparent openness of social media can be misleading.","zh":"社交媒體表面上的開放可能具有誤導性。"},{"en":"Apparent openness means the surface appearance of being free, welcoming, and easy to join.","zh":"apparent openness 是表面上看來自由、歡迎參與和容易加入。"},{"en":"A meeting may have apparent openness if everyone may speak, but only popular opinions are accepted.","zh":"如果每個人都可以發言，但只有受歡迎意見被接受，會議可能只有表面上的開放。"},{"en":"Apparent openness can hide pressure, fear, or unequal power.","zh":"表面上的開放可以隱藏壓力、恐懼或不平等權力。"},{"en":"This phrase asks readers to look beyond what a system seems to offer.","zh":"這個短語要求讀者看清一個制度表面提供的東西之外。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"frighten voices into silence","meaning":"嚇得……不敢發聲","examples":[{"en":"Online attacks can frighten reasonable voices into silence.","zh":"網上攻擊可以嚇得理性的聲音不敢發聲。"},{"en":"To frighten voices into silence means to scare people so much that they stop speaking.","zh":"frighten voices into silence 的意思是把人嚇到停止發言。"},{"en":"Cruel comments may frighten young writers into silence before they share more work.","zh":"殘酷評論可能嚇得年輕作者在分享更多作品前不敢發聲。"},{"en":"When people are frightened into silence, public debate loses careful and moderate views.","zh":"當人們被嚇得沉默，公共辯論會失去細心和溫和的看法。"},{"en":"This phrase shows how fear can control speech without an official ban.","zh":"這個短語展示恐懼如何在沒有官方禁令下控制言論。"}],"source":"2019 Q3.pdf","sourcePage":3},{"front":"reasonable voices","meaning":"理性的聲音","examples":[{"en":"Many reasonable voices stay silent online.","zh":"許多理性的聲音在網上保持沉默。"},{"en":"Reasonable voices are people who speak calmly, fairly, and with evidence.","zh":"reasonable voices 是冷靜、公平並以證據發言的人。"},{"en":"Reasonable voices can help a debate avoid insults and simple slogans.","zh":"理性的聲音可以幫助辯論避免侮辱和簡單口號。"},{"en":"If reasonable voices leave the discussion, extreme opinions may seem more common than they are.","zh":"如果理性的聲音離開討論，極端意見可能看起來比實際更常見。"},{"en":"This phrase describes the kind of speakers a healthy public forum needs.","zh":"這個短語描述健康公共論壇所需要的發言者。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"rewards speed, anger and simplicity","meaning":"獎勵速度、憤怒和簡化","examples":[{"en":"Social media rewards speed, anger and simplicity.","zh":"社交媒體獎勵速度、憤怒和簡化。"},{"en":"Rewards speed, anger and simplicity means gives more attention to quick, emotional, and simple posts.","zh":"rewards speed, anger and simplicity 的意思是給快速、情緒化和簡單化的帖文更多注意。"},{"en":"A short angry comment may spread faster than a careful explanation of the facts.","zh":"一句簡短憤怒評論，可能比細心解釋事實傳播得更快。"},{"en":"When speed, anger and simplicity are rewarded, users may stop thinking before posting.","zh":"當速度、憤怒和簡化受到獎勵，用戶可能停止在發布前思考。"},{"en":"This phrase criticises systems that value reaction more than understanding.","zh":"這個短語批評重視反應多於理解的系統。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"careful thought","meaning":"細心思考","examples":[{"en":"Public debate requires careful thought.","zh":"公共辯論需要細心思考。"},{"en":"Careful thought means slow, serious thinking that considers facts, reasons, and consequences.","zh":"careful thought 是緩慢而認真的思考，會考慮事實、理由和後果。"},{"en":"Students need careful thought before deciding whether a rule is fair.","zh":"學生在決定一條規則是否公平前，需要細心思考。"},{"en":"Without careful thought, complicated issues can be reduced to simple blame.","zh":"沒有細心思考，複雜議題可以被簡化成單純責怪。"},{"en":"This phrase shows that good judgement takes more than quick reaction.","zh":"這個短語顯示良好判斷需要的不只是快速反應。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"a transport fare rise","meaning":"交通票價上升","examples":[{"en":"A transport fare rise involves many competing concerns.","zh":"交通票價上升涉及許多互相競爭的考慮。"},{"en":"A transport fare rise is an increase in the price people pay to use buses, trains, or other public transport.","zh":"a transport fare rise 是人們乘坐巴士、火車或其他公共交通時要支付的價格上升。"},{"en":"A transport fare rise may worry students and workers who travel every day.","zh":"交通票價上升可能令每天出行的學生和工人擔心。"},{"en":"Fare rises may help transport companies cover costs, but they increase passengers’ burdens.","zh":"票價上升可能幫助運輸公司應付成本，但會增加乘客負擔。"},{"en":"This phrase describes a public issue with both financial and social effects.","zh":"這個短語描述一個同時有財務和社會影響的公共議題。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"for example","meaning":"例如","examples":[{"en":"A transport fare rise, for example, involves costs and public burdens.","zh":"例如，交通票價上升涉及成本和公眾負擔。"},{"en":"For example is used to introduce a specific case that explains a general point.","zh":"for example 用來介紹一個解釋一般觀點的具體例子。"},{"en":"Public services, for example, often involve both money and fairness.","zh":"例如，公共服務常涉及金錢和公平。"},{"en":"This phrase helps readers understand an abstract idea through a concrete situation.","zh":"這個短語幫助讀者透過具體情況理解抽象想法。"},{"en":"It is useful when an argument needs evidence or illustration.","zh":"當論點需要證據或說明時，它很有用。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"company costs","meaning":"公司成本","examples":[{"en":"A transport fare rise involves company costs.","zh":"交通票價上升涉及公司成本。"},{"en":"Company costs are the money a business must spend to operate, pay workers, and maintain services.","zh":"company costs 是企業營運、支付工資和維持服務所必須花費的金錢。"},{"en":"A bus company’s costs may include fuel, repairs, wages, and station fees.","zh":"巴士公司的成本可能包括燃油、維修、工資和車站費用。"},{"en":"If company costs rise, a business may increase prices to survive.","zh":"如果公司成本上升，企業可能加價以維持經營。"},{"en":"This phrase helps explain why a decision may look reasonable from a business point of view.","zh":"這個短語幫助解釋為何某個決定從商業角度看似合理。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"workers’ wages","meaning":"工人工資","examples":[{"en":"Workers’ wages are part of the transport-fare debate.","zh":"工人工資是交通票價辯論的一部分。"},{"en":"Workers’ wages are the money paid to employees for their labour.","zh":"workers’ wages 是支付給僱員勞動的金錢。"},{"en":"Drivers, cleaners, and station staff all depend on workers’ wages to support their families.","zh":"司機、清潔工和車站職員都依靠工人工資養家。"},{"en":"If wages are too low, public services may lose experienced workers.","zh":"如果工資太低，公共服務可能失去有經驗的工人。"},{"en":"This phrase reminds readers that price debates also involve people’s livelihoods.","zh":"這個短語提醒讀者，價格辯論也涉及人們的生計。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"passengers’ burdens","meaning":"乘客負擔","examples":[{"en":"A fare rise increases passengers’ burdens.","zh":"票價上升增加乘客負擔。"},{"en":"Passengers’ burdens are the costs, pressures, or difficulties faced by people who use transport.","zh":"passengers’ burdens 是使用交通工具的人面對的成本、壓力或困難。"},{"en":"Students may feel passengers’ burdens when bus fares rise but pocket money stays the same.","zh":"當巴士車費上升但零用錢不變時，學生可能感受到乘客負擔。"},{"en":"Higher fares can increase passengers’ burdens, especially for low-income families.","zh":"較高票價會增加乘客負擔，尤其是低收入家庭。"},{"en":"This phrase focuses on how policy affects ordinary users.","zh":"這個短語聚焦政策如何影響普通用戶。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"long-term planning","meaning":"長遠規劃","examples":[{"en":"Transport policy requires long-term planning.","zh":"交通政策需要長遠規劃。"},{"en":"Long-term planning means making decisions by considering future needs, not only immediate problems.","zh":"long-term planning 的意思是考慮未來需要來作決定，而不只是處理眼前問題。"},{"en":"A city needs long-term planning for railways, housing, and population growth.","zh":"城市在鐵路、房屋和人口增長方面需要長遠規劃。"},{"en":"Without long-term planning, today’s cheap solution may create tomorrow’s serious problem.","zh":"沒有長遠規劃，今天便宜的解決方法可能造成明天的嚴重問題。"},{"en":"This phrase is useful for issues that develop over many years.","zh":"這個短語適用於多年發展的議題。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"such an issue","meaning":"這類議題","examples":[{"en":"Such an issue is often simplified online.","zh":"這類議題在網上常被簡化。"},{"en":"Such an issue means this kind of problem or topic just mentioned.","zh":"such an issue 的意思是剛才提到的這種問題或話題。"},{"en":"Such an issue may involve money, fairness, safety, and public feeling at the same time.","zh":"這類議題可能同時涉及金錢、公平、安全和公眾感受。"},{"en":"When such an issue is discussed too quickly, important details may be lost.","zh":"當這類議題被太快討論時，重要細節可能會流失。"},{"en":"This phrase helps refer back to a complex topic without repeating its full name.","zh":"這個短語幫助回指複雜話題，而不用重複完整名稱。"}],"source":"2019 Q3.pdf","sourcePage":4},{"front":"be squeezed into","meaning":"被壓縮成","examples":[{"en":"A complex issue is often squeezed into a slogan or meme.","zh":"複雜議題常被壓縮成口號或網絡迷因。"},{"en":"To be squeezed into something means to be forced into a space or form that is too small or simple.","zh":"be squeezed into something 的意思是被迫放進過小或過於簡單的空間或形式中。"},{"en":"A serious school problem may be squeezed into one angry sentence online.","zh":"嚴肅的校園問題可能在網上被壓縮成一句憤怒說話。"},{"en":"When an issue is squeezed into a meme, its causes and consequences may disappear.","zh":"當議題被壓縮成網絡迷因時，其原因和後果可能消失。"},{"en":"This phrase criticises oversimplification.","zh":"這個短語批評過度簡化。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"a slogan","meaning":"口號","examples":[{"en":"A complex issue may be reduced to a slogan.","zh":"複雜議題可能被簡化成口號。"},{"en":"A slogan is a short, memorable phrase used to express an idea or campaign.","zh":"slogan 是用來表達想法或活動的簡短易記短語。"},{"en":"A slogan can help people remember a message, but it may hide difficult details.","zh":"口號可以幫助人們記住訊息，但也可能掩蓋困難細節。"},{"en":"Public debate becomes weaker when every policy is judged by a slogan.","zh":"當每項政策都由口號判斷時，公共辯論會變弱。"},{"en":"This phrase often appears when discussing politics, advertising, or protests.","zh":"這個詞常出現在政治、廣告或抗議討論中。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"a meme","meaning":"網絡迷因","examples":[{"en":"An issue may be squeezed into a meme.","zh":"一個議題可能被壓縮成網絡迷因。"},{"en":"A meme is an online image, joke, or short idea that spreads quickly between users.","zh":"meme 是在用戶之間快速傳播的網上圖片、笑話或簡短想法。"},{"en":"A meme can make a serious topic easier to share but harder to understand fully.","zh":"網絡迷因可以令嚴肅話題更容易分享，但更難全面理解。"},{"en":"When people learn about policy only through memes, they may miss important context.","zh":"當人們只透過網絡迷因了解政策時，他們可能錯過重要背景。"},{"en":"This phrase shows how online humour can shape public opinion.","zh":"這個詞展示網上幽默如何塑造公眾意見。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"a sarcastic comment","meaning":"諷刺評論","examples":[{"en":"A serious issue may be reduced to a sarcastic comment.","zh":"嚴肅議題可能被簡化成諷刺評論。"},{"en":"A sarcastic comment is a remark that uses mockery or irony to criticise something.","zh":"sarcastic comment 是用嘲諷或反語來批評某事的評論。"},{"en":"A sarcastic comment may get laughs but fail to explain the real problem.","zh":"諷刺評論可能令人發笑，但未能解釋真正問題。"},{"en":"Online debates become shallow when sarcastic comments replace evidence.","zh":"當諷刺評論取代證據時，網上辯論會變得膚淺。"},{"en":"This phrase shows how humour can become dismissive or hurtful.","zh":"這個短語展示幽默如何變得輕蔑或傷人。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"the more…the more…","meaning":"越……越……","examples":[{"en":"The more extreme the wording is, the more likely it is to attract likes.","zh":"措辭越極端，就越有可能吸引讚好。"},{"en":"The more…the more… shows that one thing increases as another thing increases.","zh":"the more…the more… 表示一件事增加時，另一件事也增加。"},{"en":"The more carefully students read, the more clearly they understand the argument.","zh":"學生讀得越仔細，就越清楚理解論點。"},{"en":"The more angry a post sounds, the more quickly it may spread online.","zh":"帖文聽起來越憤怒，就可能越快在網上傳播。"},{"en":"This structure is useful for showing a direct relationship between two changes.","zh":"這個結構很適合展示兩個變化之間的直接關係。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"extreme wording","meaning":"極端措辭","examples":[{"en":"Extreme wording is more likely to attract attention online.","zh":"極端措辭更有可能在網上吸引注意。"},{"en":"Extreme wording means language that is very strong, emotional, or exaggerated.","zh":"extreme wording 是非常強烈、情緒化或誇張的語言。"},{"en":"Calling every disagreement “dangerous” is an example of extreme wording.","zh":"把每個分歧都稱為「危險」，就是極端措辭的例子。"},{"en":"Extreme wording can attract attention but also make reasonable discussion harder.","zh":"極端措辭可以吸引注意，但也會令理性討論更困難。"},{"en":"This phrase warns that powerful words can distort complex issues.","zh":"這個短語提醒人們，有力的文字可以扭曲複雜議題。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"be likely to","meaning":"很可能","examples":[{"en":"Extreme wording is likely to attract likes.","zh":"極端措辭很可能吸引讚好。"},{"en":"Be likely to means something will probably happen.","zh":"be likely to 的意思是某事很可能會發生。"},{"en":"A short angry video is likely to spread faster than a long explanation.","zh":"一段簡短憤怒影片很可能比長篇解釋傳播得更快。"},{"en":"Students are likely to learn better when examples are clear and concrete.","zh":"當例子清晰而具體時，學生很可能學得更好。"},{"en":"This phrase helps writers discuss probability without saying something is certain.","zh":"這個短語幫助作者討論可能性，而不是說某事必然發生。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"attract likes","meaning":"吸引讚好","examples":[{"en":"Extreme wording often attracts likes.","zh":"極端措辭常吸引讚好。"},{"en":"To attract likes means to receive approval clicks from people on social media.","zh":"attract likes 的意思是在社交媒體上得到別人的讚好點擊。"},{"en":"A funny or angry post may attract likes because people react quickly.","zh":"有趣或憤怒的帖文可能吸引讚好，因為人們反應很快。"},{"en":"Posts that attract likes are not always accurate or useful.","zh":"吸引讚好的帖文不一定準確或有用。"},{"en":"This phrase shows how online approval can influence what people write.","zh":"這個短語展示網上認同如何影響人們寫甚麼。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"balanced explanation","meaning":"平衡的解釋","examples":[{"en":"A balanced explanation is often ignored online.","zh":"平衡的解釋在網上常被忽略。"},{"en":"A balanced explanation considers different sides of an issue fairly.","zh":"balanced explanation 會公平地考慮一個議題的不同方面。"},{"en":"A balanced explanation of a fare rise discusses both company costs and passengers’ burdens.","zh":"關於票價上升的平衡解釋，會同時討論公司成本和乘客負擔。"},{"en":"Balanced explanations may seem less exciting than angry posts, but they help people understand more deeply.","zh":"平衡的解釋可能不如憤怒帖文刺激，但能幫助人們理解得更深入。"},{"en":"This phrase describes careful reasoning that avoids simple blame.","zh":"這個短語描述避免簡單責怪的細心理據。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"be ignored","meaning":"被忽略","examples":[{"en":"A balanced explanation is more likely to be ignored.","zh":"平衡的解釋更有可能被忽略。"},{"en":"To be ignored means to receive little or no attention.","zh":"be ignored 的意思是幾乎沒有或完全沒有得到注意。"},{"en":"A calm comment may be ignored if louder users dominate the discussion.","zh":"如果更大聲的用戶主導討論，冷靜評論可能被忽略。"},{"en":"Important warnings can be ignored when people only want simple answers.","zh":"當人們只想要簡單答案時，重要警告可能被忽略。"},{"en":"This phrase shows that being correct does not always mean being noticed.","zh":"這個短語顯示正確不一定代表會被注意。"}],"source":"2019 Q3.pdf","sourcePage":5},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, the platform trains users to perform for attention.","zh":"換言之，平台訓練用戶為吸引注意而表演。"},{"en":"In other words means the same idea is being explained again more clearly or simply.","zh":"in other words 的意思是用更清楚或更簡單的方式重新解釋同一想法。"},{"en":"The rule is too confusing; in other words, students do not know what is allowed.","zh":"這條規則太混亂；換言之，學生不知道甚麼是被允許的。"},{"en":"This phrase helps writers restate a point after giving details.","zh":"這個短語幫助作者在給出細節後重新表述重點。"},{"en":"It is useful when you want to make sure readers understand the main meaning.","zh":"當你想確保讀者明白主要意思時，它很有用。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"not merely host debate","meaning":"不只是承載辯論","examples":[{"en":"The platform does not merely host debate.","zh":"平台不只是承載辯論。"},{"en":"Not merely host debate means not only provide a space for discussion, but also influence how it happens.","zh":"not merely host debate 的意思是不只提供討論空間，也影響討論如何發生。"},{"en":"A classroom does not merely host debate if the teacher chooses which voices are heard.","zh":"如果老師選擇哪些聲音被聽見，課室就不只是承載辯論。"},{"en":"Platforms do not merely host debate when their systems promote some posts over others.","zh":"當平台系統推廣某些帖文多於其他帖文時，它們就不只是承載辯論。"},{"en":"This phrase shows that a space can shape behaviour, not just contain it.","zh":"這個短語顯示空間可以塑造行為，而不只是容納行為。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"train users to","meaning":"訓練用戶去……","examples":[{"en":"The platform trains users to perform for attention.","zh":"平台訓練用戶為吸引注意而表演。"},{"en":"To train users to do something means to encourage repeated behaviour until people learn it as a habit.","zh":"train users to do something 的意思是鼓勵重複行為，直到人們把它學成習慣。"},{"en":"A platform may train users to post quickly by rewarding immediate reactions.","zh":"平台可能透過獎勵即時反應，訓練用戶快速發帖。"},{"en":"Schools train students to think carefully when they require evidence in answers.","zh":"當學校要求答案有證據時，就是訓練學生細心思考。"},{"en":"This phrase shows how systems teach behaviour even without direct lessons.","zh":"這個短語展示制度即使沒有直接教學，也會教人行為。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"perform for attention","meaning":"為吸引注意而表演","examples":[{"en":"Users learn to perform for attention.","zh":"用戶學會為吸引注意而表演。"},{"en":"To perform for attention means to act or speak in a dramatic way mainly to be noticed.","zh":"perform for attention 的意思是主要為了被注意而以戲劇化方式行動或說話。"},{"en":"A student may perform for attention by making extreme jokes in a class group chat.","zh":"學生可能在班群組裏開極端玩笑，為吸引注意而表演。"},{"en":"People perform for attention when likes become more important than honesty.","zh":"當讚好比誠實更重要時，人們就會為吸引注意而表演。"},{"en":"This phrase criticises speech that is designed for reaction rather than understanding.","zh":"這個短語批評為反應而不是理解而設計的言論。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"before long","meaning":"不久之後","examples":[{"en":"Before long, people learn a damaging style of argument.","zh":"不久之後，人們學會一種有害的爭論方式。"},{"en":"Before long means after a short time or soon.","zh":"before long 的意思是不久後或短時間之後。"},{"en":"Before long, a calm discussion can become a fight if insults are rewarded.","zh":"如果侮辱受到獎勵，冷靜討論不久之後可能變成爭吵。"},{"en":"This phrase shows that a change happens gradually but quite quickly.","zh":"這個短語顯示改變是逐漸但相當快速地發生。"},{"en":"It is useful when describing the result of repeated behaviour.","zh":"當描述重複行為的結果時，它很有用。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"winning an argument","meaning":"贏得爭論","examples":[{"en":"People may think that winning an argument means humiliating opponents.","zh":"人們可能以為贏得爭論就是羞辱對手。"},{"en":"Winning an argument means persuading others or showing that your point is stronger.","zh":"winning an argument 的意思是說服別人，或顯示自己的觀點更有力。"},{"en":"In healthy debate, winning an argument should depend on evidence, not insults.","zh":"在健康辯論中，贏得爭論應取決於證據，而不是侮辱。"},{"en":"Some people confuse winning an argument with making the other person look stupid.","zh":"有些人把贏得爭論與令對方顯得愚蠢混淆。"},{"en":"This phrase helps discuss the purpose and standards of debate.","zh":"這個短語幫助討論辯論的目的和標準。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"sound confident","meaning":"聽起來有信心","examples":[{"en":"Online users are rewarded for sounding confident.","zh":"網上用戶因聽起來有信心而受到獎勵。"},{"en":"To sound confident means to speak as if you are sure of what you are saying.","zh":"sound confident 的意思是說話時好像很肯定自己所說的內容。"},{"en":"A person can sound confident online even when they have not checked the facts.","zh":"一個人即使沒有核實事實，也可以在網上聽起來有信心。"},{"en":"Sounding confident may attract attention, but it does not prove an argument is correct.","zh":"聽起來有信心可能吸引注意，但不證明論點正確。"},{"en":"This phrase shows the difference between style and truth.","zh":"這個短語展示風格與真相之間的差別。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"humiliate opponents","meaning":"羞辱對手","examples":[{"en":"Some users think debate means humiliating opponents.","zh":"有些用戶認為辯論就是羞辱對手。"},{"en":"To humiliate opponents means to make people on the other side feel ashamed or foolish.","zh":"humiliate opponents 的意思是令另一方的人感到羞恥或愚蠢。"},{"en":"A debater humiliates opponents when he mocks their appearance instead of answering their points.","zh":"當辯論者嘲笑對手外表而不是回應其觀點時，就是羞辱對手。"},{"en":"Humiliating opponents may win applause but destroys respect.","zh":"羞辱對手可能贏得掌聲，但會破壞尊重。"},{"en":"This phrase describes a harmful way of arguing.","zh":"這個短語描述一種有害的爭論方式。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"complexity is cut down","meaning":"複雜性被削減","examples":[{"en":"Complexity is cut down in online arguments.","zh":"在網上爭論中，複雜性被削減。"},{"en":"Complexity is cut down means difficult details are reduced or removed to make something simpler.","zh":"complexity is cut down 的意思是困難細節被減少或移除，以令某事更簡單。"},{"en":"When a housing debate becomes one slogan, complexity is cut down.","zh":"當房屋辯論變成一句口號時，複雜性就被削減。"},{"en":"Cutting down complexity may make a message easier to share but less accurate.","zh":"削減複雜性可能令訊息更容易分享，但也較不準確。"},{"en":"This phrase criticises the loss of depth in discussion.","zh":"這個短語批評討論中深度的流失。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"context is removed","meaning":"背景脈絡被刪去","examples":[{"en":"Context is often removed from online debate.","zh":"背景脈絡常從網上辯論中被刪去。"},{"en":"Context is removed means the background information needed to understand something is left out.","zh":"context is removed 的意思是理解某事所需的背景資料被省略。"},{"en":"A screenshot can mislead people if context is removed.","zh":"如果背景脈絡被刪去，截圖可能誤導人。"},{"en":"When context is removed, a careful statement may look cruel or foolish.","zh":"當背景脈絡被刪去，細心說法可能看起來殘酷或愚蠢。"},{"en":"This phrase warns that meaning depends on surrounding facts and circumstances.","zh":"這個短語提醒人們，意思取決於周圍事實和情況。"}],"source":"2019 Q3.pdf","sourcePage":6},{"front":"emotion rises","meaning":"情緒升溫","examples":[{"en":"Emotion rises when debate becomes performative.","zh":"當辯論變成表演時，情緒會升溫。"},{"en":"Emotion rises means feelings such as anger, fear, or excitement become stronger.","zh":"emotion rises 的意思是憤怒、恐懼或興奮等感受變得更強。"},{"en":"Emotion rises in a group chat when people reply before calming down.","zh":"當人們未冷靜就回覆時，群組聊天中的情緒會升溫。"},{"en":"When emotion rises too quickly, people may stop listening to evidence.","zh":"當情緒太快升溫，人們可能停止聆聽證據。"},{"en":"This phrase describes the emotional temperature of a discussion.","zh":"這個短語描述討論中的情緒溫度。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"become secondary to","meaning":"變得次於……","examples":[{"en":"Truth becomes secondary to popularity.","zh":"真相變得次於人氣。"},{"en":"To become secondary to something means to become less important than it.","zh":"become secondary to something 的意思是變得不如某事重要。"},{"en":"In a bad classroom discussion, learning may become secondary to showing off.","zh":"在不良課堂討論中，學習可能變得次於炫耀。"},{"en":"When truth becomes secondary to popularity, people choose what sounds good over what is accurate.","zh":"當真相變得次於人氣時，人們會選擇聽起來好的，而不是準確的。"},{"en":"This phrase shows that the wrong value has become more important.","zh":"這個短語顯示錯誤的價值變得更重要。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"popularity","meaning":"受歡迎程度；人氣","examples":[{"en":"Truth should not become secondary to popularity.","zh":"真相不應變得次於人氣。"},{"en":"Popularity is the state of being liked, followed, or supported by many people.","zh":"popularity 是被許多人喜歡、追隨或支持的狀態。"},{"en":"A post may gain popularity because it is funny, not because it is true.","zh":"一篇帖文可能因有趣而得到人氣，而不是因為真實。"},{"en":"Popularity can influence public debate when people trust widely shared opinions too quickly.","zh":"當人們太快相信被大量分享的意見時，人氣可以影響公共辯論。"},{"en":"This phrase reminds us that being popular and being correct are different things.","zh":"這個詞提醒我們，受歡迎和正確是不同的事。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, attention has become the prize.","zh":"簡單來說，注意力已成為獎賞。"},{"en":"Put simply means expressed in a clearer and easier way.","zh":"put simply 的意思是用更清楚和更簡單的方式表達。"},{"en":"Put simply, the rule failed because students did not understand it.","zh":"簡單來說，這條規則失敗是因為學生不理解它。"},{"en":"Writers use this phrase before summarising a complicated idea.","zh":"作者在總結複雜想法前會使用這個短語。"},{"en":"It helps readers focus on the main point after detailed explanation.","zh":"它幫助讀者在詳細解釋後集中於重點。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"attention becomes the prize","meaning":"注意力成為獎賞","examples":[{"en":"When attention becomes the prize, logic becomes the casualty.","zh":"當注意力成為獎賞時，邏輯就成為犧牲品。"},{"en":"Attention becomes the prize means being noticed becomes the main goal.","zh":"attention becomes the prize 的意思是被注意成為主要目標。"},{"en":"In a class discussion, attention becomes the prize if students speak only to make others laugh.","zh":"在課堂討論中，如果學生只為逗別人笑而發言，注意力就成為獎賞。"},{"en":"When attention becomes the prize online, accuracy may matter less than shock value.","zh":"當網上注意力成為獎賞時，準確性可能不如震撼效果重要。"},{"en":"This phrase criticises a culture where visibility is treated like success.","zh":"這個短語批評一種把可見度當成成功的文化。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"logic becomes the casualty","meaning":"邏輯成為犧牲品","examples":[{"en":"When attention becomes the prize, logic becomes the casualty.","zh":"當注意力成為獎賞時，邏輯就成為犧牲品。"},{"en":"Logic becomes the casualty means clear reasoning is harmed or lost.","zh":"logic becomes the casualty 的意思是清晰推理受到傷害或消失。"},{"en":"In an angry debate, logic becomes the casualty when people stop checking whether claims make sense.","zh":"在憤怒辯論中，當人們停止檢查說法是否合理時，邏輯就成為犧牲品。"},{"en":"Logic becomes the casualty if users choose dramatic stories over evidence.","zh":"如果用戶選擇戲劇化故事而不是證據，邏輯就會成為犧牲品。"},{"en":"This phrase shows that poor debate damages thinking itself.","zh":"這個短語顯示糟糕辯論會傷害思考本身。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, these platforms push people into echo chambers.","zh":"此外，這些平台把人推進同溫層中。"},{"en":"Moreover means in addition, and it introduces another important point.","zh":"moreover 的意思是此外，並用來引入另一個重要觀點。"},{"en":"The policy is expensive; moreover, it may not solve the real problem.","zh":"這項政策很昂貴；此外，它可能無法解決真正問題。"},{"en":"This phrase helps writers add a stronger or related argument.","zh":"這個短語幫助作者加入更有力或相關的論點。"},{"en":"It is useful when building an essay step by step.","zh":"當一步步建立文章時，它很有用。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"push people into","meaning":"把人推進……","examples":[{"en":"These platforms push people into echo chambers.","zh":"這些平台把人推進同溫層中。"},{"en":"To push people into something means to move or pressure them toward a situation, often without them noticing.","zh":"push people into something 的意思是把人推向某種情況，通常他們未必察覺。"},{"en":"Repeated recommendations can push users into watching only one kind of video.","zh":"重複推薦可以把用戶推向只觀看一類影片。"},{"en":"People may be pushed into extreme views when they rarely meet different opinions.","zh":"當人們很少接觸不同意見時，可能被推向極端觀點。"},{"en":"This phrase shows influence rather than physical force.","zh":"這個短語表示影響，而不是身體上的推動。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"thereby weakening","meaning":"從而削弱","examples":[{"en":"Echo chambers weaken the foundation of public debate.","zh":"同溫層削弱公眾辯論的基礎。"},{"en":"Thereby weakening means causing something to become weaker as a result.","zh":"thereby weakening 的意思是因此導致某事物變得較弱。"},{"en":"Rumours spread quickly, thereby weakening trust in official information.","zh":"謠言迅速傳播，從而削弱人們對官方資訊的信任。"},{"en":"If students stop listening to opposing views, they thereby weaken classroom debate.","zh":"如果學生停止聆聽相反意見，他們就從而削弱課堂辯論。"},{"en":"This phrase connects an action directly to its harmful result.","zh":"這個短語把行動直接連接到有害結果。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"the foundation of public debate","meaning":"公眾辯論的基礎","examples":[{"en":"Echo chambers weaken the foundation of public debate.","zh":"同溫層削弱公眾辯論的基礎。"},{"en":"The foundation of public debate means the basic conditions that make serious public discussion possible.","zh":"the foundation of public debate 的意思是令嚴肅公共討論成為可能的基本條件。"},{"en":"Evidence, trust, listening, and disagreement form the foundation of public debate.","zh":"證據、信任、聆聽和分歧構成公眾辯論的基礎。"},{"en":"If people refuse to hear other views, the foundation of public debate becomes weak.","zh":"如果人們拒絕聽其他觀點，公眾辯論的基礎就會變弱。"},{"en":"This phrase describes what debate depends on before opinions can be useful.","zh":"這個短語描述意見變得有用之前，辯論所依賴的東西。"}],"source":"2019 Q3.pdf","sourcePage":7},{"front":"genuine debate","meaning":"真正的辯論","examples":[{"en":"A genuine debate requires citizens to meet opposing views.","zh":"真正的辯論需要市民接觸相反意見。"},{"en":"Genuine debate is real discussion in which different sides test ideas honestly.","zh":"genuine debate 是不同方面誠實檢視想法的真正討論。"},{"en":"A genuine debate allows disagreement but also requires evidence and respect.","zh":"真正的辯論容許分歧，但也需要證據和尊重。"},{"en":"If everyone only repeats the same opinion, it is not a genuine debate.","zh":"如果人人只重複同一個意見，那就不是真正的辯論。"},{"en":"This phrase separates meaningful argument from noise or performance.","zh":"這個短語把有意義的爭論與噪音或表演分開。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"opposing views","meaning":"相反意見","examples":[{"en":"Citizens need to meet opposing views.","zh":"市民需要接觸相反意見。"},{"en":"Opposing views are opinions that disagree with or challenge one’s own opinion.","zh":"opposing views 是與自己看法不同或挑戰自己看法的意見。"},{"en":"Students meet opposing views when classmates argue for a different school policy.","zh":"當同學支持不同校園政策時，學生就會接觸相反意見。"},{"en":"Opposing views can feel uncomfortable, but they help people test their ideas.","zh":"相反意見可能令人不舒服，但能幫助人檢視自己的想法。"},{"en":"This phrase is important because debate cannot exist without disagreement.","zh":"這個短語很重要，因為沒有分歧就沒有辯論。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"test their assumptions","meaning":"檢視自己的假設","examples":[{"en":"People should test their assumptions during debate.","zh":"人們應在辯論中檢視自己的假設。"},{"en":"To test their assumptions means to examine whether their beliefs are actually true.","zh":"test their assumptions 的意思是檢查自己的信念是否真的正確。"},{"en":"A student may test her assumption that phones always distract students by looking at evidence.","zh":"學生可以透過查看證據，檢視自己「手機一定令學生分心」的假設。"},{"en":"Debate improves when people test their assumptions instead of defending them blindly.","zh":"當人們檢視自己的假設，而不是盲目捍衛它們時，辯論會改善。"},{"en":"This phrase shows intellectual honesty.","zh":"這個短語展示思想上的誠實。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"revise their opinions","meaning":"修正自己的看法","examples":[{"en":"Citizens should revise their opinions when evidence points elsewhere.","zh":"當證據指向其他結論時，市民應修正自己的看法。"},{"en":"To revise their opinions means to change or adjust their views after new information.","zh":"revise their opinions 的意思是在得到新資料後改變或調整自己的觀點。"},{"en":"A student may revise her opinion about a rule after hearing how it helps disabled classmates.","zh":"學生聽到某條規則如何幫助殘疾同學後，可能修正自己的看法。"},{"en":"People who revise their opinions are not weak; they are responding to evidence.","zh":"修正自己看法的人並不軟弱；他們是在回應證據。"},{"en":"This phrase shows that good debate can lead to learning.","zh":"這個短語顯示良好辯論可以帶來學習。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"evidence points elsewhere","meaning":"證據指向其他結論","examples":[{"en":"People should revise their views when evidence points elsewhere.","zh":"當證據指向其他結論時，人們應修正自己的看法。"},{"en":"Evidence points elsewhere means the facts support a different conclusion.","zh":"evidence points elsewhere 的意思是事實支持另一個不同結論。"},{"en":"A student may blame poor marks on luck, but evidence may point elsewhere if she rarely studies.","zh":"學生可能把低分歸咎於運氣，但如果她很少溫習，證據可能指向其他結論。"},{"en":"When evidence points elsewhere, honest people should change their minds.","zh":"當證據指向其他結論時，誠實的人應改變想法。"},{"en":"This phrase reminds us that facts should guide opinion.","zh":"這個短語提醒我們，事實應引導意見。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"do the opposite","meaning":"做相反的事","examples":[{"en":"Social media often does the opposite.","zh":"社交媒體常做相反的事。"},{"en":"To do the opposite means to act in a way that is completely different from what was expected or needed.","zh":"do the opposite 的意思是以完全不同於預期或需要的方式行事。"},{"en":"A rule meant to reduce stress may do the opposite if it creates more homework.","zh":"原本用來減輕壓力的規則，如果造成更多功課，可能會做相反的事。"},{"en":"Social media should expose users to different views, but it may do the opposite by filtering content.","zh":"社交媒體應讓用戶接觸不同觀點，但它可能透過篩選內容做相反的事。"},{"en":"This phrase is useful for showing contrast between purpose and result.","zh":"這個短語很適合展示目的與結果之間的對比。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"influencers","meaning":"網絡紅人；意見領袖","examples":[{"en":"Users follow friends, influencers and pages that reflect their tastes.","zh":"用戶追蹤朋友、網絡紅人和反映他們喜好的專頁。"},{"en":"Influencers are people who have online followers and can affect what others think, buy, or discuss.","zh":"influencers 是擁有網上追隨者，並能影響別人想法、購買或討論內容的人。"},{"en":"Influencers may shape young people’s views on fashion, study habits, or politics.","zh":"網絡紅人可能塑造年輕人對時尚、學習習慣或政治的看法。"},{"en":"When users trust influencers too easily, they may stop checking information for themselves.","zh":"當用戶太容易信任網絡紅人時，可能停止自行核實資訊。"},{"en":"This phrase describes online figures whose popularity gives them power.","zh":"這個詞描述因人氣而擁有影響力的網上人物。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"reflect their tastes","meaning":"反映他們的喜好","examples":[{"en":"Users follow pages that reflect their tastes.","zh":"用戶追蹤反映他們喜好的專頁。"},{"en":"To reflect their tastes means to match what they already like, prefer, or believe.","zh":"reflect their tastes 的意思是符合他們已經喜歡、偏好或相信的東西。"},{"en":"A student may follow film pages that reflect her tastes in comedy and romance.","zh":"學生可能追蹤反映她對喜劇和愛情片喜好的電影專頁。"},{"en":"When every page reflects users’ tastes, they may rarely meet unfamiliar ideas.","zh":"當每個專頁都反映用戶喜好時，他們可能很少接觸陌生想法。"},{"en":"This phrase shows how personal preference shapes online experience.","zh":"這個短語展示個人偏好如何塑造網上經驗。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"algorithms","meaning":"演算法","examples":[{"en":"Algorithms supply more of the same content.","zh":"演算法提供更多同類內容。"},{"en":"Algorithms are sets of instructions that decide what content users see online.","zh":"algorithms 是決定用戶在網上看到甚麼內容的一組指令。"},{"en":"A video app’s algorithms may recommend similar videos after one click.","zh":"影片應用程式的演算法可能在一次點擊後推薦相似影片。"},{"en":"Algorithms can make online life convenient, but they can also narrow what people see.","zh":"演算法可以令網上生活方便，但也可以收窄人們看到的內容。"},{"en":"This phrase is important because hidden systems often shape public attention.","zh":"這個詞很重要，因為隱藏系統常塑造公眾注意。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"supply more of the same","meaning":"提供更多同類內容","examples":[{"en":"Algorithms supply more of the same because agreement keeps people scrolling.","zh":"演算法提供更多同類內容，因為認同感令用戶不斷滑動瀏覽。"},{"en":"To supply more of the same means to keep giving similar content again and again.","zh":"supply more of the same 的意思是不斷提供相似內容。"},{"en":"If a user watches one angry video, the app may supply more of the same.","zh":"如果用戶觀看一段憤怒影片，應用程式可能提供更多同類內容。"},{"en":"Supplying more of the same can make people feel comfortable but less informed.","zh":"提供更多同類內容可以令人感到舒服，但也可能令資訊更狹窄。"},{"en":"This phrase describes repetition that narrows experience.","zh":"這個短語描述會收窄經驗的重複。"}],"source":"2019 Q3.pdf","sourcePage":8},{"front":"agreement keeps people scrolling","meaning":"認同感令用戶不斷滑動瀏覽","examples":[{"en":"Agreement keeps people scrolling online.","zh":"認同感令用戶在網上不斷滑動瀏覽。"},{"en":"Agreement keeps people scrolling means users continue looking when content confirms what they already believe.","zh":"agreement keeps people scrolling 的意思是當內容確認用戶已有信念時，他們會繼續觀看。"},{"en":"A student may keep scrolling when every post supports her complaint about school rules.","zh":"如果每篇帖文都支持學生對校規的不滿，她可能會不斷滑動瀏覽。"},{"en":"If agreement keeps people scrolling, platforms may show fewer challenging views.","zh":"如果認同感令用戶不斷滑動瀏覽，平台可能展示較少具挑戰性的觀點。"},{"en":"This phrase explains why comfort can become profitable online.","zh":"這個短語解釋為何舒適感可以在網上變得有利可圖。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"over time","meaning":"隨著時間過去","examples":[{"en":"Over time, each feed begins to look like common sense.","zh":"隨著時間過去，每個資訊流開始看起來像常識。"},{"en":"Over time means gradually as days, months, or years pass.","zh":"over time 的意思是隨着日子、月份或年份過去而逐漸發生。"},{"en":"Over time, small online habits can shape what people believe is normal.","zh":"隨著時間過去，小小的網上習慣可以塑造人們認為正常的事。"},{"en":"A student improves over time when she practises writing every week.","zh":"如果學生每星期練習寫作，她會隨著時間過去而進步。"},{"en":"This phrase is useful for changes that happen slowly rather than immediately.","zh":"這個短語適用於慢慢發生，而不是即時發生的改變。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"each feed","meaning":"每個資訊流","examples":[{"en":"Each feed begins to look like common sense.","zh":"每個資訊流開始看起來像常識。"},{"en":"Each feed means each user’s stream of posts, videos, and recommended content.","zh":"each feed 是指每位用戶的一連串帖文、影片和推薦內容。"},{"en":"Each feed may look different because users click, like, and follow different things.","zh":"每個資訊流可能不同，因為用戶點擊、讚好和追蹤的東西不同。"},{"en":"If each feed shows only similar views, people may forget others see a different world.","zh":"如果每個資訊流只展示相似觀點，人們可能忘記別人看到的是不同世界。"},{"en":"This phrase helps explain personalised online experience.","zh":"這個短語幫助解釋個人化的網上經驗。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"common sense","meaning":"常識","examples":[{"en":"Each feed begins to look like common sense.","zh":"每個資訊流開始看起來像常識。"},{"en":"Common sense means what seems obviously true or reasonable to ordinary people.","zh":"common sense 是普通人覺得明顯真實或合理的想法。"},{"en":"In an echo chamber, one opinion may feel like common sense because no one challenges it.","zh":"在同溫層中，一種意見可能感覺像常識，因為沒有人挑戰它。"},{"en":"Common sense can be useful, but it can also be shaped by limited experience.","zh":"常識可以有用，但也可以被有限經驗塑造。"},{"en":"This phrase shows how repeated messages can make an idea feel natural.","zh":"這個短語展示重複訊息如何令一個想法感覺自然。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"the other side","meaning":"另一方","examples":[{"en":"The other side may appear foolish, immoral or dangerous.","zh":"另一方可能顯得愚蠢、不道德或危險。"},{"en":"The other side means people who hold the opposite view in a debate.","zh":"the other side 是指在辯論中持相反觀點的人。"},{"en":"In a school debate, the other side may support stricter phone rules.","zh":"在校園辯論中，另一方可能支持更嚴格的手機規則。"},{"en":"Public debate becomes unhealthy when the other side is treated as an enemy.","zh":"當另一方被視為敵人時，公共辯論會變得不健康。"},{"en":"This phrase helps discuss disagreement without naming every individual.","zh":"這個短語幫助討論分歧，而不用逐一指名每個人。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"appear foolish","meaning":"顯得愚蠢","examples":[{"en":"The other side may appear foolish.","zh":"另一方可能顯得愚蠢。"},{"en":"To appear foolish means to seem silly, unreasonable, or lacking good judgement.","zh":"appear foolish 的意思是看起來傻、沒道理或缺乏良好判斷。"},{"en":"A person may appear foolish if their view is shown without the reasons behind it.","zh":"如果某人的觀點被展示時沒有背後理由，那人可能顯得愚蠢。"},{"en":"Online clips can make someone appear foolish by removing important context.","zh":"網上片段可以透過移除重要背景，令某人顯得愚蠢。"},{"en":"This phrase describes appearance, not necessarily the full truth.","zh":"這個短語描述外表，不一定代表完整真相。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"immoral or dangerous","meaning":"不道德或危險","examples":[{"en":"People with opposing views may appear immoral or dangerous.","zh":"持相反意見的人可能顯得不道德或危險。"},{"en":"Immoral or dangerous means wrong in values or likely to cause harm.","zh":"immoral or dangerous 的意思是在價值上錯誤，或可能造成傷害。"},{"en":"Online users may label opponents immoral or dangerous before understanding their reasons.","zh":"網上用戶可能在理解對方理由前，就把對手標籤為不道德或危險。"},{"en":"When disagreement is treated as immoral or dangerous, debate becomes fear and attack.","zh":"當分歧被視為不道德或危險時，辯論會變成恐懼和攻擊。"},{"en":"This phrase shows how people can turn political difference into moral judgement.","zh":"這個短語展示人們如何把政治差異變成道德判斷。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"environmental policy","meaning":"環境政策","examples":[{"en":"Environmental policy is often debated online.","zh":"環境政策常在網上被辯論。"},{"en":"Environmental policy refers to rules or plans about protecting air, water, land, animals, and climate.","zh":"environmental policy 是關於保護空氣、水、土地、動物和氣候的規則或計劃。"},{"en":"Environmental policy may include recycling rules, pollution limits, or energy targets.","zh":"環境政策可能包括回收規則、污染限制或能源目標。"},{"en":"Debate about environmental policy can become difficult because it affects jobs, costs, and health.","zh":"關於環境政策的辯論可能變得困難，因為它影響工作、成本和健康。"},{"en":"This phrase describes public decisions about how society treats the natural world.","zh":"這個短語描述社會如何對待自然世界的公共決定。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"posts insisting that","meaning":"堅稱……的帖文","examples":[{"en":"One user may see posts insisting that any new restriction is an attack on freedom.","zh":"一名用戶可能看到堅稱任何新限制都是對自由的攻擊的帖文。"},{"en":"Posts insisting that something is true are online messages that state a view strongly and repeatedly.","zh":"posts insisting that something is true 是強烈並重複表示某看法正確的網上訊息。"},{"en":"A user may see posts insisting that homework should be banned completely.","zh":"用戶可能看到堅稱功課應完全被禁止的帖文。"},{"en":"Such posts can shape opinion if they leave no room for doubt or evidence.","zh":"如果這類帖文不留懷疑或證據空間，就可能塑造意見。"},{"en":"This phrase often suggests forceful online claims.","zh":"這個短語常暗示強硬的網上說法。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"any new restriction","meaning":"任何新限制","examples":[{"en":"Some posts describe any new restriction as an attack on freedom.","zh":"有些帖文把任何新限制描述成對自由的攻擊。"},{"en":"Any new restriction means every new rule or limit, no matter how small or reasonable.","zh":"any new restriction 的意思是每一項新規則或限制，不論多小或多合理。"},{"en":"Some students may treat any new restriction on phones as unfair control.","zh":"有些學生可能把任何手機新限制都視為不公平控制。"},{"en":"Seeing any new restriction as bad can stop people from discussing its purpose.","zh":"把任何新限制都看成壞事，會阻止人們討論其目的。"},{"en":"This phrase shows a broad and sometimes extreme reaction to rules.","zh":"這個短語展示對規則的廣泛、有時極端的反應。"}],"source":"2019 Q3.pdf","sourcePage":9},{"front":"an attack on freedom","meaning":"對自由的攻擊","examples":[{"en":"Some users see new restrictions as an attack on freedom.","zh":"有些用戶把新限制視為對自由的攻擊。"},{"en":"An attack on freedom means something is seen as threatening people’s right to choose or act.","zh":"an attack on freedom 的意思是某事被看成威脅人們選擇或行動的權利。"},{"en":"A student may call a phone ban an attack on freedom if she feels adults do not trust her.","zh":"如果學生覺得成年人不信任她，她可能把手機禁令稱為對自由的攻擊。"},{"en":"This phrase can be powerful, but it may exaggerate ordinary rules.","zh":"這個短語可以很有力量，但也可能誇大普通規則。"},{"en":"It is often used in debates about rights, limits, and government power.","zh":"它常用於關於權利、限制和政府權力的辯論。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"posts claiming that","meaning":"聲稱……的帖文","examples":[{"en":"Another user may see posts claiming that any hesitation is selfish.","zh":"另一名用戶可能看到聲稱任何猶豫都是自私的帖文。"},{"en":"Posts claiming that something is true are online messages that assert a view, whether or not it is proven.","zh":"posts claiming that something is true 是聲稱某觀點正確的網上訊息，不論是否已被證明。"},{"en":"People may share posts claiming that one simple rule can solve every problem.","zh":"人們可能分享聲稱一條簡單規則可以解決所有問題的帖文。"},{"en":"Posts claiming strong conclusions should be checked carefully.","zh":"對於聲稱強烈結論的帖文，應仔細核實。"},{"en":"This phrase reminds readers that online claims are not always facts.","zh":"這個短語提醒讀者，網上聲稱不一定是事實。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"any hesitation","meaning":"任何猶豫","examples":[{"en":"Some posts suggest that any hesitation is selfish.","zh":"有些帖文暗示任何猶豫都是自私的。"},{"en":"Any hesitation means every pause, doubt, or delay before agreeing or acting.","zh":"any hesitation 是指在同意或行動前的每一種停頓、疑問或延遲。"},{"en":"A person may have hesitation about a new policy because they want to understand the costs.","zh":"一個人可能對新政策有所猶豫，因為他想了解成本。"},{"en":"Calling any hesitation selfish can silence people who have reasonable questions.","zh":"把任何猶豫都稱為自私，可以令有合理問題的人沉默。"},{"en":"This phrase shows an extreme demand for immediate agreement.","zh":"這個短語展示對立即同意的極端要求。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"selfish","meaning":"自私的","examples":[{"en":"One side may describe hesitation as selfish.","zh":"一方可能把猶豫描述為自私。"},{"en":"Selfish means caring mainly about yourself and not enough about other people.","zh":"selfish 的意思是主要只關心自己，而不夠關心別人。"},{"en":"It is selfish to spread false information just to gain attention.","zh":"只為吸引注意而散播虛假資訊是自私的。"},{"en":"Calling someone selfish without listening to their reasons can be unfair.","zh":"未聆聽別人的理由就稱對方自私，可能並不公平。"},{"en":"This word is strong because it judges a person’s moral character.","zh":"這個詞很強烈，因為它判斷一個人的道德品格。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"public opinion","meaning":"公眾意見","examples":[{"en":"Users may believe they are seeing public opinion.","zh":"用戶可能相信自己看到的是公眾意見。"},{"en":"Public opinion means the views held by many people in society about an issue.","zh":"public opinion 是社會中許多人對某議題持有的看法。"},{"en":"Public opinion on school rules may differ between students, parents, and teachers.","zh":"關於校規的公眾意見，在學生、家長和老師之間可能不同。"},{"en":"Online posts may not represent public opinion if they come from only one group.","zh":"如果網上帖文只來自一個群體，它們未必代表公眾意見。"},{"en":"This phrase is important when discussing democracy, media, and policy.","zh":"這個短語在討論民主、媒體和政策時很重要。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"when in fact","meaning":"但事實上","examples":[{"en":"They may believe they are seeing public opinion, when in fact they are seeing a filtered version.","zh":"他們可能相信自己看到的是公眾意見，但事實上看到的是經過篩選的版本。"},{"en":"When in fact introduces the truth that contrasts with what people believe.","zh":"when in fact 用來介紹與人們所相信的相反的真相。"},{"en":"A student may think everyone dislikes the rule, when in fact only her friends have complained.","zh":"學生可能以為人人都不喜歡這條規則，但事實上只有她的朋友投訴過。"},{"en":"This phrase is useful when correcting a mistaken impression.","zh":"當修正錯誤印象時，這個短語很有用。"},{"en":"It often reveals that appearance and reality are different.","zh":"它常揭示表象與現實不同。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"a filtered version of","meaning":"經過篩選的版本","examples":[{"en":"Users often see a filtered version of public opinion.","zh":"用戶常看到公眾意見經過篩選的版本。"},{"en":"A filtered version of something is a selected or limited form that does not show the whole picture.","zh":"a filtered version of something 是經選擇或有限制的形式，不能展示全貌。"},{"en":"A feed may show a filtered version of the news based on what users clicked before.","zh":"資訊流可能根據用戶之前點擊過的內容，展示新聞經過篩選的版本。"},{"en":"Seeing only a filtered version of public opinion can make people misunderstand society.","zh":"只看到公眾意見經過篩選的版本，可能令人誤解社會。"},{"en":"This phrase warns that online information may be incomplete.","zh":"這個短語提醒人們，網上資訊可能並不完整。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"the result is not…but…","meaning":"結果不是……而是……","examples":[{"en":"The result is not a shared forum but a collection of private mirrors.","zh":"結果不是共同論壇，而是一堆私人鏡子。"},{"en":"The result is not A but B means the outcome is different from what people expected.","zh":"the result is not A but B 的意思是結果與人們預期不同。"},{"en":"The result is not better learning but greater stress if students only memorise answers.","zh":"如果學生只背答案，結果不是更好的學習，而是更大壓力。"},{"en":"This structure helps contrast appearance with reality.","zh":"這個結構幫助對比表象與現實。"},{"en":"It is useful when showing that a system produces the opposite of its promise.","zh":"當展示一個制度產生與承諾相反的結果時，它很有用。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"a shared forum","meaning":"共同論壇","examples":[{"en":"Social media often fails to become a shared forum.","zh":"社交媒體常未能成為共同論壇。"},{"en":"A shared forum is a common discussion space where different people can meet and exchange views.","zh":"shared forum 是不同人可以相遇並交換看法的共同討論空間。"},{"en":"A school meeting can be a shared forum if all groups are invited to speak.","zh":"如果所有群體都被邀請發言，學校會議可以成為共同論壇。"},{"en":"A shared forum becomes weak when people only hear their own side.","zh":"當人們只聽到自己一方的意見，共同論壇就會變弱。"},{"en":"This phrase describes a public space based on common participation.","zh":"這個短語描述建基於共同參與的公共空間。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"a collection of private mirrors","meaning":"一堆私人鏡子","examples":[{"en":"The result is a collection of private mirrors.","zh":"結果是一堆私人鏡子。"},{"en":"A collection of private mirrors means many separate spaces where people mostly see their own views reflected back.","zh":"a collection of private mirrors 的意思是許多分開的空間，人們主要看見自己的觀點被反射回來。"},{"en":"If every feed confirms what users already believe, social media becomes a collection of private mirrors.","zh":"如果每個資訊流都確認用戶已有信念，社交媒體就變成一堆私人鏡子。"},{"en":"Private mirrors can comfort people but stop them from understanding others.","zh":"私人鏡子可以安慰人，但阻止他們理解別人。"},{"en":"This phrase is a metaphor for echo chambers and personalised reality.","zh":"這個短語是同溫層和個人化現實的比喻。"}],"source":"2019 Q3.pdf","sourcePage":10},{"front":"only when","meaning":"只有當……時","examples":[{"en":"Only when people are exposed to disagreement can they argue responsibly.","zh":"只有當人們接觸到分歧時，他們才能負責任地辯論。"},{"en":"Only when means something can happen only under a particular condition.","zh":"only when 的意思是只有在某個特定條件下，某事才會發生。"},{"en":"Only when students hear different views can they understand the full problem.","zh":"只有當學生聽到不同觀點時，他們才能理解完整問題。"},{"en":"This structure emphasises that one condition is necessary before another result is possible.","zh":"這個結構強調某個條件是另一個結果發生前所必需的。"},{"en":"It is useful for explaining what real debate requires.","zh":"它適合用來解釋真正辯論需要甚麼。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"be exposed to","meaning":"接觸到……","examples":[{"en":"People need to be exposed to serious disagreement.","zh":"人們需要接觸到嚴肅的分歧。"},{"en":"To be exposed to something means to experience it or come into contact with it.","zh":"be exposed to something 的意思是經歷或接觸某事物。"},{"en":"Students should be exposed to different arguments before writing an essay.","zh":"學生在寫文章前應接觸不同論點。"},{"en":"Being exposed to opposing views can be uncomfortable but useful.","zh":"接觸相反意見可能令人不舒服，但很有用。"},{"en":"This phrase shows that learning often begins by meeting something unfamiliar.","zh":"這個短語顯示學習常從遇到陌生事物開始。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"serious disagreement","meaning":"嚴肅的分歧","examples":[{"en":"Public debate requires serious disagreement.","zh":"公共辯論需要嚴肅的分歧。"},{"en":"Serious disagreement is a real and meaningful difference of opinion about an important issue.","zh":"serious disagreement 是關於重要議題的真實而有意義的意見差異。"},{"en":"A class has serious disagreement when students give different reasons about a school policy.","zh":"當學生就一項校園政策提出不同理由時，班上就有嚴肅的分歧。"},{"en":"Serious disagreement can improve thinking if people argue with evidence and respect.","zh":"如果人們以證據和尊重爭論，嚴肅的分歧可以改善思考。"},{"en":"This phrase separates meaningful conflict from shallow shouting.","zh":"這個短語把有意義的衝突與膚淺叫喊分開。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"argue responsibly","meaning":"負責任地辯論","examples":[{"en":"People must learn to argue responsibly.","zh":"人們必須學會負責任地辯論。"},{"en":"To argue responsibly means to disagree with evidence, fairness, and respect for others.","zh":"argue responsibly 的意思是以證據、公平和對他人的尊重來表達不同意見。"},{"en":"Students argue responsibly when they criticise an idea without insulting the person.","zh":"當學生批評想法而不侮辱提出想法的人時，就是負責任地辯論。"},{"en":"Online users argue responsibly by checking facts before sharing strong claims.","zh":"網上用戶在分享強烈說法前核實事實，就是負責任地辯論。"},{"en":"This phrase shows that disagreement should have ethical limits.","zh":"這個短語顯示分歧應有道德界限。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, social media can sometimes encourage debate.","zh":"誠然，社交媒體有時可以鼓勵辯論。"},{"en":"Granted means it is true or accepted that something has a point.","zh":"granted 的意思是承認某事有道理或屬實。"},{"en":"Granted, phones can distract students, but they can also support learning.","zh":"誠然，手機可以令學生分心，但也可以支持學習。"},{"en":"Writers use granted to admit the other side has some truth before giving their own argument.","zh":"作者使用 granted 來承認另一方有部分道理，然後提出自己的論點。"},{"en":"This word helps make an essay sound fair and balanced.","zh":"這個詞幫助文章聽起來公平和平衡。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"it would be unfair to say","meaning":"說……並不公平","examples":[{"en":"It would be unfair to say that social media never encourages debate.","zh":"說社交媒體從不鼓勵辯論並不公平。"},{"en":"It would be unfair to say means such a statement would be too one-sided or inaccurate.","zh":"it would be unfair to say 的意思是這樣的說法太片面或不準確。"},{"en":"It would be unfair to say all students misuse phones because many use them responsibly.","zh":"說所有學生都濫用手機並不公平，因為許多人負責任地使用手機。"},{"en":"This phrase helps writers avoid extreme claims.","zh":"這個短語幫助作者避免極端說法。"},{"en":"It shows that a fair argument recognises exceptions.","zh":"它顯示公平論點會承認例外情況。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"give ordinary people a voice","meaning":"讓普通人有發聲機會","examples":[{"en":"Social media can give ordinary people a voice.","zh":"社交媒體可以讓普通人有發聲機會。"},{"en":"To give ordinary people a voice means to allow normal citizens to express opinions publicly.","zh":"give ordinary people a voice 的意思是讓普通市民公開表達意見。"},{"en":"A resident can use social media to complain about broken street lights and be noticed.","zh":"居民可以使用社交媒體投訴壞掉的街燈，並得到注意。"},{"en":"Giving ordinary people a voice is valuable when traditional channels ignore them.","zh":"當傳統渠道忽略普通人時，讓普通人有發聲機會很有價值。"},{"en":"This phrase shows the democratic promise of communication tools.","zh":"這個短語展示溝通工具的民主承諾。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"respond instantly to","meaning":"即時回應……","examples":[{"en":"Citizens can respond instantly to public events.","zh":"市民可以即時回應公共事件。"},{"en":"To respond instantly to something means to react or reply immediately when it happens.","zh":"respond instantly to something 的意思是在某事發生時立即作出反應或回覆。"},{"en":"People can respond instantly to a transport delay by sharing updates online.","zh":"人們可以透過網上分享最新消息，即時回應交通延誤。"},{"en":"Instant response can help spread urgent information, but it may also spread unverified claims.","zh":"即時回應可以幫助傳播緊急資訊，但也可能傳播未經核實的說法。"},{"en":"This phrase shows the speed of modern communication.","zh":"這個短語展示現代溝通的速度。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"public events","meaning":"公共事件","examples":[{"en":"Social media allows citizens to respond to public events.","zh":"社交媒體讓市民回應公共事件。"},{"en":"Public events are happenings that affect or interest many people in society.","zh":"public events 是影響或引起社會中許多人關注的事情。"},{"en":"Public events may include elections, storms, protests, transport failures, or major policy changes.","zh":"公共事件可能包括選舉、風暴、抗議、交通故障或重大政策改變。"},{"en":"People discuss public events online because they want information and a sense of shared reaction.","zh":"人們在網上討論公共事件，因為他們想獲得資訊和共同反應感。"},{"en":"This phrase connects individual citizens with wider social life.","zh":"這個短語把個別市民與更廣泛的社會生活連繫起來。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"make room at the table for","meaning":"為……提供參與空間","examples":[{"en":"Social media can make room at the table for overlooked groups.","zh":"社交媒體可以為被忽略的群體提供參與空間。"},{"en":"To make room at the table for someone means to include people who were previously excluded from discussion or decision-making.","zh":"make room at the table for someone 的意思是讓過去被排除在討論或決策外的人參與。"},{"en":"A school committee can make room at the table for students with special needs.","zh":"學校委員會可以為有特殊需要的學生提供參與空間。"},{"en":"Public debate improves when it makes room at the table for people directly affected by a problem.","zh":"當公共辯論為直接受問題影響的人提供參與空間時，辯論會改善。"},{"en":"This phrase suggests fairer participation and respect.","zh":"這個短語暗示更公平的參與和尊重。"}],"source":"2019 Q3.pdf","sourcePage":11},{"front":"traditional media","meaning":"傳統媒體","examples":[{"en":"Traditional media once overlooked some groups.","zh":"傳統媒體曾忽略一些群體。"},{"en":"Traditional media refers to newspapers, television, radio, and magazines before or outside social media.","zh":"traditional media 是指社交媒體之前或以外的報章、電視、電台和雜誌。"},{"en":"Traditional media may choose which stories become public news.","zh":"傳統媒體可能選擇哪些故事成為公共新聞。"},{"en":"Some communities use social media when traditional media does not report their problems.","zh":"當傳統媒體不報道某些社區的問題時，這些社區可能使用社交媒體。"},{"en":"This phrase helps compare older communication channels with online platforms.","zh":"這個短語幫助比較較舊的溝通渠道與網上平台。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"overlook","meaning":"忽略","examples":[{"en":"Traditional media once overlooked many ordinary voices.","zh":"傳統媒體曾忽略許多普通聲音。"},{"en":"To overlook someone or something means to fail to notice or consider them properly.","zh":"overlook someone or something 的意思是未能適當注意或考慮某人或某事。"},{"en":"A teacher may overlook a quiet student if only loud students raise their hands.","zh":"如果只有大聲的學生舉手，老師可能忽略安靜學生。"},{"en":"When media overlook poor residents, public policy may ignore their needs.","zh":"當媒體忽略貧困居民時，公共政策可能忽視他們的需要。"},{"en":"This word describes exclusion that may happen by accident or through bias.","zh":"這個詞描述可能因意外或偏見而出現的排除。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"noise pollution","meaning":"噪音污染","examples":[{"en":"A resident affected by noise pollution can raise an issue online.","zh":"受噪音污染影響的居民可以在網上提出問題。"},{"en":"Noise pollution is harmful or disturbing sound that affects people’s health or daily life.","zh":"noise pollution 是影響人們健康或日常生活的有害或令人困擾的聲音。"},{"en":"Construction work late at night can create noise pollution for nearby families.","zh":"深夜建築工程可以為附近家庭造成噪音污染。"},{"en":"Noise pollution can cause stress, poor sleep, and conflict between neighbours.","zh":"噪音污染可以造成壓力、睡眠差和鄰里衝突。"},{"en":"This phrase describes sound as a public health and community problem.","zh":"這個短語把聲音描述成公共健康和社區問題。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"school pressure","meaning":"學校壓力","examples":[{"en":"A student worried about school pressure can speak online.","zh":"擔心學校壓力的學生可以在網上發聲。"},{"en":"School pressure is stress caused by exams, homework, competition, expectations, or school rules.","zh":"school pressure 是由考試、功課、競爭、期望或校規造成的壓力。"},{"en":"School pressure may make students tired even when they appear successful.","zh":"學校壓力可能令學生即使看似成功，也感到疲累。"},{"en":"Talking about school pressure can help adults understand students’ hidden struggles.","zh":"談論學校壓力可以幫助成年人理解學生隱藏的掙扎。"},{"en":"This phrase describes a common problem in student life.","zh":"這個短語描述學生生活中的常見問題。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"treated unfairly","meaning":"受到不公平對待","examples":[{"en":"A customer treated unfairly can raise an issue online.","zh":"受到不公平對待的顧客可以在網上提出問題。"},{"en":"Treated unfairly means not being given the respect, rights, or treatment one deserves.","zh":"treated unfairly 的意思是沒有得到應有的尊重、權利或待遇。"},{"en":"A student is treated unfairly if punishment is harsher for them than for others who did the same thing.","zh":"如果學生因同樣行為受到比其他人更嚴厲的懲罰，就是受到不公平對待。"},{"en":"People who feel treated unfairly may speak online when no one listens offline.","zh":"當線下沒有人聆聽時，感到受到不公平對待的人可能會在網上發聲。"},{"en":"This phrase describes injustice in daily situations.","zh":"這個短語描述日常情況中的不公義。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"raise an issue","meaning":"提出問題","examples":[{"en":"Ordinary people can raise an issue without waiting for approval.","zh":"普通人可以不用等待批准就提出問題。"},{"en":"To raise an issue means to bring a problem or concern to people’s attention.","zh":"raise an issue 的意思是把一個問題或關注帶到人們注意之中。"},{"en":"A resident may raise an issue about broken lifts in a housing estate.","zh":"居民可以提出屋邨升降機故障的問題。"},{"en":"Raising an issue online can start discussion, but it should include clear facts.","zh":"在網上提出問題可以展開討論，但應包括清楚事實。"},{"en":"This phrase is useful when someone makes a problem visible.","zh":"當某人令問題被看見時，這個短語很有用。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"newspaper editor’s approval","meaning":"報章編輯的批准","examples":[{"en":"Online users do not need a newspaper editor’s approval before raising an issue.","zh":"網上用戶提出問題前，不需要報章編輯的批准。"},{"en":"A newspaper editor’s approval means permission from the person who decides what appears in a newspaper.","zh":"newspaper editor’s approval 是指由決定報章刊登內容的人給予許可。"},{"en":"In the past, ordinary citizens often needed a newspaper editor’s approval to reach a large audience.","zh":"過去，普通市民常需要報章編輯的批准，才能接觸大量讀者。"},{"en":"Social media removes this barrier, but it also removes some checking.","zh":"社交媒體移除了這道門檻，但也移除了一些核查。"},{"en":"This phrase highlights the difference between traditional media and online posting.","zh":"這個短語突顯傳統媒體與網上發帖之間的差別。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"access to a microphone","meaning":"有機會發聲","examples":[{"en":"Access to a microphone is not the same as access to a meaningful conversation.","zh":"有機會發聲不等同於有機會參與有意義的對話。"},{"en":"Access to a microphone means having a chance to speak publicly or be heard by others.","zh":"access to a microphone 的意思是有公開說話或被別人聽見的機會。"},{"en":"Social media gives many people access to a microphone, but not always to respectful listeners.","zh":"社交媒體讓許多人有機會發聲，但不一定有尊重的聽眾。"},{"en":"Having access to a microphone can spread a concern quickly, but it cannot guarantee understanding.","zh":"有機會發聲可以迅速傳播關注，但不能保證理解。"},{"en":"This phrase separates the ability to speak from the quality of discussion.","zh":"這個短語把說話能力與討論質素分開。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"not the same as","meaning":"不等同於","examples":[{"en":"Access to a microphone is not the same as a meaningful conversation.","zh":"有機會發聲不等同於有意義的對話。"},{"en":"Not the same as means two things may look related but are different in important ways.","zh":"not the same as 的意思是兩件事可能看似相關，但在重要方面不同。"},{"en":"Being busy is not the same as being productive.","zh":"忙碌不等同於有生產力。"},{"en":"Having many comments is not the same as having a good debate.","zh":"有很多評論不等同於有良好辯論。"},{"en":"This phrase helps correct a false comparison.","zh":"這個短語幫助修正錯誤比較。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"meaningful conversation","meaning":"有意義的對話","examples":[{"en":"Public debate requires meaningful conversation.","zh":"公共辯論需要有意義的對話。"},{"en":"Meaningful conversation is discussion in which people listen, respond, and understand something more deeply.","zh":"meaningful conversation 是人們聆聽、回應並更深入理解某事的討論。"},{"en":"A meaningful conversation about school pressure includes students’ real experiences and possible solutions.","zh":"關於學校壓力的有意義對話，包括學生的真實經驗和可能解決方法。"},{"en":"A discussion is not meaningful if people only attack one another.","zh":"如果人們只互相攻擊，討論就沒有意義。"},{"en":"This phrase describes communication that creates understanding, not just noise.","zh":"這個短語描述創造理解，而不只是噪音的溝通。"}],"source":"2019 Q3.pdf","sourcePage":12},{"front":"turn into","meaning":"變成","examples":[{"en":"Many online discussions quickly turn into personal attacks.","zh":"許多網上討論很快變成人身攻擊。"},{"en":"To turn into something means to change and become something different.","zh":"turn into something 的意思是改變並成為另一種東西。"},{"en":"A calm class debate may turn into an argument if students start insulting each other.","zh":"如果學生開始互相侮辱，冷靜的課堂辯論可能變成爭吵。"},{"en":"Online disagreement can turn into a fight when people stop explaining and start blaming.","zh":"當人們停止解釋並開始責怪，網上分歧可以變成爭執。"},{"en":"This phrase describes a change in form, mood, or result.","zh":"這個短語描述形式、氣氛或結果的改變。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"personal attacks","meaning":"人身攻擊","examples":[{"en":"Many online discussions turn into personal attacks.","zh":"許多網上討論變成人身攻擊。"},{"en":"Personal attacks are insults aimed at a person rather than their idea or argument.","zh":"personal attacks 是針對個人而不是其想法或論點的侮辱。"},{"en":"Calling someone stupid instead of answering their evidence is a personal attack.","zh":"不回應對方證據，反而罵對方愚蠢，就是人身攻擊。"},{"en":"Personal attacks weaken debate because they make people defensive and afraid.","zh":"人身攻擊削弱辯論，因為它令人變得防衛和害怕。"},{"en":"This phrase describes a common failure in online discussion.","zh":"這個短語描述網上討論中的常見失敗。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"pile-ons","meaning":"群起圍攻","examples":[{"en":"Online discussions can turn into pile-ons.","zh":"網上討論可以變成群起圍攻。"},{"en":"Pile-ons happen when many people attack one person at the same time, especially online.","zh":"pile-ons 是許多人同時攻擊一個人，尤其在網上發生的情況。"},{"en":"A student may face a pile-on after one awkward comment is shared widely.","zh":"一名學生的一句尷尬評論被廣泛分享後，可能面對群起圍攻。"},{"en":"Pile-ons can feel frightening because the number of attackers keeps growing.","zh":"群起圍攻會令人害怕，因為攻擊者數目不斷增加。"},{"en":"This phrase shows how group pressure can replace fair criticism.","zh":"這個短語展示群體壓力如何取代公平批評。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"public shaming","meaning":"公開羞辱","examples":[{"en":"Online discussions can become public shaming.","zh":"網上討論可以變成公開羞辱。"},{"en":"Public shaming means embarrassing or condemning someone openly in front of many people.","zh":"public shaming 是在許多人面前公開令某人難堪或譴責某人。"},{"en":"A small mistake can become public shaming if screenshots spread with cruel comments.","zh":"如果截圖伴隨殘酷評論傳播，小錯誤可能變成公開羞辱。"},{"en":"Public shaming may punish a person without giving them a chance to explain.","zh":"公開羞辱可能懲罰一個人，卻不給他解釋機會。"},{"en":"This phrase describes a harsh form of social punishment.","zh":"這個短語描述一種嚴厲的社會懲罰。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"support part of","meaning":"支持……的一部分","examples":[{"en":"A student may support part of the school’s phone policy.","zh":"學生可能支持學校手機政策的一部分。"},{"en":"To support part of something means to agree with some sections but not all of it.","zh":"support part of something 的意思是同意其中一些部分，但不是全部。"},{"en":"A parent may support part of a homework policy but disagree with weekend assignments.","zh":"家長可能支持功課政策的一部分，但不同意週末作業。"},{"en":"Supporting part of an idea shows a balanced view rather than blind agreement.","zh":"支持某想法的一部分顯示平衡看法，而不是盲目同意。"},{"en":"This phrase is useful when opinions are mixed and careful.","zh":"當意見混合而細緻時，這個短語很有用。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"phone policy","meaning":"手機政策","examples":[{"en":"The student partly supports the school’s phone policy.","zh":"這名學生部分支持學校的手機政策。"},{"en":"A phone policy is a set of rules about when and how phones may be used.","zh":"phone policy 是關於手機何時以及如何使用的一套規則。"},{"en":"A school phone policy may ban phones during lessons but allow them after school.","zh":"學校手機政策可能禁止上課時使用手機，但允許放學後使用。"},{"en":"A phone policy works better when students understand its purpose.","zh":"當學生理解其目的時，手機政策會更有效。"},{"en":"This phrase describes rules about technology use in an organisation.","zh":"這個短語描述機構中關於科技使用的規則。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"punishment system","meaning":"懲罰制度","examples":[{"en":"The student disagrees with the punishment system.","zh":"這名學生不同意懲罰制度。"},{"en":"A punishment system is the set of consequences used when people break rules.","zh":"punishment system 是人們違反規則時所使用的一套後果。"},{"en":"A school punishment system may include warnings, detention, or calls to parents.","zh":"學校懲罰制度可能包括警告、留堂或致電家長。"},{"en":"A punishment system can feel unfair if small mistakes receive very harsh penalties.","zh":"如果小錯誤受到非常嚴厲的懲罰，懲罰制度可能令人覺得不公平。"},{"en":"This phrase focuses on how rules are enforced.","zh":"這個短語聚焦規則如何被執行。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"be accused by one side of","meaning":"被其中一方指責為……","examples":[{"en":"The student may be accused by one side of being obedient.","zh":"這名學生可能被其中一方指責為順從。"},{"en":"To be accused by one side of something means one group blames or labels a person in a debate.","zh":"be accused by one side of something 的意思是在辯論中被其中一個群體責怪或標籤。"},{"en":"A resident may be accused by one side of being selfish for questioning a new rule.","zh":"居民質疑新規則時，可能被其中一方指責為自私。"},{"en":"Being accused by one side can pressure people to choose a simple position.","zh":"被其中一方指責會迫使人們選擇簡單立場。"},{"en":"This phrase shows how debate can become unfairly divided.","zh":"這個短語展示辯論如何變得不公平地分裂。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"obedient","meaning":"順從的","examples":[{"en":"One side may accuse the student of being obedient.","zh":"一方可能指責這名學生順從。"},{"en":"Obedient means willing to follow rules or instructions without resistance.","zh":"obedient 的意思是願意服從規則或指示而不反抗。"},{"en":"An obedient student may follow a phone rule even if classmates complain.","zh":"順從的學生即使同學投訴，也可能遵守手機規則。"},{"en":"Calling someone obedient can be unfair if they are simply making a careful judgement.","zh":"如果某人只是作出細心判斷，稱他順從可能並不公平。"},{"en":"This word can be positive or negative depending on context.","zh":"這個詞可以是正面或負面，視乎語境而定。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"irresponsible","meaning":"不負責任的","examples":[{"en":"The other side may accuse the student of being irresponsible.","zh":"另一方可能指責這名學生不負責任。"},{"en":"Irresponsible means not acting carefully or not thinking about the consequences.","zh":"irresponsible 的意思是行事不謹慎，或不考慮後果。"},{"en":"Sharing unverified rumours online is irresponsible because it may harm others.","zh":"在網上分享未經核實的謠言是不負責任的，因為可能傷害別人。"},{"en":"A student is not necessarily irresponsible just because she questions a school rule.","zh":"學生質疑校規，不一定就是不負責任。"},{"en":"This word strongly criticises someone’s judgement or behaviour.","zh":"這個詞強烈批評某人的判斷或行為。"}],"source":"2019 Q3.pdf","sourcePage":13},{"front":"screenshots spread","meaning":"截圖傳開","examples":[{"en":"Screenshots spread quickly online.","zh":"截圖在網上迅速傳開。"},{"en":"Screenshots spread means captured images of messages or posts are shared widely.","zh":"screenshots spread 的意思是訊息或帖文的截圖被廣泛分享。"},{"en":"A private class chat can become public when screenshots spread.","zh":"當截圖傳開時，私人班群組可以變成公開內容。"},{"en":"When screenshots spread without context, people may misunderstand what happened.","zh":"當截圖在沒有背景脈絡下傳開，人們可能誤解發生了甚麼。"},{"en":"This phrase shows how quickly online evidence can leave its original setting.","zh":"這個短語展示網上證據如何迅速離開原本語境。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"strangers mock","meaning":"陌生人嘲笑","examples":[{"en":"Strangers may mock the student online.","zh":"陌生人可能在網上嘲笑這名學生。"},{"en":"To mock someone means to laugh at them cruelly or make them seem foolish.","zh":"mock someone 的意思是殘酷地取笑某人，或令某人顯得愚蠢。"},{"en":"Strangers may mock a person after seeing only one short clip.","zh":"陌生人可能只看了一段短片後就嘲笑某人。"},{"en":"Mocking someone online can feel especially painful because the audience is large and unknown.","zh":"在網上被嘲笑可能特別痛苦，因為觀眾龐大而陌生。"},{"en":"This phrase shows how public criticism can become personal cruelty.","zh":"這個短語展示公開批評如何變成個人殘酷。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"the original issue disappears","meaning":"原本的議題消失","examples":[{"en":"The original issue disappears during online attacks.","zh":"在網上攻擊期間，原本的議題消失。"},{"en":"The original issue disappears means the real problem is forgotten because attention moves elsewhere.","zh":"the original issue disappears 的意思是真正問題被遺忘，因為注意力轉移到其他地方。"},{"en":"In a debate about school phones, the original issue disappears if everyone focuses on insulting one student.","zh":"在關於校園手機的辯論中，如果人人都集中侮辱一名學生，原本的議題就消失。"},{"en":"When the original issue disappears, no solution is found.","zh":"當原本的議題消失，就找不到解決方法。"},{"en":"This phrase shows how personal conflict can replace public discussion.","zh":"這個短語展示個人衝突如何取代公共討論。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"under such pressure","meaning":"在這種壓力下","examples":[{"en":"Under such pressure, many moderate users stay silent.","zh":"在這種壓力下，許多立場溫和的用戶保持沉默。"},{"en":"Under such pressure means because of this level of stress, fear, or force.","zh":"under such pressure 的意思是因為這種程度的壓力、恐懼或迫力。"},{"en":"Under such pressure, a student may delete a careful comment instead of defending it.","zh":"在這種壓力下，學生可能刪除一則細心評論，而不是捍衛它。"},{"en":"People often change behaviour under such pressure to avoid being attacked.","zh":"人們在這種壓力下常改變行為，以避免被攻擊。"},{"en":"This phrase connects a difficult situation with its effect on people.","zh":"這個短語把困難情況與其對人的影響連繫起來。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"moderate users","meaning":"立場溫和的用戶","examples":[{"en":"Many moderate users stay silent online.","zh":"許多立場溫和的用戶在網上保持沉默。"},{"en":"Moderate users are people whose views are balanced, not extreme.","zh":"moderate users 是觀點平衡而不極端的人。"},{"en":"Moderate users may agree with part of each side in a debate.","zh":"立場溫和的用戶可能同意辯論中雙方各一部分。"},{"en":"If moderate users stop speaking, online discussion may look more extreme than society really is.","zh":"如果立場溫和的用戶停止發言，網上討論可能比真實社會看起來更極端。"},{"en":"This phrase describes voices that can reduce conflict but are often pressured into silence.","zh":"這個短語描述能減少衝突，但常被壓到沉默的聲音。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"stay silent","meaning":"保持沉默","examples":[{"en":"Moderate users often stay silent under pressure.","zh":"立場溫和的用戶在壓力下常保持沉默。"},{"en":"To stay silent means to choose not to speak or express an opinion.","zh":"stay silent 的意思是選擇不說話或不表達意見。"},{"en":"A student may stay silent in class because she fears being laughed at.","zh":"學生可能因害怕被取笑而在課堂上保持沉默。"},{"en":"People stay silent online when speaking honestly feels unsafe.","zh":"當坦誠發言感覺不安全時，人們會在網上保持沉默。"},{"en":"This phrase can show fear, caution, or loss of confidence.","zh":"這個短語可以表示恐懼、謹慎或失去信心。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"remains noisy","meaning":"仍然嘈雜","examples":[{"en":"The platform remains noisy, but debate becomes poorer.","zh":"平台仍然嘈雜，但辯論變得更貧乏。"},{"en":"Remains noisy means continues to be full of sound, activity, or many voices.","zh":"remains noisy 的意思是繼續充滿聲音、活動或許多聲音。"},{"en":"A group chat may remain noisy even after useful discussion has ended.","zh":"有用討論結束後，群組聊天仍可能很嘈雜。"},{"en":"A platform can remain noisy while thoughtful voices disappear.","zh":"平台可以在有思想的聲音消失後仍然嘈雜。"},{"en":"This phrase shows that activity is not the same as quality.","zh":"這個短語顯示活躍不等同於質素。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"becomes poorer","meaning":"變得更貧乏","examples":[{"en":"Debate becomes poorer when moderate users stay silent.","zh":"當立場溫和的用戶保持沉默時，辯論變得更貧乏。"},{"en":"Becomes poorer means becomes lower in quality, depth, or usefulness.","zh":"becomes poorer 的意思是在質素、深度或有用程度上下降。"},{"en":"A class discussion becomes poorer if only the loudest students speak.","zh":"如果只有最大聲的學生發言，課堂討論會變得更貧乏。"},{"en":"Public debate becomes poorer when insults replace evidence.","zh":"當侮辱取代證據時，公共辯論會變得更貧乏。"},{"en":"This phrase describes decline, not simply less noise.","zh":"這個短語描述衰退，而不只是較少噪音。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"all things considered","meaning":"綜合考慮各方面","examples":[{"en":"All things considered, social media often stifles public debate.","zh":"綜合考慮各方面，社交媒體常扼殺公眾辯論。"},{"en":"All things considered means after thinking about all important points.","zh":"all things considered 的意思是在思考所有重要方面之後。"},{"en":"All things considered, the new rule may help safety but still needs clearer explanation.","zh":"綜合考慮各方面，新規則可能有助安全，但仍需要更清楚解釋。"},{"en":"Writers use this phrase before giving a final balanced judgement.","zh":"作者在提出最終平衡判斷前會使用這個短語。"},{"en":"It shows that the conclusion comes after weighing different sides.","zh":"它顯示結論來自權衡不同方面之後。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"more than they encourage it","meaning":"多於鼓勵它","examples":[{"en":"These platforms stifle public debate more than they encourage it.","zh":"這些平台扼殺公眾辯論，多於鼓勵它。"},{"en":"More than they encourage it means the negative effect is stronger than the positive effect.","zh":"more than they encourage it 的意思是負面影響比正面影響更強。"},{"en":"Some school rules frighten students more than they guide them.","zh":"有些校規嚇怕學生多於引導學生。"},{"en":"This phrase compares two effects of the same thing.","zh":"這個短語比較同一事物的兩種影響。"},{"en":"It helps writers argue that a tool does more harm than good in a specific area.","zh":"它幫助作者論證某工具在某方面弊多於利。"}],"source":"2019 Q3.pdf","sourcePage":14},{"front":"create the appearance of","meaning":"製造……的表象","examples":[{"en":"Social media may create the appearance of openness.","zh":"社交媒體可能製造開放性的表象。"},{"en":"To create the appearance of something means to make something look true even if it may not be fully real.","zh":"create the appearance of something 的意思是令某事看起來真實，即使未必完全真實。"},{"en":"A school may create the appearance of consultation by asking students questions but ignoring their answers.","zh":"學校可能透過向學生提問但忽略答案，製造諮詢的表象。"},{"en":"Platforms create the appearance of openness when everyone can post but few are truly heard.","zh":"當人人都可以發帖但很少人真正被聽見時，平台就製造開放的表象。"},{"en":"This phrase helps criticise a surface image that hides a deeper problem.","zh":"這個短語幫助批評掩蓋更深問題的表面形象。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"openness","meaning":"開放性","examples":[{"en":"The appearance of openness can hide weaker debate.","zh":"開放性的表象可以掩蓋較薄弱的辯論。"},{"en":"Openness means being willing to allow participation, different views, or public access.","zh":"openness 是願意容許參與、不同觀點或公共進入。"},{"en":"A classroom shows openness when students can ask honest questions without fear.","zh":"當學生可以不害怕地提出真誠問題時，課室就展現開放性。"},{"en":"Openness is not real if only popular opinions are welcomed.","zh":"如果只有受歡迎意見被接納，開放性就不是真實的。"},{"en":"This word is often used when discussing freedom, discussion, and institutions.","zh":"這個詞常用於討論自由、討論和機構。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"reward outrage","meaning":"獎勵憤怒情緒","examples":[{"en":"Social media platforms often reward outrage.","zh":"社交媒體平台常獎勵憤怒情緒。"},{"en":"To reward outrage means to give more attention to anger, shock, or moral fury.","zh":"reward outrage 的意思是給憤怒、震驚或道德憤慨更多注意。"},{"en":"A furious post may be rewarded with shares before anyone checks the facts.","zh":"一篇憤怒帖文可能在任何人核實事實前已因分享而受到獎勵。"},{"en":"When platforms reward outrage, users may become angrier to stay visible.","zh":"當平台獎勵憤怒情緒時，用戶可能變得更憤怒以保持可見度。"},{"en":"This phrase criticises systems that turn anger into online success.","zh":"這個短語批評把憤怒變成網上成功的系統。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"divide citizens into","meaning":"把市民分成……","examples":[{"en":"Platforms divide citizens into like-minded groups.","zh":"平台把市民分成想法相近的群體。"},{"en":"To divide citizens into groups means to separate people into different social or opinion-based groups.","zh":"divide citizens into groups 的意思是把人分隔成不同社會或意見群體。"},{"en":"Online platforms may divide citizens into groups by showing each person different news.","zh":"網上平台可能透過向每個人展示不同新聞，把市民分成不同群體。"},{"en":"When citizens are divided into separate groups, shared understanding becomes harder.","zh":"當市民被分成不同群體，共同理解會變得更困難。"},{"en":"This phrase shows how technology can increase social separation.","zh":"這個短語展示科技如何加劇社會分隔。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"like-minded groups","meaning":"想法相近的群體","examples":[{"en":"Social media divides citizens into like-minded groups.","zh":"社交媒體把市民分成想法相近的群體。"},{"en":"Like-minded groups are groups of people who think in similar ways or share similar opinions.","zh":"like-minded groups 是思考方式相似或持有相似意見的人群。"},{"en":"A like-minded group can make users feel supported, but it can also reduce disagreement.","zh":"想法相近的群體可以令用戶感到被支持，但也可能減少分歧。"},{"en":"People in like-minded groups may begin to think their view is the only reasonable one.","zh":"想法相近的群體中的人，可能開始以為自己的觀點是唯一合理的觀點。"},{"en":"This phrase is useful when discussing echo chambers.","zh":"這個短語在討論同溫層時很有用。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"punish nuance","meaning":"懲罰細緻觀點","examples":[{"en":"Platforms often punish nuance.","zh":"平台常懲罰細緻觀點。"},{"en":"To punish nuance means to make careful, balanced, or complex views less visible or less rewarded.","zh":"punish nuance 的意思是令細心、平衡或複雜的觀點較不顯眼或較少受到獎勵。"},{"en":"A post that says “both sides have a point” may be ignored because the platform punishes nuance.","zh":"一篇說「雙方都有道理」的帖文可能被忽略，因為平台懲罰細緻觀點。"},{"en":"When nuance is punished, people learn to speak in simple extremes.","zh":"當細緻觀點被懲罰，人們會學會用簡單極端方式說話。"},{"en":"This phrase criticises environments that dislike careful distinctions.","zh":"這個短語批評不喜歡細緻區分的環境。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"the time has come for","meaning":"是時候……","examples":[{"en":"The time has come for platform owners to redesign recommendation systems.","zh":"是時候讓平台擁有人重新設計推薦系統。"},{"en":"The time has come for something means it is now necessary or appropriate to do it.","zh":"the time has come for something 的意思是現在有必要或適合做某事。"},{"en":"The time has come for schools to teach students how to check online information.","zh":"是時候讓學校教學生如何核實網上資訊。"},{"en":"Writers use this phrase when calling for action after explaining a problem.","zh":"作者在解釋問題後呼籲行動時會使用這個短語。"},{"en":"It gives a conclusion a strong sense of urgency.","zh":"它令結論帶有強烈迫切感。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"recommendation systems","meaning":"推薦系統","examples":[{"en":"Platform owners should redesign recommendation systems.","zh":"平台擁有人應重新設計推薦系統。"},{"en":"Recommendation systems are tools that choose and suggest content to users based on data.","zh":"recommendation systems 是根據數據選擇並向用戶建議內容的工具。"},{"en":"A recommendation system may suggest videos similar to ones a user watched before.","zh":"推薦系統可能建議與用戶之前觀看過的影片相似的影片。"},{"en":"Recommendation systems can shape public debate by deciding what people see next.","zh":"推薦系統可以透過決定人們接下來看到甚麼來塑造公共辯論。"},{"en":"This phrase refers to a hidden but powerful part of online platforms.","zh":"這個短語指網上平台中隱藏但有力的一部分。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"verify before sharing","meaning":"分享前核實","examples":[{"en":"Users should verify information before sharing it.","zh":"用戶應在分享資訊前核實它。"},{"en":"To verify before sharing means to check whether information is true before passing it to others.","zh":"verify before sharing 的意思是在把資訊傳給別人前，先檢查它是否真實。"},{"en":"A student should verify before sharing a rumour about school closure.","zh":"學生在分享學校停課謠言前應先核實。"},{"en":"Verifying before sharing can prevent panic, false blame, and public confusion.","zh":"分享前核實可以防止恐慌、錯誤責怪和公眾混亂。"},{"en":"This phrase describes a basic habit of responsible digital citizenship.","zh":"這個短語描述負責任數碼公民意識的基本習慣。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"digital citizenship","meaning":"數碼公民意識","examples":[{"en":"Schools should teach digital citizenship seriously.","zh":"學校應認真教授數碼公民意識。"},{"en":"Digital citizenship means using the internet responsibly, safely, respectfully, and critically.","zh":"digital citizenship 是負責任、安全、尊重而批判地使用互聯網。"},{"en":"Digital citizenship includes checking sources, protecting privacy, and avoiding online cruelty.","zh":"數碼公民意識包括核實來源、保護私隱和避免網上殘酷行為。"},{"en":"Students with strong digital citizenship think before posting or forwarding information.","zh":"有良好數碼公民意識的學生，在發帖或轉發資訊前會思考。"},{"en":"This phrase treats online behaviour as part of being a responsible member of society.","zh":"這個短語把網上行為視為成為負責任社會成員的一部分。"}],"source":"2019 Q3.pdf","sourcePage":15},{"front":"as seriously as","meaning":"像……一樣認真地","examples":[{"en":"Schools should teach digital citizenship as seriously as grammar or mathematics.","zh":"學校應像教授文法或數學一樣認真地教授數碼公民意識。"},{"en":"As seriously as means with the same level of importance, care, and attention.","zh":"as seriously as 的意思是以相同的重要程度、用心和注意去對待。"},{"en":"Students should treat online safety as seriously as physical safety.","zh":"學生應像重視人身安全一樣認真地重視網上安全。"},{"en":"Teaching digital citizenship as seriously as grammar shows that online behaviour matters.","zh":"像教授文法一樣認真地教授數碼公民意識，顯示網上行為很重要。"},{"en":"This phrase is useful when comparing the importance of two things.","zh":"當比較兩件事的重要性時，這個短語很有用。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"moderated spaces","meaning":"有管理的討論空間","examples":[{"en":"Newspapers should offer moderated spaces for disagreement.","zh":"報章應提供有管理的討論空間來容納分歧。"},{"en":"Moderated spaces are discussion areas guided by rules and people who manage behaviour.","zh":"moderated spaces 是由規則和管理行為的人引導的討論區域。"},{"en":"A moderated space may remove threats while still allowing strong disagreement.","zh":"有管理的討論空間可以移除威脅，同時仍容許強烈分歧。"},{"en":"Moderated spaces can help users argue without fear of abuse.","zh":"有管理的討論空間可以幫助用戶在不怕辱罵的情況下爭論。"},{"en":"This phrase suggests that free discussion sometimes needs careful management.","zh":"這個短語暗示自由討論有時需要細心管理。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"disagreement","meaning":"分歧；不同意見","examples":[{"en":"A healthy society needs intelligent disagreement.","zh":"健康的社會需要理性的分歧。"},{"en":"Disagreement means a difference of opinion between people or groups.","zh":"disagreement 是人或群體之間的意見差異。"},{"en":"Disagreement in a class can be useful if students explain their reasons calmly.","zh":"如果學生冷靜解釋理由，課堂上的分歧可以很有用。"},{"en":"Without disagreement, people may never notice weaknesses in their ideas.","zh":"沒有分歧，人們可能永遠不會注意到自己想法中的弱點。"},{"en":"This word is central to debate because discussion needs more than agreement.","zh":"這個詞是辯論的核心，因為討論需要的不只是同意。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"firm without becoming cruel","meaning":"堅定而不變得殘酷","examples":[{"en":"Disagreement can be firm without becoming cruel.","zh":"分歧可以堅定而不變得殘酷。"},{"en":"Firm without becoming cruel means strong and clear, but not insulting or hurtful.","zh":"firm without becoming cruel 的意思是強而清晰，但不侮辱或傷害別人。"},{"en":"A student can be firm without becoming cruel by saying, “I disagree because the evidence is weak.”","zh":"學生可以說「我不同意，因為證據薄弱」，這就是堅定而不變得殘酷。"},{"en":"Debate improves when people criticise ideas firmly but treat people humanely.","zh":"當人們堅定批評想法，但人道地對待別人時，辯論會改善。"},{"en":"This phrase shows how strength and kindness can exist together.","zh":"這個短語展示力量與善意可以並存。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"a healthy society","meaning":"健康的社會","examples":[{"en":"A healthy society does not need everyone to agree.","zh":"健康的社會不需要每個人都同意。"},{"en":"A healthy society is one where people can live safely, fairly, and with trust in one another.","zh":"healthy society 是人們能安全、公平地生活，並彼此有信任的社會。"},{"en":"A healthy society allows citizens to disagree without treating each other as enemies.","zh":"健康的社會容許市民有不同意見，而不把彼此當成敵人。"},{"en":"Public debate helps a healthy society find better solutions to shared problems.","zh":"公共辯論幫助健康的社會為共同問題找到更好解決方法。"},{"en":"This phrase describes social well-being, not only physical health.","zh":"這個短語描述社會福祉，而不只是身體健康。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"disagree intelligently","meaning":"理性而聰明地表達不同意見","examples":[{"en":"A healthy society needs people to disagree intelligently.","zh":"健康的社會需要人們理性而聰明地表達不同意見。"},{"en":"To disagree intelligently means to express disagreement with evidence, logic, and respect.","zh":"disagree intelligently 的意思是以證據、邏輯和尊重表達不同意見。"},{"en":"Students disagree intelligently when they challenge a rule by explaining its effects clearly.","zh":"當學生清楚解釋規則的影響來挑戰它時，就是理性而聰明地表達不同意見。"},{"en":"People disagree intelligently when they listen before replying.","zh":"當人們先聆聽再回應時，就是理性而聰明地表達不同意見。"},{"en":"This phrase shows that disagreement can be thoughtful rather than destructive.","zh":"這個短語顯示分歧可以有思想，而不是破壞性。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"value reason more than reaction","meaning":"重視理性多於即時反應","examples":[{"en":"Social media should value reason more than reaction.","zh":"社交媒體應重視理性多於即時反應。"},{"en":"To value reason more than reaction means to give more importance to careful thinking than immediate emotion.","zh":"value reason more than reaction 的意思是給細心思考比即時情緒更高的重要性。"},{"en":"A classroom values reason more than reaction when students must explain their answers.","zh":"當學生必須解釋答案時，課室就是重視理性多於即時反應。"},{"en":"Platforms would improve debate if they valued reason more than angry speed.","zh":"如果平台重視理性多於憤怒速度，辯論會改善。"},{"en":"This phrase describes a standard for healthier discussion.","zh":"這個短語描述更健康討論的標準。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"remain a crowded square","meaning":"仍然是一個擁擠的廣場","examples":[{"en":"Social media will remain a crowded square if it ignores reason.","zh":"如果社交媒體忽視理性，它仍然只是一個擁擠的廣場。"},{"en":"To remain a crowded square means to stay busy and full of people but lack meaningful order or discussion.","zh":"remain a crowded square 的意思是保持熱鬧和多人，但缺乏有意義的秩序或討論。"},{"en":"A group chat can remain a crowded square when everyone speaks but no one listens.","zh":"當人人都說話但沒有人聆聽時，群組聊天可以仍然是一個擁擠的廣場。"},{"en":"If platforms ignore reason, they may stay active while failing as public forums.","zh":"如果平台忽視理性，它們可能仍然活躍，卻未能成為公共論壇。"},{"en":"This phrase contrasts noise and crowd size with real debate.","zh":"這個短語把噪音和人數與真正辯論作對比。"}],"source":"2019 Q3.pdf","sourcePage":16},{"front":"truly listening","meaning":"真正聆聽","examples":[{"en":"Too few people are truly listening online.","zh":"網上太少人真正聆聽。"},{"en":"Truly listening means paying real attention in order to understand, not just waiting to reply.","zh":"truly listening 的意思是真正專心理解，而不只是等着回應。"},{"en":"Students are truly listening when they can repeat another person’s point fairly before disagreeing.","zh":"當學生能在不同意前公平地重述對方觀點時，就是正在真正聆聽。"},{"en":"Online debate improves when users are truly listening to reasons, not only reacting to tone.","zh":"當用戶真正聆聽理由，而不只是對語氣作反應時，網上辯論會改善。"},{"en":"This phrase describes the heart of meaningful conversation.","zh":"這個短語描述有意義對話的核心。"}],"source":"2019 Q3.pdf","sourcePage":16}],"dse/writing/part-b/2019/Q4":[{"front":"rival captain","meaning":"對手隊長","examples":[{"en":"The rival captain acted quickly after the striker collapsed.","zh":"前鋒倒下後，對手隊長迅速行動。"},{"en":"A rival captain is the leader of the opposing team.","zh":"對手隊長是對方球隊的隊長。"},{"en":"A rival captain may shake hands before a match to show respect.","zh":"對手隊長可能在比賽前握手，以表示尊重。"},{"en":"When an accident happens, a rival captain should help even if the teams are competing.","zh":"當意外發生時，即使雙方正在競爭，對手隊長也應幫忙。"},{"en":"The phrase reminds us that an opponent can still act with kindness.","zh":"這個詞語提醒我們，對手仍然可以表現善意。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"quick thinking","meaning":"快速反應；機智反應","examples":[{"en":"Adrian Wong’s quick thinking helped protect an injured player.","zh":"Adrian Wong 的快速反應幫助保護一名受傷球員。"},{"en":"Quick thinking means the ability to make a good decision very fast.","zh":"快速反應是指很快作出正確決定的能力。"},{"en":"A student shows quick thinking when they call a teacher after seeing a classmate faint.","zh":"當學生看見同學暈倒後立即叫老師，就是表現快速反應。"},{"en":"Quick thinking can prevent danger from becoming worse.","zh":"快速反應可以防止危險變得更嚴重。"},{"en":"In emergencies, quick thinking is often more useful than panic.","zh":"在緊急情況中，快速反應通常比驚慌更有用。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"steal the spotlight","meaning":"搶盡風頭","examples":[{"en":"The rival captain’s quick thinking stole the spotlight in the season finale.","zh":"對手隊長的快速反應在賽季最後一場比賽中搶盡風頭。"},{"en":"To steal the spotlight means to attract the most attention, often unexpectedly.","zh":"搶盡風頭，意思是吸引最多注意，通常是出乎意料地。"},{"en":"A quiet student may steal the spotlight by giving a powerful speech.","zh":"一名安靜的學生可能透過有力演講搶盡風頭。"},{"en":"A brave action can steal the spotlight from the planned result of an event.","zh":"勇敢行動可以搶走原本屬於賽果的焦點。"},{"en":"Adrian stole the spotlight not by scoring, but by helping someone in danger.","zh":"Adrian 搶盡風頭，不是因為入球，而是因為幫助有危險的人。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"season finale","meaning":"賽季最後一場比賽","examples":[{"en":"The season finale was expected to decide the championship.","zh":"賽季最後一場比賽預計會決定冠軍誰屬。"},{"en":"A season finale is the final game or event in a season.","zh":"賽季最後一場比賽，是一個賽季中的最後一場賽事。"},{"en":"Fans may feel excited before a season finale because the result can be important.","zh":"球迷在賽季最後一場比賽前可能很興奮，因為結果可能很重要。"},{"en":"If two strong teams meet in the season finale, the pressure becomes greater.","zh":"如果兩支強隊在賽季最後一場比賽碰頭，壓力就會更大。"},{"en":"This season finale became memorable for courage rather than the score.","zh":"這場賽季最後一場比賽令人難忘，是因為勇氣而不是比分。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"sports reporter","meaning":"體育記者","examples":[{"en":"Chris Wong is a Young Post sports reporter.","zh":"Chris Wong 是《Young Post》的體育記者。"},{"en":"A sports reporter writes or speaks about sports events for the public.","zh":"體育記者是為公眾撰寫或報道體育賽事的人。"},{"en":"A sports reporter may interview players after a school football match.","zh":"體育記者可能在學校足球賽後訪問球員。"},{"en":"Sports reporters help readers understand not only scores, but also human stories.","zh":"體育記者幫助讀者理解的不只是比分，還有人物故事。"},{"en":"A good sports reporter notices courage as well as competition.","zh":"好的體育記者會注意勇氣，也會注意競爭。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"final game of the season","meaning":"賽季最後一場比賽","examples":[{"en":"The final game of the season was expected to decide a championship.","zh":"賽季最後一場比賽預計會決定冠軍誰屬。"},{"en":"The final game of the season is the last match before the season ends.","zh":"賽季最後一場比賽，是賽季結束前的最後一場比賽。"},{"en":"A school team may train harder before the final game of the season.","zh":"學校球隊可能在賽季最後一場比賽前更加努力訓練。"},{"en":"If the title is close, the final game of the season can feel very tense.","zh":"如果冠軍形勢接近，賽季最後一場比賽會令人非常緊張。"},{"en":"In this story, the final game of the season became important for a different reason.","zh":"在這個故事中，賽季最後一場比賽因另一個原因而變得重要。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"be expected to","meaning":"預計會","examples":[{"en":"The match was expected to decide a championship.","zh":"這場比賽預計會決定冠軍誰屬。"},{"en":"Be expected to means people think something will probably happen.","zh":"預計會，意思是人們認為某事很可能發生。"},{"en":"The bus is expected to arrive at eight, so students wait near the stop.","zh":"巴士預計會八點到達，所以學生在站旁等候。"},{"en":"If heavy rain is expected to fall, outdoor events may be cancelled.","zh":"如果預計會下大雨，戶外活動可能取消。"},{"en":"The match was expected to be about victory, but it became about humanity.","zh":"這場比賽原本預計會關乎勝利，但後來變成關乎人情味。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"decide a championship","meaning":"決定冠軍誰屬","examples":[{"en":"The game was expected to decide a championship.","zh":"這場比賽預計會決定冠軍誰屬。"},{"en":"To decide a championship means to determine which team wins the title.","zh":"決定冠軍誰屬，意思是判定哪支隊伍贏得冠軍。"},{"en":"The last basketball match may decide a championship if two teams have the same points.","zh":"如果兩隊分數相同，最後一場籃球賽可能會決定冠軍誰屬。"},{"en":"A close score makes a game that decides a championship more exciting.","zh":"接近的比分令決定冠軍誰屬的比賽更加刺激。"},{"en":"This match still had to decide a championship, but safety came first.","zh":"這場比賽仍須決定冠軍誰屬，但安全必須放在首位。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"deliver a moment of courage","meaning":"帶來勇敢的一刻","examples":[{"en":"Instead, the game delivered a moment of courage.","zh":"相反，這場比賽帶來勇敢的一刻。"},{"en":"To deliver a moment of courage means to unexpectedly produce a situation where bravery is shown.","zh":"帶來勇敢的一刻，意思是出乎意料地出現展現勇氣的情況。"},{"en":"A fire drill may deliver a moment of courage if a student calmly helps others leave.","zh":"如果學生冷靜幫助其他人離開，火警演習可能帶來勇敢的一刻。"},{"en":"Difficult situations can deliver moments of courage because people must act quickly.","zh":"困難情況可以帶來勇敢的一刻，因為人們必須迅速行動。"},{"en":"The match delivered a moment of courage when Adrian helped his injured rival.","zh":"當 Adrian 幫助受傷對手時，這場比賽帶來勇敢的一刻。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"both sets of supporters","meaning":"雙方支持者","examples":[{"en":"Both sets of supporters applauded the same player.","zh":"雙方支持者都為同一名球員鼓掌。"},{"en":"Both sets of supporters means the fans from the two opposing sides.","zh":"雙方支持者，是指來自兩個對立陣營的球迷。"},{"en":"Both sets of supporters may cheer loudly before a school final.","zh":"在學校決賽前，雙方支持者可能大聲打氣。"},{"en":"When both sets of supporters clap for one player, it shows shared respect.","zh":"當雙方支持者都為一名球員鼓掌，這顯示共同尊重。"},{"en":"In this match, both sets of supporters forgot rivalry for a moment.","zh":"在這場比賽中，雙方支持者暫時忘記了競爭。"}],"source":"2019 Q4.pdf","sourcePage":1},{"front":"applaud the same player","meaning":"為同一名球員鼓掌","examples":[{"en":"The supporters from both schools applauded the same player.","zh":"來自兩間學校的支持者都為同一名球員鼓掌。"},{"en":"To applaud the same player means fans on different sides clap for one person together.","zh":"為同一名球員鼓掌，意思是不同陣營的支持者一起為同一人拍掌。"},{"en":"Students may applaud the same player after a fair and skilful performance.","zh":"學生可能在公平而有技巧的表現後，為同一名球員鼓掌。"},{"en":"When rivals applaud the same player, respect becomes more important than winning.","zh":"當對手為同一名球員鼓掌，尊重就比勝利更重要。"},{"en":"The crowd applauded Adrian because his action protected another student.","zh":"觀眾為 Adrian 鼓掌，因為他的行動保護了另一名學生。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"highly anticipated","meaning":"備受期待的","examples":[{"en":"The highly anticipated football match was suspended yesterday.","zh":"這場備受期待的足球賽昨日被暫停。"},{"en":"Highly anticipated means many people are excited and waiting for something.","zh":"備受期待的，意思是很多人興奮地等待某事。"},{"en":"A highly anticipated school concert may sell out quickly.","zh":"備受期待的學校音樂會可能很快售罄。"},{"en":"When an event is highly anticipated, disappointment is greater if it is stopped.","zh":"當活動備受期待，如果被停止，失望會更大。"},{"en":"The match was highly anticipated, but the injury changed everyone’s focus.","zh":"這場比賽備受期待，但受傷事件改變了所有人的焦點。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"football match","meaning":"足球賽","examples":[{"en":"The football match was played at King’s Park Sports Ground.","zh":"這場足球賽在京士柏運動場舉行。"},{"en":"A football match is a game between two football teams.","zh":"足球賽是兩支足球隊之間的比賽。"},{"en":"A school football match may attract students, teachers, and parents.","zh":"學校足球賽可能吸引學生、老師和家長觀看。"},{"en":"A football match can become tense when the score is close.","zh":"當比分接近，足球賽可能變得緊張。"},{"en":"This football match became memorable because of sportsmanship, not only football.","zh":"這場足球賽令人難忘，是因為體育精神，而不只是足球本身。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"sports ground","meaning":"運動場","examples":[{"en":"The match took place at King’s Park Sports Ground.","zh":"這場比賽在京士柏運動場舉行。"},{"en":"A sports ground is an outdoor place used for sports events.","zh":"運動場是用作體育賽事的戶外地方。"},{"en":"Students may gather at a sports ground for athletics day.","zh":"學生可能在運動場集合參加田徑日。"},{"en":"A sports ground needs clear safety rules because many players and spectators are present.","zh":"運動場需要清晰安全規則，因為有很多球員和觀眾在場。"},{"en":"The sports ground became silent when Marcus collapsed.","zh":"Marcus 倒下時，運動場變得安靜。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"be suspended","meaning":"被暫停","examples":[{"en":"The match was suspended after Marcus Lee collapsed.","zh":"Marcus Lee 倒下後，比賽被暫停。"},{"en":"Be suspended means to be stopped for a period of time.","zh":"被暫停，意思是被停止一段時間。"},{"en":"A school trip may be suspended if the weather becomes dangerous.","zh":"如果天氣變得危險，學校旅行可能被暫停。"},{"en":"A match is suspended when continuing could be unsafe or unfair.","zh":"當繼續比賽可能不安全或不公平，比賽就會被暫停。"},{"en":"The game was suspended so medical help could reach Marcus safely.","zh":"比賽被暫停，好讓醫療人員安全接近 Marcus。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"striker","meaning":"前鋒","examples":[{"en":"Marcus Lee was St. George’s striker.","zh":"Marcus Lee 是 St. George’s 的前鋒。"},{"en":"A striker is a football player whose main job is to score goals.","zh":"前鋒是主要負責入球的足球球員。"},{"en":"A striker often waits near the opponent’s goal for chances to shoot.","zh":"前鋒常在對方球門附近等待射門機會。"},{"en":"If a striker is injured, the team may lose its strongest attacking option.","zh":"如果前鋒受傷，球隊可能失去最強的進攻選擇。"},{"en":"Marcus was the striker, but the story focused on his safety first.","zh":"Marcus 是前鋒，但這個故事首先關注他的安全。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"collapse following","meaning":"在……後倒下","examples":[{"en":"The striker collapsed following a heavy collision.","zh":"這名前鋒在嚴重碰撞後倒下。"},{"en":"Collapse following something means to fall down after that event happens.","zh":"在某事後倒下，意思是那件事發生後倒在地上。"},{"en":"A runner may collapse following a long race in extreme heat.","zh":"跑手可能在酷熱中完成長跑後倒下。"},{"en":"If someone collapses following an accident, people should call for help quickly.","zh":"如果有人在意外後倒下，人們應迅速求助。"},{"en":"Marcus collapsed following the collision, so the match became an emergency.","zh":"Marcus 在碰撞後倒下，所以比賽變成緊急情況。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"heavy collision","meaning":"嚴重碰撞","examples":[{"en":"Marcus Lee collapsed following a heavy collision.","zh":"Marcus Lee 在嚴重碰撞後倒下。"},{"en":"A heavy collision is a strong crash between people or objects.","zh":"嚴重碰撞，是人或物之間強烈相撞。"},{"en":"A cyclist may be injured after a heavy collision with a car door.","zh":"單車手與車門嚴重碰撞後可能受傷。"},{"en":"Heavy collisions can cause serious harm, so players should not move an injured person carelessly.","zh":"嚴重碰撞可以造成嚴重傷害，所以球員不應隨便移動傷者。"},{"en":"The heavy collision made everyone on the field stop and watch.","zh":"這次嚴重碰撞令球場上的所有人停下來觀看。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"in the 68th minute","meaning":"在第68分鐘","examples":[{"en":"The collision happened in the 68th minute.","zh":"碰撞發生在第68分鐘。"},{"en":"In the 68th minute means during the sixty-eighth minute of the match.","zh":"在第68分鐘，意思是在比賽的第六十八分鐘期間。"},{"en":"A team may score in the 68th minute and change the whole game.","zh":"球隊可能在第68分鐘入球，改變整場比賽。"},{"en":"Events in the 68th minute can be important because little time remains.","zh":"第68分鐘發生的事情可能很重要，因為剩下時間不多。"},{"en":"In the 68th minute, the match changed from a title race into an emergency.","zh":"在第68分鐘，比賽由冠軍爭奪變成緊急情況。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"with the score locked at","meaning":"比分鎖定在","examples":[{"en":"With the score locked at 1-1, both teams wanted a winner.","zh":"比分鎖定在1比1時，雙方都想取得勝利。"},{"en":"With the score locked at a number means the score is tied and not changing.","zh":"比分鎖定在某個數字，意思是比分打和而且暫時沒有改變。"},{"en":"With the score locked at 2-2, the final minutes felt tense.","zh":"比分鎖定在2比2時，最後幾分鐘令人緊張。"},{"en":"A locked score makes players push harder because neither side is ahead.","zh":"比分鎖定會令球員更加努力，因為雙方都沒有領先。"},{"en":"With the score locked at 1-1, the injury interrupted a very close match.","zh":"比分鎖定在1比1時，受傷事件打斷了一場非常接近的比賽。"}],"source":"2019 Q4.pdf","sourcePage":2},{"front":"the crowd roaring for","meaning":"觀眾高呼希望……","examples":[{"en":"The crowd was roaring for a winner.","zh":"觀眾高呼希望出現勝方。"},{"en":"The crowd roaring for something means many spectators are shouting loudly because they want it to happen.","zh":"觀眾高呼希望某事發生，意思是許多觀眾大聲喊叫，因為他們想它出現。"},{"en":"The crowd may roar for a goal during the last minute.","zh":"觀眾可能在最後一分鐘高呼希望入球。"},{"en":"When the crowd is roaring for a winner, players feel strong pressure.","zh":"當觀眾高呼希望出現勝方，球員會感到很大壓力。"},{"en":"The crowd was roaring for a winner, but silence followed the collision.","zh":"觀眾原本高呼希望出現勝方，但碰撞後一片沉默。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"chase a long pass","meaning":"追逐一記長傳","examples":[{"en":"Lee chased a long pass into the penalty area.","zh":"Lee 追逐一記長傳進入禁區。"},{"en":"To chase a long pass means to run after a ball kicked far forward.","zh":"追逐一記長傳，意思是追趕向前踢得很遠的球。"},{"en":"A striker may chase a long pass when defenders are standing too high up the field.","zh":"當防守球員站得太前，前鋒可能追逐一記長傳。"},{"en":"Chasing a long pass can create a scoring chance but also a collision risk.","zh":"追逐長傳可以創造入球機會，但也有碰撞風險。"},{"en":"Lee chased the long pass because he wanted to reach the ball before the goalkeeper.","zh":"Lee 追逐那記長傳，因為他想比守門員更早碰到球。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"penalty area","meaning":"禁區","examples":[{"en":"Lee chased the ball into the penalty area.","zh":"Lee 追球進入禁區。"},{"en":"The penalty area is the marked area near the goal where special goalkeeper and penalty rules apply.","zh":"禁區是球門附近的標記範圍，當中有特別的守門員和十二碼規則。"},{"en":"A striker becomes dangerous when they receive the ball inside the penalty area.","zh":"當前鋒在禁區內接到球，就會變得有威脅。"},{"en":"Collisions in the penalty area can happen because attackers and goalkeepers both rush for the ball.","zh":"禁區內可能發生碰撞，因為進攻球員和守門員都會衝向皮球。"},{"en":"Lee entered the penalty area hoping for a chance to score.","zh":"Lee 進入禁區，希望得到入球機會。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"collide with","meaning":"與……相撞","examples":[{"en":"Lee collided with the Royal College goalkeeper.","zh":"Lee 與 Royal College 的守門員相撞。"},{"en":"To collide with someone means to crash into them accidentally or forcefully.","zh":"與某人相撞，意思是意外或用力撞上對方。"},{"en":"Two students may collide with each other while running around a corner.","zh":"兩名學生在轉角奔跑時可能互相相撞。"},{"en":"Players can be hurt when they collide with opponents at high speed.","zh":"球員高速與對手相撞時可能受傷。"},{"en":"Lee collided with the goalkeeper while both were trying to reach the ball.","zh":"Lee 與守門員相撞，當時二人都想碰到皮球。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"goalkeeper","meaning":"守門員","examples":[{"en":"Ryan Ho was the Royal College goalkeeper.","zh":"Ryan Ho 是 Royal College 的守門員。"},{"en":"A goalkeeper is the football player who protects the goal and can use hands inside the penalty area.","zh":"守門員是保護球門的足球球員，在禁區內可以用手。"},{"en":"A goalkeeper may dive to stop a shot.","zh":"守門員可能撲出去阻止射門。"},{"en":"Goalkeepers sometimes rush forward to clear danger before a striker arrives.","zh":"守門員有時會衝前，在前鋒到達前解除危險。"},{"en":"Ryan was the goalkeeper involved in the collision with Marcus.","zh":"Ryan 是與 Marcus 發生碰撞的守門員。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"rush out to","meaning":"衝出來去","examples":[{"en":"The goalkeeper had rushed out to clear the ball.","zh":"守門員已衝出來去解圍。"},{"en":"To rush out to do something means to move out quickly in order to act.","zh":"衝出來去做某事，意思是快速走出來以採取行動。"},{"en":"A teacher may rush out to stop students from crossing a busy road.","zh":"老師可能衝出來阻止學生橫過繁忙馬路。"},{"en":"A goalkeeper rushes out to clear the ball when waiting would be dangerous.","zh":"當等待會有危險時，守門員會衝出來去解圍。"},{"en":"Ryan rushed out to protect his goal, but the moment ended in a collision.","zh":"Ryan 衝出來保護球門，但那一刻以碰撞告終。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"clear the ball","meaning":"解圍","examples":[{"en":"The goalkeeper rushed out to clear the ball.","zh":"守門員衝出來解圍。"},{"en":"To clear the ball means to kick or move it away from a dangerous area.","zh":"解圍，意思是把球踢走或移離危險範圍。"},{"en":"A defender may clear the ball when it is near the goal.","zh":"當皮球接近球門，後衛可能解圍。"},{"en":"Clearing the ball can stop the other team from getting a scoring chance.","zh":"解圍可以阻止對方得到射門機會。"},{"en":"The goalkeeper tried to clear the ball before Lee could shoot.","zh":"守門員試圖在 Lee 射門前解圍。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"for a few seconds","meaning":"有幾秒鐘","examples":[{"en":"For a few seconds, the stadium seemed to hold its breath.","zh":"有幾秒鐘，整個球場似乎屏息以待。"},{"en":"For a few seconds means for a very short period of time.","zh":"有幾秒鐘，意思是很短的一段時間。"},{"en":"For a few seconds, the classroom was silent after the alarm rang.","zh":"警鐘響起後，有幾秒鐘課室一片安靜。"},{"en":"A few seconds can feel long when people are frightened or uncertain.","zh":"當人們害怕或不確定時，幾秒鐘也會感覺很長。"},{"en":"After the collision, those few seconds felt heavy and frightening.","zh":"碰撞後，那幾秒鐘感覺沉重而可怕。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"hold its breath","meaning":"屏息以待","examples":[{"en":"The stadium seemed to hold its breath after the collision.","zh":"碰撞後，整個球場似乎屏息以待。"},{"en":"To hold its breath means a place becomes very quiet because everyone is waiting anxiously.","zh":"屏息以待，意思是整個地方變得很安靜，因為所有人都焦急等待。"},{"en":"The classroom seemed to hold its breath while the teacher read the results.","zh":"老師讀出結果時，課室似乎屏息以待。"},{"en":"A crowd holds its breath when an injured player does not move.","zh":"當受傷球員沒有動，觀眾會屏息以待。"},{"en":"The stadium held its breath because no one knew how serious the injury was.","zh":"球場屏息以待，因為沒有人知道傷勢有多嚴重。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"no one saw it coming","meaning":"沒有人預料到","examples":[{"en":"No one saw the collision coming.","zh":"沒有人預料到這次碰撞。"},{"en":"No one saw it coming means nobody expected it to happen.","zh":"沒有人預料到，意思是沒有人想到它會發生。"},{"en":"No one saw the sudden rain coming during the school picnic.","zh":"學校野餐期間，沒有人預料到突然下雨。"},{"en":"Accidents feel more shocking when no one sees them coming.","zh":"當沒有人預料到意外，意外會令人更震驚。"},{"en":"The collision shocked the crowd because no one saw it coming.","zh":"這次碰撞令觀眾震驚，因為沒有人預料到。"}],"source":"2019 Q4.pdf","sourcePage":3},{"front":"at first","meaning":"起初","examples":[{"en":"At first, several players thought Lee was simply winded.","zh":"起初，幾名球員以為 Lee 只是喘不過氣。"},{"en":"At first means in the beginning, before people understand more.","zh":"起初，意思是在開始時，在人們了解更多之前。"},{"en":"At first, the homework looked difficult, but the examples helped.","zh":"起初，功課看起來很難，但例子有幫助。"},{"en":"People may misunderstand a situation at first because they have limited information.","zh":"人們起初可能誤解情況，因為他們掌握的資料有限。"},{"en":"At first, the players did not realise Lee needed urgent help.","zh":"起初，球員沒有意識到 Lee 需要緊急幫助。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"simply winded","meaning":"只是喘不過氣","examples":[{"en":"Several players thought Lee was simply winded.","zh":"幾名球員以為 Lee 只是喘不過氣。"},{"en":"Simply winded means temporarily unable to breathe normally after a hard hit or strong effort.","zh":"只是喘不過氣，意思是在強烈撞擊或用力後暫時不能正常呼吸。"},{"en":"A runner may be simply winded after sprinting too fast.","zh":"跑手衝刺太快後可能只是喘不過氣。"},{"en":"If someone is simply winded, they usually recover after a short rest.","zh":"如果某人只是喘不過氣，通常短暫休息後會恢復。"},{"en":"Lee looked more serious than simply winded because he was not responding.","zh":"Lee 的情況比只是喘不過氣更嚴重，因為他沒有反應。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"standing barely five metres away","meaning":"站在不足五米外","examples":[{"en":"Adrian Wong was standing barely five metres away.","zh":"Adrian Wong 當時站在不足五米外。"},{"en":"Standing barely five metres away means being very close, less than or only about five metres from someone.","zh":"站在不足五米外，意思是非常接近，距離某人少於或大約五米。"},{"en":"A teacher standing barely five metres away can notice if a student falls.","zh":"站在不足五米外的老師，可以注意到學生跌倒。"},{"en":"Because Adrian was standing barely five metres away, he saw the danger quickly.","zh":"因為 Adrian 站在不足五米外，所以他很快看見危險。"},{"en":"The phrase explains why Adrian could react before many others.","zh":"這個短語解釋了為何 Adrian 能比很多人更早反應。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"barely","meaning":"僅僅；不足","examples":[{"en":"Wong was standing barely five metres away from Lee.","zh":"Wong 當時站在離 Lee 僅僅不足五米的地方。"},{"en":"Barely means only just, almost not, or less than expected.","zh":"barely 意思是僅僅、幾乎不，或少於預期。"},{"en":"The bus was barely full, so many students found seats.","zh":"巴士僅僅坐滿了一小部分，所以很多學生找到座位。"},{"en":"If someone is barely breathing, help is needed immediately.","zh":"如果某人幾乎不能呼吸，就需要立即求助。"},{"en":"Adrian was barely five metres away, so he noticed Lee’s condition quickly.","zh":"Adrian 距離不足五米，所以很快注意到 Lee 的情況。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"not responding","meaning":"沒有反應","examples":[{"en":"Wong noticed that Lee was not responding.","zh":"Wong 注意到 Lee 沒有反應。"},{"en":"Not responding means not answering, moving, or reacting when people try to communicate.","zh":"沒有反應，意思是當人們嘗試溝通時，對方沒有回答、移動或作出反應。"},{"en":"If a student is not responding after fainting, someone should call for medical help.","zh":"如果學生暈倒後沒有反應，有人應該呼叫醫療幫助。"},{"en":"Not responding can be a warning sign after a collision.","zh":"碰撞後沒有反應可能是警號。"},{"en":"Adrian acted quickly because Lee was not responding normally.","zh":"Adrian 迅速行動，因為 Lee 沒有正常反應。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"immediately","meaning":"立即","examples":[{"en":"Wong immediately waved towards the referee.","zh":"Wong 立即向裁判揮手。"},{"en":"Immediately means without delay.","zh":"立即，意思是沒有延誤。"},{"en":"A student should immediately tell an adult if someone is hurt.","zh":"如果有人受傷，學生應立即告訴成年人。"},{"en":"Immediate action can save time during an emergency.","zh":"立即行動可以在緊急情況中節省時間。"},{"en":"Wong acted immediately instead of waiting for others to notice.","zh":"Wong 立即行動，而不是等待其他人注意。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"wave frantically","meaning":"拼命揮手","examples":[{"en":"Wong waved frantically towards the referee.","zh":"Wong 拼命向裁判揮手。"},{"en":"To wave frantically means to move one’s hands urgently and repeatedly to get attention.","zh":"拼命揮手，意思是急切地、重複地揮動雙手以吸引注意。"},{"en":"A passenger may wave frantically when they see the bus leaving early.","zh":"乘客看見巴士提早開走時，可能拼命揮手。"},{"en":"People wave frantically in emergencies because they need help quickly.","zh":"人們在緊急情況中拼命揮手，因為他們需要快速幫助。"},{"en":"Wong waved frantically because Lee’s condition looked serious.","zh":"Wong 拼命揮手，因為 Lee 的情況看起來嚴重。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"towards the referee","meaning":"向裁判","examples":[{"en":"Wong waved frantically towards the referee.","zh":"Wong 拼命向裁判揮手。"},{"en":"Towards the referee means in the direction of the official controlling the match.","zh":"向裁判，意思是朝控制比賽的官方人員方向。"},{"en":"A player may look towards the referee after a foul.","zh":"犯規後，球員可能望向裁判。"},{"en":"Waving towards the referee can help stop play quickly.","zh":"向裁判揮手可以幫助迅速停止比賽。"},{"en":"Wong waved towards the referee because the referee had power to suspend the match.","zh":"Wong 向裁判揮手，因為裁判有權暫停比賽。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"shout for","meaning":"大聲呼叫","examples":[{"en":"Wong shouted for the medical team.","zh":"Wong 大聲呼叫醫療隊。"},{"en":"To shout for someone means to call loudly because their help is needed.","zh":"大聲呼叫某人，意思是因為需要幫助而大聲叫喚對方。"},{"en":"A student may shout for a teacher when a classmate falls.","zh":"當同學跌倒，學生可能大聲呼叫老師。"},{"en":"In an emergency, shouting for help can bring adults faster.","zh":"在緊急情況中，大聲求助可以令成年人更快到來。"},{"en":"Wong shouted for the medical team because Lee needed professional care.","zh":"Wong 大聲呼叫醫療隊，因為 Lee 需要專業照顧。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"medical team","meaning":"醫療隊","examples":[{"en":"Wong shouted for the medical team.","zh":"Wong 大聲呼叫醫療隊。"},{"en":"A medical team is a group of trained people who help injured or sick people.","zh":"醫療隊是一組受過訓練、幫助傷者或病人的人。"},{"en":"A sports day should have a medical team ready near the track.","zh":"運動日應有醫療隊在跑道附近準備。"},{"en":"A medical team can check injuries before deciding whether a player should move.","zh":"醫療隊可以檢查傷勢，再決定球員是否應移動。"},{"en":"The medical team became essential when Lee stopped responding.","zh":"當 Lee 沒有反應時，醫療隊變得非常重要。"}],"source":"2019 Q4.pdf","sourcePage":4},{"front":"while others froze","meaning":"當其他人愣住時","examples":[{"en":"While others froze, Wong knelt beside his rival.","zh":"當其他人愣住時，Wong 跪在對手旁邊。"},{"en":"While others froze means other people became too shocked to act.","zh":"當其他人愣住時，意思是其他人震驚得無法行動。"},{"en":"While others froze during the fire alarm, one student calmly led the class out.","zh":"火警鐘響時，當其他人愣住，一名學生冷靜帶領全班離開。"},{"en":"Some people freeze in emergencies because fear stops them from thinking clearly.","zh":"有些人在緊急情況中會愣住，因為恐懼令他們不能清晰思考。"},{"en":"Wong’s action stood out because others froze.","zh":"Wong 的行動特別突出，因為其他人愣住了。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"freeze","meaning":"呆住；愣住","examples":[{"en":"Some players froze after Lee collapsed.","zh":"Lee 倒下後，有些球員呆住了。"},{"en":"To freeze means to stop moving or acting because of shock or fear.","zh":"呆住或愣住，意思是因震驚或恐懼而停止動作或行動。"},{"en":"A student may freeze during a presentation if they suddenly forget their words.","zh":"如果學生突然忘記講稿，可能在匯報時愣住。"},{"en":"People sometimes freeze in emergencies, so clear training is important.","zh":"人們有時在緊急情況中會愣住，所以清晰訓練很重要。"},{"en":"Adrian did not freeze; he acted calmly and quickly.","zh":"Adrian 沒有愣住；他冷靜而迅速地行動。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"kneel beside","meaning":"跪在……旁邊","examples":[{"en":"Wong knelt beside his rival.","zh":"Wong 跪在對手旁邊。"},{"en":"To kneel beside someone means to lower oneself onto the knees next to that person.","zh":"跪在某人旁邊，意思是在那人身旁跪下。"},{"en":"A teacher may kneel beside a crying child to speak gently.","zh":"老師可能跪在哭泣的孩子旁邊，溫和地說話。"},{"en":"Kneeling beside an injured person can show care, but people should avoid unsafe movement.","zh":"跪在傷者旁邊可以表示關心，但人們應避免不安全的移動。"},{"en":"Wong knelt beside Lee to check on him and keep him calm.","zh":"Wong 跪在 Lee 旁邊，查看他的情況並讓他保持冷靜。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"rival","meaning":"對手","examples":[{"en":"Wong helped his rival after the collision.","zh":"Wong 在碰撞後幫助他的對手。"},{"en":"A rival is someone you compete against.","zh":"對手是與你競爭的人。"},{"en":"Two schools may be rivals in football but friendly after the match.","zh":"兩間學校可能在足球中是對手，但賽後仍友好。"},{"en":"Helping a rival shows that safety and respect are more important than winning.","zh":"幫助對手顯示安全和尊重比勝利更重要。"},{"en":"Lee was Wong’s rival in the match, but he was also a person in need.","zh":"Lee 在比賽中是 Wong 的對手，但他也是需要幫助的人。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"tell players not to","meaning":"告訴球員不要","examples":[{"en":"Wong told players not to move Lee.","zh":"Wong 告訴球員不要移動 Lee。"},{"en":"To tell players not to do something means to warn or instruct them to avoid an action.","zh":"告訴球員不要做某事，意思是警告或指示他們避免某個行動。"},{"en":"A coach may tell players not to argue with the referee.","zh":"教練可能告訴球員不要與裁判爭論。"},{"en":"In an injury, telling players not to move someone can prevent further harm.","zh":"在受傷情況中，告訴球員不要移動某人可以防止進一步傷害。"},{"en":"Wong told players not to move Lee because he remembered first-aid advice.","zh":"Wong 告訴球員不要移動 Lee，因為他記得急救建議。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"move him","meaning":"移動他","examples":[{"en":"Wong told the players not to move him.","zh":"Wong 告訴球員不要移動他。"},{"en":"Move him means change his position or carry him somewhere else.","zh":"移動他，意思是改變他的位置或把他帶到其他地方。"},{"en":"If a person may have a serious injury, students should not move him unless trained adults say so.","zh":"如果某人可能嚴重受傷，學生不應移動他，除非受訓成年人指示。"},{"en":"Moving him carelessly after a collision could make an injury worse.","zh":"碰撞後隨便移動他，可能令傷勢更嚴重。"},{"en":"Wong stopped others from moving him until medical help arrived.","zh":"Wong 阻止其他人移動他，直到醫療人員到達。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"keep talking to","meaning":"一直跟……說話","examples":[{"en":"Wong kept talking to Lee until the nurses arrived.","zh":"Wong 一直跟 Lee 說話，直到護士到達。"},{"en":"To keep talking to someone means to continue speaking to them.","zh":"一直跟某人說話，意思是持續與對方交談。"},{"en":"A parent may keep talking to a frightened child to help them stay calm.","zh":"家長可能一直跟受驚孩子說話，幫助他保持冷靜。"},{"en":"Keeping talking to an injured person can help others know whether they are conscious.","zh":"一直跟傷者說話，可以幫助其他人知道對方是否清醒。"},{"en":"Wong kept talking to Lee so Lee would not feel alone.","zh":"Wong 一直跟 Lee 說話，讓 Lee 不會感到孤單。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"school nurses","meaning":"學校護士","examples":[{"en":"The school nurses arrived to help Lee.","zh":"學校護士到達並幫助 Lee。"},{"en":"School nurses are trained health workers who care for students at school events or on campus.","zh":"學校護士是在學校活動或校園內照顧學生的受訓醫護人員。"},{"en":"School nurses may treat cuts, check fevers, or help during sports injuries.","zh":"學校護士可能處理割傷、檢查發燒，或在運動受傷時幫忙。"},{"en":"When school nurses arrive quickly, injured students can receive safer care.","zh":"當學校護士迅速到達，受傷學生可以得到更安全的照顧。"},{"en":"The school nurses took over after Wong called for help.","zh":"Wong 求助後，學校護士接手處理。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"after the match","meaning":"賽後","examples":[{"en":"Wong spoke to reporters after the match.","zh":"Wong 賽後向記者說話。"},{"en":"After the match means when the game had ended or stopped.","zh":"賽後，意思是比賽結束或停止之後。"},{"en":"Players often thank their coaches after the match.","zh":"球員常在賽後感謝教練。"},{"en":"After the match, people may discuss key moments and injuries.","zh":"賽後，人們可能討論關鍵時刻和傷患。"},{"en":"Wong explained his actions after the match, when reporters asked him what happened.","zh":"記者問 Wong 發生甚麼事時，他在賽後解釋自己的行動。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"first-aid teacher","meaning":"急救老師","examples":[{"en":"Wong remembered what his first-aid teacher had taught him.","zh":"Wong 記起急救老師教過他的事。"},{"en":"A first-aid teacher teaches people how to give basic help before professional medical care arrives.","zh":"急救老師教人們在專業醫療到達前如何提供基本幫助。"},{"en":"A first-aid teacher may teach students how to call for help and keep an injured person still.","zh":"急救老師可能教學生如何求助和讓傷者保持不動。"},{"en":"Lessons from a first-aid teacher can become important during real emergencies.","zh":"急救老師的課堂在真正緊急情況中可以變得重要。"},{"en":"Wong’s first-aid teacher had prepared him to act calmly.","zh":"Wong 的急救老師曾讓他準備好冷靜行動。"}],"source":"2019 Q4.pdf","sourcePage":5},{"front":"drill something into someone","meaning":"反覆教導某人","examples":[{"en":"The first-aid teacher had drilled the lesson into the students.","zh":"急救老師曾把這個課題反覆教導學生。"},{"en":"To drill something into someone means to teach it again and again until they remember it.","zh":"反覆教導某人某事，意思是一遍又一遍地教，直到對方記住。"},{"en":"A coach drills safety rules into players before every match.","zh":"教練在每場比賽前反覆教導球員安全規則。"},{"en":"Repeated practice drills important habits into students so they can act under pressure.","zh":"重複練習把重要習慣教進學生心中，讓他們在壓力下也能行動。"},{"en":"The teacher drilled the lesson into Wong, and he remembered it during the emergency.","zh":"老師反覆教導 Wong 這個課題，所以他在緊急情況中記得。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"in that moment","meaning":"在那一刻","examples":[{"en":"In that moment, Wong saw a person who needed help.","zh":"在那一刻，Wong 看見的是一個需要幫助的人。"},{"en":"In that moment means at that exact time, especially during an important situation.","zh":"在那一刻，意思是在那個確切時間，特別是在重要情況中。"},{"en":"In that moment, the student forgot the competition and helped a classmate.","zh":"在那一刻，學生忘記競爭，幫助同學。"},{"en":"A person’s values often appear clearly in that moment of pressure.","zh":"一個人的價值觀常在壓力中的那一刻清楚出現。"},{"en":"In that moment, Wong chose care over rivalry.","zh":"在那一刻，Wong 選擇關心，而不是競爭。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"needs help","meaning":"需要幫助","examples":[{"en":"Wong saw a person who needed help.","zh":"Wong 看見一個需要幫助的人。"},{"en":"Needs help means requires support, care, or action from others.","zh":"需要幫助，意思是需要別人的支援、照顧或行動。"},{"en":"A student who falls and cannot stand needs help.","zh":"跌倒後不能站起來的學生需要幫助。"},{"en":"When someone needs help, quick action can prevent the problem from worsening.","zh":"當有人需要幫助，迅速行動可以防止問題惡化。"},{"en":"Wong saw that Lee needed help, not that he was an opponent.","zh":"Wong 看見 Lee 需要幫助，而不是只看見他是對手。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"at once","meaning":"立即","examples":[{"en":"Referee Daniel Yip stopped the match at once.","zh":"裁判 Daniel Yip 立即停止比賽。"},{"en":"At once means immediately, without waiting.","zh":"立即，意思是馬上，不等待。"},{"en":"A teacher should stop a dangerous game at once.","zh":"老師應立即停止危險遊戲。"},{"en":"Stopping at once can protect people when an emergency appears.","zh":"當緊急情況出現，立即停止可以保護人。"},{"en":"The referee stopped the match at once because Lee’s safety came first.","zh":"裁判立即停止比賽，因為 Lee 的安全最重要。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"clear the area around","meaning":"清空……周圍範圍","examples":[{"en":"The referee cleared the area around Lee.","zh":"裁判清空 Lee 周圍範圍。"},{"en":"To clear the area around someone means to move people away from that person.","zh":"清空某人周圍範圍，意思是把人群移離那人身邊。"},{"en":"Teachers may clear the area around a sick student so nurses have space to work.","zh":"老師可能清空生病學生周圍範圍，讓護士有空間工作。"},{"en":"Clearing the area around an injured person helps medical workers reach them safely.","zh":"清空傷者周圍範圍，幫助醫護人員安全接近。"},{"en":"The referee cleared the area around Lee to prevent crowding and confusion.","zh":"裁判清空 Lee 周圍範圍，以防擁擠和混亂。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"as a precaution","meaning":"作為預防措施","examples":[{"en":"As a precaution, both teams were sent to their benches.","zh":"作為預防措施，兩隊都被安排返回後備席。"},{"en":"As a precaution means as a safety measure before something worse happens.","zh":"作為預防措施，意思是在更壞事情發生前採取安全措施。"},{"en":"As a precaution, students stayed indoors during the thunderstorm.","zh":"作為預防措施，學生在雷暴期間留在室內。"},{"en":"Precautions reduce risk even when danger is not fully certain.","zh":"預防措施即使在危險未完全確定時，也能降低風險。"},{"en":"Both teams were moved back as a precaution so medical care could continue safely.","zh":"兩隊作為預防措施被安排退後，好讓醫療照顧安全繼續。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"be sent to their benches","meaning":"被安排返回後備席","examples":[{"en":"Both teams were sent to their benches.","zh":"兩隊都被安排返回後備席。"},{"en":"Be sent to their benches means players are told to return to the team seating area.","zh":"被安排返回後備席，意思是球員被指示回到球隊座位區。"},{"en":"Players may be sent to their benches during a timeout.","zh":"暫停期間，球員可能被安排返回後備席。"},{"en":"Sending teams to their benches can create space during an injury.","zh":"把隊伍安排返回後備席，可以在受傷時創造空間。"},{"en":"Both teams were sent to their benches so the field around Lee stayed clear.","zh":"兩隊被安排返回後備席，好讓 Lee 周圍的球場保持暢通。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"move spectators back","meaning":"叫觀眾退後","examples":[{"en":"Teachers moved spectators back from the touchline.","zh":"老師叫觀眾從邊線退後。"},{"en":"To move spectators back means to ask people watching to step farther away.","zh":"叫觀眾退後，意思是要求觀看的人站得更遠。"},{"en":"Teachers may move spectators back if students are running near the edge of a field.","zh":"如果學生在球場邊奔跑，老師可能叫觀眾退後。"},{"en":"Moving spectators back keeps emergency space open.","zh":"叫觀眾退後可以保留緊急空間。"},{"en":"The teachers moved spectators back so the medical team could work safely.","zh":"老師叫觀眾退後，好讓醫療隊安全工作。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"touchline","meaning":"邊線","examples":[{"en":"Spectators were moved back from the touchline.","zh":"觀眾被安排從邊線退後。"},{"en":"The touchline is the side boundary line of a football field.","zh":"邊線是足球場兩側的界線。"},{"en":"Coaches often stand near the touchline to give instructions.","zh":"教練常站在邊線附近給予指示。"},{"en":"Spectators should stay back from the touchline so players have enough space.","zh":"觀眾應遠離邊線，讓球員有足夠空間。"},{"en":"After Lee collapsed, the touchline had to be cleared for safety.","zh":"Lee 倒下後，邊線附近必須清空以保障安全。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"off-duty parent","meaning":"休班家長","examples":[{"en":"An off-duty parent helped attend to Lee.","zh":"一名休班家長幫忙照顧 Lee。"},{"en":"An off-duty parent is a parent who is not working at that moment.","zh":"休班家長，是當時沒有上班的家長。"},{"en":"An off-duty nurse at a school concert may still help if someone faints.","zh":"學校音樂會上一名休班護士，如果有人暈倒，仍可能幫忙。"},{"en":"Off-duty professionals can be useful in emergencies because they still have training.","zh":"休班專業人士在緊急情況中很有用，因為他們仍有訓練。"},{"en":"The off-duty parent helped because he was also an emergency doctor.","zh":"這名休班家長幫忙，因為他也是急症科醫生。"}],"source":"2019 Q4.pdf","sourcePage":6},{"front":"emergency doctor","meaning":"急症科醫生","examples":[{"en":"The off-duty parent works as an emergency doctor.","zh":"這名休班家長是急症科醫生。"},{"en":"An emergency doctor treats people with urgent or serious medical problems.","zh":"急症科醫生治療有緊急或嚴重醫療問題的人。"},{"en":"An emergency doctor may care for accident victims in a hospital.","zh":"急症科醫生可能在醫院照顧意外傷者。"},{"en":"Having an emergency doctor nearby can make a serious injury safer to manage.","zh":"附近有急症科醫生，可以令嚴重受傷情況較安全地處理。"},{"en":"The emergency doctor helped Lee before the paramedics arrived.","zh":"救護員到達前，這名急症科醫生幫助 Lee。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"attend to","meaning":"照顧；處理","examples":[{"en":"The nurses and doctor attended to Lee before paramedics arrived.","zh":"救護員到達前，護士和醫生照顧 Lee。"},{"en":"To attend to someone means to look after them or deal with their needs.","zh":"照顧或處理某人，意思是照料對方或處理其需要。"},{"en":"A teacher may attend to a student who feels sick during class.","zh":"上課期間學生不舒服，老師可能會照顧他。"},{"en":"Medical workers attend to injuries before deciding the next step.","zh":"醫護人員會先處理傷勢，再決定下一步。"},{"en":"The nurses and doctor attended to Lee while others kept the area clear.","zh":"護士和醫生照顧 Lee 時，其他人保持周圍暢通。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"paramedics","meaning":"救護員","examples":[{"en":"Paramedics arrived eight minutes later.","zh":"救護員八分鐘後到達。"},{"en":"Paramedics are emergency medical workers who give urgent care and transport patients.","zh":"救護員是提供緊急照顧並運送病人的急救醫護人員。"},{"en":"Paramedics may arrive by ambulance after someone calls emergency services.","zh":"有人致電緊急服務後，救護員可能乘救護車到達。"},{"en":"Paramedics can check breathing, injuries, and consciousness before taking someone to hospital.","zh":"救護員可以檢查呼吸、傷勢和清醒程度，再把人送院。"},{"en":"The paramedics took over Lee’s care from the school nurses and doctor.","zh":"救護員從學校護士和醫生手中接手照顧 Lee。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"eight minutes later","meaning":"八分鐘後","examples":[{"en":"Paramedics arrived eight minutes later.","zh":"救護員八分鐘後到達。"},{"en":"Eight minutes later means after eight minutes had passed.","zh":"八分鐘後，意思是八分鐘過去之後。"},{"en":"The teacher called for help, and eight minutes later the nurse arrived.","zh":"老師求助，八分鐘後護士到達。"},{"en":"In an emergency, eight minutes can feel much longer than usual.","zh":"在緊急情況中，八分鐘可能感覺比平常長得多。"},{"en":"The paramedics arrived eight minutes later, after Wong had already acted.","zh":"救護員八分鐘後到達，而 Wong 已經先行行動。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"be carried into the ambulance","meaning":"被抬上救護車","examples":[{"en":"Lee was carried into the ambulance.","zh":"Lee 被抬上救護車。"},{"en":"Be carried into the ambulance means to be lifted and placed inside the emergency vehicle.","zh":"被抬上救護車，意思是被抬起並放進緊急車輛內。"},{"en":"An injured player may be carried into the ambulance if walking is unsafe.","zh":"如果走路不安全，受傷球員可能被抬上救護車。"},{"en":"Being carried into the ambulance allows paramedics to take the patient to hospital quickly.","zh":"被抬上救護車後，救護員可以迅速把病人送院。"},{"en":"Lee was carried into the ambulance while the crowd waited anxiously.","zh":"Lee 被抬上救護車時，觀眾焦急等待。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"conscious","meaning":"清醒的","examples":[{"en":"Lee was conscious when he was carried into the ambulance.","zh":"Lee 被抬上救護車時是清醒的。"},{"en":"Conscious means awake and able to know what is happening around you.","zh":"清醒的，意思是醒著並能知道周圍發生甚麼。"},{"en":"A conscious patient may be able to answer simple questions.","zh":"清醒的病人可能能回答簡單問題。"},{"en":"If someone becomes conscious after an injury, medical workers still need to check them carefully.","zh":"如果有人受傷後恢復清醒，醫護人員仍需要仔細檢查。"},{"en":"The crowd felt relieved when Lee was conscious and able to raise his thumb.","zh":"當 Lee 清醒並能豎起拇指時，觀眾感到鬆一口氣。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"raise his thumb","meaning":"豎起拇指","examples":[{"en":"Lee was able to raise his thumb.","zh":"Lee 能夠豎起拇指。"},{"en":"To raise his thumb means to lift the thumb, often to show that he is okay.","zh":"豎起拇指，意思是舉起拇指，通常表示自己沒事。"},{"en":"A cyclist may raise his thumb after a small fall to tell others he is all right.","zh":"單車手輕微跌倒後可能豎起拇指，告訴別人自己還好。"},{"en":"Raising his thumb can calm worried people because it gives a simple positive sign.","zh":"豎起拇指可以安撫擔心的人，因為它給出簡單正面的訊號。"},{"en":"Lee raised his thumb, and the anxious silence turned into applause.","zh":"Lee 豎起拇指，焦急的沉默隨即變成掌聲。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"anxious silence","meaning":"焦急的沉默","examples":[{"en":"The anxious silence finally broke into applause.","zh":"焦急的沉默終於爆發成掌聲。"},{"en":"Anxious silence is a quiet moment when people are worried and waiting.","zh":"焦急的沉默，是人們擔心並等待時出現的安靜時刻。"},{"en":"An anxious silence filled the classroom while students waited for news about their friend.","zh":"學生等待朋友消息時，課室充滿焦急的沉默。"},{"en":"Anxious silence can end when people receive a sign that someone is safe.","zh":"當人們收到某人安全的訊號，焦急的沉默可以結束。"},{"en":"The anxious silence ended when Lee showed he was conscious.","zh":"Lee 顯示自己清醒時，焦急的沉默結束了。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"break into applause","meaning":"爆發掌聲","examples":[{"en":"The silence finally broke into applause.","zh":"沉默終於爆發成掌聲。"},{"en":"To break into applause means to suddenly start clapping.","zh":"爆發掌聲，意思是突然開始拍掌。"},{"en":"The audience broke into applause when the shy student finished her speech.","zh":"害羞的學生完成演講後，觀眾爆發掌聲。"},{"en":"People may break into applause after fear turns into relief.","zh":"當恐懼變成安心，人們可能爆發掌聲。"},{"en":"The crowd broke into applause when Lee raised his thumb.","zh":"Lee 豎起拇指時，觀眾爆發掌聲。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"following the incident","meaning":"事件發生後","examples":[{"en":"Following the incident, officials held a discussion.","zh":"事件發生後，賽事職員進行討論。"},{"en":"Following the incident means after the event had happened.","zh":"事件發生後，意思是在那件事發生之後。"},{"en":"Following the incident in the lab, the school reviewed its safety rules.","zh":"實驗室事件發生後，學校檢討安全規則。"},{"en":"Important decisions often happen following an incident because people need to respond.","zh":"重要決定常在事件發生後作出，因為人們需要回應。"},{"en":"Following the incident, safety became more important than finishing the match immediately.","zh":"事件發生後，安全比立即完成比賽更重要。"}],"source":"2019 Q4.pdf","sourcePage":7},{"front":"officials","meaning":"賽事職員；官方人員","examples":[{"en":"Officials discussed whether the match should continue.","zh":"賽事職員討論比賽是否應繼續。"},{"en":"Officials are people with authority to manage an event or make decisions.","zh":"賽事職員或官方人員，是有權管理活動或作決定的人。"},{"en":"School officials may decide whether sports day should continue in heavy rain.","zh":"學校職員可能決定運動日是否應在大雨中繼續。"},{"en":"Officials must think about safety, fairness, and rules before deciding.","zh":"職員在決定前必須考慮安全、公平和規則。"},{"en":"The officials in this match chose safety over speed.","zh":"這場比賽的賽事職員選擇安全，而不是速度。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"hold a discussion","meaning":"進行討論","examples":[{"en":"Officials held a 20-minute discussion.","zh":"賽事職員進行了二十分鐘的討論。"},{"en":"To hold a discussion means to talk carefully about a decision or problem.","zh":"進行討論，意思是仔細談論一個決定或問題。"},{"en":"Teachers may hold a discussion after a playground accident.","zh":"遊樂場發生意外後，老師可能進行討論。"},{"en":"Holding a discussion helps people consider different views before acting.","zh":"進行討論有助人們在行動前考慮不同看法。"},{"en":"Officials held a discussion because continuing the match involved safety concerns.","zh":"賽事職員進行討論，因為繼續比賽涉及安全憂慮。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"principals","meaning":"校長","examples":[{"en":"Both principals joined the discussion.","zh":"兩位校長都參與討論。"},{"en":"Principals are the heads of schools.","zh":"校長是學校的負責人。"},{"en":"Principals may speak to parents after a serious school incident.","zh":"嚴重校園事件後，校長可能向家長說明情況。"},{"en":"When both principals join a discussion, the decision affects both schools.","zh":"當兩位校長都參與討論，代表決定影響兩間學校。"},{"en":"The principals helped decide whether the match should continue.","zh":"校長協助決定比賽是否應繼續。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"willing to continue","meaning":"願意繼續","examples":[{"en":"The players were willing to continue the match.","zh":"球員願意繼續比賽。"},{"en":"Willing to continue means ready or prepared to keep going.","zh":"願意繼續，意思是準備好或願意繼續下去。"},{"en":"Students may be willing to continue a project after a short break.","zh":"學生短暫休息後可能願意繼續專題。"},{"en":"Even if players are willing to continue, adults must still consider safety.","zh":"即使球員願意繼續，成年人仍必須考慮安全。"},{"en":"The players wanted to continue, but the officials decided not to risk it.","zh":"球員想繼續，但賽事職員決定不冒險。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"be abandoned on safety grounds","meaning":"基於安全理由被腰斬","examples":[{"en":"The match was abandoned on safety grounds.","zh":"這場比賽基於安全理由被腰斬。"},{"en":"Be abandoned on safety grounds means to be stopped completely because safety is the main concern.","zh":"基於安全理由被腰斬，意思是因安全是主要憂慮而完全停止。"},{"en":"A school trip may be abandoned on safety grounds if a storm becomes dangerous.","zh":"如果暴風雨變得危險，學校旅行可能基於安全理由被取消。"},{"en":"Events are abandoned on safety grounds when continuing could put people at risk.","zh":"當繼續活動可能令人的安全受威脅，活動就會基於安全理由停止。"},{"en":"The match was abandoned on safety grounds even though the title was still undecided.","zh":"雖然冠軍仍未決定，這場比賽仍基於安全理由被腰斬。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"safety grounds","meaning":"安全理由","examples":[{"en":"The match was abandoned on safety grounds.","zh":"這場比賽基於安全理由被腰斬。"},{"en":"Safety grounds are reasons connected with protecting people from harm.","zh":"安全理由，是與保護人免受傷害有關的原因。"},{"en":"A teacher may cancel outdoor practice on safety grounds during lightning.","zh":"雷電期間，老師可能基於安全理由取消戶外練習。"},{"en":"Safety grounds can outweigh excitement, money, or competition.","zh":"安全理由可以比興奮、金錢或競爭更重要。"},{"en":"Officials used safety grounds to explain why the match could not continue.","zh":"賽事職員用安全理由解釋為何比賽不能繼續。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"resume next Saturday","meaning":"下星期六恢復進行","examples":[{"en":"The match will resume next Saturday.","zh":"比賽將於下星期六恢復進行。"},{"en":"Resume next Saturday means start again or continue on the following Saturday.","zh":"下星期六恢復進行，意思是在接下來的星期六重新開始或繼續。"},{"en":"A postponed lesson may resume next Saturday if the teacher is available.","zh":"如果老師有空，被延遲的課堂可能下星期六恢復進行。"},{"en":"Resuming next Saturday gives players time to recover emotionally.","zh":"下星期六恢復進行，讓球員有時間在情緒上恢復。"},{"en":"The match will resume next Saturday instead of continuing immediately.","zh":"比賽將於下星期六恢復進行，而不是立即繼續。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"from the 68th minute","meaning":"由第68分鐘開始","examples":[{"en":"The match will resume from the 68th minute.","zh":"比賽將由第68分鐘開始恢復。"},{"en":"From the 68th minute means the game will continue at the exact time when it stopped.","zh":"由第68分鐘開始，意思是比賽會從停止時的確切時間繼續。"},{"en":"A suspended match may resume from the same minute to keep the result fair.","zh":"被暫停的比賽可能由同一分鐘恢復，以保持賽果公平。"},{"en":"Resuming from the 68th minute prevents teams from replaying the whole match.","zh":"由第68分鐘恢復，可以避免兩隊重賽整場比賽。"},{"en":"The match will restart from the moment before the emergency interrupted it.","zh":"比賽將從緊急情況打斷前的時刻重新開始。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"with the score remaining","meaning":"比分維持在","examples":[{"en":"The match will resume with the score remaining 1-1.","zh":"比賽恢復時比分維持在1比1。"},{"en":"With the score remaining means the score stays the same when play continues.","zh":"比分維持在，意思是比賽繼續時比分保持不變。"},{"en":"A basketball game may restart with the score remaining 30-30 after a power cut.","zh":"停電後，籃球賽可能在比分維持30比30下重新開始。"},{"en":"Keeping the score remaining the same protects fairness after a suspension.","zh":"讓比分維持不變，可以在比賽暫停後保障公平。"},{"en":"The teams will return with the score remaining 1-1, so the title is still open.","zh":"兩隊將在比分維持1比1下回來，所以冠軍仍未明朗。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"visibly shaken","meaning":"明顯受驚；神情震驚","examples":[{"en":"Mr Lam looked visibly shaken after the incident.","zh":"事件發生後，Lam 先生看起來明顯受驚。"},{"en":"Visibly shaken means clearly upset, shocked, or frightened in a way others can see.","zh":"明顯受驚，意思是清楚看得出心煩、震驚或害怕。"},{"en":"A teacher may look visibly shaken after seeing a student injured.","zh":"看見學生受傷後，老師可能神情震驚。"},{"en":"People become visibly shaken when a normal event suddenly turns dangerous.","zh":"當普通活動突然變得危險，人們會明顯受驚。"},{"en":"Mr Lam was visibly shaken because the incident was serious and unexpected.","zh":"Lam 先生明顯受驚，因為事件嚴重而且出乎意料。"}],"source":"2019 Q4.pdf","sourcePage":8},{"front":"praise someone for","meaning":"因……讚揚某人","examples":[{"en":"Mr Lam praised Wong for acting with remarkable calm.","zh":"Lam 先生因 Wong 表現得異常冷靜而讚揚他。"},{"en":"To praise someone for something means to say they did something good.","zh":"因某事讚揚某人，意思是說某人做得好。"},{"en":"A teacher may praise a student for helping a classmate.","zh":"老師可能因學生幫助同學而讚揚他。"},{"en":"People praise others for calm action when it prevents harm.","zh":"當冷靜行動防止傷害，人們會因此讚揚別人。"},{"en":"Mr Lam praised Wong for his calm response during the emergency.","zh":"Lam 先生因 Wong 在緊急情況中的冷靜反應而讚揚他。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"act with remarkable calm","meaning":"表現得異常冷靜","examples":[{"en":"Wong acted with remarkable calm during the emergency.","zh":"Wong 在緊急情況中表現得異常冷靜。"},{"en":"To act with remarkable calm means to behave in an unusually steady way under pressure.","zh":"表現得異常冷靜，意思是在壓力下以非常穩定的方式行動。"},{"en":"A student acts with remarkable calm when they guide others during a fire drill.","zh":"學生在火警演習中引導其他人時，就是表現得異常冷靜。"},{"en":"Acting with remarkable calm can help frightened people follow instructions.","zh":"表現得異常冷靜可以幫助受驚的人跟隨指示。"},{"en":"Wong acted with remarkable calm while others were shocked.","zh":"當其他人震驚時，Wong 表現得異常冷靜。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"remarkable calm","meaning":"非常冷靜","examples":[{"en":"Wong showed remarkable calm on the field.","zh":"Wong 在球場上表現出非常冷靜。"},{"en":"Remarkable calm means a level of calmness that is unusual and impressive.","zh":"非常冷靜，是指不尋常而令人佩服的冷靜程度。"},{"en":"A nurse may show remarkable calm while treating several patients.","zh":"護士在治療多名病人時可能表現得非常冷靜。"},{"en":"Remarkable calm matters in emergencies because panic can create more danger.","zh":"非常冷靜在緊急情況中很重要，因為恐慌可能造成更多危險。"},{"en":"Wong’s remarkable calm helped the adults understand the situation quickly.","zh":"Wong 的非常冷靜幫助成年人迅速理解情況。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"rivalry","meaning":"競爭；敵對關係","examples":[{"en":"Rivalry is part of school sport.","zh":"競爭是校園體育的一部分。"},{"en":"Rivalry is competition between people or groups who want to beat each other.","zh":"競爭或敵對關係，是想擊敗對方的人或群體之間的競爭。"},{"en":"Two classes may have a friendly rivalry during sports day.","zh":"兩個班級可能在運動日有友善競爭。"},{"en":"Rivalry can make games exciting, but it should not destroy respect.","zh":"競爭可以令比賽刺激，但不應破壞尊重。"},{"en":"This incident showed that rivalry must stop when someone needs help.","zh":"這次事件顯示，當有人需要幫助時，競爭必須暫停。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"school sport","meaning":"校園體育","examples":[{"en":"Rivalry is part of school sport.","zh":"競爭是校園體育的一部分。"},{"en":"School sport means organised games or competitions involving students.","zh":"校園體育，是涉及學生的有組織遊戲或比賽。"},{"en":"School sport can teach fitness, teamwork, discipline, and respect.","zh":"校園體育可以教導健康、團隊合作、紀律和尊重。"},{"en":"If school sport becomes only about winning, students may forget its deeper lessons.","zh":"如果校園體育只關乎勝利，學生可能忘記其更深層課題。"},{"en":"This match showed that school sport should include humanity as well as rivalry.","zh":"這場比賽顯示，校園體育應包括人情味，也包括競爭。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"a line we never cross","meaning":"絕不能越過的底線","examples":[{"en":"There is a line we never cross in school sport.","zh":"在校園體育中，有一條我們絕不能越過的底線。"},{"en":"A line we never cross means a moral limit that people must not go beyond.","zh":"絕不能越過的底線，是人們不應超越的道德界線。"},{"en":"In debate, insulting classmates is a line we never cross.","zh":"在辯論中，侮辱同學是一條絕不能越過的底線。"},{"en":"Competition is healthy only if players know the lines they should never cross.","zh":"只有當球員知道不能越過哪些底線，競爭才是健康的。"},{"en":"In school sport, ignoring an injured opponent is a line we never cross.","zh":"在校園體育中，忽視受傷對手是一條絕不能越過的底線。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"on the field","meaning":"在球場上","examples":[{"en":"Adrian reacted faster than any adult on the field.","zh":"Adrian 比球場上任何成年人反應都快。"},{"en":"On the field means on the sports playing area.","zh":"在球場上，意思是在體育比賽場地內。"},{"en":"A coach watches players on the field during a match.","zh":"教練在比賽期間觀察球場上的球員。"},{"en":"People on the field often see accidents before spectators do.","zh":"在球場上的人常比觀眾更早看見意外。"},{"en":"Adrian was on the field and close enough to react quickly.","zh":"Adrian 在球場上，而且距離夠近，所以能迅速反應。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"prevent the situation from","meaning":"防止情況……","examples":[{"en":"His response may have prevented the situation from becoming worse.","zh":"他的反應可能防止情況變得更糟。"},{"en":"To prevent the situation from doing something means to stop it from developing in a harmful way.","zh":"防止情況變成某樣子，意思是阻止它向有害方向發展。"},{"en":"Locking the gate can prevent the situation from becoming dangerous during a storm.","zh":"暴風雨期間鎖上大門，可以防止情況變得危險。"},{"en":"Quick medical help can prevent an injury situation from worsening.","zh":"快速醫療幫助可以防止受傷情況惡化。"},{"en":"Adrian’s response may have prevented the situation from becoming much worse.","zh":"Adrian 的反應可能防止情況變得嚴重得多。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"becoming much worse","meaning":"變得嚴重得多","examples":[{"en":"His quick action may have stopped the situation from becoming much worse.","zh":"他的快速行動可能阻止情況變得嚴重得多。"},{"en":"Becoming much worse means changing into a far more serious or dangerous condition.","zh":"變得嚴重得多，意思是變成更嚴重或更危險的狀況。"},{"en":"A small fire can become much worse if no one calls for help.","zh":"如果沒有人求助，小火可能變得嚴重得多。"},{"en":"Moving an injured player carelessly could make the injury become much worse.","zh":"隨便移動受傷球員，可能令傷勢變得嚴重得多。"},{"en":"Wong’s quick action helped stop the emergency from becoming much worse.","zh":"Wong 的快速行動幫助阻止緊急情況變得嚴重得多。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"be desperate to","meaning":"非常渴望","examples":[{"en":"Royal College had been desperate to win the league title.","zh":"Royal College 一直非常渴望贏得聯賽冠軍。"},{"en":"Be desperate to do something means to want it very strongly.","zh":"非常渴望做某事，意思是非常強烈地想得到它。"},{"en":"A student may be desperate to pass an exam after months of hard work.","zh":"學生努力數月後，可能非常渴望通過考試。"},{"en":"Being desperate to win can increase pressure and emotion.","zh":"非常渴望勝利會增加壓力和情緒。"},{"en":"Royal College was desperate to win, but the incident changed what mattered most.","zh":"Royal College 非常渴望取勝，但事件改變了最重要的事情。"}],"source":"2019 Q4.pdf","sourcePage":9},{"front":"league title","meaning":"聯賽冠軍","examples":[{"en":"Royal College wanted to win the league title.","zh":"Royal College 想贏得聯賽冠軍。"},{"en":"A league title is the championship won by the best team in a league season.","zh":"聯賽冠軍，是在整個聯賽賽季中由最佳球隊贏得的冠軍。"},{"en":"A school basketball team may win the league title after finishing first.","zh":"學校籃球隊排名第一後，可能贏得聯賽冠軍。"},{"en":"The league title matters because it represents success over the whole season.","zh":"聯賽冠軍重要，因為它代表整個賽季的成功。"},{"en":"The league title still mattered, but Marcus’s safety mattered more.","zh":"聯賽冠軍仍然重要，但 Marcus 的安全更重要。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"put the result into perspective","meaning":"令人重新看待賽果的重要性","examples":[{"en":"The incident put the result into perspective.","zh":"這次事件令人重新看待賽果的重要性。"},{"en":"To put the result into perspective means to make people see that the score is less important than bigger matters.","zh":"令人重新看待賽果的重要性，意思是令人明白比分不及更大的事情重要。"},{"en":"An injury can put a school race result into perspective.","zh":"受傷事件可以令人重新看待學校賽跑結果的重要性。"},{"en":"When safety is at risk, winning is put into perspective.","zh":"當安全受威脅，勝利的重要性就會被重新看待。"},{"en":"The incident made players realise that a trophy was not everything.","zh":"這次事件令球員意識到獎盃不是一切。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"want the trophy","meaning":"想贏得獎盃","examples":[{"en":"The players still wanted the trophy.","zh":"球員仍然想贏得獎盃。"},{"en":"To want the trophy means to strongly wish to win the prize or championship.","zh":"想贏得獎盃，意思是強烈希望取得獎項或冠軍。"},{"en":"A team may want the trophy after training all season.","zh":"球隊訓練整個賽季後，可能很想贏得獎盃。"},{"en":"Wanting the trophy can motivate players, but it should not remove compassion.","zh":"想贏得獎盃可以激勵球員，但不應消除同情心。"},{"en":"The players wanted the trophy, yet they also respected Marcus’s safety.","zh":"球員想贏得獎盃，但也尊重 Marcus 的安全。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, the incident reminded them what sport is really about.","zh":"話雖如此，這次事件提醒他們體育真正關乎甚麼。"},{"en":"That said is used to add a contrasting or balancing point after the previous idea.","zh":"話雖如此，用來在前一個想法後加入相反或平衡的一點。"},{"en":"The exam was difficult; that said, the teacher had prepared us well.","zh":"考試很難；話雖如此，老師已讓我們準備好。"},{"en":"Writers use that said to admit one point before moving to another.","zh":"作者使用「話雖如此」來承認一點，再轉向另一點。"},{"en":"The players wanted to win; that said, they understood that respect mattered more.","zh":"球員想取勝；話雖如此，他們明白尊重更重要。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"not just about","meaning":"不只是關於","examples":[{"en":"Sport is not just about beating opponents.","zh":"體育不只是關於擊敗對手。"},{"en":"Not just about means something includes more than one obvious idea.","zh":"不只是關於，意思是某事包含的不止一個明顯想法。"},{"en":"School is not just about marks; it is also about growing as a person.","zh":"學校不只是關於分數；也關乎成長做人。"},{"en":"Sport is not just about winning when safety, respect, and teamwork are involved.","zh":"當安全、尊重和團隊合作都涉及其中，體育就不只是關於勝利。"},{"en":"This match showed that football is not just about the final score.","zh":"這場比賽顯示足球不只是關於最終比分。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"beat opponents","meaning":"擊敗對手","examples":[{"en":"Sport is not just about beating opponents.","zh":"體育不只是關於擊敗對手。"},{"en":"To beat opponents means to defeat the people or teams you are competing against.","zh":"擊敗對手，意思是戰勝與你競爭的人或隊伍。"},{"en":"A team may beat opponents by training hard and playing fairly.","zh":"球隊可以透過努力訓練和公平比賽來擊敗對手。"},{"en":"Wanting to beat opponents is normal, but respect must remain.","zh":"想擊敗對手是正常的，但尊重必須保留。"},{"en":"Adrian showed that helping opponents can matter more than beating them.","zh":"Adrian 顯示，幫助對手可能比擊敗對手更重要。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"most importantly","meaning":"最重要的是","examples":[{"en":"Most importantly, sport is about respecting opponents.","zh":"最重要的是，體育關乎尊重對手。"},{"en":"Most importantly introduces the point that matters more than the others.","zh":"最重要的是，用來引出比其他事情更重要的一點。"},{"en":"A school trip should be fun, but most importantly, it should be safe.","zh":"學校旅行應該有趣，但最重要的是，它應該安全。"},{"en":"In an emergency, most importantly, people should call for trained help.","zh":"在緊急情況中，最重要的是人們應呼叫受訓人員幫助。"},{"en":"Most importantly, Adrian treated Lee as a person, not just a rival.","zh":"最重要的是，Adrian 把 Lee 看成一個人，而不只是對手。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"process the sudden turn","meaning":"消化突如其來的轉變","examples":[{"en":"Not everyone was able to process the sudden turn calmly.","zh":"不是每個人都能冷靜消化這個突如其來的轉變。"},{"en":"To process the sudden turn means to understand and emotionally handle an unexpected change.","zh":"消化突如其來的轉變，意思是理解並在情緒上處理意外改變。"},{"en":"Students may need time to process the sudden turn after a school event is cancelled.","zh":"學校活動取消後，學生可能需要時間消化突如其來的轉變。"},{"en":"A sudden injury can be hard to process because it changes the mood immediately.","zh":"突然受傷很難消化，因為它立即改變氣氛。"},{"en":"Some players could not process the sudden turn because they were shocked.","zh":"有些球員無法消化突如其來的轉變，因為他們很震驚。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"sudden turn","meaning":"突如其來的轉變","examples":[{"en":"The accident was a sudden turn in the match.","zh":"這次意外是比賽中的突如其來的轉變。"},{"en":"A sudden turn is an unexpected change in a situation.","zh":"突如其來的轉變，是情況中出乎意料的改變。"},{"en":"A sunny school picnic may take a sudden turn when heavy rain begins.","zh":"晴朗的學校野餐可能因大雨開始而出現突如其來的轉變。"},{"en":"Sudden turns can make people confused because plans change quickly.","zh":"突如其來的轉變會令人困惑，因為計劃迅速改變。"},{"en":"Marcus’s injury was the sudden turn that changed the whole match.","zh":"Marcus 的受傷是改變整場比賽的突如其來的轉變。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"calmly","meaning":"冷靜地","examples":[{"en":"Some players could not process the incident calmly.","zh":"有些球員無法冷靜地消化這次事件。"},{"en":"Calmly means in a quiet, steady, and controlled way.","zh":"冷靜地，意思是以安靜、穩定和受控制的方式。"},{"en":"A teacher speaks calmly when students are frightened.","zh":"當學生受驚時，老師會冷靜地說話。"},{"en":"Acting calmly helps others feel safer during an emergency.","zh":"冷靜地行動能幫助其他人在緊急情況中感到較安全。"},{"en":"Adrian responded calmly even when the field became frightening.","zh":"即使球場變得可怕，Adrian 仍冷靜地回應。"}],"source":"2019 Q4.pdf","sourcePage":10},{"front":"midfielder","meaning":"中場球員","examples":[{"en":"Jayden Fong is a St. George’s midfielder.","zh":"Jayden Fong 是 St. George’s 的中場球員。"},{"en":"A midfielder is a football player who usually works between defenders and forwards.","zh":"中場球員通常是在後衛和前鋒之間活動的足球球員。"},{"en":"A midfielder often passes the ball, supports attacks, and helps defend.","zh":"中場球員常傳球、支援進攻並協助防守。"},{"en":"If a midfielder loses control, the team may struggle to connect defence and attack.","zh":"如果中場球員失去控制，球隊可能難以連接防守和進攻。"},{"en":"Jayden was a midfielder, but in that moment he was mainly Marcus’s worried friend.","zh":"Jayden 是中場球員，但那一刻他主要是 Marcus 擔心的朋友。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"closest friend on the team","meaning":"隊中最親密的朋友","examples":[{"en":"Jayden Fong was Lee’s closest friend on the team.","zh":"Jayden Fong 是 Lee 在隊中最親密的朋友。"},{"en":"Closest friend on the team means the teammate someone trusts and knows best.","zh":"隊中最親密的朋友，是某人最信任和最熟悉的隊友。"},{"en":"A closest friend on the team may notice when a player is upset.","zh":"隊中最親密的朋友可能注意到球員心情低落。"},{"en":"Seeing an injured closest friend can make a player feel helpless.","zh":"看見隊中最親密的朋友受傷，球員可能感到無助。"},{"en":"Jayden was deeply shaken because Marcus was his closest friend on the team.","zh":"Jayden 深受震動，因為 Marcus 是他隊中最親密的朋友。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"admit that","meaning":"承認","examples":[{"en":"Fong admitted that he had felt completely helpless.","zh":"Fong 承認自己當時感到完全無助。"},{"en":"To admit that means to say honestly that something is true, often something difficult.","zh":"承認，意思是誠實說出某事是真的，通常是較難說出口的事。"},{"en":"A student may admit that they did not understand the lesson.","zh":"學生可能承認自己不明白課堂內容。"},{"en":"People admit feelings of fear or helplessness when they speak honestly after a shock.","zh":"人們在震驚後誠實說話時，會承認恐懼或無助的感覺。"},{"en":"Fong admitted that he felt helpless because the situation changed so suddenly.","zh":"Fong 承認自己感到無助，因為情況變化太突然。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"feel completely helpless","meaning":"感到完全無助","examples":[{"en":"Fong felt completely helpless after Lee collapsed.","zh":"Lee 倒下後，Fong 感到完全無助。"},{"en":"To feel completely helpless means to feel unable to do anything useful in a difficult situation.","zh":"感到完全無助，意思是在困難情況中覺得自己不能做任何有用的事。"},{"en":"A child may feel completely helpless when a friend is hurt and no adult is nearby.","zh":"當朋友受傷而附近沒有成年人，孩子可能感到完全無助。"},{"en":"People feel helpless when they care deeply but do not know what action to take.","zh":"當人們很關心但不知道如何行動，就會感到無助。"},{"en":"Fong felt completely helpless because his closest friend was on the ground.","zh":"Fong 感到完全無助，因為他最親密的朋友倒在地上。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"one moment…, the next…","meaning":"前一刻……下一刻……","examples":[{"en":"One moment they were pushing for the winning goal; the next, Marcus was on the ground.","zh":"前一刻他們還在努力爭取致勝入球；下一刻，Marcus 已倒在地上。"},{"en":"One moment…, the next… shows that a situation changed very suddenly.","zh":"前一刻……下一刻……，用來顯示情況突然改變。"},{"en":"One moment the class was laughing; the next, everyone was silent after the alarm.","zh":"前一刻全班還在笑；下一刻，警鐘響起後所有人都安靜了。"},{"en":"This structure helps show shock because two very different moments are placed together.","zh":"這個結構把兩個很不同的時刻放在一起，幫助表現震驚。"},{"en":"The sentence shows how quickly the match changed from hope to fear.","zh":"這句話顯示比賽如何迅速由希望變成恐懼。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"push for","meaning":"努力爭取","examples":[{"en":"St. George’s were pushing for the winning goal.","zh":"St. George’s 當時正在努力爭取致勝入球。"},{"en":"To push for something means to try hard to achieve it.","zh":"努力爭取某事，意思是努力嘗試達成它。"},{"en":"Students may push for more study space in the library.","zh":"學生可能努力爭取圖書館有更多自修空間。"},{"en":"A team pushes for a goal when time is running out.","zh":"當時間快完，球隊會努力爭取入球。"},{"en":"St. George’s pushed for victory until the emergency stopped the match.","zh":"St. George’s 努力爭取勝利，直到緊急情況停止比賽。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"winning goal","meaning":"致勝入球","examples":[{"en":"The team was pushing for the winning goal.","zh":"球隊正在努力爭取致勝入球。"},{"en":"A winning goal is the goal that gives a team victory.","zh":"致勝入球，是令球隊取得勝利的入球。"},{"en":"A striker may score the winning goal in the final minute.","zh":"前鋒可能在最後一分鐘射入致勝入球。"},{"en":"Teams become more urgent when they believe one winning goal can decide the match.","zh":"當球隊相信一個致勝入球可以決定比賽，他們會變得更急切。"},{"en":"The winning goal mattered less after Marcus collapsed.","zh":"Marcus 倒下後，致勝入球變得不再那麼重要。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"on the ground","meaning":"倒在地上","examples":[{"en":"Marcus was suddenly on the ground.","zh":"Marcus 突然倒在地上。"},{"en":"On the ground means lying or fallen on the surface below.","zh":"倒在地上，意思是躺在或跌在下面的地面上。"},{"en":"A player may be on the ground after being tackled.","zh":"球員被攔截後可能倒在地上。"},{"en":"When someone is on the ground and not responding, people should call for help.","zh":"當某人倒在地上而沒有反應，人們應求助。"},{"en":"Marcus being on the ground turned the match into an emergency.","zh":"Marcus 倒在地上，令比賽變成緊急情況。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"cannot thank someone enough","meaning":"對某人感激不盡","examples":[{"en":"Fong said he could not thank Adrian enough.","zh":"Fong 說他對 Adrian 感激不盡。"},{"en":"Cannot thank someone enough means feeling extremely grateful for what that person did.","zh":"對某人感激不盡，意思是對那人所做的事感到非常感激。"},{"en":"A parent may say they cannot thank a teacher enough for helping their child.","zh":"家長可能說他們對幫助孩子的老師感激不盡。"},{"en":"People use this phrase when “thank you” feels too small.","zh":"當一句「謝謝」感覺不夠，人們會使用這個短語。"},{"en":"Fong could not thank Adrian enough because Adrian helped his closest friend.","zh":"Fong 對 Adrian 感激不盡，因為 Adrian 幫助了他最親密的朋友。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"student sections","meaning":"學生打氣區","examples":[{"en":"The two student sections changed tone after the incident.","zh":"事件發生後，兩邊學生打氣區的氣氛轉變。"},{"en":"Student sections are areas where students sit or stand together to support their team.","zh":"學生打氣區，是學生聚在一起支持自己隊伍的區域。"},{"en":"Student sections may sing chants during a school football match.","zh":"學生打氣區可能在學校足球賽中唱打氣口號。"},{"en":"Student sections can affect the mood of a stadium through noise and energy.","zh":"學生打氣區可以透過聲音和活力影響球場氣氛。"},{"en":"After the injury, the student sections became quieter and more respectful.","zh":"受傷後，學生打氣區變得較安靜和尊重。"}],"source":"2019 Q4.pdf","sourcePage":11},{"front":"be famous for","meaning":"以……聞名","examples":[{"en":"The student sections were famous for trading chants.","zh":"學生打氣區以互相喊打氣口號聞名。"},{"en":"Be famous for something means to be well known because of it.","zh":"以某事聞名，意思是因某事而廣為人知。"},{"en":"A school may be famous for its music team.","zh":"一間學校可能以音樂隊聞名。"},{"en":"Being famous for loud chants can make a student section lively.","zh":"以響亮口號聞名，可以令學生打氣區很有活力。"},{"en":"The students were famous for chants, but that day they became known for respect.","zh":"學生以口號聞名，但那天他們因尊重而令人記住。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"trade chants","meaning":"互相喊打氣口號","examples":[{"en":"The two student sections usually traded chants.","zh":"兩邊學生打氣區通常互相喊打氣口號。"},{"en":"To trade chants means two groups shout songs or slogans back and forth.","zh":"互相喊打氣口號，意思是兩組人來回高喊歌曲或口號。"},{"en":"Two classes may trade chants during a sports day final.","zh":"兩個班級可能在運動日決賽中互相喊打氣口號。"},{"en":"Trading chants can be fun if it stays respectful.","zh":"如果保持尊重，互相喊打氣口號可以很有趣。"},{"en":"After Marcus was hurt, the students stopped trading chants and showed concern.","zh":"Marcus 受傷後，學生停止互相喊口號，轉而表示關心。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"change tone","meaning":"改變語氣；氣氛轉變","examples":[{"en":"The student sections changed tone after Lee was taken away.","zh":"Lee 被送走後，學生打氣區的氣氛轉變。"},{"en":"To change tone means to become different in mood, sound, or attitude.","zh":"改變語氣或氣氛轉變，意思是情緒、聲音或態度變得不同。"},{"en":"A classroom may change tone when a serious announcement is made.","zh":"當嚴肅公告發出，課室氣氛可能轉變。"},{"en":"After an accident, a cheerful event can change tone quickly.","zh":"意外發生後，歡樂活動可以迅速改變氣氛。"},{"en":"The student sections changed tone from rivalry to sympathy.","zh":"學生打氣區的氣氛由競爭轉為同情。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"chant someone’s name","meaning":"高呼某人的名字","examples":[{"en":"Royal College students started chanting Lee’s name.","zh":"Royal College 學生開始高呼 Lee 的名字。"},{"en":"To chant someone’s name means to repeat a person’s name loudly together.","zh":"高呼某人的名字，意思是一起大聲重複某人的名字。"},{"en":"Fans may chant a player’s name after a brilliant goal.","zh":"球迷可能在精彩入球後高呼球員的名字。"},{"en":"Chanting someone’s name can show support, thanks, or respect.","zh":"高呼某人的名字可以表示支持、感謝或尊重。"},{"en":"Royal College students chanted Lee’s name to show care for an injured rival.","zh":"Royal College 學生高呼 Lee 的名字，以關心受傷對手。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"be taken away","meaning":"被送走","examples":[{"en":"Lee’s name was chanted as he was taken away.","zh":"Lee 被送走時，大家高呼他的名字。"},{"en":"Be taken away means to be removed from a place, often for care or safety.","zh":"被送走，意思是被帶離某個地方，通常是為了照顧或安全。"},{"en":"An injured student may be taken away to the medical room.","zh":"受傷學生可能被送到醫療室。"},{"en":"When someone is taken away by ambulance, others may feel worried and quiet.","zh":"當有人被救護車送走，其他人可能感到擔心和安靜。"},{"en":"Lee was taken away while both sides showed support.","zh":"Lee 被送走時，雙方都表示支持。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"supporters","meaning":"支持者","examples":[{"en":"St. George’s supporters applauded Wong.","zh":"St. George’s 的支持者為 Wong 鼓掌。"},{"en":"Supporters are people who cheer for, follow, or encourage a team or person.","zh":"支持者，是為隊伍或某人打氣、關注或鼓勵的人。"},{"en":"Supporters may wear school colours during a final.","zh":"支持者可能在決賽中穿上學校顏色。"},{"en":"Supporters can show respect by applauding a rival’s brave action.","zh":"支持者可以透過為對手的勇敢行動鼓掌來表示尊重。"},{"en":"St. George’s supporters applauded Wong because he helped their player.","zh":"St. George’s 的支持者為 Wong 鼓掌，因為他幫助了他們的球員。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"leave the pitch","meaning":"離開球場","examples":[{"en":"Supporters applauded Wong when he left the pitch.","zh":"Wong 離開球場時，支持者為他鼓掌。"},{"en":"To leave the pitch means to walk off the football playing area.","zh":"離開球場，意思是走出足球比賽場地。"},{"en":"A player may leave the pitch after being substituted.","zh":"球員被換出後可能離開球場。"},{"en":"Leaving the pitch after an emotional incident can feel heavy and quiet.","zh":"在情緒化事件後離開球場，可能感覺沉重而安靜。"},{"en":"Wong left the pitch to applause from both sides.","zh":"Wong 在雙方掌聲中離開球場。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"many, if not most","meaning":"很多，甚至大多數","examples":[{"en":"Many, if not most, spectators remained in their seats.","zh":"很多，甚至大多數觀眾都留在座位上。"},{"en":"Many, if not most, means many people, and possibly the majority.","zh":"很多，甚至大多數，意思是很多人，甚至可能是大部分人。"},{"en":"Many, if not most, students felt nervous before the exam.","zh":"很多，甚至大多數學生在考試前都感到緊張。"},{"en":"This phrase lets a writer make a strong statement without claiming complete certainty.","zh":"這個短語讓作者提出強烈說法，但不聲稱完全肯定。"},{"en":"Many, if not most, spectators stayed because the incident affected them deeply.","zh":"很多，甚至大多數觀眾留下來，因為事件深深影響了他們。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"remain in their seats","meaning":"留在座位上","examples":[{"en":"Many spectators remained in their seats after the announcement.","zh":"公告後，很多觀眾仍留在座位上。"},{"en":"To remain in their seats means to stay seated instead of leaving.","zh":"留在座位上，意思是繼續坐著而不離開。"},{"en":"Students may remain in their seats after a fire drill until the teacher gives instructions.","zh":"火警演習後，學生可能留在座位上，直到老師給予指示。"},{"en":"People remain in their seats when they are shocked, worried, or waiting for more news.","zh":"當人們震驚、擔心或等待更多消息時，可能留在座位上。"},{"en":"Spectators remained in their seats because the match had become emotionally heavy.","zh":"觀眾留在座位上，因為比賽變得情緒沉重。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"long after","meaning":"在……很久之後","examples":[{"en":"Spectators stayed long after the announcement.","zh":"公告很久之後，觀眾仍然留下。"},{"en":"Long after means much later than the time something happened.","zh":"在某事很久之後，意思是在那件事發生後很長時間。"},{"en":"Students stayed in the hall long after the speech because they wanted to ask questions.","zh":"演講很久之後，學生仍留在禮堂，因為他們想提問。"},{"en":"People may remember an emotional moment long after an event ends.","zh":"人們可能在活動結束很久之後仍記得情緒化時刻。"},{"en":"The spectators remained long after the announcement because they were still processing the incident.","zh":"觀眾在公告很久之後仍留下，因為他們仍在消化事件。"}],"source":"2019 Q4.pdf","sourcePage":12},{"front":"announcement","meaning":"公告","examples":[{"en":"The spectators remained after the announcement.","zh":"公告後，觀眾仍然留下。"},{"en":"An announcement is a spoken or written message giving information to people.","zh":"公告，是向人們提供資訊的口頭或書面訊息。"},{"en":"A school announcement may tell students that a match has been postponed.","zh":"學校公告可能告訴學生比賽已延期。"},{"en":"Announcements are important when many people need the same information quickly.","zh":"當很多人需要迅速知道同一資訊時，公告很重要。"},{"en":"The announcement told spectators that the match would not continue that day.","zh":"公告告訴觀眾比賽當天不會繼續。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"unusually quiet voices","meaning":"異常安靜的聲音","examples":[{"en":"Spectators discussed the incident in unusually quiet voices.","zh":"觀眾用異常安靜的聲音討論這次事件。"},{"en":"Unusually quiet voices means voices that are much softer than normal because people feel serious or shocked.","zh":"異常安靜的聲音，意思是因人們嚴肅或震驚而比平常小聲得多。"},{"en":"Students spoke in unusually quiet voices after hearing sad news.","zh":"聽到傷心消息後，學生用異常安靜的聲音說話。"},{"en":"People use unusually quiet voices when they do not want to disturb a serious moment.","zh":"人們在不想打擾嚴肅時刻時，會使用異常安靜的聲音。"},{"en":"The spectators’ unusually quiet voices showed how deeply the incident affected them.","zh":"觀眾異常安靜的聲音顯示事件深深影響了他們。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"in a statement released last night","meaning":"在昨晚發出的聲明中","examples":[{"en":"In a statement released last night, the school said Lee was stable.","zh":"在昨晚發出的聲明中，學校表示 Lee 情況穩定。"},{"en":"In a statement released last night means in an official message made public the previous evening.","zh":"在昨晚發出的聲明中，意思是在前一晚公開的正式訊息中。"},{"en":"In a statement released last night, the club explained why practice was cancelled.","zh":"在昨晚發出的聲明中，學會解釋為何練習取消。"},{"en":"Schools release statements after serious incidents to inform families clearly.","zh":"學校在嚴重事件後發出聲明，以清楚通知家庭。"},{"en":"The statement released last night gave people important news about Lee’s condition.","zh":"昨晚發出的聲明給人們關於 Lee 情況的重要消息。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"released last night","meaning":"昨晚發出","examples":[{"en":"The statement was released last night.","zh":"這份聲明昨晚發出。"},{"en":"Released last night means made public during the previous evening.","zh":"昨晚發出，意思是在前一晚公開發布。"},{"en":"The school timetable was released last night, so students checked it this morning.","zh":"學校時間表昨晚發出，所以學生今早查看。"},{"en":"Information released last night may calm people who are waiting for news.","zh":"昨晚發出的資訊可能安撫正在等待消息的人。"},{"en":"The statement released last night said Lee was stable.","zh":"昨晚發出的聲明表示 Lee 情況穩定。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"in stable condition","meaning":"情況穩定","examples":[{"en":"Lee was in stable condition after the incident.","zh":"事件後，Lee 情況穩定。"},{"en":"In stable condition means a patient’s condition is not getting worse at that time.","zh":"情況穩定，意思是病人的狀況當時沒有惡化。"},{"en":"A hospital may say a patient is in stable condition after treatment.","zh":"醫院可能在治療後表示病人情況穩定。"},{"en":"Being in stable condition is reassuring, but doctors may still continue checks.","zh":"情況穩定令人安心，但醫生可能仍會繼續檢查。"},{"en":"Lee was in stable condition, so supporters felt some relief.","zh":"Lee 情況穩定，所以支持者感到稍為放心。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"remain under observation","meaning":"留院觀察","examples":[{"en":"Lee would remain under observation.","zh":"Lee 將會留院觀察。"},{"en":"To remain under observation means to stay where medical staff can watch and check your condition.","zh":"留院觀察，意思是留在醫護人員能監察和檢查情況的地方。"},{"en":"A patient may remain under observation after a head injury.","zh":"頭部受傷後，病人可能需要留院觀察。"},{"en":"Doctors keep people under observation when symptoms may change later.","zh":"當症狀之後可能改變，醫生會安排病人留院觀察。"},{"en":"Lee remained under observation to make sure his condition stayed stable.","zh":"Lee 留院觀察，以確保情況保持穩定。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"send a short message through","meaning":"透過……發出簡短訊息","examples":[{"en":"Lee sent a short message through his coach.","zh":"Lee 透過教練發出簡短訊息。"},{"en":"To send a short message through someone means to pass a brief message by using that person as the messenger.","zh":"透過某人發出簡短訊息，意思是由那個人代為傳達簡短訊息。"},{"en":"A student may send a short message through a teacher if they cannot speak to the class directly.","zh":"如果學生不能直接向全班說話，可能透過老師發出簡短訊息。"},{"en":"People send messages through others when they are resting or unavailable.","zh":"當人們正在休息或無法出面時，會透過別人傳話。"},{"en":"Lee sent a message through his coach to thank everyone who helped.","zh":"Lee 透過教練發出訊息，感謝所有幫助過他的人。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"everyone who helped me","meaning":"所有幫助過我的人","examples":[{"en":"Lee thanked everyone who helped him.","zh":"Lee 感謝所有幫助過他的人。"},{"en":"Everyone who helped me means all the people who gave support, care, or action.","zh":"所有幫助過我的人，意思是所有提供支援、照顧或行動的人。"},{"en":"After a school event, a student may thank everyone who helped prepare it.","zh":"學校活動後，學生可能感謝所有幫助籌備的人。"},{"en":"Thanking everyone who helped shows gratitude to both visible and quiet helpers.","zh":"感謝所有幫助過的人，顯示對明顯和默默幫忙者的感激。"},{"en":"Lee thanked everyone who helped him, including Adrian and the medical team.","zh":"Lee 感謝所有幫助過他的人，包括 Adrian 和醫療隊。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"a legend","meaning":"傳奇人物；非常了不起的人","examples":[{"en":"Lee called Adrian a legend.","zh":"Lee 稱 Adrian 是非常了不起的人。"},{"en":"A legend can mean someone who is greatly admired for doing something impressive or kind.","zh":"傳奇人物或非常了不起的人，可以指因做了令人佩服或善良的事而受欣賞的人。"},{"en":"Students may call a classmate a legend after they save a group project.","zh":"同學救回小組專題後，學生可能稱他是非常了不起的人。"},{"en":"Calling someone a legend shows warm praise, not only formal respect.","zh":"稱某人是 legend 表示親切讚賞，不只是正式尊重。"},{"en":"Lee called Adrian a legend because Adrian helped him in a frightening moment.","zh":"Lee 稱 Adrian 是非常了不起的人，因為 Adrian 在可怕時刻幫助了他。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"once the dust settles","meaning":"待事情平息後","examples":[{"en":"Once the dust settles, the league title will still have to be decided.","zh":"待事情平息後，聯賽冠軍仍須決定。"},{"en":"Once the dust settles means after confusion, emotion, or conflict has calmed down.","zh":"待事情平息後，意思是混亂、情緒或衝突冷靜下來之後。"},{"en":"Once the dust settles after exams, students can think about their next goals.","zh":"考試過後待事情平息，學生可以思考下一個目標。"},{"en":"People make clearer decisions once the dust settles.","zh":"待事情平息後，人們能作出更清晰決定。"},{"en":"Once the dust settles after the injury, the teams will return to decide the title.","zh":"受傷事件平息後，兩隊將回來決定冠軍。"}],"source":"2019 Q4.pdf","sourcePage":13},{"front":"have to be decided","meaning":"仍須決定","examples":[{"en":"The league title will still have to be decided.","zh":"聯賽冠軍仍須決定。"},{"en":"Have to be decided means a final answer or result still needs to be determined.","zh":"仍須決定，意思是最終答案或結果仍需要被判定。"},{"en":"The winner will have to be decided after the last race.","zh":"冠軍將在最後一場賽跑後仍須決定。"},{"en":"If a match is suspended, the result may have to be decided later.","zh":"如果比賽被暫停，結果可能要之後才決定。"},{"en":"The league title still had to be decided, but the defining moment had already happened.","zh":"聯賽冠軍仍須決定，但最具代表性的時刻已經發生。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"whatever happens","meaning":"無論發生甚麼","examples":[{"en":"Whatever happens next Saturday, the match has already produced its defining image.","zh":"無論下星期六發生甚麼，這場比賽已經產生了最具代表性的畫面。"},{"en":"Whatever happens means no matter what takes place.","zh":"無論發生甚麼，意思是不管出現甚麼情況。"},{"en":"Whatever happens in the exam, students should stay calm and do their best.","zh":"無論考試發生甚麼，學生都應保持冷靜並盡力。"},{"en":"This phrase shows that one truth remains even if the future result changes.","zh":"這個短語顯示，即使未來結果改變，某個事實仍然存在。"},{"en":"Whatever happens in the resumed match, Adrian’s action will be remembered.","zh":"無論恢復比賽時發生甚麼，Adrian 的行動都會被記住。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"meet again","meaning":"再次交手","examples":[{"en":"The rivals will meet again next Saturday.","zh":"對手將於下星期六再次交手。"},{"en":"To meet again means to face or see each other another time.","zh":"再次交手，意思是再次面對或碰頭。"},{"en":"Two debate teams may meet again in the final round.","zh":"兩支辯論隊可能在決賽再次交手。"},{"en":"Rivals meet again when a postponed match resumes.","zh":"當延期比賽恢復，對手就會再次交手。"},{"en":"The teams will meet again, but the atmosphere may be different after the incident.","zh":"兩隊將再次交手，但事件後氣氛可能不同。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"defining image","meaning":"最具代表性的畫面","examples":[{"en":"The match has already produced its defining image.","zh":"這場比賽已經產生了最具代表性的畫面。"},{"en":"A defining image is the picture or moment that best represents an event.","zh":"最具代表性的畫面，是最能代表一件事的畫面或時刻。"},{"en":"The defining image of a school concert may be students singing together on stage.","zh":"學校音樂會最具代表性的畫面，可能是學生一起在台上唱歌。"},{"en":"A defining image stays in people’s memory because it captures the meaning of the event.","zh":"最具代表性的畫面會留在人們記憶中，因為它捕捉了事件的意義。"},{"en":"The defining image of this match was a captain kneeling beside an injured rival.","zh":"這場比賽最具代表性的畫面，是一名隊長跪在受傷對手旁邊。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"kneeling beside","meaning":"跪在……旁邊","examples":[{"en":"The defining image was a captain kneeling beside an injured rival.","zh":"最具代表性的畫面是一名隊長跪在受傷對手旁邊。"},{"en":"Kneeling beside someone means being on one’s knees next to that person.","zh":"跪在某人旁邊，意思是在某人身旁跪下。"},{"en":"A parent kneeling beside a child can make the child feel safer.","zh":"家長跪在孩子旁邊，可以令孩子感到更安全。"},{"en":"Kneeling beside an injured rival showed care, not weakness.","zh":"跪在受傷對手旁邊顯示關心，而不是軟弱。"},{"en":"Adrian kneeling beside Marcus became the image people remembered.","zh":"Adrian 跪在 Marcus 旁邊，成為人們記住的畫面。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"prove that","meaning":"證明","examples":[{"en":"The moment proved that rivalry can leave room for humanity.","zh":"那一刻證明競爭仍可以為人情味留下空間。"},{"en":"To prove that means to show clearly that something is true.","zh":"證明，意思是清楚顯示某事是真實的。"},{"en":"A student’s careful work can prove that practice really helps.","zh":"學生細心的作品可以證明練習真的有幫助。"},{"en":"Actions often prove values more strongly than words.","zh":"行動通常比言語更有力地證明價值觀。"},{"en":"Adrian’s action proved that opponents can still care for each other.","zh":"Adrian 的行動證明對手仍可以互相關心。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"the fiercest rivalry","meaning":"最激烈的競爭","examples":[{"en":"The fiercest rivalry can still leave room for humanity.","zh":"最激烈的競爭仍可以為人情味留下空間。"},{"en":"The fiercest rivalry means the strongest and most intense competition.","zh":"最激烈的競爭，意思是最強烈、最緊張的競爭。"},{"en":"Two schools may have the fiercest rivalry during a championship match.","zh":"兩間學校可能在冠軍賽中有最激烈的競爭。"},{"en":"Even the fiercest rivalry should stop when someone is hurt.","zh":"即使是最激烈的競爭，當有人受傷時也應停止。"},{"en":"This incident showed that the fiercest rivalry does not have to erase kindness.","zh":"這次事件顯示，最激烈的競爭不必抹走善意。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"leave room for","meaning":"為……留下空間","examples":[{"en":"Even the fiercest rivalry can leave room for humanity.","zh":"即使最激烈的競爭，也可以為人情味留下空間。"},{"en":"To leave room for something means to allow space for it to exist.","zh":"為某事留下空間，意思是容許它存在。"},{"en":"A busy timetable should leave room for rest.","zh":"忙碌時間表應為休息留下空間。"},{"en":"Healthy competition leaves room for respect and fairness.","zh":"健康競爭會為尊重和公平留下空間。"},{"en":"Adrian’s action showed that rivalry can leave room for care.","zh":"Adrian 的行動顯示，競爭可以為關心留下空間。"}],"source":"2019 Q4.pdf","sourcePage":14},{"front":"humanity","meaning":"人性；人情味","examples":[{"en":"The incident showed humanity beyond rivalry.","zh":"這次事件顯示了超越競爭的人情味。"},{"en":"Humanity means kindness, care, and respect for people as human beings.","zh":"人性或人情味，是指把人當作人來看待的善意、關心和尊重。"},{"en":"A student shows humanity when they help a classmate who is being left out.","zh":"當學生幫助被排斥的同學，就是表現人情味。"},{"en":"Humanity matters most when rules and competition are not enough.","zh":"當規則和競爭不足夠時，人情味最重要。"},{"en":"Adrian’s response showed humanity because he saw a person in need, not just a rival.","zh":"Adrian 的反應展現人情味，因為他看見的是需要幫助的人，而不只是對手。"}],"source":"2019 Q4.pdf","sourcePage":14}],"dse/writing/part-b/2019/Q5":[{"front":"beyond the scroll","meaning":"不止於滑手機瀏覽","examples":[{"en":"The essay is about following pop culture beyond the scroll.","zh":"這篇文章是關於不止於滑手機瀏覽地追蹤流行文化。"},{"en":"Beyond the scroll means looking past quick social-media browsing to understand something more deeply.","zh":"beyond the scroll 指超越快速滑社交媒體的瀏覽，去更深入理解某事。"},{"en":"A student goes beyond the scroll when she reads a full review after seeing a short fashion video.","zh":"學生看完一段時裝短片後再讀完整評論，就是不止於滑手機瀏覽。"},{"en":"Going beyond the scroll can stop people from copying trends without thinking.","zh":"不止於滑手機瀏覽可以阻止人不加思考地模仿潮流。"},{"en":"Pop culture becomes more meaningful when we go beyond the scroll and ask why it matters.","zh":"當我們不止於滑手機瀏覽，並追問它為何重要，流行文化會變得更有意義。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"follow fashion and music","meaning":"關注時裝和音樂潮流","examples":[{"en":"The writer explains how to follow fashion and music wisely.","zh":"作者解釋如何明智地關注時裝和音樂潮流。"},{"en":"To follow fashion and music means to pay attention to current styles, songs, artists, and trends.","zh":"follow fashion and music 指留意當下的風格、歌曲、歌手和潮流。"},{"en":"Teenagers may follow fashion and music through short videos, playlists, magazines, and friends.","zh":"青少年可能透過短片、播放清單、雜誌和朋友關注時裝和音樂潮流。"},{"en":"If people follow fashion and music without thinking, they may waste money on every new trend.","zh":"如果人們不加思考地關注時裝和音樂潮流，可能會把錢浪費在每個新潮流上。"},{"en":"It is possible to follow fashion and music while still keeping your own taste.","zh":"一個人可以關注時裝和音樂潮流，同時仍保留自己的品味。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"without losing my head","meaning":"不失去理性；不被衝昏頭腦","examples":[{"en":"She wants to follow trends without losing her head.","zh":"她想追蹤潮流，但不失去理性。"},{"en":"Without losing my head means staying calm and sensible instead of becoming too excited or confused.","zh":"without losing my head 指保持冷靜和理智，而不是變得太興奮或混亂。"},{"en":"I can enjoy a big sale without losing my head if I buy only what I need.","zh":"如果我只買需要的東西，我就可以享受大減價而不被衝昏頭腦。"},{"en":"When a product goes viral, people may lose their heads and order it immediately.","zh":"當一件產品爆紅時，人們可能會失去理性，立刻下單。"},{"en":"Following trends without losing your head means liking new things but still thinking clearly.","zh":"不失去理性地追蹤潮流，意思是喜歡新事物，但仍然清晰思考。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"for better or worse","meaning":"不論好壞；無論利弊","examples":[{"en":"For better or worse, pop culture no longer waits for newspapers.","zh":"不論好壞，流行文化不再等待報紙。"},{"en":"For better or worse means whether the result is good or bad.","zh":"for better or worse 指無論結果是好是壞。"},{"en":"For better or worse, students now learn news from phones before teachers discuss it.","zh":"不論好壞，學生現在會在老師討論前先從手機得知新聞。"},{"en":"Social media spreads trends quickly, for better or worse.","zh":"社交媒體迅速傳播潮流，無論利弊。"},{"en":"This phrase is useful when a change has both advantages and risks.","zh":"當一種改變同時有好處和風險時，這個短語很有用。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"pop culture","meaning":"流行文化","examples":[{"en":"Pop culture now moves faster than traditional media.","zh":"流行文化現在比傳統媒體走得更快。"},{"en":"Pop culture means the music, fashion, films, shows, memes, and ideas many people enjoy at a certain time.","zh":"pop culture 指某個時期許多人喜歡的音樂、時裝、電影、節目、迷因和想法。"},{"en":"A popular dance challenge can become part of pop culture within days.","zh":"一個受歡迎的舞蹈挑戰可以在幾天內成為流行文化的一部分。"},{"en":"Pop culture changes quickly because young people share videos and opinions online.","zh":"流行文化變化很快，因為年輕人在網上分享影片和意見。"},{"en":"Studying pop culture can help us understand what people value, joke about, and discuss.","zh":"研究流行文化可以幫助我們了解人們重視、開玩笑和討論甚麼。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"no longer waits for","meaning":"不再等待","examples":[{"en":"Pop culture no longer waits for Saturday newspapers.","zh":"流行文化不再等待星期六報紙。"},{"en":"No longer waits for means something does not depend on another thing before happening.","zh":"no longer waits for 指某事不再依賴另一件事才發生。"},{"en":"News no longer waits for the evening broadcast because people receive alerts instantly.","zh":"新聞不再等待晚間廣播，因為人們即時收到通知。"},{"en":"Fashion no longer waits for magazines when influencers post outfits every day.","zh":"當網紅每天發布穿搭，時裝不再等待雜誌。"},{"en":"This phrase shows that speed and control have changed.","zh":"這個短語顯示速度和控制權已經改變。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"Saturday newspapers","meaning":"星期六報紙","examples":[{"en":"Fashion news no longer waits for Saturday newspapers.","zh":"時裝新聞不再等待星期六報紙。"},{"en":"Saturday newspapers are weekend printed newspapers that often include longer lifestyle or culture sections.","zh":"Saturday newspapers 指週末出版的印刷報紙，常有較長的生活或文化版面。"},{"en":"In the past, readers might wait for Saturday newspapers to learn about new films or fashion.","zh":"過去，讀者可能等待星期六報紙來了解新電影或時裝。"},{"en":"If trends move online first, Saturday newspapers may feel slower but more thoughtful.","zh":"如果潮流先在網上流動，星期六報紙可能顯得較慢，但也較有深度。"},{"en":"The phrase suggests an older rhythm of receiving cultural information.","zh":"這個短語暗示一種較舊的文化資訊接收節奏。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"monthly magazines","meaning":"月刊","examples":[{"en":"Trends can spread before they appear in monthly magazines.","zh":"潮流可以在出現在月刊之前已經傳開。"},{"en":"Monthly magazines are magazines published once a month.","zh":"monthly magazines 指每月出版一次的雜誌。"},{"en":"A beauty trend may already be popular online before monthly magazines write about it.","zh":"美容潮流可能在月刊報道前已經在網上流行。"},{"en":"Monthly magazines are slower than short videos, but they can explain trends more carefully.","zh":"月刊比短片慢，但可以更仔細地解釋潮流。"},{"en":"This phrase shows the difference between fast discovery and slower judgement.","zh":"這個短語顯示快速發現和較慢判斷之間的差別。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"lipstick shade","meaning":"唇膏色號","examples":[{"en":"A lipstick shade can go viral very quickly.","zh":"一個唇膏色號可以很快在網上爆紅。"},{"en":"A lipstick shade is a particular colour of lipstick.","zh":"lipstick shade 指某一種特定的唇膏顏色。"},{"en":"A soft pink lipstick shade may become popular because many people find it easy to wear.","zh":"柔和粉紅色的唇膏色號可能會流行，因為很多人覺得容易配搭。"},{"en":"When a celebrity uses one lipstick shade, shops may sell out of that colour.","zh":"當名人使用某個唇膏色號，商店可能會賣光那個顏色。"},{"en":"In beauty culture, a small detail like a lipstick shade can create a large trend.","zh":"在美容文化中，像唇膏色號這樣的小細節也可以形成大潮流。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"go viral","meaning":"在網上爆紅；瘋傳","examples":[{"en":"A lipstick shade can go viral before the model leaves the lift.","zh":"一個唇膏色號可以在模特兒離開升降機前就在網上爆紅。"},{"en":"To go viral means to spread very quickly online through shares, likes, and reposts.","zh":"go viral 指透過分享、點讚和轉發在網上迅速傳開。"},{"en":"A funny school video can go viral overnight if many students share it.","zh":"如果很多學生分享，一段有趣的校園影片可以一夜之間爆紅。"},{"en":"When a product goes viral, people may buy it before checking whether it suits them.","zh":"當一件產品爆紅，人們可能在確認是否適合自己前就購買。"},{"en":"Going viral brings attention, but it does not always mean something has lasting value.","zh":"在網上爆紅會帶來注意，但不一定代表某事有長久價值。"}],"source":"2019 Q5.pdf","sourcePage":1},{"front":"before the model leaves the lift","meaning":"在模特兒離開升降機前","examples":[{"en":"The trend can spread before the model leaves the lift.","zh":"潮流可以在模特兒離開升降機前傳開。"},{"en":"Before the model leaves the lift means extremely quickly, almost immediately after people see the look.","zh":"before the model leaves the lift 指速度極快，幾乎在人們看到造型後立即發生。"},{"en":"A celebrity’s outfit may become a trend before she leaves the lift at an event.","zh":"名人在活動中的穿搭可能在她離開升降機前已成為潮流。"},{"en":"This phrase shows how fast social media can turn a tiny moment into public attention.","zh":"這個短語顯示社交媒體能多快把一個小瞬間變成公眾焦點。"},{"en":"It suggests that fashion now moves faster than traditional reporting can follow.","zh":"它暗示時裝現在走得比傳統報道更快。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"acoustic clip","meaning":"原音片段","examples":[{"en":"A singer’s acoustic clip can make a quiet song famous.","zh":"歌手的原音片段可以令一首安靜的歌曲成名。"},{"en":"An acoustic clip is a short video or audio recording with simple, mostly non-electronic instruments.","zh":"acoustic clip 指以簡單、主要非電子樂器演出的短影片或音訊。"},{"en":"A guitarist may post an acoustic clip of a new song from her bedroom.","zh":"結他手可能從睡房發布一段新歌的原音片段。"},{"en":"Acoustic clips can make listeners focus on the singer’s voice and lyrics.","zh":"原音片段可以令聽眾集中在歌手的聲音和歌詞上。"},{"en":"A short acoustic clip may feel more honest than a heavily produced music video.","zh":"一段短短的原音片段可能比大量製作的音樂影片更真誠。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"turn something into","meaning":"把……變成","examples":[{"en":"A short video can turn a quiet song into everyone’s homework soundtrack.","zh":"一段短片可以把一首安靜的歌曲變成大家做功課時的背景音樂。"},{"en":"To turn something into another thing means to change it into a new form or role.","zh":"turn something into another thing 指把某物改變成新的形式或角色。"},{"en":"A teacher can turn a boring grammar point into a useful game.","zh":"老師可以把沉悶的文法重點變成有用的遊戲。"},{"en":"Social media can turn a private joke into a public trend.","zh":"社交媒體可以把私人笑話變成公共潮流。"},{"en":"This phrase is useful when one action changes how people see or use something.","zh":"當一個行動改變人們如何看待或使用某物時，這個短語很有用。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"quiet song","meaning":"安靜的歌曲","examples":[{"en":"A quiet song can become popular overnight.","zh":"一首安靜的歌曲可以一夜之間流行。"},{"en":"A quiet song is soft, calm, and not loud or dramatic.","zh":"quiet song 指柔和、平靜、不吵鬧或不誇張的歌曲。"},{"en":"Students may play a quiet song while reading because it does not distract them.","zh":"學生閱讀時可能播放安靜的歌曲，因為它不會令人分心。"},{"en":"A quiet song can feel powerful when the lyrics are honest.","zh":"如果歌詞真誠，一首安靜的歌曲也可以很有力量。"},{"en":"In pop culture, even a quiet song can spread widely if people connect with its mood.","zh":"在流行文化中，如果人們連結到它的氣氛，安靜的歌曲也可以廣泛傳播。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"homework soundtrack","meaning":"做功課時的背景音樂","examples":[{"en":"The song became everyone’s homework soundtrack overnight.","zh":"那首歌一夜之間變成大家做功課時的背景音樂。"},{"en":"A homework soundtrack is music people play in the background while doing homework.","zh":"homework soundtrack 指人們做功課時在背景播放的音樂。"},{"en":"Some students choose a calm homework soundtrack to help them focus.","zh":"有些學生會選擇平靜的做功課背景音樂來幫助集中。"},{"en":"A song may become a homework soundtrack when it is relaxing but not too distracting.","zh":"當一首歌令人放鬆但不太分心，它可能成為做功課時的背景音樂。"},{"en":"This phrase shows how pop culture enters ordinary student life.","zh":"這個短語顯示流行文化如何進入普通學生生活。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"overnight","meaning":"一夜之間","examples":[{"en":"A quiet song can become popular overnight.","zh":"一首安靜的歌曲可以一夜之間流行。"},{"en":"Overnight means very quickly, often within one night or a very short time.","zh":"overnight 指非常快速，常是在一晚或很短時間內。"},{"en":"The café became famous overnight after a food blogger posted about it.","zh":"美食博客發布帖文後，那間咖啡店一夜之間成名。"},{"en":"A trend that appears overnight may disappear just as quickly.","zh":"一夜之間出現的潮流，也可能同樣快地消失。"},{"en":"This word shows sudden change, especially in online culture.","zh":"這個詞顯示突然的變化，尤其是在網上文化中。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"young readers like me","meaning":"像我這樣的年輕讀者","examples":[{"en":"This change has made young readers like me look for wiser sources.","zh":"這種改變令像我這樣的年輕讀者尋找更明智的資訊來源。"},{"en":"Young readers like me means young people who read, think, and choose information in a similar way to the writer.","zh":"young readers like me 指像作者一樣閱讀、思考和選擇資訊的年輕人。"},{"en":"Young readers like me often meet pop culture first through phones.","zh":"像我這樣的年輕讀者常先透過手機接觸流行文化。"},{"en":"If young readers like me rely only on short videos, we may miss deeper explanations.","zh":"如果像我這樣的年輕讀者只依賴短片，我們可能會錯過更深入的解釋。"},{"en":"This phrase makes the essay personal and shows the writer belongs to the group she discusses.","zh":"這個短語令文章更個人化，並顯示作者屬於她討論的群體。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"a wiser way to","meaning":"更明智地……的方法","examples":[{"en":"The writer looks for a wiser way to follow trends.","zh":"作者尋找更明智地追蹤潮流的方法。"},{"en":"A wiser way to do something is a more thoughtful and sensible method.","zh":"a wiser way to do something 指更有思考、更理智的做法。"},{"en":"A wiser way to shop is to compare prices before buying.","zh":"更明智地購物的方法是在購買前比較價格。"},{"en":"A wiser way to use social media is to enjoy it without believing everything immediately.","zh":"更明智地使用社交媒體的方法是享受它，但不立刻相信所有內容。"},{"en":"This phrase suggests improvement, not complete rejection.","zh":"這個短語暗示改進，而不是完全拒絕。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"follow trends","meaning":"追蹤潮流","examples":[{"en":"Young readers need a wiser way to follow trends.","zh":"年輕讀者需要更明智地追蹤潮流的方法。"},{"en":"To follow trends means to notice and sometimes join what is becoming popular.","zh":"follow trends 指留意並有時參與正在流行的事物。"},{"en":"Students follow trends when they try a new hairstyle many classmates like.","zh":"當學生嘗試很多同學喜歡的新髮型時，就是在追蹤潮流。"},{"en":"Following trends can be fun, but it may become expensive if people copy everything.","zh":"追蹤潮流可以很有趣，但如果人們甚麼都模仿，可能會變得昂貴。"},{"en":"The best way to follow trends is to choose what fits your life and values.","zh":"追蹤潮流的最佳方法，是選擇適合自己生活和價值觀的東西。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"not just to seem fashionable","meaning":"不只是為了顯得時尚","examples":[{"en":"She follows trends not just to seem fashionable.","zh":"她追蹤潮流，不只是為了顯得時尚。"},{"en":"Not just to seem fashionable means fashion is not the only or main reason for doing something.","zh":"not just to seem fashionable 指時尚外表不是做某事的唯一或主要原因。"},{"en":"A student may wear second-hand clothes not just to seem fashionable, but to reduce waste.","zh":"學生穿二手衣服可能不只是為了顯得時尚，而是為了減少浪費。"},{"en":"People who dress well not just to seem fashionable may use style to express identity.","zh":"穿得好看但不只是為了顯得時尚的人，可能用風格表達身份。"},{"en":"This phrase separates shallow appearance from deeper purpose.","zh":"這個短語把表面的外觀與更深層的目的分開。"}],"source":"2019 Q5.pdf","sourcePage":2},{"front":"enjoy culture","meaning":"享受文化","examples":[{"en":"She wants to enjoy culture without being controlled by the algorithm.","zh":"她想享受文化，而不被推薦算法控制。"},{"en":"To enjoy culture means to take pleasure in music, fashion, films, art, stories, and shared ideas.","zh":"enjoy culture 指從音樂、時裝、電影、藝術、故事和共同想法中得到樂趣。"},{"en":"Families enjoy culture when they attend festivals, watch films, or cook traditional food together.","zh":"家人一起參加節日、看電影或煮傳統食物時，就是在享受文化。"},{"en":"People enjoy culture more deeply when they understand the meaning behind it.","zh":"當人們理解文化背後的意義，就能更深入地享受文化。"},{"en":"Enjoying culture should involve choice, curiosity, and personal judgement.","zh":"享受文化應該包括選擇、好奇心和個人判斷。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"become a puppet of","meaning":"成為……的傀儡","examples":[{"en":"Young people should not become puppets of the algorithm.","zh":"年輕人不應成為推薦算法的傀儡。"},{"en":"To become a puppet of something means to let it control your choices too much.","zh":"become a puppet of something 指讓某事過度控制自己的選擇。"},{"en":"A shopper becomes a puppet of advertising if every poster makes him buy something.","zh":"如果每張海報都令一個購物者買東西，他就成為廣告的傀儡。"},{"en":"Students may become puppets of peer pressure when they follow friends without thinking.","zh":"當學生不加思考地跟隨朋友，他們可能成為同儕壓力的傀儡。"},{"en":"The phrase warns that people can lose control while believing they are choosing freely.","zh":"這個短語警告人們可能在以為自己自由選擇時失去控制。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"the algorithm","meaning":"推薦算法","examples":[{"en":"The algorithm can influence what young people watch and buy.","zh":"推薦算法可以影響年輕人觀看和購買甚麼。"},{"en":"The algorithm is the system that chooses what content users see online based on data and behaviour.","zh":"the algorithm 是根據數據和行為選擇用戶在網上看到甚麼內容的系統。"},{"en":"The algorithm may show more make-up videos after you like one beauty post.","zh":"當你讚好一個美容帖文後，推薦算法可能會顯示更多化妝影片。"},{"en":"If people trust the algorithm too much, they may see only similar ideas.","zh":"如果人們太相信推薦算法，他們可能只看到相似想法。"},{"en":"Understanding the algorithm helps users become more active, careful viewers.","zh":"理解推薦算法能幫助用戶成為更主動、更謹慎的觀看者。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"neither...nor...alone","meaning":"既不是單靠……也不是單靠……","examples":[{"en":"Her answer is neither old media nor new media alone.","zh":"她的答案既不是單靠舊媒體，也不是單靠新媒體。"},{"en":"Neither old media nor new media alone means not only one side is enough by itself.","zh":"neither old media nor new media alone 指兩邊任何一方單獨都不足夠。"},{"en":"A good student uses neither textbooks nor online videos alone, but combines both.","zh":"好學生既不是單靠課本，也不是單靠網上影片，而是結合兩者。"},{"en":"Healthy news reading needs neither speed nor depth alone; it needs both.","zh":"健康地閱讀新聞既不能單靠速度，也不能單靠深度；兩者都需要。"},{"en":"This structure shows that the writer rejects a simple either-or choice.","zh":"這個結構顯示作者拒絕簡單的二選一。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"old media","meaning":"舊媒體；傳統媒體","examples":[{"en":"Old media still helps readers judge cultural trends.","zh":"舊媒體仍然幫助讀者判斷文化潮流。"},{"en":"Old media means traditional forms of communication such as newspapers, magazines, radio, and television.","zh":"old media 指報紙、雜誌、電台和電視等傳統傳播形式。"},{"en":"Old media may be slower, but it often offers editing, fact-checking, and expert voices.","zh":"舊媒體可能較慢，但常提供編輯、事實查核和專家聲音。"},{"en":"Readers use old media when they read a magazine review before buying a product.","zh":"讀者在購買產品前閱讀雜誌評論，就是在使用舊媒體。"},{"en":"In the essay, old media gives depth that quick posts may lack.","zh":"在文章中，舊媒體提供快速帖文可能缺少的深度。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"new media","meaning":"新媒體","examples":[{"en":"New media helps readers spot trends quickly.","zh":"新媒體幫助讀者快速察覺潮流。"},{"en":"New media means digital platforms such as social media, streaming apps, websites, and online videos.","zh":"new media 指社交媒體、串流應用程式、網站和網上影片等數碼平台。"},{"en":"New media can show a fashion trend while people are still wearing it in the street.","zh":"新媒體可以在人們仍在街上穿着某種風格時展示時裝潮流。"},{"en":"Because new media moves fast, users need to check information carefully.","zh":"因為新媒體走得很快，用戶需要仔細核實資訊。"},{"en":"In the essay, new media gives immediacy, colour, and surprise.","zh":"在文章中，新媒體提供即時性、色彩和驚喜。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"style and beauty","meaning":"造型與美容","examples":[{"en":"For style and beauty, she prefers a mix of sources.","zh":"說到造型與美容，她較喜歡混合使用不同資訊來源。"},{"en":"Style and beauty means fashion, make-up, skincare, hair, and personal appearance.","zh":"style and beauty 指時裝、化妝、護膚、髮型和個人外觀。"},{"en":"A student interested in style and beauty may watch tutorials but also read product reviews.","zh":"對造型與美容有興趣的學生可能觀看教學影片，也閱讀產品評論。"},{"en":"Style and beauty trends can be fun, but they may pressure people to buy too much.","zh":"造型與美容潮流可以很有趣，但也可能迫使人買太多東西。"},{"en":"A thoughtful approach to style and beauty asks what is useful, affordable, and personal.","zh":"對造型與美容的深思熟慮方法，會問甚麼有用、負擔得起和適合自己。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"music and concerts","meaning":"音樂與演唱會","examples":[{"en":"For music and concerts, she uses both reviews and live clips.","zh":"說到音樂與演唱會，她同時使用評論和現場片段。"},{"en":"Music and concerts refers to songs, artists, albums, performances, and live shows.","zh":"music and concerts 指歌曲、歌手、專輯、表演和現場演出。"},{"en":"Fans follow music and concerts through playlists, reviews, ticket news, and performance videos.","zh":"歌迷透過播放清單、評論、門票消息和表演影片關注音樂與演唱會。"},{"en":"Reviews can explain the music, while concert clips show whether the artist performs well live.","zh":"評論可以解釋音樂，而演唱會片段顯示歌手現場表現是否出色。"},{"en":"Combining sources helps listeners enjoy music and concerts with better judgement.","zh":"結合資訊來源能幫助聽眾更有判斷地享受音樂與演唱會。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"a mixed menu","meaning":"混合選擇","examples":[{"en":"Her answer is a mixed menu of videos, magazines and reviews.","zh":"她的答案是由影片、雜誌和評論組成的混合選擇。"},{"en":"A mixed menu means a varied choice of different sources or options.","zh":"a mixed menu 指由不同來源或選項組成的多元選擇。"},{"en":"A healthy lunch may use a mixed menu of rice, vegetables, meat, and fruit.","zh":"健康午餐可能是米飯、蔬菜、肉類和水果的混合選擇。"},{"en":"A mixed menu of media helps readers avoid depending on one narrow source.","zh":"混合媒體選擇幫助讀者避免依賴單一狹窄來源。"},{"en":"This phrase suggests balance rather than choosing only old or new media.","zh":"這個短語暗示平衡，而不是只選舊媒體或新媒體。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"quick videos","meaning":"短片；快速影片","examples":[{"en":"Quick videos help her spot what is moving.","zh":"短片幫助她察覺正在流行的東西。"},{"en":"Quick videos are short online videos that show information or entertainment in a fast way.","zh":"quick videos 是以快速方式展示資訊或娛樂內容的網上短片。"},{"en":"Quick videos can show a make-up trend in less than one minute.","zh":"短片可以在不到一分鐘內展示一種化妝潮流。"},{"en":"Because quick videos are brief, they may show the look but not explain the context.","zh":"因為短片很短，它們可能展示外觀，卻不解釋背景。"},{"en":"Quick videos are useful for discovery, but not always enough for judgement.","zh":"短片對發現潮流有用，但不一定足以作判斷。"}],"source":"2019 Q5.pdf","sourcePage":3},{"front":"spot what is moving","meaning":"察覺正在流行的東西","examples":[{"en":"She uses quick videos to spot what is moving in pop culture.","zh":"她用短片察覺流行文化中正在流行的東西。"},{"en":"To spot what is moving means to notice what is becoming popular or active.","zh":"spot what is moving 指留意甚麼正在變得流行或活躍。"},{"en":"Shop owners spot what is moving by watching what customers ask for most.","zh":"店主透過觀察顧客最常查詢甚麼，察覺正在流行的東西。"},{"en":"If students spot what is moving online, they can understand classmates’ conversations more easily.","zh":"如果學生察覺網上正在流行的東西，就更容易理解同學的對話。"},{"en":"This phrase focuses on early awareness, not deep understanding.","zh":"這個短語強調及早察覺，而不是深入理解。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"reliable magazines and reviews","meaning":"可靠的雜誌和評論","examples":[{"en":"Reliable magazines and reviews help her judge trends.","zh":"可靠的雜誌和評論幫助她判斷潮流。"},{"en":"Reliable magazines and reviews are sources that give careful, trustworthy opinions and information.","zh":"reliable magazines and reviews 指提供仔細、可信意見和資訊的來源。"},{"en":"Before buying skincare, a student may check reliable magazines and reviews for safety and value.","zh":"購買護膚品前，學生可能查看可靠的雜誌和評論，以了解安全性和價值。"},{"en":"Reliable magazines and reviews can explain whether a trend is new, copied, useful, or exaggerated.","zh":"可靠的雜誌和評論可以解釋一個潮流是新穎、抄襲、有用還是被誇大。"},{"en":"These sources help readers slow down before spending money.","zh":"這些來源幫助讀者在花錢前慢下來。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"worth my attention","meaning":"值得我注意","examples":[{"en":"She decides whether a trend is worth her attention.","zh":"她判斷一個潮流是否值得她注意。"},{"en":"Worth my attention means important, useful, or interesting enough for me to spend time on.","zh":"worth my attention 指某事重要、有用或有趣到值得我花時間。"},{"en":"A long article is worth my attention if it explains a problem clearly.","zh":"如果一篇長文章清楚解釋問題，它就值得我注意。"},{"en":"Not every viral video is worth my attention, especially if it teaches me nothing.","zh":"不是每段爆紅影片都值得我注意，尤其是當它甚麼也教不到我時。"},{"en":"This phrase helps readers choose instead of reacting to everything.","zh":"這個短語幫助讀者作選擇，而不是對所有事情都有反應。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"when it comes to","meaning":"說到……","examples":[{"en":"When it comes to style and beauty, her first stop is social media.","zh":"說到造型與美容，她的第一站是社交媒體。"},{"en":"When it comes to means when talking about a particular subject.","zh":"when it comes to 指談到某個特定主題時。"},{"en":"When it comes to saving money, small daily habits matter.","zh":"說到儲錢，日常小習慣很重要。"},{"en":"When it comes to music, live performance can reveal an artist’s real skill.","zh":"說到音樂，現場表演可以顯示歌手的真正實力。"},{"en":"This phrase helps introduce a topic before giving an opinion.","zh":"這個短語有助在提出意見前引入主題。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"my first stop","meaning":"我的第一站","examples":[{"en":"Her first stop for fashion trends is social media.","zh":"她尋找時裝潮流的第一站是社交媒體。"},{"en":"My first stop means the first place I go to for information or help.","zh":"my first stop 指我尋找資訊或幫助時首先去的地方。"},{"en":"When I feel sick, my first stop is the school nurse.","zh":"當我感到不舒服時，我的第一站是學校護士。"},{"en":"For homework questions, a student’s first stop may be the textbook before the internet.","zh":"對功課問題來說，學生的第一站可能是課本，而不是互聯網。"},{"en":"In the essay, social media is the first place she checks, not the only place.","zh":"在文章中，社交媒體是她首先查看的地方，但不是唯一地方。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Social media is useful because fashion is visual by nature.","zh":"社交媒體很有用，因為時裝本質上是視覺的。"},{"en":"Social media means online platforms where users create, share, and react to content.","zh":"social media 指用戶創作、分享和回應內容的網上平台。"},{"en":"People use social media to post outfits, songs, opinions, photos, and short videos.","zh":"人們使用社交媒體發布穿搭、歌曲、意見、照片和短片。"},{"en":"Social media can spread useful ideas, but it can also exaggerate weak trends.","zh":"社交媒體可以傳播有用想法，但也可以誇大薄弱的潮流。"},{"en":"Readers need judgement when social media makes everything look urgent.","zh":"當社交媒體令所有事情看似緊急，讀者需要判斷力。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"by nature","meaning":"本質上","examples":[{"en":"Fashion is visual by nature.","zh":"時裝本質上是視覺的。"},{"en":"By nature means because of the basic character of something.","zh":"by nature 指因為某事物的基本特性。"},{"en":"Children are often curious by nature, so they ask many questions.","zh":"孩子本質上常有好奇心，所以會問很多問題。"},{"en":"Sport is competitive by nature because teams try to win.","zh":"運動本質上有競爭性，因為隊伍會努力取勝。"},{"en":"Saying fashion is visual by nature explains why pictures and videos suit it well.","zh":"說時裝本質上是視覺的，解釋了為何圖片和影片很適合它。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"read about","meaning":"閱讀關於……的資料","examples":[{"en":"You do not just read about a jacket.","zh":"你不只是閱讀關於一件外套的資料。"},{"en":"To read about something means to learn information about it from written text.","zh":"read about something 指從文字中了解某事物的資訊。"},{"en":"I read about the concert before deciding whether to buy a ticket.","zh":"我先閱讀關於那場演唱會的資料，再決定是否買票。"},{"en":"Reading about a product can explain its materials, price, and purpose.","zh":"閱讀關於一件產品的資料，可以了解它的物料、價格和用途。"},{"en":"In fashion, reading about a jacket is useful, but seeing it on people is also important.","zh":"在時裝中，閱讀關於外套的資料有用，但看它穿在人身上也很重要。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"see how it falls on different bodies","meaning":"看它穿在不同身形上的垂墜效果","examples":[{"en":"You want to see how a jacket falls on different bodies.","zh":"你想看一件外套穿在不同身形上的垂墜效果。"},{"en":"To see how it falls on different bodies means to observe how clothing hangs or fits on people with different shapes.","zh":"see how it falls on different bodies 指觀察衣服穿在不同身形的人身上如何垂墜或合身。"},{"en":"Online videos help shoppers see how a dress falls on different bodies before buying it.","zh":"網上影片幫助購物者在購買前看裙子穿在不同身形上的垂墜效果。"},{"en":"A jacket may look neat on one body but too stiff on another.","zh":"一件外套穿在一個人身上可能整齊，穿在另一個人身上卻太硬。"},{"en":"This phrase shows why fashion often needs images, not only descriptions.","zh":"這個短語顯示為何時裝常需要影像，而不只是文字描述。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"style it outside a studio","meaning":"在攝影棚外配搭它","examples":[{"en":"People show how they style the jacket outside a studio.","zh":"人們展示如何在攝影棚外配搭那件外套。"},{"en":"To style it outside a studio means to wear and match clothing in real-life places, not only in professional photoshoots.","zh":"style it outside a studio 指在真實生活地方穿搭衣服，而不只是在專業拍攝中。"},{"en":"A student may style a blazer outside a studio with jeans and trainers.","zh":"學生可能在攝影棚外把西裝外套配搭牛仔褲和運動鞋。"},{"en":"Seeing clothes styled outside a studio helps viewers imagine daily use.","zh":"看見衣服在攝影棚外被配搭，能幫助觀眾想像日常使用。"},{"en":"This phrase contrasts real-life dressing with polished magazine images.","zh":"這個短語把真實生活穿搭與精緻雜誌圖片形成對比。"}],"source":"2019 Q5.pdf","sourcePage":4},{"front":"clean girl make-up","meaning":"clean girl 妝容","examples":[{"en":"Clean girl make-up became popular on short-video platforms.","zh":"clean girl 妝容在短片平台上流行起來。"},{"en":"Clean girl make-up is a simple, fresh beauty style with natural skin, neat hair, and soft colours.","zh":"clean girl make-up 是簡約、清新的美容風格，包含自然皮膚、整齊髮型和柔和顏色。"},{"en":"A student might try clean girl make-up because it looks light and easy for school.","zh":"學生可能嘗試 clean girl 妝容，因為它看起來輕薄，適合上學。"},{"en":"Clean girl make-up can seem effortless, but it may still require many products.","zh":"clean girl 妝容看似不費力，但仍可能需要很多產品。"},{"en":"This trend shows how social media can make a natural look into a named style.","zh":"這個潮流顯示社交媒體如何把自然外觀變成有名字的風格。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"ballet-core ribbons","meaning":"芭蕾風絲帶","examples":[{"en":"Ballet-core ribbons began appearing everywhere online.","zh":"芭蕾風絲帶開始在網上到處出現。"},{"en":"Ballet-core ribbons are ribbons used in outfits inspired by ballet style.","zh":"ballet-core ribbons 指受芭蕾風格啟發、用於穿搭的絲帶。"},{"en":"A teenager may tie ballet-core ribbons in her hair to create a soft, dancer-like look.","zh":"年輕人可能把芭蕾風絲帶綁在頭髮上，營造柔和、像舞者的造型。"},{"en":"When ballet-core ribbons appear on bags, shoes, and hairstyles, the trend becomes easy to notice.","zh":"當芭蕾風絲帶出現在袋、鞋和髮型上，這個潮流就很容易被注意到。"},{"en":"This phrase shows how one small accessory can signal a larger fashion mood.","zh":"這個短語顯示一件小配飾如何代表更大的時裝氣氛。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"oversized denim","meaning":"寬鬆牛仔服飾","examples":[{"en":"Oversized denim became visible across many accounts.","zh":"寬鬆牛仔服飾開始在許多帳戶中變得明顯。"},{"en":"Oversized denim means loose, larger-fitting denim clothing such as jeans, jackets, or skirts.","zh":"oversized denim 指寬鬆、較大版型的牛仔衣物，例如牛仔褲、外套或裙。"},{"en":"Students may wear oversized denim jackets because they feel comfortable and casual.","zh":"學生可能穿寬鬆牛仔外套，因為它舒服又休閒。"},{"en":"Oversized denim can change a look by making it more relaxed and street-style.","zh":"寬鬆牛仔服飾可以令造型變得更放鬆、更有街頭風格。"},{"en":"When many accounts show oversized denim, viewers start to recognise it as a trend.","zh":"當許多帳戶展示寬鬆牛仔服飾，觀眾就開始把它認作潮流。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"begin appearing everywhere","meaning":"開始到處出現","examples":[{"en":"New looks often begin appearing everywhere on social media.","zh":"新造型常開始在社交媒體上到處出現。"},{"en":"Begin appearing everywhere means start to be seen repeatedly in many places.","zh":"begin appearing everywhere 指開始在許多地方反覆被看見。"},{"en":"A new snack may begin appearing everywhere after students post photos of it.","zh":"一款新零食在學生發布照片後，可能開始到處出現。"},{"en":"When the same hairstyle begins appearing everywhere, people know a trend is forming.","zh":"當同一髮型開始到處出現，人們就知道潮流正在形成。"},{"en":"This phrase shows the early stage of a trend becoming visible.","zh":"這個短語顯示潮流變得可見的早期階段。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"notice something first through","meaning":"最先透過……留意到某事","examples":[{"en":"She noticed the trends first through short videos.","zh":"她最先透過短片留意到這些潮流。"},{"en":"To notice something first through a source means to become aware of it there before anywhere else.","zh":"notice something first through a source 指最先透過某個來源知道某事。"},{"en":"I noticed the new café first through my friend’s Instagram story.","zh":"我最先透過朋友的 Instagram 限時動態留意到那間新咖啡店。"},{"en":"Many students notice songs first through short videos before hearing the full version.","zh":"許多學生在聽完整版本前，最先透過短片留意到歌曲。"},{"en":"This phrase explains where a person first discovers a trend.","zh":"這個短語解釋一個人最初在哪裏發現潮流。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"make-up artists","meaning":"化妝師","examples":[{"en":"Make-up artists often post get-ready-with-me clips.","zh":"化妝師常發布一起準備出門短片。"},{"en":"Make-up artists are people who apply make-up professionally or skillfully.","zh":"make-up artists 是專業或熟練地為人化妝的人。"},{"en":"Make-up artists can teach viewers how to choose colours, brushes, and skincare steps.","zh":"化妝師可以教觀眾如何選擇顏色、掃具和護膚步驟。"},{"en":"When make-up artists repeat the same look, viewers may see a beauty trend forming.","zh":"當化妝師重複同一造型，觀眾可能看見美容潮流正在形成。"},{"en":"In online culture, make-up artists often influence what products people buy.","zh":"在網上文化中，化妝師常影響人們購買甚麼產品。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"get-ready-with-me clips","meaning":"一起準備出門短片","examples":[{"en":"Students and stylists posted get-ready-with-me clips.","zh":"學生和造型師發布了一起準備出門短片。"},{"en":"Get-ready-with-me clips are short videos showing someone preparing their outfit, hair, or make-up.","zh":"get-ready-with-me clips 是展示某人準備穿搭、髮型或妝容的短片。"},{"en":"A student may film a get-ready-with-me clip before a school picnic.","zh":"學生可能在學校旅行前拍攝一起準備出門短片。"},{"en":"These clips can show how a trend works in real life, step by step.","zh":"這些短片可以一步一步展示潮流如何在現實生活中使用。"},{"en":"They feel personal because viewers watch someone prepare for an ordinary day.","zh":"它們感覺很個人化，因為觀眾看着某人為普通一天作準備。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"across different accounts","meaning":"在不同帳戶上","examples":[{"en":"The look appeared across different accounts.","zh":"這個造型出現在不同帳戶上。"},{"en":"Across different accounts means on many separate social-media profiles or pages.","zh":"across different accounts 指在許多不同的社交媒體個人檔案或頁面上。"},{"en":"The same recipe appeared across different accounts after one chef posted it.","zh":"一位廚師發布食譜後，同一食譜出現在不同帳戶上。"},{"en":"If a jacket appears across different accounts, it may be becoming a wider trend.","zh":"如果一件外套出現在不同帳戶上，它可能正在變成更廣泛的潮流。"},{"en":"This phrase helps show that a trend is not limited to one person.","zh":"這個短語幫助顯示潮流不限於一個人。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"a wider trend taking shape","meaning":"一個更廣泛的潮流正在形成","examples":[{"en":"The repeated look showed a wider trend taking shape.","zh":"重複出現的造型顯示一個更廣泛的潮流正在形成。"},{"en":"A wider trend taking shape means a larger pattern is beginning to form clearly.","zh":"a wider trend taking shape 指一個較大的模式開始清楚形成。"},{"en":"When many students bring reusable bottles, a wider environmental trend is taking shape.","zh":"當許多學生帶可重用水樽，一個更廣泛的環保潮流正在形成。"},{"en":"A wider trend takes shape when small repeated signs point in the same direction.","zh":"當細小而重複的跡象指向同一方向，更廣泛的潮流就會形成。"},{"en":"This phrase shows that the writer is noticing a pattern, not just one example.","zh":"這個短語顯示作者注意到的是模式，而不只是一個例子。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"identify the mood early","meaning":"及早掌握潮流氣氛","examples":[{"en":"Short videos help her identify the mood early.","zh":"短片幫助她及早掌握潮流氣氛。"},{"en":"To identify the mood early means to notice the feeling or style of a trend before it becomes fully popular.","zh":"identify the mood early 指在潮流完全流行前，先察覺它的感覺或風格。"},{"en":"Designers identify the mood early by watching colours, music, and street outfits.","zh":"設計師透過觀察顏色、音樂和街頭穿搭，及早掌握潮流氣氛。"},{"en":"If students identify the mood early, they can understand why classmates like a new style.","zh":"如果學生及早掌握潮流氣氛，就能理解同學為何喜歡新風格。"},{"en":"This phrase is about sensing the direction of culture before everyone names it.","zh":"這個短語關於在所有人命名之前感受文化方向。"}],"source":"2019 Q5.pdf","sourcePage":5},{"front":"speed by itself","meaning":"單靠速度","examples":[{"en":"However, speed by itself is not enough.","zh":"然而，單靠速度並不足夠。"},{"en":"Speed by itself means quickness alone, without care, depth, or judgement.","zh":"speed by itself 指只有快速，而沒有細心、深度或判斷。"},{"en":"A fast answer is not useful if speed by itself creates mistakes.","zh":"如果單靠速度造成錯誤，快速答案就沒有用。"},{"en":"Social media offers speed, but speed by itself cannot explain whether a trend is meaningful.","zh":"社交媒體提供速度，但單靠速度不能解釋潮流是否有意義。"},{"en":"This phrase warns that being first is not the same as being wise.","zh":"這個短語提醒我們，最早知道不等於最明智。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"the trouble with","meaning":"……的問題在於","examples":[{"en":"The trouble with social media is that it can make every product look essential.","zh":"社交媒體的問題在於，它可以令每件產品看似必不可少。"},{"en":"The trouble with something is the main problem or weakness it has.","zh":"the trouble with something 指某事物的主要問題或弱點。"},{"en":"The trouble with online shopping is that discounts can make people buy things they do not need.","zh":"網購的問題在於，折扣可能令人買不需要的東西。"},{"en":"The trouble with group projects is that one person may do most of the work.","zh":"小組項目的問題在於，可能只有一個人做大部分工作。"},{"en":"This phrase introduces criticism in a clear and direct way.","zh":"這個短語以清楚直接的方式引入批評。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"make every product look essential","meaning":"令每件產品看似必不可少","examples":[{"en":"Social media can make every product look essential.","zh":"社交媒體可以令每件產品看似必不可少。"},{"en":"To make every product look essential means to make people feel each item is necessary.","zh":"make every product look essential 指令人覺得每件物品都是必要的。"},{"en":"A beauty video can make every product look essential by calling each one a “must-have.”","zh":"美容影片把每件產品都稱為「必備」，就可以令每件產品看似必不可少。"},{"en":"If advertisements make every product look essential, shoppers may lose control of their spending.","zh":"如果廣告令每件產品看似必不可少，購物者可能會失去消費控制。"},{"en":"This phrase criticises the pressure created by online marketing.","zh":"這個短語批評網上營銷造成的壓力。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"little more than","meaning":"不過是；只不過是","examples":[{"en":"Some recommendations are little more than advertisements in disguise.","zh":"有些推薦只不過是變相廣告。"},{"en":"Little more than means almost only that thing, and not as valuable as it may seem.","zh":"little more than 指幾乎只是那樣東西，並沒有看起來那麼有價值。"},{"en":"The free gift was little more than a cheap pen with a logo.","zh":"那份免費禮物只不過是一支印有標誌的廉價筆。"},{"en":"A review can be little more than promotion if the writer is paid to praise the product.","zh":"如果作者收錢讚美產品，評論可能只不過是宣傳。"},{"en":"This phrase is useful for showing disappointment or criticism.","zh":"這個短語適合用來表達失望或批評。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"an advertisement in disguise","meaning":"變相廣告","examples":[{"en":"A product recommendation may be an advertisement in disguise.","zh":"產品推薦可能是變相廣告。"},{"en":"An advertisement in disguise is promotion that looks like honest advice or ordinary content.","zh":"advertisement in disguise 指看似真誠建議或普通內容的宣傳。"},{"en":"A travel post may be an advertisement in disguise if the hotel paid for it.","zh":"如果酒店付錢給作者，旅遊帖文可能是變相廣告。"},{"en":"Viewers should be careful when a video praises a product without mentioning payment.","zh":"當影片讚美產品卻不提付款安排，觀眾應該小心。"},{"en":"This phrase warns that some online content hides its real purpose.","zh":"這個短語警告有些網上內容隱藏真正目的。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"for that reason","meaning":"因此","examples":[{"en":"For that reason, she checks magazines before spending money.","zh":"因此，她在花錢前會查看雜誌。"},{"en":"For that reason means because of the reason just mentioned.","zh":"for that reason 指因為剛才提到的原因。"},{"en":"The reviews were poor; for that reason, I did not buy the headphones.","zh":"評價很差；因此，我沒有買那副耳機。"},{"en":"The bus is often late; for that reason, students leave home earlier.","zh":"巴士經常遲到；因此，學生較早出門。"},{"en":"This phrase connects a cause to a sensible action or decision.","zh":"這個短語把原因連接到理性的行動或決定。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"before deciding whether","meaning":"在決定是否……之前","examples":[{"en":"She checks reviews before deciding whether a trend deserves attention.","zh":"她在決定一個潮流是否值得注意之前，會查看評論。"},{"en":"Before deciding whether means before making a choice about yes or no.","zh":"before deciding whether 指在作出是否如此的選擇之前。"},{"en":"I read the menu before deciding whether to eat at the restaurant.","zh":"我在決定是否在那間餐廳吃飯之前，先看餐牌。"},{"en":"Students should compare courses before deciding whether to join an expensive class.","zh":"學生在決定是否參加昂貴課程之前，應比較不同課程。"},{"en":"This phrase shows careful thinking before action.","zh":"這個短語顯示行動前的仔細思考。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"deserve my money or attention","meaning":"值得我花錢或注意","examples":[{"en":"Not every trend deserves her money or attention.","zh":"不是每個潮流都值得她花錢或注意。"},{"en":"Deserve my money or attention means be worth the cost, time, or focus I would give it.","zh":"deserve my money or attention 指值得我付出金錢、時間或專注。"},{"en":"A product deserves my money if it is useful, durable, and fairly priced.","zh":"如果一件產品有用、耐用而且價格合理，它就值得我花錢。"},{"en":"A loud online argument may not deserve my attention if it teaches me nothing.","zh":"如果一場吵鬧的網上爭論甚麼也教不到我，就不值得我注意。"},{"en":"This phrase helps people protect both their budget and their mind.","zh":"這個短語幫助人保護自己的預算和心神。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"student-friendly voice","meaning":"適合學生閱讀的語氣","examples":[{"en":"Teen Vogue explains fashion in a student-friendly voice.","zh":"Teen Vogue 以適合學生閱讀的語氣解釋時裝。"},{"en":"A student-friendly voice is a clear, approachable style that young learners can understand.","zh":"student-friendly voice 指清楚、親切、年輕學習者能理解的表達方式。"},{"en":"A teacher uses a student-friendly voice when she explains grammar with simple examples.","zh":"老師用簡單例子解釋文法時，就是使用適合學生閱讀的語氣。"},{"en":"Articles written in a student-friendly voice avoid unnecessary difficult words.","zh":"以適合學生閱讀的語氣寫成的文章會避免不必要的艱深字眼。"},{"en":"This phrase suggests that the source respects young readers instead of talking down to them.","zh":"這個短語暗示來源尊重年輕讀者，而不是居高臨下。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"streetwear","meaning":"街頭服飾","examples":[{"en":"Highsnobiety is useful for streetwear and youth culture.","zh":"Highsnobiety 對街頭服飾和青年文化很有用。"},{"en":"Streetwear is casual fashion influenced by streets, youth culture, sports, music, and sneakers.","zh":"streetwear 是受街頭、青年文化、運動、音樂和運動鞋影響的休閒時裝。"},{"en":"Hoodies, loose trousers, caps, and trainers are often part of streetwear.","zh":"連帽衫、寬鬆長褲、帽和運動鞋常是街頭服飾的一部分。"},{"en":"Streetwear can show identity because people mix comfort, brands, and local style.","zh":"街頭服飾可以展示身份，因為人們混合舒適、品牌和本地風格。"},{"en":"A magazine about streetwear helps readers understand more than just clothes.","zh":"關於街頭服飾的雜誌幫助讀者理解的不只是衣服。"}],"source":"2019 Q5.pdf","sourcePage":6},{"front":"youth culture","meaning":"青年文化","examples":[{"en":"Highsnobiety explains streetwear and youth culture well.","zh":"Highsnobiety 很好地解釋街頭服飾和青年文化。"},{"en":"Youth culture means the styles, music, language, habits, and values shared by young people.","zh":"youth culture 指年輕人共同擁有的風格、音樂、語言、習慣和價值觀。"},{"en":"Memes, playlists, slang, and fashion trends can all belong to youth culture.","zh":"迷因、播放清單、潮語和時裝潮流都可以屬於青年文化。"},{"en":"Youth culture changes quickly because young people create and share ideas online.","zh":"青年文化變化很快，因為年輕人在網上創作和分享想法。"},{"en":"Understanding youth culture helps adults see young people’s lives more clearly.","zh":"理解青年文化能幫助成年人更清楚看見年輕人的生活。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"quiet luxury look","meaning":"低調奢華風","examples":[{"en":"The quiet luxury look became popular through social media and magazines.","zh":"低調奢華風透過社交媒體和雜誌流行起來。"},{"en":"The quiet luxury look is a simple, expensive-looking style with few obvious logos.","zh":"quiet luxury look 是簡約、看似昂貴、少有明顯標誌的風格。"},{"en":"A beige blazer, clean trousers, and plain leather shoes can create a quiet luxury look.","zh":"米色西裝外套、乾淨長褲和平實皮鞋可以營造低調奢華風。"},{"en":"The quiet luxury look may attract people who prefer quality over loud branding.","zh":"低調奢華風可能吸引較重視質素而非搶眼品牌的人。"},{"en":"This trend shows that fashion can signal wealth quietly, not only loudly.","zh":"這個潮流顯示時裝可以安靜地顯示財富，而不只靠張揚。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"beige blazer","meaning":"米色西裝外套","examples":[{"en":"Videos may show the beige blazer, but magazines explain the idea behind it.","zh":"影片可能展示米色西裝外套，但雜誌解釋它背後的理念。"},{"en":"A beige blazer is a light brown or cream-coloured jacket with a smart shape.","zh":"beige blazer 是淺棕色或米白色、版型較正式的外套。"},{"en":"A student may wear a beige blazer over a T-shirt to look neat but relaxed.","zh":"學生可能把米色西裝外套穿在 T 恤外，看起來整齊但放鬆。"},{"en":"A beige blazer can appear simple, so styling and fit become important.","zh":"米色西裝外套可以看似簡單，因此配搭和剪裁變得重要。"},{"en":"In the essay, the beige blazer represents a wider quiet luxury trend.","zh":"在文章中，米色西裝外套代表更廣泛的低調奢華潮流。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"the deeper idea behind","meaning":"背後更深層的理念","examples":[{"en":"Magazines explain the deeper idea behind a fashion trend.","zh":"雜誌解釋時裝潮流背後更深層的理念。"},{"en":"The deeper idea behind something means the larger meaning, reason, or value beneath its surface.","zh":"the deeper idea behind something 指表面之下較大的意義、原因或價值。"},{"en":"The deeper idea behind school uniforms may be equality, not just appearance.","zh":"校服背後更深層的理念可能是平等，而不只是外觀。"},{"en":"A review can explain the deeper idea behind a song’s simple chorus.","zh":"評論可以解釋一首歌簡單副歌背後更深層的理念。"},{"en":"This phrase helps readers move from seeing a trend to understanding it.","zh":"這個短語幫助讀者從看見潮流走向理解潮流。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"minimal branding","meaning":"極簡品牌標誌","examples":[{"en":"Quiet luxury often involves minimal branding and better tailoring.","zh":"低調奢華風常涉及極簡品牌標誌和更好的剪裁。"},{"en":"Minimal branding means using very few visible logos or brand names.","zh":"minimal branding 指使用很少明顯標誌或品牌名稱。"},{"en":"A plain leather bag with minimal branding may look more subtle than one covered in logos.","zh":"一個極簡品牌標誌的素色皮袋，可能比滿是標誌的袋更低調。"},{"en":"Minimal branding can make people focus on material, shape, and quality instead of labels.","zh":"極簡品牌標誌可以令人把注意力放在物料、形狀和質素，而不是標籤。"},{"en":"This phrase is important because quiet luxury depends on understatement.","zh":"這個短語很重要，因為低調奢華依靠含蓄表達。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"better tailoring","meaning":"更好的剪裁","examples":[{"en":"Quiet luxury focuses on better tailoring and long-term wear.","zh":"低調奢華風注重更好的剪裁和長期穿着。"},{"en":"Better tailoring means clothing is cut and shaped more carefully to fit well.","zh":"better tailoring 指衣服被更仔細地裁剪和塑形，以便更合身。"},{"en":"A jacket with better tailoring sits neatly on the shoulders.","zh":"剪裁更好的外套會整齊地貼在肩膀上。"},{"en":"Better tailoring can make simple clothes look more expensive and comfortable.","zh":"更好的剪裁可以令簡單衣服看起來更昂貴和舒適。"},{"en":"In fashion, better tailoring often matters more than a large logo.","zh":"在時裝中，更好的剪裁常比大標誌更重要。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"long-term wear","meaning":"長期穿着；耐穿性","examples":[{"en":"Magazines explain why long-term wear matters in fashion.","zh":"雜誌解釋為何長期穿着在時裝中很重要。"},{"en":"Long-term wear means clothing can be worn for a long time without quickly becoming useless or outdated.","zh":"long-term wear 指衣服可以穿很久，而不會很快變得無用或過時。"},{"en":"A strong coat with long-term wear may cost more at first but save money later.","zh":"一件耐穿的大衣起初可能較貴，但之後能省錢。"},{"en":"Thinking about long-term wear can reduce waste from buying too many short-lived trends.","zh":"考慮長期穿着可以減少購買太多短命潮流造成的浪費。"},{"en":"This phrase connects fashion with quality, value, and responsibility.","zh":"這個短語把時裝與質素、價值和責任連在一起。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"use social media to discover style","meaning":"用社交媒體發現風格","examples":[{"en":"She uses social media to discover style.","zh":"她用社交媒體發現風格。"},{"en":"To use social media to discover style means to find new fashion ideas through online posts and videos.","zh":"use social media to discover style 指透過網上帖文和影片尋找新的時裝想法。"},{"en":"A teenager may use social media to discover style by following students from different cities.","zh":"年輕人可能透過追蹤不同城市的學生，用社交媒體發現風格。"},{"en":"Social media helps people discover style quickly because it shows real outfits in daily life.","zh":"社交媒體幫助人快速發現風格，因為它展示日常生活中的真實穿搭。"},{"en":"This method is useful for discovery, but it still needs judgement.","zh":"這種方法對發現有用，但仍需要判斷。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"use magazines to judge it","meaning":"用雜誌判斷它","examples":[{"en":"She uses digital magazines to judge whether a trend is worthwhile.","zh":"她用數碼雜誌判斷一個潮流是否值得。"},{"en":"To use magazines to judge it means to read more careful sources before deciding its value.","zh":"use magazines to judge it 指在判斷其價值前閱讀較仔細的來源。"},{"en":"A shopper may use magazines to judge whether a viral bag is well made.","zh":"購物者可能用雜誌判斷一個爆紅手袋是否製作精良。"},{"en":"Magazines can help judge a trend by explaining history, quality, and meaning.","zh":"雜誌可以透過解釋歷史、質素和意義來幫助判斷潮流。"},{"en":"This phrase shows the difference between finding a style and evaluating it.","zh":"這個短語顯示發現風格和評估風格之間的分別。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"slightly different","meaning":"略有不同","examples":[{"en":"Music and concerts are slightly different from fashion.","zh":"音樂與演唱會和時裝略有不同。"},{"en":"Slightly different means a little different, not completely different.","zh":"slightly different 指有一點不同，但不是完全不同。"},{"en":"The two jackets look slightly different because one has larger buttons.","zh":"兩件外套看起來略有不同，因為其中一件的鈕扣較大。"},{"en":"Online music discovery is slightly different from fashion discovery because sound matters more than image.","zh":"網上音樂發現與時裝發現略有不同，因為聲音比影像更重要。"},{"en":"This phrase helps compare two things gently and precisely.","zh":"這個短語有助溫和而準確地比較兩件事。"}],"source":"2019 Q5.pdf","sourcePage":7},{"front":"good criticism","meaning":"好的評論","examples":[{"en":"Good criticism teaches listeners how to listen.","zh":"好的評論教聽眾如何聆聽。"},{"en":"Good criticism is thoughtful judgement that explains strengths, weaknesses, and meaning.","zh":"good criticism 是有思考的判斷，能解釋優點、弱點和意義。"},{"en":"Good criticism of a song may discuss its lyrics, sound, emotion, and cultural background.","zh":"對歌曲的好評論可能討論歌詞、聲音、情感和文化背景。"},{"en":"Good criticism helps readers understand art instead of simply liking or disliking it.","zh":"好的評論幫助讀者理解藝術，而不只是喜歡或不喜歡。"},{"en":"This phrase shows that criticism can teach, not only attack.","zh":"這個短語顯示評論可以教人，而不只是攻擊。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"teach me how to listen","meaning":"教我如何聆聽","examples":[{"en":"Pitchfork reviews teach her how to listen more carefully.","zh":"Pitchfork 的評論教她如何更仔細地聆聽。"},{"en":"To teach me how to listen means to help me notice sound, lyrics, structure, and meaning more deeply.","zh":"teach me how to listen 指幫助我更深入留意聲音、歌詞、結構和意義。"},{"en":"A music teacher can teach me how to listen for rhythm and harmony.","zh":"音樂老師可以教我如何聆聽節奏與和聲。"},{"en":"A good review may teach me how to listen to a song beyond its catchy chorus.","zh":"好評論可以教我如何聆聽一首歌，不只停留在易記的副歌。"},{"en":"This phrase shows that listening is a skill that can improve.","zh":"這個短語顯示聆聽是一種可以進步的技能。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"point out","meaning":"指出","examples":[{"en":"A good review points out details she may miss.","zh":"好評論會指出她可能錯過的細節。"},{"en":"To point out means to show, mention, or explain something clearly.","zh":"point out 指清楚展示、提及或解釋某事。"},{"en":"The teacher pointed out the mistake before the student repeated it.","zh":"老師在學生重複錯誤前指出那個錯處。"},{"en":"A friend may point out that a jacket fits badly even if the colour is nice.","zh":"朋友可能指出一件外套雖然顏色好看，但不合身。"},{"en":"Reviews point out details so readers can notice what they overlooked.","zh":"評論指出細節，讓讀者注意到自己忽略的東西。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"production","meaning":"音樂製作","examples":[{"en":"Reviews can explain the production of a song.","zh":"評論可以解釋一首歌的音樂製作。"},{"en":"Production in music means how a song is recorded, arranged, mixed, and shaped.","zh":"production 在音樂中指歌曲如何錄製、編排、混音和塑造。"},{"en":"Strong production can make a simple melody sound rich and emotional.","zh":"出色的音樂製作可以令簡單旋律聽起來豐富而有情感。"},{"en":"Poor production may hide a singer’s voice under too many effects.","zh":"差劣的音樂製作可能用太多效果掩蓋歌手聲音。"},{"en":"Understanding production helps listeners hear how a song is built.","zh":"理解音樂製作能幫助聽眾聽出歌曲如何被建立。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"lyrics","meaning":"歌詞","examples":[{"en":"Reviews help her notice the lyrics of a song.","zh":"評論幫助她留意一首歌的歌詞。"},{"en":"Lyrics are the words of a song.","zh":"lyrics 指一首歌中的文字。"},{"en":"A sad song may have simple lyrics that feel honest and direct.","zh":"悲傷歌曲可能有簡單但真誠直接的歌詞。"},{"en":"Listeners may misunderstand lyrics if they focus only on the beat.","zh":"如果聽眾只集中在節拍上，可能會誤解歌詞。"},{"en":"Reading lyrics can reveal meaning that is easy to miss while listening casually.","zh":"閱讀歌詞可以揭示隨意聆聽時容易錯過的意思。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"cultural references","meaning":"文化典故；文化指涉","examples":[{"en":"Reviews explain cultural references that listeners may miss.","zh":"評論解釋聽眾可能錯過的文化典故。"},{"en":"Cultural references are mentions of people, events, books, films, history, or ideas from a culture.","zh":"cultural references 指對某種文化中的人物、事件、書籍、電影、歷史或思想的提及。"},{"en":"A song may include cultural references to old movies or political events.","zh":"一首歌可能包含對舊電影或政治事件的文化指涉。"},{"en":"Without context, listeners may hear the words but miss the cultural references.","zh":"沒有背景資料，聽眾可能聽到文字，卻錯過文化典故。"},{"en":"Explaining cultural references helps people understand why a song matters.","zh":"解釋文化典故能幫助人理解一首歌為何重要。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"miss on first hearing","meaning":"第一次聽時錯過","examples":[{"en":"Listeners may miss some details on first hearing.","zh":"聽眾第一次聽時可能會錯過一些細節。"},{"en":"To miss something on first hearing means not notice it the first time you listen.","zh":"miss something on first hearing 指第一次聆聽時沒有留意到某事。"},{"en":"I missed the quiet guitar part on first hearing because the drums were louder.","zh":"我第一次聽時錯過了安靜的結他部分，因為鼓聲較大。"},{"en":"A listener may miss clever lyrics on first hearing if the song is very fast.","zh":"如果歌曲很快，聽眾第一次聽時可能會錯過巧妙的歌詞。"},{"en":"This phrase shows why listening again or reading reviews can help.","zh":"這個短語顯示為何再聽一次或閱讀評論會有幫助。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, she usually discovers new songs through short videos.","zh":"然而，她通常透過短片發現新歌。"},{"en":"Nevertheless means however, despite what was just said.","zh":"nevertheless 指然而、儘管剛才說了那些情況。"},{"en":"The album received mixed reviews; nevertheless, many students loved it.","zh":"這張專輯評價不一；然而，許多學生很喜歡它。"},{"en":"Live clips are not perfect; nevertheless, they can reveal real performance skill.","zh":"現場片段並不完美；然而，它們可以顯示真正表演實力。"},{"en":"This word helps show contrast without completely rejecting the previous point.","zh":"這個詞有助顯示對比，而不完全否定前一點。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"I would be lying if I said","meaning":"如果我說……就是在說謊","examples":[{"en":"She would be lying if she said she discovered most songs through reviews.","zh":"如果她說自己大多透過評論發現歌曲，那就是在說謊。"},{"en":"I would be lying if I said means what follows would not be honest or true.","zh":"I would be lying if I said 指接下來的說法並不誠實或真實。"},{"en":"I would be lying if I said I never check my phone during homework.","zh":"如果我說自己做功課時從不看手機，那就是在說謊。"},{"en":"A writer uses this phrase to admit something honestly, even if it weakens a neat argument.","zh":"作者使用這個短語，是為了誠實承認某事，即使它削弱整齊的論點。"},{"en":"This phrase makes the voice sound personal and believable.","zh":"這個短語令語氣更個人化，也更可信。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"written reviews","meaning":"文字評論","examples":[{"en":"She does not discover most new songs through written reviews.","zh":"她不是透過文字評論發現大多數新歌。"},{"en":"Written reviews are articles or comments that judge and explain music, films, products, or performances in words.","zh":"written reviews 是用文字評價和解釋音樂、電影、產品或表演的文章或評論。"},{"en":"Written reviews can help listeners understand an album after they hear it.","zh":"文字評論可以幫助聽眾在聽過專輯後理解它。"},{"en":"Some people prefer written reviews because they can read slowly and compare opinions.","zh":"有些人較喜歡文字評論，因為他們可以慢慢閱讀並比較意見。"},{"en":"In the essay, written reviews provide depth, but not usually first discovery.","zh":"在文章中，文字評論提供深度，但通常不是最初的發現來源。"}],"source":"2019 Q5.pdf","sourcePage":8},{"front":"most of the time","meaning":"大多數時候","examples":[{"en":"Most of the time, music reaches her through short videos.","zh":"大多數時候，音樂透過短片傳到她耳邊。"},{"en":"Most of the time means usually or in the majority of situations.","zh":"most of the time 指通常或在大部分情況下。"},{"en":"Most of the time, students use their phones to check the weather.","zh":"大多數時候，學生用手機查看天氣。"},{"en":"A bus may be reliable most of the time but still arrive late during storms.","zh":"巴士大多數時候可能可靠，但暴風期間仍會遲到。"},{"en":"This phrase describes a common pattern without saying it always happens.","zh":"這個短語描述常見模式，但不是說它永遠發生。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"music reaches me through","meaning":"音樂透過……傳到我耳邊","examples":[{"en":"Music reaches her through short videos, playlists and live clips.","zh":"音樂透過短片、播放清單和現場片段傳到她耳邊。"},{"en":"Music reaches me through something means I discover or hear music by that channel.","zh":"music reaches me through something 指我透過某個渠道發現或聽到音樂。"},{"en":"Music reaches me through friends when they share playlists after school.","zh":"放學後朋友分享播放清單時，音樂透過朋友傳到我耳邊。"},{"en":"Music may reach listeners through a film scene before they know the singer’s name.","zh":"音樂可能先透過電影場景傳到聽眾耳邊，然後他們才知道歌手名字。"},{"en":"This phrase makes music sound as if it travels toward the listener.","zh":"這個短語令音樂聽起來像會走向聽眾。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"short videos, playlists and live clips","meaning":"短片、播放清單和現場片段","examples":[{"en":"New songs often reach listeners through short videos, playlists and live clips.","zh":"新歌常透過短片、播放清單和現場片段傳到聽眾耳邊。"},{"en":"Short videos, playlists and live clips are common digital ways people discover music today.","zh":"short videos, playlists and live clips 是現今人們發現音樂的常見數碼方式。"},{"en":"A chorus may spread through short videos, while playlists help listeners find the full song.","zh":"副歌可能透過短片傳開，而播放清單幫助聽眾找到完整歌曲。"},{"en":"Live clips show whether a singer can perform beyond the studio version.","zh":"現場片段顯示歌手能否在錄音室版本以外也表現出色。"},{"en":"Together, these sources make music discovery fast, social, and visual.","zh":"這些來源合起來令音樂發現變得快速、社交化和視覺化。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"streaming platform","meaning":"串流平台","examples":[{"en":"A song may sound ordinary on a streaming platform.","zh":"一首歌在串流平台上可能聽起來很普通。"},{"en":"A streaming platform is an online service where people listen to music or watch videos without downloading them fully.","zh":"streaming platform 是讓人不用完整下載就能聽音樂或看影片的網上服務。"},{"en":"Students use streaming platforms to create playlists for studying or exercise.","zh":"學生使用串流平台建立溫習或運動播放清單。"},{"en":"A song on a streaming platform may feel different from the same song performed live.","zh":"串流平台上的歌曲，可能與同一首歌的現場演出感覺不同。"},{"en":"This phrase shows one modern place where people meet music.","zh":"這個短語顯示人們接觸音樂的一個現代地方。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"suddenly make sense","meaning":"突然變得合理；突然打動人","examples":[{"en":"A song may suddenly make sense when performed live.","zh":"一首歌在現場演唱時可能突然變得合理。"},{"en":"Suddenly make sense means become clear or emotionally understandable all at once.","zh":"suddenly make sense 指突然變得清楚或在情感上可以理解。"},{"en":"A difficult poem may suddenly make sense after the teacher explains one image.","zh":"老師解釋一個意象後，一首困難的詩可能突然變得合理。"},{"en":"A song’s slow beginning may suddenly make sense when the chorus arrives.","zh":"當副歌出現，一首歌緩慢的開頭可能突然變得合理。"},{"en":"This phrase shows a moment when confusion changes into understanding.","zh":"這個短語顯示困惑轉變成理解的時刻。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"perform it live","meaning":"現場演唱它","examples":[{"en":"The singer performed the song live in a small studio.","zh":"歌手在小型錄音室現場演唱那首歌。"},{"en":"To perform it live means to sing or play it in real time before an audience or camera.","zh":"perform it live 指在觀眾或鏡頭前即時演唱或演奏它。"},{"en":"A band may perform it live at school before uploading the recording online.","zh":"樂隊可能先在學校現場演唱它，再把錄音上載到網上。"},{"en":"When artists perform songs live, small mistakes can make the music feel human.","zh":"當歌手現場演唱歌曲，小錯誤可以令音樂感覺更有人味。"},{"en":"This phrase contrasts real-time performance with edited studio production.","zh":"這個短語把即時表演與經剪接的錄音室製作形成對比。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"turn to","meaning":"轉向；求助於","examples":[{"en":"She often turns to YouTube for live music clips.","zh":"她常轉向 YouTube 尋找現場音樂片段。"},{"en":"To turn to something means to use it for help, information, or support.","zh":"turn to something 指使用某物尋求幫助、資訊或支持。"},{"en":"Students turn to dictionaries when they do not understand a word.","zh":"學生不明白一個字時會求助於字典。"},{"en":"A listener may turn to live clips to judge whether a singer is truly talented.","zh":"聽眾可能轉向現場片段，以判斷歌手是否真的有才華。"},{"en":"This phrase shows where someone goes when they need a useful source.","zh":"這個短語顯示某人需要有用來源時會去哪裏。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"the setting is small","meaning":"場地細小","examples":[{"en":"The setting is small, but that is exactly its charm.","zh":"場地細小，但這正正是它的魅力所在。"},{"en":"The setting is small means the place or environment is limited, intimate, and not grand.","zh":"the setting is small 指地方或環境有限、親密，而不宏大。"},{"en":"The setting is small in a classroom concert, so the singer feels close to the audience.","zh":"課室音樂會的場地細小，所以歌手感覺很接近觀眾。"},{"en":"A small setting can make a performance feel honest because there is less spectacle.","zh":"細小場地可以令表演感覺真誠，因為少了大型效果。"},{"en":"This phrase prepares a contrast between size and emotional power.","zh":"這個短語為規模和情感力量之間的對比作準備。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"exactly its charm","meaning":"正正是它的魅力所在","examples":[{"en":"The small setting is exactly its charm.","zh":"細小場地正正是它的魅力所在。"},{"en":"Exactly its charm means this feature is the precise reason something is attractive.","zh":"exactly its charm 指這個特點正是某物吸引人的原因。"},{"en":"The café is tiny, and that is exactly its charm because everyone feels close.","zh":"那間咖啡店很小，而這正正是它的魅力所在，因為大家感覺親近。"},{"en":"A handmade card is imperfect, but that may be exactly its charm.","zh":"手製卡片並不完美，但那可能正正是它的魅力所在。"},{"en":"This phrase turns a possible weakness into a strength.","zh":"這個短語把可能的弱點變成優點。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"without fireworks","meaning":"沒有煙花效果","examples":[{"en":"Without fireworks, the artist must rely on the song itself.","zh":"沒有煙花效果，歌手必須依靠歌曲本身。"},{"en":"Without fireworks means without spectacular effects, extra excitement, or showy decoration.","zh":"without fireworks 指沒有壯觀效果、額外刺激或華麗裝飾。"},{"en":"Without fireworks, a school performance depends on voices, acting, and emotion.","zh":"沒有煙花效果，學校表演就要依靠聲音、演技和情感。"},{"en":"A singer who performs well without fireworks proves the song is strong.","zh":"歌手在沒有煙花效果下仍表現出色，證明歌曲本身很強。"},{"en":"This phrase suggests that simple conditions can reveal real quality.","zh":"這個短語暗示簡單條件可以揭示真正質素。"}],"source":"2019 Q5.pdf","sourcePage":9},{"front":"heavy editing","meaning":"大量剪接","examples":[{"en":"Without heavy editing, the performance feels more honest.","zh":"沒有大量剪接，表演感覺更真誠。"},{"en":"Heavy editing means many changes, cuts, effects, or corrections are added after recording.","zh":"heavy editing 指錄製後加入很多改動、剪接、效果或修正。"},{"en":"Heavy editing can make a video look smooth but less natural.","zh":"大量剪接可以令影片看起來流暢，但較不自然。"},{"en":"Without heavy editing, viewers can judge the singer’s real voice more clearly.","zh":"沒有大量剪接，觀眾可以更清楚判斷歌手的真正聲音。"},{"en":"This phrase contrasts polished media with more direct performance.","zh":"這個短語把精修媒體與更直接的表演形成對比。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"have nowhere to hide","meaning":"無處可躲；不能掩飾實力","examples":[{"en":"In a live studio, an artist has nowhere to hide.","zh":"在現場錄音室裏，歌手無處可躲。"},{"en":"To have nowhere to hide means mistakes, weaknesses, or real ability can be seen clearly.","zh":"have nowhere to hide 指錯誤、弱點或真正能力會被清楚看見。"},{"en":"During a live debate, speakers have nowhere to hide if they do not understand the topic.","zh":"在現場辯論中，如果發言者不明白題目，就無處可躲。"},{"en":"A singer has nowhere to hide when there is only a microphone and a guitar.","zh":"當只有咪高峰和結他時，歌手就不能掩飾實力。"},{"en":"This phrase suggests pressure, honesty, and exposure.","zh":"這個短語暗示壓力、真實和暴露。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"favourite routine","meaning":"最喜歡的習慣","examples":[{"en":"Her favourite routine is to use reviews for context and live clips for proof.","zh":"她最喜歡的習慣是用評論了解背景，用現場片段作為證明。"},{"en":"A favourite routine is a regular method or habit someone likes using.","zh":"favourite routine 指某人喜歡反覆使用的固定方法或習慣。"},{"en":"My favourite routine before exams is to review notes, then practise questions.","zh":"我考試前最喜歡的習慣是先溫習筆記，再做練習題。"},{"en":"A listener’s favourite routine may combine reading reviews and watching performances.","zh":"聽眾最喜歡的習慣可能是結合閱讀評論和觀看表演。"},{"en":"This phrase shows a practical system, not just a random preference.","zh":"這個短語顯示的是實用系統，而不只是隨機偏好。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"use something for context","meaning":"用……了解背景","examples":[{"en":"She uses Pitchfork for context.","zh":"她用 Pitchfork 了解背景。"},{"en":"To use something for context means to use it to understand background, meaning, or situation.","zh":"use something for context 指用某物了解背景、意義或情況。"},{"en":"Students use history books for context before reading a war poem.","zh":"學生在閱讀戰爭詩前，用歷史書了解背景。"},{"en":"A music fan may use interviews for context before listening to an album.","zh":"音樂迷可能在聽專輯前，用訪問了解背景。"},{"en":"This phrase shows that a source helps explain why something matters.","zh":"這個短語顯示某個來源幫助解釋某事為何重要。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"use something for proof","meaning":"用……作為證明","examples":[{"en":"She uses live performances for proof.","zh":"她用現場表演作為證明。"},{"en":"To use something for proof means to use it as evidence that shows whether an idea is true.","zh":"use something for proof 指用某物作為證據，顯示某個想法是否真實。"},{"en":"A teacher uses test results for proof that students understand the topic.","zh":"老師用測驗結果作為證明，顯示學生理解題目。"},{"en":"A listener may use live videos for proof that a singer can perform without studio help.","zh":"聽眾可能用現場影片作為證明，判斷歌手能否不靠錄音室幫助也表演。"},{"en":"This phrase shows a move from opinion to evidence.","zh":"這個短語顯示從意見走向證據。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"a case in point","meaning":"一個例子是","examples":[{"en":"A case in point is discovering an artist through a review.","zh":"一個例子是透過評論發掘歌手。"},{"en":"A case in point means a clear example that proves or explains the point just made.","zh":"a case in point 指一個清楚例子，用來證明或解釋剛才的觀點。"},{"en":"Many students learn better from examples; a case in point is using real shopping situations to teach money words.","zh":"許多學生從例子中學得更好；一個例子是用真實購物情境教金錢詞彙。"},{"en":"Social media can create pressure; a case in point is the rush to buy viral skincare.","zh":"社交媒體會製造壓力；一個例子是人們急着購買爆紅護膚品。"},{"en":"This phrase helps introduce evidence in an essay.","zh":"這個短語有助在文章中引入證據。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"discover an artist through a review","meaning":"透過評論發掘歌手","examples":[{"en":"She may discover an artist through a review.","zh":"她可能透過評論發掘歌手。"},{"en":"To discover an artist through a review means to first learn about a singer or musician by reading criticism.","zh":"discover an artist through a review 指最先透過閱讀評論認識某位歌手或音樂人。"},{"en":"A student may discover an artist through a review in a music magazine.","zh":"學生可能透過音樂雜誌的評論發掘歌手。"},{"en":"Reviews can introduce artists by explaining their sound, background, and best songs.","zh":"評論可以透過解釋聲音、背景和最佳歌曲來介紹歌手。"},{"en":"This phrase shows that careful writing can lead listeners to new music.","zh":"這個短語顯示仔細的文字可以帶領聽眾走向新音樂。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"live session","meaning":"現場錄音演出","examples":[{"en":"She watches a live session to test the music.","zh":"她觀看現場錄音演出來測試音樂。"},{"en":"A live session is a recorded or streamed performance played live, often in a simple setting.","zh":"live session 是錄製或直播的現場表演，常在簡單環境中進行。"},{"en":"A band may film a live session in a small studio with only basic instruments.","zh":"樂隊可能在小型錄音室用基本樂器拍攝現場錄音演出。"},{"en":"A live session can reveal whether a song works without heavy production.","zh":"現場錄音演出可以揭示歌曲在沒有大量製作下是否成立。"},{"en":"This phrase connects music discovery with real performance quality.","zh":"這個短語把音樂發現與真正表演質素連在一起。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"stand up without studio polish","meaning":"沒有錄音室修飾也站得住腳","examples":[{"en":"The music must stand up without studio polish.","zh":"音樂必須沒有錄音室修飾也站得住腳。"},{"en":"To stand up without studio polish means to remain strong even without recording effects or corrections.","zh":"stand up without studio polish 指即使沒有錄音效果或修正，仍然有力量。"},{"en":"A singer’s voice stands up without studio polish when it sounds moving in a simple live clip.","zh":"如果歌手在簡單現場片段中仍令人感動，她的聲音就是沒有錄音室修飾也站得住腳。"},{"en":"If a song cannot stand up without studio polish, it may depend too much on production.","zh":"如果一首歌沒有錄音室修飾就站不住腳，它可能太依賴製作。"},{"en":"This phrase helps judge whether the music itself is strong.","zh":"這個短語幫助判斷音樂本身是否強。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"studio polish","meaning":"錄音室修飾","examples":[{"en":"Studio polish can make an ordinary song sound impressive.","zh":"錄音室修飾可以令一首普通歌曲聽起來出色。"},{"en":"Studio polish means professional recording, mixing, effects, and corrections that make music sound smoother.","zh":"studio polish 指專業錄音、混音、效果和修正，令音樂聽起來更流暢。"},{"en":"Studio polish can improve weak vocals by adjusting pitch and balance.","zh":"錄音室修飾可以透過調整音準和平衡改善較弱的人聲。"},{"en":"Too much studio polish may make a song feel perfect but less personal.","zh":"太多錄音室修飾可能令歌曲完美，但較不個人化。"},{"en":"Live clips reveal what remains when studio polish is removed.","zh":"現場片段揭示當錄音室修飾被拿走後還剩下甚麼。"}],"source":"2019 Q5.pdf","sourcePage":10},{"front":"save me from","meaning":"令我避免","examples":[{"en":"This method has saved her from following hype blindly.","zh":"這種方法令她避免盲目追捧熱潮。"},{"en":"To save me from something means to protect me from a mistake, danger, or bad habit.","zh":"save me from something 指保護我免於錯誤、危險或壞習慣。"},{"en":"Checking reviews saved me from buying a phone with poor battery life.","zh":"查看評論令我避免買到電池很差的手機。"},{"en":"A clear budget can save students from spending all their money on trends.","zh":"清楚預算可以令學生避免把所有錢花在潮流上。"},{"en":"This phrase shows that careful habits can prevent poor decisions.","zh":"這個短語顯示仔細習慣可以防止差劣決定。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"follow hype blindly","meaning":"盲目追捧熱潮","examples":[{"en":"She does not want to follow hype blindly.","zh":"她不想盲目追捧熱潮。"},{"en":"To follow hype blindly means to believe or join excitement without thinking carefully.","zh":"follow hype blindly 指不仔細思考就相信或加入熱烈追捧。"},{"en":"Some shoppers follow hype blindly and buy viral products they never use.","zh":"有些購物者盲目追捧熱潮，購買自己從不用的爆紅產品。"},{"en":"Students may follow hype blindly when they choose a course only because everyone talks about it.","zh":"當學生只因人人都在談論就選一門課，他們可能是在盲目追捧熱潮。"},{"en":"This phrase warns against letting excitement replace judgement.","zh":"這個短語警告不要讓興奮取代判斷。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"viral chorus","meaning":"爆紅副歌","examples":[{"en":"Not every viral chorus belongs on her playlist.","zh":"不是每段爆紅副歌都值得放進她的播放清單。"},{"en":"A viral chorus is the part of a song that spreads widely online.","zh":"viral chorus 指在網上廣泛傳播的一首歌的副歌部分。"},{"en":"A viral chorus may be catchy even if the full song is weak.","zh":"爆紅副歌可能很易記，即使整首歌較弱。"},{"en":"People often remember a viral chorus because it is used repeatedly in short videos.","zh":"人們常記得爆紅副歌，因為它在短片中被反覆使用。"},{"en":"This phrase reminds listeners to judge the whole song, not only the famous part.","zh":"這個短語提醒聽眾判斷整首歌，而不只是著名部分。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"belong on my playlist","meaning":"值得放進我的播放清單","examples":[{"en":"Not every viral chorus belongs on her playlist.","zh":"不是每段爆紅副歌都值得放進她的播放清單。"},{"en":"Belong on my playlist means be good or meaningful enough for me to save and listen to again.","zh":"belong on my playlist 指足夠好或有意義，值得我保存並再次聆聽。"},{"en":"A song belongs on my playlist if I still enjoy it after the trend fades.","zh":"如果潮流退去後我仍喜歡一首歌，它就值得放進我的播放清單。"},{"en":"A catchy chorus may not belong on my playlist if the rest of the song feels empty.","zh":"如果歌曲其他部分空洞，易記的副歌也未必值得放進我的播放清單。"},{"en":"This phrase turns music choice into a personal judgement.","zh":"這個短語把音樂選擇變成個人判斷。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"underrated singer","meaning":"被低估的歌手","examples":[{"en":"Not every underrated singer is boring.","zh":"不是每位被低估的歌手都沉悶。"},{"en":"An underrated singer is a singer who deserves more attention or praise than they receive.","zh":"underrated singer 指值得更多注意或讚賞，但實際得到較少的歌手。"},{"en":"An underrated singer may have a small audience but a powerful voice.","zh":"被低估的歌手可能觀眾不多，但聲音很有力量。"},{"en":"Listeners may discover an underrated singer through a live session rather than a viral clip.","zh":"聽眾可能透過現場錄音演出，而不是爆紅短片，發現被低估的歌手。"},{"en":"This phrase reminds us that popularity and quality are not always the same.","zh":"這個短語提醒我們，受歡迎程度和質素不一定相同。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"the online crowd","meaning":"網上群眾","examples":[{"en":"Sometimes the online crowd is right.","zh":"有時網上群眾是對的。"},{"en":"The online crowd means a large group of internet users reacting to the same person, product, or trend.","zh":"the online crowd 指大量網民對同一人物、產品或潮流作出反應。"},{"en":"The online crowd can help a small artist gain attention quickly.","zh":"網上群眾可以幫助小眾歌手快速得到注意。"},{"en":"The online crowd can also exaggerate excitement until everything seems important.","zh":"網上群眾也可以誇大興奮感，直到每件事都看似重要。"},{"en":"This phrase treats online opinion as powerful but not always wise.","zh":"這個短語把網上意見視為有力量，但不一定明智。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"simply loud","meaning":"只是聲音很大；只是很吵","examples":[{"en":"Sometimes the online crowd is simply loud.","zh":"有時網上群眾只是聲音很大。"},{"en":"Simply loud means noisy, forceful, or attention-grabbing, but not necessarily correct.","zh":"simply loud 指吵鬧、有力或吸引注意，但不一定正確。"},{"en":"A small group can seem important online if it is simply loud.","zh":"如果一小群人在網上只是聲音很大，也可能看似很重要。"},{"en":"An opinion that is simply loud may drown out quieter, wiser voices.","zh":"只是聲音很大的意見可能淹沒較安靜、較明智的聲音。"},{"en":"This phrase warns that volume is not the same as truth.","zh":"這個短語提醒我們，聲量不等於真相。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"what matters is not whether..., but whether...","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not whether a source is trendy, but whether it helps her think clearly.","zh":"重要的不是一個來源是否潮流，而是它是否幫助她清晰思考。"},{"en":"This structure means the important question is the second idea, not the first one.","zh":"這個結構表示重要問題是第二個想法，而不是第一個。"},{"en":"What matters is not whether shoes are famous, but whether they fit your feet.","zh":"重要的不是鞋是否有名，而是它們是否合腳。"},{"en":"What matters is not whether a video is popular, but whether it teaches something useful.","zh":"重要的不是影片是否受歡迎，而是它是否教到有用的東西。"},{"en":"This pattern helps writers shift attention from appearance to real value.","zh":"這個句式幫助作者把注意力從外觀轉向真正價值。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"traditional or trendy","meaning":"傳統或潮流","examples":[{"en":"A source may be traditional or trendy.","zh":"一個來源可能傳統或潮流。"},{"en":"Traditional or trendy means either older and established, or new and fashionable.","zh":"traditional or trendy 指較舊且有根基，或較新且時尚。"},{"en":"A newspaper is traditional, while a short-video platform is trendy.","zh":"報紙是傳統的，而短片平台是潮流的。"},{"en":"A traditional or trendy source can be useful if it helps readers think clearly.","zh":"如果一個傳統或潮流的來源能幫助讀者清晰思考，它就有用。"},{"en":"This phrase reminds us not to judge sources only by age or popularity.","zh":"這個短語提醒我們不要只按年代或受歡迎程度判斷來源。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"think more clearly","meaning":"更清晰地思考","examples":[{"en":"Good sources help her think more clearly.","zh":"好來源幫助她更清晰地思考。"},{"en":"To think more clearly means to understand ideas better and make wiser decisions.","zh":"think more clearly 指更好地理解想法並作出更明智的決定。"},{"en":"Writing notes can help students think more clearly before an exam.","zh":"記筆記可以幫助學生在考試前更清晰地思考。"},{"en":"Reading balanced reviews can help shoppers think more clearly before buying a trend.","zh":"閱讀平衡的評論可以幫助購物者在購買潮流產品前更清晰地思考。"},{"en":"This phrase shows that information should improve judgement, not create confusion.","zh":"這個短語顯示資訊應改善判斷，而不是製造混亂。"}],"source":"2019 Q5.pdf","sourcePage":11},{"front":"choose between","meaning":"在……之間二選一","examples":[{"en":"Readers should not choose between newspapers and social media.","zh":"讀者不應在報紙和社交媒體之間二選一。"},{"en":"To choose between two things means to select one and reject the other.","zh":"choose between two things 指選擇其中一方並拒絕另一方。"},{"en":"Students do not always need to choose between reading books and watching educational videos.","zh":"學生不一定要在閱讀書本和觀看教育影片之間二選一。"},{"en":"If both sources are useful, choosing between them may create a false problem.","zh":"如果兩個來源都有用，在它們之間二選一可能製造假問題。"},{"en":"This phrase often appears when a writer discusses alternatives.","zh":"當作者討論不同選項時，這個短語常會出現。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"as if","meaning":"彷彿；好像","examples":[{"en":"Do not treat newspapers and social media as if one must destroy the other.","zh":"不要對待報紙和社交媒體，好像一方必須摧毀另一方。"},{"en":"As if means like something were true, even when it may not be true.","zh":"as if 指好像某事是真的，即使它未必是真的。"},{"en":"He speaks as if he knows everything, but he has not read the report.","zh":"他說話好像甚麼都知道，但他沒有讀過報告。"},{"en":"People sometimes treat new technology as if it must replace all older methods.","zh":"人們有時對待新科技，好像它必須取代所有舊方法。"},{"en":"This phrase helps show an imagined or mistaken way of seeing things.","zh":"這個短語有助顯示想像中或錯誤的看法。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"one must destroy the other","meaning":"一方必須取代另一方","examples":[{"en":"Newspapers and social media do not have to destroy each other.","zh":"報紙和社交媒體不一定要一方取代另一方。"},{"en":"One must destroy the other means only one can survive, so the other must disappear.","zh":"one must destroy the other 指只有一方能存在，所以另一方必須消失。"},{"en":"Online classes and classroom teaching do not mean one must destroy the other.","zh":"網上課堂和實體課堂並不代表一方必須取代另一方。"},{"en":"When people think one method must destroy the other, they may miss useful combinations.","zh":"當人們認為一種方法必須取代另一種方法，他們可能錯過有用的結合。"},{"en":"This phrase criticises an extreme either-or view.","zh":"這個短語批評極端的二選一看法。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"there is something to be said for both","meaning":"兩者都有可取之處","examples":[{"en":"There is something to be said for both newspapers and social media.","zh":"報紙和社交媒體兩者都有可取之處。"},{"en":"There is something to be said for both means both sides have some value or reasonable points.","zh":"there is something to be said for both 指雙方都有一些價值或合理之處。"},{"en":"There is something to be said for both studying alone and studying with friends.","zh":"獨自溫習和與朋友一起溫習，兩者都有可取之處。"},{"en":"There is something to be said for both cheap clothes and durable clothes, depending on need.","zh":"便宜衣服和耐穿衣服兩者都有可取之處，視乎需要而定。"},{"en":"This phrase helps writers give a balanced opinion.","zh":"這個短語幫助作者提出平衡意見。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"immediacy","meaning":"即時性","examples":[{"en":"Social media gives readers immediacy, colour and surprise.","zh":"社交媒體給讀者即時性、色彩和驚喜。"},{"en":"Immediacy means the quality of happening or being available right away.","zh":"immediacy 指某事立即發生或立即可得的特質。"},{"en":"Live news alerts give readers immediacy because they appear as events happen.","zh":"即時新聞通知提供即時性，因為它們在事件發生時出現。"},{"en":"Immediacy can be exciting, but it may leave little time for careful judgement.","zh":"即時性可以令人興奮，但可能留下很少時間作仔細判斷。"},{"en":"In pop culture, immediacy helps people feel close to trends as they form.","zh":"在流行文化中，即時性幫助人們在潮流形成時感覺貼近它。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"colour and surprise","meaning":"色彩和驚喜","examples":[{"en":"Social media gives readers colour and surprise.","zh":"社交媒體給讀者色彩和驚喜。"},{"en":"Colour and surprise means liveliness, variety, and unexpected interest.","zh":"colour and surprise 指生氣、多樣性和意想不到的趣味。"},{"en":"A school fair gains colour and surprise when students perform music and sell handmade food.","zh":"當學生表演音樂和售賣手製食物，學校嘉年華就增添色彩和驚喜。"},{"en":"Social media adds colour and surprise because users post from many places and moods.","zh":"社交媒體增添色彩和驚喜，因為用戶從許多地方和心情發布內容。"},{"en":"This phrase shows the attractive energy of new media.","zh":"這個短語顯示新媒體吸引人的活力。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"background, judgement and vocabulary","meaning":"背景、判斷力和詞彙","examples":[{"en":"Magazines and reviews give readers background, judgement and vocabulary.","zh":"雜誌和評論給讀者背景、判斷力和詞彙。"},{"en":"Background, judgement and vocabulary means context, careful evaluation, and the words needed to discuss something.","zh":"background, judgement and vocabulary 指背景資料、仔細評估，以及討論某事所需的字詞。"},{"en":"A film review gives background, judgement and vocabulary when it explains the director, quality, and style.","zh":"電影評論解釋導演、質素和風格時，就是提供背景、判斷力和詞彙。"},{"en":"Students need background, judgement and vocabulary to write better cultural essays.","zh":"學生需要背景、判斷力和詞彙，才能寫出更好的文化文章。"},{"en":"This phrase shows what slower, more careful sources can provide.","zh":"這個短語顯示較慢、較仔細的來源可以提供甚麼。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"build your own information diet","meaning":"建立自己的資訊飲食","examples":[{"en":"Readers can build their own pop-culture information diet.","zh":"讀者可以建立自己的流行文化資訊飲食。"},{"en":"To build your own information diet means to choose a balanced set of sources you regularly consume.","zh":"build your own information diet 指選擇一套自己定期接收的平衡資訊來源。"},{"en":"A student builds her own information diet by reading news, watching explainers, and checking facts.","zh":"學生透過閱讀新聞、觀看解說影片和核實事實，建立自己的資訊飲食。"},{"en":"A poor information diet may include only gossip, ads, and angry comments.","zh":"差劣的資訊飲食可能只包括八卦、廣告和憤怒評論。"},{"en":"This phrase compares information habits to eating habits.","zh":"這個短語把資訊習慣比作飲食習慣。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"pop-culture information diet","meaning":"流行文化資訊飲食","examples":[{"en":"A pop-culture information diet can combine videos, magazines and reviews.","zh":"流行文化資訊飲食可以結合影片、雜誌和評論。"},{"en":"A pop-culture information diet is the regular mix of sources a person uses to learn about popular culture.","zh":"pop-culture information diet 指一個人定期用來了解流行文化的資訊來源組合。"},{"en":"A balanced pop-culture information diet may include short videos for discovery and reviews for judgement.","zh":"平衡的流行文化資訊飲食可以包括用於發現的短片和用於判斷的評論。"},{"en":"If a pop-culture information diet contains only viral posts, it may become shallow.","zh":"如果流行文化資訊飲食只包含爆紅帖文，它可能變得膚淺。"},{"en":"This phrase encourages readers to choose sources actively.","zh":"這個短語鼓勵讀者主動選擇來源。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"first impressions","meaning":"第一印象","examples":[{"en":"TikTok and Instagram are useful for first impressions.","zh":"TikTok 和 Instagram 對第一印象很有用。"},{"en":"First impressions are the first feelings or opinions you form when you see something.","zh":"first impressions 指你第一次看見某事時形成的感覺或看法。"},{"en":"A short video can give first impressions of a new fashion trend.","zh":"一段短片可以提供對新時裝潮流的第一印象。"},{"en":"First impressions are useful, but they may change after reading more careful reviews.","zh":"第一印象有用，但在閱讀更仔細的評論後可能會改變。"},{"en":"This phrase shows the beginning of judgement, not the final decision.","zh":"這個短語顯示判斷的開始，而不是最終決定。"}],"source":"2019 Q5.pdf","sourcePage":12},{"front":"music criticism","meaning":"音樂評論","examples":[{"en":"Pitchfork is useful for music criticism.","zh":"Pitchfork 對音樂評論很有用。"},{"en":"Music criticism is writing or discussion that evaluates music and explains its meaning or quality.","zh":"music criticism 是評價音樂並解釋其意義或質素的寫作或討論。"},{"en":"Good music criticism may discuss lyrics, production, performance, and cultural background.","zh":"好的音樂評論可能討論歌詞、製作、表演和文化背景。"},{"en":"Music criticism can help listeners understand why an album succeeds or fails.","zh":"音樂評論可以幫助聽眾理解一張專輯為何成功或失敗。"},{"en":"This phrase shows that music can be studied thoughtfully, not only enjoyed casually.","zh":"這個短語顯示音樂可以被仔細研究，而不只是隨意享受。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"live performance","meaning":"現場表演","examples":[{"en":"Tiny Concerts Live Studio is useful for live performance.","zh":"Tiny Concerts Live Studio 對現場表演很有用。"},{"en":"Live performance is music, theatre, dance, or another art performed in real time.","zh":"live performance 指音樂、戲劇、舞蹈或其他藝術的即時表演。"},{"en":"A live performance can show whether a singer has control, emotion, and stage presence.","zh":"現場表演可以顯示歌手是否有控制力、情感和舞台魅力。"},{"en":"Live performance may include small mistakes, but those mistakes can make it feel real.","zh":"現場表演可能有小錯誤，但那些錯誤可以令它感覺真實。"},{"en":"This phrase matters because performance quality cannot always be judged from studio recordings.","zh":"這個短語很重要，因為表演質素不一定能從錄音室版本判斷。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"trends will keep changing","meaning":"潮流會不斷改變","examples":[{"en":"Trends will keep changing in fashion and music.","zh":"時裝和音樂潮流會不斷改變。"},{"en":"Trends will keep changing means popular styles and interests will continue to become different over time.","zh":"trends will keep changing 指受歡迎的風格和興趣會隨時間繼續變化。"},{"en":"School slang will keep changing as students invent new phrases.","zh":"隨着學生創造新短語，校園潮語會不斷改變。"},{"en":"Because trends keep changing, buying every fashionable item is impossible.","zh":"因為潮流會不斷改變，購買每件時尚物品是不可能的。"},{"en":"This phrase reminds readers that no trend stays important forever.","zh":"這個短語提醒讀者，沒有潮流會永遠重要。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"sooner or later","meaning":"遲早","examples":[{"en":"Sooner or later, today’s must-have item will become tomorrow’s joke.","zh":"遲早，今天的必買單品會變成明天的笑話。"},{"en":"Sooner or later means eventually, at some time in the future.","zh":"sooner or later 指最終、將來某個時候。"},{"en":"Sooner or later, a phone battery will wear out and need replacing.","zh":"遲早，電話電池會老化並需要更換。"},{"en":"A trend that feels serious today may seem funny sooner or later.","zh":"今天感覺嚴肅的潮流，遲早可能變得好笑。"},{"en":"This phrase shows that time will eventually change the situation.","zh":"這個短語顯示時間最終會改變情況。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"must-have item","meaning":"必買單品；必備物品","examples":[{"en":"Today’s must-have item may become tomorrow’s joke.","zh":"今天的必買單品可能變成明天的笑話。"},{"en":"A must-have item is something people feel they need because it is popular or useful.","zh":"must-have item 指人們因為它受歡迎或有用而覺得必須擁有的東西。"},{"en":"A viral water bottle can become a must-have item at school.","zh":"一個爆紅水樽可以在學校成為必買單品。"},{"en":"Some must-have items are genuinely useful, while others are only temporarily fashionable.","zh":"有些必備物品真的有用，另一些只是暫時時尚。"},{"en":"This phrase shows how desire can be shaped by trends.","zh":"這個短語顯示慾望如何被潮流塑造。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"tomorrow’s joke","meaning":"明天的笑話","examples":[{"en":"Today’s must-have item may become tomorrow’s joke.","zh":"今天的必買單品可能變成明天的笑話。"},{"en":"Tomorrow’s joke means something that people may laugh at or find silly in the future.","zh":"tomorrow’s joke 指將來人們可能取笑或覺得愚蠢的東西。"},{"en":"A hairstyle that everyone wants today may become tomorrow’s joke in old photos.","zh":"今天人人想要的髮型，可能在舊照片中變成明天的笑話。"},{"en":"Calling a trend tomorrow’s joke warns that popularity can fade quickly.","zh":"把潮流稱為明天的笑話，是提醒人們受歡迎程度可能很快消退。"},{"en":"This phrase encourages readers not to take every trend too seriously.","zh":"這個短語鼓勵讀者不要把每個潮流都看得太嚴重。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"with the right sources","meaning":"有了合適的資訊來源","examples":[{"en":"With the right sources, readers can enjoy pop culture more wisely.","zh":"有了合適的資訊來源，讀者可以更明智地享受流行文化。"},{"en":"With the right sources means if people use helpful, reliable, and suitable information sources.","zh":"with the right sources 指如果人們使用有幫助、可靠和合適的資訊來源。"},{"en":"With the right sources, students can understand a news story instead of repeating rumours.","zh":"有了合適的資訊來源，學生可以理解新聞事件，而不是重複謠言。"},{"en":"A shopper with the right sources can compare products before spending money.","zh":"有了合適資訊來源的購物者，可以在花錢前比較產品。"},{"en":"This phrase shows that better information leads to better choices.","zh":"這個短語顯示更好的資訊帶來更好的選擇。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"enjoy the scroll","meaning":"享受滑手機瀏覽的樂趣","examples":[{"en":"Readers can enjoy the scroll without being controlled by it.","zh":"讀者可以享受滑手機瀏覽的樂趣，而不被它控制。"},{"en":"To enjoy the scroll means to take pleasure in browsing online posts and videos.","zh":"enjoy the scroll 指從瀏覽網上帖文和影片中得到樂趣。"},{"en":"A student can enjoy the scroll after homework without believing every advertisement.","zh":"學生可以在做完功課後享受滑手機瀏覽的樂趣，但不相信每個廣告。"},{"en":"Enjoying the scroll becomes healthier when users know when to stop.","zh":"當用戶知道何時停止，享受滑手機瀏覽會變得更健康。"},{"en":"This phrase accepts social media pleasure but warns against losing control.","zh":"這個短語接受社交媒體的樂趣，但提醒人不要失去控制。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"be controlled by","meaning":"被……控制","examples":[{"en":"Young people should not be controlled by the algorithm.","zh":"年輕人不應被推薦算法控制。"},{"en":"To be controlled by something means to let it strongly direct your choices or behaviour.","zh":"be controlled by something 指讓某事強烈支配自己的選擇或行為。"},{"en":"A shopper may be controlled by discounts if every sale makes her buy more.","zh":"如果每次減價都令購物者買更多，她可能被折扣控制。"},{"en":"Students should not be controlled by fear when choosing subjects.","zh":"學生選科時不應被恐懼控制。"},{"en":"In the essay, the goal is to use media without being controlled by it.","zh":"在文章中，目標是使用媒體而不被它控制。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"after all","meaning":"畢竟","examples":[{"en":"Pop culture, after all, is not just about keeping up.","zh":"畢竟，流行文化不只是關於跟上潮流。"},{"en":"After all means when you consider the most important reason or truth.","zh":"after all 指當你考慮最重要的原因或真相時。"},{"en":"You should rest tonight; after all, you have an exam tomorrow.","zh":"你今晚應該休息；畢竟，你明天有考試。"},{"en":"A trend may be fun, but after all, your own comfort still matters.","zh":"潮流可能有趣，但畢竟，你自己的舒適仍然重要。"},{"en":"This phrase often introduces a final, thoughtful reminder.","zh":"這個短語常引入最後而有思考的提醒。"}],"source":"2019 Q5.pdf","sourcePage":13},{"front":"keeping up","meaning":"跟上潮流","examples":[{"en":"Pop culture is not just about keeping up.","zh":"流行文化不只是關於跟上潮流。"},{"en":"Keeping up means staying informed about what is new or changing.","zh":"keeping up 指了解新的或正在改變的事物。"},{"en":"Students keep up with schoolwork by reviewing notes every week.","zh":"學生透過每週溫習筆記來跟上課業。"},{"en":"Keeping up with trends can be tiring if something new appears every day.","zh":"如果每天都有新東西出現，跟上潮流可能令人疲倦。"},{"en":"This phrase shows the pressure to remain current.","zh":"這個短語顯示保持貼近當下的壓力。"}],"source":"2019 Q5.pdf","sourcePage":14},{"front":"worth carrying with us","meaning":"值得帶着前行；值得保留下來","examples":[{"en":"Pop culture is also about knowing what is worth carrying with us.","zh":"流行文化也關於知道甚麼值得帶着前行。"},{"en":"Worth carrying with us means valuable enough to remember, keep, or bring into the future.","zh":"worth carrying with us 指有足夠價值，值得我們記住、保留或帶到未來。"},{"en":"A song is worth carrying with us if it still comforts us after the trend ends.","zh":"如果一首歌在潮流結束後仍安慰我們，它就值得帶着前行。"},{"en":"Family stories are worth carrying with us because they teach identity and memory.","zh":"家庭故事值得保留下來，因為它們教我們身份和記憶。"},{"en":"This phrase ends the essay by asking readers to choose lasting value, not only passing fashion.","zh":"這個短語在文章結尾要求讀者選擇長久價值，而不只是短暫時尚。"}],"source":"2019 Q5.pdf","sourcePage":14}],"dse/writing/part-b/2019/Q6":[{"front":"takes flight","meaning":"起飛；展翅高飛","examples":[{"en":"Cinderella takes flight in this superhero fairytale.","zh":"Cinderella 在這個超級英雄童話中展翅高飛。"},{"en":"Takes flight means begins to fly or begins to become exciting and successful.","zh":"Takes flight 指開始飛起來，或開始變得精彩和成功。"},{"en":"The story takes flight when the quiet servant discovers her hidden power.","zh":"當那位安靜僕人發現自己的隱藏力量時，故事便展翅高飛。"},{"en":"A film can take flight when its action, emotion, and music finally come together.","zh":"當動作、情感和音樂終於結合起來，一部電影就可以起飛。"},{"en":"This phrase suggests movement upward, both physically and imaginatively.","zh":"這個短語暗示向上的動作，包括實際和想像上的提升。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"slipper-fast","meaning":"像玻璃鞋般飛快的；飛快的","examples":[{"en":"The film is described as a slipper-fast superhero fairytale.","zh":"這部電影被形容為像玻璃鞋般飛快的超級英雄童話。"},{"en":"Slipper-fast is a playful phrase meaning extremely quick, with a clear link to Cinderella’s glass slipper.","zh":"Slipper-fast 是帶玩味的說法，意思是非常快速，並明顯連繫到 Cinderella 的玻璃鞋。"},{"en":"The chase feels slipper-fast as Cinderella races across the palace roof.","zh":"當 Cinderella 衝過宮殿屋頂時，追逐場面像玻璃鞋般飛快。"},{"en":"A story can feel slipper-fast when scenes move quickly without becoming confusing.","zh":"當場景快速推進但不令人混亂，故事可以顯得飛快。"},{"en":"This invented phrase adds humour while describing speed.","zh":"這個自創短語一邊加入幽默，一邊描述速度。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"superhero fairytale","meaning":"超級英雄童話","examples":[{"en":"This version turns Cinderella into a superhero fairytale.","zh":"這個版本把 Cinderella 變成一個超級英雄童話。"},{"en":"A superhero fairytale mixes magical story elements with heroic powers and world-saving action.","zh":"Superhero fairytale 把魔法故事元素與英雄力量和拯救世界的行動混合起來。"},{"en":"A princess who flies, fights villains, and protects a kingdom belongs in a superhero fairytale.","zh":"會飛、打反派並保護王國的公主，屬於超級英雄童話。"},{"en":"This type of story changes a familiar fairy tale into an adventure about courage and power.","zh":"這類故事把熟悉童話變成關於勇氣和力量的冒險。"},{"en":"The phrase helps readers expect both magic and action.","zh":"這個短語幫助讀者預期故事既有魔法，也有動作場面。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, Cinderella sounds like the safest film in the world.","zh":"乍看之下，Cinderella 聽起來像世界上最穩陣保守的電影。"},{"en":"At first glance means when you look at or consider something quickly for the first time.","zh":"At first glance 指第一次快速看或考慮某事時。"},{"en":"At first glance, the old book looked boring, but its story was exciting.","zh":"乍看之下，那本舊書看似沉悶，但故事其實很精彩。"},{"en":"People may judge a film wrongly at first glance if they only know its title.","zh":"如果人們只知道片名，可能會在乍看之下錯誤判斷一部電影。"},{"en":"This phrase often introduces an early impression that may later change.","zh":"這個短語常引出之後可能改變的早期印象。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"sounds like","meaning":"聽起來像","examples":[{"en":"Cinderella sounds like the safest film in the world.","zh":"Cinderella 聽起來像世界上最穩陣保守的電影。"},{"en":"Sounds like means seems to be something based on what you hear, read, or are told.","zh":"Sounds like 指根據聽到、讀到或被告知的內容，感覺某事像某種東西。"},{"en":"The lesson sounds like a simple review, but it may include difficult ideas.","zh":"那堂課聽起來像簡單溫習，但可能包含困難概念。"},{"en":"A film can sound like a children’s story before viewers discover its deeper message.","zh":"一部電影在觀眾發現其深層訊息前，可能聽起來像兒童故事。"},{"en":"This phrase describes an impression, not a confirmed fact.","zh":"這個短語描述印象，而不是已確認的事實。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"the safest film in the world","meaning":"最穩陣保守的電影","examples":[{"en":"At first glance, Cinderella sounds like the safest film in the world.","zh":"乍看之下，Cinderella 聽起來像世界上最穩陣保守的電影。"},{"en":"The safest film in the world means a film that seems very familiar, harmless, and unlikely to surprise anyone.","zh":"The safest film in the world 指看起來非常熟悉、無害，而且不太可能令人驚訝的電影。"},{"en":"A remake of a famous fairy tale may look like the safest film in the world before it changes the story.","zh":"一部著名童話翻拍片在改變故事前，可能看似最穩陣保守的電影。"},{"en":"Studios may choose a safe story because audiences already know it.","zh":"電影公司可能選擇穩陣故事，因為觀眾已經熟悉它。"},{"en":"This phrase can be ironic when the film later proves bold or unusual.","zh":"當電影後來證明大膽或不尋常時，這個短語可以帶諷刺意味。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"a cruel stepmother","meaning":"惡毒繼母","examples":[{"en":"The story includes a pretty girl, a cruel stepmother and a grand ball.","zh":"這個故事包括一位漂亮女孩、一位惡毒繼母和一場盛大舞會。"},{"en":"A cruel stepmother is a stepmother who treats her stepchild harshly or unfairly.","zh":"A cruel stepmother 指嚴厲或不公平對待繼子女的繼母。"},{"en":"In many old tales, a cruel stepmother gives the heroine too much work and too little love.","zh":"在許多舊童話中，惡毒繼母給女主角太多工作和太少關愛。"},{"en":"Cruel treatment at home can make a character feel powerless and alone.","zh":"家中的殘酷對待可以令角色感到無力和孤單。"},{"en":"This phrase helps set up conflict in a family-based story.","zh":"這個短語幫助建立家庭故事中的衝突。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"a grand ball","meaning":"盛大舞會","examples":[{"en":"Cinderella usually makes people think of a grand ball and a lost shoe.","zh":"Cinderella 通常令人想到一場盛大舞會和一隻遺失的鞋。"},{"en":"A grand ball is a large formal dance, often held in a palace or elegant hall.","zh":"A grand ball 指大型正式舞會，通常在宮殿或優雅大廳舉行。"},{"en":"Guests at a grand ball may wear gowns, suits, masks, and jewellery.","zh":"參加盛大舞會的賓客可能穿禮服、西裝、戴面具和佩戴珠寶。"},{"en":"In fairy tales, a grand ball often creates a chance for hidden identity to be revealed.","zh":"在童話中，盛大舞會常製造機會，讓隱藏身份被揭示。"},{"en":"This phrase suggests wealth, ceremony, and romance.","zh":"這個短語暗示財富、儀式感和浪漫。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"on closer inspection","meaning":"仔細看時","examples":[{"en":"On closer inspection, this new adaptation is anything but safe.","zh":"仔細看時，這部新改編作品絕不保守。"},{"en":"On closer inspection means after looking at something more carefully.","zh":"On closer inspection 指更仔細觀察某事之後。"},{"en":"On closer inspection, the simple cartoon contained a serious message about loneliness.","zh":"仔細看時，那部簡單卡通包含關於孤獨的嚴肅訊息。"},{"en":"A story may seem ordinary at first, but on closer inspection it may be brave and original.","zh":"一個故事起初可能看似普通，但仔細看時可能大膽而原創。"},{"en":"This phrase helps move from first impression to deeper judgement.","zh":"這個短語幫助由第一印象轉向更深入判斷。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"new adaptation","meaning":"新改編作品","examples":[{"en":"This new adaptation of Princesses of Power is anything but safe.","zh":"這部 Princesses of Power 的新改編作品絕不保守。"},{"en":"A new adaptation is a fresh version of an older story, book, comic, or film.","zh":"A new adaptation 指舊故事、書、漫畫或電影的新版本。"},{"en":"A new adaptation may keep the main character but change the setting and message.","zh":"新改編作品可能保留主角，但改變背景和訊息。"},{"en":"Viewers compare a new adaptation with the original to see what has changed.","zh":"觀眾會把新改編作品與原作比較，看看有甚麼改變。"},{"en":"This phrase is useful when old material is remade for a new audience.","zh":"當舊材料被重新製作給新觀眾時，這個短語很有用。"}],"source":"2019 Q6.pdf","sourcePage":1},{"front":"comic series","meaning":"漫畫系列","examples":[{"en":"The film is adapted from the 1950s comic series Princesses of Power.","zh":"這部電影改編自 1950 年代的漫畫系列 Princesses of Power。"},{"en":"A comic series is a set of connected stories told through drawings, panels, and speech bubbles.","zh":"A comic series 指透過圖畫、分格和對話框講述的一系列相連故事。"},{"en":"A comic series may follow the same heroes across many issues.","zh":"漫畫系列可能在多期中跟隨同一批英雄。"},{"en":"Films adapted from a comic series often keep visual energy and dramatic action.","zh":"改編自漫畫系列的電影常保留視覺活力和戲劇動作。"},{"en":"This phrase tells readers the source of the story.","zh":"這個短語告訴讀者故事來源。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"anything but safe","meaning":"絕不保守；絕不穩陣","examples":[{"en":"This new adaptation is anything but safe.","zh":"這部新改編作品絕不保守。"},{"en":"Anything but safe means not safe, ordinary, or predictable at all.","zh":"Anything but safe 指完全不穩陣、不普通或不可預測。"},{"en":"The lesson looked easy, but the questions were anything but safe.","zh":"那堂課看似容易，但題目絕不簡單穩陣。"},{"en":"A fairy-tale film becomes anything but safe when it challenges old ideas about princesses.","zh":"當童話電影挑戰關於公主的舊想法，它就變得絕不保守。"},{"en":"This phrase strongly rejects the first impression.","zh":"這個短語有力否定第一印象。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"most audiences think they know","meaning":"大多數觀眾以為自己熟悉的","examples":[{"en":"The film takes the fairy tale most audiences think they know.","zh":"這部電影取用了大多數觀眾以為自己熟悉的童話。"},{"en":"“Most audiences think they know” means many viewers believe a story is already familiar to them.","zh":"“Most audiences think they know” 指很多觀眾相信自己已經熟悉某個故事。"},{"en":"Most audiences think they know Cinderella because they remember the ball and the slipper.","zh":"大多數觀眾以為自己熟悉 Cinderella，因為他們記得舞會和玻璃鞋。"},{"en":"A remake can surprise people by changing a story most audiences think they know.","zh":"翻拍作品可以透過改變大多數觀眾以為自己熟悉的故事，令人驚喜。"},{"en":"This phrase suggests that familiarity may be incomplete.","zh":"這個短語暗示熟悉感可能並不完整。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"straps a cape onto","meaning":"為……披上斗篷","examples":[{"en":"The film straps a cape onto a familiar fairy tale.","zh":"這部電影為一個熟悉童話披上斗篷。"},{"en":"To strap a cape onto something means to give it superhero qualities in a playful way.","zh":"To strap a cape onto something 指以帶玩味的方式賦予某事超級英雄特質。"},{"en":"The movie straps a cape onto Cinderella by turning her into a flying heroine.","zh":"電影把 Cinderella 變成會飛的女英雄，就是為她披上斗篷。"},{"en":"A writer can strap a cape onto an old legend by adding rescue missions and powers.","zh":"作者可以透過加入拯救任務和能力，為古老傳說披上斗篷。"},{"en":"This phrase makes the change sound energetic and imaginative.","zh":"這個短語令改變聽起來充滿活力和想像力。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"the result is","meaning":"結果是","examples":[{"en":"The result is a colourful and confident adventure.","zh":"結果是一場色彩繽紛而自信的冒險。"},{"en":"The result is means this is what happens because of earlier choices or actions.","zh":"The result is 指因之前的選擇或行動而產生的結果。"},{"en":"The director mixes comedy, action, and feeling; the result is a lively family film.","zh":"導演混合喜劇、動作和情感；結果是一部活潑的家庭電影。"},{"en":"When a story combines old magic with new questions, the result can feel fresh.","zh":"當故事把舊魔法和新問題結合，結果可能感覺新鮮。"},{"en":"This phrase clearly introduces an outcome.","zh":"這個短語清楚引出結果。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"surprisingly moving","meaning":"出乎意料地動人","examples":[{"en":"The film is a colourful, confident and surprisingly moving adventure.","zh":"這部電影是一場色彩繽紛、自信而出乎意料地動人的冒險。"},{"en":"Surprisingly moving means unexpectedly touching or emotionally powerful.","zh":"Surprisingly moving 指出乎意料地感人或情感力量強。"},{"en":"The superhero scenes are exciting, but the lonely moments are surprisingly moving.","zh":"超級英雄場面很刺激，但孤獨時刻出乎意料地動人。"},{"en":"A funny film can be surprisingly moving when it treats its characters seriously.","zh":"當喜劇認真對待角色，它可以出乎意料地動人。"},{"en":"This phrase shows that the emotional effect is stronger than expected.","zh":"這個短語顯示情感效果比預期更強。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"does not simply dream of","meaning":"不只是夢想","examples":[{"en":"Cinderella does not simply dream of being chosen by a prince.","zh":"Cinderella 不只是夢想被王子選中。"},{"en":"Does not simply dream of means wants more than one traditional or limited goal.","zh":"Does not simply dream of 指追求的不只是某個傳統或有限目標。"},{"en":"The heroine does not simply dream of escape; she plans to change the kingdom.","zh":"女主角不只是夢想逃走；她計劃改變王國。"},{"en":"A student may not simply dream of good marks, but of using knowledge to help others.","zh":"學生可能不只是夢想好成績，而是夢想用知識幫助別人。"},{"en":"This phrase rejects a narrow expectation.","zh":"這個短語否定狹窄的期待。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"being chosen by","meaning":"被……選中","examples":[{"en":"She does not simply dream of being chosen by a prince.","zh":"她不只是夢想被王子選中。"},{"en":"Being chosen by someone means being selected, accepted, or approved by that person.","zh":"Being chosen by someone 指被某人挑選、接受或認可。"},{"en":"In old fairy tales, heroines often wait for being chosen by someone powerful.","zh":"在舊童話中，女主角常等待被有權力的人選中。"},{"en":"Depending only on being chosen by others can make a character seem passive.","zh":"只依賴被別人選中，可能令角色顯得被動。"},{"en":"This phrase is useful when discussing approval and power.","zh":"這個短語適合討論認可和權力。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"chooses to save the world","meaning":"選擇拯救世界","examples":[{"en":"She chooses to save the world.","zh":"她選擇拯救世界。"},{"en":"Chooses to save the world means actively decides to protect others from great danger.","zh":"Chooses to save the world 指主動決定保護別人免受巨大危險。"},{"en":"Cinderella chooses to save the world instead of waiting for someone to rescue her.","zh":"Cinderella 選擇拯救世界，而不是等待別人拯救她。"},{"en":"A hero becomes active when she chooses to save others despite fear.","zh":"當英雄即使害怕仍選擇拯救他人，她就變得主動。"},{"en":"This phrase shows agency, courage, and responsibility.","zh":"這個短語顯示主動性、勇氣和責任。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"begins with","meaning":"以……開始","examples":[{"en":"The film begins with a lovely comic-book opening.","zh":"這部電影以一個可愛的漫畫式開場開始。"},{"en":"Begins with means starts with a particular scene, action, or idea.","zh":"Begins with 指以某個場景、動作或想法作為開端。"},{"en":"The lesson begins with a simple question before moving to difficult examples.","zh":"課堂以一個簡單問題開始，然後進入困難例子。"},{"en":"A film that begins with strong images can quickly pull viewers into its world.","zh":"以強烈畫面開始的電影，可以很快把觀眾帶進它的世界。"},{"en":"This phrase helps explain structure and sequence.","zh":"這個短語幫助解釋結構和次序。"}],"source":"2019 Q6.pdf","sourcePage":2},{"front":"comic-book opening","meaning":"漫畫式開場","examples":[{"en":"The film begins with a lovely comic-book opening.","zh":"這部電影以一個可愛的漫畫式開場開始。"},{"en":"A comic-book opening is an opening scene designed to look or feel like pages from a comic.","zh":"A comic-book opening 指設計得像漫畫頁面的開場場面。"},{"en":"A comic-book opening may use panels, bold colours, and dramatic lettering.","zh":"漫畫式開場可能使用分格、鮮明色彩和戲劇化字體。"},{"en":"This opening prepares viewers for a story shaped by superhero style.","zh":"這種開場讓觀眾準備進入一個受超級英雄風格影響的故事。"},{"en":"The phrase describes both visual design and storytelling mood.","zh":"這個短語同時描述視覺設計和敘事氣氛。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"turns the pages of","meaning":"翻動……的頁面","examples":[{"en":"A hand turns the pages of an old twelve-cent issue.","zh":"一隻手翻動一本舊的十二美仙期刊的頁面。"},{"en":"Turns the pages of means moves pages one by one in a book, magazine, or comic.","zh":"Turns the pages of 指逐頁翻動書、雜誌或漫畫。"},{"en":"The child turned the pages of the picture book slowly to see every detail.","zh":"孩子慢慢翻動圖畫書的頁面，為了看清每個細節。"},{"en":"A film may show someone turning pages to introduce an old story.","zh":"電影可能展示有人翻頁，以介紹一個舊故事。"},{"en":"This phrase describes a simple action that can open a memory or narrative.","zh":"這個短語描述簡單動作，但可以開啟記憶或敘事。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"a twelve-cent issue","meaning":"一本售價十二美仙的期刊","examples":[{"en":"A hand turns the pages of an old twelve-cent issue.","zh":"一隻手翻動一本舊的十二美仙期刊的頁面。"},{"en":"A twelve-cent issue is an old magazine or comic that originally cost twelve cents.","zh":"A twelve-cent issue 指原本售價十二美仙的舊雜誌或漫畫。"},{"en":"A collector may keep a twelve-cent issue because it shows the style of an earlier time.","zh":"收藏家可能保留一本十二美仙期刊，因為它顯示早期年代的風格。"},{"en":"The price makes the comic feel old and nostalgic.","zh":"這個價錢令漫畫感覺古舊而懷舊。"},{"en":"This phrase gives a small historical detail that builds atmosphere.","zh":"這個短語提供一個細小歷史細節，用來營造氣氛。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"taken into","meaning":"被帶進","examples":[{"en":"We are taken into the smoky kingdom of Belloria.","zh":"我們被帶進 Belloria 這個煙霧瀰漫的王國。"},{"en":"Taken into means brought or led into a place, story, or situation.","zh":"Taken into 指被帶入或引進某個地方、故事或情況。"},{"en":"The opening music takes viewers into a mysterious forest.","zh":"開場音樂把觀眾帶進神秘森林。"},{"en":"A good introduction can take students into a difficult topic gently.","zh":"好的引言可以溫和地把學生帶進困難課題。"},{"en":"This phrase shows movement into a new world or experience.","zh":"這個短語顯示進入新世界或新經歷的動作。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"smoky kingdom","meaning":"煙霧瀰漫的王國","examples":[{"en":"We are taken into the smoky kingdom of Belloria.","zh":"我們被帶進 Belloria 這個煙霧瀰漫的王國。"},{"en":"A smoky kingdom is a kingdom filled with smoke, mist, darkness, or a troubled atmosphere.","zh":"A smoky kingdom 指充滿煙、霧、黑暗或不安氣氛的王國。"},{"en":"The smoky kingdom looks dangerous because its sky is grey and its streets are dim.","zh":"那個煙霧瀰漫的王國看起來危險，因為天空灰暗、街道昏暗。"},{"en":"Smoke can make a fantasy world feel mysterious or damaged.","zh":"煙霧可以令奇幻世界顯得神秘或受破壞。"},{"en":"This phrase gives the setting a dark visual mood.","zh":"這個短語為背景加入陰暗的視覺氣氛。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"has been frozen at","meaning":"被凍結在","examples":[{"en":"The sky has been frozen at eleven minutes to midnight.","zh":"天空被凍結在午夜前十一分鐘。"},{"en":"Has been frozen at means has been stopped and held at a particular time, state, or position.","zh":"Has been frozen at 指被停止並固定在某個時間、狀態或位置。"},{"en":"The classroom clock seemed frozen at three o’clock as students waited for the bell.","zh":"學生等待鐘聲時，課室時鐘彷彿被凍結在三點。"},{"en":"In fantasy stories, time may be frozen at a dangerous moment to create tension.","zh":"在奇幻故事中，時間可能被凍結在危險一刻，以製造緊張感。"},{"en":"This phrase suggests that normal change has been stopped.","zh":"這個短語暗示正常變化被停止。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"eleven minutes to midnight","meaning":"午夜前十一分鐘","examples":[{"en":"The sky has been frozen at eleven minutes to midnight.","zh":"天空被凍結在午夜前十一分鐘。"},{"en":"Eleven minutes to midnight means 11:49 p.m., shortly before midnight.","zh":"Eleven minutes to midnight 指晚上十一時四十九分，即快到午夜。"},{"en":"Eleven minutes to midnight feels urgent because the final hour is almost over.","zh":"午夜前十一分鐘感覺很緊急，因為最後一小時快結束。"},{"en":"A story set at eleven minutes to midnight suggests that time is running out.","zh":"設定在午夜前十一分鐘的故事，暗示時間快用完。"},{"en":"This phrase creates suspense by placing danger close to a deadline.","zh":"這個短語把危險放近最後期限，製造懸念。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"nicknamed","meaning":"被暱稱為","examples":[{"en":"Ella is nicknamed Cinderella because she works among the ashes.","zh":"Ella 因為在灰燼中工作而被暱稱為 Cinderella。"},{"en":"Nicknamed means given an informal name, often based on appearance, behaviour, or experience.","zh":"Nicknamed 指被給予非正式名字，通常基於外貌、行為或經歷。"},{"en":"The tall student was nicknamed Tower by his basketball teammates.","zh":"那位高大的學生被籃球隊友暱稱為 Tower。"},{"en":"Ella’s nickname comes from the cinders and ashes around her work.","zh":"Ella 的暱稱來自她工作周圍的煤灰和灰燼。"},{"en":"This word explains how a casual name can carry meaning.","zh":"這個詞解釋隨意名字如何帶有意義。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"works among the ashes","meaning":"在灰燼中工作","examples":[{"en":"Ella works among the ashes of the palace furnace.","zh":"Ella 在宮殿火爐的灰燼中工作。"},{"en":"Works among the ashes means does dirty or low-status work near burned remains.","zh":"Works among the ashes 指在燃燒後的灰燼旁做骯髒或低等工作。"},{"en":"A servant who works among the ashes may clean fireplaces and carry coal.","zh":"在灰燼中工作的僕人可能要清理壁爐和搬煤。"},{"en":"This kind of work shows how far Ella has fallen from her former life.","zh":"這種工作顯示 Ella 與從前生活相差很遠。"},{"en":"The phrase connects physical dirt with social humiliation.","zh":"這個短語把身體上的骯髒與社會上的羞辱連接起來。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"palace furnace","meaning":"宮殿火爐","examples":[{"en":"Cinderella works among the ashes of the palace furnace.","zh":"Cinderella 在宮殿火爐的灰燼中工作。"},{"en":"A palace furnace is a heating place or large fire system inside a palace.","zh":"A palace furnace 指宮殿內用來供暖的大火爐或火系統。"},{"en":"The palace furnace may keep rooms warm but leave servants covered in soot.","zh":"宮殿火爐可能讓房間溫暖，卻令僕人滿身煤灰。"},{"en":"Working near a furnace can show the hard labour hidden behind royal beauty.","zh":"在火爐旁工作可以顯示王室美麗背後隱藏的辛勞。"},{"en":"This phrase contrasts palace luxury with servant hardship.","zh":"這個短語對比宮殿奢華與僕人困苦。"}],"source":"2019 Q6.pdf","sourcePage":3},{"front":"no ordinary servant","meaning":"並非普通僕人","examples":[{"en":"Ella is no ordinary servant.","zh":"Ella 並非普通僕人。"},{"en":"No ordinary servant means not a typical servant because she has unusual qualities, history, or powers.","zh":"No ordinary servant 指並不是典型僕人，因為她有不尋常特質、過去或力量。"},{"en":"Ella seems poor and powerless, but she is no ordinary servant.","zh":"Ella 看似貧窮無力，但她並非普通僕人。"},{"en":"A character may be no ordinary servant if she once protected the kingdom.","zh":"如果一個角色曾保護王國，她就可能並非普通僕人。"},{"en":"This phrase prepares readers for a hidden identity.","zh":"這個短語讓讀者準備發現隱藏身份。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"before her father disappeared","meaning":"在她父親失蹤之前","examples":[{"en":"Before her father disappeared, Ella was one of the Princesses of Power.","zh":"在她父親失蹤之前，Ella 是 Power 公主團的一員。"},{"en":"Before her father disappeared means during the time before he went missing.","zh":"Before her father disappeared 指在她父親不知所蹤之前的時期。"},{"en":"Before her father disappeared, Ella lived with more freedom and respect.","zh":"在她父親失蹤之前，Ella 過着更自由、更受尊重的生活。"},{"en":"A disappearance can divide a character’s life into a happy past and a difficult present.","zh":"一次失蹤可以把角色人生分成快樂過去和困難現在。"},{"en":"This phrase introduces an important event that changed Ella’s life.","zh":"這個短語引出改變 Ella 人生的重要事件。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"one of the Princesses of Power","meaning":"Power 公主團的一員","examples":[{"en":"Ella was one of the Princesses of Power.","zh":"Ella 是 Power 公主團的一員。"},{"en":"One of the Princesses of Power means a member of a group of heroic princesses with special abilities.","zh":"One of the Princesses of Power 指一個擁有特殊能力的英雄公主團體成員。"},{"en":"Ella was not alone; she was one of the Princesses of Power who protected Belloria.","zh":"Ella 並不孤單；她是保護 Belloria 的 Power 公主團的一員。"},{"en":"Being one of the group gives her a past identity and a shared mission.","zh":"作為團體一員，給予她過去身份和共同使命。"},{"en":"This phrase shows membership in a heroic team.","zh":"這個短語顯示她屬於一支英雄團隊。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"secret order","meaning":"秘密組織","examples":[{"en":"The Princesses of Power were a secret order of young heroines.","zh":"Power 公主團是一個由年輕女英雄組成的秘密組織。"},{"en":"A secret order is a hidden group with shared rules, duties, or beliefs.","zh":"A secret order 指一個擁有共同規則、責任或信念的隱密團體。"},{"en":"The secret order trained young heroines to protect the realm without public praise.","zh":"這個秘密組織訓練年輕女英雄在沒有公眾讚賞下保護王國。"},{"en":"Secret orders often appear in fantasy stories because they create mystery and loyalty.","zh":"秘密組織常出現在奇幻故事中，因為它們製造神秘感和忠誠感。"},{"en":"This phrase suggests organisation, secrecy, and purpose.","zh":"這個短語暗示組織、秘密和目的。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"young heroines","meaning":"年輕女英雄","examples":[{"en":"The secret order was made up of young heroines.","zh":"這個秘密組織由年輕女英雄組成。"},{"en":"Young heroines are brave female characters, often girls or young women, who help others.","zh":"Young heroines 指勇敢的女性角色，通常是女孩或年輕女性，會幫助他人。"},{"en":"Young heroines may be inexperienced, but they can still make courageous choices.","zh":"年輕女英雄可能經驗不足，但仍能作出勇敢選擇。"},{"en":"Stories about young heroines show that age does not limit bravery.","zh":"關於年輕女英雄的故事顯示，年齡不會限制勇氣。"},{"en":"This phrase focuses on female courage and action.","zh":"這個短語集中表現女性勇氣和行動。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"protected the realm","meaning":"保護王國","examples":[{"en":"The young heroines protected the realm.","zh":"年輕女英雄保護王國。"},{"en":"Protected the realm means defended the kingdom or land from danger.","zh":"Protected the realm 指保衛王國或土地免受危險。"},{"en":"The guards protected the realm from monsters beyond the mountains.","zh":"守衛保護王國免受山外怪物侵襲。"},{"en":"Heroes protect the realm when ordinary people cannot fight the threat alone.","zh":"當普通人不能獨自對抗威脅時，英雄便保護王國。"},{"en":"This phrase is common in fantasy stories about duty and defence.","zh":"這個短語常見於關於責任和防衛的奇幻故事。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"public identity","meaning":"公眾身份","examples":[{"en":"Lady Malvora has stolen Ella’s public identity.","zh":"Lady Malvora 偷走了 Ella 的公眾身份。"},{"en":"Public identity means the name, image, and role by which other people recognise someone.","zh":"Public identity 指別人用來認出某人的名字、形象和角色。"},{"en":"A superhero’s public identity may be very different from her secret life.","zh":"超級英雄的公眾身份可能與秘密生活很不同。"},{"en":"If someone steals Ella’s public identity, people no longer know who she truly is.","zh":"如果有人偷走 Ella 的公眾身份，人們就不再知道她真正是誰。"},{"en":"This phrase connects reputation with recognition.","zh":"這個短語把名聲和被認出連接起來。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"most of her powers","meaning":"她大部分的力量","examples":[{"en":"Lady Malvora has stolen most of Ella’s powers.","zh":"Lady Malvora 偷走了 Ella 大部分的力量。"},{"en":"Most of her powers means the greater part of her special abilities.","zh":"Most of her powers 指她特殊能力中的大部分。"},{"en":"Ella can still think and choose, even after losing most of her powers.","zh":"即使失去大部分力量，Ella 仍能思考和選擇。"},{"en":"A villain who steals most of a hero’s powers makes the hero seem vulnerable.","zh":"反派偷走英雄大部分力量，會令英雄顯得脆弱。"},{"en":"This phrase shows serious loss without saying everything is gone.","zh":"這個短語顯示嚴重失去，但不是說一切都沒有了。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"leaving someone invisible","meaning":"令某人像隱形一樣","examples":[{"en":"Malvora leaves Ella invisible in her own home.","zh":"Malvora 令 Ella 在自己的家裏像隱形一樣。"},{"en":"Leaving someone invisible means making a person feel unseen, ignored, or unrecognised.","zh":"Leaving someone invisible 指令某人感到不被看見、被忽視或不被認出。"},{"en":"A quiet student may feel invisible if teachers never call on them.","zh":"如果老師從不叫一位安靜學生回答，他可能感到像隱形一樣。"},{"en":"Ella is invisible because people fail to recognise her value and identity.","zh":"Ella 像隱形一樣，因為人們沒有認出她的價值和身份。"},{"en":"This phrase can be magical or emotional, depending on the context.","zh":"這個短語可帶魔法意思，也可帶情感意思，視乎語境。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"in her own home","meaning":"在她自己的家裏","examples":[{"en":"Ella is invisible in her own home.","zh":"Ella 在她自己的家裏像隱形一樣。"},{"en":"In her own home means inside the place where she should feel safe and recognised.","zh":"In her own home 指在她本應感到安全和被認出的地方。"},{"en":"A child should not feel lonely in her own home.","zh":"孩子不應在自己的家裏感到孤單。"},{"en":"Being ignored in her own home makes Ella’s suffering feel especially painful.","zh":"在自己的家裏被忽視，令 Ella 的痛苦顯得特別深。"},{"en":"This phrase stresses that the hurt happens in a place that should protect her.","zh":"這個短語強調傷害發生在本應保護她的地方。"}],"source":"2019 Q6.pdf","sourcePage":4},{"front":"only when","meaning":"只有當……才","examples":[{"en":"Only when the clock strikes midnight can Ella’s true form be restored.","zh":"只有當時鐘敲響午夜，Ella 的真正形態才可以被恢復。"},{"en":"Only when means something can happen only under one necessary condition.","zh":"Only when 指某事只有在一個必要條件下才會發生。"},{"en":"Only when students practise often can they speak more naturally.","zh":"只有當學生經常練習，他們才可以說得更自然。"},{"en":"Ella’s power returns only when a specific magical time arrives.","zh":"Ella 的力量只有在特定魔法時間到來時才回來。"},{"en":"This phrase makes the condition feel strict and important.","zh":"這個短語令條件顯得嚴格而重要。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"the clock strikes midnight","meaning":"時鐘敲響午夜","examples":[{"en":"Ella’s true form can be restored when the clock strikes midnight.","zh":"當時鐘敲響午夜，Ella 的真正形態可以被恢復。"},{"en":"The clock strikes midnight means the clock sounds twelve at night.","zh":"The clock strikes midnight 指時鐘在晚上十二點響起。"},{"en":"In fairy tales, the clock striking midnight often changes magic or identity.","zh":"在童話中，時鐘敲響午夜常改變魔法或身份。"},{"en":"When the clock strikes midnight, Cinderella must act before Malvora opens the gate.","zh":"時鐘敲響午夜時，Cinderella 必須在 Malvora 打開大門前行動。"},{"en":"This phrase creates a clear deadline in the story.","zh":"這個短語在故事中製造清楚的最後期限。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"true form","meaning":"真正形態","examples":[{"en":"Ella’s true form can be restored at midnight.","zh":"Ella 的真正形態可以在午夜被恢復。"},{"en":"True form means someone’s real shape, identity, or natural state.","zh":"True form 指某人的真實形狀、身份或自然狀態。"},{"en":"The monster’s true form was revealed when the spell broke.","zh":"咒語解除時，怪物的真正形態被揭示。"},{"en":"Ella wants her true form back because she wants to be seen as herself.","zh":"Ella 想取回真正形態，因為她想以自己本來的樣子被看見。"},{"en":"This phrase is common in fantasy stories about disguise and transformation.","zh":"這個短語常見於關於偽裝和變身的奇幻故事。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"be restored","meaning":"被恢復","examples":[{"en":"Her true form can be restored at midnight.","zh":"她的真正形態可以在午夜被恢復。"},{"en":"Be restored means be brought back to an earlier, proper, or complete state.","zh":"Be restored 指被帶回較早、正常或完整的狀態。"},{"en":"Old paintings can be restored when experts clean and repair them carefully.","zh":"專家細心清潔和修復後，舊畫可以被恢復原貌。"},{"en":"Ella’s identity must be restored before the kingdom can be saved.","zh":"Ella 的身份必須被恢復，王國才可以被拯救。"},{"en":"This phrase suggests recovery after damage or loss.","zh":"這個短語暗示在受損或失去後復原。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"the catch is that","meaning":"問題是；難處在於","examples":[{"en":"The catch is that Malvora also plans to open the dark gate at midnight.","zh":"問題是 Malvora 也計劃在午夜打開黑暗之門。"},{"en":"The catch is that means the problem or hidden difficulty is this.","zh":"The catch is that 指問題或隱藏難處在於這一點。"},{"en":"The ticket is free, but the catch is that you must arrive before sunrise.","zh":"門票是免費的，但問題是你必須在日出前到達。"},{"en":"Ella can regain her form at midnight, but the catch is that the villain acts then too.","zh":"Ella 可以在午夜恢復形態，但難處在於反派也在那時行動。"},{"en":"This phrase introduces a complication.","zh":"這個短語引出複雜情況。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"plans to","meaning":"計劃去","examples":[{"en":"Malvora plans to open the dark gate above the castle.","zh":"Malvora 計劃在城堡上方打開黑暗之門。"},{"en":"Plans to means intends or prepares to do something.","zh":"Plans to 指打算或準備做某事。"},{"en":"The class plans to visit the museum after finishing the history unit.","zh":"班級計劃在完成歷史單元後參觀博物館。"},{"en":"A villain who plans to open a dark gate creates danger before the action happens.","zh":"反派計劃打開黑暗之門，會在行動發生前先製造危險。"},{"en":"This phrase shows intention and future action.","zh":"這個短語顯示意圖和未來行動。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"dark gate","meaning":"黑暗之門","examples":[{"en":"Malvora plans to open the dark gate above the castle.","zh":"Malvora 計劃在城堡上方打開黑暗之門。"},{"en":"A dark gate is a magical entrance connected to danger, evil, or another world.","zh":"A dark gate 指與危險、邪惡或另一個世界相連的魔法入口。"},{"en":"The dark gate glows above the castle and frightens the people below.","zh":"黑暗之門在城堡上方發光，嚇怕下面的人民。"},{"en":"Opening a dark gate can let destructive forces enter the kingdom.","zh":"打開黑暗之門可能讓破壞力量進入王國。"},{"en":"This phrase creates fantasy danger through a simple image.","zh":"這個短語用簡單畫面製造奇幻危險。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"above the castle","meaning":"在城堡上方","examples":[{"en":"The dark gate appears above the castle.","zh":"黑暗之門出現在城堡上方。"},{"en":"Above the castle means in the sky or space over the castle.","zh":"Above the castle 指在城堡上空或上方空間。"},{"en":"A storm gathered above the castle before the final battle.","zh":"最終決戰前，暴風雨在城堡上方聚集。"},{"en":"When danger appears above the castle, the whole kingdom can see the threat.","zh":"當危險出現在城堡上方，整個王國都能看見威脅。"},{"en":"This phrase helps place the action clearly in a scene.","zh":"這個短語幫助清楚交代場景中的位置。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"recover the glass slipper","meaning":"取回玻璃鞋","examples":[{"en":"Cinderella must recover the glass slipper.","zh":"Cinderella 必須取回玻璃鞋。"},{"en":"To recover the glass slipper means to get the slipper back after it has been lost or taken.","zh":"To recover the glass slipper 指在玻璃鞋遺失或被奪走後把它取回。"},{"en":"Cinderella must recover the glass slipper because it now holds magical power.","zh":"Cinderella 必須取回玻璃鞋，因為它現在藏有魔法力量。"},{"en":"A hero often has to recover an important object before saving others.","zh":"英雄常要取回重要物件，才能拯救他人。"},{"en":"This phrase turns a familiar fairy-tale object into a mission goal.","zh":"這個短語把熟悉童話物件變成任務目標。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"reimagined as","meaning":"被重新想像成","examples":[{"en":"The glass slipper is reimagined as a crystal power-core.","zh":"玻璃鞋被重新想像成水晶能量核心。"},{"en":"Reimagined as means redesigned or reinterpreted as something new.","zh":"Reimagined as 指被重新設計或重新詮釋成新的東西。"},{"en":"The old castle is reimagined as a school for young heroes.","zh":"舊城堡被重新想像成一所年輕英雄學校。"},{"en":"A familiar object can feel fresh when it is reimagined as a source of power.","zh":"當熟悉物件被重新想像成力量來源，它可以變得新鮮。"},{"en":"This phrase is useful when adaptations change meaning creatively.","zh":"當改編作品有創意地改變意義時，這個短語很有用。"}],"source":"2019 Q6.pdf","sourcePage":5},{"front":"crystal power-core","meaning":"水晶能量核心","examples":[{"en":"The glass slipper is reimagined as a crystal power-core.","zh":"玻璃鞋被重新想像成水晶能量核心。"},{"en":"A crystal power-core is a magical or technological energy source made of crystal.","zh":"A crystal power-core 指由水晶構成的魔法或科技能量來源。"},{"en":"The crystal power-core gives Cinderella the strength to fly and fight.","zh":"水晶能量核心給 Cinderella 飛行和戰鬥的力量。"},{"en":"If the crystal power-core breaks, the kingdom’s protection may fail.","zh":"如果水晶能量核心破裂，王國的保護可能失效。"},{"en":"This phrase gives the glass slipper a superhero function.","zh":"這個短語賦予玻璃鞋超級英雄功能。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"the kingdom will fall","meaning":"王國將會淪陷","examples":[{"en":"If Cinderella cannot recover the slipper, the kingdom will fall.","zh":"如果 Cinderella 無法取回玻璃鞋，王國將會淪陷。"},{"en":"The kingdom will fall means the kingdom will be defeated, destroyed, or taken over.","zh":"The kingdom will fall 指王國將被擊敗、毀滅或佔領。"},{"en":"If the walls break during the attack, the kingdom will fall.","zh":"如果城牆在攻擊中破裂，王國將會淪陷。"},{"en":"Fantasy stories use this phrase to show that the danger affects everyone.","zh":"奇幻故事使用這個短語來顯示危險影響所有人。"},{"en":"This phrase creates high stakes for the hero’s mission.","zh":"這個短語為英雄任務製造重大利害關係。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"could easily have become","meaning":"本來很容易變成","examples":[{"en":"This plot could easily have become ridiculous.","zh":"這個情節本來很容易變得荒謬。"},{"en":"Could easily have become means had a strong chance of turning into something else.","zh":"Could easily have become 指很有可能變成另一種情況。"},{"en":"The joke could easily have become offensive without careful writing.","zh":"如果寫得不小心，那個笑話本來很容易變得冒犯。"},{"en":"A strange story idea could easily have become silly if the director did not treat it sincerely.","zh":"如果導演沒有真誠處理，一個奇怪故事構思本來很容易變得愚蠢。"},{"en":"This phrase shows a danger that was avoided.","zh":"這個短語顯示某種危險被避免了。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"ridiculous","meaning":"荒謬的","examples":[{"en":"The plot could easily have become ridiculous.","zh":"這個情節本來很容易變得荒謬。"},{"en":"Ridiculous means silly, unreasonable, or hard to take seriously.","zh":"Ridiculous 指愚蠢、不合理或難以認真看待。"},{"en":"A superhero glass slipper might sound ridiculous if the story has no emotion.","zh":"如果故事沒有情感，超級英雄玻璃鞋可能聽起來很荒謬。"},{"en":"An idea becomes less ridiculous when the film explains why it matters.","zh":"當電影解釋某個想法為何重要，它就不那麼荒謬。"},{"en":"This word is useful for judging tone and believability.","zh":"這個詞適合用來判斷語氣和可信度。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"keeps it swift and sincere","meaning":"令……節奏明快而真誠","examples":[{"en":"Director Chris Wong keeps the film swift and sincere.","zh":"導演 Chris Wong 令這部電影節奏明快而真誠。"},{"en":"Keeps it swift and sincere means makes the film move quickly while still feeling honest.","zh":"Keeps it swift and sincere 指令電影推進快速，同時仍感覺真實。"},{"en":"A teacher can keep a lesson swift and sincere by explaining clearly without rushing feelings.","zh":"老師可以透過清楚解釋而不急促處理情感，令課堂明快而真誠。"},{"en":"The film avoids silliness because the director keeps the action fast and the emotions real.","zh":"電影避免變得愚蠢，因為導演令動作快速、情感真實。"},{"en":"This phrase praises both pace and emotional honesty.","zh":"這個短語同時讚賞節奏和情感真誠。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"swift and sincere","meaning":"節奏明快而真誠","examples":[{"en":"The director keeps the adventure swift and sincere.","zh":"導演令這場冒險節奏明快而真誠。"},{"en":"Swift and sincere means fast-moving but emotionally honest.","zh":"Swift and sincere 指推進快速但情感真實。"},{"en":"A short speech can be swift and sincere if it says something true without wasting time.","zh":"如果短演講不浪費時間又說出真心話，就可以節奏明快而真誠。"},{"en":"An adventure feels swift when it never drags, and sincere when characters matter.","zh":"冒險不拖慢時感覺明快；角色令人重視時感覺真誠。"},{"en":"This phrase combines speed with warmth.","zh":"這個短語把速度和溫度結合起來。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"flying scenes","meaning":"飛行場面","examples":[{"en":"The flying scenes are especially impressive.","zh":"飛行場面特別令人印象深刻。"},{"en":"Flying scenes are parts of a film where characters move through the air.","zh":"Flying scenes 指電影中角色在空中移動的部分。"},{"en":"The flying scenes show Cinderella racing above towers and clouds.","zh":"飛行場面展示 Cinderella 在高塔和雲層上方疾馳。"},{"en":"Flying scenes can make a superhero film feel free, fast, and visually exciting.","zh":"飛行場面可以令超級英雄電影感覺自由、快速而視覺刺激。"},{"en":"This phrase refers to action moments involving flight.","zh":"這個短語指涉及飛行的動作場面。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"especially impressive","meaning":"特別令人印象深刻","examples":[{"en":"The flying scenes are especially impressive.","zh":"飛行場面特別令人印象深刻。"},{"en":"Especially impressive means more striking or memorable than other parts.","zh":"Especially impressive 指比其他部分更突出或更令人難忘。"},{"en":"The final speech was especially impressive because it was calm and honest.","zh":"最後演講特別令人印象深刻，因為它平靜而真誠。"},{"en":"A scene becomes especially impressive when its visuals and emotion work together.","zh":"當畫面和情感互相配合，一個場面就會特別令人印象深刻。"},{"en":"This phrase highlights the strongest feature.","zh":"這個短語突出最強的特點。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"one moment…, the next…","meaning":"前一刻……下一刻……","examples":[{"en":"One moment Cinderella is sweeping cinders; the next, she is soaring over towers.","zh":"前一刻 Cinderella 正在清掃煤灰；下一刻，她已在高塔上空翱翔。"},{"en":"One moment…, the next… shows a sudden change from one situation to another.","zh":"One moment…, the next… 顯示從一種情況突然轉到另一種情況。"},{"en":"One moment the room was silent; the next, everyone was cheering.","zh":"前一刻房間一片安靜；下一刻，大家都在歡呼。"},{"en":"This structure makes Cinderella’s change from servant to hero feel fast and dramatic.","zh":"這個結構令 Cinderella 從僕人變成英雄的轉變顯得快速而戲劇化。"},{"en":"It is useful for showing sharp contrast in action.","zh":"它適合用來展示動作中的鮮明對比。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"sweeping cinders","meaning":"清掃煤灰","examples":[{"en":"Cinderella is sweeping cinders from the floor.","zh":"Cinderella 正在清掃地上的煤灰。"},{"en":"Sweeping cinders means cleaning away small pieces of burned coal or ash.","zh":"Sweeping cinders 指清理燒過的煤或灰燼碎屑。"},{"en":"A servant sweeping cinders may become dirty even after hours of work.","zh":"清掃煤灰的僕人可能工作數小時後仍滿身骯髒。"},{"en":"This action shows Cinderella’s low position before she becomes powerful.","zh":"這個動作顯示 Cinderella 在變得有力量前的低微地位。"},{"en":"The phrase connects hard labour with the Cinderella name.","zh":"這個短語把辛苦勞動與 Cinderella 這個名字連接起來。"}],"source":"2019 Q6.pdf","sourcePage":6},{"front":"soaring over","meaning":"在……上空翱翔","examples":[{"en":"Cinderella is soaring over black towers.","zh":"Cinderella 在黑色高塔上空翱翔。"},{"en":"Soaring over means flying high and smoothly above something.","zh":"Soaring over 指在某物上方高高而流暢地飛行。"},{"en":"Birds were soaring over the harbour before sunset.","zh":"日落前，鳥兒在海港上空翱翔。"},{"en":"Cinderella soaring over towers shows freedom after years of being trapped.","zh":"Cinderella 在高塔上空翱翔，顯示她多年被困後得到自由。"},{"en":"This phrase suggests height, speed, and confidence.","zh":"這個短語暗示高度、速度和自信。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"black towers","meaning":"黑色高塔","examples":[{"en":"Cinderella soars over black towers.","zh":"Cinderella 在黑色高塔上空翱翔。"},{"en":"Black towers are tall dark buildings or structures that create a threatening visual image.","zh":"Black towers 指高大而黑暗的建築或結構，製造威脅性的視覺形象。"},{"en":"The black towers rise above the city like shadows.","zh":"黑色高塔像影子一樣在城市上方升起。"},{"en":"Flying over black towers makes Cinderella look brave against danger.","zh":"在黑色高塔上方飛行，令 Cinderella 在危險中顯得勇敢。"},{"en":"This phrase adds a dark fantasy setting to the action.","zh":"這個短語為動作加入黑暗奇幻背景。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"cape cutting through the clouds","meaning":"斗篷劃破雲層","examples":[{"en":"Her cape cuts through the clouds as she flies.","zh":"她飛行時，斗篷劃破雲層。"},{"en":"A cape cutting through the clouds means a cloak moving sharply through mist or cloud during flight.","zh":"A cape cutting through the clouds 指斗篷在飛行時銳利地穿過霧氣或雲層。"},{"en":"The hero’s cape cut through the clouds as she rushed toward the castle.","zh":"女英雄衝向城堡時，斗篷劃破雲層。"},{"en":"This image makes flight look fast, clean, and powerful.","zh":"這個畫面令飛行看起來快速、俐落而有力量。"},{"en":"The phrase turns costume movement into action.","zh":"這個短語把服裝動作變成行動感。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"tumbling from the sky","meaning":"從天空翻滾墜下","examples":[{"en":"The slipper tumbles from the sky.","zh":"玻璃鞋從天空翻滾墜下。"},{"en":"Tumbling from the sky means falling through the air while turning over and over.","zh":"Tumbling from the sky 指在空中一邊翻轉一邊下墜。"},{"en":"Leaves were tumbling from the sky after the strong wind lifted them.","zh":"強風吹起樹葉後，葉子從天空翻滾落下。"},{"en":"A slipper tumbling from the sky creates danger because it may be lost or broken.","zh":"玻璃鞋從天空翻滾墜下會製造危險，因為它可能遺失或破碎。"},{"en":"This phrase shows uncontrolled movement downward.","zh":"這個短語顯示失控地下墜。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"used cleverly","meaning":"被巧妙運用","examples":[{"en":"The image of the slipper is used cleverly.","zh":"玻璃鞋的形象被巧妙運用。"},{"en":"Used cleverly means used in a smart, creative, or meaningful way.","zh":"Used cleverly 指被聰明、有創意或有意義地使用。"},{"en":"The film uses the clock cleverly to create both magic and pressure.","zh":"電影巧妙運用時鐘，同時製造魔法和壓力。"},{"en":"A familiar object is used cleverly when it gains a new purpose in the story.","zh":"當熟悉物件在故事中得到新用途，它就是被巧妙運用。"},{"en":"This phrase praises thoughtful storytelling.","zh":"這個短語讚賞用心的敘事。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"not as…, but as…","meaning":"不是作為……而是作為……","examples":[{"en":"The slipper is used not as a symbol of helplessness, but as a sign of shared power.","zh":"玻璃鞋不是作為無助的象徵，而是作為共享力量的標誌。"},{"en":"Not as…, but as… corrects one meaning and replaces it with another.","zh":"Not as…, but as… 修正一個意思，並以另一個意思取代它。"},{"en":"The test should be seen not as punishment, but as a chance to check learning.","zh":"測驗不應被視作懲罰，而應被視作檢查學習的機會。"},{"en":"The slipper is not shown as weakness, but as power that can be shared.","zh":"玻璃鞋不是被呈現為弱點，而是被呈現為可以共享的力量。"},{"en":"This structure is useful for contrast and reinterpretation.","zh":"這個結構適合用於對比和重新詮釋。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"a symbol of","meaning":"……的象徵","examples":[{"en":"The slipper is not just a symbol of romantic helplessness.","zh":"玻璃鞋不只是浪漫化無助感的象徵。"},{"en":"A symbol of something is an object, person, or image that represents an idea.","zh":"A symbol of something 指代表某個想法的物件、人物或形象。"},{"en":"A dove is often a symbol of peace.","zh":"鴿子常是和平的象徵。"},{"en":"In this film, the slipper becomes a symbol of power rather than dependence.","zh":"在這部電影中，玻璃鞋成為力量的象徵，而不是依賴的象徵。"},{"en":"This phrase helps explain what an image means beyond its literal form.","zh":"這個短語幫助解釋形象在字面以外的意義。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"romantic helplessness","meaning":"浪漫化的無助感","examples":[{"en":"The slipper is not used as a symbol of romantic helplessness.","zh":"玻璃鞋不是作為浪漫化無助感的象徵。"},{"en":"Romantic helplessness means weakness presented as beautiful or attractive in a love story.","zh":"Romantic helplessness 指在愛情故事中把軟弱呈現得美麗或吸引。"},{"en":"A princess waiting for rescue may be shown with romantic helplessness in old tales.","zh":"在舊故事中，等待救援的公主可能帶有浪漫化的無助感。"},{"en":"Modern stories often reject romantic helplessness by giving heroines choices and skills.","zh":"現代故事常透過給女主角選擇和技能，拒絕浪漫化的無助感。"},{"en":"This phrase criticises stories that make passivity look charming.","zh":"這個短語批評把被動描寫得迷人的故事。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"a sign that","meaning":"表示……的象徵","examples":[{"en":"The slipper becomes a sign that power can be lost, found and shared.","zh":"玻璃鞋成為一個象徵，表示力量可以失去、尋回和分享。"},{"en":"A sign that means evidence or a symbol showing that something is true.","zh":"A sign that 指顯示某事真實的證據或象徵。"},{"en":"A student asking questions is a sign that they are thinking seriously.","zh":"學生提問表示他們正在認真思考。"},{"en":"The restored slipper is a sign that Ella’s power can return.","zh":"被修復的玻璃鞋表示 Ella 的力量可以回來。"},{"en":"This phrase links a visible detail to a larger meaning.","zh":"這個短語把可見細節連接到更大意義。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"lost, found and shared","meaning":"失去、尋回和分享","examples":[{"en":"Power can be lost, found and shared.","zh":"力量可以失去、尋回和分享。"},{"en":"Lost, found and shared means something may disappear, be recovered, and then be given to others too.","zh":"Lost, found and shared 指某物可能消失、被找回，然後也給予別人。"},{"en":"Confidence can be lost after failure, found through support, and shared by helping others.","zh":"信心可以在失敗後失去，透過支持尋回，再藉幫助他人分享。"},{"en":"Ella’s power matters because it is not only recovered but also shared.","zh":"Ella 的力量之所以重要，是因為它不只被尋回，也被分享。"},{"en":"This phrase shows a full journey from loss to community.","zh":"這個短語展示由失去到社群的完整旅程。"}],"source":"2019 Q6.pdf","sourcePage":7},{"front":"what makes the story work","meaning":"令故事成功的原因","examples":[{"en":"What makes the story work is the emotional pressure behind the magic.","zh":"令故事成功的原因，是魔法背後的情感張力。"},{"en":"What makes the story work means the reason the story feels successful or believable.","zh":"What makes the story work 指令故事感覺成功或可信的原因。"},{"en":"What makes the comedy work is that the characters still feel real.","zh":"令喜劇成功的原因，是角色仍然感覺真實。"},{"en":"A superhero plot works better when emotion gives the action meaning.","zh":"當情感賦予動作意義，超級英雄情節會更成功。"},{"en":"This phrase identifies the key strength of a story.","zh":"這個短語指出故事的關鍵優點。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"by itself","meaning":"本身；單靠","examples":[{"en":"The magic by itself is not what makes the story work.","zh":"魔法本身並不是令故事成功的原因。"},{"en":"By itself means alone, without help from anything else.","zh":"By itself 指單獨地，不依靠其他東西。"},{"en":"Good visuals by themselves cannot save a film with flat characters.","zh":"好畫面本身不能拯救角色單薄的電影。"},{"en":"Magic by itself may entertain viewers, but emotion makes them care.","zh":"魔法本身可能娛樂觀眾，但情感令他們在乎。"},{"en":"This phrase separates one element from the whole effect.","zh":"這個短語把一個元素與整體效果分開。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"emotional pressure","meaning":"情感張力","examples":[{"en":"The emotional pressure behind the magic makes the story work.","zh":"魔法背後的情感張力令故事成功。"},{"en":"Emotional pressure means strong feelings, worries, or personal stakes that push a character.","zh":"Emotional pressure 指推動角色的強烈感受、憂慮或個人利害關係。"},{"en":"Ella’s loneliness creates emotional pressure behind her fight.","zh":"Ella 的孤獨為她的戰鬥製造情感張力。"},{"en":"A story becomes stronger when action scenes are supported by emotional pressure.","zh":"當動作場面有情感張力支撐，故事會更有力量。"},{"en":"This phrase explains why events feel important, not just exciting.","zh":"這個短語解釋事件為何重要，而不只是刺激。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"behind it","meaning":"在其背後","examples":[{"en":"There is emotional pressure behind Cinderella’s magic.","zh":"Cinderella 的魔法背後有情感張力。"},{"en":"Behind it means underneath or supporting what people can first see.","zh":"Behind it 指在人們首先看見的事物之下或支撐它的東西。"},{"en":"The joke sounds simple, but there is sadness behind it.","zh":"那個笑話聽起來簡單，但背後有悲傷。"},{"en":"Cinderella’s magic matters because there is pain and courage behind it.","zh":"Cinderella 的魔法重要，因為背後有痛苦和勇氣。"},{"en":"This phrase points to a deeper reason beneath the surface.","zh":"這個短語指向表面之下更深層的原因。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"trying to become","meaning":"努力成為","examples":[{"en":"Ella is trying to become brave enough to be seen.","zh":"Ella 正努力成為勇敢得足以被看見的人。"},{"en":"Trying to become means making an effort to develop into a certain kind of person.","zh":"Trying to become 指努力發展成某一種人。"},{"en":"A shy student may be trying to become confident enough to speak in class.","zh":"害羞學生可能正努力成為有信心在課堂發言的人。"},{"en":"Ella’s journey is about trying to become visible and brave, not just beautiful.","zh":"Ella 的旅程是努力成為可被看見和勇敢的人，而不只是變美。"},{"en":"This phrase shows growth through effort.","zh":"這個短語顯示透過努力成長。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"beautiful enough to be loved","meaning":"美麗得足以被愛","examples":[{"en":"Ella is not trying to become beautiful enough to be loved.","zh":"Ella 並不是努力變得美麗得足以被愛。"},{"en":"Beautiful enough to be loved means attractive enough that others will give love or approval.","zh":"Beautiful enough to be loved 指外表吸引到足以得到別人的愛或認可。"},{"en":"The film rejects the idea that a girl must be beautiful enough to be loved.","zh":"這部電影拒絕女孩必須美麗得足以被愛的想法。"},{"en":"Children should not grow up believing they need perfect looks to deserve care.","zh":"孩子不應長大後相信自己需要完美外貌才值得被關心。"},{"en":"This phrase criticises judging worth by appearance.","zh":"這個短語批評以外貌判斷價值。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"brave enough to be seen","meaning":"勇敢得足以被看見","examples":[{"en":"Ella is trying to become brave enough to be seen.","zh":"Ella 正努力成為勇敢得足以被看見的人。"},{"en":"Brave enough to be seen means courageous enough to show one’s true self to others.","zh":"Brave enough to be seen 指有足夠勇氣向別人展示真實自我。"},{"en":"A student is brave enough to be seen when they share their own poem with the class.","zh":"當學生把自己的詩分享給全班時，就是勇敢得足以被看見。"},{"en":"Ella must become brave enough to be seen after years of being ignored.","zh":"Ella 多年被忽視後，必須變得勇敢得足以被看見。"},{"en":"This phrase connects courage with identity and visibility.","zh":"這個短語把勇氣與身份和可見性連接起來。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"portrayed with far more care","meaning":"被刻畫得細心得多","examples":[{"en":"The characters are portrayed with far more care than in the traditional version.","zh":"角色比傳統版本被刻畫得細心得多。"},{"en":"Portrayed with far more care means shown in a more thoughtful, detailed, and respectful way.","zh":"Portrayed with far more care 指以更 thoughtful、更細緻和更尊重的方式呈現。"},{"en":"The stepsisters are portrayed with far more care because they are funny but not simply cruel.","zh":"繼姐妹被刻畫得細心得多，因為她們有喜劇感，但不只是殘酷。"},{"en":"Characters feel richer when writers portray them with care instead of using flat stereotypes.","zh":"當作者細心刻畫角色，而不是使用單薄刻板印象，角色會更豐富。"},{"en":"This phrase praises deeper character writing.","zh":"這個短語讚賞更深入的角色描寫。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"the traditional version","meaning":"傳統版本","examples":[{"en":"The characters are more carefully portrayed than in the traditional version.","zh":"角色比傳統版本被刻畫得更細心。"},{"en":"The traditional version means the older or more familiar form of a story.","zh":"The traditional version 指故事較舊或較熟悉的形式。"},{"en":"In the traditional version, Cinderella often waits for rescue.","zh":"在傳統版本中，Cinderella 常等待救援。"},{"en":"A new adaptation may challenge the traditional version by changing the heroine’s choices.","zh":"新改編作品可能透過改變女主角選擇，挑戰傳統版本。"},{"en":"This phrase helps compare old and new storytelling.","zh":"這個短語幫助比較新舊敘事。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"no longer","meaning":"不再","examples":[{"en":"Cinderella is kind, but she is no longer obedient to the point of silence.","zh":"Cinderella 仍然善良，但她不再順從到沉默的程度。"},{"en":"No longer means not now, although it may have been true before.","zh":"No longer 指現在不再如此，雖然以前可能是這樣。"},{"en":"The child is no longer afraid of reading aloud after months of practice.","zh":"經過數月練習，那孩子不再害怕朗讀。"},{"en":"This Cinderella is no longer a passive girl who waits quietly.","zh":"這個 Cinderella 不再是安靜等待的被動女孩。"},{"en":"The phrase marks an important change from past to present.","zh":"這個短語標示由過去到現在的重要改變。"}],"source":"2019 Q6.pdf","sourcePage":8},{"front":"obedient to the point of silence","meaning":"順從到沉默的程度","examples":[{"en":"Cinderella is no longer obedient to the point of silence.","zh":"Cinderella 不再順從到沉默的程度。"},{"en":"Obedient to the point of silence means so willing to obey that one stops speaking up.","zh":"Obedient to the point of silence 指順從到不再為自己發聲。"},{"en":"A student should not be obedient to the point of silence when something unfair happens.","zh":"當不公平事情發生時，學生不應順從到沉默的程度。"},{"en":"Old fairy tales sometimes praised heroines for being obedient to the point of silence.","zh":"舊童話有時讚美女主角順從到沉默的程度。"},{"en":"This phrase criticises obedience that removes voice and agency.","zh":"這個短語批評令人失去聲音和主動性的順從。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"occasionally fails","meaning":"偶爾失敗","examples":[{"en":"She questions, plans, fights and occasionally fails.","zh":"她會質疑、計劃、戰鬥，也偶爾失敗。"},{"en":"Occasionally fails means sometimes does not succeed, though not all the time.","zh":"Occasionally fails 指有時不成功，但不是一直失敗。"},{"en":"A brave student occasionally fails when learning a hard skill, but keeps practising.","zh":"勇敢學生學習困難技能時會偶爾失敗，但仍繼續練習。"},{"en":"Ella feels more human because she occasionally fails instead of winning every scene.","zh":"Ella 偶爾失敗，而不是每場都勝利，令她更有人性。"},{"en":"This phrase makes success feel earned.","zh":"這個短語令成功顯得是努力得來的。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"in one of the film’s best scenes","meaning":"在電影其中一場最佳戲份中","examples":[{"en":"In one of the film’s best scenes, Cinderella admits that she misses her old face.","zh":"在電影其中一場最佳戲份中，Cinderella 承認她想念自己從前的樣子。"},{"en":"In one of the film’s best scenes means during one of the strongest or most memorable moments in the film.","zh":"In one of the film’s best scenes 指在電影其中一個最強或最難忘的時刻中。"},{"en":"In one of the film’s best scenes, the hero speaks honestly instead of fighting.","zh":"在電影其中一場最佳戲份中，英雄選擇誠實說話，而不是戰鬥。"},{"en":"This phrase prepares readers to pay attention to an important example.","zh":"這個短語讓讀者留意一個重要例子。"},{"en":"It is useful in reviews when highlighting a standout moment.","zh":"在影評中突出精彩時刻時，這個短語很有用。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"admits that","meaning":"承認","examples":[{"en":"She admits that she misses her old face.","zh":"她承認自己想念從前的樣子。"},{"en":"Admits that means honestly says something true, especially something difficult or private.","zh":"Admits that 指誠實說出真相，特別是困難或私人的事情。"},{"en":"The student admits that he did not understand the homework.","zh":"學生承認自己不明白功課。"},{"en":"Cinderella admits a painful feeling, which makes her more believable.","zh":"Cinderella 承認一種痛苦感受，令她更可信。"},{"en":"This phrase often shows honesty and vulnerability.","zh":"這個短語常顯示誠實和脆弱。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"misses her old face","meaning":"想念自己從前的樣子","examples":[{"en":"Cinderella admits that she misses her old face.","zh":"Cinderella 承認她想念自己從前的樣子。"},{"en":"Misses her old face means feels sadness or longing for the way she used to look.","zh":"Misses her old face 指對自己過去的外貌感到思念或傷感。"},{"en":"After the spell changed her appearance, Ella missed her old face and her old life.","zh":"咒語改變她的外貌後，Ella 想念自己從前的樣子和從前的生活。"},{"en":"Missing her old face shows that identity is personal, not just beautiful or ugly.","zh":"想念自己從前的樣子顯示身份是個人的，不只是美或醜。"},{"en":"This phrase connects appearance with memory and selfhood.","zh":"這個短語把外貌與記憶和自我連接起來。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"being unrecognised by","meaning":"不被……認出","examples":[{"en":"Being unrecognised by the people she saved has left her lonely.","zh":"不被她曾拯救的人認出，令她感到孤獨。"},{"en":"Being unrecognised by someone means not being known, identified, or thanked by that person.","zh":"Being unrecognised by someone 指不被某人認識、認出或感謝。"},{"en":"A volunteer may feel hurt after being unrecognised by the community she helped.","zh":"義工幫助社區後不被人認出或肯定，可能會感到受傷。"},{"en":"Ella suffers because being unrecognised by others makes her heroic work feel invisible.","zh":"Ella 受苦，因為不被別人認出令她的英雄行動像隱形一樣。"},{"en":"This phrase shows the pain of not being seen.","zh":"這個短語顯示不被看見的痛苦。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"the people she saved","meaning":"她曾拯救的人","examples":[{"en":"Cinderella feels lonely because the people she saved do not recognise her.","zh":"Cinderella 感到孤獨，因為她曾拯救的人認不出她。"},{"en":"The people she saved are the people she protected or rescued from danger.","zh":"The people she saved 指她保護或從危險中救出的人。"},{"en":"A firefighter may never meet the people she saved during a storm.","zh":"消防員可能永遠不會見到自己在風暴中曾拯救的人。"},{"en":"Ella’s sadness grows because the people she saved cannot thank the real her.","zh":"Ella 的悲傷加深，因為她曾拯救的人不能感謝真正的她。"},{"en":"This phrase gives emotional weight to her hidden heroism.","zh":"這個短語為她隱藏的英雄行為增加情感重量。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"has left her lonely","meaning":"令她感到孤獨","examples":[{"en":"Being unrecognised has left her lonely.","zh":"不被認出令她感到孤獨。"},{"en":"Has left her lonely means has caused her to feel alone and emotionally separated from others.","zh":"Has left her lonely 指令她感到孤單，並在情感上與他人分離。"},{"en":"Moving to a new city has left the student lonely at first.","zh":"搬到新城市起初令那位學生感到孤獨。"},{"en":"Ella’s invisibility has left her lonely because no one knows what she has done.","zh":"Ella 的隱形狀態令她感到孤獨，因為沒有人知道她做過甚麼。"},{"en":"This phrase links an experience to its emotional result.","zh":"這個短語把經歷和情感結果連接起來。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"thankfully","meaning":"幸好","examples":[{"en":"Thankfully, Prince Theo is not a shining trophy.","zh":"幸好，Theo 王子不是一件閃亮的獎品。"},{"en":"Thankfully means fortunately, or it is good that something is true.","zh":"Thankfully 指幸運地，或某事是真的令人覺得好。"},{"en":"Thankfully, the film gives Cinderella a partner, not a rescuer.","zh":"幸好，電影給 Cinderella 一位伙伴，而不是拯救者。"},{"en":"Reviewers use thankfully when they are relieved a story avoids a weak choice.","zh":"影評人慶幸故事避開弱點時，會用 thankfully。"},{"en":"This word shows approval and relief.","zh":"這個詞顯示認同和鬆一口氣。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"a shining trophy","meaning":"閃亮的獎品","examples":[{"en":"Prince Theo is not a shining trophy waiting at the end of the story.","zh":"Theo 王子不是在故事結尾等待着的閃亮獎品。"},{"en":"A shining trophy is a prize-like person or object that exists only as a reward.","zh":"A shining trophy 指像獎品一樣存在、只作為獎賞的人或物。"},{"en":"In weak romances, a prince may become a shining trophy rather than a real character.","zh":"在薄弱愛情故事中，王子可能變成閃亮獎品，而不是真正角色。"},{"en":"Prince Theo avoids this problem because he has his own work and choices.","zh":"Theo 王子避免這個問題，因為他有自己的工作和選擇。"},{"en":"This phrase criticises treating people as prizes.","zh":"這個短語批評把人當成獎品。"}],"source":"2019 Q6.pdf","sourcePage":9},{"front":"waiting at the end of the story","meaning":"在故事結尾等待着","examples":[{"en":"Prince Theo is not a trophy waiting at the end of the story.","zh":"Theo 王子不是在故事結尾等待着的獎品。"},{"en":"Waiting at the end of the story means appearing only as the final reward after everything else is finished.","zh":"Waiting at the end of the story 指只在一切結束後作為最終獎賞出現。"},{"en":"A character should not exist only as someone waiting at the end of the story.","zh":"一個角色不應只作為在故事結尾等待着的人而存在。"},{"en":"The film gives Prince Theo a role before the ending, so he feels more real.","zh":"電影在結局前已給 Theo 王子角色作用，所以他更真實。"},{"en":"This phrase criticises passive story roles.","zh":"這個短語批評被動的故事角色。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"young reporter","meaning":"年輕記者","examples":[{"en":"Prince Theo is a young reporter.","zh":"Theo 王子是一位年輕記者。"},{"en":"A young reporter is a young person whose job is to find information and write or speak about news.","zh":"A young reporter 指負責尋找資料並報道新聞的年輕人。"},{"en":"A young reporter may ask difficult questions that older officials avoid.","zh":"年輕記者可能會提出年長官員避開的尖銳問題。"},{"en":"Making Theo a young reporter gives him curiosity and purpose.","zh":"把 Theo 設定為年輕記者，給予他好奇心和目的。"},{"en":"This phrase explains his role outside romance.","zh":"這個短語解釋他在愛情以外的角色。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"investigates","meaning":"調查","examples":[{"en":"Prince Theo investigates the royal cover-up.","zh":"Theo 王子調查王室掩飾事件。"},{"en":"Investigates means carefully searches for facts about a problem, crime, or secret.","zh":"Investigates 指仔細尋找關於問題、罪案或秘密的事實。"},{"en":"A journalist investigates why the town’s water became unsafe.","zh":"記者調查小鎮食水為何變得不安全。"},{"en":"Theo investigates because the official story does not seem honest.","zh":"Theo 調查，是因為官方說法看似不誠實。"},{"en":"This word shows active questioning.","zh":"這個詞顯示主動提問。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"royal cover-up","meaning":"王室掩飾事件","examples":[{"en":"Prince Theo investigates the royal cover-up.","zh":"Theo 王子調查王室掩飾事件。"},{"en":"A royal cover-up is an attempt by the royal family or palace to hide the truth.","zh":"A royal cover-up 指王室或宮殿試圖隱瞞真相。"},{"en":"The royal cover-up keeps citizens from learning what happened to the Princesses of Power.","zh":"王室掩飾事件令市民無法知道 Power 公主團發生了甚麼事。"},{"en":"A cover-up creates conflict because powerful people are hiding facts.","zh":"掩飾事件會製造衝突，因為有權力的人正在隱藏事實。"},{"en":"This phrase combines politics, secrecy, and royal power.","zh":"這個短語結合政治、秘密和王室權力。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"learns to support","meaning":"學會支持","examples":[{"en":"Prince Theo learns to support Cinderella.","zh":"Theo 王子學會支持 Cinderella。"},{"en":"Learns to support means gradually understands how to help someone without controlling them.","zh":"Learns to support 指逐漸明白如何幫助某人，而不是控制對方。"},{"en":"A good teammate learns to support others by listening first.","zh":"好隊友會先聆聽，學會支持別人。"},{"en":"Theo learns to support Cinderella instead of trying to become the main hero.","zh":"Theo 學會支持 Cinderella，而不是試圖成為主英雄。"},{"en":"This phrase shows emotional growth.","zh":"這個短語顯示情感成長。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"without taking over","meaning":"沒有接管","examples":[{"en":"He supports Cinderella without taking over her mission.","zh":"他支持 Cinderella，沒有接管她的使命。"},{"en":"Without taking over means helping without seizing control or becoming the leader.","zh":"Without taking over 指在不奪取控制權或不成為領導者的情況下幫助。"},{"en":"Parents can help with homework without taking over the child’s project.","zh":"父母可以幫助孩子做功課，但不接管孩子的專題。"},{"en":"Theo respects Cinderella because he supports her without taking over.","zh":"Theo 尊重 Cinderella，因為他支持她而沒有接管。"},{"en":"This phrase is useful for describing healthy support.","zh":"這個短語適合描述健康的支持。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"mission","meaning":"使命","examples":[{"en":"Prince Theo does not take over Cinderella’s mission.","zh":"Theo 王子沒有接管 Cinderella 的使命。"},{"en":"A mission is an important task or purpose that someone tries to complete.","zh":"A mission 指某人努力完成的重要任務或目的。"},{"en":"Cinderella’s mission is to recover the slipper and save the kingdom.","zh":"Cinderella 的使命是取回玻璃鞋並拯救王國。"},{"en":"A mission gives a hero direction, pressure, and responsibility.","zh":"使命給英雄方向、壓力和責任。"},{"en":"This word is common in adventure and superhero stories.","zh":"這個詞常見於冒險和超級英雄故事。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"comic without being cruelly mocked","meaning":"有喜劇感但沒有被殘酷嘲笑","examples":[{"en":"The stepsisters are comic without being cruelly mocked.","zh":"繼姐妹有喜劇感，但沒有被殘酷嘲笑。"},{"en":"Comic without being cruelly mocked means funny, but not treated with harsh or humiliating laughter.","zh":"Comic without being cruelly mocked 指有趣，但沒有被苛刻或羞辱式地取笑。"},{"en":"A character can be comic without being cruelly mocked if the joke respects their humanity.","zh":"如果笑點仍尊重角色的人性，角色可以有喜劇感但不被殘酷嘲笑。"},{"en":"The stepsisters make mistakes, but the film does not simply laugh at their pain.","zh":"繼姐妹會犯錯，但電影不只是嘲笑她們的痛苦。"},{"en":"This phrase praises kinder comedy.","zh":"這個短語讚賞較善意的喜劇。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"spoiled","meaning":"被寵壞的","examples":[{"en":"The stepsisters are spoiled but also trapped.","zh":"繼姐妹被寵壞，但也被困住。"},{"en":"Spoiled means used to getting too much comfort, attention, or special treatment.","zh":"Spoiled 指習慣得到太多舒適、注意或特殊待遇。"},{"en":"A spoiled child may complain when they cannot get exactly what they want.","zh":"被寵壞的孩子得不到自己想要的東西時，可能會抱怨。"},{"en":"The stepsisters are spoiled because their mother teaches them to expect status.","zh":"繼姐妹被寵壞，因為母親教她們期待地位。"},{"en":"This word criticises behaviour shaped by too much indulgence.","zh":"這個詞批評被過度縱容塑造出來的行為。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"trapped by","meaning":"被……困住","examples":[{"en":"The stepsisters are trapped by their mother’s hunger for status.","zh":"繼姐妹被母親對地位的渴求困住。"},{"en":"Trapped by means unable to escape from the control, pressure, or result of something.","zh":"Trapped by 指無法逃離某事的控制、壓力或結果。"},{"en":"A student may feel trapped by parents’ expectations.","zh":"學生可能感到被父母期望困住。"},{"en":"The stepsisters are trapped by their mother’s ambition, even when they seem privileged.","zh":"繼姐妹即使看似有特權，仍被母親的野心困住。"},{"en":"This phrase shows that comfort can still be a kind of prison.","zh":"這個短語顯示舒適也可以是一種牢籠。"}],"source":"2019 Q6.pdf","sourcePage":10},{"front":"hunger for status","meaning":"對地位的渴求","examples":[{"en":"The stepsisters are trapped by their mother’s hunger for status.","zh":"繼姐妹被母親對地位的渴求困住。"},{"en":"Hunger for status means a strong desire to gain social rank, respect, or importance.","zh":"Hunger for status 指強烈渴望得到社會地位、尊重或重要性。"},{"en":"A person with a hunger for status may care more about titles than kindness.","zh":"對地位有渴求的人可能更在意頭銜，而不是善良。"},{"en":"Malvora’s hunger for status pushes her family into unhealthy choices.","zh":"Malvora 對地位的渴求把家人推向不健康的選擇。"},{"en":"This phrase criticises ambition based on social position.","zh":"這個短語批評建基於社會位置的野心。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"as for","meaning":"至於","examples":[{"en":"As for Lady Malvora, she is a superb villain.","zh":"至於 Lady Malvora，她是一位出色的反派。"},{"en":"As for means turning attention to another person, topic, or point.","zh":"As for 指把注意力轉向另一個人、話題或重點。"},{"en":"The acting is strong; as for the music, it is unforgettable.","zh":"演技很強；至於音樂，則令人難忘。"},{"en":"Reviewers use as for when moving from one character to another.","zh":"影評人從一個角色轉到另一個角色時，會用 as for。"},{"en":"This phrase helps organise discussion smoothly.","zh":"這個短語幫助順暢組織討論。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"superb villain","meaning":"出色的反派","examples":[{"en":"Lady Malvora is a superb villain.","zh":"Lady Malvora 是一位出色的反派。"},{"en":"A superb villain is an excellent bad character who is memorable and effective.","zh":"A superb villain 指令人難忘又有效製造威脅的優秀壞角色。"},{"en":"A superb villain has clear motives, strong presence, and real danger.","zh":"出色的反派有清楚動機、強烈存在感和真正危險性。"},{"en":"Lady Malvora works as a superb villain because she understands power and image.","zh":"Lady Malvora 是出色的反派，因為她理解權力和形象。"},{"en":"This phrase praises the writing or performance of an antagonist.","zh":"這個短語讚賞反派的寫作或演出。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"public image","meaning":"公眾形象","examples":[{"en":"Lady Malvora understands how public image can become a weapon.","zh":"Lady Malvora 明白公眾形象如何可以變成武器。"},{"en":"Public image means the way people are seen and judged by society.","zh":"Public image 指一個人在社會中被看見和評價的方式。"},{"en":"A leader’s public image may improve if they appear calm during a crisis.","zh":"如果領袖在危機中顯得冷靜，其公眾形象可能改善。"},{"en":"Malvora uses public image to control what people believe about Ella.","zh":"Malvora 利用公眾形象控制人們對 Ella 的看法。"},{"en":"This phrase connects appearance with power.","zh":"這個短語把外在形象和權力連接起來。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"become a weapon","meaning":"變成武器","examples":[{"en":"Public image can become a weapon.","zh":"公眾形象可以變成武器。"},{"en":"Become a weapon means be used to harm, control, or pressure others.","zh":"Become a weapon 指被用來傷害、控制或施壓於他人。"},{"en":"Rumours can become a weapon when people spread them to destroy someone’s reputation.","zh":"當人們散播謠言來破壞某人名聲，謠言就可以變成武器。"},{"en":"In the film, public image becomes a weapon because Malvora uses it to erase Ella.","zh":"在電影中，公眾形象變成武器，因為 Malvora 用它抹走 Ella。"},{"en":"This phrase shows how ordinary things can be turned into tools of power.","zh":"這個短語顯示普通事物如何被變成權力工具。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"clearly wanted to","meaning":"明顯想要","examples":[{"en":"The director clearly wanted to make this film for a questioning generation.","zh":"導演明顯想要為一個愛質疑的一代製作這部電影。"},{"en":"Clearly wanted to means obviously intended or hoped to do something.","zh":"Clearly wanted to 指明顯打算或希望做某事。"},{"en":"The teacher clearly wanted to make the lesson easier by using real examples.","zh":"老師明顯想要透過真實例子令課堂更容易理解。"},{"en":"The director clearly wanted to update Cinderella for viewers who dislike passive princesses.","zh":"導演明顯想要為不喜歡被動公主的觀眾更新 Cinderella。"},{"en":"This phrase identifies intention from visible choices.","zh":"這個短語從可見選擇中指出意圖。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"a generation that has grown up","meaning":"成長於……的一代","examples":[{"en":"The film is made for a generation that has grown up questioning old fairy tales.","zh":"這部電影是為成長於質疑舊童話的一代而製作。"},{"en":"A generation that has grown up means a group of people shaped by the same period and experiences.","zh":"A generation that has grown up 指受同一時代和經歷塑造的一群人。"},{"en":"A generation that has grown up online may expect stories to be discussed and challenged.","zh":"成長於網絡時代的一代，可能期待故事被討論和質疑。"},{"en":"This film speaks to young viewers shaped by modern conversations about identity and power.","zh":"這部電影面向受現代身份和權力討論塑造的年輕觀眾。"},{"en":"The phrase connects age group with shared attitudes.","zh":"這個短語把年齡群體與共同態度連接起來。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"questioning old fairy tales","meaning":"質疑舊童話","examples":[{"en":"This generation has grown up questioning old fairy tales.","zh":"這一代人成長於質疑舊童話。"},{"en":"Questioning old fairy tales means asking whether traditional stories still send fair or useful messages.","zh":"Questioning old fairy tales 指詢問傳統故事是否仍傳遞公平或有用的訊息。"},{"en":"Students may question old fairy tales that reward girls for silence and beauty.","zh":"學生可能質疑那些因女孩沉默和美貌而獎賞她們的舊童話。"},{"en":"Questioning old fairy tales does not mean hating them; it means thinking about their values.","zh":"質疑舊童話不代表討厭它們，而是思考其中價值觀。"},{"en":"This phrase shows a critical but thoughtful attitude toward tradition.","zh":"這個短語顯示對傳統批判但 thoughtful 的態度。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"Gone are the days when","meaning":"……的日子已經過去","examples":[{"en":"Gone are the days when a heroine simply waited by the fireplace.","zh":"女主角只是在壁爐旁等待的日子已經過去。"},{"en":"Gone are the days when means that a past situation is finished and no longer accepted.","zh":"Gone are the days when 指過去某種情況已經結束，而且不再被接受。"},{"en":"Gone are the days when students learned only by copying notes silently.","zh":"學生只靠安靜抄筆記學習的日子已經過去。"},{"en":"The phrase suggests that modern audiences expect heroines to act, not only wait.","zh":"這個短語暗示現代觀眾期待女主角行動，而不只是等待。"},{"en":"It is useful for showing social or cultural change.","zh":"它適合用來顯示社會或文化變化。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"heroine","meaning":"女主角；女英雄","examples":[{"en":"The heroine does not simply wait by the fireplace.","zh":"女主角不只是坐在壁爐旁等待。"},{"en":"A heroine is the main female character in a story, especially one who is brave or admirable.","zh":"A heroine 指故事中的主要女性角色，特別是勇敢或令人敬佩的人。"},{"en":"The heroine of the film saves the kingdom through courage and choice.","zh":"這部電影的女英雄透過勇氣和選擇拯救王國。"},{"en":"A heroine becomes stronger when she has goals beyond romance.","zh":"當女主角有愛情以外的目標，她會變得更強。"},{"en":"This word can mean both female main character and female hero.","zh":"這個詞可以指女性主角，也可以指女英雄。"}],"source":"2019 Q6.pdf","sourcePage":11},{"front":"wait by the fireplace","meaning":"在壁爐旁等待","examples":[{"en":"Old fairy tales often showed a heroine waiting by the fireplace.","zh":"舊童話常描寫女主角在壁爐旁等待。"},{"en":"Wait by the fireplace means stay passively at home, often near ashes or household work.","zh":"Wait by the fireplace 指被動地留在家中，常靠近灰燼或家務工作。"},{"en":"A character who waits by the fireplace depends on others to change her life.","zh":"在壁爐旁等待的角色依靠別人改變自己的人生。"},{"en":"This image reminds viewers of the old Cinderella who suffered quietly.","zh":"這個畫面令觀眾想起默默受苦的舊版 Cinderella。"},{"en":"The phrase symbolises passivity and domestic confinement.","zh":"這個短語象徵被動和家庭中的困住狀態。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"be rewarded for","meaning":"因……而得到獎賞","examples":[{"en":"A heroine should not simply be rewarded for suffering quietly.","zh":"女主角不應只是因默默受苦而得到獎賞。"},{"en":"Be rewarded for means receive something good because of a certain action or behaviour.","zh":"Be rewarded for 指因某種行動或行為而得到好處。"},{"en":"Students should be rewarded for effort, not only perfect answers.","zh":"學生應因努力而得到獎賞，而不只是因完美答案。"},{"en":"Old stories sometimes reward girls for patience instead of active courage.","zh":"舊故事有時獎賞女孩的忍耐，而不是主動勇氣。"},{"en":"This phrase connects behaviour with praise or prize.","zh":"這個短語把行為和稱讚或獎品連接起來。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"suffering quietly","meaning":"默默受苦","examples":[{"en":"The old heroine was rewarded for suffering quietly.","zh":"舊版女主角因默默受苦而得到獎賞。"},{"en":"Suffering quietly means enduring pain or unfair treatment without speaking up.","zh":"Suffering quietly 指在不發聲的情況下忍受痛苦或不公平對待。"},{"en":"A worker suffering quietly may never tell others about unfair pay.","zh":"默默受苦的工人可能永遠不告訴別人自己薪酬不公平。"},{"en":"The film questions stories that praise girls for suffering quietly.","zh":"這部電影質疑那些讚美女孩默默受苦的故事。"},{"en":"This phrase criticises silence in the face of hurt.","zh":"這個短語批評面對傷害時的沉默。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"asks a sharper question","meaning":"提出更尖銳的問題","examples":[{"en":"This version asks a sharper question.","zh":"這個版本提出更尖銳的問題。"},{"en":"Asks a sharper question means raises a more direct, serious, or challenging issue.","zh":"Asks a sharper question 指提出更直接、更嚴肅或更具挑戰性的問題。"},{"en":"Instead of asking who Cinderella will marry, the film asks a sharper question about identity.","zh":"電影不問 Cinderella 會嫁給誰，而是提出關於身份的更尖銳問題。"},{"en":"A teacher asks a sharper question when she moves from facts to values.","zh":"當老師由事實轉向價值觀，她就是提出更尖銳的問題。"},{"en":"This phrase shows deeper critical thinking.","zh":"這個短語顯示更深入的批判思考。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"real enemy","meaning":"真正敵人","examples":[{"en":"The film asks what Cinderella’s real enemy is.","zh":"電影問 Cinderella 的真正敵人是甚麼。"},{"en":"Real enemy means the true problem or force that causes harm, not just the obvious villain.","zh":"Real enemy 指真正造成傷害的問題或力量，而不只是明顯反派。"},{"en":"In the story, the real enemy may be shame rather than only Malvora.","zh":"在故事中，真正敵人可能是羞恥感，而不只是 Malvora。"},{"en":"A film becomes deeper when it asks whether the real enemy is a belief or system.","zh":"當電影問真正敵人是否是一種信念或制度，它就變得更深入。"},{"en":"This phrase helps move from surface conflict to deeper cause.","zh":"這個短語幫助由表面衝突轉向深層原因。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"the belief that","meaning":"……這種信念","examples":[{"en":"The real enemy may be the belief that a girl’s worth depends on others.","zh":"真正敵人可能是女孩的價值取決於別人這種信念。"},{"en":"The belief that means the idea or opinion that something is true.","zh":"The belief that 指認為某事是真的這種想法或意見。"},{"en":"The belief that boys should not cry can hurt children emotionally.","zh":"男孩不應哭這種信念，可能在情感上傷害孩子。"},{"en":"The film challenges the belief that girls need approval to have value.","zh":"電影挑戰女孩需要認可才有價值這種信念。"},{"en":"This phrase often introduces an idea that may be questioned.","zh":"這個短語常引出可能被質疑的想法。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"depends on","meaning":"取決於","examples":[{"en":"A girl’s worth should not depend on how others look at her.","zh":"女孩的價值不應取決於別人如何看待她。"},{"en":"Depends on means is decided, affected, or controlled by something.","zh":"Depends on 指由某事決定、影響或控制。"},{"en":"A student’s confidence should not depend only on exam marks.","zh":"學生的信心不應只取決於考試分數。"},{"en":"Ella learns that her worth does not depend on other people’s recognition.","zh":"Ella 學會自己的價值不取決於別人的認出。"},{"en":"This phrase shows what controls or influences a result.","zh":"這個短語顯示甚麼控制或影響結果。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"how others look at her","meaning":"別人如何看待她","examples":[{"en":"The film questions whether a girl’s worth depends on how others look at her.","zh":"電影質疑女孩的價值是否取決於別人如何看待她。"},{"en":"How others look at her means the way other people judge, see, or value her.","zh":"How others look at her 指別人如何判斷、看待或評價她。"},{"en":"A teenager may feel anxious if she cares too much about how others look at her.","zh":"如果青少年太在意別人如何看待她，可能會感到焦慮。"},{"en":"Cinderella must stop letting how others look at her decide who she is.","zh":"Cinderella 必須停止讓別人如何看待她決定她是誰。"},{"en":"This phrase connects identity with social judgement.","zh":"這個短語把身份與社會評價連接起來。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"by blending","meaning":"透過融合","examples":[{"en":"The film succeeds by blending retro style with a modern message.","zh":"這部電影透過融合復古風格和現代訊息而成功。"},{"en":"By blending means by mixing two or more things together smoothly.","zh":"By blending 指透過順暢混合兩種或以上東西。"},{"en":"A restaurant creates new dishes by blending local flavours with foreign techniques.","zh":"餐廳透過融合本地味道和外國技巧創造新菜式。"},{"en":"The film feels fresh by blending old comic style with new ideas about identity.","zh":"電影透過融合舊漫畫風格和關於身份的新想法，感覺新鮮。"},{"en":"This phrase explains the method behind success.","zh":"這個短語解釋成功背後的方法。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"retro comic-book style","meaning":"復古漫畫風格","examples":[{"en":"The film blends a retro comic-book style with a modern message.","zh":"這部電影融合復古漫畫風格和現代訊息。"},{"en":"Retro comic-book style means a visual style that imitates older comics.","zh":"Retro comic-book style 指模仿舊漫畫的視覺風格。"},{"en":"Retro comic-book style may use bold colours, dramatic frames, and old-fashioned lettering.","zh":"復古漫畫風格可能使用鮮明色彩、戲劇化分格和舊式字體。"},{"en":"This style reminds viewers of the story’s comic-series roots.","zh":"這種風格提醒觀眾故事來自漫畫系列。"},{"en":"The phrase describes a look that feels both old and energetic.","zh":"這個短語描述既懷舊又有活力的外觀。"}],"source":"2019 Q6.pdf","sourcePage":12},{"front":"modern message","meaning":"現代訊息","examples":[{"en":"The film combines retro style with a modern message.","zh":"這部電影結合復古風格和現代訊息。"},{"en":"A modern message is an idea that speaks to present-day values, problems, or audiences.","zh":"A modern message 指回應當代價值、問題或觀眾的想法。"},{"en":"The modern message of the film is that courage matters more than appearance.","zh":"這部電影的現代訊息是勇氣比外貌更重要。"},{"en":"Old stories can feel fresh when they carry a modern message.","zh":"當舊故事帶有現代訊息，它們可以感覺新鮮。"},{"en":"This phrase contrasts old style with new meaning.","zh":"這個短語對比舊風格和新意義。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"reminds young viewers that","meaning":"提醒年輕觀眾","examples":[{"en":"The film reminds young viewers that courage and appearance are not the same thing.","zh":"這部電影提醒年輕觀眾，勇氣與外貌不是同一回事。"},{"en":"Reminds young viewers that means helps young audiences remember or understand an important idea.","zh":"Reminds young viewers that 指幫助年輕觀眾記住或理解一個重要想法。"},{"en":"The story reminds young viewers that failure does not make them worthless.","zh":"這個故事提醒年輕觀眾，失敗不代表自己沒有價值。"},{"en":"Films can remind young viewers that being kind is not the same as being silent.","zh":"電影可以提醒年輕觀眾，善良不等於沉默。"},{"en":"This phrase is useful when explaining a lesson or message.","zh":"解釋教訓或訊息時，這個短語很有用。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"courage and appearance","meaning":"勇氣與外貌","examples":[{"en":"The film shows that courage and appearance are not the same thing.","zh":"這部電影顯示勇氣與外貌不是同一回事。"},{"en":"Courage and appearance means inner bravery and outer looks.","zh":"Courage and appearance 指內在勇敢和外在樣貌。"},{"en":"A person may look ordinary but show great courage during a crisis.","zh":"一個人可能外表普通，但在危機中展現巨大勇氣。"},{"en":"Cinderella learns that courage and appearance should not be confused.","zh":"Cinderella 學會勇氣與外貌不應被混淆。"},{"en":"This phrase contrasts character with physical image.","zh":"這個短語對比品格和身體形象。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"not the same thing","meaning":"不是同一回事","examples":[{"en":"Courage and appearance are not the same thing.","zh":"勇氣與外貌不是同一回事。"},{"en":"Not the same thing means two ideas are different and should not be confused.","zh":"Not the same thing 指兩個想法不同，不應混淆。"},{"en":"Being quiet and being weak are not the same thing.","zh":"安靜和軟弱不是同一回事。"},{"en":"Looking beautiful and being worthy are not the same thing in this film.","zh":"在這部電影中，看起來美麗和有價值不是同一回事。"},{"en":"This phrase is useful for correcting a mistaken connection.","zh":"這個短語適合用來糾正錯誤連繫。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"admittedly","meaning":"誠然","examples":[{"en":"Admittedly, the film is not perfect.","zh":"誠然，這部電影並不完美。"},{"en":"Admittedly means used to accept a weakness or truth before continuing an argument.","zh":"Admittedly 指在繼續論點前承認一個弱點或事實。"},{"en":"Admittedly, the story is simple, but the characters are warm.","zh":"誠然，故事很簡單，但角色很溫暖。"},{"en":"Reviewers use admittedly to sound fair when mentioning problems.","zh":"影評人提到問題時用 admittedly，可以顯得公平。"},{"en":"This word introduces balance rather than complete criticism.","zh":"這個詞引入平衡，而不是完全批評。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"final battle","meaning":"最終決戰","examples":[{"en":"The final battle is a little crowded.","zh":"最終決戰稍為擁擠。"},{"en":"The final battle is the last major fight or conflict near the end of a story.","zh":"The final battle 指故事接近結尾時最後一場大型戰鬥或衝突。"},{"en":"In the final battle, heroes often face the villain and the biggest danger.","zh":"在最終決戰中，英雄常面對反派和最大危險。"},{"en":"A final battle can feel crowded if too many characters and problems appear at once.","zh":"如果太多角色和問題同時出現，最終決戰可能顯得元素太多。"},{"en":"This phrase marks the climax of an adventure story.","zh":"這個短語標示冒險故事的高潮。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"a little crowded","meaning":"稍為擁擠；元素太多","examples":[{"en":"The final battle is a little crowded.","zh":"最終決戰稍為擁擠。"},{"en":"A little crowded means slightly too full of people, action, ideas, or details.","zh":"A little crowded 指人、動作、想法或細節稍為太多。"},{"en":"The poster looks a little crowded because it has too many words and pictures.","zh":"海報因為有太多文字和圖片，看起來稍為擁擠。"},{"en":"A film scene feels a little crowded when viewers do not know where to look.","zh":"當觀眾不知道看哪裏，電影場面就會顯得元素太多。"},{"en":"This phrase gives mild criticism, not harsh attack.","zh":"這個短語表達溫和批評，而不是嚴厲攻擊。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"deserve more screen time","meaning":"值得有更多出場時間","examples":[{"en":"Two Princesses of Power deserve more screen time.","zh":"兩位 Power 公主值得有更多出場時間。"},{"en":"Deserve more screen time means should appear more often or be given more attention in the film.","zh":"Deserve more screen time 指應該在電影中出現更多，或得到更多注意。"},{"en":"The funny grandmother deserves more screen time because every scene with her is warm.","zh":"那位有趣的祖母值得有更多出場時間，因為她每場戲都很溫暖。"},{"en":"Characters deserve more screen time when they are interesting but underdeveloped.","zh":"當角色有趣但發展不足，他們就值得有更多出場時間。"},{"en":"This phrase is common in reviews of films and television.","zh":"這個短語常見於電影和電視評論。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"screen time","meaning":"出場時間","examples":[{"en":"Some characters deserve more screen time.","zh":"有些角色值得有更多出場時間。"},{"en":"Screen time means the amount of time a character appears on screen.","zh":"Screen time 指角色出現在螢幕上的時間長度。"},{"en":"The villain has little screen time, but every scene with her is powerful.","zh":"反派出場時間不多，但每場戲都很有力量。"},{"en":"More screen time can help audiences understand a character’s motives.","zh":"更多出場時間可以幫助觀眾理解角色動機。"},{"en":"This phrase is useful when discussing character development.","zh":"討論角色發展時，這個短語很有用。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"even so","meaning":"即使如此","examples":[{"en":"Even so, the film’s energy makes up for its flaws.","zh":"即使如此，電影的活力彌補了它的缺點。"},{"en":"Even so means despite what was just mentioned.","zh":"Even so 指儘管剛才提到某事仍然如此。"},{"en":"The ending is rushed; even so, the story remains touching.","zh":"結尾有點急促；即使如此，故事仍然動人。"},{"en":"Reviewers use even so to move from criticism back to praise.","zh":"影評人用 even so 從批評轉回讚賞。"},{"en":"This phrase creates balance in an argument.","zh":"這個短語在論證中製造平衡。"}],"source":"2019 Q6.pdf","sourcePage":13},{"front":"energy, humour and heart","meaning":"活力、幽默和真情","examples":[{"en":"The film’s energy, humour and heart make up for its flaws.","zh":"電影的活力、幽默和真情彌補了它的缺點。"},{"en":"Energy, humour and heart means liveliness, comedy, and sincere emotion.","zh":"Energy, humour and heart 指活潑感、喜劇感和真誠情感。"},{"en":"A school play can succeed through energy, humour and heart even with simple costumes.","zh":"學校話劇即使服裝簡單，也可以靠活力、幽默和真情成功。"},{"en":"These qualities make viewers forgive some weak parts of the film.","zh":"這些特質令觀眾原諒電影某些弱點。"},{"en":"This phrase praises the film’s spirit and warmth.","zh":"這個短語讚賞電影的精神和溫暖。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"more than make up for","meaning":"足以彌補；遠遠彌補","examples":[{"en":"The film’s strengths more than make up for its flaws.","zh":"電影的優點足以彌補它的缺點。"},{"en":"More than make up for means compensate so well that the problem feels much less important.","zh":"More than make up for 指彌補得很好，令問題顯得不太重要。"},{"en":"The restaurant is small, but the friendly service more than makes up for it.","zh":"那間餐廳很小，但友善服務遠遠彌補了這點。"},{"en":"Strong characters can more than make up for a simple plot.","zh":"有力角色可以足以彌補簡單情節。"},{"en":"This phrase gives strong praise after admitting a weakness.","zh":"這個短語在承認弱點後給予強烈讚賞。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"flaws","meaning":"缺點","examples":[{"en":"The film’s energy makes up for its flaws.","zh":"電影的活力彌補了它的缺點。"},{"en":"Flaws are weaknesses, mistakes, or imperfect parts.","zh":"Flaws 指弱點、錯誤或不完美的部分。"},{"en":"The essay has flaws, but its main argument is clear.","zh":"這篇文章有缺點，但主要論點清楚。"},{"en":"A film’s flaws may include rushed scenes, weak jokes, or underused characters.","zh":"電影缺點可能包括場面急促、笑話薄弱或角色未被充分運用。"},{"en":"This word helps discuss problems without saying something is completely bad.","zh":"這個詞幫助討論問題，而不是說某事完全不好。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"emotionally generous","meaning":"情感豐沛的","examples":[{"en":"Cinderella is fast, bright and emotionally generous.","zh":"Cinderella 節奏快、明亮，而且情感豐沛。"},{"en":"Emotionally generous means rich in feeling and willing to give characters emotional depth.","zh":"Emotionally generous 指情感豐富，並願意給角色情感深度。"},{"en":"An emotionally generous film lets even minor characters have hopes and fears.","zh":"情感豐沛的電影會讓小角色也有希望和恐懼。"},{"en":"Cinderella feels emotionally generous because it treats loneliness, courage, and friendship seriously.","zh":"Cinderella 感覺情感豐沛，因為它認真處理孤獨、勇氣和友情。"},{"en":"This phrase praises warmth and care in storytelling.","zh":"這個短語讚賞敘事中的溫暖和用心。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time the last clock tower lights up, the story feels fresh.","zh":"到最後一座鐘樓亮起的時候，故事感覺新鮮。"},{"en":"By the time means when a particular moment has arrived.","zh":"By the time 指某個特定時刻到來時。"},{"en":"By the time the lesson ended, the difficult idea felt much clearer.","zh":"到課堂結束的時候，那個困難概念已清楚得多。"},{"en":"By the time the final scene arrives, viewers understand Ella’s change.","zh":"到最後一幕出現的時候，觀眾已理解 Ella 的轉變。"},{"en":"This phrase connects an ending point with a result.","zh":"這個短語把一個結束點和結果連接起來。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"lights up","meaning":"亮起","examples":[{"en":"The last clock tower lights up near the end of the film.","zh":"最後一座鐘樓在電影接近結尾時亮起。"},{"en":"Lights up means becomes bright because light appears or is switched on.","zh":"Lights up 指因燈光出現或開啟而變亮。"},{"en":"The theatre sign lights up when the evening show begins.","zh":"晚場表演開始時，劇院招牌亮起。"},{"en":"A clock tower lighting up can signal hope, danger, or a magical change.","zh":"鐘樓亮起可以表示希望、危險或魔法變化。"},{"en":"This phrase describes a visual change that attracts attention.","zh":"這個短語描述吸引注意的視覺變化。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"familiar fairy tale","meaning":"熟悉的童話","examples":[{"en":"The film turns a familiar fairy tale into something fresh.","zh":"這部電影把一個熟悉的童話變成新鮮的東西。"},{"en":"A familiar fairy tale is a traditional story many people already know.","zh":"A familiar fairy tale 指許多人已經知道的傳統故事。"},{"en":"Cinderella is a familiar fairy tale because many children learn it early.","zh":"Cinderella 是熟悉的童話，因為許多孩子很早就認識它。"},{"en":"A familiar fairy tale can still surprise viewers when its message changes.","zh":"當訊息改變時，熟悉的童話仍可以令觀眾驚喜。"},{"en":"This phrase contrasts known material with new treatment.","zh":"這個短語對比已知材料和新處理方式。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"into something fresh","meaning":"變成新鮮的東西","examples":[{"en":"The film turns Cinderella into something fresh.","zh":"這部電影把 Cinderella 變成新鮮的東西。"},{"en":"Into something fresh means into something new, lively, or different from the expected version.","zh":"Into something fresh 指變成新的、有活力的，或不同於預期版本的東西。"},{"en":"A teacher can turn an old grammar point into something fresh with real-life examples.","zh":"老師可以用生活例子把舊文法點變成新鮮的東西。"},{"en":"Cinderella becomes something fresh when the slipper becomes a power-core.","zh":"當玻璃鞋變成能量核心，Cinderella 就變成新鮮的東西。"},{"en":"This phrase describes creative renewal.","zh":"這個短語描述創意更新。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"not a story about…, but a story about…","meaning":"不是關於……而是關於……","examples":[{"en":"This is not a story about losing a slipper, but a story about finding a self.","zh":"這不是一個關於遺失玻璃鞋的故事，而是一個關於找回自我的故事。"},{"en":"Not a story about…, but a story about… replaces a surface topic with a deeper meaning.","zh":"Not a story about…, but a story about… 用更深層意義取代表面題材。"},{"en":"The film is not a story about a prince, but a story about courage and identity.","zh":"這部電影不是關於王子的故事，而是關於勇氣和身份的故事。"},{"en":"This structure helps writers explain what a story is truly about.","zh":"這個結構幫助作者解釋故事真正關於甚麼。"},{"en":"It is useful for showing contrast between plot and theme.","zh":"它適合展示情節和主題之間的對比。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"finding a self","meaning":"找回自我","examples":[{"en":"The film is a story about finding a self.","zh":"這部電影是一個關於找回自我的故事。"},{"en":"Finding a self means discovering one’s true identity, voice, and value.","zh":"Finding a self 指發現自己的真正身份、聲音和價值。"},{"en":"A teenager may begin finding a self by choosing what they believe instead of only copying friends.","zh":"青少年開始選擇自己相信的事，而不只是模仿朋友時，可能開始找回自我。"},{"en":"Ella finds a self when she stops depending on others to recognise her.","zh":"當 Ella 不再依賴別人認出她，她就找回自我。"},{"en":"This phrase connects personal growth with identity.","zh":"這個短語把個人成長與身份連接起來。"}],"source":"2019 Q6.pdf","sourcePage":14},{"front":"comic fans","meaning":"漫畫迷","examples":[{"en":"The film is suitable for families and comic fans.","zh":"這部電影適合家庭和漫畫迷。"},{"en":"Comic fans are people who enjoy reading, collecting, or watching stories based on comics.","zh":"Comic fans 指喜歡閱讀、收藏或觀看漫畫相關故事的人。"},{"en":"Comic fans may enjoy the film’s bold colours and panel-like opening.","zh":"漫畫迷可能會喜歡電影鮮明色彩和像分格漫畫的開場。"},{"en":"A film adapted from a comic series often attracts comic fans first.","zh":"改編自漫畫系列的電影常先吸引漫畫迷。"},{"en":"This phrase identifies one target audience.","zh":"這個短語指出其中一類目標觀眾。"}],"source":"2019 Q6.pdf","sourcePage":15},{"front":"anyone tired of","meaning":"任何厭倦……的人","examples":[{"en":"This Cinderella is for anyone tired of helpless princesses.","zh":"這個 Cinderella 適合任何厭倦無助公主的人。"},{"en":"Anyone tired of means any person who feels bored, annoyed, or dissatisfied with something repeated too often.","zh":"Anyone tired of 指任何對反覆出現的某事感到沉悶、厭煩或不滿的人。"},{"en":"This book is for anyone tired of stories where girls only wait for rescue.","zh":"這本書適合任何厭倦女孩只等待救援故事的人。"},{"en":"Viewers tired of old princess roles may enjoy this active Cinderella.","zh":"厭倦舊公主角色的觀眾可能會喜歡這個主動的 Cinderella。"},{"en":"This phrase helps describe the audience who would appreciate something different.","zh":"這個短語幫助描述會欣賞不同作品的觀眾。"}],"source":"2019 Q6.pdf","sourcePage":15},{"front":"helpless princesses","meaning":"無助的公主","examples":[{"en":"This version is for viewers tired of helpless princesses.","zh":"這個版本適合厭倦無助公主的觀眾。"},{"en":"Helpless princesses are princess characters who cannot solve problems or act for themselves.","zh":"Helpless princesses 指不能自己解決問題或採取行動的公主角色。"},{"en":"Old stories sometimes show helpless princesses waiting for brave men to rescue them.","zh":"舊故事有時描寫無助的公主等待勇敢男人拯救。"},{"en":"Modern viewers may dislike helpless princesses because they want heroines with choices.","zh":"現代觀眾可能不喜歡無助的公主，因為他們想看到有選擇的女主角。"},{"en":"This phrase criticises passive female roles in traditional stories.","zh":"這個短語批評傳統故事中的被動女性角色。"}],"source":"2019 Q6.pdf","sourcePage":15},{"front":"well worth watching","meaning":"非常值得觀看","examples":[{"en":"This Cinderella is well worth watching.","zh":"這個 Cinderella 非常值得觀看。"},{"en":"Well worth watching means definitely worth spending time to see.","zh":"Well worth watching 指絕對值得花時間觀看。"},{"en":"The documentary is well worth watching because it explains a difficult issue clearly.","zh":"那部紀錄片非常值得觀看，因為它清楚解釋一個困難議題。"},{"en":"A film can be well worth watching even if it has a few flaws.","zh":"一部電影即使有少許缺點，也可以非常值得觀看。"},{"en":"This phrase gives a strong recommendation.","zh":"這個短語表示強烈推薦。"}],"source":"2019 Q6.pdf","sourcePage":15}],"dse/writing/part-b/2019/Q7":[{"front":"from blame to better art","meaning":"由責備走向更好的藝術","examples":[{"en":"The speech is about moving from blame to better art.","zh":"這篇演講是關於由責備走向更好的藝術。"},{"en":"From blame to better art means changing criticism from personal attack into useful improvement.","zh":"由責備走向更好的藝術，是指把批評由人身攻擊變成有用的改進。"},{"en":"A drama club moves from blame to better art when members stop saying “you are bad” and start explaining how a scene can improve.","zh":"當戲劇學會成員不再說「你很差」，而開始解釋一幕戲可以如何改善時，他們就是由責備走向更好的藝術。"},{"en":"Moving from blame to better art helps artists feel safe enough to try again.","zh":"由責備走向更好的藝術，能幫助藝術家感到安全，願意再次嘗試。"},{"en":"This phrase reminds us that criticism should lead to growth, not shame.","zh":"這個短語提醒我們，批評應帶來成長，而不是羞辱。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"learn to criticise","meaning":"學會批評","examples":[{"en":"We need to learn to criticise with courage and kindness.","zh":"我們需要學會以勇氣與善意批評。"},{"en":"To learn to criticise means to practise giving comments that are honest, fair, and useful.","zh":"學會批評是指練習提出誠實、公平和有用的意見。"},{"en":"Students learn to criticise when they explain why a poster works instead of simply saying they like it.","zh":"當學生解釋海報為何有效，而不是只說自己喜歡時，他們就是在學會批評。"},{"en":"If people do not learn to criticise properly, feedback can become hurtful or unclear.","zh":"如果人們沒有學會正確批評，回饋可能變得傷人或不清楚。"},{"en":"Learning to criticise is also learning how to help others improve.","zh":"學會批評，也是在學習如何幫助別人進步。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"with courage and kindness","meaning":"以勇氣與善意","examples":[{"en":"We should criticise with courage and kindness.","zh":"我們應該以勇氣與善意批評。"},{"en":"With courage and kindness means being brave enough to tell the truth but gentle enough not to hurt unnecessarily.","zh":"以勇氣與善意是指有勇氣說出真相，同時有善意避免不必要地傷人。"},{"en":"A teacher speaks with courage and kindness when she tells a student the essay is weak but explains how to improve it.","zh":"當老師告訴學生文章較弱，但解釋如何改善時，她就是以勇氣與善意說話。"},{"en":"Feedback given with courage and kindness can be honest without becoming cruel.","zh":"以勇氣與善意提出的回饋可以誠實，而不變得殘酷。"},{"en":"This phrase shows that good criticism needs both truth and care.","zh":"這個短語顯示，好的批評需要真誠，也需要關懷。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"good afternoon, everyone","meaning":"各位午安","examples":[{"en":"Good afternoon, everyone.","zh":"各位午安。"},{"en":"Good afternoon, everyone is a polite greeting used when speaking to a group in the afternoon.","zh":"「各位午安」是在下午向一群人說話時使用的禮貌問候。"},{"en":"A student may begin a school speech with “Good afternoon, everyone” before introducing the topic.","zh":"學生在介紹題目前，可能會用「各位午安」開始學校演講。"},{"en":"This greeting helps the speaker sound respectful and ready to address the audience.","zh":"這個問候能令講者聽起來有禮貌，並準備好向觀眾發言。"},{"en":"It is suitable for speeches, meetings, presentations, and formal club events.","zh":"它適合用於演講、會議、匯報和正式學會活動。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"once said that","meaning":"曾經說過","examples":[{"en":"Taylor Swift once said that criticism is unavoidable.","zh":"Taylor Swift 曾經說過，批評是無可避免的。"},{"en":"Once said that is used to introduce something a person said in the past.","zh":"曾經說過用來引出某人在過去說過的話。"},{"en":"A teacher once said that mistakes are proof that students are trying.","zh":"一位老師曾經說過，錯誤是學生正在嘗試的證明。"},{"en":"Writers use once said that when they want to begin with a memorable quotation or idea.","zh":"作者想以令人記得的引言或想法開首時，會使用「曾經說過」。"},{"en":"The phrase gives a sentence a clear link to someone else’s words.","zh":"這個短語令句子清楚連繫到別人的話。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"criticism is unavoidable","meaning":"批評是無可避免的","examples":[{"en":"Taylor Swift once said that criticism is unavoidable.","zh":"Taylor Swift 曾經說過，批評是無可避免的。"},{"en":"Criticism is unavoidable means people will receive comments or judgement whenever they create or do something publicly.","zh":"批評是無可避免的，意思是當人公開創作或做事時，就會收到評論或評價。"},{"en":"A student who performs on stage may find that criticism is unavoidable because many people will have opinions.","zh":"上台表演的學生可能會發現批評是無可避免的，因為很多人都會有意見。"},{"en":"Criticism is unavoidable, so artists need to learn how to listen without losing confidence.","zh":"批評是無可避免的，所以藝術家需要學會聆聽，而不失去信心。"},{"en":"This phrase does not mean all criticism is fair; it means criticism cannot be completely escaped.","zh":"這個短語不是指所有批評都是公道的，而是指批評不能完全逃避。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"cross a line","meaning":"越界","examples":[{"en":"People cross a line when they attack the person instead of reviewing the work.","zh":"當人們攻擊個人，而不是評論作品時，他們就是越界。"},{"en":"To cross a line means to go beyond what is acceptable or respectful.","zh":"越界是指超出可接受或尊重的範圍。"},{"en":"A joke crosses a line when it humiliates someone instead of making people laugh kindly.","zh":"當笑話羞辱某人，而不是善意地令人發笑時，它就是越界。"},{"en":"Criticism crosses a line when it attacks appearance, identity, or personal worth.","zh":"當批評攻擊外貌、身份或個人價值時，它就是越界。"},{"en":"Knowing where the line is helps a group stay honest without becoming cruel.","zh":"知道界線在哪裡，有助群體保持誠實而不變得殘酷。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"reviewing the work","meaning":"評論作品","examples":[{"en":"Good critics focus on reviewing the work.","zh":"好的批評者專注於評論作品。"},{"en":"Reviewing the work means looking carefully at the piece itself, such as its structure, purpose, and effect.","zh":"評論作品是指仔細看作品本身，例如其結構、目的和效果。"},{"en":"When reviewing the work, students should discuss the poem’s images, rhythm, and message.","zh":"評論作品時，學生應討論詩的意象、節奏和信息。"},{"en":"Reviewing the work keeps criticism useful because it avoids personal attack.","zh":"評論作品能保持批評有用，因為它避免人身攻擊。"},{"en":"This phrase reminds critics to focus on what can be changed and improved.","zh":"這個短語提醒批評者專注於可以改變和改善的地方。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"attacking the person","meaning":"攻擊個人","examples":[{"en":"Criticism becomes harmful when people start attacking the person.","zh":"當人們開始攻擊個人時，批評就會變得有害。"},{"en":"Attacking the person means criticising someone’s character, identity, or worth instead of the work.","zh":"攻擊個人是指批評某人的性格、身份或價值，而不是作品。"},{"en":"Saying “this scene is unclear” reviews the work, but saying “you are useless” is attacking the person.","zh":"說「這一幕不清楚」是在評論作品，但說「你很沒用」就是攻擊個人。"},{"en":"Attacking the person can make artists afraid to share their work again.","zh":"攻擊個人可能令藝術家害怕再次分享作品。"},{"en":"Good feedback avoids attacking the person and focuses on specific choices.","zh":"好的回饋會避免攻擊個人，並專注於具體選擇。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"as members of","meaning":"作為……的成員","examples":[{"en":"As members of our after-school arts club, we need to review one another’s work properly.","zh":"作為課後藝術學會的成員，我們需要正確地評論彼此的作品。"},{"en":"As members of means speaking from the role or responsibility of belonging to a group.","zh":"作為……的成員，是指以屬於某個群體的角色或責任來說話。"},{"en":"As members of a class, students should listen when others are presenting.","zh":"作為班級成員，學生在別人匯報時應該聆聽。"},{"en":"As members of a team, players must support one another even after mistakes.","zh":"作為隊伍成員，球員即使在犯錯後也必須互相支持。"},{"en":"This phrase reminds people that belonging to a group brings shared duties.","zh":"這個短語提醒人們，屬於一個群體會帶來共同責任。"}],"source":"2019 Q7.pdf","sourcePage":1},{"front":"after-school arts club","meaning":"課後藝術學會","examples":[{"en":"We are members of an after-school arts club.","zh":"我們是課後藝術學會的成員。"},{"en":"An after-school arts club is a student group that meets after lessons to create or discuss art.","zh":"課後藝術學會是在課後聚會、創作或討論藝術的學生組織。"},{"en":"An after-school arts club may include drawing, drama, music, dance, or film activities.","zh":"課後藝術學會可能包括繪畫、戲劇、音樂、舞蹈或電影活動。"},{"en":"Students join an after-school arts club to practise skills and share creative ideas.","zh":"學生加入課後藝術學會，是為了練習技能和分享創意想法。"},{"en":"Such a club should be a safe place for honest feedback and artistic growth.","zh":"這樣的學會應是讓人誠實回饋和藝術成長的安全地方。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"expose the most private parts of ourselves","meaning":"展露自己最私密的一面","examples":[{"en":"Artists sometimes expose the most private parts of themselves to other people’s eyes.","zh":"藝術家有時會在別人的目光下展露自己最私密的一面。"},{"en":"To expose the most private parts of ourselves means to reveal personal feelings, fears, memories, or beliefs.","zh":"展露自己最私密的一面，是指呈現個人的感受、恐懼、記憶或信念。"},{"en":"A poet may expose the most private parts of herself when she writes about grief after losing a family member.","zh":"當詩人寫失去家人後的悲傷時，她可能是在展露自己最私密的一面。"},{"en":"Because art can expose private feelings, criticism should be careful and humane.","zh":"因為藝術可以展露私密感受，所以批評應該小心而有人情味。"},{"en":"This phrase shows why creative work can feel both brave and vulnerable.","zh":"這個短語顯示為何創作會令人感到勇敢，也令人脆弱。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"to other people’s eyes","meaning":"在別人的目光下","examples":[{"en":"Artists expose private parts of themselves to other people’s eyes.","zh":"藝術家在別人的目光下展露自己私密的一面。"},{"en":"To other people’s eyes means in a way that others can see, judge, or notice.","zh":"在別人的目光下，是指以他人能看見、評價或注意到的方式呈現。"},{"en":"A student’s painting becomes open to other people’s eyes when it is displayed in the school hall.","zh":"當學生的畫作在學校禮堂展示時，它就出現在別人的目光下。"},{"en":"Showing work to other people’s eyes can be frightening because the artist cannot control every reaction.","zh":"把作品放在別人的目光下可能令人害怕，因為藝術家不能控制所有反應。"},{"en":"This phrase highlights the public side of creative expression.","zh":"這個短語突出創意表達中公開的一面。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"exciting and frightening","meaning":"令人興奮又害怕","examples":[{"en":"Creating art is exciting and frightening.","zh":"創作藝術令人興奮又害怕。"},{"en":"Exciting and frightening means something brings both energy and fear at the same time.","zh":"令人興奮又害怕，是指某事同時帶來能量和恐懼。"},{"en":"Performing a solo dance can be exciting and frightening because the audience is watching closely.","zh":"獨舞表演可能令人興奮又害怕，因為觀眾正仔細觀看。"},{"en":"Sharing personal writing is exciting and frightening because praise and criticism may both come.","zh":"分享個人寫作令人興奮又害怕，因為讚賞和批評都可能出現。"},{"en":"This phrase is useful when an experience is attractive but emotionally risky.","zh":"當一個經歷吸引人但在情感上有風險時，這個短語很有用。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"this is why","meaning":"這就是為甚麼","examples":[{"en":"This is why we need to learn how to review one another’s work properly.","zh":"這就是為甚麼我們需要學會如何正確評論彼此的作品。"},{"en":"This is why introduces the reason or explanation for what should happen next.","zh":"這就是為甚麼，用來引出接下來應該發生的事情的原因或解釋。"},{"en":"Some students feel hurt by careless comments; this is why feedback rules are important.","zh":"一些學生會被粗心的評論傷害；這就是為甚麼回饋規則很重要。"},{"en":"The road is dangerous at night; this is why the school asks students to leave in groups.","zh":"晚上的道路很危險；這就是為甚麼學校要求學生結伴離開。"},{"en":"Writers use this is why to connect a problem with a necessary response.","zh":"作者使用「這就是為甚麼」來把問題與必要回應連接起來。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"review one another’s work","meaning":"評論彼此的作品","examples":[{"en":"We need to learn how to review one another’s work properly.","zh":"我們需要學會如何正確評論彼此的作品。"},{"en":"To review one another’s work means to look at each other’s creative pieces and give thoughtful comments.","zh":"評論彼此的作品，是指看大家的創作並提出有思想的意見。"},{"en":"In an art class, students review one another’s work by discussing colour, shape, and message.","zh":"在藝術課中，學生透過討論色彩、形狀和信息來評論彼此的作品。"},{"en":"Reviewing one another’s work helps creators see strengths and weaknesses they may miss alone.","zh":"評論彼此的作品能幫助創作者看見自己可能忽略的優點和弱點。"},{"en":"The process works best when everyone is honest, specific, and respectful.","zh":"當每個人都誠實、具體和尊重時，這個過程最有效。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"not so that…, but so that…","meaning":"不是為了……而是為了……","examples":[{"en":"We criticise not so that we can sound clever, but so that we can help each other grow.","zh":"我們批評不是為了聽起來聰明，而是為了幫助彼此成長。"},{"en":"Not so that A, but so that B shows the real purpose by rejecting a weaker purpose first.","zh":"「不是為了A，而是為了B」先否定較弱的目的，再顯示真正目的。"},{"en":"We practise speeches not so that we can show off, but so that we can communicate more clearly.","zh":"我們練習演講不是為了炫耀，而是為了更清楚溝通。"},{"en":"Teachers ask questions not so that students feel small, but so that they learn to think more deeply.","zh":"老師提問不是為了令學生覺得渺小，而是為了讓他們學會更深入思考。"},{"en":"This structure helps writers explain what an action is truly for.","zh":"這個句式幫助作者解釋一個行動真正的目的。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"sound clever","meaning":"聽起來聰明","examples":[{"en":"We should not criticise just to sound clever.","zh":"我們不應只是為了聽起來聰明而批評。"},{"en":"To sound clever means to speak in a way that makes others think you are intelligent.","zh":"聽起來聰明是指說話方式令別人覺得你有智慧。"},{"en":"A student may use difficult words to sound clever, even when simple words are clearer.","zh":"學生可能使用艱深詞語來聽起來聰明，即使簡單詞語更清楚。"},{"en":"Criticism given only to sound clever often helps the critic more than the artist.","zh":"只為聽起來聰明而提出的批評，通常幫助批評者多於藝術家。"},{"en":"Good feedback should aim to help, not merely to sound clever.","zh":"好的回饋應以幫助為目的，而不只是為了聽起來聰明。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"help each other grow","meaning":"幫助彼此成長","examples":[{"en":"Good criticism can help each other grow.","zh":"好的批評可以幫助彼此成長。"},{"en":"To help each other grow means to support one another’s improvement through honest care.","zh":"幫助彼此成長，是指透過誠實的關心支持大家進步。"},{"en":"Club members help each other grow when they share useful advice after rehearsals.","zh":"學會成員在排練後分享有用建議時，就是幫助彼此成長。"},{"en":"People grow faster when they receive feedback from others who want them to succeed.","zh":"當人們收到希望自己成功的人給予的回饋時，會成長得更快。"},{"en":"This phrase makes criticism feel cooperative rather than competitive.","zh":"這個短語令批評感覺像合作，而不是競爭。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"I would like to discuss","meaning":"我想討論","examples":[{"en":"Today, I would like to discuss three things.","zh":"今天，我想討論三件事。"},{"en":"I would like to discuss is a polite way to introduce the topic of a speech or conversation.","zh":"我想討論，是介紹演講或對話主題的禮貌說法。"},{"en":"In a meeting, a student may say, “I would like to discuss how we can improve our exhibition.”","zh":"在會議中，學生可能會說：「我想討論我們可以如何改善展覽。」"},{"en":"This phrase helps listeners know what the speaker plans to explain.","zh":"這個短語幫助聽眾知道講者打算解釋甚麼。"},{"en":"It sounds more formal and organised than simply saying “I want to talk about.”","zh":"它比直接說「我想講」更正式和有條理。"}],"source":"2019 Q7.pdf","sourcePage":2},{"front":"give criticism","meaning":"提出批評","examples":[{"en":"We need to learn how to give criticism.","zh":"我們需要學會如何提出批評。"},{"en":"To give criticism means to offer comments about what works and what needs improvement.","zh":"提出批評是指就哪些地方有效和哪些地方需要改善給予意見。"},{"en":"A music teacher gives criticism when she explains why the rhythm sounds uneven.","zh":"當音樂老師解釋節奏為何不平均時，她就是在提出批評。"},{"en":"Giving criticism well helps the creator improve without feeling personally attacked.","zh":"好好提出批評能幫助創作者改善，而不感到被人身攻擊。"},{"en":"Good criticism should be clear, fair, and connected to evidence.","zh":"好的批評應清楚、公平，並與證據有關。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"respond to criticism","meaning":"回應批評","examples":[{"en":"We also need to learn how to respond to criticism.","zh":"我們也需要學會如何回應批評。"},{"en":"To respond to criticism means to listen, think, ask questions, and decide what to use.","zh":"回應批評是指聆聽、思考、提問，並決定採用甚麼。"},{"en":"A student can respond to criticism by taking notes instead of arguing immediately.","zh":"學生可以透過做筆記，而不是立即爭辯來回應批評。"},{"en":"Responding to criticism calmly helps people learn from useful comments.","zh":"冷靜回應批評能幫助人們從有用意見中學習。"},{"en":"This phrase focuses on what the receiver does after feedback is given.","zh":"這個短語著重接收者在收到回饋後做甚麼。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"with maturity","meaning":"成熟地","examples":[{"en":"We should respond to criticism with maturity.","zh":"我們應該成熟地回應批評。"},{"en":"With maturity means in a calm, responsible, and thoughtful way.","zh":"成熟地是指以冷靜、負責和有思想的方式。"},{"en":"A student responds with maturity when he listens to a teacher’s comment before explaining his view.","zh":"當學生先聆聽老師的意見，再解釋自己的看法時，他就是成熟地回應。"},{"en":"Responding with maturity prevents a difficult conversation from becoming an argument.","zh":"成熟地回應能防止困難對話變成爭執。"},{"en":"This phrase shows emotional control and respect.","zh":"這個短語顯示情緒控制和尊重。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"actually do","meaning":"實際上做甚麼","examples":[{"en":"What does a critic actually do?","zh":"批評者實際上做甚麼？"},{"en":"Actually do asks what someone really does, not what people only imagine they do.","zh":"實際上做甚麼，是問某人真正做的事情，而不是人們想像他們做的事情。"},{"en":"What does a class monitor actually do besides writing names on the board?","zh":"班長除了在黑板上寫名字，實際上還做甚麼？"},{"en":"Asking what critics actually do helps us move beyond stereotypes.","zh":"詢問批評者實際上做甚麼，能幫助我們超越刻板印象。"},{"en":"This phrase is useful when we want a practical explanation of a role.","zh":"當我們想實際解釋一個角色時，這個短語很有用。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"professional fault-finder","meaning":"專門挑錯的人","examples":[{"en":"A critic is not a professional fault-finder.","zh":"批評者不是專門挑錯的人。"},{"en":"A professional fault-finder is someone who seems to look only for mistakes as if it were their job.","zh":"專門挑錯的人，是指好像以尋找錯處為工作、只看錯誤的人。"},{"en":"A teacher should not act like a professional fault-finder who ignores every strength.","zh":"老師不應像專門挑錯的人一樣忽略所有優點。"},{"en":"When critics become professional fault-finders, artists may stop trusting their comments.","zh":"當批評者變成專門挑錯的人，藝術家可能不再相信他們的意見。"},{"en":"Good critics notice problems, but they also explain purpose, effort, and possibility.","zh":"好的批評者會注意問題，但也會解釋目的、努力和可能性。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"careful observer","meaning":"細心觀察者","examples":[{"en":"A critic is a careful observer.","zh":"批評者是細心觀察者。"},{"en":"A careful observer is someone who notices details before making a judgement.","zh":"細心觀察者是在作判斷前注意細節的人。"},{"en":"A careful observer watching a dance may notice posture, timing, and facial expression.","zh":"細心觀察者觀看舞蹈時，可能會留意姿勢、時間配合和面部表情。"},{"en":"Careful observers give better feedback because they see more than obvious mistakes.","zh":"細心觀察者能提出更好的回饋，因為他們看見的不只是明顯錯誤。"},{"en":"This phrase shows that criticism begins with attention, not attack.","zh":"這個短語顯示批評始於注意，而不是攻擊。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"fair interpreter","meaning":"公正的詮釋者","examples":[{"en":"A critic should be a fair interpreter.","zh":"批評者應是公正的詮釋者。"},{"en":"A fair interpreter tries to understand the meaning of a work without twisting it unfairly.","zh":"公正的詮釋者會嘗試理解作品的意思，而不作不公平的扭曲。"},{"en":"A fair interpreter asks what the artist may be trying to say before judging the result.","zh":"公正的詮釋者會先問藝術家可能想表達甚麼，再評價結果。"},{"en":"Fair interpretation prevents critics from forcing their own taste onto every piece.","zh":"公正詮釋能防止批評者把自己的品味強加於每件作品。"},{"en":"This phrase suggests that critics should explain a work honestly and respectfully.","zh":"這個短語表示批評者應誠實而尊重地解釋作品。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"at best","meaning":"最理想情況下","examples":[{"en":"At best, a critic is a helpful guide between the artist and the audience.","zh":"最理想情況下，批評者是在藝術家與觀眾之間有幫助的引導者。"},{"en":"At best means in the most positive or ideal situation.","zh":"最理想情況下，是指在最正面或最理想的情況中。"},{"en":"At best, homework feedback helps students understand how to improve, not just what mark they received.","zh":"最理想情況下，功課回饋幫助學生明白如何改善，而不只是知道分數。"},{"en":"At best, criticism builds a bridge between intention and understanding.","zh":"最理想情況下，批評會在意圖與理解之間建立橋樑。"},{"en":"Writers use at best to show what something can become when it works well.","zh":"作者使用「最理想情況下」來顯示某事運作良好時可以成為甚麼。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"a helpful guide","meaning":"有幫助的引導者","examples":[{"en":"A critic can be a helpful guide between the artist and the audience.","zh":"批評者可以是在藝術家與觀眾之間有幫助的引導者。"},{"en":"A helpful guide is someone who helps others understand where to look and what to notice.","zh":"有幫助的引導者是幫助別人明白該看哪裡和注意甚麼的人。"},{"en":"A museum guide is helpful when she explains why an old object matters.","zh":"當博物館導賞員解釋舊物件為何重要時，她就是有幫助的引導者。"},{"en":"A helpful guide does not control people’s opinions but helps them see more clearly.","zh":"有幫助的引導者不控制人們的意見，而是幫助他們看得更清楚。"},{"en":"In art, a critic becomes a helpful guide by explaining purpose, technique, and effect.","zh":"在藝術中，批評者透過解釋目的、技巧和效果，成為有幫助的引導者。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"between the artist and the audience","meaning":"在藝術家與觀眾之間","examples":[{"en":"A critic acts as a guide between the artist and the audience.","zh":"批評者在藝術家與觀眾之間擔任引導者。"},{"en":"Between the artist and the audience means connecting the creator of a work with the people who experience it.","zh":"在藝術家與觀眾之間，是指連接作品創作者與欣賞作品的人。"},{"en":"A film reviewer stands between the director and the audience by explaining how the story works.","zh":"電影評論者透過解釋故事如何運作，站在導演與觀眾之間。"},{"en":"Critics can reduce misunderstanding between the artist and the audience.","zh":"批評者可以減少藝術家與觀眾之間的誤解。"},{"en":"This phrase shows that criticism can connect people, not only judge work.","zh":"這個短語顯示批評可以連接人，而不只是評價作品。"}],"source":"2019 Q7.pdf","sourcePage":3},{"front":"review a poem","meaning":"評論一首詩","examples":[{"en":"When we review a poem, we should ask what the creator is trying to achieve.","zh":"當我們評論一首詩時，應該問創作者試圖達成甚麼。"},{"en":"To review a poem means to examine its language, images, rhythm, meaning, and effect.","zh":"評論一首詩是指審視它的語言、意象、節奏、意思和效果。"},{"en":"Students review a poem by asking how repeated words shape the mood.","zh":"學生透過詢問重複詞語如何塑造氣氛來評論一首詩。"},{"en":"Reviewing a poem carefully helps readers understand more than the surface meaning.","zh":"仔細評論一首詩能幫助讀者理解表面意思以外的內容。"},{"en":"A good review explains how the poem works, not just whether the reader likes it.","zh":"好評論會解釋詩如何運作，而不只是讀者是否喜歡它。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"a dance performance","meaning":"舞蹈表演","examples":[{"en":"We may review a poem, a painting, a short film, or a dance performance.","zh":"我們可以評論一首詩、一幅畫、一部短片或一場舞蹈表演。"},{"en":"A dance performance is a piece of art shown through body movement, rhythm, space, and expression.","zh":"舞蹈表演是透過身體動作、節奏、空間和表情呈現的藝術作品。"},{"en":"A school dance performance may tell a story without using any words.","zh":"學校舞蹈表演可能不用任何文字也能講故事。"},{"en":"When reviewing a dance performance, critics may discuss timing, emotion, and movement.","zh":"評論舞蹈表演時，批評者可能討論時間配合、情感和動作。"},{"en":"A dance performance can be powerful when the body clearly expresses the idea.","zh":"當身體清楚表達想法時，舞蹈表演可以很有力量。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"trying to achieve","meaning":"試圖達成","examples":[{"en":"We should ask what the creator is trying to achieve.","zh":"我們應該問創作者試圖達成甚麼。"},{"en":"Trying to achieve means attempting to reach a goal or create a certain effect.","zh":"試圖達成是指嘗試達到某個目標或營造某種效果。"},{"en":"A painter may be trying to achieve a feeling of loneliness through empty space.","zh":"畫家可能試圖透過空白空間營造孤獨感。"},{"en":"Understanding what an artist is trying to achieve helps critics judge the work fairly.","zh":"理解藝術家試圖達成甚麼，有助批評者公平評價作品。"},{"en":"This phrase focuses on intention before judgement.","zh":"這個短語在評價前先著重意圖。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"how the work is constructed","meaning":"作品如何構成","examples":[{"en":"A critic should ask how the work is constructed.","zh":"批評者應該問作品如何構成。"},{"en":"How the work is constructed means how its parts are arranged to create meaning or effect.","zh":"作品如何構成，是指作品各部分如何安排，以創造意思或效果。"},{"en":"In a short film, critics examine how scenes, music, lighting, and dialogue are constructed together.","zh":"在短片中，批評者會審視場景、音樂、燈光和對白如何共同構成作品。"},{"en":"Understanding construction helps people see why a work feels strong or weak.","zh":"理解構成方式能幫助人們看見作品為何感覺強或弱。"},{"en":"This phrase looks at the craft behind the final piece.","zh":"這個短語著重成品背後的技巧。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"have an effect on","meaning":"對……產生影響","examples":[{"en":"A critic should ask what effect the work has on the audience.","zh":"批評者應該問作品對觀眾產生甚麼影響。"},{"en":"To have an effect on someone means to influence how they think, feel, or act.","zh":"對某人產生影響，是指影響他們的思想、感受或行動。"},{"en":"A sad song can have an effect on listeners by making them remember a personal loss.","zh":"悲傷的歌曲可以令聽眾想起個人失去，從而對他們產生影響。"},{"en":"A poster has an effect on people when it makes them stop and read the message.","zh":"當海報令人停下來閱讀信息時，它就對人們產生影響。"},{"en":"Critics study effect because art is not only made; it is also experienced.","zh":"批評者研究效果，因為藝術不只是被創作，也被人經歷。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"choice of colour","meaning":"色彩選擇","examples":[{"en":"The choice of colour may support the artist’s intention.","zh":"色彩選擇可能配合藝術家的意圖。"},{"en":"Choice of colour means the colours an artist selects and how those colours affect the work.","zh":"色彩選擇是指藝術家選用的顏色，以及那些顏色如何影響作品。"},{"en":"A poster may use red as its choice of colour to create energy and urgency.","zh":"海報可能以紅色作為色彩選擇，以營造活力和迫切感。"},{"en":"The wrong choice of colour can make a serious message look playful.","zh":"錯誤的色彩選擇可能令嚴肅信息看起來輕浮。"},{"en":"Colour choices matter because they shape mood before people read the details.","zh":"色彩選擇很重要，因為它在人們閱讀細節前已塑造氣氛。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"support the artist’s intention","meaning":"配合藝術家的意圖","examples":[{"en":"Colour, rhythm, and movement should support the artist’s intention.","zh":"色彩、節奏和動作應該配合藝術家的意圖。"},{"en":"To support the artist’s intention means to help express what the artist wanted to communicate.","zh":"配合藝術家的意圖，是指幫助表達藝術家想傳達的東西。"},{"en":"Quiet music can support the artist’s intention if the scene is meant to feel lonely.","zh":"如果一幕戲本意是令人感到孤獨，安靜音樂可以配合藝術家的意圖。"},{"en":"If a bright design is used for a sad topic, it may not support the artist’s intention.","zh":"如果悲傷主題使用鮮艷設計，它可能無法配合藝術家的意圖。"},{"en":"Good artistic choices work together to make the creator’s purpose clearer.","zh":"好的藝術選擇會互相配合，令創作者的目的更清楚。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"artist’s intention","meaning":"藝術家的意圖","examples":[{"en":"A critic should consider the artist’s intention.","zh":"批評者應考慮藝術家的意圖。"},{"en":"Artist’s intention means what the artist wanted to express, question, or create.","zh":"藝術家的意圖是指藝術家想表達、提問或創造的東西。"},{"en":"A director’s intention may be to make the audience feel trapped in a character’s mind.","zh":"導演的意圖可能是令觀眾感覺被困在角色的思想中。"},{"en":"Critics consider the artist’s intention before deciding whether the work succeeds.","zh":"批評者在判斷作品是否成功前，會考慮藝術家的意圖。"},{"en":"Understanding intention does not mean agreeing with every artistic choice.","zh":"理解意圖並不代表同意每一個藝術選擇。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take a poster, for example.","zh":"以一張海報為例。"},{"en":"Take something for example means using one case to explain a wider point clearly.","zh":"以……為例，是指用一個例子清楚解釋較大的觀點。"},{"en":"Take a school concert, for example: lighting can change how the audience feels.","zh":"以學校音樂會為例：燈光可以改變觀眾的感受。"},{"en":"A speaker may say “take a poster, for example” before showing how criticism should work.","zh":"講者可能在展示批評應如何運作前說「以一張海報為例」。"},{"en":"This phrase helps listeners move from an abstract idea to a concrete example.","zh":"這個短語幫助聽眾由抽象想法轉向具體例子。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"promote a charity concert","meaning":"宣傳慈善音樂會","examples":[{"en":"The poster’s purpose is to promote a charity concert.","zh":"這張海報的目的是宣傳慈善音樂會。"},{"en":"To promote a charity concert means to encourage people to notice, attend, or support a concert that raises money for a good cause.","zh":"宣傳慈善音樂會，是指鼓勵人們注意、參加或支持為善事籌款的音樂會。"},{"en":"Students may design posters to promote a charity concert for flood victims.","zh":"學生可能設計海報來宣傳為水災災民籌款的慈善音樂會。"},{"en":"A clear date and strong image help promote a charity concert more effectively.","zh":"清晰日期和有力圖像有助更有效地宣傳慈善音樂會。"},{"en":"Promotion works best when people quickly understand the event and its purpose.","zh":"當人們能快速理解活動及其目的時，宣傳最有效。"}],"source":"2019 Q7.pdf","sourcePage":4},{"front":"not merely say","meaning":"不只是說","examples":[{"en":"A critic should not merely say, “I like it” or “I hate it.”","zh":"批評者不應只是說：「我喜歡它」或「我討厭它」。"},{"en":"Not merely say means not stop at a simple statement without explanation.","zh":"不只是說，是指不要停留在沒有解釋的簡單陳述。"},{"en":"A teacher should not merely say “wrong” but should explain why the answer does not work.","zh":"老師不應只是說「錯」，而應解釋答案為何不成立。"},{"en":"Critics who merely say they like or hate something do not help the creator improve.","zh":"批評者如果只是說自己喜歡或討厭某物，並不能幫助創作者改善。"},{"en":"This phrase pushes people to give reasons, evidence, and suggestions.","zh":"這個短語推動人們給出理由、證據和建議。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"create energy","meaning":"營造活力","examples":[{"en":"The red background creates energy.","zh":"紅色背景營造活力。"},{"en":"To create energy means to make something feel lively, active, or exciting.","zh":"營造活力是指令某物感覺生動、活躍或令人興奮。"},{"en":"Fast music can create energy at the beginning of a dance performance.","zh":"快速音樂可以在舞蹈表演開首營造活力。"},{"en":"Bright colours create energy in a poster and may attract people’s eyes.","zh":"鮮艷色彩在海報中營造活力，並可能吸引人們的目光。"},{"en":"Artists create energy through colour, movement, sound, rhythm, and contrast.","zh":"藝術家透過色彩、動作、聲音、節奏和對比營造活力。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"attract attention","meaning":"吸引注意","examples":[{"en":"The singer’s photo attracts attention.","zh":"歌手的照片吸引注意。"},{"en":"To attract attention means to make people notice something.","zh":"吸引注意是指令人注意到某物。"},{"en":"A large headline attracts attention when people walk past a noticeboard.","zh":"當人們走過告示板時，大標題會吸引注意。"},{"en":"A poster must attract attention quickly because viewers may only look for a few seconds.","zh":"海報必須快速吸引注意，因為觀眾可能只看幾秒。"},{"en":"Good design attracts attention without hiding important information.","zh":"好設計會吸引注意，而不遮掩重要資訊。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"from a distance","meaning":"從遠處","examples":[{"en":"The date is too small to read from a distance.","zh":"日期太小，從遠處看不清。"},{"en":"From a distance means from far away, not close up.","zh":"從遠處是指由較遠的位置，而不是近距離。"},{"en":"A stage sign must be clear from a distance so the back row can read it.","zh":"舞台標誌必須從遠處也清楚，讓後排觀眾能閱讀。"},{"en":"If a poster’s words cannot be read from a distance, people may miss the event details.","zh":"如果海報文字從遠處看不清，人們可能錯過活動詳情。"},{"en":"Designers consider distance because public information is often seen while people are moving.","zh":"設計者會考慮距離，因為公共資訊常在人們走動時被看見。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"useful criticism","meaning":"有用的批評","examples":[{"en":"That is useful criticism because it examines purpose, technique, and effect.","zh":"那是有用的批評，因為它審視目的、技巧和效果。"},{"en":"Useful criticism gives clear reasons and helps the creator improve.","zh":"有用的批評會給出清楚理由，並幫助創作者改善。"},{"en":"Telling a classmate which paragraph is confusing is useful criticism if you also explain why.","zh":"如果你告訴同學哪一段令人困惑，並解釋原因，那就是有用的批評。"},{"en":"Useful criticism saves time because the artist knows what to change next.","zh":"有用的批評能節省時間，因為藝術家知道下一步要改甚麼。"},{"en":"Criticism becomes useful when it is specific, fair, and connected to the work.","zh":"當批評具體、公平，並與作品有關時，它就變得有用。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"examine purpose, technique and effect","meaning":"審視目的、技巧和效果","examples":[{"en":"Useful criticism examines purpose, technique, and effect.","zh":"有用的批評會審視目的、技巧和效果。"},{"en":"To examine purpose, technique, and effect means to look at what the work tries to do, how it is made, and how it affects people.","zh":"審視目的、技巧和效果，是指看作品想做甚麼、如何製作，以及如何影響人。"},{"en":"A critic may examine purpose, technique, and effect when reviewing a school play.","zh":"批評者評論學校話劇時，可能會審視目的、技巧和效果。"},{"en":"This method prevents criticism from becoming only personal taste.","zh":"這種方法能防止批評只變成個人喜好。"},{"en":"It helps creators understand both their goals and their artistic choices.","zh":"它幫助創作者理解自己的目標和藝術選擇。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"put simply","meaning":"簡單來說","examples":[{"en":"Put simply, a critic helps the creator see the work more clearly.","zh":"簡單來說，批評者幫助創作者更清楚看見作品。"},{"en":"Put simply is used before explaining something in a clear and easy way.","zh":"簡單來說，是在用清楚易明的方式解釋某事前使用。"},{"en":"Put simply, recycling works only when people know where to put different materials.","zh":"簡單來說，只有當人們知道把不同物料放在哪裡時，回收才有效。"},{"en":"A speaker uses put simply when the previous idea may sound complicated.","zh":"當前面的想法可能聽起來複雜時，講者會使用「簡單來說」。"},{"en":"This phrase helps listeners focus on the main point.","zh":"這個短語幫助聽眾集中於重點。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"judge a work","meaning":"評價一件作品","examples":[{"en":"A critic does not just judge a work.","zh":"批評者不只是評價一件作品。"},{"en":"To judge a work means to form an opinion about its quality, meaning, or effect.","zh":"評價一件作品是指對其質素、意思或效果形成看法。"},{"en":"A teacher judges a work more fairly when she reads the whole essay before marking it.","zh":"老師在評分前讀完整篇文章，會更公平地評價一件作品。"},{"en":"Critics should judge a work by its purpose and evidence, not by personal dislike alone.","zh":"批評者應根據作品目的和證據評價一件作品，而不只是根據個人不喜歡。"},{"en":"Judging a work is useful only when the judgement explains something.","zh":"只有當評價能解釋一些事情時，評價一件作品才有用。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"help the creator see","meaning":"幫助創作者看清","examples":[{"en":"A critic helps the creator see the work more clearly.","zh":"批評者幫助創作者更清楚看見作品。"},{"en":"To help the creator see means to make the artist notice things they may have missed.","zh":"幫助創作者看清，是指令藝術家注意到自己可能忽略的事情。"},{"en":"A friend can help the creator see that a story’s ending feels too sudden.","zh":"朋友可以幫助創作者看清故事結尾感覺太突然。"},{"en":"Helpful feedback gives creators another pair of eyes on their work.","zh":"有幫助的回饋為創作者提供另一雙眼睛看作品。"},{"en":"This phrase shows that criticism can be supportive, not only corrective.","zh":"這個短語顯示批評可以是支持性的，而不只是糾正性的。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"the golden rule","meaning":"黃金法則","examples":[{"en":"The golden rule is to criticise the work, not the worth of the person.","zh":"黃金法則是批評作品，而不是否定人的價值。"},{"en":"The golden rule is the most important rule to remember in a situation.","zh":"黃金法則是在某種情況中最重要、最應記住的規則。"},{"en":"The golden rule in group feedback is to speak honestly without attacking anyone.","zh":"小組回饋中的黃金法則是誠實說話，但不攻擊任何人。"},{"en":"When people forget the golden rule, criticism can become personal and painful.","zh":"當人們忘記黃金法則時，批評可能變得針對個人並令人痛苦。"},{"en":"This phrase signals a simple principle that should guide everyone’s behaviour.","zh":"這個短語表示一條應指引所有人行為的簡單原則。"}],"source":"2019 Q7.pdf","sourcePage":5},{"front":"criticise the work, not the worth of the person","meaning":"批評作品，而不是否定人的價值","examples":[{"en":"We should criticise the work, not the worth of the person.","zh":"我們應批評作品，而不是否定人的價值。"},{"en":"Criticise the work, not the worth of the person means discuss the creation without attacking the creator’s value.","zh":"批評作品，而不是否定人的價值，是指討論創作，而不攻擊創作者的價值。"},{"en":"Saying “the ending is unclear” criticises the work, but saying “you cannot write” attacks the person.","zh":"說「結尾不清楚」是在批評作品，但說「你不會寫作」是在攻擊個人。"},{"en":"This rule protects artists from shame while still allowing honest feedback.","zh":"這條規則保護藝術家免於羞辱，同時仍容許誠實回饋。"},{"en":"It helps a creative group stay brave, respectful, and productive.","zh":"它幫助創作群體保持勇敢、尊重和有效率。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"the worth of the person","meaning":"一個人的價值","examples":[{"en":"Good criticism should not attack the worth of the person.","zh":"好的批評不應攻擊一個人的價值。"},{"en":"The worth of the person means a person’s value as a human being.","zh":"一個人的價值是指某人作為人的價值。"},{"en":"A weak painting does not reduce the worth of the person who painted it.","zh":"一幅較弱的畫不會降低畫它的人的價值。"},{"en":"Attacking the worth of the person makes feedback cruel instead of useful.","zh":"攻擊一個人的價值會令回饋變得殘酷，而不是有用。"},{"en":"Good critics separate a person’s value from one piece of work.","zh":"好的批評者會把人的價值與一件作品分開。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"feels rushed","meaning":"感覺倉促","examples":[{"en":"We may say, “The ending feels rushed.”","zh":"我們可以說：「結尾感覺倉促。」"},{"en":"Feels rushed means something seems too quick, unfinished, or not fully developed.","zh":"感覺倉促是指某事看似太快、未完成或發展不足。"},{"en":"A story ending feels rushed when three problems are solved in one short paragraph.","zh":"當三個問題在一個短段落中被解決時，故事結尾會感覺倉促。"},{"en":"A performance may feel rushed if actors speak too quickly and skip emotional pauses.","zh":"如果演員說話太快並跳過情感停頓，表演可能感覺倉促。"},{"en":"This phrase criticises the pace of the work, not the ability of the artist.","zh":"這個短語批評作品的節奏，而不是藝術家的能力。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"the melody becomes repetitive","meaning":"旋律變得重複","examples":[{"en":"The melody becomes repetitive after the second verse.","zh":"第二段之後，旋律變得重複。"},{"en":"The melody becomes repetitive means the tune repeats so much that it starts to feel dull.","zh":"旋律變得重複，是指曲調重複太多，以致開始感覺沉悶。"},{"en":"A song may lose energy when the melody becomes repetitive without any change in rhythm or pitch.","zh":"當旋律變得重複，而節奏或音高沒有任何變化時，歌曲可能失去活力。"},{"en":"Critics mention repetition when it weakens the listener’s interest.","zh":"當重複削弱聽眾興趣時，批評者會提到這一點。"},{"en":"This comment is useful because it points to a specific part of the music.","zh":"這個評論有用，因為它指出音樂中的具體部分。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"after the second verse","meaning":"第二段之後","examples":[{"en":"The melody becomes repetitive after the second verse.","zh":"第二段之後，旋律變得重複。"},{"en":"After the second verse means following the second main section of a song or poem.","zh":"第二段之後，是指在歌曲或詩的第二個主要段落之後。"},{"en":"The singer adds stronger drums after the second verse to build excitement.","zh":"歌手在第二段之後加入更強的鼓聲，以建立興奮感。"},{"en":"If nothing changes after the second verse, listeners may feel the song is too predictable.","zh":"如果第二段之後沒有任何變化，聽眾可能覺得歌曲太易預測。"},{"en":"This phrase helps critics locate exactly where a musical problem begins.","zh":"這個短語幫助批評者準確指出音樂問題從哪裡開始。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"a world of difference between","meaning":"……之間有天壤之別","examples":[{"en":"There is a world of difference between criticising work and attacking a person.","zh":"批評作品與攻擊個人之間有天壤之別。"},{"en":"A world of difference between two things means they are extremely different.","zh":"兩者之間有天壤之別，是指它們非常不同。"},{"en":"There is a world of difference between honest feedback and public humiliation.","zh":"誠實回饋與公開羞辱之間有天壤之別。"},{"en":"Understanding this difference helps students give criticism without cruelty.","zh":"理解這種差別能幫助學生提出批評而不殘酷。"},{"en":"This phrase strongly emphasises that two things should not be confused.","zh":"這個短語強調兩件事不應被混淆。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"specific, evidence-based and actionable","meaning":"具體、有證據支持而且可實行","examples":[{"en":"Good criticism should be specific, evidence-based, and actionable.","zh":"好的批評應該具體、有證據支持而且可實行。"},{"en":"Specific, evidence-based, and actionable criticism names the problem, supports it with proof, and suggests what to do next.","zh":"具體、有證據支持而且可實行的批評，會指出問題、用證據支持，並建議下一步做法。"},{"en":"A teacher gives this kind of criticism by pointing to one paragraph and explaining how to revise it.","zh":"老師指向某一段並解釋如何修改，就是給出這類批評。"},{"en":"Such criticism helps creators improve because it is clear rather than vague.","zh":"這類批評能幫助創作者改善，因為它清楚而不含糊。"},{"en":"These three qualities turn criticism from opinion into guidance.","zh":"這三個特質把批評由意見變成指引。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"evidence-based","meaning":"有證據支持的","examples":[{"en":"Good criticism should be evidence-based.","zh":"好的批評應該是有證據支持的。"},{"en":"Evidence-based means supported by clear facts, examples, or details.","zh":"有證據支持的是指由清楚事實、例子或細節支持。"},{"en":"A comment is evidence-based when it refers to a specific line, image, scene, or sound.","zh":"當評論提到具體句子、圖像、場景或聲音時，它就是有證據支持的。"},{"en":"Evidence-based criticism is fairer because the creator can see what the critic means.","zh":"有證據支持的批評較公平，因為創作者能看見批評者的意思。"},{"en":"Without evidence, criticism can feel like personal taste or random judgement.","zh":"沒有證據，批評可能感覺像個人喜好或隨意判斷。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"actionable","meaning":"可實行的","examples":[{"en":"Good criticism should be actionable.","zh":"好的批評應該是可實行的。"},{"en":"Actionable means clear enough for someone to know what to do next.","zh":"可實行的是指清楚到令人知道下一步可以做甚麼。"},{"en":"“Make the ending slower by adding one pause” is more actionable than “make it better.”","zh":"「加入一個停頓，令結尾慢一點」比「令它更好」更可實行。"},{"en":"Actionable feedback helps artists revise instead of just feel discouraged.","zh":"可實行的回饋幫助藝術家修改，而不只是感到沮喪。"},{"en":"A comment is useful when it gives the creator a possible next step.","zh":"當評論給創作者一個可能的下一步時，它就是有用的。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"start by identifying","meaning":"先指出","examples":[{"en":"Start by identifying one genuine strength.","zh":"先指出一個真正的優點。"},{"en":"Start by identifying means begin by noticing and naming something clearly.","zh":"先指出是指開始時先清楚注意並說出某事。"},{"en":"A peer reviewer may start by identifying the strongest image in a poem.","zh":"同儕評閱者可能先指出一首詩中最有力的意象。"},{"en":"Starting with a strength helps the creator feel seen before hearing suggestions.","zh":"先從優點開始，能令創作者在聽取建議前感到被看見。"},{"en":"This phrase gives a practical first step for giving balanced feedback.","zh":"這個短語為提出平衡回饋提供實際第一步。"}],"source":"2019 Q7.pdf","sourcePage":6},{"front":"one genuine strength","meaning":"一個真正的優點","examples":[{"en":"Good criticism begins with one genuine strength.","zh":"好的批評由一個真正的優點開始。"},{"en":"One genuine strength means one real positive feature, not empty praise.","zh":"一個真正的優點，是指一個真實的正面特點，而不是空洞讚美。"},{"en":"In a painting, one genuine strength might be the careful use of light.","zh":"在一幅畫中，一個真正的優點可能是細心使用光線。"},{"en":"Naming one genuine strength shows the creator what already works well.","zh":"說出一個真正的優點，能讓創作者知道哪些地方已經有效。"},{"en":"Honest praise makes later criticism easier to accept.","zh":"誠實的讚賞會令之後的批評更容易被接受。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"point out","meaning":"指出","examples":[{"en":"Then point out one area for improvement.","zh":"然後指出一個有待改善的地方。"},{"en":"To point out means to draw someone’s attention to something important.","zh":"指出是指讓某人注意到重要的事情。"},{"en":"A classmate may point out that the title is interesting but the ending is unclear.","zh":"同學可能指出標題有趣，但結尾不清楚。"},{"en":"Pointing out a problem is helpful when the comment is specific and respectful.","zh":"當評論具體而尊重時，指出問題是有幫助的。"},{"en":"This phrase is often used when giving advice or correction.","zh":"這個短語常用於給予建議或糾正。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"one area for improvement","meaning":"一個有待改善的地方","examples":[{"en":"Point out one area for improvement.","zh":"指出一個有待改善的地方。"},{"en":"One area for improvement means one specific part that could become better.","zh":"一個有待改善的地方，是指一個可以變得更好的具體部分。"},{"en":"In a speech, one area for improvement might be eye contact with the audience.","zh":"在演講中，一個有待改善的地方可能是與觀眾的眼神接觸。"},{"en":"Choosing one area for improvement prevents feedback from becoming overwhelming.","zh":"選擇一個有待改善的地方，能防止回饋變得令人承受不了。"},{"en":"This phrase sounds constructive because it focuses on growth, not failure.","zh":"這個短語聽起來有建設性，因為它著重成長，而不是失敗。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"explain why it matters","meaning":"解釋為何重要","examples":[{"en":"After that, explain why it matters.","zh":"之後，解釋為何重要。"},{"en":"To explain why it matters means to show why a point is important or how it affects the work.","zh":"解釋為何重要，是指顯示某一點為何重要或如何影響作品。"},{"en":"If a poster’s date is too small, explain why it matters: people may miss the concert.","zh":"如果海報日期太小，便要解釋為何重要：人們可能錯過音樂會。"},{"en":"Explaining why it matters helps the creator understand the reason behind the advice.","zh":"解釋為何重要能幫助創作者理解建議背後的原因。"},{"en":"Good criticism does not only name a problem; it explains its effect.","zh":"好的批評不只指出問題，還會解釋其影響。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"suggest a possible solution","meaning":"提出一個可行解決方法","examples":[{"en":"A helpful critic suggests a possible solution.","zh":"有幫助的批評者會提出一個可行解決方法。"},{"en":"To suggest a possible solution means to offer one practical way to improve the problem.","zh":"提出一個可行解決方法，是指提供一種實際方法來改善問題。"},{"en":"If a speech sounds flat, a critic may suggest a possible solution such as adding a personal story.","zh":"如果演講聽起來平淡，批評者可能提出加入個人故事等可行解決方法。"},{"en":"Suggesting a possible solution makes criticism easier to act on.","zh":"提出一個可行解決方法，令批評更容易付諸行動。"},{"en":"The solution does not have to be perfect, but it should give the creator a useful direction.","zh":"解決方法不必完美，但應給創作者有用方向。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"instead of saying","meaning":"與其說","examples":[{"en":"Instead of saying, “Your monologue is bad,” give specific comments.","zh":"與其說「你的獨白很差」，不如給出具體評論。"},{"en":"Instead of saying introduces a less helpful phrase that should be replaced by a better one.","zh":"與其說，用來引出一個較沒有幫助、應被更好說法取代的句子。"},{"en":"Instead of saying “this is boring,” explain which part loses energy and why.","zh":"與其說「這很沉悶」，不如解釋哪一部分失去活力以及原因。"},{"en":"This phrase helps speakers move from vague judgement to useful feedback.","zh":"這個短語幫助講者由含糊評價轉向有用回饋。"},{"en":"It teaches people to choose words that guide rather than wound.","zh":"它教人選擇能引導而不是傷害的說話。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"monologue","meaning":"獨白","examples":[{"en":"A monologue can become stronger with clearer emotional development.","zh":"獨白可以透過更清晰的情感發展變得更有力。"},{"en":"A monologue is a long speech by one character or speaker.","zh":"獨白是由一個角色或講者說出的長篇說話。"},{"en":"In a drama performance, a monologue may reveal what a character secretly feels.","zh":"在戲劇表演中，獨白可能揭示角色暗中感受到的事情。"},{"en":"A monologue becomes more powerful when the emotion changes instead of staying the same.","zh":"當情感有變化而不是停留不變時，獨白會更有力量。"},{"en":"Critics reviewing a monologue may discuss voice, pacing, silence, and feeling.","zh":"評論獨白時，批評者可能討論聲線、節奏、沉默和感情。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"opening line","meaning":"開場白","examples":[{"en":"Your opening line is powerful.","zh":"你的開場白很有力量。"},{"en":"An opening line is the first sentence or first spoken line of a piece.","zh":"開場白是作品中的第一句或第一句說話。"},{"en":"A strong opening line can make the audience curious immediately.","zh":"有力的開場白可以立即令觀眾好奇。"},{"en":"If the opening line is confusing, listeners may struggle to follow the rest.","zh":"如果開場白令人困惑，聽眾可能難以跟上之後的內容。"},{"en":"Critics often discuss the opening line because it sets the first impression.","zh":"批評者常討論開場白，因為它建立第一印象。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"powerful","meaning":"有力量的","examples":[{"en":"The opening line is powerful.","zh":"開場白很有力量。"},{"en":"Powerful means strong in effect, emotion, or meaning.","zh":"有力量的是指在效果、情感或意思上很強。"},{"en":"A powerful photograph can make people understand suffering without many words.","zh":"一張有力量的照片可以不用很多文字就令人理解痛苦。"},{"en":"A speech becomes powerful when examples are honest and easy to imagine.","zh":"當例子真誠又容易想像時，演講會變得有力量。"},{"en":"In criticism, powerful describes something that strongly affects the audience.","zh":"在批評中，有力量的形容某物強烈影響觀眾。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"middle section","meaning":"中段","examples":[{"en":"The middle section repeats the same emotion for too long.","zh":"中段重複同一種情緒太久。"},{"en":"The middle section is the part between the beginning and the ending.","zh":"中段是開首與結尾之間的部分。"},{"en":"In a short story, the middle section develops the conflict before the conclusion.","zh":"在短篇故事中，中段在結論前發展衝突。"},{"en":"If the middle section is too slow, readers may lose interest before the ending.","zh":"如果中段太慢，讀者可能在結尾前失去興趣。"},{"en":"Critics locate problems by naming parts such as the opening, middle section, and ending.","zh":"批評者透過指出開首、中段和結尾等部分來定位問題。"}],"source":"2019 Q7.pdf","sourcePage":7},{"front":"repeat the same emotion","meaning":"重複同一種情緒","examples":[{"en":"The middle section repeats the same emotion for too long.","zh":"中段重複同一種情緒太久。"},{"en":"To repeat the same emotion means to show one feeling again and again without change.","zh":"重複同一種情緒，是指不斷展示同一種感受而沒有變化。"},{"en":"A monologue may feel flat if it repeats the same anger from beginning to end.","zh":"如果獨白從頭到尾重複同一種憤怒，可能會感覺平淡。"},{"en":"Repeating the same emotion for too long can reduce dramatic tension.","zh":"重複同一種情緒太久，可能減弱戲劇張力。"},{"en":"A change in tone can help the audience see the character more deeply.","zh":"語氣轉變可以幫助觀眾更深入看見角色。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"for too long","meaning":"太久","examples":[{"en":"The middle section repeats the same emotion for too long.","zh":"中段重複同一種情緒太久。"},{"en":"For too long means for more time than is helpful, comfortable, or effective.","zh":"太久是指時間長到不再有幫助、不舒服或無效。"},{"en":"If a speech introduction lasts for too long, the audience may lose focus.","zh":"如果演講引言持續太久，觀眾可能失去焦點。"},{"en":"Holding the same note for too long can make a song feel awkward.","zh":"同一個音拉得太久，可能令歌曲感覺尷尬。"},{"en":"This phrase often points to a problem of timing or pacing.","zh":"這個短語常指出時間或節奏上的問題。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"add a moment of silence","meaning":"加入一刻沉默","examples":[{"en":"You could add a moment of silence to reveal the character more deeply.","zh":"你可以加入一刻沉默，以更深入展現角色。"},{"en":"To add a moment of silence means to include a short pause with no words or sound.","zh":"加入一刻沉默，是指加入一段沒有說話或聲音的短暫停頓。"},{"en":"An actor may add a moment of silence before confessing a painful memory.","zh":"演員可能在承認痛苦記憶前加入一刻沉默。"},{"en":"A moment of silence can make the audience feel tension, sadness, or thoughtfulness.","zh":"一刻沉默可以令觀眾感到緊張、悲傷或深思。"},{"en":"Silence is useful when words alone cannot show the character’s inner life.","zh":"當單靠說話不能展示角色內心時，沉默很有用。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"a change in tone","meaning":"語氣轉變","examples":[{"en":"You could add a change in tone to improve the monologue.","zh":"你可以加入語氣轉變來改善獨白。"},{"en":"A change in tone means a shift in feeling, attitude, or voice.","zh":"語氣轉變是指感情、態度或聲線上的變化。"},{"en":"A speech may become more interesting when it moves from humorous to serious in tone.","zh":"當演講由幽默轉為嚴肅時，可能會因語氣轉變而更有趣。"},{"en":"A change in tone can show that a character is beginning to understand something.","zh":"語氣轉變可以顯示角色開始明白某件事。"},{"en":"Without a change in tone, a long performance may feel emotionally flat.","zh":"沒有語氣轉變，長篇表演可能感覺情感平淡。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"reveal the character more deeply","meaning":"更深入展現角色","examples":[{"en":"A memory may reveal the character more deeply.","zh":"一段記憶可能更深入展現角色。"},{"en":"To reveal the character more deeply means to show more of a character’s thoughts, feelings, past, or motives.","zh":"更深入展現角色，是指展示角色更多思想、感受、過去或動機。"},{"en":"A pause before an apology can reveal the character more deeply than a long explanation.","zh":"道歉前的停頓，可能比長篇解釋更深入展現角色。"},{"en":"Details about childhood may reveal the character more deeply by explaining their fear.","zh":"關於童年的細節可以透過解釋恐懼，更深入展現角色。"},{"en":"This phrase is useful in drama, film, fiction, and performance criticism.","zh":"這個短語在戲劇、電影、小說和表演評論中很有用。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"that way","meaning":"這樣一來","examples":[{"en":"That way, the artist knows what worked and what to try next.","zh":"這樣一來，藝術家就知道哪些地方有效，以及下一步可以嘗試甚麼。"},{"en":"That way means by doing this or as a result of this method.","zh":"這樣一來，是指透過這樣做或因這個方法而產生結果。"},{"en":"Give one strength and one suggestion; that way, the student knows both what to keep and what to change.","zh":"給出一個優點和一個建議；這樣一來，學生就知道哪些要保留、哪些要改變。"},{"en":"Write the feedback clearly; that way, the artist can use it later.","zh":"清楚寫下回饋；這樣一來，藝術家日後就能使用。"},{"en":"This phrase connects an action with its helpful result.","zh":"這個短語把行動與其有幫助的結果連接起來。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"what worked","meaning":"哪些地方有效","examples":[{"en":"The artist knows what worked in the piece.","zh":"藝術家知道作品中哪些地方有效。"},{"en":"What worked means the parts that were successful or effective.","zh":"哪些地方有效，是指成功或有成效的部分。"},{"en":"After a performance, actors discuss what worked so they can keep the strongest moments.","zh":"表演後，演員會討論哪些地方有效，好保留最有力的時刻。"},{"en":"Knowing what worked is as important as knowing what failed.","zh":"知道哪些地方有效，與知道哪些地方失敗同樣重要。"},{"en":"This phrase helps feedback include strengths, not only problems.","zh":"這個短語幫助回饋包括優點，而不只是問題。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"what did not","meaning":"哪些地方無效","examples":[{"en":"The artist knows what did not work in the piece.","zh":"藝術家知道作品中哪些地方無效。"},{"en":"What did not means the parts that failed, confused people, or had less effect.","zh":"哪些地方無效，是指失敗、令人困惑或效果較弱的部分。"},{"en":"A writer learns what did not work when readers say the middle chapter feels slow.","zh":"當讀者說中間章節感覺緩慢時，作者就知道哪些地方無效。"},{"en":"Knowing what did not work helps the creator revise with direction.","zh":"知道哪些地方無效，能幫助創作者有方向地修改。"},{"en":"This phrase focuses on the work’s effect, not the artist’s personal worth.","zh":"這個短語著重作品效果，而不是藝術家的個人價值。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"what to try next","meaning":"下一步可以嘗試甚麼","examples":[{"en":"Useful criticism tells the artist what to try next.","zh":"有用的批評會告訴藝術家下一步可以嘗試甚麼。"},{"en":"What to try next means the next action or experiment that may improve the work.","zh":"下一步可以嘗試甚麼，是指可能改善作品的下一個行動或實驗。"},{"en":"A dance teacher may tell a student what to try next, such as slowing one movement down.","zh":"舞蹈老師可能告訴學生下一步可以嘗試甚麼，例如放慢一個動作。"},{"en":"Feedback becomes practical when it gives the creator something to try next.","zh":"當回饋給創作者可以下一步嘗試的事情時，它就變得實用。"},{"en":"This phrase turns criticism into a path forward.","zh":"這個短語把批評轉化成向前走的路。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"ask questions","meaning":"提問","examples":[{"en":"Good critics also ask questions.","zh":"好的批評者也會提問。"},{"en":"To ask questions means to invite explanation instead of making only statements.","zh":"提問是指邀請別人解釋，而不是只作陳述。"},{"en":"A critic may ask questions such as, “What feeling did you want this scene to create?”","zh":"批評者可能提問，例如：「你希望這一幕營造甚麼感覺？」"},{"en":"Asking questions helps the artist explain intentions that may not be obvious.","zh":"提問幫助藝術家解釋可能不明顯的意圖。"},{"en":"Questions can make criticism feel like a conversation rather than a judgement.","zh":"問題可以令批評感覺像對話，而不是判決。"}],"source":"2019 Q7.pdf","sourcePage":8},{"front":"what mood were you hoping to create","meaning":"你希望營造甚麼氣氛","examples":[{"en":"“What mood were you hoping to create?” is a respectful question.","zh":"「你希望營造甚麼氣氛？」是一個尊重人的問題。"},{"en":"What mood were you hoping to create asks what feeling the artist wanted the audience to have.","zh":"「你希望營造甚麼氣氛？」是問藝術家希望觀眾有甚麼感受。"},{"en":"A teacher may ask this question before giving advice about music, colour, or lighting.","zh":"老師在給予關於音樂、色彩或燈光的建議前，可能會問這個問題。"},{"en":"This question respects the artist’s intention before judging the result.","zh":"這個問題在評價結果前尊重藝術家的意圖。"},{"en":"It helps critics understand whether the work’s choices match its aim.","zh":"它幫助批評者理解作品選擇是否符合目標。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"more respectful than","meaning":"比……更尊重人","examples":[{"en":"A question can be more respectful than a blunt judgement.","zh":"問題可以比直接判斷更尊重人。"},{"en":"More respectful than means showing greater care, politeness, or consideration than something else.","zh":"比……更尊重人，是指比另一事物表現出更多關心、禮貌或體諒。"},{"en":"Asking “What were you trying to show here?” is more respectful than saying “This makes no sense.”","zh":"問「你在這裡想展示甚麼？」比說「這完全沒意思」更尊重人。"},{"en":"A more respectful comment keeps the conversation open instead of closing it down.","zh":"更尊重人的評論會保持對話開放，而不是令對話結束。"},{"en":"This phrase compares two ways of speaking and shows which is kinder.","zh":"這個短語比較兩種說話方式，並顯示哪一種更善意。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"only when…do…","meaning":"只有當……才會……","examples":[{"en":"Only when people feel safe do they speak honestly.","zh":"只有當人們感到安全時，他們才會坦誠發言。"},{"en":"Only when A do B means B happens only if A is true first.","zh":"「只有當A才會B」意思是只有A先成立，B才會發生。"},{"en":"Only when students understand the rules do they give fair feedback.","zh":"只有當學生理解規則時，他們才會給出公平回饋。"},{"en":"Only when artists trust the room do they share unfinished work bravely.","zh":"只有當藝術家信任這個空間時，他們才會勇敢分享未完成作品。"},{"en":"This structure strongly emphasises the necessary condition for an action.","zh":"這個句式強烈強調一個行動所需的條件。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"feel safe","meaning":"感到安全","examples":[{"en":"People speak honestly when they feel safe.","zh":"人們感到安全時，會坦誠發言。"},{"en":"To feel safe means to believe you will not be attacked, laughed at, or treated unfairly.","zh":"感到安全是指相信自己不會被攻擊、嘲笑或不公平對待。"},{"en":"Students feel safe in a discussion when classmates listen respectfully.","zh":"當同學尊重地聆聽時，學生在討論中會感到安全。"},{"en":"Artists share more honestly when they feel safe from personal insult.","zh":"當藝術家感到不會被人身侮辱時，會更誠實分享。"},{"en":"A safe environment makes brave and useful criticism possible.","zh":"安全的環境令勇敢而有用的批評成為可能。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"speak honestly","meaning":"坦誠發言","examples":[{"en":"People speak honestly when they feel safe.","zh":"人們感到安全時，會坦誠發言。"},{"en":"To speak honestly means to say what one truly thinks or feels without pretending.","zh":"坦誠發言是指說出自己真正的想法或感受，而不假裝。"},{"en":"A student speaks honestly when she admits that a group project is confusing.","zh":"當學生承認小組專題令人困惑時，她就是坦誠發言。"},{"en":"People speak honestly more easily when they know disagreement will stay respectful.","zh":"當人們知道分歧仍會保持尊重時，會更容易坦誠發言。"},{"en":"Honest speech helps a group solve problems instead of hiding them.","zh":"坦誠發言幫助群體解決問題，而不是隱藏問題。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"can art improve","meaning":"藝術才能進步","examples":[{"en":"Only when criticism is honest can art improve.","zh":"只有當批評是誠實的，藝術才能進步。"},{"en":"Can art improve asks whether creative work can become better through effort, revision, and feedback.","zh":"藝術才能進步，是問創作能否透過努力、修改和回饋變得更好。"},{"en":"Art can improve when creators understand what works and what needs change.","zh":"當創作者理解哪些地方有效、哪些地方需要改變時，藝術才能進步。"},{"en":"If criticism is only praise or only attack, art may not improve much.","zh":"如果批評只有讚美或只有攻擊，藝術可能不會有太大進步。"},{"en":"This phrase connects honest feedback with artistic growth.","zh":"這個短語把誠實回饋與藝術成長連接起來。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"let me be clear","meaning":"讓我說清楚","examples":[{"en":"Let me be clear: listening to criticism does not mean obeying every comment.","zh":"讓我說清楚：聆聽批評並不代表接受每一個意見。"},{"en":"Let me be clear is used before a speaker states an important point directly.","zh":"讓我說清楚，是講者直接說出重要觀點前使用的短語。"},{"en":"Let me be clear: asking for feedback does not mean losing control of your work.","zh":"讓我說清楚：尋求回饋並不代表失去對作品的控制。"},{"en":"A speaker uses this phrase to prevent misunderstanding.","zh":"講者使用這個短語來防止誤解。"},{"en":"It signals that the next idea should be taken seriously.","zh":"它表示接下來的想法應被認真看待。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"listening to criticism","meaning":"聆聽批評","examples":[{"en":"Listening to criticism does not mean obeying every comment.","zh":"聆聽批評並不代表接受每一個意見。"},{"en":"Listening to criticism means paying attention to feedback before deciding what to accept.","zh":"聆聽批評是指在決定接受甚麼前，先留心聽取回饋。"},{"en":"A dancer listens to criticism when she asks why a movement looked unclear.","zh":"當舞者詢問一個動作為何看起來不清楚時，她就是在聆聽批評。"},{"en":"Listening to criticism helps creators notice problems they could not see alone.","zh":"聆聽批評幫助創作者注意到自己無法獨自看見的問題。"},{"en":"It is different from blindly following every opinion.","zh":"它不同於盲目跟隨每一個意見。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"obey every comment","meaning":"接受每一個意見","examples":[{"en":"You do not have to obey every comment.","zh":"你不必接受每一個意見。"},{"en":"To obey every comment means to follow all feedback exactly, even when some of it may not fit your purpose.","zh":"接受每一個意見，是指完全跟隨所有回饋，即使有些未必符合你的目的。"},{"en":"A writer should not obey every comment if two readers give opposite advice.","zh":"如果兩位讀者給出相反建議，作者不應接受每一個意見。"},{"en":"Obeying every comment can make a work lose its own voice.","zh":"接受每一個意見可能令作品失去自己的聲音。"},{"en":"Artists should listen carefully, then choose what truly helps the work.","zh":"藝術家應仔細聆聽，然後選擇真正幫助作品的意見。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"your work is still yours","meaning":"你的作品仍然屬於你","examples":[{"en":"Your work is still yours.","zh":"你的作品仍然屬於你。"},{"en":"Your work is still yours means feedback does not take away your ownership or artistic choice.","zh":"你的作品仍然屬於你，是指回饋不會奪走你的擁有權或藝術選擇。"},{"en":"Even after ten classmates comment on your painting, your work is still yours.","zh":"即使十位同學評論你的畫作，你的作品仍然屬於你。"},{"en":"Remembering this helps artists listen without feeling controlled.","zh":"記住這一點能幫助藝術家聆聽，而不感到被控制。"},{"en":"This phrase gives creators confidence to accept useful advice and reject unsuitable advice.","zh":"這個短語給創作者信心，讓他們接受有用建議並拒絕不合適的建議。"}],"source":"2019 Q7.pdf","sourcePage":9},{"front":"first reaction","meaning":"第一反應","examples":[{"en":"Your first reaction may be to defend everything.","zh":"你的第一反應可能是為一切辯護。"},{"en":"First reaction means the immediate feeling or response before you have time to think deeply.","zh":"第一反應是指在有時間深入思考前立即出現的感受或回應。"},{"en":"A student’s first reaction to criticism may be embarrassment or anger.","zh":"學生面對批評的第一反應可能是尷尬或憤怒。"},{"en":"First reactions are natural, but they are not always the wisest response.","zh":"第一反應是自然的，但不一定是最明智的回應。"},{"en":"Pausing helps people move beyond their first reaction and listen better.","zh":"停一停能幫助人們超越第一反應，更好地聆聽。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"defend everything","meaning":"為一切辯護","examples":[{"en":"If you defend everything immediately, you may miss something valuable.","zh":"如果你立即為一切辯護，可能會錯過有價值的東西。"},{"en":"To defend everything means to explain or protect every choice without first considering the feedback.","zh":"為一切辯護，是指在考慮回饋前，先解釋或保護每一個選擇。"},{"en":"A writer who defends everything may fail to notice that readers are genuinely confused.","zh":"為一切辯護的作者可能無法注意到讀者真的感到困惑。"},{"en":"Defending everything can turn useful criticism into an argument.","zh":"為一切辯護可能把有用批評變成爭執。"},{"en":"Listening first does not mean surrendering; it means giving feedback a fair chance.","zh":"先聆聽不代表投降，而是給回饋一個公平機會。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"miss something valuable","meaning":"錯過有價值的東西","examples":[{"en":"You may miss something valuable if you refuse to listen.","zh":"如果你拒絕聆聽，可能會錯過有價值的東西。"},{"en":"To miss something valuable means to fail to notice useful information, advice, or opportunity.","zh":"錯過有價值的東西，是指未能注意有用資訊、建議或機會。"},{"en":"A student may miss something valuable in feedback if they only focus on feeling hurt.","zh":"如果學生只專注於受傷的感覺，可能會錯過回饋中有價值的東西。"},{"en":"Artists who ignore all criticism may miss ideas that could strengthen their work.","zh":"忽視所有批評的藝術家可能錯過能加強作品的想法。"},{"en":"This phrase warns that pride can block learning.","zh":"這個短語警告我們，驕傲可能阻礙學習。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"take notes","meaning":"做筆記","examples":[{"en":"When someone comments on your work, pause and take notes.","zh":"當有人評論你的作品時，停一停並做筆記。"},{"en":"To take notes means to write down important points so you can remember and think about them later.","zh":"做筆記是指寫下重要重點，以便日後記得和思考。"},{"en":"During feedback, a student may take notes on which scene felt unclear.","zh":"在回饋過程中，學生可能會做筆記，記下哪一幕感覺不清楚。"},{"en":"Taking notes helps people listen calmly instead of arguing immediately.","zh":"做筆記幫助人們冷靜聆聽，而不是立即爭辯。"},{"en":"Notes give creators time to decide what advice to accept later.","zh":"筆記給創作者時間日後決定接受甚麼建議。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"ask follow-up questions","meaning":"追問跟進問題","examples":[{"en":"You should ask follow-up questions after receiving criticism.","zh":"收到批評後，你應該追問跟進問題。"},{"en":"To ask follow-up questions means to ask more questions to understand feedback better.","zh":"追問跟進問題，是指提出更多問題，以更好理解回饋。"},{"en":"A painter may ask follow-up questions such as, “Which colour feels distracting?”","zh":"畫家可能追問跟進問題，例如：「哪種顏色令人分心？」"},{"en":"Follow-up questions help turn vague criticism into useful details.","zh":"跟進問題幫助把含糊批評變成有用細節。"},{"en":"Asking them shows that the creator is listening seriously.","zh":"提出跟進問題顯示創作者正在認真聆聽。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"I hear you","meaning":"我明白你的意思","examples":[{"en":"You might say, “I hear you.”","zh":"你可以說：「我明白你的意思。」"},{"en":"I hear you means I understand that you are making a point, even if I may not fully agree yet.","zh":"「我明白你的意思」是指我理解你正在提出一個觀點，即使我未必已完全同意。"},{"en":"A student may say “I hear you” before asking which part of the essay was unclear.","zh":"學生可能在詢問文章哪一部分不清楚前說：「我明白你的意思。」"},{"en":"This phrase helps keep a feedback conversation calm and respectful.","zh":"這個短語有助令回饋對話保持冷靜和尊重。"},{"en":"It shows listening without promising to accept every comment.","zh":"它顯示聆聽，但不承諾接受每一個意見。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"show me which part","meaning":"指給我看是哪一部分","examples":[{"en":"Could you show me which part felt unclear?","zh":"你可以指給我看是哪一部分感覺不清楚嗎？"},{"en":"Show me which part asks someone to point to the exact place they are talking about.","zh":"指給我看是哪一部分，是請別人指出他們正在談論的確切位置。"},{"en":"A writer may ask, “Can you show me which part of the story lost your attention?”","zh":"作者可能會問：「你可以指給我看故事哪一部分令你失去注意嗎？」"},{"en":"This question helps make criticism specific instead of general.","zh":"這個問題幫助批評變得具體，而不是籠統。"},{"en":"It allows the creator to revise the right section rather than guess.","zh":"它讓創作者能修改正確部分，而不是猜測。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"felt unclear","meaning":"感覺不清楚","examples":[{"en":"Could you show me which part felt unclear?","zh":"你可以指給我看是哪一部分感覺不清楚嗎？"},{"en":"Felt unclear means seemed difficult to understand or follow.","zh":"感覺不清楚是指看似難以理解或跟上。"},{"en":"A film scene felt unclear when viewers did not know why the character left.","zh":"當觀眾不知道角色為何離開時，那一幕電影就感覺不清楚。"},{"en":"If instructions felt unclear, students may complete the task in different ways.","zh":"如果指示感覺不清楚，學生可能會以不同方式完成任務。"},{"en":"This phrase invites explanation without accusing the creator of failure.","zh":"這個短語邀請別人解釋，而不指責創作者失敗。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"I see your point","meaning":"我明白你的觀點","examples":[{"en":"You might say, “I see your point.”","zh":"你可以說：「我明白你的觀點。」"},{"en":"I see your point means I understand your argument or reason.","zh":"「我明白你的觀點」意思是我理解你的論點或原因。"},{"en":"A director may say “I see your point” after hearing that the final scene confused the audience.","zh":"導演聽到最後一幕令觀眾困惑後，可能會說：「我明白你的觀點。」"},{"en":"This phrase shows respect even when the artist may still choose differently.","zh":"這個短語表達尊重，即使藝術家仍可能作不同選擇。"},{"en":"It helps people disagree politely during feedback.","zh":"它幫助人們在回饋中有禮貌地不同意。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"intended the ending to feel unresolved","meaning":"原意是讓結局感覺未解決","examples":[{"en":"I intended the ending to feel unresolved.","zh":"我的原意是讓結局感覺未解決。"},{"en":"Intended the ending to feel unresolved means the creator wanted the conclusion to leave questions open.","zh":"原意是讓結局感覺未解決，是指創作者希望結尾留下未解答的問題。"},{"en":"A writer may intend the ending to feel unresolved so readers keep thinking after the story ends.","zh":"作者可能原意是讓結局感覺未解決，好讓讀者在故事結束後繼續思考。"},{"en":"Explaining this intention helps critics understand that uncertainty may be deliberate.","zh":"解釋這個意圖能幫助批評者理解，不確定性可能是有意安排。"},{"en":"This phrase separates an artistic choice from a careless mistake.","zh":"這個短語把藝術選擇與粗心錯誤分開。"}],"source":"2019 Q7.pdf","sourcePage":10},{"front":"feel unresolved","meaning":"感覺懸而未決","examples":[{"en":"The ending was intended to feel unresolved.","zh":"結局原意是感覺懸而未決。"},{"en":"Feel unresolved means seem unfinished or still open to questions.","zh":"感覺懸而未決，是指看似未完成或仍留有問題。"},{"en":"A play may feel unresolved if the audience never learns whether the family reconciles.","zh":"如果觀眾一直不知道家人是否和好，一齣戲可能感覺懸而未決。"},{"en":"Sometimes an unresolved ending is used to make viewers think more deeply.","zh":"有時懸而未決的結局是用來令觀眾更深入思考。"},{"en":"Critics should ask whether an unresolved feeling is deliberate or accidental.","zh":"批評者應詢問懸而未決的感覺是有意還是無意。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"decide what to accept","meaning":"決定接受甚麼","examples":[{"en":"Then decide what to accept, what to adapt, and what to leave aside.","zh":"然後決定接受甚麼、調整甚麼，以及暫且放下甚麼。"},{"en":"Decide what to accept means choose which feedback you believe is useful and will follow.","zh":"決定接受甚麼，是指選擇哪些回饋你認為有用並會跟隨。"},{"en":"After reading comments, a writer must decide what to accept and what does not fit the story.","zh":"讀完評論後，作者必須決定接受甚麼，以及哪些不符合故事。"},{"en":"This decision helps creators keep ownership while still learning from others.","zh":"這個決定幫助創作者保持作品主導權，同時仍向別人學習。"},{"en":"Mature artists listen carefully before deciding what to accept.","zh":"成熟的藝術家會仔細聆聽，再決定接受甚麼。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"adapt","meaning":"調整","examples":[{"en":"You can decide what to adapt after hearing criticism.","zh":"聽完批評後，你可以決定調整甚麼。"},{"en":"To adapt means to change something so it fits a new purpose, situation, or suggestion.","zh":"調整是指改變某物，使其配合新的目的、情況或建議。"},{"en":"A playwright may adapt a scene after actors say the dialogue feels unnatural.","zh":"當演員說對白感覺不自然時，劇作家可能調整一幕戲。"},{"en":"Artists adapt feedback when they use the idea but keep their own style.","zh":"當藝術家使用建議的想法但保留自己的風格時，就是在調整回饋。"},{"en":"Adapting is different from obeying because the creator still makes the final choice.","zh":"調整不同於服從，因為創作者仍作最後選擇。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"leave aside","meaning":"暫且放下；不採納","examples":[{"en":"You can decide what to leave aside.","zh":"你可以決定暫且放下甚麼。"},{"en":"To leave aside means to choose not to use something for now.","zh":"暫且放下是指暫時選擇不使用某事。"},{"en":"A painter may leave aside a suggestion if it does not match the mood of the work.","zh":"如果一項建議不符合作品氣氛，畫家可能會暫且放下它。"},{"en":"Leaving aside unsuitable criticism helps artists protect their main intention.","zh":"暫且放下不合適的批評，能幫助藝術家保護主要意圖。"},{"en":"This phrase is gentler than saying “ignore” because it allows future reconsideration.","zh":"這個短語比「忽視」溫和，因為它容許日後重新考慮。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"some criticism will be fair","meaning":"有些批評會是公道的","examples":[{"en":"Some criticism will be fair.","zh":"有些批評會是公道的。"},{"en":"Some criticism will be fair means some comments will be reasonable, balanced, and supported by evidence.","zh":"有些批評會是公道的，意思是有些評論會合理、平衡，並有證據支持。"},{"en":"A comment about unclear lighting may be fair if several viewers could not see the actor’s face.","zh":"如果幾位觀眾都看不清演員的臉，關於燈光不清楚的評論可能是公道的。"},{"en":"Fair criticism helps creators improve without attacking them personally.","zh":"公道的批評幫助創作者改善，而不攻擊他們個人。"},{"en":"Artists should learn to recognise fair criticism even when it is uncomfortable.","zh":"藝術家應學會辨認公道的批評，即使它令人不舒服。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"some will be mistaken","meaning":"有些會是錯誤的","examples":[{"en":"Some criticism will be mistaken.","zh":"有些批評會是錯誤的。"},{"en":"Some will be mistaken means some comments may be wrong, unfair, or based on misunderstanding.","zh":"有些會是錯誤的，意思是有些評論可能錯誤、不公平或基於誤解。"},{"en":"A critic may be mistaken if they miss the artist’s intended irony.","zh":"如果批評者沒有看出藝術家有意使用的反諷，他們可能是錯誤的。"},{"en":"Not every comment should be followed because some will be mistaken.","zh":"不是每個意見都應被跟隨，因為有些會是錯誤的。"},{"en":"Creators need judgement to separate helpful criticism from mistaken criticism.","zh":"創作者需要判斷力，把有幫助的批評與錯誤批評分開。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"unkind","meaning":"不友善的","examples":[{"en":"Some criticism may even be unkind.","zh":"有些批評甚至可能是不友善的。"},{"en":"Unkind means lacking care, sympathy, or respect for another person’s feelings.","zh":"不友善的是指缺乏對他人感受的關心、同情或尊重。"},{"en":"Saying “your work is worthless” is unkind because it attacks the person, not the piece.","zh":"說「你的作品毫無價值」是不友善的，因為它攻擊的是人，而不是作品。"},{"en":"Unkind criticism can silence creativity even when it contains a small useful point.","zh":"不友善的批評即使含有一點有用內容，也可能令創意沉默。"},{"en":"Feedback should be honest, but it does not need to be unkind.","zh":"回饋應該誠實，但不需要不友善。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"attack your identity","meaning":"攻擊你的身份","examples":[{"en":"A comment may attack your identity rather than your work.","zh":"一個評論可能攻擊你的身份，而不是你的作品。"},{"en":"To attack your identity means to criticise who you are, such as your background, gender, culture, or personality.","zh":"攻擊你的身份，是指批評你是誰，例如你的背景、性別、文化或性格。"},{"en":"A comment attacks your identity when it mocks your accent instead of reviewing your speech.","zh":"當評論嘲笑你的口音，而不是評論你的演講時，它就是攻擊你的身份。"},{"en":"Such attacks are not useful criticism because they target the person’s selfhood.","zh":"這類攻擊不是有用批評，因為它針對人的自我身份。"},{"en":"Creators have the right to reject comments that attack their identity.","zh":"創作者有權拒絕攻擊其身份的評論。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"rather than your work","meaning":"而不是你的作品","examples":[{"en":"Some comments attack your identity rather than your work.","zh":"有些評論攻擊你的身份，而不是你的作品。"},{"en":"Rather than your work shows that the attack targets the person instead of the creation.","zh":"而不是你的作品，顯示攻擊針對的是人，而不是創作。"},{"en":"If someone mocks your background rather than your work, the comment is unfair.","zh":"如果有人嘲笑你的背景，而不是你的作品，那個評論就是不公平的。"},{"en":"This phrase makes the contrast between personal attack and artistic criticism clear.","zh":"這個短語清楚顯示人身攻擊與藝術批評之間的對比。"},{"en":"Critics should discuss the work rather than the creator’s identity.","zh":"批評者應討論作品，而不是創作者的身份。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"have every right to","meaning":"完全有權","examples":[{"en":"You have every right to draw the line.","zh":"你完全有權劃清界線。"},{"en":"Have every right to means someone is completely allowed or justified to do something.","zh":"完全有權是指某人完全被允許或有充分理由做某事。"},{"en":"You have every right to ask for respectful language during feedback.","zh":"你完全有權在回饋中要求尊重的語言。"},{"en":"Artists have every right to reject comments that become personal attacks.","zh":"藝術家完全有權拒絕變成人身攻擊的評論。"},{"en":"This phrase gives confidence to people who need to protect a boundary.","zh":"這個短語給需要保護界線的人信心。"}],"source":"2019 Q7.pdf","sourcePage":11},{"front":"draw the line","meaning":"劃清界線","examples":[{"en":"You have every right to draw the line when criticism becomes personal.","zh":"當批評變成針對個人時，你完全有權劃清界線。"},{"en":"To draw the line means to set a clear limit on what you will accept.","zh":"劃清界線是指清楚設定你會接受甚麼的限制。"},{"en":"A student may draw the line when classmates laugh at their family instead of discussing the project.","zh":"當同學取笑學生的家庭，而不是討論專題時，學生可能會劃清界線。"},{"en":"Drawing the line protects respectful discussion from becoming abuse.","zh":"劃清界線保護尊重的討論，避免它變成辱罵。"},{"en":"This phrase is useful when kindness and boundaries are both needed.","zh":"當善意和界線都需要時，這個短語很有用。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"harsh voice","meaning":"刺耳的聲音","examples":[{"en":"Do not let one harsh voice silence your creativity.","zh":"不要讓一個刺耳的聲音令你的創意沉默。"},{"en":"A harsh voice is a cruel, severe, or hurtful way of speaking.","zh":"刺耳的聲音是指殘酷、嚴厲或傷人的說話方式。"},{"en":"One harsh voice in a classroom can make a shy student afraid to share again.","zh":"課室中一個刺耳的聲音可以令害羞學生害怕再次分享。"},{"en":"Harsh voices can damage confidence even when the work itself can improve.","zh":"刺耳的聲音可能損害信心，即使作品本身可以改善。"},{"en":"This phrase reminds artists not to let cruelty become the loudest truth.","zh":"這個短語提醒藝術家，不要讓殘酷成為最響亮的真相。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"silence your creativity","meaning":"令你的創意沉默","examples":[{"en":"Do not let one harsh voice silence your creativity.","zh":"不要讓一個刺耳的聲音令你的創意沉默。"},{"en":"To silence your creativity means to make you stop expressing ideas, making art, or taking creative risks.","zh":"令你的創意沉默，是指使你停止表達想法、創作藝術或冒創作風險。"},{"en":"A cruel comment may silence a student’s creativity if it makes them afraid to draw again.","zh":"如果殘酷評論令學生害怕再次畫畫，它可能令學生的創意沉默。"},{"en":"Supportive feedback protects creativity while still helping the work improve.","zh":"支持性的回饋會保護創意，同時仍幫助作品改善。"},{"en":"This phrase warns that bad criticism can stop people from creating.","zh":"這個短語警告我們，差劣批評可以阻止人創作。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"turn cruel reviews into","meaning":"把殘酷評論轉化成……","examples":[{"en":"Taylor Swift turned cruel reviews into a song.","zh":"Taylor Swift 把殘酷評論轉化成一首歌。"},{"en":"To turn cruel reviews into something means to use hurtful criticism as material for a new creation or response.","zh":"把殘酷評論轉化成某物，是指把傷人的批評用作新創作或回應的材料。"},{"en":"A poet may turn cruel reviews into a poem about confidence and survival.","zh":"詩人可能把殘酷評論轉化成一首關於信心和堅持的詩。"},{"en":"Turning cruel reviews into art can help creators regain power over painful comments.","zh":"把殘酷評論轉化成藝術，可以幫助創作者重新掌握痛苦評論的力量。"},{"en":"This phrase shows how negative feedback can become creative fuel.","zh":"這個短語顯示負面回饋可以變成創作燃料。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"in the same spirit","meaning":"本着同樣精神","examples":[{"en":"In the same spirit, we can turn useful criticism into better drafts.","zh":"本着同樣精神，我們可以把有用批評轉化成更好的草稿。"},{"en":"In the same spirit means with the same attitude, purpose, or idea.","zh":"本着同樣精神，是指以相同的態度、目的或想法。"},{"en":"A club may praise brave attempts; in the same spirit, it should also welcome careful revision.","zh":"學會可能讚賞勇敢嘗試；本着同樣精神，它也應歡迎細心修改。"},{"en":"This phrase connects a new suggestion to a previous example or value.","zh":"這個短語把新的建議與之前的例子或價值連接起來。"},{"en":"It helps a speech move smoothly from one idea to a related one.","zh":"它幫助演講由一個想法順暢轉到相關想法。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"turn useful criticism into","meaning":"把有用批評轉化成……","examples":[{"en":"We can turn useful criticism into better drafts and stronger performances.","zh":"我們可以把有用批評轉化成更好的草稿和更有力的表演。"},{"en":"To turn useful criticism into something means to use feedback to create a better result.","zh":"把有用批評轉化成某物，是指使用回饋創造更好的結果。"},{"en":"A writer can turn useful criticism into a clearer ending after readers explain what confused them.","zh":"當讀者解釋令他們困惑的地方後，作者可以把有用批評轉化成更清晰的結尾。"},{"en":"Turning criticism into improvement requires listening, choosing, and revising.","zh":"把批評轉化成改善，需要聆聽、選擇和修改。"},{"en":"This phrase shows criticism as a tool for progress.","zh":"這個短語把批評呈現為進步工具。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"better drafts","meaning":"更好的草稿","examples":[{"en":"Useful criticism can lead to better drafts.","zh":"有用的批評可以帶來更好的草稿。"},{"en":"Better drafts are improved versions of writing, artwork, scripts, or plans.","zh":"更好的草稿是寫作、藝術作品、劇本或計劃的改進版本。"},{"en":"A student creates better drafts when feedback helps them organise ideas more clearly.","zh":"當回饋幫助學生更清楚組織想法時，學生就能創作更好的草稿。"},{"en":"Better drafts usually come after revision, not after the first attempt.","zh":"更好的草稿通常來自修改，而不是第一次嘗試。"},{"en":"This phrase reminds creators that early work can improve through feedback.","zh":"這個短語提醒創作者，早期作品可以透過回饋改善。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"stronger performances","meaning":"更有力的表演","examples":[{"en":"Useful criticism can lead to stronger performances.","zh":"有用的批評可以帶來更有力的表演。"},{"en":"Stronger performances are performances that communicate more clearly and affect the audience more powerfully.","zh":"更有力的表演是指表達更清楚、對觀眾影響更強的表演。"},{"en":"Actors give stronger performances when they understand pacing, emotion, and movement better.","zh":"當演員更好理解節奏、情感和動作時，他們會作出更有力的表演。"},{"en":"Feedback about voice and timing can lead to stronger performances on stage.","zh":"關於聲線和時間配合的回饋可以帶來台上更有力的表演。"},{"en":"This phrase shows that criticism can improve live artistic work.","zh":"這個短語顯示批評可以改善現場藝術作品。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"braver choices","meaning":"更勇敢的選擇","examples":[{"en":"Useful criticism can lead to braver choices.","zh":"有用的批評可以帶來更勇敢的選擇。"},{"en":"Braver choices are decisions that take more creative risk or emotional honesty.","zh":"更勇敢的選擇是指承擔更多創作風險或情感誠實的決定。"},{"en":"A director makes braver choices when she uses silence instead of explaining everything in dialogue.","zh":"當導演使用沉默，而不是用對白解釋一切時，她作出了更勇敢的選擇。"},{"en":"Supportive criticism can encourage artists to make braver choices because they feel safer to experiment.","zh":"支持性的批評可以鼓勵藝術家作出更勇敢的選擇，因為他們感到更安全去實驗。"},{"en":"Braver choices often make art more memorable and personal.","zh":"更勇敢的選擇常令藝術更令人記得和更個人化。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"to conclude","meaning":"總結來說","examples":[{"en":"To conclude, our club should be a workshop, not a courtroom.","zh":"總結來說，我們的學會應是工作坊，而不是法庭。"},{"en":"To conclude introduces the final point or summary of a speech.","zh":"總結來說，用來引出演講的最後觀點或總結。"},{"en":"To conclude, students should give feedback that is honest, specific, and kind.","zh":"總結來說，學生應給出誠實、具體和善意的回饋。"},{"en":"A speaker uses to conclude when moving toward the ending.","zh":"講者在走向結尾時會使用「總結來說」。"},{"en":"This phrase helps the audience recognise the message they should remember.","zh":"這個短語幫助觀眾認出應該記住的信息。"}],"source":"2019 Q7.pdf","sourcePage":12},{"front":"a workshop, not a courtroom","meaning":"工作坊，而不是法庭","examples":[{"en":"Our club should be a workshop, not a courtroom.","zh":"我們的學會應是工作坊，而不是法庭。"},{"en":"A workshop, not a courtroom means a place for improving work, not judging people as guilty.","zh":"工作坊，而不是法庭，是指一個改善作品的地方，而不是判定人有罪的地方。"},{"en":"A writing group should be a workshop, not a courtroom, because members are there to revise, not to shame.","zh":"寫作小組應是工作坊，而不是法庭，因為成員是來修改，而不是來羞辱人的。"},{"en":"This image helps students understand that criticism should build rather than punish.","zh":"這個意象幫助學生理解批評應該建立，而不是懲罰。"},{"en":"It turns the club into a place of practice, care, and growth.","zh":"它把學會變成練習、關懷和成長的地方。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"prove that we are perfect","meaning":"證明自己完美","examples":[{"en":"We are not here to prove that we are perfect.","zh":"我們不是來證明自己完美。"},{"en":"To prove that we are perfect means to show others that we have no faults or weaknesses.","zh":"證明自己完美，是指向別人顯示自己沒有錯處或弱點。"},{"en":"Students should not enter a rehearsal trying to prove that they are perfect.","zh":"學生不應抱着證明自己完美的心態進入排練。"},{"en":"Trying to prove perfection can make people hide mistakes instead of learning from them.","zh":"試圖證明完美可能令人隱藏錯誤，而不是從錯誤中學習。"},{"en":"Creative spaces work better when people accept that improvement is normal.","zh":"當人們接受改善是正常的，創意空間會運作得更好。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"become more thoughtful artists","meaning":"成為更有思想的藝術創作者","examples":[{"en":"We are here to help one another become more thoughtful artists.","zh":"我們在這裡是為了幫助彼此成為更有思想的藝術創作者。"},{"en":"To become more thoughtful artists means to create with deeper care, reflection, and awareness.","zh":"成為更有思想的藝術創作者，是指以更深的關懷、反思和意識進行創作。"},{"en":"Students become more thoughtful artists when they ask why each colour, word, or movement is chosen.","zh":"當學生詢問每種顏色、每個詞語或每個動作為何被選用時，他們會成為更有思想的藝術創作者。"},{"en":"Feedback helps artists become more thoughtful by making them examine their choices.","zh":"回饋透過令藝術家審視自己的選擇，幫助他們變得更有思想。"},{"en":"This phrase values growth in mind and character, not only technical skill.","zh":"這個短語重視思想和品格上的成長，而不只是技巧。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"from today onwards","meaning":"由今天起","examples":[{"en":"From today onwards, let us review each other’s work with care.","zh":"由今天起，讓我們用心評論彼此的作品。"},{"en":"From today onwards means starting today and continuing into the future.","zh":"由今天起，是指從今天開始並延續到未來。"},{"en":"From today onwards, club members should give comments that are specific and kind.","zh":"由今天起，學會成員應提出具體而善意的評論。"},{"en":"This phrase marks a clear change in behaviour or attitude.","zh":"這個短語標示行為或態度上的清晰改變。"},{"en":"It is useful in speeches when asking people to begin a new habit.","zh":"在演講中要求人們開始新習慣時，這個短語很有用。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"let us remember","meaning":"讓我們記住","examples":[{"en":"Let us remember three promises.","zh":"讓我們記住三個承諾。"},{"en":"Let us remember is used to ask a group to keep an important idea in mind.","zh":"讓我們記住，是用來請一群人把重要想法放在心上。"},{"en":"Let us remember that criticism should help the artist, not embarrass them.","zh":"讓我們記住，批評應幫助藝術家，而不是令他們尷尬。"},{"en":"A speaker uses this phrase to make the audience focus on key principles.","zh":"講者使用這個短語，讓觀眾集中於關鍵原則。"},{"en":"It sounds formal, inclusive, and encouraging.","zh":"它聽起來正式、具包容性並令人鼓舞。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"be observant","meaning":"善於觀察","examples":[{"en":"When we review each other’s work, we should be observant.","zh":"當我們評論彼此的作品時，應該善於觀察。"},{"en":"To be observant means to notice details carefully.","zh":"善於觀察是指仔細注意細節。"},{"en":"An observant critic may notice that the lighting changes when the character becomes afraid.","zh":"善於觀察的批評者可能注意到角色變得害怕時燈光改變。"},{"en":"Being observant helps feedback become evidence-based rather than vague.","zh":"善於觀察能幫助回饋變得有證據支持，而不是含糊。"},{"en":"Good artists and good critics both need observant eyes.","zh":"好藝術家和好批評者都需要善於觀察的眼睛。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"be specific","meaning":"具體","examples":[{"en":"When we criticise, we should be specific.","zh":"當我們批評時，應該具體。"},{"en":"To be specific means to give clear details instead of general comments.","zh":"具體是指給出清楚細節，而不是籠統評論。"},{"en":"Saying “the final paragraph repeats the same idea” is more specific than saying “this is bad.”","zh":"說「最後一段重複同一個想法」比說「這很差」更具體。"},{"en":"Specific feedback helps the creator know exactly what to improve.","zh":"具體回饋幫助創作者確切知道要改善甚麼。"},{"en":"Being specific makes criticism fairer and more useful.","zh":"具體能令批評更公平和更有用。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"be humane","meaning":"有人情味；仁厚","examples":[{"en":"When we criticise, we should be humane.","zh":"當我們批評時，應該有人情味。"},{"en":"To be humane means to treat people with compassion, dignity, and care.","zh":"有人情味是指以同情、尊嚴和關懷對待別人。"},{"en":"A humane critic can be honest about a weak scene without humiliating the actor.","zh":"有人情味的批評者可以誠實指出一幕戲較弱，而不羞辱演員。"},{"en":"Humane criticism protects the person while improving the work.","zh":"有人情味的批評會保護人，同時改善作品。"},{"en":"This phrase reminds us that art is made by real people with real feelings.","zh":"這個短語提醒我們，藝術是由有真實感受的人創作的。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"no longer feel like","meaning":"不再感覺像","examples":[{"en":"Criticism will no longer feel like an attack.","zh":"批評將不再感覺像攻擊。"},{"en":"No longer feel like means stop seeming or feeling like something it once felt like.","zh":"不再感覺像，是指不再像以前那樣看似或感覺像某事。"},{"en":"Feedback will no longer feel like punishment when teachers explain how to improve.","zh":"當老師解釋如何改善時，回饋將不再感覺像懲罰。"},{"en":"A club no longer feels frightening when members treat mistakes as part of learning.","zh":"當成員把錯誤視為學習一部分時，學會不再感覺可怕。"},{"en":"This phrase shows a change in emotional experience.","zh":"這個短語顯示情感經驗上的改變。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"feel like an attack","meaning":"感覺像攻擊","examples":[{"en":"Bad criticism can feel like an attack.","zh":"差劣批評可能感覺像攻擊。"},{"en":"Feel like an attack means seem personal, hurtful, or threatening rather than helpful.","zh":"感覺像攻擊，是指看似針對個人、傷人或具威脅性，而不是有幫助。"},{"en":"A comment feels like an attack when it says “you are talentless” instead of naming a problem in the work.","zh":"當評論說「你沒有才華」，而不是指出作品中的問題時，它就感覺像攻擊。"},{"en":"If feedback feels like an attack, the creator may stop listening.","zh":"如果回饋感覺像攻擊，創作者可能停止聆聽。"},{"en":"Good critics avoid language that makes advice feel like an attack.","zh":"好的批評者會避免令建議感覺像攻擊的語言。"}],"source":"2019 Q7.pdf","sourcePage":13},{"front":"one of the best tools","meaning":"最好的工具之一","examples":[{"en":"Criticism can become one of the best tools we have.","zh":"批評可以成為我們擁有的最好工具之一。"},{"en":"One of the best tools means one of the most useful ways to achieve a purpose.","zh":"最好的工具之一，是指達成某個目的的最有用方法之一。"},{"en":"Careful feedback is one of the best tools for improving a first draft.","zh":"細心回饋是改善初稿的最好工具之一。"},{"en":"Criticism becomes one of the best tools when it is honest, specific, and kind.","zh":"當批評誠實、具體和善意時，它會成為最好的工具之一。"},{"en":"This phrase presents criticism as something helpful rather than frightening.","zh":"這個短語把批評呈現為有幫助，而不是可怕的東西。"}],"source":"2019 Q7.pdf","sourcePage":14},{"front":"turn effort into excellence","meaning":"把努力轉化為卓越","examples":[{"en":"Criticism can help us turn effort into excellence.","zh":"批評可以幫助我們把努力轉化為卓越。"},{"en":"To turn effort into excellence means to change hard work into high-quality results through guidance and improvement.","zh":"把努力轉化為卓越，是指透過指導和改善，把辛勤付出變成高質素成果。"},{"en":"A dancer turns effort into excellence by practising, receiving feedback, and refining each movement.","zh":"舞者透過練習、接受回饋和精修每個動作，把努力轉化為卓越。"},{"en":"Effort alone may not create excellence if people do not know what to improve.","zh":"如果人們不知道要改善甚麼，單靠努力未必能創造卓越。"},{"en":"This phrase shows criticism as a bridge between trying hard and doing well.","zh":"這個短語把批評呈現為努力嘗試與表現出色之間的橋樑。"}],"source":"2019 Q7.pdf","sourcePage":14},{"front":"thank you","meaning":"多謝","examples":[{"en":"Thank you.","zh":"多謝。"},{"en":"Thank you is a polite expression used to show gratitude or close a speech respectfully.","zh":"多謝是用來表達感謝或禮貌結束演講的說法。"},{"en":"A speaker may say “Thank you” after finishing a presentation to acknowledge the audience.","zh":"講者完成匯報後，可能會說「多謝」來感謝觀眾。"},{"en":"Saying thank you at the end of a speech shows respect for the listeners’ time.","zh":"在演講結尾說多謝，表示尊重聽眾的時間。"},{"en":"It is simple, but it gives a formal ending a polite tone.","zh":"它很簡單，但能令正式結尾帶有禮貌語氣。"}],"source":"2019 Q7.pdf","sourcePage":14}],"dse/writing/part-b/2019/Q8":[{"front":"making room at","meaning":"為……騰出位置","examples":[{"en":"The proposal is about making room at the Games for Dragon Boat Racing.","zh":"這項建議是關於在運動會中為龍舟競渡騰出位置。"},{"en":"Making room at an event means creating space in the programme for something new.","zh":"在活動中為某事騰出位置，意思是在節目安排中加入新的項目。"},{"en":"A school may make room at sports day for a new relay race.","zh":"學校可能在運動會中為新的接力賽騰出位置。"},{"en":"If the Games make room for Dragon Boat Racing, more Asian sporting traditions can be seen.","zh":"如果運動會為龍舟競渡騰出位置，更多亞洲體育傳統便能被看見。"},{"en":"Making room at a major event usually means changing the schedule, budget, or venue plan.","zh":"在大型活動中騰出位置，通常意味著要改動時間表、預算或場地安排。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"a proposal to include","meaning":"建議納入……","examples":[{"en":"This is a proposal to include Dragon Boat Racing.","zh":"這是一項建議納入龍舟競渡的提案。"},{"en":"A proposal to include something is a formal suggestion that it should be added.","zh":"建議納入某事，是正式提出應把某事加入。"},{"en":"Students may write a proposal to include more music activities in school.","zh":"學生可能寫一份建議納入更多音樂活動的提案。"},{"en":"A proposal to include a new sport must explain why it is suitable.","zh":"建議納入一項新運動時，必須解釋它為何合適。"},{"en":"Good proposals to include something usually give reasons, benefits, and practical details.","zh":"好的納入建議通常會提出理由、好處和實際細節。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"Dear Members of","meaning":"各位……成員","examples":[{"en":"The letter begins with Dear Members of the Council Election Committee.","zh":"這封信以「各位選舉委員會成員」開始。"},{"en":"Dear Members of is a formal opening used when writing to a group of people.","zh":"Dear Members of 是寫給一群人時使用的正式開首語。"},{"en":"A student may write “Dear Members of the School Board” in a formal letter.","zh":"學生可能在正式信件中寫 “Dear Members of the School Board”。"},{"en":"This opening is useful when the writer does not address only one person.","zh":"當作者不是只寫給一個人時，這個開首語很有用。"},{"en":"Using “Dear Members of” makes the letter sound respectful and official.","zh":"使用 “Dear Members of” 令信件聽起來尊重而正式。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"the Council Election Committee","meaning":"選舉委員會","examples":[{"en":"The proposal is addressed to the Council Election Committee.","zh":"這項建議是寫給選舉委員會的。"},{"en":"The Council Election Committee is the group responsible for handling matters about the council election.","zh":"選舉委員會是負責處理區議會選舉相關事宜的組織。"},{"en":"A candidate may send poster designs to the Council Election Committee for review.","zh":"候選人可能把海報設計交給選舉委員會審視。"},{"en":"If the committee approves the materials, the campaign can use them officially.","zh":"如果委員會批准材料，競選團隊便可以正式使用。"},{"en":"Writing to the correct committee helps the proposal reach the people who can decide.","zh":"寫給正確的委員會，有助建議到達能作決定的人手上。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"in the run-up to","meaning":"在……前夕","examples":[{"en":"In the run-up to the council election, the posters should communicate Ricky Kwan’s message clearly.","zh":"在區議會選舉前夕，海報應清楚傳達關偉基的訊息。"},{"en":"In the run-up to an event means during the period shortly before it happens.","zh":"in the run-up to 某活動，意思是在該活動即將發生前的一段時間。"},{"en":"In the run-up to exams, students often review past papers.","zh":"在考試前夕，學生通常會溫習歷年試題。"},{"en":"In the run-up to an election, candidates try to make their message memorable.","zh":"在選舉前夕，候選人會努力令自己的訊息令人記得。"},{"en":"This phrase helps explain why preparation is important before a major event.","zh":"這個片語有助解釋為何大型活動前的準備很重要。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"council election","meaning":"區議會選舉","examples":[{"en":"The posters are designed for the council election.","zh":"這些海報是為區議會選舉而設計的。"},{"en":"A council election is an election in which residents choose local representatives.","zh":"區議會選舉是居民選出地區代表的選舉。"},{"en":"During a council election, candidates explain how they will serve the district.","zh":"在區議會選舉期間，候選人會解釋自己將如何服務社區。"},{"en":"A clear campaign message can help voters understand a candidate in a council election.","zh":"清晰的競選訊息可幫助選民在區議會選舉中理解候選人。"},{"en":"Council elections matter because local decisions affect daily community life.","zh":"區議會選舉很重要，因為地區決定會影響日常社區生活。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"should be more than","meaning":"應該不只是……","examples":[{"en":"The posters should be more than attractive decoration.","zh":"這些海報應該不只是好看的裝飾。"},{"en":"Should be more than means something should have a deeper purpose, not only a simple surface function.","zh":"should be more than 意思是某物應有更深目的，而不只是表面功能。"},{"en":"A school notice should be more than colourful paper; it should give clear information.","zh":"學校告示應該不只是彩色紙張；它應提供清晰資訊。"},{"en":"Campaign posters should be more than beautiful images because voters need a message.","zh":"競選海報應該不只是漂亮圖像，因為選民需要訊息。"},{"en":"This phrase helps show that appearance alone is not enough.","zh":"這個片語有助表明外觀本身並不足夠。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"attractive decoration","meaning":"好看的裝飾","examples":[{"en":"Election posters should be more than attractive decoration.","zh":"選舉海報應該不只是好看的裝飾。"},{"en":"Attractive decoration means something that looks pleasant but may not communicate much meaning.","zh":"好看的裝飾指外表悅目，但未必傳達很多意思的東西。"},{"en":"Balloons can be attractive decoration at a party, but they do not explain the event.","zh":"氣球可以是派對上的好看裝飾，但它們不會解釋活動內容。"},{"en":"If a poster is only attractive decoration, voters may forget its message quickly.","zh":"如果海報只是好看的裝飾，選民可能很快忘記它的訊息。"},{"en":"A strong poster should look good and say something important.","zh":"有力的海報應該既好看，也說出重要內容。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"tell residents","meaning":"告訴居民","examples":[{"en":"The posters should tell residents what kind of representative Ricky hopes to become.","zh":"這些海報應告訴居民關偉基希望成為甚麼樣的代表。"},{"en":"To tell residents means to communicate clearly with people who live in the district.","zh":"告訴居民意思是清楚地向住在該區的人傳達資訊。"},{"en":"A notice can tell residents when road repairs will begin.","zh":"告示可以告訴居民道路維修何時開始。"},{"en":"Campaign posters tell residents what problems the candidate wants to solve.","zh":"競選海報告訴居民候選人想解決甚麼問題。"},{"en":"Clear communication helps residents make informed choices.","zh":"清晰溝通幫助居民作出知情選擇。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"what kind of representative","meaning":"甚麼樣的代表","examples":[{"en":"The posters show what kind of representative Ricky hopes to become.","zh":"這些海報展示關偉基希望成為甚麼樣的代表。"},{"en":"What kind of representative means the type of public servant a candidate wants to be.","zh":"甚麼樣的代表指候選人希望成為哪一類公職服務者。"},{"en":"Voters want to know what kind of representative will listen to their problems.","zh":"選民想知道甚麼樣的代表會聆聽他們的問題。"},{"en":"A poster can show whether a candidate is caring, practical, or creative.","zh":"海報可以顯示候選人是否關懷、實際或有創意。"},{"en":"This phrase focuses on character, not only election promises.","zh":"這個片語著重人物特質，而不只是選舉承諾。"}],"source":"2019 Q8.pdf","sourcePage":1},{"front":"hopes to become","meaning":"希望成為","examples":[{"en":"The posters show what kind of representative he hopes to become.","zh":"這些海報展示他希望成為甚麼樣的代表。"},{"en":"Hopes to become means wants to develop into a certain role or type of person.","zh":"希望成為意思是想發展成某個角色或某類人。"},{"en":"A student may hope to become a doctor who helps poor communities.","zh":"學生可能希望成為幫助貧困社區的醫生。"},{"en":"A candidate who hopes to become a good representative must earn public trust.","zh":"希望成為好代表的候選人必須贏得公眾信任。"},{"en":"This phrase suggests ambition, direction, and future responsibility.","zh":"這個片語帶有抱負、方向和未來責任的意思。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"with this in mind","meaning":"考慮到這一點","examples":[{"en":"With this in mind, I have designed Posters A and B around three connected ideas.","zh":"考慮到這一點，我圍繞三個互相關連的理念設計了海報 A 和 B。"},{"en":"With this in mind means considering the point just mentioned.","zh":"with this in mind 意思是考慮剛才提到的一點。"},{"en":"With this in mind, the teacher prepared easier examples for weaker students.","zh":"考慮到這一點，老師為能力較弱的學生準備了較容易的例子。"},{"en":"With this in mind, the campaign posters focus on trust, ideas, and action.","zh":"考慮到這一點，競選海報集中於信任、理念和行動。"},{"en":"This phrase helps connect a reason to the next decision.","zh":"這個片語有助把理由連接到下一個決定。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"design something around","meaning":"圍繞……設計某物","examples":[{"en":"I have designed Posters A and B around three connected ideas.","zh":"我圍繞三個互相關連的理念設計了海報 A 和 B。"},{"en":"To design something around an idea means to make that idea the centre of the design.","zh":"圍繞某理念設計某物，意思是把該理念作為設計核心。"},{"en":"A museum may design an exhibition around family memories.","zh":"博物館可能圍繞家庭回憶設計展覽。"},{"en":"If a poster is designed around listening, its words and images should support that message.","zh":"如果海報圍繞聆聽設計，其文字和圖像都應支持這個訊息。"},{"en":"Good design feels clearer when it is built around one main idea.","zh":"當設計圍繞一個主要理念建立時，會感覺更清晰。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"three connected ideas","meaning":"三個互相關連的理念","examples":[{"en":"The posters are designed around three connected ideas.","zh":"這些海報圍繞三個互相關連的理念設計。"},{"en":"Three connected ideas are three points that support one another instead of standing separately.","zh":"三個互相關連的理念是三個互相支持、而不是各自獨立的重點。"},{"en":"A school campaign may use three connected ideas: health, exercise, and sleep.","zh":"學校宣傳活動可能使用三個互相關連的理念：健康、運動和睡眠。"},{"en":"Connected ideas make a campaign easier to remember because the message feels organised.","zh":"互相關連的理念令宣傳更容易記得，因為訊息感覺有組織。"},{"en":"In this proposal, listening, connection, and action work together as one theme.","zh":"在這項建議中，聆聽、連繫和行動共同形成一個主題。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"listening, connection and creative action","meaning":"聆聽、連繫和創意行動","examples":[{"en":"The campaign theme is based on listening, connection and creative action.","zh":"競選主題建基於聆聽、連繫和創意行動。"},{"en":"Listening, connection and creative action mean hearing residents, building relationships, and finding practical new solutions.","zh":"聆聽、連繫和創意行動意思是聽取居民意見、建立關係，並尋找實際的新解決方案。"},{"en":"A community project needs listening before it can create real connection.","zh":"社區項目需要先聆聽，才能建立真正連繫。"},{"en":"Creative action turns residents’ concerns into steps that can improve the district.","zh":"創意行動把居民的關注變成能改善地區的步驟。"},{"en":"These three ideas show that Ricky wants to understand people before acting.","zh":"這三個理念顯示關偉基希望先理解居民，再採取行動。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"my recommendation is that","meaning":"我的建議是","examples":[{"en":"My recommendation is that the posters should form a campaign theme.","zh":"我的建議是這些海報應形成一個競選主題。"},{"en":"My recommendation is that is a formal way to introduce advice.","zh":"my recommendation is that 是正式提出建議的說法。"},{"en":"My recommendation is that the school should test the new timetable first.","zh":"我的建議是學校應先測試新時間表。"},{"en":"In a proposal, this phrase helps the writer state the main suggestion clearly.","zh":"在建議書中，這個片語幫助作者清楚提出主要建議。"},{"en":"It sounds more professional than simply saying “I think we should”.","zh":"它比簡單說 “I think we should” 聽起來更專業。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"form a campaign theme","meaning":"形成一個競選主題","examples":[{"en":"The posters should form a campaign theme called “From Concern to Solution”.","zh":"這些海報應形成一個名為「由關注到解決方案」的競選主題。"},{"en":"To form a campaign theme means to create one clear message across different campaign materials.","zh":"形成一個競選主題意思是在不同競選材料中建立一個清晰訊息。"},{"en":"Three posters can form a campaign theme if they share colours, slogans, and ideas.","zh":"如果三張海報共享顏色、口號和理念，它們便可形成一個競選主題。"},{"en":"A strong campaign theme helps voters connect separate posters into one story.","zh":"有力的競選主題幫助選民把不同海報連成一個故事。"},{"en":"Without a campaign theme, the posters may look unrelated.","zh":"沒有競選主題，海報可能看起來互不相關。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"From Concern to Solution","meaning":"由關注到解決方案","examples":[{"en":"The campaign theme could be called “From Concern to Solution”.","zh":"競選主題可以稱為「由關注到解決方案」。"},{"en":"“From Concern to Solution” means moving from noticing problems to solving them.","zh":"「由關注到解決方案」意思是由注意問題走向解決問題。"},{"en":"A resident’s complaint about street lights can move from concern to solution if the council acts.","zh":"如果議會採取行動，居民對街燈的投訴便可以由關注走向解決方案。"},{"en":"This theme suggests that Ricky will not only listen but also respond practically.","zh":"這個主題表示關偉基不只會聆聽，也會作出實際回應。"},{"en":"The phrase gives the campaign a simple journey voters can understand.","zh":"這個片語為競選提供一段選民容易理解的簡單歷程。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"complete the sequence","meaning":"完成這個系列","examples":[{"en":"Poster C would complete the sequence.","zh":"海報 C 會完成這個系列。"},{"en":"To complete the sequence means to finish a set by adding the final part.","zh":"完成這個系列意思是加入最後部分，使整套內容完整。"},{"en":"A third lesson can complete the sequence after students learn the first two steps.","zh":"學生學完前兩個步驟後，第三課可以完成這個系列。"},{"en":"Poster C completes the sequence by showing what happens after listening and thinking.","zh":"海報 C 透過展示聆聽和思考之後會發生甚麼來完成這個系列。"},{"en":"A complete sequence helps the audience follow the campaign’s logic.","zh":"完整系列幫助觀眾理解競選的邏輯。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"residents’ voices","meaning":"居民的聲音","examples":[{"en":"Poster C shows how residents’ voices can become practical improvement.","zh":"海報 C 展示居民的聲音如何變成實際改善。"},{"en":"Residents’ voices means the opinions, needs, complaints, and suggestions of people in the district.","zh":"居民的聲音指區內居民的意見、需要、投訴和建議。"},{"en":"Residents’ voices may include concerns about transport, hygiene, or elderly care.","zh":"居民的聲音可能包括對交通、衞生或長者照顧的關注。"},{"en":"When leaders listen to residents’ voices, policies can become more relevant.","zh":"當領袖聆聽居民的聲音，政策便能更切合需要。"},{"en":"This phrase suggests that ordinary people should influence public decisions.","zh":"這個片語表示普通人應能影響公共決定。"}],"source":"2019 Q8.pdf","sourcePage":2},{"front":"practical improvement","meaning":"實際改善","examples":[{"en":"Residents’ voices can become practical improvement.","zh":"居民的聲音可以變成實際改善。"},{"en":"Practical improvement means real changes that make daily life better.","zh":"實際改善指真正令日常生活變好的改變。"},{"en":"Fixing broken street lights is a practical improvement for a neighbourhood.","zh":"修理損壞街燈是社區的實際改善。"},{"en":"If residents report problems clearly, the council can turn complaints into practical improvement.","zh":"如果居民清楚通報問題，議會便能把投訴變成實際改善。"},{"en":"Practical improvement is different from empty talk because people can see the result.","zh":"實際改善不同於空談，因為人們可以看到結果。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"be built around","meaning":"以……為核心設計","examples":[{"en":"Poster A is built around the image of two people shaking hands.","zh":"海報 A 以兩個人握手的圖像為核心設計。"},{"en":"Be built around means be designed with one main image, idea, or purpose at the centre.","zh":"be built around 意思是以一個主要圖像、理念或目的作中心來設計。"},{"en":"A lesson may be built around one real-life problem so students understand better.","zh":"課堂可以以一個真實生活問題為核心設計，讓學生更易理解。"},{"en":"If a poster is built around a handshake, the design naturally suggests trust.","zh":"如果海報以握手為核心設計，設計自然會象徵信任。"},{"en":"This phrase shows what holds the whole design together.","zh":"這個片語顯示整個設計由甚麼連繫起來。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"shaking hands","meaning":"握手","examples":[{"en":"Poster A shows two people shaking hands across a gap.","zh":"海報 A 顯示兩個人跨越一道距離握手。"},{"en":"Shaking hands is the action of holding another person’s hand as a greeting or sign of agreement.","zh":"握手是握住另一個人的手，作為問候或達成共識的表示。"},{"en":"Two neighbours may shake hands after solving a disagreement.","zh":"兩位鄰居解決分歧後可能會握手。"},{"en":"In a campaign poster, shaking hands can suggest cooperation and trust.","zh":"在競選海報中，握手可以象徵合作和信任。"},{"en":"This image is simple because people quickly understand its meaning.","zh":"這個圖像簡單，因為人們很快明白其意思。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"across a gap","meaning":"跨越一道距離","examples":[{"en":"The image shows two people shaking hands across a gap.","zh":"這個圖像顯示兩個人跨越一道距離握手。"},{"en":"Across a gap means from one side of a space or divide to the other side.","zh":"across a gap 意思是從一道空隙或分隔的一邊到另一邊。"},{"en":"A bridge helps people walk across a gap between two roads.","zh":"橋樑幫助人們跨越兩條道路之間的距離。"},{"en":"Shaking hands across a gap suggests that distance can be overcome.","zh":"跨越距離握手表示距離是可以克服的。"},{"en":"In the poster, the gap can represent separation between residents and public bodies.","zh":"在海報中，這道距離可以代表居民與公共機構之間的隔閡。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"placed above","meaning":"放在……上方","examples":[{"en":"A bridge is placed above the two figures.","zh":"一道橋放在兩個人物上方。"},{"en":"Placed above means put in a higher position than something else.","zh":"placed above 意思是放在比另一物更高的位置。"},{"en":"A title is often placed above a picture so readers see it first.","zh":"標題通常放在圖片上方，讓讀者先看到。"},{"en":"If the bridge is placed above the figures, it may suggest a way forward.","zh":"如果橋放在人物上方，它可能象徵前路。"},{"en":"Placement affects how viewers understand the relationship between images.","zh":"位置安排會影響觀眾如何理解圖像之間的關係。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, Poster A is warm and simple.","zh":"乍看之下，海報 A 溫暖而簡單。"},{"en":"At first glance means when something is first seen, before careful study.","zh":"at first glance 意思是初次看見某物、尚未仔細研究時。"},{"en":"At first glance, the poster looks like a friendly picture of cooperation.","zh":"乍看之下，這張海報像是一幅友善合作的圖像。"},{"en":"A design may look simple at first glance but carry deeper meaning later.","zh":"設計乍看之下可能簡單，但之後會帶出更深意思。"},{"en":"This phrase prepares the reader to look more carefully afterwards.","zh":"這個片語讓讀者準備之後更仔細觀察。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"on closer inspection","meaning":"仔細一看","examples":[{"en":"On closer inspection, Poster A carries a clear message.","zh":"仔細一看，海報 A 傳達清晰訊息。"},{"en":"On closer inspection means after looking at something more carefully.","zh":"on closer inspection 意思是更仔細查看某物之後。"},{"en":"On closer inspection, the small bridge in the poster becomes important.","zh":"仔細一看，海報中的小橋變得重要。"},{"en":"A campaign image may seem decorative, but on closer inspection it may show a political idea.","zh":"競選圖像可能看似裝飾，但仔細一看可能展示政治理念。"},{"en":"This phrase is useful when explaining hidden or deeper meaning.","zh":"這個片語適合用來解釋隱藏或更深層意思。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"carry a clear message","meaning":"傳達清晰訊息","examples":[{"en":"Poster A carries a clear message.","zh":"海報 A 傳達清晰訊息。"},{"en":"To carry a clear message means to communicate an idea in a way people can easily understand.","zh":"傳達清晰訊息意思是以人們容易明白的方式表達理念。"},{"en":"A road safety poster carries a clear message when drivers know exactly what to do.","zh":"道路安全海報若能令司機清楚知道該怎樣做，便是傳達清晰訊息。"},{"en":"If a campaign poster carries a clear message, voters remember it more easily.","zh":"如果競選海報傳達清晰訊息，選民會更容易記得。"},{"en":"Images, colours, and slogans should work together to carry a clear message.","zh":"圖像、顏色和口號應共同傳達清晰訊息。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"directly invite someone to","meaning":"直接邀請某人去……","examples":[{"en":"The question directly invites residents to speak.","zh":"這個問題直接邀請居民發聲。"},{"en":"To directly invite someone to do something means to ask them clearly and openly to take action.","zh":"直接邀請某人去做某事，意思是清楚而公開地請他們採取行動。"},{"en":"A teacher may directly invite quiet students to share their views.","zh":"老師可能直接邀請安靜的學生分享看法。"},{"en":"A poster directly invites residents to speak when it asks, “What do you need?”","zh":"當海報問「你需要甚麼？」時，就是直接邀請居民發聲。"},{"en":"Direct invitation can make people feel included rather than ignored.","zh":"直接邀請可以令人感到被包括，而不是被忽視。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"suggest a community activity","meaning":"建議社區活動","examples":[{"en":"Residents may wish to suggest a community activity.","zh":"居民可能希望建議社區活動。"},{"en":"To suggest a community activity means to propose an event or programme for local people.","zh":"建議社區活動意思是提出給本地居民參與的活動或計劃。"},{"en":"A resident may suggest a community activity such as a clean-up day.","zh":"居民可能建議清潔日等社區活動。"},{"en":"Community activities can bring neighbours together and reduce distance between generations.","zh":"社區活動可以把鄰里連繫起來，減少年齡層之間的距離。"},{"en":"Asking residents to suggest activities shows that their ideas matter.","zh":"邀請居民建議活動，顯示他們的想法很重要。"}],"source":"2019 Q8.pdf","sourcePage":3},{"front":"complain about","meaning":"投訴……","examples":[{"en":"Residents may complain about a damaged pavement.","zh":"居民可能投訴損壞的行人路。"},{"en":"To complain about something means to say that it is wrong, unfair, broken, or unsatisfactory.","zh":"投訴某事意思是指出它錯誤、不公平、損壞或令人不滿。"},{"en":"A customer may complain about late delivery.","zh":"顧客可能投訴送貨遲。"},{"en":"Residents complain about problems so public bodies know what needs fixing.","zh":"居民投訴問題，讓公共機構知道甚麼需要修理。"},{"en":"Complaints should not be ignored because they can point to real community needs.","zh":"投訴不應被忽視，因為它們可能指出真正的社區需要。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"a damaged pavement","meaning":"損壞的行人路","examples":[{"en":"Residents may complain about a damaged pavement.","zh":"居民可能投訴損壞的行人路。"},{"en":"A damaged pavement is a footpath that is cracked, uneven, broken, or unsafe to walk on.","zh":"損壞的行人路是裂開、不平、破損或不安全的步行道路。"},{"en":"Elderly residents may fall if a damaged pavement is not repaired.","zh":"如果損壞的行人路沒有維修，長者可能跌倒。"},{"en":"A damaged pavement can turn a small street problem into a safety concern.","zh":"損壞的行人路可以把小街道問題變成安全隱患。"},{"en":"Reporting damaged pavements helps the district become safer for everyone.","zh":"通報損壞的行人路有助令社區對所有人更安全。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"raise concerns about","meaning":"提出對……的關注","examples":[{"en":"Residents may raise concerns about hygiene, transport or elderly care.","zh":"居民可能提出對衞生、交通或長者照顧的關注。"},{"en":"To raise concerns about something means to express worries so they can be discussed.","zh":"提出對某事的關注意思是表達憂慮，好讓問題可以被討論。"},{"en":"Parents may raise concerns about school bus safety.","zh":"家長可能提出對校巴安全的關注。"},{"en":"If residents raise concerns early, the council can respond before problems worsen.","zh":"如果居民及早提出關注，議會便可在問題惡化前回應。"},{"en":"This phrase sounds more formal than simply saying “complain about”.","zh":"這個片語比簡單說「投訴」更正式。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"hygiene","meaning":"衞生","examples":[{"en":"Residents may raise concerns about hygiene.","zh":"居民可能提出對衞生的關注。"},{"en":"Hygiene means cleanliness that helps protect health and prevent disease.","zh":"衞生指有助保障健康和預防疾病的清潔狀況。"},{"en":"Public toilets need good hygiene so residents can use them safely.","zh":"公廁需要良好衞生，讓居民可以安全使用。"},{"en":"Poor hygiene in markets can attract pests and cause health complaints.","zh":"街市衞生差可能吸引害蟲並引起健康投訴。"},{"en":"Hygiene is a local issue because clean public spaces affect everyone.","zh":"衞生是地區議題，因為清潔的公共空間影響每個人。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"elderly care","meaning":"長者照顧","examples":[{"en":"Residents may raise concerns about elderly care.","zh":"居民可能提出對長者照顧的關注。"},{"en":"Elderly care is support for older people, such as health services, home help, and safe facilities.","zh":"長者照顧是給年長人士的支援，例如醫療服務、家居協助和安全設施。"},{"en":"A community centre may provide elderly care through meal delivery and exercise classes.","zh":"社區中心可透過送飯和運動班提供長者照顧。"},{"en":"If elderly care is weak, older residents may become isolated or unsafe.","zh":"如果長者照顧不足，年長居民可能變得孤立或不安全。"},{"en":"Good elderly care shows that a district values its older generation.","zh":"良好的長者照顧顯示社區重視年長一代。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"symbolise the distance","meaning":"象徵距離","examples":[{"en":"The gap between the two figures symbolises the distance between residents and public bodies.","zh":"兩個人物之間的空隙象徵居民與公共機構之間的距離。"},{"en":"To symbolise the distance means to use an image to represent separation or lack of connection.","zh":"象徵距離意思是用圖像代表分隔或缺乏連繫。"},{"en":"A closed door may symbolise the distance between leaders and citizens.","zh":"一道關上的門可能象徵領袖與市民之間的距離。"},{"en":"In Poster A, the gap symbolises a problem that cooperation can solve.","zh":"在海報 A 中，空隙象徵一個合作可以解決的問題。"},{"en":"Symbols help viewers understand abstract ideas through simple pictures.","zh":"象徵能幫助觀眾透過簡單圖像理解抽象概念。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"public bodies","meaning":"公共機構","examples":[{"en":"The poster reflects the distance that can exist between residents and public bodies.","zh":"這張海報反映居民與公共機構之間可能存在的距離。"},{"en":"Public bodies are organisations that provide public services or make decisions for the community.","zh":"公共機構是提供公共服務或為社區作決定的組織。"},{"en":"A transport department and a district council can be public bodies.","zh":"運輸部門和區議會都可以是公共機構。"},{"en":"Residents may feel distant from public bodies if complaints receive no reply.","zh":"如果投訴沒有回覆，居民可能覺得與公共機構有距離。"},{"en":"Good representatives help connect residents with public bodies.","zh":"好代表會幫助居民與公共機構建立連繫。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"younger and older generations","meaning":"年輕一代和年長一代","examples":[{"en":"The gap may also represent the distance between younger and older generations.","zh":"這道距離也可以代表年輕一代和年長一代之間的距離。"},{"en":"Younger and older generations are people from different age groups, such as youths and elderly residents.","zh":"年輕一代和年長一代是不同年齡層的人，例如青少年和長者居民。"},{"en":"A community garden can bring younger and older generations together.","zh":"社區花園可以把年輕一代和年長一代連繫起來。"},{"en":"If generations rarely speak, misunderstandings may grow between them.","zh":"如果不同世代很少交談，彼此之間的誤解可能增加。"},{"en":"Shared activities help different generations learn from one another.","zh":"共同活動幫助不同世代互相學習。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"complaints and solutions","meaning":"投訴與解決方案","examples":[{"en":"The gap symbolises the distance between complaints and solutions.","zh":"這道距離象徵投訴與解決方案之間的距離。"},{"en":"Complaints and solutions are the problems people raise and the actions that fix them.","zh":"投訴與解決方案是人們提出的問題和修正問題的行動。"},{"en":"A complaint about traffic noise needs a solution such as better road planning.","zh":"對交通噪音的投訴需要更好道路規劃等解決方案。"},{"en":"If complaints never become solutions, residents may lose trust.","zh":"如果投訴從不變成解決方案，居民可能失去信任。"},{"en":"Good district work shortens the distance between complaints and solutions.","zh":"良好的地區工作會縮短投訴與解決方案之間的距離。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"by placing","meaning":"透過放置……","examples":[{"en":"By placing the handshake at the centre, the design suggests trust and cooperation.","zh":"透過把握手放在中心位置，設計暗示信任與合作。"},{"en":"By placing means through putting something in a particular position.","zh":"by placing 意思是透過把某物放在某個特定位置。"},{"en":"By placing the title at the top, a poster helps readers understand the topic first.","zh":"透過把標題放在頂部，海報幫助讀者先理解主題。"},{"en":"By placing residents at the bottom of Poster C, the design shows their voices as the starting point.","zh":"透過把居民放在海報 C 的底部，設計顯示居民的聲音是起點。"},{"en":"This phrase explains how a design choice creates meaning.","zh":"這個片語解釋設計選擇如何創造意思。"}],"source":"2019 Q8.pdf","sourcePage":4},{"front":"at the centre","meaning":"在中心位置","examples":[{"en":"The handshake is placed at the centre of the poster.","zh":"握手被放在海報的中心位置。"},{"en":"At the centre means in the middle or in the most important position.","zh":"at the centre 意思是在中間或最重要的位置。"},{"en":"A teacher may place the main question at the centre of the board.","zh":"老師可能把主要問題放在黑板中心位置。"},{"en":"When an image is at the centre, viewers usually notice it first.","zh":"當圖像在中心位置時，觀眾通常最先注意到它。"},{"en":"In a campaign, residents’ needs should be at the centre of every decision.","zh":"在競選中，居民需要應位於每個決定的中心。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"district work","meaning":"地區工作","examples":[{"en":"Ricky does not see district work as giving orders from above.","zh":"關偉基不把地區工作看作從上而下發號施令。"},{"en":"District work means practical work that serves a local community and solves local problems.","zh":"地區工作指服務本地社區和解決地區問題的實際工作。"},{"en":"District work may include following up on broken facilities or traffic complaints.","zh":"地區工作可能包括跟進損壞設施或交通投訴。"},{"en":"Good district work needs listening because residents know daily problems best.","zh":"良好的地區工作需要聆聽，因為居民最了解日常問題。"},{"en":"District work is about serving people nearby, not only making speeches.","zh":"地區工作是服務身邊的人，而不只是發表演說。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"giving orders from above","meaning":"從上而下發號施令","examples":[{"en":"The design suggests that district work is not about giving orders from above.","zh":"這個設計表示地區工作不是從上而下發號施令。"},{"en":"Giving orders from above means making decisions in a top-down way without listening to people affected.","zh":"從上而下發號施令意思是不聆聽受影響的人，只以由上至下方式作決定。"},{"en":"A manager gives orders from above if he changes rules without asking staff.","zh":"如果經理不詢問員工就改變規則，就是從上而下發號施令。"},{"en":"Residents may reject leaders who only give orders from above.","zh":"居民可能拒絕只會從上而下發號施令的領袖。"},{"en":"The poster rejects this image by showing handshake and partnership.","zh":"這張海報透過握手和合作關係拒絕這種形象。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"rather","meaning":"反而；更準確地說","examples":[{"en":"Rather, he sees district work as building trust face to face.","zh":"更準確地說，他把地區工作看作面對面建立信任。"},{"en":"Rather is used to correct or replace one idea with a more accurate one.","zh":"rather 用來修正或取代一個想法，提出更準確的說法。"},{"en":"The aim is not to punish students; rather, it is to help them improve.","zh":"目的不是懲罰學生；更準確地說，是幫助他們進步。"},{"en":"Ricky is not shown as a distant official; rather, he is shown as a partner.","zh":"關偉基不是被塑造成疏離的官員；反而，他被塑造成合作夥伴。"},{"en":"This word helps the writer shift from what something is not to what it really is.","zh":"這個字幫助作者由「不是甚麼」轉向「真正是甚麼」。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"build trust","meaning":"建立信任","examples":[{"en":"Ricky sees district work as building trust face to face.","zh":"關偉基把地區工作看作面對面建立信任。"},{"en":"To build trust means to make people believe in someone through honest and reliable actions.","zh":"建立信任意思是透過誠實可靠的行動令人相信某人。"},{"en":"A teacher builds trust by treating students fairly every day.","zh":"老師每天公平對待學生，便能建立信任。"},{"en":"A representative builds trust when residents see that their concerns are followed up.","zh":"當居民看到自己的關注被跟進，代表便能建立信任。"},{"en":"Trust is built slowly through action, not only slogans.","zh":"信任是透過行動慢慢建立的，不只是靠口號。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"face to face","meaning":"面對面","examples":[{"en":"The poster presents district work as building trust face to face.","zh":"這張海報把地區工作呈現為面對面建立信任。"},{"en":"Face to face means meeting or speaking directly in person.","zh":"face to face 意思是親身直接見面或交談。"},{"en":"Some problems are easier to solve when neighbours talk face to face.","zh":"有些問題在鄰居面對面交談時較容易解決。"},{"en":"Face-to-face meetings help residents feel heard more personally.","zh":"面對面會面幫助居民更親身感到被聆聽。"},{"en":"This phrase suggests closeness, patience, and real communication.","zh":"這個片語暗示親近、耐性和真正溝通。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"cross the bridge together","meaning":"一起跨過橋樑","examples":[{"en":"The line “Let’s cross the bridge together” suggests partnership.","zh":"「讓我們一起跨過橋樑」這句話表示合作關係。"},{"en":"To cross the bridge together means to face a problem as partners, not separately.","zh":"一起跨過橋樑意思是作為夥伴共同面對問題，而不是各自行動。"},{"en":"A school and parents can cross the bridge together when helping a struggling student.","zh":"學校和家長可一起跨過橋樑，幫助有困難的學生。"},{"en":"In the poster, the bridge suggests a path from complaint to solution.","zh":"在海報中，橋樑象徵由投訴走向解決方案的道路。"},{"en":"This phrase makes the candidate sound cooperative rather than superior.","zh":"這個片語令候選人聽起來合作，而不是高高在上。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"be effective because","meaning":"有效，因為……","examples":[{"en":"The line is effective because it avoids an arrogant promise.","zh":"這句話有效，因為它避免作出傲慢的承諾。"},{"en":"Be effective because means work well for a clear reason.","zh":"be effective because 意思是因某個清楚原因而有效。"},{"en":"A poster is effective because its slogan is short and easy to remember.","zh":"海報有效，因為它的口號簡短而容易記住。"},{"en":"The handshake image is effective because people quickly understand cooperation.","zh":"握手圖像有效，因為人們很快理解合作的意思。"},{"en":"This phrase is useful when explaining why a design choice succeeds.","zh":"這個片語適合用來解釋設計選擇為何成功。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"avoid an arrogant promise","meaning":"避免傲慢的承諾","examples":[{"en":"The slogan avoids an arrogant promise of instant success.","zh":"這個口號避免作出即時成功的傲慢承諾。"},{"en":"To avoid an arrogant promise means not to claim too proudly that everything will be solved easily.","zh":"避免傲慢的承諾意思是不過分自豪地聲稱一切都能輕易解決。"},{"en":"A candidate should avoid an arrogant promise such as “I alone can fix everything.”","zh":"候選人應避免「只有我能解決一切」這類傲慢承諾。"},{"en":"Voters may distrust slogans that make arrogant promises.","zh":"選民可能不信任作出傲慢承諾的口號。"},{"en":"A humble slogan offers partnership instead of pretending to have all the answers.","zh":"謙遜的口號提供合作關係，而不是假裝擁有所有答案。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"instant success","meaning":"即時成功","examples":[{"en":"The poster does not promise instant success.","zh":"這張海報沒有承諾即時成功。"},{"en":"Instant success means success that happens immediately, without time, effort, or difficulty.","zh":"即時成功意思是不用時間、努力或困難便立即成功。"},{"en":"A new study method rarely brings instant success after one day.","zh":"新學習方法很少在一天後帶來即時成功。"},{"en":"Promising instant success in district work may sound unrealistic.","zh":"在地區工作中承諾即時成功可能聽起來不切實際。"},{"en":"Real improvement usually needs listening, planning, and follow-up.","zh":"真正改善通常需要聆聽、計劃和跟進。"}],"source":"2019 Q8.pdf","sourcePage":5},{"front":"offer partnership","meaning":"提供合作關係","examples":[{"en":"Instead, the slogan offers partnership.","zh":"相反，這個口號提供合作關係。"},{"en":"To offer partnership means to invite others to work together rather than act alone.","zh":"提供合作關係意思是邀請他人一起工作，而不是單獨行動。"},{"en":"A school offers partnership when it asks parents to help plan student support.","zh":"學校邀請家長協助規劃學生支援時，就是提供合作關係。"},{"en":"A candidate offers partnership by listening before making decisions.","zh":"候選人在作決定前先聆聽，就是提供合作關係。"},{"en":"Partnership can make residents feel that change belongs to them too.","zh":"合作關係可以令居民覺得改變也屬於他們。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"a good campaign theme","meaning":"好的競選主題","examples":[{"en":"This would make a good campaign theme.","zh":"這會成為一個好的競選主題。"},{"en":"A good campaign theme is a clear idea that connects a candidate’s posters, slogans, and message.","zh":"好的競選主題是連繫候選人海報、口號和訊息的清晰理念。"},{"en":"“Clean Streets, Caring District” could be a good campaign theme for a local election.","zh":"「清潔街道，關懷社區」可以是地區選舉的好競選主題。"},{"en":"A good campaign theme helps voters remember what the candidate stands for.","zh":"好的競選主題幫助選民記得候選人代表甚麼。"},{"en":"It should be simple enough to remember but meaningful enough to persuade.","zh":"它應簡單到容易記住，但有足夠意義去說服人。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"present someone as","meaning":"把某人塑造成","examples":[{"en":"The poster presents Ricky as approachable and patient.","zh":"這張海報把關偉基塑造成平易近人和有耐性的人。"},{"en":"To present someone as something means to show them in a particular way.","zh":"present someone as 意思是以某種方式展示某人。"},{"en":"A school brochure may present the principal as caring and experienced.","zh":"學校小冊子可能把校長塑造成關懷且有經驗的人。"},{"en":"A poster can present a candidate as practical through images of local action.","zh":"海報可透過本地行動圖像，把候選人塑造成務實的人。"},{"en":"This phrase is useful when discussing image, character, or public impression.","zh":"這個片語適合用來討論形象、性格或公眾印象。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"approachable","meaning":"平易近人的","examples":[{"en":"The poster presents Ricky as approachable.","zh":"這張海報把關偉基塑造成平易近人的人。"},{"en":"Approachable means friendly and easy to talk to.","zh":"平易近人的意思是友善而容易交談。"},{"en":"An approachable teacher makes students feel safe to ask questions.","zh":"平易近人的老師令學生敢於發問。"},{"en":"A candidate looks approachable when residents feel they can share problems honestly.","zh":"當居民覺得可以坦誠分享問題時，候選人便顯得平易近人。"},{"en":"Being approachable is important in district work because residents need to speak freely.","zh":"平易近人在地區工作中很重要，因為居民需要自由發聲。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"patient","meaning":"有耐性的","examples":[{"en":"The poster presents Ricky as patient.","zh":"這張海報把關偉基塑造成有耐性的人。"},{"en":"Patient means able to listen or wait calmly without becoming angry quickly.","zh":"有耐性的意思是能冷靜聆聽或等待，不容易生氣。"},{"en":"A patient nurse explains medicine again when an elderly patient is confused.","zh":"有耐性的護士會在年長病人困惑時再次解釋藥物。"},{"en":"A patient representative listens to long complaints before suggesting action.","zh":"有耐性的代表會先聽完長篇投訴，再建議行動。"},{"en":"Patience helps leaders understand problems deeply before making decisions.","zh":"耐性幫助領袖在作決定前深入理解問題。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"willing to","meaning":"願意","examples":[{"en":"The poster presents Ricky as willing to walk with residents through difficult issues.","zh":"這張海報把關偉基塑造成願意與居民一同面對棘手問題的人。"},{"en":"Willing to means ready or prepared to do something.","zh":"willing to 意思是準備好或願意做某事。"},{"en":"A volunteer is willing to help neighbours carry heavy bags.","zh":"義工願意幫鄰居搬重物。"},{"en":"A candidate who is willing to listen may earn more trust.","zh":"願意聆聽的候選人可能贏得更多信任。"},{"en":"This phrase suggests attitude, not only ability.","zh":"這個片語強調態度，而不只是能力。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"walk with residents","meaning":"與居民同行","examples":[{"en":"Ricky is presented as willing to walk with residents through difficult issues.","zh":"關偉基被塑造成願意與居民一同面對棘手問題的人。"},{"en":"To walk with residents means to support local people through problems instead of leaving them alone.","zh":"與居民同行意思是在問題中支持本地居民，而不是讓他們獨自面對。"},{"en":"A social worker walks with families by helping them step by step.","zh":"社工透過一步步幫助家庭，與他們同行。"},{"en":"A representative walks with residents when he follows up after hearing complaints.","zh":"代表在聽取投訴後繼續跟進，就是與居民同行。"},{"en":"This phrase suggests patience, partnership, and shared effort.","zh":"這個片語暗示耐性、合作關係和共同努力。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"difficult issues","meaning":"棘手問題","examples":[{"en":"The campaign theme shows Ricky dealing with difficult issues.","zh":"競選主題展示關偉基處理棘手問題。"},{"en":"Difficult issues are problems that are serious, complicated, or hard to solve quickly.","zh":"棘手問題是嚴重、複雜或難以快速解決的問題。"},{"en":"Elderly care and transport planning can be difficult issues in a district.","zh":"長者照顧和交通規劃可以是地區中的棘手問題。"},{"en":"Difficult issues need patient listening because one simple answer may not work.","zh":"棘手問題需要耐心聆聽，因為單一簡單答案未必有效。"},{"en":"A good representative does not avoid difficult issues.","zh":"好代表不會避開棘手問題。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"whereas","meaning":"而；相對於","examples":[{"en":"Whereas Poster A stresses relationship, Poster B presents Ricky as a fresh thinker.","zh":"相對於海報 A 強調關係，海報 B 把關偉基塑造成思維新穎的人。"},{"en":"Whereas is used to compare two different ideas or situations.","zh":"whereas 用來比較兩個不同理念或情況。"},{"en":"Whereas one student learns by reading, another learns better through practice.","zh":"有學生透過閱讀學習，而另一位則透過實踐學得更好。"},{"en":"Whereas Poster A feels warm, Poster B feels creative and energetic.","zh":"海報 A 感覺溫暖，而海報 B 感覺有創意和活力。"},{"en":"This word helps explain contrast clearly in formal writing.","zh":"這個字幫助在正式寫作中清楚解釋對比。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"stress relationship","meaning":"強調關係","examples":[{"en":"Poster A stresses relationship.","zh":"海報 A 強調關係。"},{"en":"To stress relationship means to give special importance to trust, connection, and communication between people.","zh":"強調關係意思是特別重視人與人之間的信任、連繫和溝通。"},{"en":"A family event may stress relationship more than competition.","zh":"家庭活動可能比競爭更強調關係。"},{"en":"Poster A stresses relationship by showing two people shaking hands.","zh":"海報 A 透過展示兩個人握手來強調關係。"},{"en":"This focus makes Ricky seem close to residents rather than distant.","zh":"這個重點令關偉基看起來與居民親近，而不是疏離。"}],"source":"2019 Q8.pdf","sourcePage":6},{"front":"present someone as a fresh thinker","meaning":"把某人塑造成思維新穎的人","examples":[{"en":"Poster B presents Ricky as a fresh thinker.","zh":"海報 B 把關偉基塑造成思維新穎的人。"},{"en":"To present someone as a fresh thinker means to show that person as creative and open to new ideas.","zh":"把某人塑造成思維新穎的人，意思是展示此人有創意並樂於接受新想法。"},{"en":"A company may present a young designer as a fresh thinker through bold work.","zh":"公司可能透過大膽作品把年輕設計師塑造成思維新穎的人。"},{"en":"A candidate is presented as a fresh thinker when posters show new solutions.","zh":"當海報展示新解決方案時，候選人便被塑造成思維新穎的人。"},{"en":"This image can make voters believe the candidate will not repeat old methods.","zh":"這種形象可令選民相信候選人不會重複舊方法。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"visual design","meaning":"視覺設計","examples":[{"en":"The visual design shows a light bulb rising out of an open box.","zh":"視覺設計展示一個從打開的盒子中升起的燈泡。"},{"en":"Visual design means the use of images, colours, layout, and symbols to communicate meaning.","zh":"視覺設計指使用圖像、顏色、版面和象徵來傳達意思。"},{"en":"Good visual design helps people understand a poster before reading every word.","zh":"好的視覺設計幫助人們在讀完所有文字前先理解海報。"},{"en":"A light bulb in visual design often suggests ideas or invention.","zh":"在視覺設計中，燈泡通常象徵想法或創新。"},{"en":"Visual design is important because voters may only glance at a poster briefly.","zh":"視覺設計很重要，因為選民可能只會短暫看一眼海報。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"a light bulb rising out of","meaning":"從……升起的燈泡","examples":[{"en":"The poster shows a light bulb rising out of an open box.","zh":"這張海報展示一個從打開的盒子中升起的燈泡。"},{"en":"A light bulb rising out of something suggests an idea coming out from a limited place.","zh":"從某物升起的燈泡，表示想法從有限空間中出現。"},{"en":"A drawing of a light bulb rising out of a book can suggest learning and discovery.","zh":"從書本中升起的燈泡圖像，可以象徵學習和發現。"},{"en":"In Poster B, the bulb rising out of the box suggests breaking old limits.","zh":"在海報 B 中，從盒子升起的燈泡象徵打破舊限制。"},{"en":"This image makes creativity visible.","zh":"這個圖像令創意變得可見。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"an open box","meaning":"打開的盒子","examples":[{"en":"A light bulb rises out of an open box.","zh":"一個燈泡從打開的盒子中升起。"},{"en":"An open box is a box that is not closed, so something can come out of it.","zh":"打開的盒子是沒有關上的盒子，因此有東西可以從中出來。"},{"en":"In a poster, an open box can suggest that old limits are being broken.","zh":"在海報中，打開的盒子可以象徵舊限制正在被打破。"},{"en":"If ideas rise from an open box, the image suggests freedom and creativity.","zh":"如果想法從打開的盒子中升起，圖像便象徵自由和創意。"},{"en":"The open box contrasts with the idea of being trapped.","zh":"打開的盒子與被困住的概念形成對比。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"bird-like shapes","meaning":"像雀鳥的形狀","examples":[{"en":"There are bird-like shapes inside the bulb.","zh":"燈泡內有像雀鳥的形狀。"},{"en":"Bird-like shapes are shapes that look like birds but may not be detailed drawings of real birds.","zh":"像雀鳥的形狀是看起來像鳥，但未必是仔細描繪真鳥的形狀。"},{"en":"Bird-like shapes can suggest freedom, movement, and release.","zh":"像雀鳥的形狀可以象徵自由、流動和釋放。"},{"en":"In the light bulb, bird-like shapes make the idea feel alive and active.","zh":"在燈泡中，像雀鳥的形狀令想法感覺有生命力和活力。"},{"en":"Simple shapes can carry meaning even without realistic detail.","zh":"簡單形狀即使沒有寫實細節，也能承載意思。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"old assumptions","meaning":"舊有假設","examples":[{"en":"The box suggests old assumptions.","zh":"盒子象徵舊有假設。"},{"en":"Old assumptions are ideas people keep believing without checking whether they are still true.","zh":"舊有假設是人們一直相信、卻沒有檢查是否仍然正確的想法。"},{"en":"A school may have old assumptions about how students should learn.","zh":"學校可能對學生應如何學習抱有舊有假設。"},{"en":"Old assumptions can stop a district from trying better solutions.","zh":"舊有假設可能阻止社區嘗試更好的解決方案。"},{"en":"Thinking outside the box means questioning old assumptions.","zh":"跳出框框思考就是質疑舊有假設。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"rigid routines","meaning":"僵化常規","examples":[{"en":"The box suggests rigid routines.","zh":"盒子象徵僵化常規。"},{"en":"Rigid routines are fixed ways of doing things that are hard to change.","zh":"僵化常規是難以改變的固定做事方式。"},{"en":"A workplace with rigid routines may reject useful new ideas.","zh":"有僵化常規的工作場所可能拒絕有用的新想法。"},{"en":"District problems may remain unsolved if officials follow rigid routines only.","zh":"如果官員只跟隨僵化常規，地區問題可能仍得不到解決。"},{"en":"Creative action helps people move beyond rigid routines.","zh":"創意行動幫助人們超越僵化常規。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"familiar excuse","meaning":"熟悉的藉口","examples":[{"en":"The box also suggests the familiar excuse that things have always been done this way.","zh":"盒子也象徵「事情一直都是這樣做」這個熟悉的藉口。"},{"en":"A familiar excuse is a common reason people give to avoid changing something.","zh":"熟悉的藉口是人們常用來避免改變某事的理由。"},{"en":"“We have no time” can become a familiar excuse for not helping others.","zh":"「我們沒有時間」可以成為不幫助別人的熟悉藉口。"},{"en":"In district work, familiar excuses can delay practical improvement.","zh":"在地區工作中，熟悉的藉口可能延誤實際改善。"},{"en":"A fresh thinker challenges familiar excuses and asks what can be done differently.","zh":"思維新穎的人會挑戰熟悉的藉口，並問有甚麼可以不同地做。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"how things have always been done","meaning":"一直以來的做法","examples":[{"en":"The poster challenges the idea that this is how things have always been done.","zh":"這張海報挑戰「事情一直以來都是這樣做」這個想法。"},{"en":"How things have always been done means the usual method people keep using because it is familiar.","zh":"一直以來的做法指人們因熟悉而一直使用的慣常方法。"},{"en":"A school may keep paper forms because that is how things have always been done.","zh":"學校可能保留紙本表格，因為那是一直以來的做法。"},{"en":"This mindset can block better systems even when old methods are slow.","zh":"即使舊方法很慢，這種心態也可能阻礙更好的制度。"},{"en":"Poster B suggests that tradition should not stop creative solutions.","zh":"海報 B 表示傳統不應阻止創意解決方案。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"The light bulb, by contrast, suggests invention.","zh":"相比之下，燈泡象徵創新。"},{"en":"By contrast is used to show that the next idea is different from the previous one.","zh":"by contrast 用來顯示下一個想法與前一個不同。"},{"en":"The box suggests limits; by contrast, the light bulb suggests freedom.","zh":"盒子象徵限制；相比之下，燈泡象徵自由。"},{"en":"One poster may feel calm; by contrast, another may feel energetic.","zh":"一張海報可能感覺平靜；相比之下，另一張可能感覺有活力。"},{"en":"This phrase helps readers see differences clearly.","zh":"這個片語幫助讀者清楚看見差異。"}],"source":"2019 Q8.pdf","sourcePage":7},{"front":"suggest invention","meaning":"象徵創新","examples":[{"en":"The light bulb suggests invention.","zh":"燈泡象徵創新。"},{"en":"To suggest invention means to give the idea of creativity, discovery, or new solutions.","zh":"象徵創新意思是帶出創意、發現或新解決方案的概念。"},{"en":"A light bulb above a student’s head often suggests invention or a new idea.","zh":"學生頭上的燈泡通常象徵創新或新想法。"},{"en":"Poster B suggests invention by showing the bulb rising from the box.","zh":"海報 B 透過展示燈泡從盒子升起來象徵創新。"},{"en":"This image supports Ricky’s image as a creative problem-solver.","zh":"這個圖像支持關偉基作為創意解難者的形象。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"imply that","meaning":"暗示","examples":[{"en":"The birds imply that ideas are being released rather than trapped.","zh":"鳥形圖案暗示想法正在被釋放，而不是被困住。"},{"en":"To imply that means to suggest something indirectly without saying it directly.","zh":"imply that 意思是不直接說出，而是間接暗示某事。"},{"en":"A closed door may imply that people are not welcome.","zh":"關上的門可能暗示人們不受歡迎。"},{"en":"Bird shapes in a bulb imply that ideas can fly freely.","zh":"燈泡中的鳥形圖案暗示想法可以自由飛翔。"},{"en":"Designers often use images to imply meanings that words do not state.","zh":"設計師常用圖像暗示文字沒有直接說出的意思。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"be released rather than trapped","meaning":"被釋放而不是被困住","examples":[{"en":"The birds suggest that ideas are being released rather than trapped.","zh":"鳥形圖案表示想法正在被釋放，而不是被困住。"},{"en":"Be released rather than trapped means be set free instead of kept inside a limit.","zh":"被釋放而不是被困住意思是被放出來，而不是被限制在內。"},{"en":"Students’ ideas are released rather than trapped when teachers allow open discussion.","zh":"當老師容許開放討論時，學生的想法就是被釋放，而不是被困住。"},{"en":"In Poster B, the open box helps show ideas being released.","zh":"在海報 B 中，打開的盒子幫助展示想法被釋放。"},{"en":"This phrase contrasts freedom with restriction.","zh":"這個片語把自由與限制作對比。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"district problems","meaning":"地區問題","examples":[{"en":"District problems rarely fit into neat categories.","zh":"地區問題很少能清楚歸入不同類別。"},{"en":"District problems are local issues that affect people living in a particular area.","zh":"地區問題是影響某一地區居民的本地議題。"},{"en":"Broken facilities, traffic noise, and poor hygiene can all be district problems.","zh":"損壞設施、交通噪音和衞生欠佳都可以是地區問題。"},{"en":"District problems often overlap, so one solution may need several departments.","zh":"地區問題常互相重疊，因此一個解決方案可能需要多個部門配合。"},{"en":"Understanding district problems requires listening to residents’ daily experiences.","zh":"理解地區問題需要聆聽居民的日常經驗。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"fit into neat categories","meaning":"能清楚歸入不同類別","examples":[{"en":"District problems rarely fit into neat categories.","zh":"地區問題很少能清楚歸入不同類別。"},{"en":"Fit into neat categories means be easily sorted into clear and separate groups.","zh":"fit into neat categories 意思是能容易分成清晰而分開的類別。"},{"en":"Some student problems do not fit into neat categories because family, health, and study issues overlap.","zh":"有些學生問題不能清楚歸入不同類別，因為家庭、健康和學習問題互相重疊。"},{"en":"Traffic noise may not fit into one category if it also affects sleep and elderly care.","zh":"如果交通噪音也影響睡眠和長者照顧，它可能不能歸入單一類別。"},{"en":"This phrase shows that real problems are often more complex than labels.","zh":"這個片語顯示真實問題往往比標籤更複雜。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"traffic noise","meaning":"交通噪音","examples":[{"en":"Traffic noise may overlap with other district problems.","zh":"交通噪音可能與其他地區問題重疊。"},{"en":"Traffic noise is loud sound from cars, buses, trucks, or motorcycles.","zh":"交通噪音是汽車、巴士、貨車或電單車造成的巨大聲音。"},{"en":"Residents near a busy road may complain about traffic noise at night.","zh":"住在繁忙道路附近的居民可能投訴夜間交通噪音。"},{"en":"Traffic noise can affect sleep, health, and children’s study.","zh":"交通噪音可以影響睡眠、健康和孩子學習。"},{"en":"Reducing traffic noise may require transport planning, road design, and enforcement.","zh":"減少交通噪音可能需要交通規劃、道路設計和執法。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"recycling","meaning":"回收","examples":[{"en":"Recycling may overlap with other community issues.","zh":"回收可能與其他社區議題重疊。"},{"en":"Recycling means collecting and processing used materials so they can be used again.","zh":"回收指收集和處理用過的材料，使它們可以再次使用。"},{"en":"A housing estate may improve recycling by adding clearly labelled bins.","zh":"屋苑可透過增加清楚標示的回收箱來改善回收。"},{"en":"Recycling problems can connect with hygiene if bins are dirty or full.","zh":"如果回收箱骯髒或滿溢，回收問題可能與衞生相關。"},{"en":"Good recycling systems need education, space, and regular collection.","zh":"良好的回收系統需要教育、空間和定期收集。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"youth facilities","meaning":"青少年設施","examples":[{"en":"Youth facilities are one of the district issues mentioned.","zh":"青少年設施是提到的其中一個地區議題。"},{"en":"Youth facilities are places or services for young people, such as sports courts, study rooms, or activity centres.","zh":"青少年設施是為年輕人而設的地方或服務，例如球場、自修室或活動中心。"},{"en":"A district with few youth facilities may leave teenagers with nowhere safe to gather.","zh":"青少年設施不足的地區，可能令青少年沒有安全地方聚集。"},{"en":"Good youth facilities can support learning, friendship, and mental health.","zh":"良好的青少年設施可以支持學習、友誼和心理健康。"},{"en":"Planning youth facilities well helps young people feel valued in the community.","zh":"妥善規劃青少年設施有助年輕人感到被社區重視。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"support for elderly residents","meaning":"對長者居民的支援","examples":[{"en":"Support for elderly residents may overlap with other local issues.","zh":"對長者居民的支援可能與其他本地議題重疊。"},{"en":"Support for elderly residents means services or help that make older people’s lives safer and easier.","zh":"對長者居民的支援指令年長人士生活更安全和方便的服務或幫助。"},{"en":"Better benches and clearer crossings are forms of support for elderly residents.","zh":"更好的長椅和更清晰的過路處都是對長者居民的支援。"},{"en":"If transport is poor, support for elderly residents becomes harder.","zh":"如果交通不便，對長者居民的支援便更困難。"},{"en":"A caring district plans public spaces with elderly residents in mind.","zh":"關懷社區會在規劃公共空間時考慮長者居民。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"overlap","meaning":"重疊；互相關連","examples":[{"en":"Traffic noise, recycling and youth facilities may overlap.","zh":"交通噪音、回收和青少年設施可能互相關連。"},{"en":"To overlap means to connect or share parts with another issue.","zh":"overlap 意思是與另一個議題連接或共享部分內容。"},{"en":"Health and housing problems often overlap when overcrowding affects sleep.","zh":"當擠迫居住環境影響睡眠時，健康和住屋問題便會重疊。"},{"en":"District issues overlap because daily life does not fit into separate boxes.","zh":"地區議題會互相重疊，因為日常生活不能分成獨立盒子。"},{"en":"When problems overlap, solutions should involve different teams.","zh":"當問題互相重疊，解決方案應涉及不同團隊。"}],"source":"2019 Q8.pdf","sourcePage":8},{"front":"a single old answer","meaning":"單一舊方法","examples":[{"en":"A single old answer is often not enough.","zh":"單一舊方法往往不足夠。"},{"en":"A single old answer means one familiar solution that people keep using even when problems have changed.","zh":"單一舊方法指人們在問題已改變時仍繼續使用的一個熟悉解決方案。"},{"en":"More posters alone may be a single old answer to low community participation.","zh":"單靠增加海報可能只是面對社區參與低落的單一舊方法。"},{"en":"Complex district problems often need more than a single old answer.","zh":"複雜的地區問題通常需要不止一個單一舊方法。"},{"en":"Fresh thinking helps leaders move beyond old answers.","zh":"新思維幫助領袖超越舊方法。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"think outside the box","meaning":"跳出框框思考","examples":[{"en":"The slogan “Think outside the box” supports Ricky’s image as a creative problem-solver.","zh":"“Think outside the box” 這個口號支持關偉基作為創意解難者的形象。"},{"en":"To think outside the box means to look for new solutions instead of only following old habits.","zh":"跳出框框思考意思是尋找新解決方案，而不是只跟隨舊習慣。"},{"en":"A teacher thinks outside the box when she uses games to teach difficult grammar.","zh":"老師用遊戲教授困難文法時，就是跳出框框思考。"},{"en":"District leaders must think outside the box when old answers no longer work.","zh":"當舊答案不再有效，地區領袖必須跳出框框思考。"},{"en":"This phrase suggests creativity, flexibility, and courage to try new methods.","zh":"這個片語表示創意、彈性和嘗試新方法的勇氣。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"short enough for passers-by to remember","meaning":"簡短到讓路人記得","examples":[{"en":"The slogan is short enough for passers-by to remember.","zh":"這個口號簡短到讓路人記得。"},{"en":"Short enough for passers-by to remember means brief enough for people walking past to understand quickly.","zh":"short enough for passers-by to remember 意思是夠簡短，讓路過的人能快速理解。"},{"en":"A road safety sign must be short enough for drivers to read at once.","zh":"道路安全標語必須夠簡短，讓司機能立即讀懂。"},{"en":"Election slogans need to be short because passers-by may only look for a few seconds.","zh":"選舉口號需要簡短，因為路人可能只看幾秒。"},{"en":"A memorable slogan helps the message stay in voters’ minds.","zh":"容易記住的口號幫助訊息留在選民腦海中。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"passers-by","meaning":"路人","examples":[{"en":"The slogan should be easy for passers-by to remember.","zh":"這個口號應容易讓路人記得。"},{"en":"Passers-by are people who walk past a place without necessarily stopping.","zh":"路人是經過某地方但未必停下來的人。"},{"en":"A shop window needs clear signs because passers-by may not read long text.","zh":"店舖櫥窗需要清晰標語，因為路人未必閱讀長文字。"},{"en":"Campaign posters must catch passers-by quickly on busy streets.","zh":"競選海報必須在繁忙街道上快速吸引路人。"},{"en":"If passers-by remember the slogan, the poster has done part of its job.","zh":"如果路人記得口號，海報已完成部分作用。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"meaningful enough to","meaning":"有足夠意義去……","examples":[{"en":"The slogan is meaningful enough to support Ricky’s image.","zh":"這個口號有足夠意義去支持關偉基的形象。"},{"en":"Meaningful enough to means having enough depth or value to achieve a purpose.","zh":"meaningful enough to 意思是有足夠深度或價值去達到某目的。"},{"en":"A thank-you note should be meaningful enough to show real gratitude.","zh":"感謝信應有足夠意義去表達真正感激。"},{"en":"A slogan must be meaningful enough to connect with voters, not just sound catchy.","zh":"口號必須有足夠意義去連繫選民，而不只是順口。"},{"en":"This phrase helps judge whether words have real purpose.","zh":"這個片語幫助判斷文字是否有真正目的。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"search for better solutions","meaning":"尋找更好的解決方案","examples":[{"en":"The slogan presents Ricky as someone who will search for better solutions.","zh":"這個口號把關偉基塑造成會尋找更好解決方案的人。"},{"en":"To search for better solutions means to actively look for more effective ways to solve problems.","zh":"尋找更好的解決方案意思是主動尋找更有效的解難方法。"},{"en":"A teacher searches for better solutions when students do not understand the old method.","zh":"當學生不明白舊方法時，老師會尋找更好的解決方案。"},{"en":"District problems need leaders who search for better solutions instead of repeating excuses.","zh":"地區問題需要會尋找更好解決方案，而不是重複藉口的領袖。"},{"en":"This phrase suggests effort, openness, and practical thinking.","zh":"這個片語表示努力、開放和實際思考。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"pop-up consultation booths","meaning":"快閃諮詢站","examples":[{"en":"Ricky could explore pop-up consultation booths.","zh":"關偉基可以探索設立快閃諮詢站。"},{"en":"Pop-up consultation booths are temporary places where residents can share opinions or ask questions.","zh":"快閃諮詢站是臨時設置、讓居民分享意見或提問的地方。"},{"en":"A booth outside a market can collect views from people who rarely attend meetings.","zh":"街市外的諮詢站可以收集很少出席會議的人的意見。"},{"en":"Pop-up consultation booths make public discussion more accessible.","zh":"快閃諮詢站令公共討論更容易參與。"},{"en":"They can turn street contact into useful community feedback.","zh":"它們可以把街頭接觸變成有用的社區意見。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"mobile reporting system","meaning":"流動通報系統","examples":[{"en":"He could explore a mobile reporting system for broken facilities.","zh":"他可以探索設立一個用於通報損壞設施的流動通報系統。"},{"en":"A mobile reporting system is a phone-based tool for sending reports about local problems.","zh":"流動通報系統是以手機為基礎、用來提交本地問題報告的工具。"},{"en":"Residents could use a mobile reporting system to upload photos of broken lights.","zh":"居民可使用流動通報系統上載損壞街燈的相片。"},{"en":"Such a system can help staff locate problems faster.","zh":"這種系統可以幫助職員更快找到問題位置。"},{"en":"A mobile reporting system makes complaint handling more organised and evidence-based.","zh":"流動通報系統令投訴處理更有組織，也更以證據為本。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"broken facilities","meaning":"損壞設施","examples":[{"en":"A mobile reporting system could help residents report broken facilities.","zh":"流動通報系統可以幫助居民通報損壞設施。"},{"en":"Broken facilities are public objects or services that are damaged or not working.","zh":"損壞設施是受損或不能正常運作的公共物件或服務。"},{"en":"Broken facilities may include street lights, benches, lifts, or playground equipment.","zh":"損壞設施可能包括街燈、長椅、升降機或遊樂場設備。"},{"en":"If broken facilities are not repaired, residents may face inconvenience or danger.","zh":"如果損壞設施沒有維修，居民可能面對不便或危險。"},{"en":"Clear reporting helps public bodies fix broken facilities more quickly.","zh":"清晰通報幫助公共機構更快修理損壞設施。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"shared spaces","meaning":"共用空間","examples":[{"en":"He could explore shared spaces for different generations.","zh":"他可以探索為不同世代設立共用空間。"},{"en":"Shared spaces are places used by different groups of people together.","zh":"共用空間是不同群體共同使用的地方。"},{"en":"A park with exercise equipment and seats can be a shared space for young and old residents.","zh":"有健身設備和座椅的公園，可以成為年輕和年長居民的共用空間。"},{"en":"Shared spaces can reduce distance between generations by encouraging daily contact.","zh":"共用空間透過鼓勵日常接觸，減少世代之間的距離。"},{"en":"Good shared spaces are safe, welcoming, and useful for more than one group.","zh":"好的共用空間應安全、友善，並對多於一個群體有用。"}],"source":"2019 Q8.pdf","sourcePage":9},{"front":"different generations","meaning":"不同世代","examples":[{"en":"Shared spaces could bring different generations together.","zh":"共用空間可以把不同世代聚在一起。"},{"en":"Different generations are people from different age groups, such as children, adults, and elderly people.","zh":"不同世代指不同年齡層的人，例如兒童、成年人和長者。"},{"en":"A cooking class can bring different generations together through family recipes.","zh":"烹飪班可以透過家庭食譜把不同世代聚在一起。"},{"en":"If different generations rarely meet, stereotypes may grow.","zh":"如果不同世代很少見面，刻板印象可能增加。"},{"en":"Community spaces should help different generations understand one another.","zh":"社區空間應幫助不同世代互相理解。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"balance Poster A","meaning":"與海報 A 取得平衡","examples":[{"en":"Poster B also balances Poster A.","zh":"海報 B 也與海報 A 取得平衡。"},{"en":"To balance Poster A means to add a different strength so the two posters work better together.","zh":"與海報 A 取得平衡意思是加入不同優點，使兩張海報更好地配合。"},{"en":"If Poster A feels warm, Poster B can balance it by adding creativity.","zh":"如果海報 A 感覺溫暖，海報 B 可以透過加入創意與它取得平衡。"},{"en":"A campaign needs balance so it does not show only one side of the candidate.","zh":"競選需要平衡，才不會只展示候選人的一面。"},{"en":"Poster B prevents the campaign from seeming caring but not dynamic.","zh":"海報 B 防止競選看起來只有關懷而不夠有活力。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"caring but not dynamic","meaning":"關懷但不夠有活力","examples":[{"en":"One poster may seem caring but not dynamic.","zh":"一張海報可能顯得關懷但不夠有活力。"},{"en":"Caring but not dynamic means kind and sympathetic, but not energetic or action-oriented enough.","zh":"關懷但不夠有活力意思是友善有同情心，但不夠有能量或行動感。"},{"en":"A leader may sound caring but not dynamic if he listens but never acts.","zh":"如果領袖只聆聽但從不行動，可能聽起來關懷但不夠有活力。"},{"en":"A campaign that is only warm may seem caring but not dynamic.","zh":"只著重溫暖的競選可能顯得關懷但不夠有活力。"},{"en":"Adding creative solutions makes the candidate appear more active.","zh":"加入創意解決方案令候選人看起來更積極。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"clever but distant","meaning":"聰明但有距離感","examples":[{"en":"The other poster may seem clever but distant.","zh":"另一張海報可能顯得聰明但有距離感。"},{"en":"Clever but distant means intelligent and creative, but not warm or close to people.","zh":"聰明但有距離感意思是有智慧和創意，但不夠溫暖或親近人。"},{"en":"A speaker may seem clever but distant if he uses brilliant ideas without listening.","zh":"如果演講者只有出色想法卻不聆聽，他可能顯得聰明但有距離感。"},{"en":"A campaign that only shows innovation may seem clever but distant.","zh":"只展示創新的競選可能顯得聰明但有距離感。"},{"en":"Warm human images can stop a creative poster from feeling distant.","zh":"溫暖的人物圖像可避免創意海報感覺疏離。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"compassionate and capable","meaning":"有同理心且有能力","examples":[{"en":"Together, the posters show Ricky as both compassionate and capable.","zh":"兩張海報合起來顯示關偉基既有同理心，又有能力。"},{"en":"Compassionate and capable means caring about people and also able to solve problems.","zh":"有同理心且有能力意思是關心他人，同時也能解決問題。"},{"en":"A nurse is compassionate and capable when she comforts patients and gives accurate care.","zh":"護士安慰病人並提供準確照顧時，就是有同理心且有能力。"},{"en":"Voters need a representative who is compassionate and capable, not only friendly.","zh":"選民需要有同理心且有能力的代表，而不只是友善的人。"},{"en":"This phrase joins emotion with ability.","zh":"這個片語把情感與能力結合起來。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"I propose the slogan","meaning":"我建議口號","examples":[{"en":"For Poster C, I propose the slogan “Your voice lights the way.”","zh":"對於海報 C，我建議口號為 “Your voice lights the way.”"},{"en":"I propose the slogan means I formally suggest these words for use as the slogan.","zh":"I propose the slogan 意思是我正式建議使用這些文字作為口號。"},{"en":"For the school campaign, I propose the slogan “Study Well, Rest Well.”","zh":"對於學校宣傳活動，我建議口號為 “Study Well, Rest Well.”"},{"en":"A proposed slogan should match the poster’s image and message.","zh":"建議的口號應配合海報圖像和訊息。"},{"en":"This phrase is useful when presenting a design recommendation.","zh":"這個片語適合用於提出設計建議。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"light the way","meaning":"照亮方向","examples":[{"en":"The slogan says that residents’ voices can light the way.","zh":"這個口號表示居民的聲音可以照亮方向。"},{"en":"To light the way means to guide people towards the right direction or next step.","zh":"light the way 意思是引導人們走向正確方向或下一步。"},{"en":"A teacher’s advice can light the way for a confused student.","zh":"老師的建議可以為困惑的學生照亮方向。"},{"en":"Residents’ voices light the way when they help leaders understand what to fix.","zh":"當居民的聲音幫助領袖理解要修正甚麼時，就是在照亮方向。"},{"en":"This phrase suggests guidance, hope, and action.","zh":"這個片語象徵指引、希望和行動。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"vote for","meaning":"投票支持","examples":[{"en":"The slogan encourages residents to vote for Ricky Kwan.","zh":"這個口號鼓勵居民投票支持關偉基。"},{"en":"To vote for someone means to choose that person in an election.","zh":"vote for 某人意思是在選舉中選擇那個人。"},{"en":"Residents vote for a candidate by marking their choice on a ballot.","zh":"居民透過在選票上標記選擇來投票支持候選人。"},{"en":"People are more likely to vote for someone when they trust the message.","zh":"當人們信任訊息時，較可能投票支持某人。"},{"en":"This phrase is direct and common in election language.","zh":"這個片語在選舉語言中直接而常見。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"centre image","meaning":"中央圖像","examples":[{"en":"The centre image would combine the strongest symbols from the first two posters.","zh":"中央圖像會結合前兩張海報中最有力的象徵。"},{"en":"The centre image is the main picture placed in the most important visual position.","zh":"中央圖像是放在最重要視覺位置的主要圖片。"},{"en":"In a health poster, the centre image might be a family walking in a park.","zh":"在健康海報中，中央圖像可能是一家人在公園散步。"},{"en":"A strong centre image helps viewers understand the message quickly.","zh":"有力的中央圖像幫助觀眾快速理解訊息。"},{"en":"Poster C’s centre image should connect voice, light, and action.","zh":"海報 C 的中央圖像應連繫聲音、光和行動。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"combine the strongest symbols","meaning":"結合最有力的象徵","examples":[{"en":"Poster C would combine the strongest symbols from the first two posters.","zh":"海報 C 會結合前兩張海報中最有力的象徵。"},{"en":"To combine the strongest symbols means to bring the most meaningful images together.","zh":"結合最有力的象徵意思是把最有意義的圖像放在一起。"},{"en":"A festival poster may combine the strongest symbols of food, music, and family.","zh":"節日海報可能結合食物、音樂和家庭這些最有力的象徵。"},{"en":"Combining the handshake and light bulb can link trust with creativity.","zh":"結合握手和燈泡，可以把信任與創意連繫起來。"},{"en":"Good combination makes separate posters feel like one campaign series.","zh":"好的結合令不同海報感覺像同一個競選系列。"}],"source":"2019 Q8.pdf","sourcePage":10},{"front":"at the bottom","meaning":"在底部","examples":[{"en":"Several residents would be shown at the bottom of the poster.","zh":"幾位居民會被展示在海報底部。"},{"en":"At the bottom means in the lowest part of a page, picture, or object.","zh":"at the bottom 意思是在頁面、圖片或物件的最低部分。"},{"en":"Contact details are often placed at the bottom of a poster.","zh":"聯絡資料通常放在海報底部。"},{"en":"Placing residents at the bottom can show that the campaign begins with them.","zh":"把居民放在底部可以顯示競選由他們開始。"},{"en":"The bottom of the image can act as the starting point of a visual journey.","zh":"圖像底部可以作為視覺旅程的起點。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"be represented by","meaning":"由……代表","examples":[{"en":"The residents would be represented by simple speech bubbles.","zh":"居民會由簡單的對話泡泡代表。"},{"en":"Be represented by means be shown through a symbol, picture, or sign.","zh":"be represented by 意思是由象徵、圖像或標誌展示。"},{"en":"On a map, hospitals may be represented by a cross symbol.","zh":"在地圖上，醫院可能由十字標誌代表。"},{"en":"In Poster C, residents’ voices are represented by speech bubbles.","zh":"在海報 C 中，居民的聲音由對話泡泡代表。"},{"en":"Representation helps abstract ideas become easier to see.","zh":"代表方式幫助抽象理念變得更容易看見。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"speech bubbles","meaning":"對話泡泡","examples":[{"en":"The residents would be represented by simple speech bubbles.","zh":"居民會由簡單的對話泡泡代表。"},{"en":"Speech bubbles are shapes in pictures or comics that contain a person’s words.","zh":"對話泡泡是圖片或漫畫中載有人物說話的形狀。"},{"en":"A poster can use speech bubbles to show public opinions simply.","zh":"海報可以使用對話泡泡簡單展示公眾意見。"},{"en":"Speech bubbles suggest that residents are speaking, not staying silent.","zh":"對話泡泡表示居民正在發聲，而不是保持沉默。"},{"en":"This symbol fits a campaign about listening to local voices.","zh":"這個象徵適合關於聆聽本地聲音的競選。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"rise into","meaning":"升進","examples":[{"en":"The speech bubbles would rise into a large light bulb.","zh":"對話泡泡會升進一個大燈泡。"},{"en":"To rise into something means to move upward and become part of that thing.","zh":"rise into 意思是向上移動並成為某物的一部分。"},{"en":"Smoke may rise into the sky after a fire.","zh":"火災後，煙可能升進天空。"},{"en":"In the poster, speech bubbles rising into a bulb show voices becoming ideas.","zh":"在海報中，對話泡泡升進燈泡，顯示聲音變成想法。"},{"en":"This movement creates a visual path from residents to solutions.","zh":"這種移動創造一條由居民通往解決方案的視覺路線。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"form a bridge or path","meaning":"形成橋樑或道路","examples":[{"en":"The light from the bulb would form a bridge or path.","zh":"燈泡發出的光會形成橋樑或道路。"},{"en":"To form a bridge or path means to create a visual route that connects one place or idea to another.","zh":"形成橋樑或道路意思是創造一條連接地方或理念的視覺路線。"},{"en":"A line of footprints can form a path in a children’s poster.","zh":"一排腳印可以在兒童海報中形成道路。"},{"en":"In Poster C, light forming a path suggests action after ideas appear.","zh":"在海報 C 中，光形成道路，表示想法出現後有行動。"},{"en":"This image connects residents’ voices with practical improvement.","zh":"這個圖像把居民的聲音與實際改善連繫起來。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"lead towards","meaning":"通往","examples":[{"en":"The path would lead towards a cleaner, brighter street.","zh":"這條道路會通往一條更清潔、更明亮的街道。"},{"en":"Lead towards means guide or move in the direction of a place, result, or goal.","zh":"lead towards 意思是引導或走向某地方、結果或目標。"},{"en":"Better study habits can lead towards stronger exam results.","zh":"更好的學習習慣可以通往更好的考試成績。"},{"en":"In Poster C, the path leads towards visible district improvement.","zh":"在海報 C 中，這條路通往可見的地區改善。"},{"en":"This phrase suggests progress from present problems to a better future.","zh":"這個片語表示由現有問題邁向更好未來。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"a cleaner, brighter street","meaning":"更清潔、更明亮的街道","examples":[{"en":"The path would lead towards a cleaner, brighter street.","zh":"這條道路會通往一條更清潔、更明亮的街道。"},{"en":"A cleaner, brighter street is a street that looks tidier, safer, and more pleasant to use.","zh":"更清潔、更明亮的街道是看起來更整潔、更安全和更舒適的街道。"},{"en":"Better lighting and regular cleaning can create a cleaner, brighter street.","zh":"更好的照明和定期清潔可以創造更清潔、更明亮的街道。"},{"en":"A cleaner, brighter street can make residents feel safer at night.","zh":"更清潔、更明亮的街道可以令居民夜晚感到更安全。"},{"en":"This image turns the idea of improvement into something people can picture.","zh":"這個圖像把改善的理念變成人們能想像的畫面。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"along one side","meaning":"沿著一邊","examples":[{"en":"Three concise words could appear along one side.","zh":"三個簡潔的字詞可以沿著一邊出現。"},{"en":"Along one side means on or beside one edge of a design or object.","zh":"along one side 意思是在設計或物件的一個邊緣上或旁邊。"},{"en":"A poster may place contact details along one side to save space.","zh":"海報可能沿著一邊放置聯絡資料，以節省空間。"},{"en":"Words along one side can guide the viewer’s eye without blocking the main image.","zh":"沿著一邊放文字可以引導觀眾視線，而不遮擋主圖像。"},{"en":"This layout choice can keep the poster clean and organised.","zh":"這種版面選擇可以令海報保持乾淨和有組織。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"concise words","meaning":"簡潔的字詞","examples":[{"en":"Three concise words could appear on the poster.","zh":"三個簡潔的字詞可以出現在海報上。"},{"en":"Concise words are short, clear words that express meaning without waste.","zh":"簡潔的字詞是短而清楚、沒有多餘內容的字。"},{"en":"“Listen. Think. Act.” are concise words because each one is simple and direct.","zh":"“Listen. Think. Act.” 是簡潔的字詞，因為每個字都簡單直接。"},{"en":"Concise words help passers-by understand a poster quickly.","zh":"簡潔的字詞幫助路人快速理解海報。"},{"en":"In design, concise words often work better than long sentences.","zh":"在設計中，簡潔字詞通常比長句更有效。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"Listen. Think. Act.","meaning":"聆聽、思考、行動","examples":[{"en":"The words “Listen. Think. Act.” would summarise the campaign process.","zh":"“Listen. Think. Act.” 這幾個字會總結競選過程。"},{"en":"“Listen. Think. Act.” means first hear residents, then study the problem, then take practical steps.","zh":"“Listen. Think. Act.” 意思是先聆聽居民，再研究問題，然後採取實際步驟。"},{"en":"A good leader listens before thinking and acts only after understanding.","zh":"好領袖會先聆聽再思考，並在理解後才行動。"},{"en":"These three words make the campaign process simple and memorable.","zh":"這三個字令競選過程簡單而容易記住。"},{"en":"The slogan shows that Ricky values both care and action.","zh":"這個口號顯示關偉基重視關懷和行動。"}],"source":"2019 Q8.pdf","sourcePage":11},{"front":"show a process","meaning":"展示一個過程","examples":[{"en":"The design would show a process.","zh":"這個設計會展示一個過程。"},{"en":"To show a process means to present steps in the order they happen.","zh":"展示一個過程意思是按事情發生的次序呈現步驟。"},{"en":"A recipe poster shows a process by moving from ingredients to cooking to serving.","zh":"食譜海報由材料到烹調再到上碟，就是展示一個過程。"},{"en":"Poster C shows a process from residents’ voices to ideas to action.","zh":"海報 C 展示一個由居民聲音到想法再到行動的過程。"},{"en":"Showing a process helps viewers understand how change can happen.","zh":"展示過程幫助觀眾理解改變如何發生。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"study their concerns creatively","meaning":"有創意地研究他們的關注","examples":[{"en":"Ricky studies residents’ concerns creatively.","zh":"關偉基有創意地研究居民的關注。"},{"en":"To study their concerns creatively means to examine people’s worries with fresh thinking, not only routine methods.","zh":"有創意地研究他們的關注意思是用新思維檢視人們的憂慮，而不只是用慣常方法。"},{"en":"A teacher studies students’ concerns creatively by trying different ways to reduce stress.","zh":"老師透過嘗試不同方法減輕壓力，便是在有創意地研究學生的關注。"},{"en":"Ricky can study residents’ concerns creatively by comparing data, stories, and street observations.","zh":"關偉基可以透過比較數據、故事和街道觀察，有創意地研究居民的關注。"},{"en":"Creative study can turn ordinary complaints into better solutions.","zh":"創意研究可以把普通投訴變成更好的解決方案。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"council work follows","meaning":"議會工作隨之展開","examples":[{"en":"Residents speak, Ricky studies their concerns, and council work follows.","zh":"居民發聲，關偉基研究他們的關注，議會工作隨之展開。"},{"en":"Council work follows means official action comes after listening and understanding.","zh":"council work follows 意思是聆聽和理解之後，正式行動便展開。"},{"en":"After residents report broken lights, inspection and repair work may follow.","zh":"居民通報損壞街燈後，檢查和維修工作可能隨之展開。"},{"en":"The phrase suggests that public work should respond to residents’ voices.","zh":"這個片語表示公共工作應回應居民的聲音。"},{"en":"It creates a clear order: voice, thought, and action.","zh":"它創造清晰次序：聲音、思考和行動。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"avoid overcrowding","meaning":"避免過於擠迫","examples":[{"en":"The design should avoid overcrowding.","zh":"這個設計應避免過於擠迫。"},{"en":"To avoid overcrowding means not to put too many words or images into a small space.","zh":"避免過於擠迫意思是不要在小空間放入太多文字或圖像。"},{"en":"A poster should avoid overcrowding so viewers can focus on the main message.","zh":"海報應避免過於擠迫，讓觀眾能集中於主要訊息。"},{"en":"Overcrowding makes design noisy and hard to read.","zh":"過於擠迫會令設計雜亂且難以閱讀。"},{"en":"Leaving space helps important symbols stand out.","zh":"留下空間有助重要象徵突出。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"soft colours","meaning":"柔和色彩","examples":[{"en":"The poster could use two or three soft colours.","zh":"這張海報可以使用兩至三種柔和色彩。"},{"en":"Soft colours are gentle colours that do not feel harsh or noisy.","zh":"柔和色彩是溫和、不刺眼或不雜亂的顏色。"},{"en":"Pale blue and light green can be soft colours in a community poster.","zh":"淺藍色和淺綠色可以是社區海報中的柔和色彩。"},{"en":"Soft colours can make a campaign poster feel calm and positive.","zh":"柔和色彩可以令競選海報感覺平和而正面。"},{"en":"Too many strong colours may distract viewers from the main message.","zh":"太多強烈顏色可能令觀眾分心，忽略主要訊息。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"leave enough white space","meaning":"留下足夠留白","examples":[{"en":"The design should leave enough white space around the main image.","zh":"設計應在主圖像周圍留下足夠留白。"},{"en":"To leave enough white space means to keep empty areas so the design can breathe.","zh":"留下足夠留白意思是保留空白區域，令設計有呼吸空間。"},{"en":"A worksheet with enough white space is easier for students to read.","zh":"有足夠留白的工作紙較容易讓學生閱讀。"},{"en":"White space around a slogan helps people notice it faster.","zh":"口號周圍的留白幫助人們更快注意到它。"},{"en":"Good white space makes a poster feel calm rather than crowded.","zh":"良好留白令海報感覺平靜，而不是擠迫。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"around the main image","meaning":"在主圖像周圍","examples":[{"en":"There should be enough white space around the main image.","zh":"主圖像周圍應有足夠留白。"},{"en":"Around the main image means surrounding the most important picture in the design.","zh":"around the main image 意思是在設計中最重要圖片的周圍。"},{"en":"A poster may leave space around the main image so it stands out clearly.","zh":"海報可在主圖像周圍留下空間，讓它清楚突出。"},{"en":"If too much text crowds around the main image, viewers may feel confused.","zh":"如果太多文字擠在主圖像周圍，觀眾可能感到混亂。"},{"en":"The space around the main image helps guide attention.","zh":"主圖像周圍的空間有助引導注意力。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"that way","meaning":"這樣一來","examples":[{"en":"That way, the poster would feel positive rather than noisy.","zh":"這樣一來，海報會感覺正面而不雜亂。"},{"en":"That way means by doing this or as a result of this method.","zh":"that way 意思是透過這樣做，或作為這種方法的結果。"},{"en":"Use short sentences; that way, readers can understand the notice quickly.","zh":"使用短句；這樣一來，讀者可以快速理解告示。"},{"en":"Leave more white space; that way, the poster will feel calmer.","zh":"留下更多留白；這樣一來，海報會感覺更平靜。"},{"en":"This phrase connects a design choice with its expected result.","zh":"這個片語把設計選擇與預期結果連接起來。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"positive rather than noisy","meaning":"正面而不雜亂","examples":[{"en":"The poster would feel positive rather than noisy.","zh":"這張海報會感覺正面而不雜亂。"},{"en":"Positive rather than noisy means encouraging and clear, not messy or overwhelming.","zh":"positive rather than noisy 意思是令人鼓舞而清晰，不是混亂或令人負擔過重。"},{"en":"A classroom display should feel positive rather than noisy so students can focus.","zh":"課室展示應感覺正面而不雜亂，讓學生能集中。"},{"en":"Too many colours and slogans may make a campaign poster noisy.","zh":"太多顏色和口號可能令競選海報變得雜亂。"},{"en":"Soft colours and white space help the poster feel positive.","zh":"柔和色彩和留白有助海報感覺正面。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"practical rather than vague","meaning":"實際而不空泛","examples":[{"en":"The poster would feel practical rather than vague.","zh":"這張海報會感覺實際而不空泛。"},{"en":"Practical rather than vague means focused on real action instead of unclear ideas.","zh":"practical rather than vague 意思是著重真正行動，而不是含糊理念。"},{"en":"“Repair broken lights within two weeks” is practical rather than vague.","zh":"「兩星期內修理損壞街燈」是實際而不空泛的說法。"},{"en":"A campaign should be practical rather than vague so voters know what may happen.","zh":"競選應該實際而不空泛，讓選民知道可能會發生甚麼。"},{"en":"Poster C feels practical because it shows voices leading towards action.","zh":"海報 C 感覺實際，因為它展示聲音通往行動。"}],"source":"2019 Q8.pdf","sourcePage":12},{"front":"complete a logical sequence","meaning":"完成一個合乎邏輯的系列","examples":[{"en":"Poster C would complete a logical sequence.","zh":"海報 C 會完成一個合乎邏輯的系列。"},{"en":"To complete a logical sequence means to finish a set of steps that follow a clear order.","zh":"完成一個合乎邏輯的系列意思是完成一組按清楚次序發展的步驟。"},{"en":"A lesson on planning, writing, and editing completes a logical sequence for essay skills.","zh":"關於規劃、寫作和修改的課堂，完成了作文技巧的合乎邏輯系列。"},{"en":"Poster C completes the campaign sequence by turning concern and thought into action.","zh":"海報 C 透過把關注和思考轉化為行動，完成競選系列。"},{"en":"A logical sequence helps voters understand the campaign as a journey.","zh":"合乎邏輯的系列幫助選民把競選理解為一段歷程。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"invite residents to","meaning":"邀請居民去……","examples":[{"en":"Poster A invites residents to cross the bridge.","zh":"海報 A 邀請居民跨過橋樑。"},{"en":"To invite residents to do something means to ask local people to take part or respond.","zh":"邀請居民去做某事，意思是請本地居民參與或回應。"},{"en":"A notice may invite residents to join a clean-up activity.","zh":"告示可能邀請居民參加清潔活動。"},{"en":"Poster A invites residents to see politics as cooperation.","zh":"海報 A 邀請居民把政治視為合作。"},{"en":"Inviting residents makes the campaign feel open and participatory.","zh":"邀請居民令競選感覺開放且有參與性。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"promise creative thinking","meaning":"承諾創意思考","examples":[{"en":"Poster B promises creative thinking.","zh":"海報 B 承諾創意思考。"},{"en":"To promise creative thinking means to suggest that the candidate will use new ideas to solve problems.","zh":"承諾創意思考意思是表示候選人會用新想法解決問題。"},{"en":"A school leader promises creative thinking when she offers new ways to reduce homework stress.","zh":"當學校領袖提出減少功課壓力的新方法時，就是承諾創意思考。"},{"en":"Poster B promises creative thinking through the light bulb and open box.","zh":"海報 B 透過燈泡和打開的盒子承諾創意思考。"},{"en":"This promise should later be supported by practical action.","zh":"這個承諾之後應由實際行動支持。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"light the route towards action","meaning":"照亮通往行動的路線","examples":[{"en":"Poster C shows how residents’ voices can light the route towards action.","zh":"海報 C 展示居民的聲音如何照亮通往行動的路線。"},{"en":"To light the route towards action means to guide people from ideas or concerns to real steps.","zh":"照亮通往行動的路線意思是引導人們由想法或關注走向實際步驟。"},{"en":"Clear feedback can light the route towards action for a school improvement plan.","zh":"清晰意見可以為學校改善計劃照亮通往行動的路線。"},{"en":"Residents’ voices light the route when they show which problems matter most.","zh":"當居民的聲音顯示哪些問題最重要時，它們便照亮了路線。"},{"en":"This phrase connects listening with practical results.","zh":"這個片語把聆聽與實際結果連繫起來。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"all things considered","meaning":"綜合考慮各方面","examples":[{"en":"All things considered, the three posters could work as a coherent campaign series.","zh":"綜合考慮各方面，三張海報可以成為一個連貫的競選宣傳系列。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 意思是在考慮所有重要因素後。"},{"en":"All things considered, the design should stay simple and clear.","zh":"綜合考慮各方面，設計應保持簡單清晰。"},{"en":"This phrase is useful when giving a final judgement after analysis.","zh":"這個片語適合在分析後提出最後判斷。"},{"en":"It shows that the writer has weighed different strengths and risks.","zh":"它顯示作者已衡量不同優點和風險。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"a coherent campaign series","meaning":"連貫的競選宣傳系列","examples":[{"en":"The three posters could work as a coherent campaign series.","zh":"三張海報可以成為一個連貫的競選宣傳系列。"},{"en":"A coherent campaign series is a set of campaign materials that fit together clearly.","zh":"連貫的競選宣傳系列是一組清楚配合的競選材料。"},{"en":"Posters using the same colours, tone, and message can form a coherent campaign series.","zh":"使用相同顏色、語氣和訊息的海報，可以形成連貫的競選宣傳系列。"},{"en":"A coherent series helps voters remember the campaign as one connected story.","zh":"連貫系列幫助選民把競選記成一個互相關連的故事。"},{"en":"Without coherence, each poster may feel separate and weaker.","zh":"沒有連貫性，每張海報可能顯得分散且較弱。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"build trust","meaning":"建立信任","examples":[{"en":"Poster A builds trust.","zh":"海報 A 建立信任。"},{"en":"To build trust means to make people feel confident that someone is honest and reliable.","zh":"建立信任意思是令人相信某人誠實可靠。"},{"en":"A councillor builds trust by answering residents’ messages and following up problems.","zh":"議員透過回覆居民訊息和跟進問題來建立信任。"},{"en":"Poster A builds trust through the handshake and bridge image.","zh":"海報 A 透過握手和橋樑圖像建立信任。"},{"en":"Trust grows when words, images, and actions all point in the same direction.","zh":"當文字、圖像和行動都指向同一方向時，信任便會增長。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"build confidence in","meaning":"建立對……的信心","examples":[{"en":"Poster B builds confidence in Ricky’s ideas.","zh":"海報 B 建立人們對關偉基理念的信心。"},{"en":"To build confidence in something means to make people believe it is strong, useful, or worth supporting.","zh":"建立對某事的信心意思是令人相信它有力、有用或值得支持。"},{"en":"Clear explanations build confidence in a new school policy.","zh":"清晰解釋可以建立人們對新校規的信心。"},{"en":"Poster B builds confidence in Ricky’s ideas by showing creativity and movement.","zh":"海報 B 透過展示創意和動感，建立人們對關偉基理念的信心。"},{"en":"Voters need confidence in both the person and the plan.","zh":"選民需要對人和計劃都有信心。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"build belief in action","meaning":"建立對行動的信念","examples":[{"en":"Poster C builds belief in action.","zh":"海報 C 建立對行動的信念。"},{"en":"To build belief in action means to make people feel that real steps can follow from ideas.","zh":"建立對行動的信念意思是令人相信想法之後可以有真正步驟。"},{"en":"A school builds belief in action when student suggestions lead to actual changes.","zh":"當學生建議帶來實際改變時，學校便建立了對行動的信念。"},{"en":"Poster C builds belief in action by showing voices becoming a brighter street.","zh":"海報 C 透過展示聲音變成更明亮街道，建立對行動的信念。"},{"en":"This phrase suggests hope that problems can truly be improved.","zh":"這個片語表示相信問題真的可以改善的希望。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"I would appreciate it if","meaning":"如蒙……我將十分感激","examples":[{"en":"I would appreciate it if the committee could review these proposals.","zh":"如蒙委員會審視這些建議，我將十分感激。"},{"en":"I would appreciate it if is a polite formal way to make a request.","zh":"I would appreciate it if 是正式而有禮地提出請求的說法。"},{"en":"I would appreciate it if you could reply by Friday.","zh":"如蒙你在星期五前回覆，我將十分感激。"},{"en":"In a proposal letter, this phrase sounds respectful rather than demanding.","zh":"在建議信中，這個片語聽起來尊重，而不是命令式。"},{"en":"It is useful when asking people in authority to consider something.","zh":"當請有權力的人考慮某事時，這個片語很有用。"}],"source":"2019 Q8.pdf","sourcePage":13},{"front":"review these proposals","meaning":"審視這些建議","examples":[{"en":"The committee is asked to review these proposals.","zh":"委員會被請求審視這些建議。"},{"en":"To review these proposals means to examine the suggestions carefully before making a decision.","zh":"審視這些建議意思是在作決定前仔細檢查這些提議。"},{"en":"Teachers may review students’ proposals before approving a school event.","zh":"老師可能在批准學校活動前審視學生的建議。"},{"en":"The committee should review these proposals to check their message, design, and practicality.","zh":"委員會應審視這些建議，以檢查其訊息、設計和可行性。"},{"en":"Review is important because good ideas may still need adjustment.","zh":"審視很重要，因為好想法仍可能需要調整。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"advise whether","meaning":"建議是否","examples":[{"en":"The committee is asked to advise whether the final campaign theme should use one slogan or another.","zh":"委員會被請求建議最終競選主題應使用一個口號還是另一個口號。"},{"en":"To advise whether means to give guidance about which choice is better.","zh":"advise whether 意思是就哪個選擇較好提供指引。"},{"en":"A doctor can advise whether a patient should rest or return to work.","zh":"醫生可以建議病人是否應休息或復工。"},{"en":"The committee can advise whether “From Concern to Solution” or “Listen. Think. Act.” is stronger.","zh":"委員會可以建議 “From Concern to Solution” 還是 “Listen. Think. Act.” 較有力。"},{"en":"This phrase is useful when asking for a decision between options.","zh":"這個片語適合用於請求在選項之間作決定。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"final campaign theme","meaning":"最終競選主題","examples":[{"en":"The final campaign theme may be “From Concern to Solution”.","zh":"最終競選主題可能是「由關注到解決方案」。"},{"en":"The final campaign theme is the main message chosen for the finished campaign.","zh":"最終競選主題是完成後的競選所選用的主要訊息。"},{"en":"After reviewing all designs, the team can choose the final campaign theme.","zh":"審視所有設計後，團隊可以選擇最終競選主題。"},{"en":"A strong final campaign theme should connect all posters clearly.","zh":"有力的最終競選主題應清楚連繫所有海報。"},{"en":"Once the final theme is chosen, colours, slogans, and images can be refined.","zh":"一旦選定最終主題，顏色、口號和圖像便可再作修改。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"be presented as","meaning":"被呈現為","examples":[{"en":"The campaign theme could be presented as “Listen. Think. Act.”","zh":"競選主題可以被呈現為 “Listen. Think. Act.”"},{"en":"Be presented as means be shown or described in a particular form.","zh":"be presented as 意思是以某種形式被展示或描述。"},{"en":"A school rule can be presented as a safety measure rather than a punishment.","zh":"校規可以被呈現為安全措施，而不是懲罰。"},{"en":"The campaign could be presented as a journey from voice to action.","zh":"這場競選可以被呈現為由聲音走向行動的旅程。"},{"en":"Presentation affects how people understand the same idea.","zh":"呈現方式會影響人們如何理解同一理念。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"once your preference is confirmed","meaning":"一旦確認你們的偏好","examples":[{"en":"Once your preference is confirmed, I will refine Poster C accordingly.","zh":"一旦確認你們的偏好，我會相應修改海報 C。"},{"en":"Once your preference is confirmed means after your chosen option becomes clear and definite.","zh":"once your preference is confirmed 意思是在你們選定的選項變得清楚和確定之後。"},{"en":"Once your preference is confirmed, the designer can adjust the colours and slogan.","zh":"一旦確認你們的偏好，設計師便可以調整顏色和口號。"},{"en":"This phrase is useful when work depends on another person’s decision.","zh":"當工作取決於另一人的決定時，這個片語很有用。"},{"en":"It shows that the next step will follow the committee’s choice.","zh":"它顯示下一步會跟隨委員會的選擇。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"refine Poster C accordingly","meaning":"相應修改海報 C","examples":[{"en":"I will refine Poster C accordingly.","zh":"我會相應修改海報 C。"},{"en":"To refine Poster C accordingly means to improve or adjust Poster C based on the decision made.","zh":"相應修改海報 C 意思是根據已作出的決定改善或調整海報 C。"},{"en":"If the committee chooses a softer tone, the designer will refine Poster C accordingly.","zh":"如果委員會選擇較柔和的語氣，設計師會相應修改海報 C。"},{"en":"Refining the poster may include changing the slogan, colours, or layout.","zh":"修改海報可能包括改變口號、顏色或版面。"},{"en":"This phrase shows flexibility and willingness to respond to feedback.","zh":"這個片語顯示彈性和願意回應意見。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"The letter ends with Yours faithfully.","zh":"這封信以 “Yours faithfully” 結尾。"},{"en":"Yours faithfully is a formal closing used in business or official letters, often when writing to a group or unknown recipient.","zh":"Yours faithfully 是商業或正式信件中的正式結尾，常用於寫給團體或不確定姓名的收信人。"},{"en":"A volunteer may end a formal proposal letter with “Yours faithfully”.","zh":"義工可能以 “Yours faithfully” 結束正式建議信。"},{"en":"This closing keeps the tone respectful and professional.","zh":"這個結尾保持語氣尊重和專業。"},{"en":"It is more formal than casual endings such as “Thanks” or “Best”.","zh":"它比 “Thanks” 或 “Best” 等隨意結尾更正式。"}],"source":"2019 Q8.pdf","sourcePage":14},{"front":"Volunteer, District Council Office","meaning":"區議會辦事處義工","examples":[{"en":"Chris Wong signs the letter as a volunteer at the District Council Office.","zh":"Chris Wong 以區議會辦事處義工身份簽署這封信。"},{"en":"Volunteer, District Council Office identifies the writer’s role and organisation.","zh":"Volunteer, District Council Office 說明作者的角色和所屬機構。"},{"en":"A volunteer at a district office may help with community events and resident enquiries.","zh":"區議會辦事處義工可能協助社區活動和居民查詢。"},{"en":"Including this title helps readers understand why Chris is involved in the proposal.","zh":"加上這個身份有助讀者理解 Chris 為何參與這項建議。"},{"en":"A clear signature makes a formal letter more trustworthy.","zh":"清楚署名令正式信件更可信。"}],"source":"2019 Q8.pdf","sourcePage":14}],"dse/writing/part-b/2019/Q9":[{"front":"need two","meaning":"需要兩個人；需要兩位拍檔","examples":[{"en":"The race needed two partners to finish together.","zh":"這場比賽需要兩位拍檔一起完成。"},{"en":"“Need two” means that two people are required rather than only one.","zh":"「need two」表示需要兩個人，而不是只有一個人。"},{"en":"This game needs two players because one person cannot play it alone.","zh":"這個遊戲需要兩名玩家，因為一個人無法獨自進行。"},{"en":"Carrying the heavy table may need two people to keep it balanced.","zh":"搬這張沉重的桌子可能需要兩個人，才能保持平衡。"},{"en":"Some challenges need two partners because each person brings a different strength.","zh":"有些挑戰需要兩位拍檔，因為每個人都有不同的長處。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"long after","meaning":"在……很久之後","examples":[{"en":"Long after the tortoise had beaten the hare, the animals still told the story.","zh":"在陸龜擊敗野兔很久之後，動物們仍然講述這個故事。"},{"en":"“Long after” means a considerable time after an event has happened.","zh":"「long after」表示某件事發生了很長時間之後。"},{"en":"Long after the school trip ended, the students still talked about the funny moments.","zh":"在學校旅行結束很久之後，學生仍談論那些有趣的時刻。"},{"en":"Some lessons remain important long after the original event is forgotten.","zh":"有些教訓在原本的事件被忘記很久之後仍然重要。"},{"en":"Long after an argument is over, people may still remember the words that hurt them.","zh":"在爭吵結束很久之後，人們可能仍記得那些傷人的說話。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"the tortoise","meaning":"陸龜","examples":[{"en":"The tortoise had beaten the hare in the famous race.","zh":"陸龜在那場著名比賽中擊敗了野兔。"},{"en":"A tortoise is a slow-moving land animal with a hard shell protecting its body.","zh":"陸龜是一種行動緩慢、身體受到硬殼保護的陸生動物。"},{"en":"The tortoise pulled its head into its shell when it felt frightened.","zh":"陸龜感到害怕時，把頭縮進龜殼裏。"},{"en":"Although a tortoise moves slowly, it can travel steadily for a long time.","zh":"雖然陸龜移動緩慢，但可以長時間穩定前進。"},{"en":"In the story, the tortoise represents patience and steady effort.","zh":"在故事中，陸龜代表耐性和穩定的努力。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"beat the hare","meaning":"擊敗野兔","examples":[{"en":"The tortoise had beaten the hare long ago.","zh":"陸龜很久以前已擊敗野兔。"},{"en":"To beat the hare means to defeat the hare in a race or competition.","zh":"「beat the hare」表示在比賽或競賽中擊敗野兔。"},{"en":"The slower runner beat the favourite because she kept going when others became tired.","zh":"那位較慢的跑手擊敗了大熱門，因為其他人疲倦時她仍繼續前進。"},{"en":"The tortoise beat the hare because patience mattered more than careless speed.","zh":"陸龜擊敗野兔，是因為耐性比粗心的速度更重要。"},{"en":"Beating a stronger opponent often requires good judgement as well as ability.","zh":"擊敗較強的對手，往往需要良好判斷力，也需要能力。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"the hare","meaning":"野兔","examples":[{"en":"The hare remembered how he had lost the race.","zh":"野兔記得自己當年如何輸掉比賽。"},{"en":"A hare is a fast-running animal similar to a rabbit but usually larger, with longer legs and ears.","zh":"野兔是一種與兔子相似但通常較大、腿和耳朵較長，而且跑得很快的動物。"},{"en":"The hare could cross the field much faster than the tortoise.","zh":"野兔可以比陸龜快得多地跑過田野。"},{"en":"Hares depend on speed to escape danger in open countryside.","zh":"野兔在開闊的鄉郊主要依靠速度逃避危險。"},{"en":"In the story, the hare learns that speed alone is not enough.","zh":"在故事中，野兔學會單靠速度並不足夠。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"tell the story","meaning":"講述這個故事","examples":[{"en":"The animals told the story whenever someone became too proud.","zh":"每當有人變得太驕傲，動物們便講述這個故事。"},{"en":"To tell the story means to describe what happened in a particular event or tale.","zh":"「tell the story」表示講述某件事或故事中發生了甚麼。"},{"en":"Grandparents often tell the story of how the family first moved to the city.","zh":"祖父母常講述這個家庭當初如何搬到城市的故事。"},{"en":"Teachers tell the story again because it helps students remember the lesson.","zh":"老師再次講述這個故事，因為它能幫助學生記住教訓。"},{"en":"People often tell a story when they want others to learn from what happened.","zh":"當人們希望別人從事情中學習時，往往會講述那個故事。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"whenever someone became too proud","meaning":"每當有人變得太驕傲時","examples":[{"en":"The animals repeated the lesson whenever someone became too proud.","zh":"每當有人變得太驕傲時，動物們便重複那個教訓。"},{"en":"This phrase means every time a person started thinking too highly of themselves.","zh":"這個片語表示每當某人開始過分看高自己時。"},{"en":"The coach reminded the team to stay humble whenever someone became too proud after winning.","zh":"每當有人勝出後變得太驕傲，教練便提醒隊員保持謙虛。"},{"en":"Whenever someone became too proud, the old story reminded them that success can disappear quickly.","zh":"每當有人變得太驕傲時，這個古老故事便提醒他們成功可以很快消失。"},{"en":"Advice is especially useful whenever confidence begins turning into arrogance.","zh":"每當自信開始變成自大時，勸告便特別有用。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"slow and steady","meaning":"慢而穩","examples":[{"en":"Every squirrel remembered the phrase “slow and steady.”","zh":"每隻松鼠都記得「慢而穩」這句話。"},{"en":"“Slow and steady” describes doing something patiently and consistently rather than rushing.","zh":"「slow and steady」形容耐心而持續地做事，而不是急於求成。"},{"en":"Slow and steady revision every day is often better than studying everything the night before an exam.","zh":"每天慢而穩地溫習，往往比考試前一晚一次過讀完全部內容更好。"},{"en":"The worker finished the difficult task through slow and steady progress.","zh":"那名工人靠慢而穩的進度完成了困難任務。"},{"en":"Slow and steady effort can succeed when rushing leads to mistakes.","zh":"當急躁會導致錯誤時，慢而穩的努力反而可能成功。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"ears burned","meaning":"耳朵發燙；感到尷尬","examples":[{"en":"The hare’s ears burned whenever he heard the old saying.","zh":"每當野兔聽到那句老話，他的耳朵便發燙。"},{"en":"If someone’s ears burn from embarrassment, they feel hot because they are ashamed or uncomfortable.","zh":"如果某人的耳朵因尷尬而發燙，表示他因羞愧或不自在而感到發熱。"},{"en":"His ears burned when the teacher mentioned the mistake he had made in front of the class.","zh":"老師在全班面前提到他犯過的錯誤時，他尷尬得耳朵發燙。"},{"en":"The hare’s ears burned because the old saying reminded him of his embarrassing defeat.","zh":"野兔的耳朵發燙，因為那句老話令他想起令人尷尬的失敗。"},{"en":"People may feel their face or ears burn when an uncomfortable memory is mentioned.","zh":"當令人不自在的往事被提起，人可能會感到臉或耳朵發熱。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"the tale was true","meaning":"這個故事是真的","examples":[{"en":"The hare knew that the tale was true.","zh":"野兔知道這個故事是真的。"},{"en":"“The tale was true” means the story accurately described something that had really happened.","zh":"「the tale was true」表示故事準確描述了真正發生過的事情。"},{"en":"At first the children thought it was only a legend, but later they discovered the tale was true.","zh":"孩子們起初以為那只是傳說，後來才發現這個故事是真的。"},{"en":"The hare could not deny the lesson because the tale was true and he had lived through it himself.","zh":"野兔無法否認那個教訓，因為故事是真的，而且他親身經歷過。"},{"en":"A painful story can be difficult to hear when you know the tale is true.","zh":"當你知道故事是真的，一個痛苦的故事可能特別難聽下去。"}],"source":"2019 Q9.pdf","sourcePage":1},{"front":"careless and foolish","meaning":"粗心而愚蠢","examples":[{"en":"The hare had been fast, careless and foolish.","zh":"野兔曾經跑得很快，卻粗心而愚蠢。"},{"en":"“Careless and foolish” describes someone who does not pay enough attention and makes unwise decisions.","zh":"「careless and foolish」形容某人不夠留神，而且作出不明智的決定。"},{"en":"Leaving the door unlocked all night was careless and foolish.","zh":"整晚不鎖門是粗心而愚蠢的行為。"},{"en":"The hare was careless and foolish because he depended on speed and ignored the risk of losing.","zh":"野兔粗心而愚蠢，因為他只依賴速度，忽視了落敗的風險。"},{"en":"Talent can be wasted when a capable person behaves carelessly and foolishly.","zh":"即使很有才能，如果一個人行事粗心而愚蠢，也可能浪費自己的能力。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"impossible to shake","meaning":"難以動搖","examples":[{"en":"The tortoise was patient and impossible to shake.","zh":"陸龜很有耐性，而且難以動搖。"},{"en":"“Impossible to shake” describes someone whose determination or confidence is extremely difficult to weaken.","zh":"「impossible to shake」形容某人的決心或信心極難被削弱。"},{"en":"The goalkeeper remained impossible to shake even after the other team scored first.","zh":"即使對方先入球，那位守門員仍然難以動搖。"},{"en":"The tortoise was impossible to shake because setbacks never made him abandon his plan.","zh":"陸龜難以動搖，因為挫折從來沒有令他放棄計劃。"},{"en":"A person who is impossible to shake stays calm even when others doubt them.","zh":"一個難以動搖的人，即使受到別人懷疑仍能保持冷靜。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"one golden morning","meaning":"一個金色的早晨","examples":[{"en":"One golden morning, a poster appeared on the old oak.","zh":"一個金色的早晨，老橡樹上出現了一張海報。"},{"en":"“One golden morning” describes a bright, beautiful morning filled with warm sunlight.","zh":"「one golden morning」形容一個陽光溫暖、明亮而美麗的早晨。"},{"en":"One golden morning, the family opened the curtains and saw the garden shining in the sun.","zh":"一個金色的早晨，一家人拉開窗簾，看見花園在陽光下閃耀。"},{"en":"Writers may use “golden” to make an ordinary morning feel warm and special.","zh":"作家可以使用「golden」令普通早晨顯得溫暖而特別。"},{"en":"One golden morning can mark the beginning of an important new event in a story.","zh":"在故事中，一個金色的早晨可以標誌重要新事件的開始。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"a poster appeared","meaning":"一張海報出現","examples":[{"en":"A poster appeared on the old oak.","zh":"老橡樹上出現了一張海報。"},{"en":"“A poster appeared” means a notice or large printed message suddenly became visible in a place.","zh":"「a poster appeared」表示一張告示或大型印刷訊息突然在某個地方出現。"},{"en":"A poster appeared outside the school announcing the sports competition.","zh":"學校外出現了一張海報，宣布運動比賽的消息。"},{"en":"When a poster appeared in the town square, people gathered to read it.","zh":"廣場上出現一張海報後，人們聚集起來閱讀。"},{"en":"A poster appearing unexpectedly can signal that something new is about to happen.","zh":"一張海報突然出現，可以表示一件新事情即將發生。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"the old oak","meaning":"老橡樹","examples":[{"en":"The poster was fixed to the old oak.","zh":"海報被固定在老橡樹上。"},{"en":"An oak is a large strong tree, and “the old oak” refers to one that has grown for many years.","zh":"橡樹是一種高大而堅固的樹，而「the old oak」指一棵生長了很多年的橡樹。"},{"en":"The children often met beneath the old oak because its branches gave plenty of shade.","zh":"孩子們常在老橡樹下見面，因為它的枝葉提供很多樹蔭。"},{"en":"The old oak had stood in the clearing longer than any of the animals could remember.","zh":"那棵老橡樹在林中空地屹立的時間，比任何動物記得的都更久。"},{"en":"An old tree can become an important meeting place or landmark in a community.","zh":"一棵老樹可以成為社區中重要的聚會地點或地標。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"teams of two only","meaning":"只限二人隊伍","examples":[{"en":"The challenge allowed teams of two only.","zh":"這項挑戰只限二人隊伍參加。"},{"en":"“Teams of two only” means every team must contain exactly two members.","zh":"「teams of two only」表示每隊必須剛好有兩名成員。"},{"en":"The cooking competition accepts teams of two only, so three friends cannot enter together.","zh":"烹飪比賽只限二人隊伍，所以三位朋友不能一起參賽。"},{"en":"Because the race required teams of two only, every contestant needed one partner.","zh":"因為比賽只限二人隊伍，每位參賽者都需要一位拍檔。"},{"en":"A rule of teams of two only forces participants to cooperate closely with one other person.","zh":"只限二人隊伍的規則迫使參賽者與另一個人緊密合作。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"mountains, river, meadow and maze","meaning":"山、河、草地和迷宮","examples":[{"en":"The course included mountains, a river, a meadow and a maze.","zh":"賽道包括山、河、草地和迷宮。"},{"en":"This phrase lists four different kinds of places or obstacles on the race route.","zh":"這個片語列出賽道路線上的四種不同地方或障礙。"},{"en":"Their journey crossed mountains, a river, a meadow and a maze, so no single skill was enough.","zh":"他們的旅程經過山、河、草地和迷宮，因此單靠一種技能並不足夠。"},{"en":"Different parts of the course tested climbing, swimming, speed and judgement.","zh":"賽道不同部分分別考驗攀爬、游泳、速度和判斷力。"},{"en":"A route containing mountains, a river, a meadow and a maze requires competitors to adapt to changing conditions.","zh":"包含山、河、草地和迷宮的路線要求參賽者適應不斷改變的環境。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"meadow","meaning":"草地","examples":[{"en":"The contestants had to cross the meadow.","zh":"參賽者必須穿過草地。"},{"en":"A meadow is an open area of grass, often found in the countryside and sometimes filled with wild flowers.","zh":"草地是一片開闊的青草地，常見於鄉郊，有時長滿野花。"},{"en":"Cows were grazing quietly in the green meadow.","zh":"牛群正在綠色草地上安靜地吃草。"},{"en":"The runners could move quickly across the meadow because there were few trees.","zh":"因為草地上樹木不多，跑手可以快速前進。"},{"en":"A wet meadow may look easy to cross but can become slippery after rain.","zh":"潮濕的草地看起來容易通過，但下雨後可能非常濕滑。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"maze","meaning":"迷宮","examples":[{"en":"The final part of the race was a maze.","zh":"比賽最後一部分是一個迷宮。"},{"en":"A maze is a network of paths designed to make it difficult to find the correct way through.","zh":"迷宮是由多條道路組成、令人難以找到正確出口的路線系統。"},{"en":"The children entered the garden maze and quickly lost their sense of direction.","zh":"孩子們走進花園迷宮，很快便失去方向感。"},{"en":"In a maze, moving fast is useless if you keep choosing the wrong path.","zh":"在迷宮中，如果不斷選錯路，跑得再快也沒有用。"},{"en":"A maze tests patience, memory and judgement rather than speed alone.","zh":"迷宮考驗耐性、記憶和判斷力，而不只是速度。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"first pair to cross the line","meaning":"首對衝線的組合","examples":[{"en":"The first pair to cross the line together would win.","zh":"首對一起衝線的組合便會勝出。"},{"en":"“The first pair to cross the line” means the two-person team that reaches and passes the finishing line before all others.","zh":"「the first pair to cross the line」表示最先到達並越過終點線的二人隊伍。"},{"en":"The first pair to cross the line received the gold medals.","zh":"首對衝線的組合獲得了金牌。"},{"en":"Because both partners had to arrive, one fast runner alone could not become the first pair to cross the line.","zh":"因為兩位拍檔都必須到達，所以只有一名快跑手不能成為首對衝線的組合。"},{"en":"In a team race, winning depends on when the whole pair finishes, not only the quickest member.","zh":"在團隊賽中，勝負取決於整個組合何時完成，而不是只看最快的成員。"}],"source":"2019 Q9.pdf","sourcePage":2},{"front":"cross the line together","meaning":"一起衝線","examples":[{"en":"Both partners had to cross the line together.","zh":"兩位拍檔都必須一起衝線。"},{"en":"To cross the line together means for both team members to pass the finishing line as a pair.","zh":"一起衝線是指兩名隊員以一對的形式越過終點線。"},{"en":"The runners slowed down near the end so they could cross the line together.","zh":"跑手接近終點時減慢速度，好讓他們一起衝線。"},{"en":"One partner could not win alone because the rules required them to cross the line together.","zh":"其中一位拍檔不能獨自取勝，因為規則要求他們一起衝線。"},{"en":"Crossing the line together shows that teamwork matters until the very end.","zh":"一起衝線表示團隊合作直到最後一刻仍然重要。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"by noon","meaning":"到了中午","examples":[{"en":"By noon, the clearing was buzzing.","zh":"到了中午，林中空地已經熱鬧起來。"},{"en":"“By noon” means at or before twelve o’clock in the middle of the day.","zh":"「by noon」表示在中午十二時或之前。"},{"en":"By noon, most students had already finished the morning examination.","zh":"到了中午，大部分學生已經完成早上的考試。"},{"en":"The market becomes crowded by noon as more shoppers arrive.","zh":"隨着更多顧客到來，市場到了中午便會變得擠迫。"},{"en":"If something must be completed by noon, it cannot be left until the afternoon.","zh":"如果某件事必須在中午前完成，就不能留到下午才做。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"the clearing","meaning":"林中空地","examples":[{"en":"The animals gathered in the clearing.","zh":"動物們聚集在林中空地。"},{"en":"A clearing is an open area in a forest where there are few or no trees.","zh":"林中空地是森林中樹木很少或完全沒有樹木的一片開闊地方。"},{"en":"The hikers stopped in a clearing to rest in the sunlight.","zh":"行山人士在一片林中空地停下來，在陽光下休息。"},{"en":"The clearing was large enough for all the animals to watch the race begin.","zh":"那片林中空地很大，足以讓所有動物觀看比賽開始。"},{"en":"A forest clearing often becomes a natural meeting place because there is more open space.","zh":"林中空地因空間較開揚，常自然成為聚會地點。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"be buzzing","meaning":"熱鬧起來；充滿興奮氣氛","examples":[{"en":"The clearing was buzzing with excitement.","zh":"林中空地充滿興奮氣氛。"},{"en":"To be buzzing means to be full of lively activity, conversation, excitement, or energy.","zh":"「be buzzing」表示某處充滿活躍活動、談話、興奮或活力。"},{"en":"The school hall was buzzing before the talent show began.","zh":"才藝表演開始前，學校禮堂已經熱鬧起來。"},{"en":"The market was buzzing with shoppers, music and conversation.","zh":"市場裏有顧客、音樂和談話聲，十分熱鬧。"},{"en":"A place starts buzzing when many excited people gather and something important is about to happen.","zh":"當很多興奮的人聚集，而重要事情即將發生時，一個地方便會熱鬧起來。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"clever and sharp-eyed","meaning":"聰明而眼利","examples":[{"en":"The fox and the weasel were clever and sharp-eyed.","zh":"狐狸和黃鼠狼都聰明而眼利。"},{"en":"“Clever and sharp-eyed” describes someone who thinks quickly and notices small details easily.","zh":"「clever and sharp-eyed」形容某人思考敏捷，而且容易留意細小細節。"},{"en":"A clever and sharp-eyed detective may notice a clue that everyone else misses.","zh":"聰明而眼利的偵探可能發現其他人錯過的線索。"},{"en":"The fox and weasel seemed strong competitors because they were both clever and sharp-eyed.","zh":"狐狸和黃鼠狼看起來是強勁對手，因為兩者都聰明而眼利。"},{"en":"Being clever and sharp-eyed is useful, but teamwork is still necessary when two people must cooperate.","zh":"聰明而眼利很有用，但如果兩人必須合作，團隊精神仍然不可缺少。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"sharp-eyed","meaning":"眼利的；眼光敏銳的","examples":[{"en":"The weasel was sharp-eyed and quick to notice danger.","zh":"黃鼠狼很眼利，很快便察覺危險。"},{"en":"Sharp-eyed means very good at noticing small details or changes.","zh":"「sharp-eyed」表示非常擅長發現細小細節或變化。"},{"en":"A sharp-eyed teacher noticed that one answer had been copied incorrectly.","zh":"一位眼利的老師發現其中一個答案抄錯了。"},{"en":"The sharp-eyed bird spotted movement in the grass from high above.","zh":"那隻眼光敏銳的鳥從高處發現草叢中的動靜。"},{"en":"Being sharp-eyed helps when danger or useful clues are difficult to see.","zh":"當危險或有用線索難以察覺時，眼利便非常有幫助。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"one strong and one nimble","meaning":"一個強壯、一個敏捷","examples":[{"en":"The stag and the squirrel made a team of one strong and one nimble.","zh":"鹿和松鼠組成了一隊，一個強壯、一個敏捷。"},{"en":"“One strong and one nimble” describes a pair in which one member has physical power and the other moves quickly and skilfully.","zh":"「one strong and one nimble」形容一對拍檔，其中一個有力量，另一個動作敏捷靈活。"},{"en":"The rescue team needed one strong person to lift boxes and one nimble person to climb through the small opening.","zh":"救援隊需要一個強壯的人搬箱子，以及一個敏捷的人穿過狹窄入口。"},{"en":"One strong and one nimble can form a useful partnership because their abilities are different.","zh":"一個強壯、一個敏捷可以組成很有用的拍檔，因為他們能力不同。"},{"en":"A balanced team often works well when one member can do what the other cannot.","zh":"當一名成員能做到另一名成員做不到的事情，均衡的團隊往往運作良好。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"nimble","meaning":"敏捷的","examples":[{"en":"The squirrel was small but nimble.","zh":"松鼠雖然細小，但十分敏捷。"},{"en":"Nimble means able to move quickly, lightly, and easily.","zh":"「nimble」表示能快速、輕巧而容易地移動。"},{"en":"The nimble child climbed over the playground equipment without difficulty.","zh":"那個敏捷的孩子毫不困難地爬過遊樂場設施。"},{"en":"Squirrels are nimble enough to jump between narrow branches.","zh":"松鼠很敏捷，可以在狹窄樹枝之間跳躍。"},{"en":"Being nimble is especially useful where quick changes of direction are needed.","zh":"在需要迅速改變方向的地方，敏捷尤其有用。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"at home in water","meaning":"熟習水性","examples":[{"en":"The otter was at home in water.","zh":"水獺非常熟習水性。"},{"en":"To be at home in water means to feel completely comfortable and skilled while swimming or moving in water.","zh":"「at home in water」表示在水中游泳或移動時非常自在而熟練。"},{"en":"A strong swimmer feels at home in water even when the pool is deep.","zh":"一位游泳健將即使泳池很深，也會在水中感到非常自在。"},{"en":"The otter was at home in water, so crossing the river was easy for it.","zh":"水獺熟習水性，所以過河對牠來說很容易。"},{"en":"Someone who is at home in a particular environment behaves there naturally and confidently.","zh":"一個人在某種環境中「at home」，表示他在那裏表現自然又有信心。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"in the air","meaning":"在空中","examples":[{"en":"The kingfisher was quick in the air.","zh":"翠鳥在空中動作很快。"},{"en":"“In the air” means while flying or moving above the ground.","zh":"「in the air」表示在飛行或離開地面移動時。"},{"en":"The eagle changed direction quickly in the air.","zh":"老鷹在空中迅速改變方向。"},{"en":"Birds that are skilled in the air can cross obstacles without touching the ground.","zh":"擅長在空中活動的鳥，可以不接觸地面便越過障礙。"},{"en":"Different animals are strongest in different environments, such as water, land or the air.","zh":"不同動物在不同環境最有優勢，例如水中、陸地或空中。"}],"source":"2019 Q9.pdf","sourcePage":3},{"front":"stand alone","meaning":"獨自站着","examples":[{"en":"The hare stood alone, pretending not to care.","zh":"野兔獨自站着，假裝自己不在乎。"},{"en":"To stand alone means to remain by yourself without anyone beside you.","zh":"「stand alone」表示身邊沒有其他人，自己一個站着。"},{"en":"The new student stood alone until someone invited her to join the group.","zh":"那位新同學獨自站着，直到有人邀請她加入小組。"},{"en":"The hare stood alone because every other contestant had already found a partner.","zh":"野兔獨自站着，因為其他參賽者已經找到拍檔。"},{"en":"Standing alone can make someone look independent even when they actually feel uncertain.","zh":"獨自站着可以令人看起來很獨立，即使內心其實不安。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"pretend not to care","meaning":"假裝不在乎","examples":[{"en":"The hare pretended not to care about the race.","zh":"野兔假裝不在乎這場比賽。"},{"en":"To pretend not to care means to act as if something does not matter even though it actually does.","zh":"「pretend not to care」表示裝作某件事並不重要，即使心裏其實很在意。"},{"en":"He pretended not to care about the result, but he checked his score several times.","zh":"他假裝不在乎結果，卻查看自己的分數好幾次。"},{"en":"The hare pretended not to care because admitting his disappointment would have been embarrassing.","zh":"野兔假裝不在乎，因為承認自己失望會令他覺得尷尬。"},{"en":"People sometimes pretend not to care in order to protect their pride.","zh":"人有時會假裝不在乎，以保護自己的自尊。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"a calm voice","meaning":"平靜的聲音","examples":[{"en":"A calm voice came from behind him.","zh":"一把平靜的聲音從他身後傳來。"},{"en":"A calm voice is a way of speaking that sounds peaceful, controlled, and not anxious or angry.","zh":"平靜的聲音是聽起來安定、有控制，而且不焦急或憤怒的說話方式。"},{"en":"The nurse used a calm voice to reassure the frightened child.","zh":"護士用平靜的聲音安慰那個受驚的孩子。"},{"en":"A calm voice can reduce tension when two people disagree.","zh":"當兩個人意見不合時，平靜的聲音可以減少緊張氣氛。"},{"en":"Hearing a calm voice in a stressful moment can make a difficult situation feel more manageable.","zh":"在壓力大的時刻聽到平靜的聲音，可以令困難情況感覺較容易處理。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"enter together","meaning":"一起參賽","examples":[{"en":"The tortoise suggested that they enter together.","zh":"陸龜建議他們一起參賽。"},{"en":"To enter together means to join a competition, event, or place as a pair at the same time.","zh":"一起參賽是指以一對拍檔的身分，同時加入比賽或活動。"},{"en":"The sisters decided to enter the singing contest together.","zh":"兩姊妹決定一起參加歌唱比賽。"},{"en":"Because the challenge required partners, the tortoise asked the hare to enter together with him.","zh":"因為這項挑戰需要拍檔，陸龜邀請野兔和他一起參賽。"},{"en":"Entering together means accepting that success and failure will be shared.","zh":"一起參賽表示接受成功與失敗都要共同承擔。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"spin round","meaning":"猛地轉身","examples":[{"en":"The hare spun round when he heard the tortoise.","zh":"野兔聽到陸龜的聲音後猛地轉身。"},{"en":"To spin round means to turn your whole body around very quickly.","zh":"「spin round」表示非常迅速地把整個身體轉向後方。"},{"en":"She spun round when someone suddenly called her name from behind.","zh":"有人突然從後面叫她的名字時，她猛地轉身。"},{"en":"The hare spun round because he was surprised to hear the tortoise’s voice.","zh":"野兔猛地轉身，因為聽到陸龜的聲音令他很驚訝。"},{"en":"People often spin round when an unexpected sound immediately attracts their attention.","zh":"當突如其來的聲音立即吸引注意時，人常會猛地轉身。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"after what happened","meaning":"在發生那件事之後","examples":[{"en":"The hare was surprised to team up after what happened.","zh":"在發生那件事之後，野兔對於要合作感到很驚訝。"},{"en":"“After what happened” refers to a previous event that both people already know about.","zh":"「after what happened」指雙方都知道的某件較早發生的事情。"},{"en":"After what happened during their last argument, she was surprised he invited her again.","zh":"在上次爭吵發生那件事之後，她很驚訝他再次邀請自己。"},{"en":"The hare found partnership strange after what happened in their famous race.","zh":"在昔日那場著名比賽發生那件事之後，野兔覺得合作十分奇怪。"},{"en":"This phrase is useful when the earlier event is obvious from the context and does not need to be repeated.","zh":"當較早發生的事件從上下文已很清楚，不需要重複說明時，可以使用這個片語。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"because of what happened","meaning":"正正因為發生過那件事","examples":[{"en":"The tortoise wanted to team up because of what happened.","zh":"陸龜正正因為發生過那件事，所以想與野兔組隊。"},{"en":"“Because of what happened” means that a previous event is the reason for a present decision or feeling.","zh":"「because of what happened」表示之前發生的事情是現在決定或感受的原因。"},{"en":"Because of what happened during the storm, the school introduced new safety rules.","zh":"正正因為暴風雨期間發生過那件事，學校推出了新的安全規則。"},{"en":"The tortoise wanted a new partnership because of what happened in the first race.","zh":"陸龜正正因為第一次比賽發生過的事，所以想建立新的合作關係。"},{"en":"Past failures can become useful when people change their behaviour because of what happened.","zh":"如果人們因為發生過的事情而改變行為，過去的失敗也可以變得有用。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"know speed","meaning":"懂得速度","examples":[{"en":"The hare knew speed better than anyone.","zh":"野兔比任何人都更懂得速度。"},{"en":"To know speed means to understand how to move quickly and use speed effectively.","zh":"「know speed」表示明白如何快速移動和有效運用速度。"},{"en":"Experienced racing drivers know speed, but they also know when to slow down.","zh":"有經驗的賽車手懂得速度，但也知道何時需要減速。"},{"en":"The hare knew speed because running fast had always been his greatest strength.","zh":"野兔懂得速度，因為快速奔跑一直是他最大的長處。"},{"en":"Knowing speed is useful, but a difficult course may require other abilities too.","zh":"懂得速度很有用，但困難賽道可能還需要其他能力。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"know patience","meaning":"懂得耐性","examples":[{"en":"The tortoise knew patience better than anyone.","zh":"陸龜比任何人都更懂得耐性。"},{"en":"To know patience means to understand how to wait, continue calmly, and avoid rushing.","zh":"「know patience」表示懂得等待、冷靜堅持，以及避免急躁。"},{"en":"Good gardeners know patience because plants need time to grow.","zh":"好園丁懂得耐性，因為植物需要時間生長。"},{"en":"The tortoise knew patience because he could continue steadily without becoming frustrated.","zh":"陸龜懂得耐性，因為他可以穩定前進而不感到煩躁。"},{"en":"Knowing patience helps when progress is slow and rushing would cause mistakes.","zh":"當進展緩慢而急於求成會造成錯誤時，懂得耐性非常重要。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"neither of us","meaning":"我們兩個都不","examples":[{"en":"Neither of us knows enough alone.","zh":"我們兩個單靠自己都懂得不夠多。"},{"en":"“Neither of us” means not one and not the other of two people.","zh":"「neither of us」表示兩個人之中，這個不，那個也不。"},{"en":"Neither of us can lift this cupboard by ourselves, so we need help.","zh":"我們兩個都無法獨自抬起這個櫃，所以需要幫助。"},{"en":"Neither of us had visited the city before, so we checked the map together.","zh":"我們兩個以前都沒有去過這個城市，所以一起查看地圖。"},{"en":"“Neither of us” emphasises that the statement is true for both people in a pair.","zh":"「neither of us」強調某個說法對一對人中的兩者都成立。"}],"source":"2019 Q9.pdf","sourcePage":4},{"front":"know enough alone","meaning":"單靠自己知道得不夠","examples":[{"en":"Neither of them knew enough alone.","zh":"他們兩個單靠自己都知道得不夠。"},{"en":"To know enough alone means to have all the knowledge needed without another person’s help.","zh":"「know enough alone」表示不需要別人幫助，自己已具備所需的全部知識。"},{"en":"Neither student knew enough alone to solve every part of the difficult problem.","zh":"兩位學生單靠自己都知道得不夠，無法解決困難問題的所有部分。"},{"en":"The hare understood speed and the tortoise understood patience, but neither knew enough alone.","zh":"野兔明白速度，陸龜明白耐性，但兩者單靠自己都知道得不夠。"},{"en":"Admitting that you do not know enough alone can be the first step towards useful cooperation.","zh":"承認自己單靠自己知道得不夠，可以是有效合作的第一步。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"want to prove that","meaning":"想證明","examples":[{"en":"The hare wanted to prove that he could win without help.","zh":"野兔想證明自己可以不靠幫助而勝出。"},{"en":"To want to prove that something is true means to strongly wish to demonstrate it through evidence or action.","zh":"想證明某件事是真的，表示很希望透過證據或行動把它展示出來。"},{"en":"She wanted to prove that she could complete the project without special treatment.","zh":"她想證明自己不用特殊待遇也能完成項目。"},{"en":"The hare wanted to prove that his speed was enough to win.","zh":"野兔想證明自己的速度已足以取勝。"},{"en":"Wanting to prove something can motivate people, but pride can also stop them accepting help.","zh":"想證明某件事可以帶來動力，但自尊也可能令人拒絕幫助。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"win without help","meaning":"不靠幫助而取勝","examples":[{"en":"The hare wanted to win without help.","zh":"野兔想不靠幫助而取勝。"},{"en":"To win without help means to succeed in a competition entirely through your own efforts.","zh":"不靠幫助而取勝是指完全依靠自己的努力在比賽中成功。"},{"en":"The student wanted to solve the puzzle and win without help from the teacher.","zh":"那名學生想自己解開謎題，不靠老師幫助而勝出。"},{"en":"The hare believed winning without help would prove how capable he was.","zh":"野兔相信不靠幫助而取勝可以證明自己有多能幹。"},{"en":"Some challenges are designed so that nobody can win without help from a partner.","zh":"有些挑戰刻意設計成沒有人可以在沒有拍檔幫助下獲勝。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"the course stretched beyond","meaning":"賽道延伸至……以外","examples":[{"en":"The course stretched beyond the meadow.","zh":"賽道延伸至草地以外。"},{"en":"“The course stretched beyond” means the route continued farther than a particular place.","zh":"「the course stretched beyond」表示路線繼續延伸到某個地方之外。"},{"en":"The walking trail stretched beyond the village and into the hills.","zh":"步行徑延伸至村莊以外，進入山區。"},{"en":"The race looked simple at first, but the course stretched beyond the meadow towards harder obstacles.","zh":"比賽起初看起來很簡單，但賽道延伸至草地以外，通往更困難的障礙。"},{"en":"When a route stretches beyond what you can see, more challenges may still lie ahead.","zh":"當路線延伸至視線以外，前方可能仍有更多挑戰。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"beyond the meadow","meaning":"在草地之外","examples":[{"en":"The race went beyond the meadow and across the river.","zh":"比賽路線延伸至草地之外，並橫過河流。"},{"en":"“Beyond the meadow” means farther than the grassy field or on the other side of it.","zh":"「beyond the meadow」表示在那片草地更遠之處或另一邊。"},{"en":"Beyond the meadow, the path climbed sharply into the hills.","zh":"在草地之外，小路陡峭地向山上延伸。"},{"en":"The runners could not see the river until they travelled beyond the meadow.","zh":"跑手直到走到草地之外才看見河流。"},{"en":"What lies beyond a familiar place may require very different skills.","zh":"熟悉地方之外的環境，可能需要完全不同的技能。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"thorn maze","meaning":"荊棘迷宮","examples":[{"en":"The course led into the thorn maze.","zh":"賽道通往荊棘迷宮。"},{"en":"A thorn maze is a maze formed by plants or branches covered with sharp thorns.","zh":"荊棘迷宮是由帶有尖刺的植物或樹枝形成的迷宮。"},{"en":"The hikers moved slowly through the thorn maze to avoid scratching their arms.","zh":"行山人士緩慢穿過荊棘迷宮，以免手臂被刮傷。"},{"en":"The thorn maze was difficult because its narrow paths could trap careless competitors.","zh":"荊棘迷宮很困難，因為狹窄路徑可能困住粗心的參賽者。"},{"en":"In a thorn maze, rushing can be dangerous because the branches may catch your clothes or body.","zh":"在荊棘迷宮中急着前進可能很危險，因為樹枝可能勾住衣服或身體。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"there was no getting around the fact that","meaning":"無法迴避……這個事實","examples":[{"en":"There was no getting around the fact that speed alone would not be enough.","zh":"無法迴避單靠速度並不足夠這個事實。"},{"en":"“There was no getting around the fact that” means an important truth could not be avoided, denied, or ignored.","zh":"「there was no getting around the fact that」表示某個重要事實無法逃避、否認或忽略。"},{"en":"There was no getting around the fact that the project would cost more than expected.","zh":"無法迴避這個事實：項目成本會比預期高。"},{"en":"The hare disliked admitting it, but there was no getting around the fact that he needed a partner.","zh":"野兔雖然不喜歡承認，但無法迴避自己需要拍檔這個事實。"},{"en":"This phrase is used when evidence makes a conclusion unavoidable.","zh":"當證據令某個結論無法避免時，可以使用這個片語。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"speed alone","meaning":"單靠速度","examples":[{"en":"Speed alone would not be enough to win the race.","zh":"單靠速度並不足以贏得比賽。"},{"en":"“Speed alone” means speed by itself, without help from judgement, patience, teamwork, or another ability.","zh":"「speed alone」表示只靠速度，而沒有判斷力、耐性、合作或其他能力。"},{"en":"Speed alone cannot help a driver if they choose the wrong road.","zh":"如果駕駛者選錯道路，單靠速度也沒有用。"},{"en":"The river and maze showed that speed alone could not solve every problem.","zh":"河流和迷宮證明單靠速度不能解決所有問題。"},{"en":"One strength alone is often insufficient when a challenge requires several different skills.","zh":"當挑戰需要幾種不同技能時，單靠一項長處通常並不足夠。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"would not be enough","meaning":"並不足夠","examples":[{"en":"The hare realised that speed alone would not be enough.","zh":"野兔明白單靠速度並不足夠。"},{"en":"“Would not be enough” means something would be insufficient to achieve the required result.","zh":"「would not be enough」表示某件事不足以達成所需結果。"},{"en":"One hour of study would not be enough to prepare for the entire examination.","zh":"只溫習一小時並不足夠準備整個考試。"},{"en":"Running fast would not be enough because both partners had to finish together.","zh":"跑得快並不足夠，因為兩位拍檔都必須一起完成。"},{"en":"Realising that one ability would not be enough can encourage people to seek help or develop new skills.","zh":"明白一項能力並不足夠，可以鼓勵人尋求幫助或發展新技能。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"nod","meaning":"點頭","examples":[{"en":"The hare nodded and agreed to race with the tortoise.","zh":"野兔點頭，同意與陸龜一起比賽。"},{"en":"To nod means to move your head down and up, often to show agreement, understanding, or greeting.","zh":"點頭是指把頭向下再抬起，通常表示同意、明白或打招呼。"},{"en":"The student nodded when the teacher asked whether the instructions were clear.","zh":"老師問指示是否清楚時，那名學生點頭。"},{"en":"The hare nodded instead of arguing, showing that he accepted the tortoise’s idea.","zh":"野兔沒有爭辯，而是點頭，表示接受陸龜的建議。"},{"en":"A simple nod can communicate agreement without any words.","zh":"一個簡單的點頭可以不用說話便表達同意。"}],"source":"2019 Q9.pdf","sourcePage":5},{"front":"if we lose","meaning":"如果我們輸了","examples":[{"en":"The hare worried about what would happen if they lost.","zh":"野兔擔心如果他們輸了會發生甚麼。"},{"en":"“If we lose” introduces a possible future situation in which the speaker and another person fail to win.","zh":"「if we lose」帶出一個可能的未來情況：說話者和另一個人未能取勝。"},{"en":"If we lose this match, we will congratulate the other team and practise harder.","zh":"如果我們輸了這場比賽，我們會恭喜對手並更加努力練習。"},{"en":"The hare was worried about embarrassment if they lost the race together.","zh":"野兔擔心如果他們一起輸掉比賽會很尷尬。"},{"en":"Thinking about what happens if we lose can reveal whether we are prepared to share responsibility.","zh":"思考「如果我們輸了」會怎樣，可以反映我們是否準備好共同承擔責任。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"lose together","meaning":"一起輸","examples":[{"en":"The tortoise said they would lose together.","zh":"陸龜說他們會一起輸。"},{"en":"To lose together means for both partners to share the same defeat instead of blaming one another.","zh":"一起輸表示兩位拍檔共同承受失敗，而不是互相責怪。"},{"en":"The players promised that if the team failed, they would lose together and learn together.","zh":"隊員承諾，如果球隊失敗，他們會一起輸，也會一起學習。"},{"en":"The tortoise accepted that partnership meant they might win together or lose together.","zh":"陸龜接受了合作的意義：他們可能一起贏，也可能一起輸。"},{"en":"Teams become stronger when members can lose together without turning against each other.","zh":"團隊成員如果能一起輸而不互相攻擊，團隊會變得更強。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"at dawn","meaning":"黎明時分","examples":[{"en":"At dawn the next day, the contestants lined up.","zh":"第二天黎明時分，參賽者列隊站好。"},{"en":"“At dawn” means at the time early in the morning when daylight first begins to appear.","zh":"「at dawn」表示清晨第一道日光開始出現的時候。"},{"en":"The fishermen left the harbour at dawn before the sea became busy.","zh":"漁民在黎明時分離開港口，趁海面還未繁忙。"},{"en":"At dawn, the forest slowly changed from darkness to pale morning light.","zh":"黎明時分，森林慢慢由黑暗變成淡淡的晨光。"},{"en":"Starting at dawn means beginning very early, often before most people are awake.","zh":"在黎明開始意味着非常早開始，通常大部分人仍未起床。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"contestants","meaning":"參賽者","examples":[{"en":"The contestants lined up beneath fluttering leaves.","zh":"參賽者在飄動的樹葉下列隊。"},{"en":"Contestants are people or teams who take part in a competition.","zh":"參賽者是參加比賽的人或隊伍。"},{"en":"All contestants had to register before entering the singing contest.","zh":"所有參賽者參加歌唱比賽前都必須登記。"},{"en":"The contestants waited nervously for the race to begin.","zh":"參賽者緊張地等待比賽開始。"},{"en":"Contestants compete against one another according to the same rules.","zh":"參賽者按照同一套規則彼此競爭。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"line up","meaning":"排成一列；列隊","examples":[{"en":"The contestants lined up before the race began.","zh":"比賽開始前，參賽者列隊站好。"},{"en":"To line up means to stand or arrange people one behind another or side by side in an orderly row.","zh":"「line up」表示把人有秩序地一個接一個或並排排成一列。"},{"en":"Students lined up outside the classroom before entering.","zh":"學生進入課室前在門外排成一列。"},{"en":"The runners lined up at the starting point when the official called them forward.","zh":"工作人員叫跑手上前時，他們在起點列隊站好。"},{"en":"Lining up keeps a group organised when many people need to begin from the same place.","zh":"當很多人需要從同一地點開始時，列隊可以保持秩序。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"beneath fluttering leaves","meaning":"在飄動的樹葉下","examples":[{"en":"The contestants stood beneath fluttering leaves.","zh":"參賽者站在飄動的樹葉下。"},{"en":"“Beneath fluttering leaves” means under leaves that are moving lightly in the wind.","zh":"「beneath fluttering leaves」表示在被風吹得輕輕擺動的樹葉下面。"},{"en":"The children ate lunch beneath fluttering leaves in the park.","zh":"孩子們在公園飄動的樹葉下吃午餐。"},{"en":"Sunlight moved across the ground beneath fluttering leaves.","zh":"陽光在飄動的樹葉下的地面上移動。"},{"en":"This description creates an image of a gentle breeze moving through the trees above.","zh":"這個描述營造出微風輕輕吹動頭頂樹葉的畫面。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"fluttering leaves","meaning":"飄動的樹葉","examples":[{"en":"Fluttering leaves moved above the contestants.","zh":"飄動的樹葉在參賽者頭頂移動。"},{"en":"Fluttering leaves are leaves that move lightly and quickly because of a gentle wind.","zh":"飄動的樹葉是受到微風吹動而輕快擺動的樹葉。"},{"en":"The fluttering leaves made soft sounds outside the window.","zh":"窗外飄動的樹葉發出輕柔聲音。"},{"en":"In autumn, fluttering leaves fell from the branches and crossed the path.","zh":"秋天時，飄動的樹葉從樹枝落下，掠過小路。"},{"en":"“Fluttering” suggests light, repeated movement rather than strong or violent motion.","zh":"「fluttering」表示輕柔而重複的移動，而不是猛烈動作。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"raise one wing","meaning":"舉起一邊翅膀","examples":[{"en":"The owl raised one wing to start the race.","zh":"貓頭鷹舉起一邊翅膀，準備開始比賽。"},{"en":"To raise one wing means for a bird to lift one of its wings upward.","zh":"「raise one wing」表示鳥把其中一邊翅膀向上舉起。"},{"en":"The bird raised one wing while balancing on the branch.","zh":"那隻鳥站在樹枝上保持平衡時，舉起了一邊翅膀。"},{"en":"The owl raised one wing as a clear signal that the race was about to begin.","zh":"貓頭鷹舉起一邊翅膀，清楚示意比賽即將開始。"},{"en":"A simple physical signal can replace spoken instructions when everyone knows what it means.","zh":"當所有人都明白意思時，簡單的身體訊號可以代替口頭指示。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"both members","meaning":"兩名隊員","examples":[{"en":"Both members must finish together.","zh":"兩名隊員都必須一起完成。"},{"en":"“Both members” means the two people who belong to the same pair or team.","zh":"「both members」表示屬於同一組合或隊伍的兩個人。"},{"en":"Both members of the project group must attend the final presentation.","zh":"項目小組的兩名隊員都必須出席最後匯報。"},{"en":"Both members were responsible for checking that the equipment was safe.","zh":"兩名隊員都有責任檢查設備是否安全。"},{"en":"When both members share responsibility, neither person can simply leave all the work to the other.","zh":"當兩名隊員共同承擔責任，其中一個就不能把所有工作留給另一個。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"finish together","meaning":"一起完成","examples":[{"en":"The rules required both members to finish together.","zh":"規則要求兩名隊員一起完成。"},{"en":"To finish together means to reach the end as a pair rather than separately.","zh":"一起完成是指以一對拍檔的形式到達終點，而不是分開完成。"},{"en":"The cyclists slowed down so they could finish together.","zh":"單車手減慢速度，好讓他們一起完成。"},{"en":"The race tested cooperation because both partners had to finish together.","zh":"因為兩位拍檔都要一起完成，這場比賽考驗合作。"},{"en":"Finishing together means helping a slower partner instead of abandoning them near the end.","zh":"一起完成意味着要幫助較慢的拍檔，而不是在接近終點時拋下對方。"}],"source":"2019 Q9.pdf","sourcePage":6},{"front":"mutter","meaning":"低聲咕噥","examples":[{"en":"The hare muttered the word “together.”","zh":"野兔低聲咕噥着「一起」這個詞。"},{"en":"To mutter means to speak in a very low voice, often because you are annoyed, embarrassed, or speaking to yourself.","zh":"「mutter」表示以很低的聲音說話，通常因為生氣、尷尬或在自言自語。"},{"en":"The student muttered an apology that the teacher could hardly hear.","zh":"那名學生低聲咕噥着道歉，老師幾乎聽不見。"},{"en":"The hare muttered because he still felt uncomfortable about depending on a partner.","zh":"野兔低聲咕噥，因為他對依靠拍檔仍感到不自在。"},{"en":"People often mutter when they do not want everyone around them to hear what they are saying.","zh":"當人不想周圍每個人都聽到自己的說話時，常會低聲咕噥。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"as if","meaning":"好像","examples":[{"en":"The hare spoke as if the word were heavy.","zh":"野兔說出那個詞時，好像它很沉重。"},{"en":"“As if” means in a way that makes something seem true, even when it may only be an impression or comparison.","zh":"「as if」表示以某種方式令事情看起來是真的，即使那可能只是一種感覺或比較。"},{"en":"He stared at the empty room as if he had seen a ghost.","zh":"他望着空蕩蕩的房間，好像見到了鬼一樣。"},{"en":"The child held the old photograph as if it were something extremely valuable.","zh":"那個孩子拿着舊照片，好像它是極為珍貴的東西。"},{"en":"Writers use “as if” to compare a feeling or action with an imagined situation.","zh":"作家使用「as if」把一種感受或行動與想像中的情況作比較。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"heavier than a boulder","meaning":"比巨石更重","examples":[{"en":"The word felt heavier than a boulder to the hare.","zh":"對野兔來說，那個詞感覺比巨石更重。"},{"en":"“Heavier than a boulder” is an exaggeration showing that something feels emotionally extremely difficult or burdensome.","zh":"「heavier than a boulder」是一種誇張說法，表示某件事情在情感上極難承受。"},{"en":"Admitting the mistake felt heavier than a boulder because he was so proud.","zh":"因為他非常驕傲，承認錯誤對他來說感覺比巨石更重。"},{"en":"The word “together” felt heavier than a boulder because it forced the hare to accept dependence on someone else.","zh":"「一起」這個詞感覺比巨石更重，因為它迫使野兔接受要依靠別人。"},{"en":"Writers compare emotional burdens with heavy objects to make the feeling easier to imagine.","zh":"作家把情感負擔比作沉重物件，可以令讀者更容易想像那種感受。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"boulder","meaning":"巨石","examples":[{"en":"The hare felt as if the word were heavier than a boulder.","zh":"野兔覺得那個詞好像比巨石更重。"},{"en":"A boulder is a very large, heavy rock.","zh":"巨石是一塊非常巨大而沉重的石頭。"},{"en":"The hikers had to walk around a huge boulder blocking the path.","zh":"行山人士要繞過堵住小路的一塊巨大巨石。"},{"en":"A boulder can be too heavy for one person to move without equipment.","zh":"巨石可能重得一個人不用工具便無法移動。"},{"en":"Because a boulder is extremely heavy, it is often used in comparisons to describe a great burden.","zh":"因為巨石非常沉重，所以常被用來比喻巨大的負擔。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"No sooner had… than…","meaning":"一……就……","examples":[{"en":"No sooner had the race begun than the hare shot forward.","zh":"比賽一開始，野兔就飛奔向前。"},{"en":"“No sooner had A happened than B happened” means B happened immediately after A.","zh":"「No sooner had A happened than B happened」表示A一發生，B便立即發生。"},{"en":"No sooner had the teacher left the room than the students began talking.","zh":"老師一離開課室，學生就開始說話。"},{"en":"No sooner had the doors opened than shoppers rushed inside.","zh":"大門一打開，顧客就衝進去。"},{"en":"This structure emphasises that almost no time passed between two events.","zh":"這個句式強調兩件事之間幾乎沒有時間間隔。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"shoot forward","meaning":"飛奔向前","examples":[{"en":"The hare shot forward like an arrow.","zh":"野兔像箭一樣飛奔向前。"},{"en":"To shoot forward means to move ahead suddenly and extremely quickly.","zh":"「shoot forward」表示突然而非常快速地向前移動。"},{"en":"The cyclist shot forward as soon as the traffic light turned green.","zh":"交通燈一轉綠，那名單車手便飛奔向前。"},{"en":"The hare shot forward because speed was his natural strength.","zh":"野兔飛奔向前，因為速度是他的天生長處。"},{"en":"Someone who shoots forward may gain distance quickly but can miss warnings or obstacles.","zh":"飛奔向前的人可以迅速拉開距離，但也可能錯過警告或障礙。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"like an arrow","meaning":"像箭一樣","examples":[{"en":"The hare shot forward like an arrow.","zh":"野兔像箭一樣飛奔向前。"},{"en":"“Like an arrow” compares very fast, straight movement with an arrow flying through the air.","zh":"「like an arrow」把快速而筆直的移動比作箭在空中飛行。"},{"en":"The racing car moved down the straight road like an arrow.","zh":"賽車像箭一樣沿着直路高速前進。"},{"en":"The dog ran towards its owner like an arrow as soon as the gate opened.","zh":"大門一打開，那隻狗就像箭一樣奔向主人。"},{"en":"This comparison helps the reader imagine sudden, direct speed.","zh":"這個比喻幫助讀者想像突然、直接而快速的移動。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"call after someone","meaning":"在某人身後喊","examples":[{"en":"The tortoise called after the hare.","zh":"陸龜在野兔身後喊他。"},{"en":"To call after someone means to shout to a person who is moving away from you.","zh":"「call after someone」表示向正在離開自己的人大聲喊話。"},{"en":"She called after her brother when he left his wallet on the table.","zh":"她的弟弟把錢包留在桌上，她便在他身後喊他。"},{"en":"The tortoise called after the hare because he was already racing far ahead.","zh":"陸龜在野兔身後喊，因為野兔已經跑到很前面。"},{"en":"Calling after someone is useful when you need their attention before they get too far away.","zh":"當某人正走遠，而你需要在他走得太遠前引起注意，可以在他身後喊。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"the middle path","meaning":"中間的小路","examples":[{"en":"The tortoise warned the hare not to take the middle path.","zh":"陸龜警告野兔不要走中間的小路。"},{"en":"The middle path is the route positioned between two other paths or sides.","zh":"中間的小路是位於其他兩條道路或兩側之間的路線。"},{"en":"At the fork, the middle path looked shortest but was covered in wet mud.","zh":"到了岔路，中間的小路看起來最短，卻滿是濕泥。"},{"en":"The tortoise avoided the middle path because he had noticed the ground was dangerous.","zh":"陸龜避開中間的小路，因為他已察覺地面很危險。"},{"en":"The most direct-looking path is not always the safest or fastest route.","zh":"看起來最直接的道路，不一定是最安全或最快的路線。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"for once","meaning":"這一次；難得一次","examples":[{"en":"For once, the hare listened to the tortoise.","zh":"這一次，野兔聽從了陸龜的話。"},{"en":"“For once” means on this particular occasion, especially when someone usually behaves differently.","zh":"「for once」表示在這一次特別的情況下，尤其當某人平時通常不是這樣做。"},{"en":"For once, the usually late student arrived ten minutes early.","zh":"那個平時常遲到的學生難得一次早了十分鐘到達。"},{"en":"The hare normally trusted his own judgement, but for once he listened to advice.","zh":"野兔平時總相信自己的判斷，但這一次他聽取了建議。"},{"en":"“For once” often highlights a surprising change from someone’s normal behaviour.","zh":"「for once」常用來突出某人與平常不同而令人意外的行為。"}],"source":"2019 Q9.pdf","sourcePage":7},{"front":"curve towards","meaning":"轉向","examples":[{"en":"The hare curved towards the dry ridge.","zh":"野兔轉向乾爽的山脊。"},{"en":"To curve towards something means to change direction gradually in a bending path towards it.","zh":"「curve towards」表示沿彎曲路線逐漸改變方向，朝某處前進。"},{"en":"The road curved towards the coast after leaving the village.","zh":"公路離開村莊後逐漸轉向海岸。"},{"en":"Instead of running straight ahead, the hare curved towards the safer ridge.","zh":"野兔沒有直衝向前，而是轉向較安全的山脊。"},{"en":"Curving towards a destination is a gradual change of direction rather than a sudden turn.","zh":"朝某處彎去是一種逐漸改變方向，而不是突然轉彎。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"dry ridge","meaning":"乾爽的山脊；高地","examples":[{"en":"The hare ran along the dry ridge.","zh":"野兔沿着乾爽的山脊奔跑。"},{"en":"A dry ridge is a raised narrow area of land that is not wet or muddy.","zh":"乾爽的山脊是一條較高而狹窄、不濕滑也不泥濘的地帶。"},{"en":"The walkers chose the dry ridge because the lower ground was flooded.","zh":"行山人士選擇乾爽的山脊，因為較低的地方已經水浸。"},{"en":"Running along the dry ridge gave the hare firmer ground under his feet.","zh":"沿着乾爽的山脊跑，野兔腳下有較穩固的地面。"},{"en":"A raised dry route can be safer than a wet field after heavy rain.","zh":"大雨過後，較高而乾爽的路線可能比濕草地更安全。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"slip","meaning":"滑倒","examples":[{"en":"The stag slipped on the wet grass.","zh":"鹿在濕草地上滑倒。"},{"en":"To slip means to lose your footing and slide unexpectedly, often because the surface is wet or smooth.","zh":"「slip」表示因表面濕滑或光滑而突然失去立足點並滑動。"},{"en":"She slipped on the kitchen floor because someone had spilled water.","zh":"因為有人把水倒在廚房地板上，她滑倒了。"},{"en":"The stag slipped when its feet could not grip the wet grass properly.","zh":"鹿的腳無法抓穩濕草地，因此滑倒。"},{"en":"Walking more slowly can reduce the chance of slipping on a dangerous surface.","zh":"在危險表面慢一點走，可以減少滑倒的機會。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"send someone tumbling","meaning":"令某人摔倒","examples":[{"en":"The stag slipped, sending the squirrel tumbling into a mushroom patch.","zh":"鹿滑倒了，令松鼠摔進蘑菇叢。"},{"en":"To send someone tumbling means to cause them to fall and roll or move uncontrollably.","zh":"「send someone tumbling」表示令某人跌倒、翻滾或失去控制地移動。"},{"en":"The sudden push sent the boxes tumbling down the stairs.","zh":"突然的一推令箱子翻滾着掉下樓梯。"},{"en":"When the stag slipped, the movement sent the squirrel tumbling away from its back.","zh":"鹿滑倒時，動作令松鼠從牠背上摔了出去。"},{"en":"One person losing balance can send another person tumbling if they are moving together.","zh":"如果兩個人一起移動，其中一人失去平衡也可能令另一個人摔倒。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"mushroom patch","meaning":"蘑菇叢","examples":[{"en":"The squirrel tumbled into a mushroom patch.","zh":"松鼠摔進了一片蘑菇叢。"},{"en":"A mushroom patch is a small area where many mushrooms are growing together.","zh":"蘑菇叢是一小片長着很多蘑菇的地方。"},{"en":"After several days of rain, a mushroom patch appeared beside the fallen tree.","zh":"下了幾天雨後，倒下的樹旁出現了一片蘑菇叢。"},{"en":"The squirrel landed among the soft mushrooms in the mushroom patch.","zh":"松鼠跌落在蘑菇叢中柔軟的蘑菇之間。"},{"en":"A “patch” is often used for a small area covered by one particular kind of plant.","zh":"「patch」常用來表示長滿某一種植物的一小片地方。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"laugh too soon","meaning":"笑得太早","examples":[{"en":"The fox laughed too soon and then made a mistake.","zh":"狐狸笑得太早，之後自己也犯了錯。"},{"en":"To laugh too soon means to celebrate another person’s failure before you are safely successful yourself.","zh":"「laugh too soon」表示自己尚未確定成功，就先嘲笑或慶祝別人的失敗。"},{"en":"He laughed too soon when his opponent missed one question, because he later missed two.","zh":"對手答錯一道題時他笑得太早，因為後來自己錯了兩題。"},{"en":"The fox laughed too soon because his own shortcut soon caused trouble.","zh":"狐狸笑得太早，因為牠自己的捷徑很快便帶來麻煩。"},{"en":"Laughing too soon can be embarrassing when the situation suddenly changes against you.","zh":"如果情況突然對自己不利，笑得太早會令人非常尷尬。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"take a shortcut","meaning":"抄捷徑","examples":[{"en":"The fox took a shortcut through mud.","zh":"狐狸抄捷徑穿過泥濘。"},{"en":"To take a shortcut means to choose a shorter route in order to reach somewhere faster.","zh":"抄捷徑是指選擇較短的路線，希望更快到達目的地。"},{"en":"We took a shortcut through the park instead of walking around the main road.","zh":"我們穿過公園抄捷徑，而不是沿着大路繞行。"},{"en":"The fox took a shortcut hoping to save time, but the mud slowed him down.","zh":"狐狸抄捷徑希望節省時間，但泥濘反而令牠減慢。"},{"en":"A shortcut is useful only if the shorter route does not create greater problems.","zh":"只有當較短路線不會帶來更大問題時，捷徑才真正有用。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"through mud","meaning":"穿過泥濘","examples":[{"en":"The fox took a shortcut through mud.","zh":"狐狸抄捷徑穿過泥濘。"},{"en":"“Through mud” means moving across or inside wet, soft earth.","zh":"「through mud」表示穿過濕軟的泥土。"},{"en":"The hikers walked through mud after several days of heavy rain.","zh":"經過幾天大雨後，行山人士要穿過泥濘。"},{"en":"Running through mud is difficult because your feet can sink and slip.","zh":"在泥濘中奔跑很困難，因為雙腳可能陷下去或滑倒。"},{"en":"A route through mud may look shorter but can take longer than a dry path.","zh":"穿過泥濘的路線可能看起來較短，實際上卻可能比乾路花更多時間。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"slowly but surely","meaning":"緩慢但穩定地","examples":[{"en":"Slowly but surely, the tortoise’s advice became valuable.","zh":"緩慢但穩定地，陸龜的建議變得越來越有價值。"},{"en":"“Slowly but surely” means progress happens gradually but reliably and is likely to succeed.","zh":"「slowly but surely」表示進展雖然逐步發生，但可靠而且很可能成功。"},{"en":"Slowly but surely, the child became more confident at speaking English.","zh":"那個孩子緩慢但穩定地變得更有信心說英語。"},{"en":"The damaged garden recovered slowly but surely after regular care.","zh":"經過定期照料，受損的花園緩慢但穩定地恢復。"},{"en":"This phrase emphasises dependable improvement even when progress is not fast.","zh":"這個片語強調即使進展不快，改善仍然可靠而持續。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"advice became valuable","meaning":"建議變得有價值","examples":[{"en":"The tortoise’s advice became as valuable as the hare’s speed.","zh":"陸龜的建議變得和野兔的速度一樣有價值。"},{"en":"“Advice became valuable” means guidance that seemed unimportant earlier became useful or important in solving problems.","zh":"「advice became valuable」表示原本看似不重要的指導，在解決問題時變得有用或重要。"},{"en":"Her father’s advice became valuable when she faced the same difficulty at work.","zh":"當她在工作中遇到同樣困難時，父親的建議變得很有價值。"},{"en":"The tortoise’s advice became valuable because it helped the hare avoid dangerous routes.","zh":"陸龜的建議變得有價值，因為它幫助野兔避開危險路線。"},{"en":"Advice often becomes valuable when experience shows why it was given.","zh":"當經驗證明為甚麼當初會有人提出那些話時，建議往往會變得有價值。"}],"source":"2019 Q9.pdf","sourcePage":8},{"front":"as valuable as","meaning":"和……一樣有價值","examples":[{"en":"The tortoise’s advice became as valuable as the hare’s legs.","zh":"陸龜的建議變得和野兔的雙腿一樣有價值。"},{"en":"“As valuable as” means equally useful, important, or worthwhile as something else.","zh":"「as valuable as」表示與另一樣東西同樣有用、重要或值得。"},{"en":"Clear information can be as valuable as money when making an important decision.","zh":"作重大決定時，清楚資訊可以和金錢一樣有價值。"},{"en":"In the race, good judgement became as valuable as physical speed.","zh":"在比賽中，良好判斷力變得和身體速度一樣有價值。"},{"en":"Different abilities can be equally valuable even when they are useful in different situations.","zh":"不同能力即使在不同情況發揮作用，也可以同樣有價值。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"stop dead","meaning":"突然停住","examples":[{"en":"At the river, the hare stopped dead.","zh":"到了河邊，野兔突然停住。"},{"en":"To stop dead means to stop moving suddenly and completely.","zh":"「stop dead」表示突然而完全停止移動。"},{"en":"The cyclist stopped dead when a child ran into the road.","zh":"一個孩子跑到馬路上時，那名單車手突然停住。"},{"en":"The hare stopped dead because the wide river blocked his path.","zh":"野兔突然停住，因為寬闊的河流擋住了去路。"},{"en":"People often stop dead when they suddenly see unexpected danger ahead.","zh":"當人突然看見前方有意料之外的危險，常會立即停住。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"foam over","meaning":"在……上泛起泡沫","examples":[{"en":"The water foamed over smooth black stones.","zh":"河水流過光滑的黑石時泛起泡沫。"},{"en":"To foam over something means for moving water to form white bubbles as it flows across it.","zh":"「foam over」表示流動的水經過某物時形成白色泡沫。"},{"en":"Sea water foamed over the rocks during the storm.","zh":"暴風雨期間，海水流過岩石時泛起泡沫。"},{"en":"The fast river foamed over stones where the current struck them.","zh":"湍急河水撞上石頭時，在石面上泛起泡沫。"},{"en":"Water often foams when it moves quickly over an uneven surface.","zh":"水快速流過不平表面時常會形成泡沫。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"smooth black stones","meaning":"光滑的黑石","examples":[{"en":"The river foamed over smooth black stones.","zh":"河水流過光滑的黑石時泛起泡沫。"},{"en":"Smooth black stones are dark rocks whose surfaces have been worn until they feel even rather than rough.","zh":"光滑的黑石是表面被磨得平滑而不粗糙的深色石頭。"},{"en":"The children collected smooth black stones from the riverbank.","zh":"孩子們在河岸收集光滑的黑石。"},{"en":"Years of flowing water had made the black stones smooth.","zh":"多年流水把那些黑石磨得非常光滑。"},{"en":"Smooth stones can be slippery when they are wet, especially in a fast river.","zh":"光滑的石頭濕了之後可能很滑，尤其在湍急河流中。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"jump streams","meaning":"跳過小溪","examples":[{"en":"The hare could jump streams but not rivers.","zh":"野兔可以跳過小溪，卻不能跳過河流。"},{"en":"To jump streams means to leap over small flowing bodies of water from one side to the other.","zh":"跳過小溪是指從一邊躍到另一邊，越過較小的流水。"},{"en":"The hikers could jump the narrow streams without getting their boots wet.","zh":"行山人士可以跳過狹窄小溪，不讓靴子弄濕。"},{"en":"The hare was strong enough to jump streams, but the river was too wide.","zh":"野兔有能力跳過小溪，但河流實在太寬。"},{"en":"A skill that works for a small obstacle may not be enough for a much larger one.","zh":"能應付小障礙的技能，未必足以處理大得多的障礙。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"glide ahead","meaning":"向前滑行","examples":[{"en":"The otter and kingfisher were already gliding ahead.","zh":"水獺和翠鳥已經向前滑行。"},{"en":"To glide ahead means to move smoothly and easily forward with little visible effort.","zh":"「glide ahead」表示看起來幾乎不費力地平順向前移動。"},{"en":"The boat glided ahead across the calm lake.","zh":"小船在平靜湖面上平穩向前滑行。"},{"en":"The otter and kingfisher glided ahead because water and air were their natural strengths.","zh":"水獺和翠鳥能順利向前滑行，是因為水和空中活動本來就是牠們的長處。"},{"en":"Someone who glides ahead appears to make progress smoothly while others struggle.","zh":"一個人向前滑行時，看起來會在別人掙扎之際輕鬆取得進展。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"climb on","meaning":"爬上來","examples":[{"en":"The tortoise told the hare to climb on.","zh":"陸龜叫野兔爬上來。"},{"en":"To climb on means to move onto the top or back of something by climbing.","zh":"「climb on」表示攀爬到某樣東西的上面或背上。"},{"en":"The child climbed on the horse with help from the instructor.","zh":"那個孩子在教練協助下爬上馬背。"},{"en":"The tortoise told the hare to climb on because carrying him was the safest way across the river.","zh":"陸龜叫野兔爬上來，因為載着他是最安全的過河方法。"},{"en":"Accepting an invitation to climb on may require trust when another person will support your weight.","zh":"當另一個人要承托你的重量時，接受「爬上來」的邀請可能需要信任。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"unless you would rather","meaning":"除非你寧願","examples":[{"en":"The tortoise asked whether the hare would rather argue until sunset.","zh":"陸龜問野兔，除非他寧願爭論到日落。"},{"en":"“Unless you would rather…” introduces another choice, often one that is less sensible or less attractive.","zh":"「unless you would rather…」用來提出另一個選擇，而那個選擇往往較不合理或不吸引。"},{"en":"We can leave now, unless you would rather wait another hour.","zh":"我們現在可以離開，除非你寧願再等一小時。"},{"en":"The tortoise suggested climbing on unless the hare would rather waste time arguing.","zh":"陸龜建議野兔爬上來，除非他寧願浪費時間爭論。"},{"en":"This phrase can make one option seem obviously more practical than the alternative.","zh":"這個片語可以令其中一個選擇顯得明顯比另一個更實際。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"argue until sunset","meaning":"爭論到日落","examples":[{"en":"The tortoise did not want to argue until sunset.","zh":"陸龜不想爭論到日落。"},{"en":"To argue until sunset means to continue disagreeing for many hours instead of solving the problem.","zh":"爭論到日落表示持續爭辯很多小時，而沒有真正解決問題。"},{"en":"The siblings could argue until sunset about whose turn it was if nobody made a decision.","zh":"如果沒有人作決定，兄弟姊妹可能會為輪到誰而爭論到日落。"},{"en":"The tortoise preferred action because arguing until sunset would waste the whole day.","zh":"陸龜寧願行動，因為爭論到日落會浪費整天時間。"},{"en":"Long arguments become unhelpful when they delay an obvious practical solution.","zh":"當長時間爭論只會拖延明顯而實際的解決方法時，它就沒有幫助。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"ridiculous, embarrassing and necessary","meaning":"荒謬、尷尬但必要","examples":[{"en":"Riding on the tortoise’s back was ridiculous, embarrassing and necessary.","zh":"騎在陸龜背上這件事既荒謬、尷尬，但又必要。"},{"en":"“Ridiculous, embarrassing and necessary” describes something that feels silly and uncomfortable but still must be done.","zh":"「ridiculous, embarrassing and necessary」形容某件事看起來可笑又令人不自在，卻仍必須去做。"},{"en":"Wearing the huge safety suit looked ridiculous and embarrassing, but it was necessary.","zh":"穿上那套巨大的安全服看起來荒謬又尷尬，但確實有必要。"},{"en":"The hare hated being carried, yet the situation made it ridiculous, embarrassing and necessary.","zh":"野兔很討厭被載着，但情況令這件事既荒謬、尷尬又必要。"},{"en":"Sometimes the sensible choice is uncomfortable because necessity matters more than pride.","zh":"有時最合理的選擇會令人不自在，因為實際需要比自尊更重要。"}],"source":"2019 Q9.pdf","sourcePage":9},{"front":"climb onto","meaning":"爬到……上","examples":[{"en":"The hare climbed onto the tortoise’s back.","zh":"野兔爬到陸龜背上。"},{"en":"To climb onto something means to move up and place yourself on top of it.","zh":"「climb onto」表示向上攀爬並把自己移到某物上面。"},{"en":"The child climbed onto the chair to reach the high shelf.","zh":"那個孩子爬到椅子上，想拿到高架上的東西。"},{"en":"The hare climbed onto the tortoise because he could not cross the river alone.","zh":"野兔爬到陸龜背上，因為他無法獨自過河。"},{"en":"“Onto” emphasises movement from one position to a higher or supporting surface.","zh":"「onto」強調由一個位置移動到較高或可以承托自己的表面。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"bit by bit","meaning":"一點一點地","examples":[{"en":"Bit by bit, they crossed the river.","zh":"他們一點一點地渡過河流。"},{"en":"“Bit by bit” means gradually, in small stages rather than all at once.","zh":"「bit by bit」表示逐漸地、一小步一小步地，而不是一次過完成。"},{"en":"Bit by bit, the family saved enough money to repair the house.","zh":"那個家庭一點一點地儲錢，最後有足夠金錢修理房子。"},{"en":"They crossed the difficult river bit by bit because rushing would have made them unstable.","zh":"他們一點一點地渡過困難的河流，因為急着前進會令他們失去平衡。"},{"en":"Large tasks often become manageable when completed bit by bit.","zh":"大型任務如果一點一點地完成，往往會變得較容易處理。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"the current","meaning":"水流","examples":[{"en":"The current shoved them sideways.","zh":"水流把他們推向一邊。"},{"en":"The current is the continuous movement of water in a particular direction in a river, sea, or other body of water.","zh":"水流是河流、海洋或其他水域中朝特定方向持續移動的水。"},{"en":"The swimmer struggled because the current was carrying him away from the shore.","zh":"那名泳手十分吃力，因為水流正把他帶離岸邊。"},{"en":"A strong river current can push even a powerful swimmer off course.","zh":"強勁河流可以把即使很有力量的泳手推離原來路線。"},{"en":"When crossing moving water, people must consider both their own movement and the force of the current.","zh":"穿過流動的水時，人既要考慮自己的動作，也要考慮水流的力量。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"shove someone sideways","meaning":"把某人推向一邊","examples":[{"en":"The current shoved them sideways.","zh":"水流把他們推向一邊。"},{"en":"To shove someone sideways means to push them strongly towards one side instead of forward.","zh":"「shove someone sideways」表示用力把某人推向側面，而不是向前。"},{"en":"A sudden crowd movement shoved me sideways against the wall.","zh":"人群突然移動，把我推向一邊撞到牆上。"},{"en":"The current shoved them sideways, so the hare had to help keep their direction.","zh":"水流把他們推向一邊，所以野兔要幫忙保持方向。"},{"en":"A strong sideways force can make it difficult to stay balanced or move straight.","zh":"強勁的側向力量可以令人難以保持平衡或直線前進。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"lean left and right","meaning":"左右傾斜","examples":[{"en":"The hare leaned left and right to balance them.","zh":"野兔左右傾斜身體，令他們保持平衡。"},{"en":"To lean left and right means to move the upper body alternately towards each side.","zh":"「lean left and right」表示上半身交替向左右兩邊傾斜。"},{"en":"The cyclist leaned left and right while moving through the narrow course.","zh":"單車手穿過狹窄賽道時左右傾斜身體。"},{"en":"The hare leaned left and right to respond whenever the current pushed them.","zh":"每當水流推動他們時，野兔便左右傾斜作出調整。"},{"en":"Leaning in different directions can help correct balance on a moving surface.","zh":"在移動的表面上，向不同方向傾斜可以幫助修正平衡。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"balance them","meaning":"令他們保持平衡","examples":[{"en":"The hare balanced them as they crossed the river.","zh":"過河時，野兔令他們保持平衡。"},{"en":"To balance them means to help both people remain steady and prevent them from falling or rolling.","zh":"「balance them」表示幫助兩個人保持穩定，防止跌倒或翻側。"},{"en":"The parent balanced the children on the small boat by asking them to sit on opposite sides.","zh":"那位家長叫孩子坐在小船兩邊，令他們保持平衡。"},{"en":"The hare balanced them by shifting his weight whenever the current pushed.","zh":"每當水流推動時，野兔便改變自己的重量位置，令他們保持平衡。"},{"en":"Balancing a pair requires constant small adjustments when the surface is unstable.","zh":"當表面不穩定，要令兩個人保持平衡需要不斷作細小調整。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"swim on","meaning":"繼續游","examples":[{"en":"The tortoise swam on while the hare balanced them.","zh":"野兔保持他們平衡時，陸龜繼續游。"},{"en":"To swim on means to continue swimming despite difficulty or interruption.","zh":"「swim on」表示即使有困難或干擾，仍然繼續游泳。"},{"en":"Although the water became colder, she swam on towards the shore.","zh":"雖然水變得更冷，她仍繼續游向岸邊。"},{"en":"The tortoise swam on because stopping in the strong current would have been dangerous.","zh":"陸龜繼續游，因為在強勁水流中停下來會很危險。"},{"en":"“On” after a verb often means continuing an action rather than stopping.","zh":"動詞後面的「on」常表示繼續某項動作，而不是停止。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"keep someone from doing something","meaning":"防止某人做某事","examples":[{"en":"The hare kept them from rolling over.","zh":"野兔防止他們翻側。"},{"en":"To keep someone from doing something means to prevent that action from happening.","zh":"「keep someone from doing something」表示防止某個動作發生。"},{"en":"The safety rail kept the child from falling down the stairs.","zh":"安全欄防止那個孩子從樓梯跌下。"},{"en":"The hare’s careful movements kept them from losing balance in the river.","zh":"野兔小心的動作防止他們在河中失去平衡。"},{"en":"Preventing a problem before it happens is often easier than fixing it afterwards.","zh":"在問題發生前加以防止，往往比事後修正更容易。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"roll over","meaning":"翻側","examples":[{"en":"The hare kept them from rolling over in the river.","zh":"野兔防止他們在河中翻側。"},{"en":"To roll over means to turn completely onto another side, sometimes uncontrollably.","zh":"「roll over」表示整個翻到另一邊，有時是不受控制的。"},{"en":"The small boat nearly rolled over when everyone moved to one side.","zh":"所有人都移到同一邊時，小船差點翻側。"},{"en":"The hare shifted his weight to stop them from rolling over in the current.","zh":"野兔轉移自己的重量，以防止他們在水流中翻側。"},{"en":"Rolling over in deep or fast water can be dangerous because balance is difficult to recover.","zh":"在深水或急流中翻側可能很危險，因為很難重新取得平衡。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time they reached the bank, both had helped each other.","zh":"到他們抵達河岸的時候，兩者都已經幫助過對方。"},{"en":"“By the time” means that something has already happened before or when another event is reached.","zh":"「by the time」表示在另一件事發生時或之前，某件事已經發生。"},{"en":"By the time we arrived at the cinema, the film had already begun.","zh":"到我們抵達戲院的時候，電影已經開始了。"},{"en":"By the time they crossed the river, both partners understood that they needed one another.","zh":"到他們渡過河流的時候，兩位拍檔都明白自己需要對方。"},{"en":"This phrase is useful for showing how one situation develops before another point in time.","zh":"這個片語適合表示某種情況在另一個時間點前如何逐步發展。"}],"source":"2019 Q9.pdf","sourcePage":10},{"front":"opposite bank","meaning":"對岸","examples":[{"en":"They finally reached the opposite bank.","zh":"他們終於到達對岸。"},{"en":"The opposite bank is the land on the other side of a river from where you started.","zh":"對岸是河流另一邊、與出發位置相對的陸地。"},{"en":"We could see houses on the opposite bank across the water.","zh":"我們可以看見河水另一邊對岸的房屋。"},{"en":"The swimmers rested after finally reaching the opposite bank.","zh":"泳手終於到達對岸後停下來休息。"},{"en":"Reaching the opposite bank means the river crossing has been successfully completed.","zh":"到達對岸表示渡河已成功完成。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"neither could say","meaning":"兩者都說不出","examples":[{"en":"Neither could say who had saved whom.","zh":"兩者都說不出誰救了誰。"},{"en":"“Neither could say” means neither of two people was able to give a clear answer.","zh":"「neither could say」表示兩個人都無法給出清楚答案。"},{"en":"After the confusing accident, neither could say exactly how it had started.","zh":"那場混亂意外之後，兩者都說不出事情究竟如何開始。"},{"en":"Both partners had contributed so much that neither could say who had helped more.","zh":"兩位拍檔都付出很多，所以兩者都說不出誰幫得更多。"},{"en":"This phrase can show that two people’s actions were so closely connected that responsibility cannot be separated easily.","zh":"這個片語可以表示兩個人的行動緊密相連，很難把責任清楚分開。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"who had saved whom","meaning":"誰救了誰","examples":[{"en":"Neither could say who had saved whom.","zh":"兩者都說不出誰救了誰。"},{"en":"“Who had saved whom” asks which person helped or rescued the other person.","zh":"「who had saved whom」是在問哪一個人幫助或拯救了另一個人。"},{"en":"After they both pulled each other from danger, nobody knew who had saved whom.","zh":"兩人都把對方從危險中拉出來後，沒有人知道究竟誰救了誰。"},{"en":"The river crossing made it impossible to decide who had saved whom because each had prevented the other from failing.","zh":"過河時每一個都防止對方失敗，因此很難判斷誰救了誰。"},{"en":"Mutual help can become so balanced that asking who saved whom no longer has a simple answer.","zh":"當互相幫助十分平衡時，「誰救了誰」往往不再有簡單答案。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"final obstacle","meaning":"最後一個障礙","examples":[{"en":"The final obstacle was the thorn maze.","zh":"最後一個障礙是荊棘迷宮。"},{"en":"A final obstacle is the last difficulty or barrier that must be overcome before reaching the goal.","zh":"最後一個障礙是到達目標前必須克服的最後困難或阻礙。"},{"en":"The steep staircase was the final obstacle before the hikers reached the viewpoint.","zh":"那條陡峭樓梯是行山人士抵達觀景台前的最後一個障礙。"},{"en":"The thorn maze was the final obstacle separating the racers from the finishing line.","zh":"荊棘迷宮是賽跑者與終點線之間的最後一個障礙。"},{"en":"Reaching the final obstacle can be encouraging because the end is near, but concentration is still necessary.","zh":"到達最後一個障礙令人鼓舞，因為終點已近，但仍需要保持專注。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"enter first","meaning":"率先進入","examples":[{"en":"The fox and weasel had entered first.","zh":"狐狸和黃鼠狼率先進入。"},{"en":"To enter first means to go into a place or stage before everyone else.","zh":"「enter first」表示比所有其他人更早進入某個地方或階段。"},{"en":"The winning group entered the hall first and chose their seats.","zh":"勝出的組別率先進入禮堂並選擇座位。"},{"en":"The fox and weasel entered the maze first, giving them an early advantage.","zh":"狐狸和黃鼠狼率先進入迷宮，因此一開始佔有優勢。"},{"en":"Entering first is useful only if you continue making good decisions afterwards.","zh":"只有之後繼續作出良好決定，率先進入才真正有用。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"only to","meaning":"結果卻","examples":[{"en":"They entered first, only to blame each other at every turn.","zh":"他們率先進入，結果卻在每個轉角互相責怪。"},{"en":"“Only to” introduces an unexpected or disappointing result that happens after an earlier action.","zh":"「only to」用來帶出之前行動之後發生的意外或令人失望的結果。"},{"en":"She rushed to the station, only to discover that the train had been cancelled.","zh":"她匆忙趕到車站，結果卻發現列車已取消。"},{"en":"They gained an early lead, only to waste it by arguing.","zh":"他們一開始取得領先，結果卻因爭吵而浪費了優勢。"},{"en":"This structure often shows that an effort led to a result very different from what was hoped for.","zh":"這個句式常表示一番努力帶來的結果與原本希望的非常不同。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"blame each other","meaning":"互相責怪","examples":[{"en":"The fox and weasel began to blame each other.","zh":"狐狸和黃鼠狼開始互相責怪。"},{"en":"To blame each other means for two people to accuse one another of causing a problem or mistake.","zh":"互相責怪表示兩個人都指責對方造成問題或犯錯。"},{"en":"The brothers blamed each other for breaking the window.","zh":"兩兄弟互相責怪，說是對方打破窗戶。"},{"en":"The fox and weasel lost time because they blamed each other instead of solving the problem.","zh":"狐狸和黃鼠狼因為互相責怪而不是解決問題，浪費了時間。"},{"en":"Teams usually make less progress when members blame each other rather than share responsibility.","zh":"當團隊成員互相責怪而不共同承擔責任，通常會取得較少進展。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"at every turn","meaning":"每到一個轉角；每一步","examples":[{"en":"They blamed each other at every turn.","zh":"他們每到一個轉角都互相責怪。"},{"en":"“At every turn” can mean at every change of direction or repeatedly at every stage of a situation.","zh":"「at every turn」可以表示每到一個轉向位置，也可以表示事情每個階段都反覆出現。"},{"en":"The maze confused us at every turn because each path looked the same.","zh":"那個迷宮每到一個轉角都令我們困惑，因為每條路看起來都一樣。"},{"en":"The partners argued at every turn instead of trusting each other’s judgement.","zh":"那兩位拍檔每一步都在爭吵，而不是信任對方的判斷。"},{"en":"When difficulties appear at every turn, patience becomes especially important.","zh":"當困難每一步都出現，耐性便尤其重要。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"cleverness, divided","meaning":"分裂的聰明才智","examples":[{"en":"Their cleverness, divided, became little more than noise.","zh":"他們分裂的聰明才智，最後只不過變成噪音。"},{"en":"“Cleverness, divided” means intelligence that is not working together towards the same goal.","zh":"「cleverness, divided」表示智慧沒有共同朝同一目標發揮。"},{"en":"A group may contain brilliant people, but their cleverness is divided if everyone follows a different plan.","zh":"一個小組可以有很多聰明人，但如果每個人都按不同計劃行事，他們的聰明才智便是分裂的。"},{"en":"The fox and weasel were both intelligent, but their cleverness, divided, could not guide them efficiently.","zh":"狐狸和黃鼠狼都很聰明，但分裂的聰明才智無法有效引導他們。"},{"en":"Ability loses much of its value when talented people work against rather than with one another.","zh":"當有才能的人互相對抗而不是合作，能力便會失去很多價值。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"little more than","meaning":"只不過是","examples":[{"en":"Their cleverness became little more than noise.","zh":"他們的聰明才智最後只不過變成噪音。"},{"en":"“Little more than” means almost nothing beyond the thing mentioned.","zh":"「little more than」表示除了所提到的東西外，幾乎沒有其他價值。"},{"en":"Without evidence, the confident speech was little more than an opinion.","zh":"沒有證據，那番自信的說話只不過是一個意見。"},{"en":"Their arguments became little more than noise because nobody was listening or cooperating.","zh":"他們的爭論只不過變成噪音，因為沒有人真正聆聽或合作。"},{"en":"Useful talent can become little more than noise when it does not lead to effective action.","zh":"如果才能不能帶來有效行動，再有用的才智也可能只不過是噪音。"}],"source":"2019 Q9.pdf","sourcePage":11},{"front":"study the ground","meaning":"細看地面","examples":[{"en":"The tortoise studied the ground before choosing the route.","zh":"陸龜選擇路線前細看地面。"},{"en":"To study the ground means to examine the surface carefully for signs, dangers, or clues.","zh":"「study the ground」表示仔細檢查地面，以尋找跡象、危險或線索。"},{"en":"The hikers studied the ground for footprints before deciding which path to follow.","zh":"行山人士決定走哪條路前，細看地面尋找腳印。"},{"en":"The tortoise studied the ground because small details could reveal the safer route.","zh":"陸龜細看地面，因為微小細節可能顯示較安全的路線。"},{"en":"Studying the ground carefully can prevent mistakes that happen when people rush ahead without looking.","zh":"仔細觀察地面，可以避免因為不看清楚便衝前而造成的錯誤。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"bend towards","meaning":"向……彎曲","examples":[{"en":"The roots bend towards the hill.","zh":"樹根向山丘方向彎曲。"},{"en":"To bend towards something means to curve or turn gradually in its direction.","zh":"「bend towards」表示逐漸彎向或轉向某個方向。"},{"en":"The tree branches bend towards the sunlight near the window.","zh":"窗邊的樹枝向陽光方向彎曲。"},{"en":"The roots bend towards the hill, giving the tortoise a natural clue about the route.","zh":"樹根向山丘彎曲，為陸龜提供了天然的路線線索。"},{"en":"Natural features can bend towards a direction and help careful observers understand the landscape.","zh":"自然環境中的形狀可以朝某方向彎曲，幫助細心觀察的人理解地形。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"follow them","meaning":"跟着它們走","examples":[{"en":"The tortoise told the hare to follow the roots.","zh":"陸龜叫野兔跟着那些樹根走。"},{"en":"To follow them means to move in the same direction indicated by the people, objects, marks, or paths already mentioned.","zh":"「follow them」表示按照之前提到的人、物件、痕跡或路線所指的方向前進。"},{"en":"We saw footprints leading into the forest and decided to follow them.","zh":"我們看見腳印通往森林，於是決定跟着它們走。"},{"en":"The tortoise noticed the roots and told the hare to follow them towards the hill.","zh":"陸龜留意到那些樹根，叫野兔跟着它們向山丘前進。"},{"en":"Following reliable clues can be more effective than choosing a direction at random.","zh":"跟隨可靠線索，往往比隨便選一個方向更有效。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"dash ahead","meaning":"向前衝","examples":[{"en":"The hare dashed ahead, then stopped himself.","zh":"野兔向前衝，然後使自己停下來。"},{"en":"To dash ahead means to run or move forward suddenly and quickly.","zh":"「dash ahead」表示突然快速地向前跑或移動。"},{"en":"The excited child dashed ahead of the family when he saw the playground.","zh":"那個孩子看見遊樂場後興奮地向前衝，跑到家人前面。"},{"en":"The hare’s first instinct was to dash ahead because he was naturally fast.","zh":"野兔的第一個本能是向前衝，因為他天生跑得快。"},{"en":"Dashing ahead can create a problem in teamwork if your partner cannot keep up.","zh":"團隊合作時，如果拍檔跟不上，向前衝可能造成問題。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"stop himself","meaning":"使自己停下來","examples":[{"en":"The hare dashed ahead but stopped himself.","zh":"野兔向前衝，但使自己停下來。"},{"en":"To stop himself means to deliberately prevent himself from continuing an action he had already started or wanted to do.","zh":"「stop himself」表示刻意阻止自己繼續已開始或本來想做的動作。"},{"en":"He was about to shout angrily but stopped himself before saying something hurtful.","zh":"他本來想憤怒地大叫，但在說出傷人的話前使自己停下來。"},{"en":"The hare stopped himself because he remembered that his partner was still behind him.","zh":"野兔使自己停下來，因為他記起拍檔仍在後面。"},{"en":"Being able to stop yourself shows self-control when your first instinct may be unhelpful.","zh":"當第一反應可能沒有幫助時，能使自己停下來代表有自制力。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"up until yesterday","meaning":"直到昨天為止","examples":[{"en":"Up until yesterday, the hare would have run on alone.","zh":"直到昨天為止，野兔還會獨自繼續跑。"},{"en":"“Up until yesterday” means continuously before and including the day before today, but no longer now.","zh":"「up until yesterday」表示一直到昨天仍然如此，但現在已經不同。"},{"en":"Up until yesterday, I believed the meeting would be on Friday.","zh":"直到昨天為止，我仍相信會議會在星期五舉行。"},{"en":"Up until yesterday, the hare still thought independence was more important than teamwork.","zh":"直到昨天為止，野兔仍認為獨立比團隊合作重要。"},{"en":"This phrase often signals that a recent change has just happened.","zh":"這個片語常表示最近才剛剛出現某種改變。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"run on alone","meaning":"獨自繼續跑","examples":[{"en":"The hare would once have run on alone.","zh":"野兔以前本來會獨自繼續跑。"},{"en":"To run on alone means to continue running forward without waiting for or helping anyone else.","zh":"「run on alone」表示不等待或幫助任何人，自己繼續向前跑。"},{"en":"The strongest runner could have run on alone, but she stayed with the injured teammate.","zh":"最強的跑手本來可以獨自繼續跑，但她留在受傷的隊友身邊。"},{"en":"In the past, the hare would run on alone whenever he believed speed could solve everything.","zh":"過去野兔只要相信速度能解決一切，就會獨自繼續跑。"},{"en":"Running on alone may be faster personally, but it can fail in a race that requires partnership.","zh":"獨自繼續跑對個人可能較快，但在需要合作的比賽中可能無法取勝。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"look back","meaning":"回頭看","examples":[{"en":"This time, the hare looked back.","zh":"這一次，野兔回頭看。"},{"en":"To look back means to turn your head or body to see what is behind you.","zh":"「look back」表示轉動頭部或身體，看身後的情況。"},{"en":"She looked back to check whether her younger brother was still following.","zh":"她回頭看，確認弟弟是否仍跟在後面。"},{"en":"The hare looked back because he had begun thinking about his partner rather than only himself.","zh":"野兔回頭看，因為他開始想到拍檔，而不只是自己。"},{"en":"Looking back can be an important act of care when someone else is depending on you.","zh":"當別人依靠你時，回頭看可以是一個重要的關心行動。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"be stuck beneath","meaning":"被困在……下面","examples":[{"en":"The tortoise was stuck beneath a tangle of thorns.","zh":"陸龜被困在一團荊棘下面。"},{"en":"To be stuck beneath something means to be trapped underneath it and unable to move freely.","zh":"「be stuck beneath」表示被困在某物下面，無法自由移動。"},{"en":"The cat was stuck beneath the fallen fence until someone lifted it.","zh":"那隻貓被困在倒下的圍欄下面，直到有人把圍欄抬起。"},{"en":"The tortoise was stuck beneath the thorns because his shell had become caught.","zh":"陸龜被困在荊棘下面，因為龜殼被勾住了。"},{"en":"Someone who is stuck beneath a heavy or tangled object usually needs help to get free.","zh":"被困在沉重或糾纏物件下面的人，通常需要幫助才能脫困。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"a tangle of thorns","meaning":"一團荊棘","examples":[{"en":"The tortoise was trapped beneath a tangle of thorns.","zh":"陸龜被困在一團荊棘下面。"},{"en":"A tangle of thorns is a confused mass of thorny branches twisted together.","zh":"一團荊棘是多條帶刺樹枝互相纏繞形成的混亂一團。"},{"en":"The path was blocked by a tangle of thorns growing across the entrance.","zh":"小路入口被一團長滿尖刺的荊棘堵住。"},{"en":"The tortoise could not simply push through the tangle of thorns because his shell was caught.","zh":"陸龜無法直接穿過那團荊棘，因為他的龜殼被卡住。"},{"en":"A tangled group of thorny branches can trap clothing, fur, or other objects easily.","zh":"一團互相纏繞的帶刺樹枝很容易勾住衣服、毛髮或其他物件。"}],"source":"2019 Q9.pdf","sourcePage":12},{"front":"shell wedged tight","meaning":"龜殼被緊緊卡住","examples":[{"en":"The tortoise’s shell was wedged tight under the thorns.","zh":"陸龜的龜殼被緊緊卡在荊棘下面。"},{"en":"“Wedged tight” means stuck firmly in a narrow space so that movement is very difficult.","zh":"「wedged tight」表示牢牢卡在狹窄空間，幾乎無法移動。"},{"en":"The box was wedged tight between the wall and the cupboard.","zh":"箱子被緊緊卡在牆與櫃之間。"},{"en":"The tortoise could not move because his shell was wedged tight beneath the branches.","zh":"陸龜無法移動，因為龜殼被緊緊卡在樹枝下面。"},{"en":"Something wedged tight usually has to be pulled, lifted, or loosened before it can move again.","zh":"被緊緊卡住的東西通常需要先拉出、抬起或弄鬆，才能重新移動。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"for a heartbeat","meaning":"一瞬間","examples":[{"en":"For a heartbeat, the finishing line flashed before the hare’s eyes.","zh":"一瞬間，終點線在野兔眼前閃過。"},{"en":"“For a heartbeat” means for an extremely short moment, about as brief as one beat of the heart.","zh":"「for a heartbeat」表示極短的一刻，短得像心跳一下的時間。"},{"en":"For a heartbeat, she thought she had lost her passport.","zh":"一瞬間，她以為自己遺失了護照。"},{"en":"The hare imagined winning for a heartbeat before remembering his trapped partner.","zh":"野兔一瞬間想像自己取勝，然後便記起被困的拍檔。"},{"en":"This expression emphasises how quickly a thought or temptation appears and disappears.","zh":"這個表達強調一個念頭或誘惑出現和消失得非常快。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"finishing line","meaning":"終點線","examples":[{"en":"The finishing line flashed before the hare’s eyes.","zh":"終點線在野兔眼前閃過。"},{"en":"The finishing line is the marked line at the end of a race that competitors must cross to finish.","zh":"終點線是比賽末端的標記線，參賽者越過它便完成比賽。"},{"en":"The runners could finally see the finishing line at the end of the road.","zh":"跑手終於在道路盡頭看見終點線。"},{"en":"Reaching the finishing line first did not matter unless both partners arrived together.","zh":"除非兩位拍檔一起到達，否則率先到達終點線也沒有意義。"},{"en":"Seeing the finishing line can make competitors push harder because the race is nearly over.","zh":"看見終點線會令參賽者更加努力，因為比賽快要結束。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"flash before someone’s eyes","meaning":"在某人眼前閃過","examples":[{"en":"The finishing line flashed before the hare’s eyes.","zh":"終點線在野兔眼前閃過。"},{"en":"To flash before someone’s eyes means to appear suddenly and briefly in their sight or imagination.","zh":"「flash before someone’s eyes」表示某個畫面突然短暫出現在某人的視線或想像中。"},{"en":"For a moment, the possibility of winning flashed before her eyes.","zh":"一瞬間，勝出的可能性在她眼前閃過。"},{"en":"The finishing line flashed before the hare’s eyes as he considered running on without his partner.","zh":"當野兔考慮拋下拍檔繼續跑時，終點線在他眼前閃過。"},{"en":"A tempting image may flash before someone’s eyes just before they make an important decision.","zh":"在作重大決定前，一個很有誘惑力的畫面可能會在某人眼前閃過。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"so close, so tempting","meaning":"如此接近，如此誘人","examples":[{"en":"The finishing line was so close, so tempting.","zh":"終點線如此接近，如此誘人。"},{"en":"“So close, so tempting” means something desirable is nearby and therefore especially difficult to resist.","zh":"「so close, so tempting」表示想要的東西就在附近，因此特別難抗拒。"},{"en":"The last piece of cake was so close, so tempting that he nearly forgot his diet.","zh":"最後一件蛋糕如此接近、如此誘人，他差點忘了自己正在節食。"},{"en":"The finishing line was so close, so tempting that the hare briefly thought of leaving his partner behind.","zh":"終點線如此接近、如此誘人，野兔一度想到拋下拍檔。"},{"en":"Temptation is strongest when a desired reward seems almost within reach.","zh":"當渴望的獎勵看起來幾乎伸手可及時，誘惑往往最強。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"turn around","meaning":"轉身回去","examples":[{"en":"The hare turned around to help the tortoise.","zh":"野兔轉身回去幫助陸龜。"},{"en":"To turn around means to change direction so that you face the opposite way.","zh":"「turn around」表示改變方向，面向相反的一邊。"},{"en":"She turned around when she realised her friend had fallen behind.","zh":"她發現朋友落在後面時，便轉身回去。"},{"en":"The hare turned around instead of continuing towards the finishing line.","zh":"野兔沒有繼續衝向終點，而是轉身回去。"},{"en":"Turning around can symbolise a decision to return and help rather than continue alone.","zh":"轉身回去可以象徵選擇回去幫助別人，而不是獨自繼續前進。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"dig, pull and scratch","meaning":"挖、拉、抓","examples":[{"en":"The hare dug, pulled and scratched until the tortoise was free.","zh":"野兔不斷挖、拉、抓，直到陸龜脫困。"},{"en":"“Dig, pull and scratch” describes using several physical actions to remove or loosen something that is trapping another person.","zh":"「dig, pull and scratch」形容使用幾種身體動作，把困住別人的東西移除或弄鬆。"},{"en":"The children dug, pulled and scratched at the sand until the buried box appeared.","zh":"孩子們不斷挖、拉和抓沙，直到埋着的箱子出現。"},{"en":"The hare dug at the earth, pulled branches, and scratched away thorns to free his partner.","zh":"野兔挖開泥土、拉開樹枝並抓走荊棘，救出拍檔。"},{"en":"Using several methods can be necessary when one action alone cannot solve the problem.","zh":"當單一方法不能解決問題時，可能需要使用幾種不同方法。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"until someone was free","meaning":"直到某人脫困","examples":[{"en":"The hare worked until the tortoise was free.","zh":"野兔一直努力，直到陸龜脫困。"},{"en":"“Until someone was free” means continuing an action up to the point when a trapped person could move again.","zh":"「until someone was free」表示一直繼續某項行動，直到被困的人可以重新移動。"},{"en":"The rescuers kept digging until the worker was free.","zh":"救援人員不停挖掘，直到那名工人脫困。"},{"en":"The hare did not stop when he became tired; he continued until the tortoise was free.","zh":"野兔即使疲倦也沒有停下來，而是繼續到陸龜脫困為止。"},{"en":"Helping until someone is free shows commitment because the task is not abandoned halfway.","zh":"一直幫助到某人脫困，表示有承擔，因為沒有半途放棄。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"burst from the maze","meaning":"從迷宮中衝出","examples":[{"en":"The other teams burst from the maze.","zh":"其他隊伍從迷宮中衝出。"},{"en":"To burst from the maze means to come out of it suddenly, quickly, and with great energy.","zh":"「burst from the maze」表示突然、快速而充滿力量地從迷宮出來。"},{"en":"The children burst from the classroom as soon as the final bell rang.","zh":"最後鐘聲一響，孩子們便從課室衝出。"},{"en":"The teams burst from the maze because the finishing line was immediately ahead.","zh":"各隊從迷宮中衝出，因為終點線就在前方。"},{"en":"“Burst” suggests fast, forceful movement after being contained or delayed.","zh":"「burst」帶有被困或受阻一段時間後迅速有力衝出的感覺。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"a few leaps away","meaning":"只差幾步之遙","examples":[{"en":"The line was only a few leaps away.","zh":"終點線只差幾步之遙。"},{"en":"“A few leaps away” means very close, only several jumps or short movements from the destination.","zh":"「a few leaps away」表示非常接近目的地，只需跳幾下或移動一小段距離。"},{"en":"The rabbit’s hiding place was only a few leaps away from the hedge.","zh":"兔子的藏身處距離樹籬只差幾步之遙。"},{"en":"The finishing line was a few leaps away, making it difficult for the hare to wait.","zh":"終點線只差幾步之遙，令野兔很難耐心等待。"},{"en":"Saying something is only a few leaps away emphasises that the goal is extremely near.","zh":"說某處只有幾步之遙，強調目標已非常接近。"}],"source":"2019 Q9.pdf","sourcePage":13},{"front":"pant","meaning":"氣喘吁吁地說","examples":[{"en":"The tortoise panted and told the hare to go.","zh":"陸龜氣喘吁吁地叫野兔先走。"},{"en":"To pant means to breathe quickly and heavily, usually after hard physical effort.","zh":"「pant」表示通常在劇烈運動後快速而沉重地呼吸。"},{"en":"The dog panted after running around the field in hot weather.","zh":"那隻狗在炎熱天氣跑遍草地後不斷喘氣。"},{"en":"The tortoise panted because the difficult race had exhausted him.","zh":"陸龜氣喘吁吁，因為艱難的比賽已令他非常疲倦。"},{"en":"Panting is a sign that the body is working hard and needs more air.","zh":"喘氣表示身體正在大量用力，需要更多空氣。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"not this time","meaning":"這次不會","examples":[{"en":"The hare refused to leave him, saying, “Not this time.”","zh":"野兔拒絕拋下他，說：「這次不會。」"},{"en":"“Not this time” means the speaker will not repeat the same behaviour or mistake on this occasion.","zh":"「not this time」表示這一次不會重複以往的行為或錯誤。"},{"en":"He had ignored his friend before, but not this time; he stayed and helped.","zh":"他以前曾忽略朋友，但這次不會；他留下來幫忙。"},{"en":"The hare once ran ahead alone, but “not this time” showed that he had changed.","zh":"野兔以前曾獨自跑走，但「這次不會」表示他已經改變。"},{"en":"This phrase can mark an important decision to behave differently from the past.","zh":"這個片語可以標誌一個重要決定：這一次要採取與過去不同的做法。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"lower his back","meaning":"壓低背部","examples":[{"en":"The hare lowered his back so the tortoise could climb on.","zh":"野兔壓低背部，讓陸龜可以爬上去。"},{"en":"To lower his back means to bend or move his body downward so another person can get onto it more easily.","zh":"「lower his back」表示把身體彎低或向下移動，讓另一個人較容易爬上去。"},{"en":"The horse lowered its back slightly as the rider climbed on.","zh":"騎手爬上去時，那匹馬稍微壓低背部。"},{"en":"The hare lowered his back because the tired tortoise needed help moving quickly.","zh":"野兔壓低背部，因為疲倦的陸龜需要幫助才能快速前進。"},{"en":"Lowering your body for someone else can be a practical way of helping them climb or ride.","zh":"為別人壓低身體，可以是一種實際的方法，幫助對方爬上或乘坐。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"not wildly, not proudly, but carefully","meaning":"不是魯莽地，也不是驕傲地，而是小心地","examples":[{"en":"The hare ran not wildly, not proudly, but carefully.","zh":"野兔跑得不是魯莽，也不是驕傲，而是小心。"},{"en":"This pattern rejects two ways of acting and emphasises a third, more appropriate one.","zh":"這個句式否定兩種做法，並強調第三種更適合的做法。"},{"en":"She answered not angrily, not defensively, but calmly.","zh":"她回答時不是憤怒，也不是防衛，而是冷靜。"},{"en":"The hare no longer ran wildly or proudly because protecting his partner now mattered more than showing off.","zh":"野兔不再魯莽或驕傲地奔跑，因為保護拍檔已比炫耀自己更重要。"},{"en":"“Not A, not B, but C” strongly contrasts bad choices with the behaviour that is really needed.","zh":"「not A, not B, but C」強烈對比不適當的選擇與真正需要的行為。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"feel every breath","meaning":"感受到每一下呼吸","examples":[{"en":"The hare ran while feeling every breath of his partner behind him.","zh":"野兔奔跑時，感受到身後拍檔的每一下呼吸。"},{"en":"To feel every breath means to be extremely aware of another person’s breathing, often because they are very close.","zh":"「feel every breath」表示非常清楚感受到另一個人的呼吸，通常因為對方離自己很近。"},{"en":"Carrying the tired child, he could feel every breath against his shoulder.","zh":"他抱着疲倦的孩子時，可以感受到孩子靠在肩上的每一下呼吸。"},{"en":"The hare felt every breath of the tortoise and adjusted his speed carefully.","zh":"野兔感受到陸龜每一下呼吸，因此小心調整速度。"},{"en":"Being aware of a partner’s breathing can remind you that another person depends on your movements.","zh":"感受到拍檔的呼吸，可以提醒你另一個人正依靠你的動作。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"partner","meaning":"拍檔","examples":[{"en":"The hare carried his partner across the finishing line.","zh":"野兔把拍檔背過終點線。"},{"en":"A partner is someone who works, competes, or does an activity together with another person.","zh":"拍檔是與另一個人一起工作、比賽或進行某項活動的人。"},{"en":"Each student chose a partner for the speaking exercise.","zh":"每位學生都為口語練習選了一位拍檔。"},{"en":"A good race partner helps when the other person’s strength is not enough.","zh":"當另一個人的能力不足時，好拍檔會提供幫助。"},{"en":"Partnership means sharing effort, responsibility, success and failure.","zh":"成為拍檔意味着共同分享努力、責任、成功和失敗。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"just one whisker ahead of","meaning":"只以極微距離領先","examples":[{"en":"They finished just one whisker ahead of the otter and kingfisher.","zh":"他們只以極微距離領先水獺和翠鳥完成比賽。"},{"en":"“Just one whisker ahead of” means only an extremely small distance in front of someone else.","zh":"「just one whisker ahead of」表示只比另一個人領先極小的距離。"},{"en":"The runner won by such a tiny margin that she was only a whisker ahead of her rival.","zh":"那名跑手以極微差距勝出，只比對手領先一點點。"},{"en":"The hare and tortoise finished just one whisker ahead of the second-place team.","zh":"野兔和陸龜只以極微距離領先第二名隊伍完成比賽。"},{"en":"This expression exaggerates how narrow the winning difference was.","zh":"這個表達誇張地強調勝負差距非常微小。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"the clearing erupted","meaning":"林中空地爆發歡呼","examples":[{"en":"The clearing erupted when the pair won the race.","zh":"那對拍檔贏得比賽時，林中空地爆發歡呼。"},{"en":"“The clearing erupted” means the people or animals there suddenly became extremely noisy and excited.","zh":"「the clearing erupted」表示那裏的人或動物突然變得非常嘈吵和興奮。"},{"en":"The stadium erupted when the home team scored in the final minute.","zh":"主隊在最後一分鐘入球時，整個球場爆發歡呼。"},{"en":"The clearing erupted in cheers as the hare and tortoise crossed the line.","zh":"野兔和陸龜衝線時，林中空地爆發出歡呼聲。"},{"en":"A crowd can “erupt” when strong excitement suddenly turns into shouting, cheering, or applause.","zh":"當強烈興奮突然變成叫喊、歡呼或掌聲時，可以說人群「erupt」。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"I suppose","meaning":"我想；我猜","examples":[{"en":"The hare said, “I suppose the message is still the old one.”","zh":"野兔說：「我想，教訓仍然是舊的那一個吧。」"},{"en":"“I suppose” introduces an opinion or conclusion that the speaker thinks is probably true, sometimes with slight uncertainty.","zh":"「I suppose」用來帶出說話者認為大概正確的意見或結論，有時帶少許不確定。"},{"en":"I suppose we should leave now if we want to catch the last train.","zh":"我想，如果我們想趕上尾班車，現在應該出發了。"},{"en":"The hare said “I suppose” because he was trying to understand the lesson after the race.","zh":"野兔說「I suppose」，因為他正在嘗試理解比賽後的教訓。"},{"en":"This phrase often sounds softer and less definite than saying “I know” or “I am certain”.","zh":"這個片語通常比「I know」或「I am certain」語氣更柔和，也較不肯定。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"not exactly","meaning":"不完全是","examples":[{"en":"The tortoise smiled and said, “Not exactly.”","zh":"陸龜笑着說：「不完全是。」"},{"en":"“Not exactly” means something is not completely correct, although it may be partly true.","zh":"「not exactly」表示某個說法不完全正確，雖然可能有部分是真的。"},{"en":"“So you hated the film?” “Not exactly; I liked the acting but not the story.”","zh":"「所以你很討厭那套電影？」 「不完全是；我喜歡演技，但不喜歡故事。」"},{"en":"The tortoise said “not exactly” because the new lesson was similar to the old one but had an important difference.","zh":"陸龜說「not exactly」，因為新的教訓與舊的相似，但有一個重要分別。"},{"en":"This phrase is useful for correcting an idea gently rather than saying it is totally wrong.","zh":"這個片語適合溫和地修正一個想法，而不是直接說它完全錯誤。"}],"source":"2019 Q9.pdf","sourcePage":14},{"front":"carve new words","meaning":"刻上新字","examples":[{"en":"The owl carved new words beneath the old oak.","zh":"貓頭鷹在老橡樹下刻上新字。"},{"en":"To carve new words means to cut letters into a hard surface so that the message remains there.","zh":"「carve new words」表示把文字刻進堅硬表面，讓訊息長久保留下來。"},{"en":"The artist carved new words into the wooden sign with a small tool.","zh":"藝術家用小工具在木牌上刻上新字。"},{"en":"The owl carved new words because the animals had learned a new lesson from the race.","zh":"貓頭鷹刻上新字，因為動物們從比賽中學到了一個新的教訓。"},{"en":"Words carved into wood or stone can become a lasting reminder for people who visit later.","zh":"刻在木頭或石上的文字，可以成為日後訪客長久的提醒。"}],"source":"2019 Q9.pdf","sourcePage":15},{"front":"beneath the old oak","meaning":"在老橡樹下","examples":[{"en":"The owl carved new words beneath the old oak.","zh":"貓頭鷹在老橡樹下刻上新字。"},{"en":"“Beneath the old oak” means in the space underneath the branches of the old oak tree.","zh":"「beneath the old oak」表示在那棵老橡樹枝葉下面的空間。"},{"en":"The animals often gathered beneath the old oak to discuss important news.","zh":"動物們常在老橡樹下聚集，討論重要消息。"},{"en":"The message beneath the old oak could be seen by everyone entering the clearing.","zh":"在老橡樹下的訊息，所有進入林中空地的人都能看見。"},{"en":"A familiar place can gain symbolic importance when important events repeatedly happen there.","zh":"當重要事件反覆在某個熟悉地方發生，那個地方可以具有象徵意義。"}],"source":"2019 Q9.pdf","sourcePage":15},{"front":"speed may win a moment","meaning":"速度也許能贏得一刻","examples":[{"en":"Speed may win a moment, but trust wins the greater race.","zh":"速度也許能贏得一刻，但信任能贏得更大的比賽。"},{"en":"“Speed may win a moment” means being fast can give a short-term advantage without guaranteeing final success.","zh":"「speed may win a moment」表示快速可以帶來短期優勢，但不能保證最終成功。"},{"en":"Answering first may win a moment, but a careful answer may earn the higher score.","zh":"搶先回答也許能贏得一刻，但仔細作答可能得到更高分。"},{"en":"The hare’s speed helped at certain parts of the course, so speed did win some moments.","zh":"野兔的速度在賽道某些部分有幫助，所以速度確實贏得了某些時刻。"},{"en":"A temporary advantage matters less if it cannot carry someone through the whole challenge.","zh":"如果短暫優勢無法幫助人完成整個挑戰，它的重要性便較低。"}],"source":"2019 Q9.pdf","sourcePage":15},{"front":"patience may win a mile","meaning":"耐性也許能贏得一里路","examples":[{"en":"Patience may win a mile, but trust helps partners finish together.","zh":"耐性也許能贏得一里路，但信任能幫助拍檔一起完成。"},{"en":"“Patience may win a mile” means patience can carry someone successfully through part of a long challenge.","zh":"「patience may win a mile」表示耐性可以令人成功完成長期挑戰中的一部分。"},{"en":"Patient saving may win a mile towards buying a home, but long-term planning is also needed.","zh":"耐心儲蓄也許能讓人向買樓目標前進一大步，但仍需要長期規劃。"},{"en":"The tortoise’s patience helped them through difficult sections, but partnership was needed for the whole race.","zh":"陸龜的耐性幫助他們通過困難部分，但完成整場比賽仍需要合作。"},{"en":"One good quality can take you far, yet complex goals often require more than one strength.","zh":"一項好特質可以令人走得很遠，但複雜目標通常需要不只一種長處。"}],"source":"2019 Q9.pdf","sourcePage":15},{"front":"trust wins the race","meaning":"信任贏得比賽","examples":[{"en":"Trust wins the race that no one can finish alone.","zh":"信任能贏得沒有人可以獨自完成的比賽。"},{"en":"“Trust wins the race” means mutual confidence and cooperation can be the most important reason for success.","zh":"「trust wins the race」表示互相信任和合作可以成為成功最重要的原因。"},{"en":"In a rescue team, trust wins the race because every person depends on others doing their job properly.","zh":"在救援隊中，信任能贏得比賽，因為每個人都依賴其他人做好自己的工作。"},{"en":"The hare and tortoise succeeded because each finally trusted the other’s strengths.","zh":"野兔和陸龜之所以成功，是因為最後都信任對方的長處。"},{"en":"When a challenge requires partnership, trust can matter more than individual speed or talent.","zh":"當挑戰需要合作時，信任可能比個人速度或才能更重要。"}],"source":"2019 Q9.pdf","sourcePage":15},{"front":"no one can finish alone","meaning":"沒有人能獨自完成","examples":[{"en":"Some races are so difficult that no one can finish alone.","zh":"有些比賽困難得沒有人能獨自完成。"},{"en":"“No one can finish alone” means every person needs help or cooperation in order to complete the challenge.","zh":"「no one can finish alone」表示每個人都需要幫助或合作，才能完成挑戰。"},{"en":"Building a large community project is difficult because no one can finish it alone.","zh":"建設大型社區項目十分困難，因為沒有人能獨自完成。"},{"en":"The race proved that no one could finish alone when every obstacle demanded a different strength.","zh":"當每個障礙都需要不同能力時，這場比賽證明沒有人能獨自完成。"},{"en":"Recognising that no one can finish alone encourages people to value teamwork rather than individual pride.","zh":"明白沒有人能獨自完成，可以鼓勵人重視團隊合作，而不是個人自尊。"}],"source":"2019 Q9.pdf","sourcePage":15}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2019_SEED);
